--
-- Name: boardstatus_delete(integer, text); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.boardstatus_delete(boardstatusid integer, updatedby text) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
deleteposition integer default  0 ;
boardid integer default  0 ;
offected integer;
BEGIN
--delete

IF NOT EXISTS (SELECT 1 FROM  board.boardstatus WHERE "LabelID"=boardstatusid) THEN
    return query select 'delete failed due to selected label not available' as message,'false'::boolean as status;
    return;
END IF;

--get position of deleted row :=changeposition
deleteposition := (SELECT "Position" FROM  board.boardstatus WHERE "LabelID"=boardstatusid);

-- validation open position not able to delete
IF(deleteposition =1) THEN 
    return query select 'selected label could not delete due to it is first position.' as message,'false'::boolean as status;
    return;
END IF;
-- get board id 
boardid :=(SELECT "BoardID" FROM  board.boardstatus WHERE "LabelID"=boardstatusid);

-- update position 0
UPDATE board.boardstatus SET "Position"=0, is_active ='false',last_updated_date = current_timestamp,updated_by = updatedby 
WHERE "LabelID"=boardstatusid;

-- call rearrange position
perform  board.rearrange_boardstatus_position(deleteposition,0,boardid,'delete');

get diagnostics offected = ROW_COUNT;
		 
     IF(offected>0)
      THEN
		  return query select 'Board Label Deleted Successfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'Board Label Delete Failed' as message,'false'::boolean as status;
	 END IF;
end;
$$;


--
-- Name: boardstatus_move(integer, integer); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.boardstatus_move(boardstatusid integer, moveposition integer) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
declare
boardid integer default  0 ;
currentpos integer default  0 ;

offected integer;
begin
	-- validation
	IF moveposition = 1 THEN -- open position
		return query select 'could not move to open position ' as message,'false'::boolean as status;
		return ;
	END IF;
	
	-- get board id 
	SELECT "BoardID" INTO boardid FROM  board.boardstatus 
	WHERE "LabelID"=boardstatusid;
	
	-- verify the condition move position is available or not
	IF NOT  EXISTS (SELECT  1 FROM  board.boardstatus WHERE "BoardID"=boardid AND "Position" IN (moveposition)) THEN
			 return query select 'invalid move position' as message,'false'::boolean as status; 
			 return;
	 end if;
	 
	-- get current position
 	SELECT "Position"  INTO currentpos  FROM  board.boardstatus 
	WHERE "LabelID"=boardstatusid;
	
	IF( currentpos > moveposition) THEN
	raise info 'started left move ';
	-- call rearrange position
		perform  board.rearrange_boardstatus_position(moveposition,currentpos,boardid,'leftmove');
		-- update position 
		UPDATE board.boardstatus SET "Position"=moveposition
		WHERE "LabelID"=boardstatusid;
		 
	ELSE
	   raise info 'started right move ';
		perform  board.rearrange_boardstatus_position(moveposition,currentpos,boardid,'rightmove');
		-- update position 
		UPDATE board.boardstatus SET "Position"=moveposition
		WHERE "LabelID"=boardstatusid;
	END IF;
	
	get diagnostics offected = ROW_COUNT;

     IF(offected>0)
      THEN
		  return query select 'moved sucessfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'moved failed' as message,'false'::boolean as status;
	 END IF;
	 
end;
$$;


