--
-- Name: create_board_with_labels(integer, integer, character varying, text, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.create_board_with_labels(IN in_work_space_id integer, IN in_board_id integer, IN in_board_name character varying, IN in_type text, IN in_labels text, IN in_created_by text, INOUT new_board_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_code VARCHAR(50);
    v_label_code VARCHAR(250);
    v_label JSONB;
    v_position INT;
    v_sequence_val INT;
    v_label_id INT;
    v_context TEXT;
    v_labels JSONB := in_labels::JSONB;
    v_is_new BOOLEAN := FALSE;
BEGIN
/*
Authour : Mubarak Basha
Details : To add & update the boards with relalted labels
Sprinit : Kanban Board - 5
*/
    -- Initialize
    new_board_id := COALESCE(new_board_id, 0);
    message := 'Initialization';
    status := 'PENDING';

    -- Generate board code only if creating new
    IF in_board_id = 0 THEN
        v_is_new := TRUE;

        -- Prevent duplicate board name
        IF EXISTS (
            SELECT 1 
            FROM board.board 
            WHERE LOWER("Name") = LOWER(in_board_name)
              AND work_space_id = in_work_space_id
              AND is_active = TRUE
        ) THEN
            message := format('Board name "%s" already exists in this workspace', in_board_name);
            status := 'false';
            RETURN;
        END IF;

        v_code := 'bc-' || LEFT(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT), 5);

        -- Get next BoardID
        SELECT COALESCE(MAX("BoardID"), 0) + 1 INTO new_board_id
        FROM board.board;

        -- Insert new board
        INSERT INTO board.board 
        (
            "BoardID",
            "Name", 
            work_space_id,
            code,
            type,
            is_active,
            created_date,
            created_by
        )
        VALUES 
        (
            new_board_id, 
            in_board_name,
            in_work_space_id, 
            v_code, 
            in_type,
            TRUE,
            CURRENT_TIMESTAMP, 
            in_created_by
        );

    ELSE
        v_is_new := FALSE;
        new_board_id := in_board_id;

        -- Prevent duplicate board name on update
        IF EXISTS (
            SELECT 1 
            FROM board.board 
            WHERE LOWER("Name") = LOWER(in_board_name)
              AND work_space_id = in_work_space_id
              AND "BoardID" <> in_board_id
              AND is_active = TRUE
        ) THEN
            message := 'Board Name Already Exists in this Workspace';
            status := 'false';
            RETURN;
        END IF;

        -- Update existing board
        UPDATE board.board
        SET "Name" = in_board_name,
            last_updated_date = CURRENT_TIMESTAMP,
            updated_by = in_created_by
        WHERE "BoardID" = in_board_id;

        -- Check if board exists
        IF NOT EXISTS (SELECT 1 FROM board.board WHERE "BoardID" = in_board_id) THEN
            message := 'Board does not exist';
            status := 'false';
            RETURN;
        END IF;
    END IF;

    -- Check if board exists
    IF NOT EXISTS (SELECT 1 FROM board.board WHERE "BoardID" = new_board_id) THEN
        message := 'Board insert/update failed';
        status := 'false';
        RETURN;
    END IF;

   -- Handle Labels
FOR v_label IN
    SELECT * FROM jsonb_array_elements(v_labels)
LOOP
    v_label_id := COALESCE((v_label ->> 'labelId')::INT, 0); 
    v_position := COALESCE((v_label ->> 'position')::INT, 0);

	-- Duplicate label name check 
    IF EXISTS (
        SELECT 1 
        FROM board.boardstatus 
        WHERE LOWER("Name") = LOWER(v_label ->> 'name')
          AND "BoardID" = new_board_id
          AND is_active = TRUE
          AND ("LabelID" <> v_label_id OR v_label_id = 0) -- exclude itself during update
    ) THEN
        message := format('Duplicate label name "%s" not allowed in the same board', v_label ->> 'name');
        status := 'false';
        RETURN;
    END IF;

    IF v_is_new THEN
        -- Insert new label (only for new boards)
        v_label_code := 'lbc-' || LEFT(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT), 5);
        SELECT nextval(pg_get_serial_sequence('board.boardstatus', 'LabelID')) INTO v_sequence_val;

        INSERT INTO board.boardstatus 
        (
            "LabelID", 
            "Name", 
            "BoardID",
            "Position",
            "ColorCode",
            "Code",
            is_active, 
            created_date,
            created_by
        )
        VALUES 
        (
            v_sequence_val,
            v_label ->> 'name',
            new_board_id,
            v_position,
            v_label ->> 'color_code',
            v_label_code,
            TRUE,
            CURRENT_TIMESTAMP,
            in_created_by
        );

    ELSIF v_label_id > 0 THEN
        -- Update existing label
        UPDATE board.boardstatus
        SET "Name" = v_label ->> 'name',
            "Position" = v_position,
            "ColorCode" = v_label ->> 'color_code',
            last_updated_date = CURRENT_TIMESTAMP,
            updated_by = in_created_by
        WHERE "LabelID" = v_label_id
          AND "BoardID" = new_board_id
          AND is_active = TRUE;

    ELSE
        -- Allow adding new labels during update as well (optional)
        v_label_code := 'lbc-' || LEFT(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT), 5);
        SELECT nextval(pg_get_serial_sequence('board.boardstatus', 'LabelID')) INTO v_sequence_val;

        INSERT INTO board.boardstatus 
        (
            "LabelID", 
            "Name", 
            "BoardID",
            "Position",
            "ColorCode",
            "Code",
            is_active, 
            created_date,
            created_by
        )
        VALUES 
        (
            v_sequence_val,
            v_label ->> 'name',
            new_board_id,
            v_position,
            v_label ->> 'color_code',
            v_label_code,
            TRUE,
            CURRENT_TIMESTAMP,
            in_created_by
        );
    END IF;
END LOOP;

    IF v_is_new THEN
        message := 'Board added successfully';
		status := 'true';
    ELSE
        message := 'Board updated successfully';
		status := 'true';
    END IF;

    

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'board.create_board_with_labels',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                in_work_space_id,
                in_board_id,
                in_board_name,
                in_type,
                in_labels,
                in_created_by
            ))::TEXT
        );
        status := 'ERROR';
        message := SQLERRM;
END;
$$;


--
-- Name: create_tool_flow(integer, integer[], integer, text, integer, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.create_tool_flow(IN p_tool_flow_id integer, IN p_tool_id integer[], IN p_flow_id integer, IN p_created_by text, INOUT new_tool_flow_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_tool_id integer;
	v_rowcount INTEGER := 0;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : To Create the Tool Flow
      Sprint  : Rules and Movements - 6
    */

    -- To check duplicate tool_id 
    IF EXISTS (
        SELECT 1
        FROM board.tool_flow
        WHERE tool_id = ANY(p_tool_id)
          AND is_active = TRUE
    ) THEN
        message := format('tool_id(s) %s already exist in this tool flow', array_to_string(p_tool_id, ','));
        status := 'FALSE';
        RETURN;
    END IF;

    -- Generate new tool_flow_id for each tool
    FOREACH v_tool_id IN ARRAY p_tool_id LOOP
        SELECT COALESCE(MAX(tool_flow_id), 0) + 1
        INTO new_tool_flow_id
        FROM board.tool_flow;

        INSERT INTO board.tool_flow (
            tool_flow_id,
            tool_id,
            flow_id,
            is_active,
            created_date,
            created_by
        )
        VALUES (
            new_tool_flow_id,
            v_tool_id,
            p_flow_id,
            true,
            current_timestamp AT TIME ZONE 'UTC',
            p_created_by
        );
    END LOOP;
	 GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
       message := 'Tool Flow Created successfully';
        status := 'true';
    ELSE
       message := 'Tool Flow Failed';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'board.create_tool_flow',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_tool_flow_id,
                p_tool_id,
                p_flow_id,
                p_created_by
            ))::TEXT
        );

        status := 'ERROR';
        message := SQLERRM;
END;
$$;


--
-- Name: create_update_board_with_labels(integer, integer, character varying, text, text, integer[], text, integer, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.create_update_board_with_labels(IN in_work_space_id integer, IN in_board_id integer, IN in_board_name character varying, IN in_type text, IN in_labels text, IN in_delete_labels_id integer[], IN in_created_by text, INOUT new_board_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_code VARCHAR(50);
    v_label_code VARCHAR(250);
    v_label JSONB;
    v_position INT;
    v_sequence_val INT;
    v_label_id INT;
    v_context TEXT;
    v_labels JSONB := in_labels::JSONB;
    v_is_new BOOLEAN := FALSE;
    v_row_count INT; 
    v_board_rows INT := 0;
    v_label_inserted INT := 0;
    v_label_updated INT := 0;
    v_label_deleted INT := 0;
	v_new_main_board_id INT := 0;
	v_statuses jsonb;
	v_main_label jsonb;
BEGIN
 
 
 /*
      Author  : Mubarak Basha
      Details : Create and update the board and labels
      Sprint  : Kanban Board - 5
  */
    -- Input validation
    IF in_work_space_id IS NULL OR in_board_name IS NULL OR in_created_by IS NULL THEN
        message := 'Workspace ID, board name, and created by cannot be null';
        status := 'FALSE';
        RETURN;
    END IF;

    -- Initialize
    new_board_id := COALESCE(new_board_id, 0);
    message := 'Initialization';
    status := 'PENDING';

    -- Generate board code only if creating new
    IF in_board_id = 0 THEN
        v_is_new := TRUE;

        -- Prevent duplicate board name
        IF EXISTS (
            SELECT 1 
            FROM board.board 
            WHERE LOWER("Name") = LOWER(in_board_name)
              AND work_space_id = in_work_space_id
              AND is_active = TRUE
        ) THEN
            message := format('Board name "%s" already exists in this workspace', in_board_name);
            status := 'FALSE';
            RETURN;
        END IF;

         -- Generate board code from board name (uppercase, no spaces)
        v_code := UPPER(REPLACE(in_board_name, ' ', ''));
		
		-- Get next BoardID
        SELECT COALESCE(MAX("BoardID"), 0) + 1 INTO v_new_main_board_id
        FROM board.board;
			
        -- Insert new main board
        INSERT INTO board.board 
        (
            "BoardID",
            "Name", 
            work_space_id,
            code,
            type,
            is_active,
            created_date,
            created_by
        )
        VALUES 
        (
            v_new_main_board_id, 
            in_board_name || '_Main_Board_View',
            in_work_space_id, 
            v_code, 
            'maintask',
            TRUE,
             current_timestamp AT TIME ZONE 'UTC',
            in_created_by
        );

		-- Default statuses for the main board
		FOR v_main_label IN
			SELECT unnest(ARRAY[
				'{"name": "Open", "color_code": "#00ADF0", "position":1, "code":"OPEN"}'::jsonb,
				'{"name": "In-progress", "color_code": "#F29E7A", "position":2, "code":"INPROGRESS"}'::jsonb,
				'{"name": "Completed", "color_code": "#2B8931", "position":3, "code":"COMPLETED"}'::jsonb
			])
		LOOP
		SELECT nextval(pg_get_serial_sequence('board.boardstatus', 'LabelID')) INTO v_sequence_val;
			INSERT INTO board.boardstatus 
			(
				"LabelID", 
				"Name", 
				"BoardID",
				"Position",
				"ColorCode",
				"Code",
				is_active, 
				created_date,
				created_by
			)
			VALUES 
			(
				v_sequence_val,
				v_main_label ->> 'name',
				v_new_main_board_id,
				(v_main_label ->> 'position')::int,
				v_main_label ->> 'color_code',
				v_main_label ->> 'code',
				TRUE,
				 current_timestamp AT TIME ZONE 'UTC',
				in_created_by
			);
		END LOOP;
	
        -- Get next BoardID
        SELECT COALESCE(MAX("BoardID"), 0) + 1 INTO new_board_id
        FROM board.board;

        -- Insert new sub board
        INSERT INTO board.board 
        (
            "BoardID",
            "Name", 
            work_space_id,
            code,
            type,
            is_active,
            created_date,
            created_by,
			main_board_id
        )
        VALUES 
        (
            new_board_id, 
            in_board_name,
            in_work_space_id, 
            v_code, 
            in_type,
            TRUE,
             current_timestamp AT TIME ZONE 'UTC',
            in_created_by,
			v_new_main_board_id
        );
        GET DIAGNOSTICS v_board_rows = ROW_COUNT;

    ELSE
        v_is_new := FALSE;
        new_board_id := in_board_id;

        -- Prevent duplicate board name on update
        IF EXISTS (
            SELECT 1 
            FROM board.board 
            WHERE LOWER("Name") = LOWER(in_board_name)
              AND work_space_id = in_work_space_id
              AND "BoardID" <> in_board_id
              AND is_active = TRUE
        ) THEN
            message := 'Board Name Already Exists in this Workspace';
            status := 'FALSE';
            RETURN;
        END IF;

        -- Update existing board
        UPDATE board.board
        SET "Name" = in_board_name,
            last_updated_date =  current_timestamp AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE "BoardID" = in_board_id;
        GET DIAGNOSTICS v_board_rows = ROW_COUNT;

        -- Check if board exists
        IF v_board_rows = 0 THEN
            message := 'Board does not exist';
            status := 'FALSE';
            RETURN;
        END IF;
    END IF;

    -- Soft Delete Labels
    IF in_delete_labels_id IS NOT NULL AND array_length(in_delete_labels_id, 1) > 0 THEN
        FOR v_label_id IN SELECT unnest(in_delete_labels_id)
        LOOP
            -- Check if tickets exist for this label
            IF EXISTS (
                SELECT 1
                FROM tickets.ticket t
                JOIN tickets.tool_detail td 
                  ON t.ticket_id = td.ticket_id 
                 AND td.is_active = TRUE
                WHERE t.is_active = TRUE
                  AND t.is_process_order = TRUE
                  AND td.label_id = v_label_id
            ) THEN
                message := format('Cannot delete label as tickets are assigned. Move them to another stage first.', v_label_id);
                status := 'FALSE';
                RETURN; 
            END IF;

            -- Perform soft delete
            UPDATE board.boardstatus
            SET is_active = FALSE,
                last_updated_date =  current_timestamp AT TIME ZONE 'UTC',
                updated_by = in_created_by
            WHERE "LabelID" = v_label_id
              AND "BoardID" = new_board_id
              AND is_active = TRUE;

            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            v_label_deleted := v_label_deleted + v_row_count;
        END LOOP;
    END IF;

    -- Handle Labels
    IF v_labels IS NOT NULL AND jsonb_array_length(v_labels) > 0 THEN
        FOR v_label IN
            SELECT * FROM jsonb_array_elements(v_labels)
        LOOP
            v_label_id := COALESCE((v_label ->> 'labelId')::INT, 0); 
            v_position := COALESCE((v_label ->> 'position')::INT, 0);

			-- Duplicate label name check 
		    IF EXISTS (
		        SELECT 1 
		        FROM board.boardstatus 
		        WHERE LOWER("Name") = LOWER(v_label ->> 'name')
		          AND "BoardID" = new_board_id
		          AND is_active = TRUE
		          AND ("LabelID" <> v_label_id OR v_label_id = 0) -- exclude itself during update
		    ) THEN
		        message := format('Duplicate label name "%s" not allowed in the same board', v_label ->> 'name');
		        status := 'false';
		        RETURN;
		    END IF;

            IF v_is_new OR v_label_id = 0 THEN
               
               -- Generate label code from label name (uppercase, no spaces)
                v_label_code := UPPER(REPLACE(v_label ->> 'name', ' ', ''));
				
			   SELECT nextval(pg_get_serial_sequence('board.boardstatus', 'LabelID')) INTO v_sequence_val;

                INSERT INTO board.boardstatus 
                (
                    "LabelID", 
                    "Name", 
                    "BoardID",
                    "Position",
                    "ColorCode",
                    "Code",
                    is_active, 
                    created_date,
                    created_by
                )
                VALUES 
                (
                    v_sequence_val,
                    v_label ->> 'name',
                    new_board_id,
                    v_position,
                    v_label ->> 'color_code',
                    v_label_code,
                    TRUE,
                     current_timestamp AT TIME ZONE 'UTC',
                    in_created_by
                );
                GET DIAGNOSTICS v_label_inserted = ROW_COUNT;

            ELSIF v_label_id > 0 THEN
                -- Skip update if this label is in delete array
                IF in_delete_labels_id IS NULL OR v_label_id <> ALL(in_delete_labels_id) THEN
                    UPDATE board.boardstatus
                    SET "Name" = v_label ->> 'name',
                        "Position" = v_position,
                        "ColorCode" = v_label ->> 'color_code',
                        last_updated_date =  current_timestamp AT TIME ZONE 'UTC',
                        updated_by = in_created_by
                    WHERE "LabelID" = v_label_id
                      AND "BoardID" = new_board_id
                      AND is_active = TRUE;

                    GET DIAGNOSTICS v_label_updated = ROW_COUNT;
                END IF;
            END IF;
        END LOOP;
    END IF;

    -- Final message
    IF v_is_new THEN
        message := 'Board added successfully';
        status := 'TRUE';
    ELSE
        message := 'Board updated successfully';
        status := 'TRUE';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'board.create_update_board_with_labels',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                in_work_space_id,
                in_board_id,
                in_board_name,
                in_type,
                in_labels,
                in_delete_labels_id,
                in_created_by
            ))::TEXT
        );
        status := 'ERROR';
        message := SQLERRM;
END;
$$;


--
-- Name: create_update_flow(integer, character varying, character varying, text, text, integer, integer, integer, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.create_update_flow(IN p_flow_id integer, IN p_flow_name character varying, IN p_description character varying, IN p_flow_details text, IN p_created_by text, IN p_workflow_type integer, IN p_workspace_id integer, INOUT new_flow_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_flow_details jsonb := p_flow_details::jsonb;
    v_name_exists boolean;
    v_exists boolean;
    v_rowcount integer := 0;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : Create or Update Flow
      Sprint  : Rules and Movements - 6

    */

   
    -- Validate workflow type (must exist in master)
	
    IF p_workflow_type IS NULL OR NOT EXISTS (
        SELECT 1
        FROM master.status_code_master
        WHERE status_id = p_workflow_type
          AND type = 'WORKFLOWTYPE'
          AND is_active = true
    ) THEN
        message := 'Invalid workflow type';
        status  := 'false';
        RETURN;
    END IF;

    
    --  Check duplicate flow name
 
    SELECT EXISTS (
        SELECT 1
        FROM board.flow f
        WHERE lower(f.flow_name) = lower(p_flow_name)
          AND f.is_active = true
          AND (p_flow_id IS NULL OR f.flow_id <> p_flow_id)
    )
    INTO v_name_exists;

    IF v_name_exists THEN
        message := format('Flow with name "%s" already exists', p_flow_name);
        status  := 'false';
        RETURN;
    END IF;

    -- Check if flow exists
    SELECT EXISTS (
        SELECT 1
        FROM board.flow
        WHERE flow_id = p_flow_id
    )
    INTO v_exists;

    -- Workflow type rules
    -- Tool (60) → workspace must be NULL
    -- Task (61) → workspace mandatory + unique per workspace
 
    -- IF p_workflow_type = 60 THEN
    --     p_workspace_id := NULL;

   -- ELSIF p_workflow_type = 61 THEN

    IF p_workflow_type = 61 THEN

    IF p_workspace_id IS NULL THEN
        message := 'For Task workflow type, workspace_id is mandatory';
        status  := 'false';
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM board.flow f
        WHERE f.work_flow_type = 61
          AND f.workspace_id = p_workspace_id
          AND f.is_active = true
          AND (p_flow_id IS NULL OR f.flow_id <> p_flow_id)
    ) THEN
        message := 'Flow already added to task for this workspace';
        status  := 'false';
        RETURN;
    END IF;

END IF;
	
	--  Check duplicate Source → Target label combination across flow rules
-- IF EXISTS (
--     SELECT 1
--     FROM (
--         SELECT
--             (elem->'Source'->>'workspace_id')::int AS src_ws,
--             (elem->'Source'->>'board_id')::int      AS src_board,
--             (elem->'Source'->>'label_id')::int       AS src_label,
--             (target->>'label_id')::int               AS tgt_label
--         FROM jsonb_array_elements(v_flow_details) elem
--         CROSS JOIN LATERAL jsonb_array_elements(elem->'Targets') target
--     ) combos
--     GROUP BY src_ws, src_board, src_label, tgt_label
--     HAVING COUNT(*) > 1
-- ) THEN
--     message := 'Duplicate Source-Target label combination found in flow details';
--     status  := 'false';
--     RETURN;
-- END IF;

    
    --  UPDATE FLOW

    IF v_exists THEN

        UPDATE board.flow
        SET flow_name        = p_flow_name,
            description      = p_description,
            flow_details     = v_flow_details,
            work_flow_type   = p_workflow_type,
            workspace_id     = p_workspace_id,
            updated_by       = p_created_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE flow_id = p_flow_id;

        new_flow_id := p_flow_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Flow updated successfully';
            status  := 'true';
        ELSE
            message := 'Flow update failed';
            status  := 'false';
        END IF;

 
    -- INSERT FLOW
 
    ELSE

        IF p_flow_id IS NULL OR p_flow_id = 0 THEN
            SELECT COALESCE(MAX(flow_id), 0) + 1
            INTO new_flow_id
            FROM board.flow;
        ELSE
            new_flow_id := p_flow_id;
        END IF;

        INSERT INTO board.flow (
            flow_id,
            flow_name,
            description,
            flow_details,
            work_flow_type,
            workspace_id,
            is_active,
            created_date,
            created_by
        )
        VALUES (
            new_flow_id,
            p_flow_name,
            p_description,
            v_flow_details,
            p_workflow_type,
            p_workspace_id,
            true,
            current_timestamp AT TIME ZONE 'UTC',
            p_created_by
        );

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Flow created successfully';
            status  := 'true';
        ELSE
            message := 'Flow creation failed';
            status  := 'false';
        END IF;

    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'board.create_update_flow',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_flow_id,
                p_flow_name,
                p_description,
                p_flow_details,
                p_workflow_type,
                p_workspace_id,
                p_created_by
            ))::text
        );

        status  := 'ERROR';
        message := SQLERRM;
END;
$$;


--
-- Name: delete_flow(integer, text, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.delete_flow(IN p_flow_id integer, IN p_created_by text, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_exists integer;
	v_rowcount INTEGER := 0;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : Soft delete flow
      Sprint  : flow & rule - 6
    */

    -- Check flow exists
    SELECT COUNT(1) INTO v_exists
    FROM board.flow
    WHERE flow_id = p_flow_id
      AND is_active = true;

    IF v_exists = 0 THEN
        message := 'Flow not found';
        status := 'false';
        RETURN;
    END IF;

    -- Flow Validation: Check if any tools are assigned to this flow
    IF EXISTS (
        SELECT 1
        FROM board.flow f
        JOIN tickets.tool_detail td 
          ON f.flow_id = td.flow_id 
        WHERE td.is_active = true
          AND f.flow_id = p_flow_id
    ) THEN
        message := 'Cannot delete flow as tools are assigned. Move them to another flow first.';
        status := 'false';
        RETURN;
    END IF;

	-- Flow Validation: Check if any tools are assigned in tool_flow
			IF EXISTS (
			    SELECT 1
			    FROM board.flow f
			    JOIN board.tool_flow tf 
			      ON f.flow_id = tf.flow_id 
			    WHERE tf.is_active = true
			      AND f.flow_id = p_flow_id
			) THEN
			    message := 'Cannot delete flow as tools are assigned. Move them to another flow first.';
			    status := 'false';
			    RETURN;
			END IF;

    -- Soft delete flow
    UPDATE board.flow
    SET is_active = false,
        last_updated_date = current_timestamp AT TIME ZONE 'UTC',
        updated_by = p_created_by
    WHERE flow_id = p_flow_id;
	GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'Flow deleted successfully';
        status := 'true';
    ELSE
       message := 'Flow deleted failed';
       status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'board.delete_flow',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_flow_id,
                p_created_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: delete_tool_flow(integer, text, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.delete_tool_flow(IN p_tool_flow_id integer, IN p_created_by text, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_exists integer;
	v_rowcount INTEGER := 0;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : Soft delete flow
      Sprint  : flow & rule - 6
    */

    -- Check flow exists
    SELECT COUNT(1) INTO v_exists
    FROM board.tool_flow
    WHERE tool_flow_id = p_tool_flow_id
      AND is_active = true;

    IF v_exists = 0 THEN
        message := 'Flow not found';
        status := 'false';
        RETURN;
    END IF;

    -- Soft delete tool flow
    UPDATE board.tool_flow
    SET is_active = false,
        last_updated_date = current_timestamp AT TIME ZONE 'UTC',
        updated_by = p_created_by
    WHERE tool_flow_id = p_tool_flow_id;
	GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'Tool Flow deleted successfully';
        status := 'true';
    ELSE
       message := 'Tool Flow deleted failed';
       status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'board.delete_tool_flow',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_tool_flow_id,
                p_created_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: get_board_participants_info(uuid, uuid); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_board_participants_info(added_by uuid, assign_to uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    participants JSONB;
BEGIN
    participants := (
        SELECT jsonb_agg(user_info)
        FROM (
            SELECT
                jsonb_build_object(
                    'regid', reguser."RegId",
                    'displayname', reguser."DisplayName",
                    'email', reguser."Email",
                    'photo', encode(reguser."Photo"::bytea, 'base64')
                ) AS user_info
            FROM
                users.registereduser reguser
            WHERE
                reguser."RegId" = added_by
                AND reguser.is_active = 'true'  
			
            UNION            
			
            SELECT
                jsonb_build_object(
                    'regid', reguser_ass."RegId",
                    'displayname', reguser_ass."DisplayName",
                    'email', reguser_ass."Email",
                    'photo', encode(reguser_ass."Photo"::bytea, 'base64')
                ) AS user_info
            FROM
                users.registereduser reguser_ass
            WHERE
                reguser_ass."RegId" = assign_to
                AND reguser_ass.is_active = 'true'
        ) AS user_infos
    );

    RETURN participants;
END;
$$;


--
-- Name: get_dashboard_ticket_orders(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_orders(order_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(tabname text, type text, tabid integer, typeid integer, totalorder integer, totaltool integer, ordercomplete integer, orderreceived integer, orderactive integer)
    LANGUAGE plpgsql
    AS $$
BEGIN 
    RETURN QUERY  
    SELECT 
        'Orders' AS tabname,
        'Orders' AS type, 
		0 AS tabid,
		0 AS typeid,
          COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
		--(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd 
        ON b."BoardID" = dbd."BoardID" AND dbd.is_active = 'true'
    INNER JOIN master.department d 
        ON dbd."DeptID" = d."DeptID" AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd 
        ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt 
        ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic 
        ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct 
        ON tic.ticket_id = ct.ticket_id
    LEFT JOIN tickets.basic_ticket bt 
        ON tic.ticket_id = bt.ticket_id
    LEFT JOIN tickets.premium_ticket pt 
        ON tic.ticket_id = pt.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1 
        AND d."DeptCode" = 'OB'
        AND (order_type <> 'active' OR (
            (bsd."Code" = 'DONE' AND EXISTS (
                SELECT 1 FROM tickets.custom_ticket ct_sub
                LEFT JOIN master.status_code_master sc_sub 
                    ON ct_sub.status_id = sc_sub.status_id
                WHERE ct_sub.ticket_id = tic.ticket_id 
                AND UPPER(sc_sub.type) = 'TOOL'
                AND UPPER(sc_sub.name) <> 'COMPLETED'
            )) OR (UPPER(sc.name) <> 'COMPLETED')
        )) 
		AND (
			    (from_date IS NULL OR to_date IS NULL) 
			    OR (tic.created_date::DATE BETWEEN from_date AND to_date)
            );

    -- Second query: Orders Grouped by Board Name
    RETURN QUERY  
    SELECT  
        'Orders' AS tabname,
        COALESCE(b."Name", 'ON BOARDING')::text AS type,
		0 AS tabid,
		b."BoardID" AS typeid,
       COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b  
    INNER JOIN board.departmentboard dbd  
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'  
    INNER JOIN master.department d  
        ON dbd."DeptID" = d."DeptID"  
        AND d.is_active = 'true'  
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"  
        AND bsd.is_active = 'true'    
    LEFT JOIN tickets.ticket_board_tracker tbt  
        ON tbt.board_id = b."BoardID"  
        AND tbt.label_id = bsd."LabelID"  
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true'  
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id  
    LEFT JOIN tickets.basic_ticket bt 
        ON tic.ticket_id = bt.ticket_id
    LEFT JOIN tickets.premium_ticket pt 
        ON tic.ticket_id = pt.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE  
        b.is_active = 'true'  
        AND b.work_space_id = 1   
        AND d."DeptCode" = 'OB'  
        AND (order_type <> 'active' OR LOWER(ct.status) <> 'close')  
		AND (
			    (from_date IS NULL OR to_date IS NULL) 
			    OR (tic.created_date::DATE BETWEEN from_date AND to_date)
            )
    GROUP BY b."Name",b."BoardID"
    ORDER BY MIN(tic.created_date::DATE);
    
    --Third query: Orders Grouped by Support Production
  RETURN QUERY
SELECT
	'Orders' AS TABNAME,
	COALESCE(B."Name", 'PRODUCTION')::TEXT AS TYPE,
	0 AS tabid,
	b."BoardID" AS typeid,
	COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
	COUNT(CT.TOOL_TICKET_ID)::INTEGER AS TOTALTOOL,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) = 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERCOMPLETE,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				TIC.CREATED_DATE::DATE BETWEEN FROM_DATE AND TO_DATE
		)::INTEGER
		ELSE NULL
	END AS ORDERRECEIVED,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) <> 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERACTIVE
FROM
	BOARD.BOARD B
	INNER JOIN BOARD.DEPARTMENTBOARD DBD ON B."BoardID" = DBD."BoardID"
	AND DBD.IS_ACTIVE = 'true'
	INNER JOIN MASTER.DEPARTMENT D ON DBD."DeptID" = D."DeptID"
	AND D.IS_ACTIVE = 'true'
	LEFT JOIN BOARD.BOARDSTATUS BSD ON BSD."BoardID" = B."BoardID"
	AND BSD.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.TICKET_BOARD_TRACKER TBT ON TBT.BOARD_ID = B."BoardID"
	AND TBT.LABEL_ID = BSD."LabelID"
	LEFT JOIN TICKETS.TICKET TIC ON TBT.TICKET_ID = TIC.TICKET_ID
	AND TIC.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.CUSTOM_TICKET CT ON TIC.TICKET_ID = CT.TICKET_ID
	  LEFT JOIN tickets.basic_ticket bt 
        ON tic.ticket_id = bt.ticket_id
    LEFT JOIN tickets.premium_ticket pt 
        ON tic.ticket_id = pt.ticket_id
	LEFT JOIN MASTER.STATUS_CODE_MASTER SC ON CT.STATUS_ID = SC.STATUS_ID
	LEFT JOIN MASTER.TOOL TOL ON TOL."ToolID" = CT.TOOL_ID
WHERE
	B.IS_ACTIVE = 'true'
	AND B.WORK_SPACE_ID = 1
	AND D."DeptCode" = 'SP'
	AND (UPPER(SC.NAME) <> 'COMPLETED')
	AND CT.STATUS = 'close'
	AND (
		TOL.IS_DEPENDENCY_REQUIRED = FALSE
		OR (
			TOL.IS_DEPENDENCY_REQUIRED = TRUE
			AND EXISTS (
				SELECT
					1
				FROM
					TICKETS.CUSTOM_TOOL_UPDATE_TEAM UT
					LEFT JOIN MASTER.STATUS_CODE_MASTER SC_SUB ON UT.STATUS_ID = SC_SUB.STATUS_ID
				WHERE
					UT.TOOL_TICKET_ID = CT.TOOL_TICKET_ID
					AND UPPER(SC_SUB.TYPE) = 'TOOL'
					AND UPPER(SC_SUB.NAME) = 'COMPLETED'
			)
		)
	)
	AND UPPER(SC.TYPE) = 'TOOL'
	AND (
		(from_date IS NULL OR to_date IS NULL) 
		OR (tic.created_date::DATE BETWEEN from_date AND to_date)
	)
GROUP BY
	B."Name" ,  B."BoardID"
ORDER BY
	MIN(TIC.CREATED_DATE::DATE);

	--FOURTH query: Orders Grouped by UPDATE TEAM
RETURN QUERY 
SELECT  
    'Orders' AS tabname,
    COALESCE(b."Name", 'UPDATE')::text AS type,
	0 AS tabid,
	(b."BoardID") AS typeid,
   COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
    COUNT(ct.tool_ticket_id)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
Left JOIN board.departmentboard dbd    
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
Left JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"   
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"   
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt   
    ON tbt.board_id = b."BoardID"   
    AND tbt.label_id = bsd."LabelID"
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id  
    AND tic.is_active = 'true' 
LEFT JOIN tickets.custom_ticket ct  
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.basic_ticket bt 
ON tic.ticket_id = bt.ticket_id
LEFT JOIN tickets.premium_ticket pt 
ON tic.ticket_id = pt.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ut.tool_ticket_id = ct.tool_ticket_id
LEFT JOIN master.status_code_master sc 
    ON sc.status_id = ut.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    AND d."DeptCode" IN ('DT', 'UT','AC')
    AND ut.dept_code IN ('DT', 'UT','AC')
   AND (
		(from_date IS NULL OR to_date IS NULL) 
		OR (tic.created_date::DATE BETWEEN from_date AND to_date)
	)
GROUP BY b."Name" ,  b."BoardID"
ORDER BY MIN(tic.created_date::DATE);

-- FIFTH query: Orders Grouped by other support Production with labels for All department completed stage
    RETURN QUERY  
   SELECT  
    COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
    COALESCE(bsd."Name", 'OPEN')::text AS type,
	b."BoardID" AS tabid,
	bsd."LabelID" AS typeid,
	(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))::integer AS totalorder,
	 (COUNT( ct.tool_ticket_id) + COUNT( bt.tool_ticket_id) + COUNT( pt.tool_ticket_id))::integer AS totaltool,
	 --COALESCE(count( gtc.tool_ordered_count), 0)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) = 'COMPLETED'  AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date  AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) <> 'COMPLETED'  AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
INNER JOIN board.departmentboard dbd  
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
INNER JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"  
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"  
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt    
    ON tbt.board_id = b."BoardID"  
    AND (tbt.label_id = bsd."LabelID" OR tbt.label_id IS NULL) -- Include all labels even if not in tracker
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id   
    AND tic.is_active = 'true' 
LEFT JOIN LATERAL (
SELECT gtc.tool_ordered_count 
FROM board.get_tool_counts(tic.ticket_id) AS gtc
) AS gtc ON true
LEFT JOIN tickets.custom_ticket ct   
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.basic_ticket bt 
	ON tic.ticket_id = bt.ticket_id
LEFT JOIN tickets.premium_ticket pt 
	ON tic.ticket_id = pt.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ct.tool_ticket_id = ut.tool_ticket_id
LEFT JOIN master.status_code_master sc_sub 
    ON ut.status_id = sc_sub.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    --AND d."DeptCode" IN('AC,UT,DT')  -- Uncomment if needed
    AND (UPPER(sc_sub.name) = 'COMPLETED' OR sc_sub.name IS NULL)
    AND (UPPER(sc_sub.type) = 'TOOL' OR sc_sub.type IS NULL) -- Ensure statuses without tools are included
	-- AND (
	-- 	(from_date IS NULL OR to_date IS NULL) 
	-- 	OR (tic.created_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date)
	-- )
GROUP BY b."BoardID", bsd."LabelID"
ORDER BY  b."BoardID", bsd."Position";

END;  
$$;


--
-- Name: get_dashboard_ticket_orders112(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_orders112(order_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(tabname text, type text, tabid integer, typeid integer, totalorder integer, totaltool integer, ordercomplete integer, orderreceived integer, orderactive integer)
    LANGUAGE plpgsql
    AS $$
BEGIN 
    RETURN QUERY  
    SELECT 
        'Orders' AS tabname,
        'Orders' AS type, 
		0 AS tabid,
		0 AS typeid,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
		--(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd 
        ON b."BoardID" = dbd."BoardID" AND dbd.is_active = 'true'
    INNER JOIN master.department d 
        ON dbd."DeptID" = d."DeptID" AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd 
        ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt 
        ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic 
        ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct 
        ON tic.ticket_id = ct.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1 
        AND d."DeptCode" = 'OB'
        AND (order_type <> 'active' OR (
            (bsd."Code" = 'DONE' AND EXISTS (
                SELECT 1 FROM tickets.custom_ticket ct_sub
                LEFT JOIN master.status_code_master sc_sub 
                    ON ct_sub.status_id = sc_sub.status_id
                WHERE ct_sub.ticket_id = tic.ticket_id 
                AND UPPER(sc_sub.type) = 'TOOL'
                AND UPPER(sc_sub.name) <> 'COMPLETED'
            )) OR (UPPER(sc.name) <> 'COMPLETED')
        ));

    -- Second query: Orders Grouped by Board Name
    RETURN QUERY  
    SELECT  
        'Orders' AS tabname,
        COALESCE(b."Name", 'ON BOARDING')::text AS type,
		0 AS tabid,
		b."BoardID" AS typeid,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED'   AND (tic.created_date::DATE BETWEEN from_date AND to_date) )::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b  
    INNER JOIN board.departmentboard dbd  
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'  
    INNER JOIN master.department d  
        ON dbd."DeptID" = d."DeptID"  
        AND d.is_active = 'true'  
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"  
        AND bsd.is_active = 'true'    
    LEFT JOIN tickets.ticket_board_tracker tbt  
        ON tbt.board_id = b."BoardID"  
        AND tbt.label_id = bsd."LabelID"  
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true'  
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id  
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE  
        b.is_active = 'true'  
        AND b.work_space_id = 1   
        AND d."DeptCode" = 'OB'  
        AND (order_type <> 'active' OR LOWER(ct.status) <> 'close')  
    GROUP BY b."Name"  ,  b."BoardID"
    ORDER BY MIN(tic.created_date::DATE);
    
    --Third query: Orders Grouped by Support Production
  RETURN QUERY
SELECT
	'Orders' AS TABNAME,
	COALESCE(B."Name", 'PRODUCTION')::TEXT AS TYPE,
	0 AS tabid,
	b."BoardID" AS typeid,
	COUNT(DISTINCT TIC.TICKET_ID)::INTEGER AS TOTALORDER,
	COUNT(CT.TOOL_TICKET_ID)::INTEGER AS TOTALTOOL,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) = 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERCOMPLETE,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				TIC.CREATED_DATE::DATE BETWEEN FROM_DATE AND TO_DATE
		)::INTEGER
		ELSE NULL
	END AS ORDERRECEIVED,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) <> 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERACTIVE
FROM
	BOARD.BOARD B
	INNER JOIN BOARD.DEPARTMENTBOARD DBD ON B."BoardID" = DBD."BoardID"
	AND DBD.IS_ACTIVE = 'true'
	INNER JOIN MASTER.DEPARTMENT D ON DBD."DeptID" = D."DeptID"
	AND D.IS_ACTIVE = 'true'
	LEFT JOIN BOARD.BOARDSTATUS BSD ON BSD."BoardID" = B."BoardID"
	AND BSD.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.TICKET_BOARD_TRACKER TBT ON TBT.BOARD_ID = B."BoardID"
	AND TBT.LABEL_ID = BSD."LabelID"
	LEFT JOIN TICKETS.TICKET TIC ON TBT.TICKET_ID = TIC.TICKET_ID
	AND TIC.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.CUSTOM_TICKET CT ON TIC.TICKET_ID = CT.TICKET_ID
	LEFT JOIN MASTER.STATUS_CODE_MASTER SC ON CT.STATUS_ID = SC.STATUS_ID
	LEFT JOIN MASTER.TOOL TOL ON TOL."ToolID" = CT.TOOL_ID
WHERE
	B.IS_ACTIVE = 'true'
	AND B.WORK_SPACE_ID = 1
	AND D."DeptCode" = 'SP'
	AND (UPPER(SC.NAME) <> 'COMPLETED')
	AND CT.STATUS = 'close'
	AND (
		TOL.IS_DEPENDENCY_REQUIRED = FALSE
		OR (
			TOL.IS_DEPENDENCY_REQUIRED = TRUE
			AND EXISTS (
				SELECT
					1
				FROM
					TICKETS.CUSTOM_TOOL_UPDATE_TEAM UT
					LEFT JOIN MASTER.STATUS_CODE_MASTER SC_SUB ON UT.STATUS_ID = SC_SUB.STATUS_ID
				WHERE
					UT.TOOL_TICKET_ID = CT.TOOL_TICKET_ID
					AND UPPER(SC_SUB.TYPE) = 'TOOL'
					AND UPPER(SC_SUB.NAME) = 'COMPLETED'
			)
		)
	)
	AND UPPER(SC.TYPE) = 'TOOL'
GROUP BY
	B."Name" ,  B."BoardID"
ORDER BY
	MIN(TIC.CREATED_DATE::DATE);

	-- FOURTH query: Orders Grouped by UPDATE TEAM
RETURN QUERY 
SELECT  
    'Orders' AS tabname,
    COALESCE(b."Name", 'UPDATE')::text AS type,
	0 AS tabid,
	(b."BoardID") AS typeid,
    COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
    COUNT(ct.tool_ticket_id)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED'  AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
Left JOIN board.departmentboard dbd    
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
Left JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"   
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"   
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt   
    ON tbt.board_id = b."BoardID"   
    AND tbt.label_id = bsd."LabelID"
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id  
    AND tic.is_active = 'true' 
LEFT JOIN tickets.custom_ticket ct  
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ut.tool_ticket_id = ct.tool_ticket_id
LEFT JOIN master.status_code_master sc 
    ON sc.status_id = ut.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    AND d."DeptCode" IN ('DT', 'UT','AC')
    AND ut.dept_code IN ('DT', 'UT','AC')
    
GROUP BY b."Name" ,  b."BoardID"
ORDER BY MIN(tic.created_date::DATE);

-- FIFTH query: Orders Grouped by other support Production with labels for All department completed stage
    RETURN QUERY  
   SELECT  
    COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
    COALESCE(bsd."Name", 'OPEN')::text AS type,
	b."BoardID" AS tabid,
	bsd."LabelID" AS typeid,
    --COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
	(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))::integer AS totalorder,
    --COUNT(ct.tool_ticket_id)::integer AS totaltool,
	 COALESCE(SUM(gtc.tool_ordered_count), 0)::integer AS totaltool,
	--COALESCE((SELECT Sum(gtc.tool_ordered_count) FROM board.get_tool_counts(tic.ticket_id) AS gtc),0)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) = 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) <> 'COMPLETED'  AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
INNER JOIN board.departmentboard dbd  
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
INNER JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"  
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"  
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt    
    ON tbt.board_id = b."BoardID"  
    AND (tbt.label_id = bsd."LabelID" OR tbt.label_id IS NULL) -- Include all labels even if not in tracker
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id   
    AND tic.is_active = 'true' 
LEFT JOIN LATERAL (
SELECT gtc.tool_ordered_count 
FROM board.get_tool_counts(tic.ticket_id) AS gtc
) AS gtc ON true
LEFT JOIN tickets.custom_ticket ct   
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ct.tool_ticket_id = ut.tool_ticket_id
LEFT JOIN master.status_code_master sc_sub 
    ON ut.status_id = sc_sub.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    --AND d."DeptCode" IN('AC,UT,DT')  -- Uncomment if needed
    AND (UPPER(sc_sub.name) = 'COMPLETED' OR sc_sub.name IS NULL)
    AND (UPPER(sc_sub.type) = 'TOOL' OR sc_sub.type IS NULL) -- Ensure statuses without tools are included
GROUP BY b."BoardID", bsd."LabelID"
ORDER BY  b."BoardID", bsd."Position";

