--
-- Name: get_dashboard_ticket_orders77(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_orders77(order_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(tabname text, type text, tabid integer, typeid integer, totalorder integer, totaltool integer, ordercomplete integer, orderreceived integer, orderactive integer)
    LANGUAGE plpgsql
    AS $$
BEGIN 
    RETURN QUERY  
    SELECT 
        'Orders' AS tabname,
        'Orders' AS type, 
		0 AS tabid,
		0 AS typeid,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
		--(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd 
        ON b."BoardID" = dbd."BoardID" AND dbd.is_active = 'true'
    INNER JOIN master.department d 
        ON dbd."DeptID" = d."DeptID" AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd 
        ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt 
        ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic 
        ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct 
        ON tic.ticket_id = ct.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1 
        AND d."DeptCode" = 'OB'
        AND (order_type <> 'active' OR (
            (bsd."Code" = 'DONE' AND EXISTS (
                SELECT 1 FROM tickets.custom_ticket ct_sub
                LEFT JOIN master.status_code_master sc_sub 
                    ON ct_sub.status_id = sc_sub.status_id
                WHERE ct_sub.ticket_id = tic.ticket_id 
                AND UPPER(sc_sub.type) = 'TOOL'
                AND UPPER(sc_sub.name) <> 'COMPLETED'
            )) OR (UPPER(sc.name) <> 'COMPLETED')
        ));

    -- Second query: Orders Grouped by Board Name
    RETURN QUERY  
    SELECT  
        'Orders' AS tabname,
        COALESCE(b."Name", 'ON BOARDING')::text AS type,
		0 AS tabid,
		b."BoardID" AS typeid,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED'   AND (tic.created_date::DATE BETWEEN from_date AND to_date) )::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b  
    INNER JOIN board.departmentboard dbd  
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'  
    INNER JOIN master.department d  
        ON dbd."DeptID" = d."DeptID"  
        AND d.is_active = 'true'  
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"  
        AND bsd.is_active = 'true'    
    LEFT JOIN tickets.ticket_board_tracker tbt  
        ON tbt.board_id = b."BoardID"  
        AND tbt.label_id = bsd."LabelID"  
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true'  
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id  
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE  
        b.is_active = 'true'  
        AND b.work_space_id = 1   
        AND d."DeptCode" = 'OB'  
        AND (order_type <> 'active' OR LOWER(ct.status) <> 'close')  
    GROUP BY b."Name"  ,  b."BoardID"
    ORDER BY MIN(tic.created_date::DATE);
    
    --Third query: Orders Grouped by Support Production
  RETURN QUERY
SELECT
	'Orders' AS TABNAME,
	COALESCE(B."Name", 'PRODUCTION')::TEXT AS TYPE,
	0 AS tabid,
	b."BoardID" AS typeid,
	COUNT(DISTINCT TIC.TICKET_ID)::INTEGER AS TOTALORDER,
	COUNT(CT.TOOL_TICKET_ID)::INTEGER AS TOTALTOOL,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) = 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERCOMPLETE,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				TIC.CREATED_DATE::DATE BETWEEN FROM_DATE AND TO_DATE
		)::INTEGER
		ELSE NULL
	END AS ORDERRECEIVED,
	CASE
		WHEN ORDER_TYPE = 'overall' THEN COUNT(*) FILTER (
			WHERE
				UPPER(SC.NAME) <> 'COMPLETED'
		)::INTEGER
		ELSE NULL
	END AS ORDERACTIVE
FROM
	BOARD.BOARD B
	INNER JOIN BOARD.DEPARTMENTBOARD DBD ON B."BoardID" = DBD."BoardID"
	AND DBD.IS_ACTIVE = 'true'
	INNER JOIN MASTER.DEPARTMENT D ON DBD."DeptID" = D."DeptID"
	AND D.IS_ACTIVE = 'true'
	LEFT JOIN BOARD.BOARDSTATUS BSD ON BSD."BoardID" = B."BoardID"
	AND BSD.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.TICKET_BOARD_TRACKER TBT ON TBT.BOARD_ID = B."BoardID"
	AND TBT.LABEL_ID = BSD."LabelID"
	LEFT JOIN TICKETS.TICKET TIC ON TBT.TICKET_ID = TIC.TICKET_ID
	AND TIC.IS_ACTIVE = 'true'
	LEFT JOIN TICKETS.CUSTOM_TICKET CT ON TIC.TICKET_ID = CT.TICKET_ID
	LEFT JOIN MASTER.STATUS_CODE_MASTER SC ON CT.STATUS_ID = SC.STATUS_ID
	LEFT JOIN MASTER.TOOL TOL ON TOL."ToolID" = CT.TOOL_ID
WHERE
	B.IS_ACTIVE = 'true'
	AND B.WORK_SPACE_ID = 1
	AND D."DeptCode" = 'SP'
	AND (UPPER(SC.NAME) <> 'COMPLETED')
	AND CT.STATUS = 'close'
	AND (
		TOL.IS_DEPENDENCY_REQUIRED = FALSE
		OR (
			TOL.IS_DEPENDENCY_REQUIRED = TRUE
			AND EXISTS (
				SELECT
					1
				FROM
					TICKETS.CUSTOM_TOOL_UPDATE_TEAM UT
					LEFT JOIN MASTER.STATUS_CODE_MASTER SC_SUB ON UT.STATUS_ID = SC_SUB.STATUS_ID
				WHERE
					UT.TOOL_TICKET_ID = CT.TOOL_TICKET_ID
					AND UPPER(SC_SUB.TYPE) = 'TOOL'
					AND UPPER(SC_SUB.NAME) = 'COMPLETED'
			)
		)
	)
	AND UPPER(SC.TYPE) = 'TOOL'
GROUP BY
	B."Name" ,  B."BoardID"
ORDER BY
	MIN(TIC.CREATED_DATE::DATE);

	-- FOURTH query: Orders Grouped by UPDATE TEAM
RETURN QUERY 
SELECT  
    'Orders' AS tabname,
    COALESCE(b."Name", 'UPDATE')::text AS type,
	0 AS tabid,
	(b."BoardID") AS typeid,
    COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
    COUNT(ct.tool_ticket_id)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED'  AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
Left JOIN board.departmentboard dbd    
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
Left JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"   
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"   
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt   
    ON tbt.board_id = b."BoardID"   
    AND tbt.label_id = bsd."LabelID"
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id  
    AND tic.is_active = 'true' 
LEFT JOIN tickets.custom_ticket ct  
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ut.tool_ticket_id = ct.tool_ticket_id
LEFT JOIN master.status_code_master sc 
    ON sc.status_id = ut.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    AND d."DeptCode" IN ('DT', 'UT','AC')
    AND ut.dept_code IN ('DT', 'UT','AC')
    
GROUP BY b."Name" ,  b."BoardID"
ORDER BY MIN(tic.created_date::DATE);

-- FIFTH query: Orders Grouped by other support Production with labels for All department completed stage
    RETURN QUERY  
   SELECT  
    COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
    COALESCE(bsd."Name", 'OPEN')::text AS type,
	b."BoardID" AS tabid,
	bsd."LabelID" AS typeid,
    --COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
	(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))::integer AS totalorder,
    --COUNT(ct.tool_ticket_id)::integer AS totaltool,
	 COALESCE(SUM(gtc.tool_ordered_count), 0)::integer AS totaltool,
	--COALESCE((SELECT Sum(gtc.tool_ordered_count) FROM board.get_tool_counts(tic.ticket_id) AS gtc),0)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) = 'COMPLETED' AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) <> 'COMPLETED'  AND (tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
INNER JOIN board.departmentboard dbd  
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
INNER JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"  
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"  
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt    
    ON tbt.board_id = b."BoardID"  
    AND (tbt.label_id = bsd."LabelID" OR tbt.label_id IS NULL) -- Include all labels even if not in tracker
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id   
    AND tic.is_active = 'true' 
LEFT JOIN LATERAL (
SELECT gtc.tool_ordered_count 
FROM board.get_tool_counts(tic.ticket_id) AS gtc
) AS gtc ON true
LEFT JOIN tickets.custom_ticket ct   
    ON tic.ticket_id = ct.ticket_id
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ct.tool_ticket_id = ut.tool_ticket_id
LEFT JOIN master.status_code_master sc_sub 
    ON ut.status_id = sc_sub.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    --AND d."DeptCode" IN('AC,UT,DT')  -- Uncomment if needed
    AND (UPPER(sc_sub.name) = 'COMPLETED' OR sc_sub.name IS NULL)
    AND (UPPER(sc_sub.type) = 'TOOL' OR sc_sub.type IS NULL) -- Ensure statuses without tools are included
GROUP BY b."BoardID", bsd."LabelID"
ORDER BY  b."BoardID", bsd."Position";

 -- FIFTH query: Orders Grouped by Support Production with labels
--     RETURN QUERY  
--     SELECT  
--     COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
--     COALESCE(bsd."Name", 'OPEN')::text AS type,
