$$;


--
-- Name: get_dashboard_ticket_orders_anc(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_orders_anc(order_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(tabname text, type text, totalorder integer, totaltool integer, ordercomplete integer, orderreceived integer, orderactive integer)
    LANGUAGE plpgsql
    AS $$
BEGIN 
    RETURN QUERY  
    SELECT 
        'Orders' AS tabname,
        'Orders' AS type, 
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd 
        ON b."BoardID" = dbd."BoardID" AND dbd.is_active = 'true'
    INNER JOIN master.department d 
        ON dbd."DeptID" = d."DeptID" AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd 
        ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt 
        ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic 
        ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct 
        ON tic.ticket_id = ct.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1 
        AND d."DeptCode" = 'OB'
        AND (order_type <> 'active' OR (
            (bsd."Code" = 'DONE' AND EXISTS (
                SELECT 1 FROM tickets.custom_ticket ct_sub
                LEFT JOIN master.status_code_master sc_sub 
                    ON ct_sub.status_id = sc_sub.status_id
                WHERE ct_sub.ticket_id = tic.ticket_id 
                AND UPPER(sc_sub.type) = 'TOOL'
                AND UPPER(sc_sub.name) <> 'COMPLETED'
            )) OR (UPPER(sc.name) <> 'COMPLETED')
        ));

    -- Second query: Orders Grouped by Board Name
    RETURN QUERY  
    SELECT  
        'Orders' AS tabname,
        COALESCE(b."Name", 'ON BOARDING')::text AS type,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b  
    INNER JOIN board.departmentboard dbd  
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'  
    INNER JOIN master.department d  
        ON dbd."DeptID" = d."DeptID"  
        AND d.is_active = 'true'  
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"  
        AND bsd.is_active = 'true'    
    LEFT JOIN tickets.ticket_board_tracker tbt  
        ON tbt.board_id = b."BoardID"  
        AND tbt.label_id = bsd."LabelID"  
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true'  
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id  
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE  
        b.is_active = 'true'  
        AND b.work_space_id = 1   
        AND d."DeptCode" = 'OB'  
        AND (order_type <> 'active' OR LOWER(ct.status) <> 'close')  
        AND tic.created_date::DATE BETWEEN from_date AND to_date  
    GROUP BY b."Name"  
    ORDER BY MIN(tic.created_date::DATE);
    
    -- Third query: Orders Grouped by Support Production
    RETURN QUERY  
    SELECT  
        'Orders' AS tabname,
        COALESCE(b."Name", 'PRODUCTION')::text AS type,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd    
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'
    INNER JOIN master.department d   
        ON dbd."DeptID" = d."DeptID"   
        AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"   
        AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt   
        ON tbt.board_id = b."BoardID"   
        AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
        AND d."DeptCode" = 'SP'
        AND tic.created_date::DATE BETWEEN from_date AND to_date
    GROUP BY b."Name"
    ORDER BY MIN(tic.created_date::DATE);

END;  
$$;


--
-- Name: get_dashboard_ticket_toolinfo(text, text, text, timestamp without time zone, timestamp without time zone, text, integer, integer, text, integer, integer, boolean); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_toolinfo(order_type text, order_by text, sort_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, search_text text DEFAULT NULL::text, team integer DEFAULT NULL::integer, card_stage integer DEFAULT NULL::integer, team_member text DEFAULT NULL::uuid, offsetno integer DEFAULT 0, page_size integer DEFAULT 20, is_excel_download boolean DEFAULT false) RETURNS TABLE(totalcount integer, "SNo" integer, "OrderID" text, "TicketId" integer, "CardName" text, "CompanyName" text, "CompanyCode" text, "BoardName" text, "ToolNames" text, "OrderDate" text, "ToolsOrderedCount" integer, "CurrentStage" text, "CreatedDate" text, "DueDate" text, "DisplayName" text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    sql_query TEXT;
BEGIN 
    RETURN QUERY  
		WITH ticket_toolinfo AS (
		SELECT 
		combined_assignees.ticket_id, 
		STRING_AGG(tl."ToolName", E'\n') AS tool_names
		FROM(
		SELECT 
		bt.ticket_id, bt.tool_ticket_id, bt.tool_id 
		FROM tickets.basic_ticket bt 
		UNION ALL
		SELECT 
		ct.ticket_id, ct.tool_ticket_id, ct.tool_id 
		FROM tickets.custom_ticket ct
		UNION ALL
		SELECT 
		pt.ticket_id, pt.tool_ticket_id, pt.tool_id
		FROM tickets.premium_ticket pt
		) AS combined_assignees
		JOIN master.tool tl ON tl."ToolID" = combined_assignees.tool_id
		GROUP BY combined_assignees.ticket_id
		)
		SELECT
		COUNT(*) OVER()::INT AS TotalCount,
		ROW_NUMBER() OVER 
		(ORDER BY tic.ticket_id)::INT AS "SNo",
		tic.order_id::TEXT AS "OrderID",
		tic.ticket_id::INT AS "TicketId", 
		tic.name::TEXT as CardName,
		c.company_name::TEXT AS "CompanyName",
		c.customer_code::TEXT as CompanyCode,
		b."Name"::TEXT as BoardName,
		tl.tool_names::TEXT,
		TO_CHAR(tic.order_date, 'DD-MM-YYYY') AS "OrderDate",
		(
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.custom_ticket WHERE ticket_id = tic.ticket_id) +
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.basic_ticket WHERE ticket_id = tic.ticket_id) +
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.premium_ticket WHERE ticket_id = tic.ticket_id)
		) AS "ToolsOrderedCount",
		bsd."Name"::TEXT AS "CurrentStage",	
		TO_CHAR(tic.created_date, 'DD-MM-YYYY') AS "CreatedDate", 
		TO_CHAR(tic.due_date, 'DD-MM-YYYY') AS "DueDate"   ,
		rg."DisplayName"
		FROM tickets.ticket tic  
		JOIN ticket_toolinfo tl ON tic.ticket_id = tl.ticket_id
		JOIN customers.customer c ON tic.customer_id = c.customer_id
		JOIN tickets.ticket_board_tracker tbt ON tic.ticket_id = tbt.ticket_id
		JOIN board.boardstatus bsd ON tbt.label_id = bsd."LabelID" 
		JOIN board.board b ON bsd."BoardID" = b."BoardID"
		INNER JOIN board.departmentboard dbd    ON b."BoardID" = dbd."BoardID"  AND dbd.is_active = 'true'
		INNER JOIN master.department d   ON dbd."DeptID" = d."DeptID"   AND d.is_active = 'true'
		JOIN users.registereduser rg on rg."RegId"=tic.created_by :: UUID
		WHERE d."DeptCode" IN ('OB','SP','AC','DT','UT')
		AND (from_date IS NULL OR tic.created_date::DATE >= from_date::DATE)
		AND (to_date IS NULL OR tic.created_date::DATE <= to_date::DATE)
		--AND tic.created_date::DATE BETWEEN '2025-01-04' AND '2025-02-05' 
		AND ((search_text IS NULL) OR (tic.name ILIKE '%' || search_text || '%') OR  (c.company_name ILIKE '%' || search_text || '%'))
        --Filters
		AND (team IS NULL  OR  team = 0 OR b."BoardID" = team) --Board
		AND (card_stage IS NULL  OR    card_stage = 0 OR bsd."LabelID" = card_stage)  --Label 
       AND (team_member IS NULL OR rg."RegId" = NULLIF(team_member, '')::UUID) --RegId
		--ORDER BY tic.created_date,tic.ticket_id,b."Name"
		 ORDER BY
        CASE WHEN order_by = 'CompanyName' AND sort_type = 'ASC' THEN c.company_name END ASC,
        CASE WHEN order_by = 'CompanyName' AND sort_type = 'DESC' THEN c.company_name END DESC,
        CASE WHEN order_by = 'OrderDate' AND sort_type = 'ASC' THEN tic.order_date END ASC,
        CASE WHEN order_by = 'OrderDate' AND sort_type = 'DESC' THEN tic.order_date END DESC,
        CASE WHEN order_by = 'DueDate' AND sort_type = 'ASC' THEN tic.due_date END ASC,
        CASE WHEN order_by = 'DueDate' AND sort_type = 'DESC' THEN tic.due_date END DESC,
        CASE WHEN order_by = 'CreatedDate' AND sort_type = 'ASC' THEN tic.created_date END ASC,
        CASE WHEN order_by = 'CreatedDate' AND sort_type = 'DESC' THEN tic.created_date END DESC
        --tic.created_date, tic.ticket_id
      -- OFFSET offsetno LIMIT page_size;
	   OFFSET CASE WHEN is_excel_download = false THEN offsetno ELSE 0 END
       LIMIT CASE WHEN is_excel_download = false THEN page_size ELSE NULL END;
		
END;  
$$;


--
-- Name: get_dashboard_ticket_toolinfo(text, text, text, timestamp without time zone, timestamp without time zone, text, integer, integer, uuid, integer, integer, boolean); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_toolinfo(order_type text, order_by text, sort_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, search_text text DEFAULT NULL::text, team integer DEFAULT NULL::integer, card_stage integer DEFAULT NULL::integer, team_member uuid DEFAULT NULL::uuid, offsetno integer DEFAULT 0, page_size integer DEFAULT 20, is_excel_download boolean DEFAULT false) RETURNS TABLE(totalcount integer, "SNo" integer, "OrderID" text, "TicketId" integer, "CardName" text, "CompanyName" text, "CompanyCode" text, "BoardName" text, "ToolNames" text, "OrderDate" text, "ToolsOrderedCount" integer, "CurrentStage" text, "CreatedDate" text, "DueDate" text, "DisplayName" text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    sql_query TEXT;
BEGIN 
    RETURN QUERY  
		WITH ticket_toolinfo AS (
		SELECT 
		combined_assignees.ticket_id, 
		STRING_AGG(tl."ToolName", E'\n') AS tool_names
		FROM(
		SELECT 
		bt.ticket_id, bt.tool_ticket_id, bt.tool_id 
		FROM tickets.basic_ticket bt 
		UNION ALL
		SELECT 
		ct.ticket_id, ct.tool_ticket_id, ct.tool_id 
		FROM tickets.custom_ticket ct
		UNION ALL
		SELECT 
		pt.ticket_id, pt.tool_ticket_id, pt.tool_id
		FROM tickets.premium_ticket pt
		) AS combined_assignees
		JOIN master.tool tl ON tl."ToolID" = combined_assignees.tool_id
		GROUP BY combined_assignees.ticket_id
		)
		SELECT
		COUNT(*) OVER()::INT AS TotalCount,
		ROW_NUMBER() OVER 
		(ORDER BY tic.ticket_id)::INT AS "SNo",
		tic.order_id::TEXT AS "OrderID",
		tic.ticket_id::INT AS "TicketId", 
		tic.name::TEXT as CardName,
		c.company_name::TEXT AS "CompanyName",
		c.customer_code::TEXT as CompanyCode,
		b."Name"::TEXT as BoardName,
		tl.tool_names::TEXT,
		TO_CHAR(tic.order_date, 'DD-MM-YYYY') AS "OrderDate",
		(
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.custom_ticket WHERE ticket_id = tic.ticket_id) +
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.basic_ticket WHERE ticket_id = tic.ticket_id) +
		(SELECT COUNT(tool_ticket_id)::INT FROM tickets.premium_ticket WHERE ticket_id = tic.ticket_id)
		) AS "ToolsOrderedCount",
		bsd."Name"::TEXT AS "CurrentStage",	
		TO_CHAR(tic.created_date, 'DD-MM-YYYY') AS "CreatedDate", 
		TO_CHAR(tic.due_date, 'DD-MM-YYYY') AS "DueDate"   ,
		rg."DisplayName"
		FROM tickets.ticket tic  
		JOIN ticket_toolinfo tl ON tic.ticket_id = tl.ticket_id
		JOIN customers.customer c ON tic.customer_id = c.customer_id
		JOIN tickets.ticket_board_tracker tbt ON tic.ticket_id = tbt.ticket_id
		JOIN board.boardstatus bsd ON tbt.label_id = bsd."LabelID" 
		JOIN board.board b ON bsd."BoardID" = b."BoardID"
		INNER JOIN board.departmentboard dbd    ON b."BoardID" = dbd."BoardID"  AND dbd.is_active = 'true'
		INNER JOIN master.department d   ON dbd."DeptID" = d."DeptID"   AND d.is_active = 'true'
		JOIN users.registereduser rg on rg."RegId"=tic.created_by :: UUID
		WHERE d."DeptCode" IN ('OB','SP','AC','DT','UT')
		AND (from_date IS NULL OR tic.created_date::DATE >= from_date::DATE)
		AND (to_date IS NULL OR tic.created_date::DATE <= to_date::DATE)
		--AND tic.created_date::DATE BETWEEN '2025-01-04' AND '2025-02-05' 
		AND ((search_text IS NULL) OR (tic.name ILIKE '%' || search_text || '%') OR  (c.company_name ILIKE '%' || search_text || '%'))
        --Filters
		AND (team IS NULL  OR  team = 0 OR b."BoardID" = team) --Board
		AND (card_stage IS NULL  OR    card_stage = 0 OR bsd."LabelID" = card_stage)  --Label 
        AND (team_member IS NULL OR rg."RegId" = team_member) --RegId
		--ORDER BY tic.created_date,tic.ticket_id,b."Name"
		 ORDER BY
        CASE WHEN order_by = 'CompanyName' AND sort_type = 'ASC' THEN c.company_name END ASC,
        CASE WHEN order_by = 'CompanyName' AND sort_type = 'DESC' THEN c.company_name END DESC,
        CASE WHEN order_by = 'OrderDate' AND sort_type = 'ASC' THEN tic.order_date END ASC,
        CASE WHEN order_by = 'OrderDate' AND sort_type = 'DESC' THEN tic.order_date END DESC,
        CASE WHEN order_by = 'DueDate' AND sort_type = 'ASC' THEN tic.due_date END ASC,
        CASE WHEN order_by = 'DueDate' AND sort_type = 'DESC' THEN tic.due_date END DESC,
        CASE WHEN order_by = 'CreatedDate' AND sort_type = 'ASC' THEN tic.created_date END ASC,
        CASE WHEN order_by = 'CreatedDate' AND sort_type = 'DESC' THEN tic.created_date END DESC
        --tic.created_date, tic.ticket_id
      -- OFFSET offsetno LIMIT page_size;
	   OFFSET CASE WHEN is_excel_download = false THEN offsetno ELSE 0 END
       LIMIT CASE WHEN is_excel_download = false THEN page_size ELSE NULL END;
		
END;  
$$;


