        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd    
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'
    INNER JOIN master.department d   
        ON dbd."DeptID" = d."DeptID"   
        AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"   
        AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt   
        ON tbt.board_id = b."BoardID"   
        AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id
		 join users.registereduser rg On rg."RegId" = ct."assign_to"
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
        AND d."DeptCode" = 'SP'
        AND (
			    (from_date IS NULL OR to_date IS NULL) 
			    OR (tic.created_date::DATE BETWEEN from_date AND to_date)
            )
     GROUP BY b."Name",rg."RegId",rg."DisplayName"
    ORDER BY MIN(tic.created_date::DATE);

	--FOURTH query: Orders Grouped by UPDATE TEAM 
RETURN QUERY 
SELECT  
   'Orders' AS tabname,
    COALESCE(b."Name", 'UPDATE')::text AS type,
	    (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
    COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
    COUNT(ct.tool_ticket_id)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
INNER JOIN board.departmentboard dbd    
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
INNER JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"   
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"   
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt   
    ON tbt.board_id = b."BoardID"   
    AND tbt.label_id = bsd."LabelID"
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id  
    AND tic.is_active = 'true' 
LEFT JOIN tickets.custom_ticket ct  
    ON tic.ticket_id = ct.ticket_id
	 join users.registereduser rg On rg."RegId" = ct."assign_to"
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ut.tool_ticket_id = ct.tool_ticket_id
LEFT JOIN master.status_code_master sc 
    ON sc.status_id = ut.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    AND d."DeptCode" IN ('DT', 'UT','AC')
    AND ut.dept_code IN ('DT', 'UT','AC')
    AND (
			    (from_date IS NULL OR to_date IS NULL) 
			    OR (tic.created_date::DATE BETWEEN from_date AND to_date)
            )
 GROUP BY b."Name",rg."RegId",
		rg."DisplayName"
ORDER BY MIN(tic.created_date::DATE);


-- FIFTH query: Orders Grouped by other support Production with labels
    RETURN QUERY  
    SELECT  
	  COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
	  COALESCE(b."Name", '')::text AS type,
	  (rg."RegId")::uuid as regid,
	  (rg."DisplayName")::text as displayname,
	   --'' AS type,
       --COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
	   (tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID"))::integer AS totalorder,
       --COUNT(ct.tool_ticket_id)::integer AS totaltool,
	   COALESCE(SUM(gtc.tool_ordered_count), 0)::integer AS totaltool,
         CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) = 'COMPLETED' AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc_sub.name) <> 'COMPLETED'AND (from_date IS NULL OR to_date IS NULL OR tic.created_date::DATE BETWEEN from_date AND to_date))::integer
        ELSE NULL 
    END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd  ON b."BoardID" = dbd."BoardID"  AND dbd.is_active = 'true'
    INNER JOIN master.department d   ON dbd."DeptID" = d."DeptID"  AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  ON bsd."BoardID" = b."BoardID"  AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt    ON tbt.board_id = b."BoardID"  AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  ON tbt.ticket_id = tic.ticket_id   AND tic.is_active = 'true' 
    LEFT JOIN LATERAL (SELECT gtc.tool_ordered_count FROM board.get_tool_counts(tic.ticket_id) AS gtc) AS gtc ON true
	LEFT JOIN tickets.custom_ticket ct   ON tic.ticket_id = ct.ticket_id
	 join users.registereduser rg On rg."RegId" = ct."assign_to"
   -- LEFT JOIN master.status_code_master sc  ON ct.status_id = sc.status_id
	LEFT JOIN tickets.custom_tool_update_team  ut ON ct.tool_ticket_id = ut.tool_ticket_id
    LEFT JOIN master.status_code_master sc_sub ON ut.status_id = sc_sub.status_id
	LEFT JOIN master.tool tol ON  tol."ToolID" = ct.tool_id  
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
       -- AND d."DeptCode" IN('AC,UT,DT')
		AND (UPPER(sc_sub.name) = 'COMPLETED') 
        AND (
			    (from_date IS NULL OR to_date IS NULL) 
			    OR (tic.created_date::DATE BETWEEN from_date AND to_date)
            )
	AND UPPER(sc_sub.type) = 'TOOL'
	GROUP BY b."BoardID", bsd."LabelID",
	--tic.created_date::DATE,
	rg."RegId",
    rg."DisplayName"
	ORDER BY b."BoardID", bsd."LabelID";
	
END;  
$$;


--
-- Name: get_dashboard_ticket_users_orders_jp(text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_dashboard_ticket_users_orders_jp(order_type text, from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(tabname text, type text, regid uuid, displayname text, totalorder integer, totaltool integer, ordercomplete integer, orderreceived integer, orderactive integer)
    LANGUAGE plpgsql
    AS $$
BEGIN 
 

    -- Second query: Orders Grouped by Board Name
    RETURN QUERY  
    SELECT  
	    'Orders' AS tabname,
        COALESCE(b."Name", 'ON BOARDING')::text AS type,
		    (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b  
    INNER JOIN board.departmentboard dbd  
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'  
    INNER JOIN master.department d  
        ON dbd."DeptID" = d."DeptID"  
        AND d.is_active = 'true'  
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"  
        AND bsd.is_active = 'true'    
    LEFT JOIN tickets.ticket_board_tracker tbt  
        ON tbt.board_id = b."BoardID"  
        AND tbt.label_id = bsd."LabelID"  
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true'  
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id  
		 join users.registereduser rg On rg."RegId" = ct."assign_to"
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id AND UPPER(sc.type) = 'TOOL'
    WHERE  
        b.is_active = 'true'  
        AND b.work_space_id = 1   
        AND d."DeptCode" = 'OB'  
        AND (order_type <> 'active' OR LOWER(ct.status) <> 'close')  
        AND tic.created_date::DATE BETWEEN from_date AND to_date  
    GROUP BY b."Name",rg."RegId",
		rg."DisplayName"
    ORDER BY MIN(tic.created_date::DATE);
    
    -- Third query: Orders Grouped by Support Production
    RETURN QUERY  
    SELECT  
	 'Orders' AS tabname,
        COALESCE(b."Name", 'PRODUCTION')::text AS type,
		 (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
            ELSE NULL 
        END AS ordercomplete,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
            ELSE NULL 
        END AS orderreceived,
        CASE 
            WHEN order_type = 'overall' 
            THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
            ELSE NULL 
        END AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd    
        ON b."BoardID" = dbd."BoardID"  
        AND dbd.is_active = 'true'
    INNER JOIN master.department d   
        ON dbd."DeptID" = d."DeptID"   
        AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  
        ON bsd."BoardID" = b."BoardID"   
        AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt   
        ON tbt.board_id = b."BoardID"   
        AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  
        ON tbt.ticket_id = tic.ticket_id  
        AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct  
        ON tic.ticket_id = ct.ticket_id
		 join users.registereduser rg On rg."RegId" = ct."assign_to"
    LEFT JOIN master.status_code_master sc 
        ON ct.status_id = sc.status_id
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
        AND d."DeptCode" = 'SP'
        AND tic.created_date::DATE BETWEEN from_date AND to_date
     GROUP BY b."Name",rg."RegId",
		rg."DisplayName"
    ORDER BY MIN(tic.created_date::DATE);

	-- FOURTH query: Orders Grouped by UPDATE TEAM 
RETURN QUERY 
SELECT  
   'Orders' AS tabname,
    COALESCE(b."Name", 'UPDATE')::text AS type,
	    (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
    COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
    COUNT(ct.tool_ticket_id)::integer AS totaltool,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) = 'COMPLETED')::integer
        ELSE NULL 
    END AS ordercomplete,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE tic.created_date::DATE BETWEEN from_date AND to_date)::integer
        ELSE NULL 
    END AS orderreceived,
    CASE 
        WHEN order_type = 'overall' 
        THEN COUNT(*) FILTER (WHERE UPPER(sc.name) <> 'COMPLETED')::integer
        ELSE NULL 
    END AS orderactive
FROM board.board b
INNER JOIN board.departmentboard dbd    
    ON b."BoardID" = dbd."BoardID"  
    AND dbd.is_active = 'true'
INNER JOIN master.department d   
    ON dbd."DeptID" = d."DeptID"   
    AND d.is_active = 'true'
LEFT JOIN board.boardstatus bsd  
    ON bsd."BoardID" = b."BoardID"   
    AND bsd.is_active = 'true'  
LEFT JOIN tickets.ticket_board_tracker tbt   
    ON tbt.board_id = b."BoardID"   
    AND tbt.label_id = bsd."LabelID"
LEFT JOIN tickets.ticket tic  
    ON tbt.ticket_id = tic.ticket_id  
    AND tic.is_active = 'true' 
LEFT JOIN tickets.custom_ticket ct  
    ON tic.ticket_id = ct.ticket_id
	 join users.registereduser rg On rg."RegId" = ct."assign_to"
LEFT JOIN tickets.custom_tool_update_team ut 
    ON ut.tool_ticket_id = ct.tool_ticket_id
LEFT JOIN master.status_code_master sc 
    ON sc.status_id = ut.status_id
LEFT JOIN master.tool tol 
    ON tol."ToolID" = ct.tool_id  
WHERE 
    b.is_active = 'true' 
    AND b.work_space_id = 1  
    AND d."DeptCode" IN ('DT', 'UT','AC')
    AND ut.dept_code IN ('DT', 'UT','AC')
    AND tic.created_date::DATE BETWEEN from_date AND to_date
 GROUP BY b."Name",rg."RegId",
		rg."DisplayName"
ORDER BY MIN(tic.created_date::DATE);

 -- FIFTH query: Orders Grouped by Support Production with labels
    RETURN QUERY  
    SELECT  
	COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
       -- COALESCE(bsd."Name", 'OPEN')::text AS type,
	    COALESCE(b."Name", '')::text AS type,
	    (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        0 AS ordercomplete,
        0 AS orderreceived,
        0 AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd  ON b."BoardID" = dbd."BoardID"  AND dbd.is_active = 'true'
    INNER JOIN master.department d   ON dbd."DeptID" = d."DeptID"  AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  ON bsd."BoardID" = b."BoardID"  AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt    ON tbt.board_id = b."BoardID"  AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  ON tbt.ticket_id = tic.ticket_id   AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct   ON tic.ticket_id = ct.ticket_id
	 join users.registereduser rg On rg."RegId" = ct."assign_to"
    LEFT JOIN master.status_code_master sc  ON ct.status_id = sc.status_id
	LEFT JOIN master.tool tol ON  tol."ToolID" = ct.tool_id  
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
        AND d."DeptCode" = 'SP'
		AND (UPPER(sc.name) <> 'COMPLETED') 
		AND ct.status = 'close'
        AND tic.created_date::DATE BETWEEN from_date AND to_date
		AND (tol.is_dependency_required =false OR (tol.is_dependency_required =true AND  EXISTS (
        SELECT 1 FROM tickets.custom_tool_update_team  ut
        LEFT JOIN master.status_code_master sc_sub ON ut.status_id = sc_sub.status_id
        WHERE ut.tool_ticket_id = ct.tool_ticket_id 
        AND UPPER(sc_sub.type) = 'TOOL'
        AND UPPER(sc_sub.name) = 'COMPLETED') ) )
	AND UPPER(sc.type) = 'TOOL'
	    GROUP BY b."Name",tic.created_date::DATE,rg."RegId",
		rg."DisplayName"
	ORDER BY tic.created_date::DATE;

-- FIFTH query: Orders Grouped by other support Production with labels
    RETURN QUERY  
    SELECT  
	  COALESCE(b."Name", 'PRODUCTION')::text AS tabname,
	 
		--'' AS type,
        COALESCE(b."Name", '')::text AS type,
		 (rg."RegId")::uuid as regid,
		(rg."DisplayName")::text as displayname,
        COUNT(DISTINCT tic.ticket_id)::integer AS totalorder, 
        COUNT(ct.tool_ticket_id)::integer AS totaltool,
        0 AS ordercomplete,
        0 AS orderreceived,
        0 AS orderactive
    FROM board.board b
    INNER JOIN board.departmentboard dbd  ON b."BoardID" = dbd."BoardID"  AND dbd.is_active = 'true'
    INNER JOIN master.department d   ON dbd."DeptID" = d."DeptID"  AND d.is_active = 'true'
    LEFT JOIN board.boardstatus bsd  ON bsd."BoardID" = b."BoardID"  AND bsd.is_active = 'true'  
    LEFT JOIN tickets.ticket_board_tracker tbt    ON tbt.board_id = b."BoardID"  AND tbt.label_id = bsd."LabelID"
    LEFT JOIN tickets.ticket tic  ON tbt.ticket_id = tic.ticket_id   AND tic.is_active = 'true' 
    LEFT JOIN tickets.custom_ticket ct   ON tic.ticket_id = ct.ticket_id
	 join users.registereduser rg On rg."RegId" = ct."assign_to"
   -- LEFT JOIN master.status_code_master sc  ON ct.status_id = sc.status_id
	LEFT JOIN tickets.custom_tool_update_team  ut ON ct.tool_ticket_id = ut.tool_ticket_id
    LEFT JOIN master.status_code_master sc_sub ON ut.status_id = sc_sub.status_id
	LEFT JOIN master.tool tol ON  tol."ToolID" = ct.tool_id  
    WHERE 
        b.is_active = 'true' 
        AND b.work_space_id = 1  
       -- AND d."DeptCode" IN('AC,UT,DT')
		AND (UPPER(sc_sub.name) = 'COMPLETED') 
        AND tic.created_date::DATE BETWEEN from_date AND to_date
	AND UPPER(sc_sub.type) = 'TOOL'
	GROUP BY b."Name",
	tic.created_date::DATE,
	rg."RegId",
		rg."DisplayName"
	ORDER BY tic.created_date::DATE;
	
END;  
$$;


--
-- Name: get_department_wise_board(uuid, bigint, integer); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_department_wise_board(regid uuid, bid bigint, p_boardid integer DEFAULT NULL::integer) RETURNS TABLE(boardid integer, boardname character varying, boarddescription text, deptid integer, deptname character varying, deptcode character varying, labelid integer, labelname character varying, labeldescription text, labelposition integer, colorcode character varying, is_default boolean, is_move_state boolean, code character varying, ticket_id bigint, ticket_no character varying, name character varying, description text, ticket_position integer, due_date timestamp without time zone, order_date timestamp without time zone, assign_to uuid, ticketparticipant jsonb, updated_on text, tool_status boolean, tool_ordered_count bigint, tool_completed_count bigint, update_team_tool_completed_count bigint, divident_team_tool_completed_count bigint, analyse_team_tool_completed_count bigint, is_dependency_required text, created_date timestamp without time zone, ticket_comments_count bigint, ticket_attachments_count bigint, ticket_status character varying, ticket_status_is_paused text, ticketlabels jsonb, moved_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
/* 
bid = 0 select Particular RegId board detail
bid > 0 select Particular Id board detail
*/

BEGIN
   
     -- updatedby  ||  updateddate   || purpose
	 -- Naveen S   ||  14-03-2024    || included the new properties in created_date,ticket_comments_count,ticket_attachments_count,ticket_status,ticket_status_is_paused
	 -- Naveen S   ||  20-03-2024    || I have get the Ticket Labels
	 -- Naveen S   ||  16-04-2024    || I have get the filed in due_date,order_date,assign_to 
	 -- MalarkodiJaganathan  || 02-05-2024 || added Moved date to display the most recently moved ticket in lastinfirst.
   
IF(bid = 0)
THEN
	return query

	SELECT  b."BoardID",b."Name",b."Description",d."DeptID",d."Name",d."DeptCode" as deptcode
		   ,bsd."LabelID",bsd."Name",bsd."Description",bsd."Position" as labelposition,bsd."ColorCode",
		   bsd.is_default,bsd.is_move_state ,bsd."Code"
		   ,tic.ticket_id , tic.ticket_no,tic.name, tic.description,tic.position,tic.due_date,tic.order_date,tic.assign_to,COALESCE (( SELECT
             jsonb_agg(user_info)
        FROM (
            SELECT
                jsonb_build_object(
                    'regid', reguser."RegId"
                    ,'displayname', reguser."DisplayName"
					,'email',reguser."Email"
					,'photo',encode(reguser."Photo"::bytea, 'base64')
					
                ) AS user_info
            FROM
                users.registereduser reguser
            WHERE
                reguser."RegId" ::text = tic.added_by::text
                AND reguser.is_active = 'true'
 
            UNION
 
            SELECT
                jsonb_build_object(
                   'regid', reguser_ass."RegId"
                    ,'displayname', reguser_ass."DisplayName"
					,'email',reguser_ass."Email"
					,'photo',encode(reguser_ass."Photo"::bytea, 'base64')
                ) AS user_info
            FROM
                users.registereduser reguser_ass
            WHERE
                reguser_ass."RegId" ::text = tic.assign_to::text
                AND reguser_ass.is_active = 'true'
        ) AS subquery_alias
    ),'[]'::jsonb) AS participants
	,CONCAT(
    CASE
        WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) || ' year' || 
            CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) || ' month' || 
            CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) || ' day' || 
            CASE WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) || ' hour' || 
            CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' || 
            CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        ELSE
            'just now'
    END
   ) AS updated_on ,
   (
    SELECT
        EXISTS (
            SELECT 1
            FROM tickets.premium_ticket pt
            WHERE pt.ticket_id = tic.ticket_id
                AND UPPER(status) = 'CLOSE'
        )
        OR EXISTS (
            SELECT 1
            FROM tickets.basic_ticket bt
            WHERE bt.ticket_id = tic.ticket_id
               AND UPPER(status) = 'CLOSE'
        )
        OR EXISTS (
            SELECT 1
            FROM tickets.custom_ticket ct
            WHERE ct.ticket_id = tic.ticket_id
                AND UPPER(status) = 'CLOSE'
        ) AS tool_status   -- ADDED CODE FOR GETTING TOOL STATUS WITH COMPLETED
),
 max (
    (
        SELECT COUNT(*)
        FROM tickets.premium_ticket pt
        WHERE pt.ticket_id = tic.ticket_id           
    )
    +
    (
        SELECT COUNT(*)
        FROM tickets.basic_ticket bt
        WHERE bt.ticket_id = tic.ticket_id
    )
    +
    (
        SELECT COUNT(*)
        FROM tickets.custom_ticket ct
        WHERE ct.ticket_id = tic.ticket_id
    )
	) AS tool_ordered_count,
	 max (
    (
        SELECT COUNT(*)
        FROM tickets.premium_ticket pt
        WHERE pt.ticket_id = tic.ticket_id
            AND status_id IN (
                SELECT (status_id)
                FROM master.status_code_master sc
                WHERE upper(sc.name) = 'COMPLETED' and upper(sc.type) = 'TOOL'
            )
    )
    +
    (
        SELECT COUNT(*)
        FROM tickets.basic_ticket bt
        WHERE bt.ticket_id = tic.ticket_id
            AND status_id IN (
                SELECT status_id
                FROM master.status_code_master sc
                WHERE upper(sc.name) = 'COMPLETED' and upper(sc.type) = 'TOOL'
            )
    )
    +
    (
        SELECT COUNT(*)
        FROM tickets.custom_ticket ct
        WHERE ct.ticket_id = tic.ticket_id
            AND status_id IN (
                SELECT status_id
                FROM master.status_code_master sc
                WHERE upper(sc.name) = 'COMPLETED' and upper(sc.type) = 'TOOL'
            )
    )
	) AS tool_completed_count
