        WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' || 
            CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        ELSE
            'just now'
    END
   ) AS updated_on ,
  (
