--
-- Name: get_filter_date(text); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_filter_date(input_text text) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_date DATE;
BEGIN
     CASE input_text
        WHEN 'next_week' THEN
           -- Get the following week's Saturday (skip this week's Saturday)
            result_date :=(CURRENT_DATE + ((12 - EXTRACT(DOW FROM CURRENT_DATE)::INTEGER) % 7 + 1) * INTERVAL '1 day' + INTERVAL '7 days')+INTERVAL '1 day';
        WHEN 'next_month' THEN
            -- Get the last day of the next month
            result_date := (date_trunc('month', CURRENT_DATE) + INTERVAL '2 months' - INTERVAL '1 day')::date;
        WHEN 'next_day' THEN
            -- Get tomorrow's date
            result_date := CURRENT_DATE + INTERVAL '1 day';
        ELSE
            -- If the input doesn't match any case, raise an error
            RAISE EXCEPTION 'Invalid input: %', input_text;
    END CASE;
    RETURN result_date AS filter_date;
END;
$$;


--
-- Name: get_flow(integer); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_flow(p_flow_id integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : To Fetch the Flow(s)
      Sprint  : Rules and Movements - 6
    */

    IF p_flow_id IS NULL OR p_flow_id = 0 THEN
        -- Get all flows
        SELECT COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'flow_id', f.flow_id,
                    'name', f.flow_name,
                    'description', f.description,
                    'flow_detail', f.flow_details,
					'workflowType',f.work_flow_type,
					'workspace_id',f.workspace_id,
					'workSpaceName', wm.name,
                    'is_active', f.is_active,
                    'created_date', f.created_date,
                    'created_by', f.created_by,
					'user_info', (
						SELECT COALESCE(
							jsonb_agg(
								jsonb_build_object(
									'regId', r."RegId",
									'photo', r.photo_url,
									'name', r."DisplayName",
									'email', r."Email"
								)
							), '[]'::jsonb
						)
						FROM users.registereduser r
						WHERE r."RegId" = f.created_by::uuid
					)
                )
            ), '[]'::jsonb
        )
        INTO result
		   FROM board.flow f
			LEFT JOIN master.work_space_master wm
			  ON wm.work_space_id = f.workspace_id
			  AND wm.is_active = true
			WHERE f.is_active = true;

    ELSE
        -- Get single flow by id (still return as array for consistency)
        SELECT COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'flow_id', f.flow_id,
                    'name', f.flow_name,
                    'description', f.description,
                    'flow_detail', f.flow_details,
					'workflowType',f.work_flow_type,
					'workspace_id',f.workspace_id,
					'workSpaceName', wm.name,
                    'is_active', f.is_active,
                    'created_date', f.created_date,
                    'created_by', f.created_by,
					'user_info', (
						SELECT COALESCE(
							jsonb_agg(
								jsonb_build_object(
									'regId', r."RegId",
									'photo', r.photo_url,
									'name', r."DisplayName",
									'email', r."Email"
								)
							), '[]'::jsonb
						)
						FROM users.registereduser r
						WHERE r."RegId" = f.created_by::uuid
					)
                )
            ), '[]'::jsonb
        )
        INTO result
		FROM board.flow f
		LEFT JOIN master.work_space_master wm
		  ON wm.work_space_id = f.workspace_id
		  AND wm.is_active = true
		WHERE f.is_active = true;

    END IF;

    RETURN result;
END;
$$;


--
-- Name: get_ticket_ids_by_assignee(uuid); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_ticket_ids_by_assignee(p_assign_to uuid) RETURNS TABLE(ticket_id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY 
    SELECT ct.ticket_id 
    FROM tickets.custom_ticket ct
    JOIN tickets.custom_ticket_assignee cta ON ct.tool_ticket_id = cta.tool_ticket_id  
    WHERE ct.is_active = 'true' 
      AND cta.is_active = 'true' 
      AND cta.assignee_to = p_assign_to

    UNION ALL

    SELECT bt.ticket_id 
    FROM tickets.basic_ticket bt
    JOIN tickets.basic_ticket_assignee bta ON bt.tool_ticket_id = bta.tool_ticket_id  
    WHERE bt.is_active = 'true' 
      AND bta.is_active = 'true' 
      AND bta.assignee_to = p_assign_to

    UNION ALL

    SELECT pt.ticket_id 			
    FROM tickets.premium_ticket pt
    JOIN tickets.premium_ticket_assignee pta ON pt.tool_ticket_id = pta.tool_ticket_id 
    WHERE pt.is_active = 'true' 
      AND pta.is_active = 'true' 
      AND pta.assignee_to = p_assign_to

    UNION ALL

    SELECT tic.ticket_id 
    FROM tickets.ticket tic
    WHERE tic.assign_to = p_assign_to;
END;
$$;


--
-- Name: get_tool_counts(bigint); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_tool_counts(ticketid bigint) RETURNS TABLE(tool_ordered_count bigint, tool_completed_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH all_tickets AS (
--         SELECT pt.ticket_id, pt.status_id
--         FROM tickets.premium_ticket pt
--         WHERE pt.ticket_id = ticketid

--         UNION ALL

--         SELECT bt.ticket_id, bt.status_id
--         FROM tickets.basic_ticket bt
--         WHERE bt.ticket_id = ticketid

--         UNION ALL

--         SELECT ct.ticket_id, ct.status_id
--         FROM tickets.custom_ticket ct
--         WHERE ct.ticket_id = ticketid
	 	   
	 	   SELECT ticket_id, status_id 
	 	   FROM tickets.tool_detail 
	       WHERE ticket_id = ticketid
    ),
    completed_status AS (
        SELECT status_id
        FROM master.status_code_master sc
        WHERE UPPER(sc.name) = 'COMPLETED'
          AND UPPER(sc.type) = 'TOOL'
    )
    SELECT 
        COUNT(*) AS tool_ordered_count,
        COUNT(*) FILTER (WHERE status_id IN (SELECT status_id FROM completed_status)) AS tool_completed_count
    FROM all_tickets;
END;
$$;


--
-- Name: get_tool_flow(integer); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.get_tool_flow(p_tool_flow_id integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'tool_flow_id', tf.tool_flow_id,
            'tool_id', (
                SELECT jsonb_agg(tfi.tool_id)
                FROM board.tool_flow tfi
                WHERE tfi.tool_flow_id = tf.tool_flow_id
                  AND tfi.is_active = true
            ),
            'flow_id', tf.flow_id,
            'is_active', tf.is_active,
            'created_date', tf.created_date,
            'created_by', tf.created_by,
            'user_info', (
                SELECT COALESCE(
                    jsonb_agg(
                        jsonb_build_object(
                            'regId', r."RegId",
                            'photo', r.photo_url,
                            'name', r."DisplayName",
                            'email', r."Email"
                        )
                    ), '[]'::jsonb
                )
                FROM users.registereduser r
                WHERE r."RegId" = tf.created_by::uuid
            )
        )
    )
    INTO result
    FROM board.tool_flow tf
    WHERE (p_tool_flow_id IS NULL OR tf.tool_flow_id = p_tool_flow_id)
      AND tf.is_active = true;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


