CREATE FUNCTION board.getboard_label_detail_reguser(regid uuid, bid bigint, p_labelid integer, p_offset integer, p_limit integer) RETURNS TABLE(ticket_id bigint, ticket_no character varying, name character varying, description text, ticket_position integer, due_date timestamp without time zone, order_date timestamp without time zone, assign_to uuid, ticketparticipant jsonb, updated_on text, tool_status boolean, tool_ordered_count bigint, tool_completed_count bigint, update_team_tool_completed_count bigint, divident_team_tool_completed_count bigint, analyse_team_tool_completed_count bigint, is_dependency_required text, created_date timestamp without time zone, ticket_comments_count bigint, ticket_attachments_count bigint, ticket_status character varying, ticket_status_is_paused text, ticketlabels jsonb, moved_date timestamp without time zone, rno bigint)
    LANGUAGE plpgsql
    AS $$

BEGIN  
     -- updatedby  ||  updateddate   || purpose
	 -- Mageswari T ||  06-06-2025   || get the ticket details based on board and label

    return query

	SELECT tic.ticket_id , tic.ticket_no,tic.name, tic.description,tic.position,tic.due_date,tic.order_date,tic.assign_to
		   ,COALESCE (COALESCE ( board.get_board_participants_info(tic.added_by, tic.assign_to),'[]'::jsonb),'[]'::jsonb) AS participants
	,CONCAT(
    CASE
        WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) || ' year' || 
            CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) || ' month' || 
            CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) || ' day' || 
            CASE WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) || ' hour' || 
            CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
            EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' || 
            CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
        ELSE
            'just now'
    END
   ) AS updated_on ,
   (
    SELECT
        EXISTS (
        --     SELECT 1
        --     FROM tickets.premium_ticket pt
        --     WHERE pt.ticket_id = tic.ticket_id
        --         AND UPPER(status) = 'CLOSE'
        -- )
        -- OR EXISTS (
        --     SELECT 1
        --     FROM tickets.basic_ticket bt
        --     WHERE bt.ticket_id = tic.ticket_id
        --        AND UPPER(status) = 'CLOSE'
        -- )
        -- OR EXISTS (
            SELECT 1
            FROM tickets.tool_detail td
            WHERE td.ticket_id = tic.ticket_id
                AND UPPER(status) = 'CLOSE'
        ) AS tool_status   -- ADDED CODE FOR GETTING TOOL STATUS WITH COMPLETED
),	(SELECT gtc.tool_ordered_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
	(SELECT gtc.tool_completed_count  FROM board.get_tool_counts(tic.ticket_id) AS gtc) AS tool_completed_count
	,
		 
     tickets.get_dependency_completed_tool_count(tic.ticket_id,'UT') as update_team_tool_completed_count
	,
	tickets.get_dependency_completed_tool_count(tic.ticket_id,'DT')AS divident_team_tool_completed_count
	,		 
   tickets.get_dependency_completed_tool_count(tic.ticket_id,'AC')AS analyse_team_tool_completed_count
	,
	
   ( SELECT 
        CASE 
            WHEN EXISTS (
            --     SELECT 1
            --     FROM tickets.premium_tool_update_team put
            --     JOIN tickets.premium_ticket pt ON pt.tool_ticket_id = put.tool_ticket_id
            --     WHERE put.is_active = 'true' AND pt.ticket_id = tic.ticket_id
            -- ) THEN 'true'
            -- WHEN EXISTS (
            --     SELECT 1
            --     FROM tickets.basic_tool_update_team pbt
            --     JOIN tickets.basic_ticket bt ON bt.tool_ticket_id = pbt.tool_ticket_id
            --     WHERE pbt.is_active = 'true' AND bt.ticket_id = tic.ticket_id
            -- ) THEN 'true'
            -- WHEN EXISTS (
                SELECT 1
                FROM tickets.tool_board_log bl
                JOIN tickets.tool_detail td ON td.tool_ticket_id = bl.tool_ticket_id
                WHERE bl.is_active = 'true' AND td.ticket_id = tic.ticket_id
            ) THEN 'true'
            ELSE 'false'
        END AS is_dependency_required
     ),
      tic.created_date,  --included the new property in created_date
	  (
        SELECT COUNT(*)
        FROM tickets.ticket_comments ct
        WHERE ct.ticket_id = tic.ticket_id
      ) as ticket_comments_count,    --included the new property in ticket_comments_count
	  (
        SELECT COUNT(*)
        FROM tickets.ticket_attachment ta
        WHERE ta.ticket_id =tic.ticket_id
      ) as ticket_attachments_count, --included the new property in ticket_attachments_count
	  (
        SELECT scm.name
        FROM master.status_code_master scm
        WHERE scm.status_id =tic.status_id and is_active='true' and upper(scm.type) = 'TICKET'
      ) as ticket_status,   --included the new property in ticket_status
	  (
        SELECT 
		  CASE WHEN upper(scm.name) = 'PAUSE'  THEN 'true'
		  ELSE
			  'false'
		  END
        FROM master.status_code_master scm
        WHERE scm.status_id =tic.status_id and is_active='true' and upper(scm.type) = 'TICKET'
      ) as ticket_status_is_paused ,--included the new property in ticket_status_is_paused
	  COALESCE (( SELECT
             jsonb_agg(
                jsonb_build_object(
                    'labelid', tl."LabelId"
                    ,'name', ml."Name"
					,'colorcode',ml.colorcode					
                )
			 )
            FROM tickets.ticket_labels tl
			JOIN master.label ml ON tl."LabelId" = ml."LabelId"
            WHERE
                tl.ticket_id = tic.ticket_id
                AND ml.is_active = 'true'
    ),'[]'::jsonb) AS ticketlabels  -- i have get the ticketLabels data
	,tbt.moved_date --added Moved date to display the most recently moved ticket in lastinfirst.
	,ROW_NUMBER() OVER (PARTITION BY bsd."LabelID" ORDER BY tic.ticket_id DESC) as rn
        FROM board.board b 
		INNER JOIN board.boardstatus bsd ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'
	    left join tickets.ticket_board_tracker tbt on tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
	    INNER JOIN tickets.ticket tic ON tbt.ticket_id = tic.ticket_id  AND tic.is_active = 'true'
		WHERE b."BoardID" = bid and bsd."LabelID"=p_labelid AND b.is_active = 'true'  
		 GROUP BY bsd."LabelID",b."BoardID",tic.ticket_id,tbt.moved_date
       ORDER BY tbt.moved_date DESC 
		LIMIT p_limit
		OFFSET (p_offset) * p_limit;
END;

$$;


--
-- Name: getboarddetail_filter(uuid, bigint, text, uuid, boolean, boolean, boolean, boolean, boolean, integer[]); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.getboarddetail_filter(regid uuid, bid bigint, search_ticket_name text DEFAULT NULL::text, search_assign_to uuid DEFAULT NULL::uuid, filter_no_due_date boolean DEFAULT false, filter_over_due_date boolean DEFAULT false, filter_due_date_next_day boolean DEFAULT false, filter_due_date_next_week boolean DEFAULT false, filter_due_date_next_month boolean DEFAULT false, labelids integer[] DEFAULT NULL::integer[]) RETURNS TABLE(boardid integer, boardname character varying, boarddescription text, deptid integer, deptname character varying, deptcode character varying, labelid integer, labelname character varying, labeldescription text, labelposition integer, colorcode character varying, is_default boolean, is_move_state boolean, code character varying, ticket_id bigint, ticket_no character varying, name character varying, description text, ticket_position integer, due_date timestamp without time zone, order_date timestamp without time zone, assign_to uuid, ticketparticipant jsonb, updated_on text, tool_status boolean, tool_ordered_count bigint, tool_completed_count bigint, update_team_tool_completed_count bigint, divident_team_tool_completed_count bigint, analyse_team_tool_completed_count bigint, is_dependency_required text, created_date timestamp without time zone, ticket_comments_count bigint, ticket_attachments_count bigint, ticket_status character varying, ticket_status_is_paused text, ticketlabels jsonb, moved_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_role TEXT;
    filter_date DATE DEFAULT NULL;
BEGIN
    IF regid IS NOT NULL THEN
        -- Retrieve the user's role
        SELECT INTO user_role users.getuserrolename(regid);
        
        -- Check the user's role and the bid value
       /* IF user_role NOT IN ('Lead', 'Member') AND bid = 0 THEN
            SELECT "BoardID" INTO bid FROM board.board WHERE "Name" = 'ON BOARDING';
        END IF;*/
    END IF;
	 -- Dynamically adjust the input parameters
    IF filter_due_date_next_week THEN
        filter_due_date_next_day := false;
    END IF;

    IF filter_due_date_next_month THEN
        filter_due_date_next_day := false;
        filter_due_date_next_week := false;
    END IF;
    -- Setting filter_date based on filter_due_date_next_week
    IF filter_due_date_next_week THEN 
        filter_date := board.get_filter_date('next_week');
    END IF;
	IF filter_due_date_next_month THEN 
        filter_date := board.get_filter_date('next_month');
    END IF;
	

    -- Log filter_date for debugging purposes
    RAISE NOTICE 'Variable value: %', filter_date;
	RAISE NOTICE 'search_ticket_name: %',search_ticket_name; 
	RAISE NOTICE 'filter_over_due_date: %',filter_over_due_date;
	RAISE NOTICE 'filter_due_date_next_day: %',filter_due_date_next_day;
	RAISE NOTICE 'filter_due_date_next_month: %',filter_due_date_next_month;
    IF bid > 0 THEN
        RETURN QUERY
        WITH labelsdetails AS (
            SELECT tl.ticket_id, jsonb_agg(
                jsonb_build_object(
                    'labelid', tl."LabelId",
                    'name', ml."Name",
                    'colorcode', ml.colorcode
                )
            ) AS ticketlabels
            FROM tickets.ticket_labels tl 
            JOIN master.label ml ON tl."LabelId" = ml."LabelId"
            GROUP BY tl.ticket_id
        )
        SELECT
            b."BoardID",
            b."Name",
            b."Description",
            d."DeptID",
            d."Name",
            d."DeptCode" AS deptcode,
            bsd."LabelID",
            bsd."Name",
            bsd."Description",
            bsd."Position" AS labelposition,
            bsd."ColorCode",
            bsd.is_default,
            bsd.is_move_state,
            bsd."Code",
            tic.ticket_id,
            tic.ticket_no,
            tic.name,
            tic.description,
            tic.position,
            tic.due_date,
            tic.order_date,
            tic.assign_to,
            COALESCE(board.get_board_participants_info(tic.added_by, tic.assign_to), '[]'::jsonb) AS participants,
            CONCAT(
                CASE
                    WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) || ' year' ||
                        CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) || ' month' ||
                        CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) || ' day' ||
                        CASE WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) || ' hour' ||
                        CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' ||
                        CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    ELSE 'just now'
                END
            ) AS updated_on,
            (
--                 SELECT
--                     EXISTS (
--                         SELECT 1
--                         FROM tickets.premium_ticket pt
--                         WHERE pt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.basic_ticket bt
--                         WHERE bt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.custom_ticket ct
--                         WHERE ct.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     ) AS tool_status
				SELECT 
					EXISTS (
						SELECT 1
						FROM tickets.tool_detail ct
						WHERE ct.ticket_id = tic.ticket_id
							AND UPPER(status) = 'CLOSE'
					) AS tool_status
            ),
            (SELECT gtc.tool_ordered_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            (SELECT gtc.tool_completed_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'UT') AS update_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'DT') AS divident_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'AC') AS analyse_team_tool_completed_count,
            (
--                 SELECT
--                     CASE
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.premium_tool_update_team put
--                             JOIN tickets.premium_ticket pt ON pt.tool_ticket_id = put.tool_ticket_id
--                             WHERE put.is_active = 'true' AND pt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.basic_tool_update_team pbt
--                             JOIN tickets.basic_ticket bt ON bt.tool_ticket_id = pbt.tool_ticket_id
--                             WHERE pbt.is_active = 'true' AND bt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.custom_tool_update_team cbt
--                             JOIN tickets.custom_ticket ct ON ct.tool_ticket_id = cbt.tool_ticket_id
--                             WHERE cbt.is_active = 'true' AND ct.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         ELSE 'false'
--                     END AS is_dependency_required
				SELECT 
					(SELECT 
						CASE 
							WHEN td.is_updateteam_dependency = true 
							  OR td.is_analyse_dependency = true 
							  OR td.is_tsr_dependency = true 
							THEN true 
							ELSE false 
						END AS dependency
					FROM tickets.tool_detail td
					JOIN master.tool t ON t."ToolID" = td.tool_id
					WHERE 
						td.is_active = true
						AND td.ticket_id = tic.ticket_id) AS is_dependency_required	
            ),
            tic.created_date,
            (
                SELECT COUNT(ct.ticket_id)
                FROM tickets.ticket_comments ct
                WHERE ct.ticket_id = tic.ticket_id
            ) AS ticket_comments_count,
            (
                SELECT COUNT(ta.ticket_id)
                FROM tickets.ticket_attachment ta
                WHERE ta.ticket_id = tic.ticket_id
            ) AS ticket_attachments_count,
            (
                SELECT scm.name
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status,
            (
                SELECT
                    CASE WHEN upper(scm.name) = 'PAUSE' THEN 'true' ELSE 'false' END
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status_is_paused,
            COALESCE(ld.ticketlabels, '[]'::jsonb) AS ticketlabels,
            tbt.moved_date             
        FROM
            board.board b
            INNER JOIN board.departmentboard db ON b."BoardID" = db."BoardID" AND db.is_active = 'true'
            INNER JOIN master.department d ON db."DeptID" = d."DeptID" AND d.is_active = 'true'
            LEFT JOIN board.boardstatus bsd ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'
            LEFT JOIN tickets.ticket_board_tracker tbt ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
            LEFT JOIN tickets.ticket tic ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true'
            LEFT JOIN labelsdetails ld ON ld.ticket_id = tic.ticket_id 
        WHERE
           b."BoardID" = bid AND b.is_active = 'true' 
		 AND (
                tic.ticket_id is null
                OR (
                    (search_ticket_name IS NULL OR upper(tic.name) ILIKE '%' || upper(search_ticket_name) || '%')
                    AND (search_assign_to IS NULL OR tic.assign_to = search_assign_to)
                    AND (  filter_over_due_date=false OR tic.due_date < CURRENT_TIMESTAMP::timestamp)
					 AND (filter_no_due_date=false OR DATE(tic.due_date) is null)
                    AND (  filter_due_date_next_day =false OR DATE(tic.due_date) = CURRENT_DATE + INTERVAL '1 day')
                    AND (  filter_due_date_next_week =false  OR tic.due_date BETWEEN CURRENT_TIMESTAMP::timestamp AND filter_date)
                    AND (  filter_due_date_next_month =false  OR tic.due_date BETWEEN CURRENT_TIMESTAMP::timestamp  AND filter_date)
                    AND (labelids IS NULL OR tic.ticket_id IN (
                            SELECT tl.ticket_id 
                            FROM tickets.ticket_labels tl 
                            WHERE tl."LabelId" = ANY(labelids)
                        ))
                )
            )  
        ORDER BY
            b."BoardID" ASC,
            bsd."Position" ASC,
            tic.ticket_id DESC;
    END IF;
END;
$$;


--
-- Name: getboarddetail_reguser(uuid, bigint); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.getboarddetail_reguser(regid uuid, bid bigint) RETURNS TABLE(boardid integer, boardname character varying, boarddescription text, deptid integer, deptname character varying, deptcode character varying, labelid integer, totalticketscount bigint, labelname character varying, labeldescription text, labelposition integer, colorcode character varying, is_default boolean, is_move_state boolean, code character varying, ticket_id bigint, ticket_no character varying, name character varying, description text, ticket_position integer, due_date timestamp without time zone, order_date timestamp without time zone, assign_to uuid, ticketparticipant jsonb, updated_on text, tool_status boolean, tool_ordered_count bigint, tool_completed_count bigint, update_team_tool_completed_count bigint, divident_team_tool_completed_count bigint, analyse_team_tool_completed_count bigint, is_dependency_required text, created_date timestamp without time zone, ticket_comments_count bigint, ticket_attachments_count bigint, ticket_status character varying, ticket_status_is_paused text, ticketlabels jsonb, moved_date timestamp without time zone, rn bigint)
    LANGUAGE plpgsql
    AS $$
/* 
bid = 0 select Particular RegId board detail
bid > 0 select Particular Id board detail
*/
DECLARE
    user_role TEXT;
BEGIN
    IF regid IS NOT NULL THEN
        -- Retrieve the user's role
        SELECT INTO user_role users.getuserrolename(regid);        
        -- Check the user's role and the bid value
       IF user_role NOT IN ('Lead', 'Member') AND bid = 0 THEN
	       	select "BoardID" into bid from board.board where "Name"='ON BOARDING';
           -- bid := 108;
        END IF;
    END IF;

    -- Naveen S   ||  14-03-2024    || included the new properties in created_date, ticket_comments_count, ticket_attachments_count, ticket_status, ticket_status_is_paused
    -- Naveen S   ||  20-03-2024    || I have get the Ticket Labels
    -- Naveen S   ||  16-04-2024    || I have get the field in due_date, order_date, assign_to 
    -- Malarkodi Jaganathan || 02-05-2024 || added Moved date to display the most recently moved ticket in lastinfirst.
    -- Karuppaiah || 23-05-2024 || changes done for performance
	-- Naveen/Karuppaiah || 17-06-2024 || We have added the totalticketcount field
	-- Aravindhan B || 06-06-2025 || PLG - New table changes added and remove the old tables.
	
    IF bid = 0 THEN
        RETURN QUERY
		
		WITH BoardDetails AS (
        SELECT
            b."BoardID",
            b."Name",
            b."Description",
            d."DeptID",
            d."Name",
            d."DeptCode" as deptcode,
            bsd."LabelID",
			(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID")) AS totalticketscount,
            bsd."Name",
            bsd."Description",
            bsd."Position" as labelposition,
            bsd."ColorCode",
            bsd.is_default,
            bsd.is_move_state,
            bsd."Code",
            tic.ticket_id,
            tic.ticket_no,
            tic.name,
            tic.description,
            tic.position,
            tic.due_date,
            tic.order_date,
            tic.assign_to,
            COALESCE(board.get_board_participants_info(tic.added_by, tic.assign_to), '[]'::jsonb) AS participants,
            CONCAT(
                CASE
                    WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) || ' year' ||
                        CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) || ' month' ||
                        CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) || ' day' ||
                        CASE WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) || ' hour' ||
                        CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' ||
                        CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    ELSE
                        'just now'
                END
            ) AS updated_on,
            (
--                 SELECT
--                     EXISTS (
--                         SELECT 1
--                         FROM tickets.premium_ticket pt
--                         WHERE pt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.basic_ticket bt
--                         WHERE bt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.custom_ticket ct
--                         WHERE ct.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     ) AS tool_status
				SELECT 
					EXISTS (
						SELECT 1
						FROM tickets.tool_detail ct
						WHERE ct.ticket_id = tic.ticket_id
							AND UPPER(status) = 'CLOSE'
					) AS tool_status
            ),
            (SELECT gtc.tool_ordered_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            (SELECT gtc.tool_completed_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'UT') AS update_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'DT') AS divident_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'AC') AS analyse_team_tool_completed_count,
            (
--                 SELECT
--                     CASE
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.premium_tool_update_team put
--                             JOIN tickets.premium_ticket pt ON pt.tool_ticket_id = put.tool_ticket_id
--                             WHERE put.is_active = 'true' AND pt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.basic_tool_update_team pbt
--                             JOIN tickets.basic_ticket bt ON bt.tool_ticket_id = pbt.tool_ticket_id
--                             WHERE pbt.is_active = 'true' AND bt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.custom_tool_update_team cbt
--                             JOIN tickets.custom_ticket ct ON ct.tool_ticket_id = cbt.tool_ticket_id
--                             WHERE cbt.is_active = 'true' AND ct.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         ELSE 'false'
--                     END AS is_dependency_required
				SELECT 
					(SELECT 
						CASE 
							WHEN t.is_updateteam_dependency = true 
							  OR t.is_analyse_dependency = true 
							  OR t.is_tsr_dependency = true 
							THEN true 
							ELSE false 
						END AS dependency
					FROM tickets.tool_detail td
					JOIN master.tool t ON t."ToolID" = td.tool_id
					WHERE 
						td.is_active = true
						AND td.ticket_id = tic.ticket_id) AS is_dependency_required			
            ),
            tic.created_date,
            (
                SELECT COUNT(ct.ticket_id)
                FROM tickets.ticket_comments ct
                WHERE ct.ticket_id = tic.ticket_id
            ) AS ticket_comments_count,
            (
                SELECT COUNT(ta.ticket_id)
                FROM tickets.ticket_attachment ta
                WHERE ta.ticket_id = tic.ticket_id
            ) AS ticket_attachments_count,
            (
                SELECT scm.name
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status,
            (
                SELECT
                    CASE WHEN upper(scm.name) = 'PAUSE' THEN 'true' ELSE 'false' END
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status_is_paused,
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'labelid', tl."LabelId",
                            'name', ml."Name",
                            'colorcode', ml.colorcode
                        )
                    )
                    FROM tickets.ticket_labels tl
                    JOIN master.label ml ON tl."LabelId" = ml."LabelId"
                    WHERE tl.ticket_id = tic.ticket_id AND ml.is_active = 'true'
                ), '[]'::jsonb
            ) AS ticketlabels,
            tbt.moved_date,
            ROW_NUMBER() OVER (PARTITION BY bsd."LabelID" ORDER BY tic.ticket_id DESC) AS rn
        FROM
            board.board b
            INNER JOIN board.departmentboard dbd ON b."BoardID" = dbd."BoardID" AND dbd.is_active = 'true'
            INNER JOIN master.department d ON dbd."DeptID" = d."DeptID" AND d.is_active = 'true'
            LEFT JOIN users.userdepartment ud ON ud."DeptID" = d."DeptID" AND ud.is_active = 'true'
            LEFT JOIN board.boardstatus bsd ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  --change inner to left join
			LEFT JOIN tickets.ticket_board_tracker tbt ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
            LEFT JOIN tickets.ticket tic ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true'
        WHERE
            b.is_active = 'true'
            AND (
                ud."RegId" = regid
                OR (SELECT "rolename" FROM users.getuserrolename(regid)) = 'SuperAdmin'
                OR b."Name" = 'TRELLO BOARD'
            )
        GROUP BY
            bsd."LabelID",
            b."BoardID",
            d."DeptID",
            tic.ticket_id,
            tbt.moved_date
        ORDER BY
            b."BoardID" ASC,
            bsd."Position" ASC,
            tbt.moved_date DESC )
			SELECT
				*
			FROM
				BoardDetails Brd
			WHERE
				Brd.rn <= 10;
    END IF;

    IF bid > 0 THEN
        RETURN QUERY
	    WITH BoardDetails AS (
        SELECT
            b."BoardID",
            b."Name",
            b."Description",
            d."DeptID",
            d."Name",
            d."DeptCode" AS deptcode,
            bsd."LabelID",
			(tickets.get_ticket_count_by_labelid(bsd."LabelID",b."BoardID")) AS totalticketscount,
            bsd."Name",
            bsd."Description",
            bsd."Position" AS labelposition,
            bsd."ColorCode",
            bsd.is_default,
            bsd.is_move_state,
            bsd."Code",
            tic.ticket_id,
            tic.ticket_no,
            tic.name,
            tic.description,
            tic.position,
            tic.due_date,
            tic.order_date,
            tic.assign_to,
            COALESCE(board.get_board_participants_info(tic.added_by, tic.assign_to), '[]'::jsonb) AS participants,
            CONCAT(
                CASE
                    WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) || ' year' ||
                        CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) || ' month' ||
                        CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) || ' day' ||
                        CASE WHEN EXTRACT(DAY FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) || ' hour' ||
                        CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 0 THEN
                        EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) || ' minute' ||
                        CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), tic.created_date)) > 1 THEN 's' ELSE '' END || ' ago '
                    ELSE
                        'just now'
                END
            ) AS updated_on,
            (
--                 SELECT
--                     EXISTS (
--                         SELECT 1
--                         FROM tickets.premium_ticket pt
--                         WHERE pt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.basic_ticket bt
--                         WHERE bt.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     )
--                     OR EXISTS (
--                         SELECT 1
--                         FROM tickets.custom_ticket ct
--                         WHERE ct.ticket_id = tic.ticket_id
--                             AND UPPER(status) = 'CLOSE'
--                     ) AS tool_status
				SELECT 
					EXISTS (
						SELECT 1
						FROM tickets.tool_detail ct
						WHERE ct.ticket_id = tic.ticket_id
							AND UPPER(status) = 'CLOSE'
					) AS tool_status
            ),
            (SELECT gtc.tool_ordered_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            (SELECT gtc.tool_completed_count FROM board.get_tool_counts(tic.ticket_id) AS gtc),
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'UT') AS update_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'DT') AS divident_team_tool_completed_count,
            tickets.get_dependency_completed_tool_count(tic.ticket_id, 'AC') AS analyse_team_tool_completed_count,
            (
--                 SELECT
--                     CASE
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.premium_tool_update_team put
--                             JOIN tickets.premium_ticket pt ON pt.tool_ticket_id = put.tool_ticket_id
--                             WHERE put.is_active = 'true' AND pt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.basic_tool_update_team pbt
--                             JOIN tickets.basic_ticket bt ON bt.tool_ticket_id = pbt.tool_ticket_id
--                             WHERE pbt.is_active = 'true' AND bt.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         WHEN EXISTS (
--                             SELECT 1
--                             FROM tickets.custom_tool_update_team cbt
--                             JOIN tickets.custom_ticket ct ON ct.tool_ticket_id = cbt.tool_ticket_id
--                             WHERE cbt.is_active = 'true' AND ct.ticket_id = tic.ticket_id
--                         ) THEN 'true'
--                         ELSE 'false'
--                     END AS is_dependency_required
				SELECT 
					(SELECT 
						CASE 
							WHEN t.is_updateteam_dependency = true 
							  OR t.is_analyse_dependency = true 
							  OR t.is_tsr_dependency = true 
							THEN true 
							ELSE false 
						END AS dependency
					FROM tickets.tool_detail td
					JOIN master.tool t ON t."ToolID" = td.tool_id
					WHERE 
						td.is_active = true
						AND td.ticket_id = tic.ticket_id) AS is_dependency_required	
            ),
            tic.created_date,
            (
                SELECT COUNT(ct.ticket_id)
                FROM tickets.ticket_comments ct
                WHERE ct.ticket_id = tic.ticket_id
            ) AS ticket_comments_count,
            (
                SELECT COUNT(ta.ticket_id)
                FROM tickets.ticket_attachment ta
                WHERE ta.ticket_id = tic.ticket_id
            ) AS ticket_attachments_count,
            (
                SELECT scm.name
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status,
            (
                SELECT
                    CASE WHEN upper(scm.name) = 'PAUSE' THEN 'true' ELSE 'false' END
                FROM master.status_code_master scm
                WHERE scm.status_id = tic.status_id AND is_active = 'true' AND upper(scm.type) = 'TICKET'
            ) AS ticket_status_is_paused,
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'labelid', tl."LabelId",
                            'name', ml."Name",
                            'colorcode', ml.colorcode
                        )
                    )
                    FROM tickets.ticket_labels tl
                    JOIN master.label ml ON tl."LabelId" = ml."LabelId"
                    WHERE tl.ticket_id = tic.ticket_id AND ml.is_active = 'true'
                ), '[]'::jsonb
            ) AS ticketlabels,
            tbt.moved_date,
            ROW_NUMBER() OVER (PARTITION BY bsd."LabelID" ORDER BY tic.ticket_id DESC) AS rn
        FROM
            board.board b
            INNER JOIN board.departmentboard db
			        ON b."BoardID" = db."BoardID" AND db.is_active = 'true'
            INNER JOIN master.department d ON db."DeptID" = d."DeptID" AND d.is_active = 'true'
            LEFT JOIN board.boardstatus bsd ON bsd."BoardID" = b."BoardID" AND bsd.is_active = 'true'  --change inner to left join
            LEFT JOIN tickets.ticket_board_tracker tbt ON tbt.board_id = b."BoardID" AND tbt.label_id = bsd."LabelID"
            LEFT JOIN tickets.ticket tic ON tbt.ticket_id = tic.ticket_id AND tic.is_active = 'true' --change inner to left join
        WHERE
            b."BoardID" = bid AND b.is_active = 'true'
        ORDER BY
            b."BoardID" ASC,
            bsd."Position" ASC,
            tbt.moved_date DESC  )
			SELECT
				*
			FROM
				BoardDetails Brd
			WHERE
				Brd.rn <= 10;
    END IF;

END;

$$;


--
-- Name: rearrange_boardstatus_position(integer, integer, integer, character varying); Type: FUNCTION; Schema: board; Owner: -
--

CREATE FUNCTION board.rearrange_boardstatus_position(changepos integer, currrentpos integer, boardid integer, activity character varying) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE rowaffected integer;
begin
	IF activity = 'add' THEN
		UPDATE board.boardstatus SET "Position" = "Position" + 1 WHERE "Position" >= changepos
		AND "BoardID" = boardid;
	ELSEIF activity = 'delete' THEN
		UPDATE board.boardstatus SET "Position" = "Position" - 1 WHERE "Position" > changepos
		AND "BoardID" = boardid;
	ELSEIF activity = 'leftmove' THEN
		UPDATE board.boardstatus SET "Position" = "Position"+ 1 WHERE "Position" >= changepos 
		AND "Position" < currrentpos 
		AND "BoardID" = boardid;
	ELSEIF activity = 'rightmove' THEN
		UPDATE board.boardstatus SET "Position" = "Position"- 1 WHERE "Position" > currrentpos 
		AND "Position" <= changepos 
		AND "BoardID" = boardid;
	END IF;
	get diagnostics rowaffected = ROW_COUNT;
	 IF(rowaffected>0)
      THEN
		  return query select 'Postion rearranged sucessfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'Postion rearranged failed' as message,'false'::boolean as status;
	 END IF;
end;
$$;


--
-- Name: updateboarddeptdetails(bigint, character varying, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: board; Owner: -
--

CREATE PROCEDURE board.updateboarddeptdetails(IN iboardid bigint, IN iboardname character varying, IN idescription character varying, IN iby character varying, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
begin

IF EXISTS (SELECT "Name" FROM board.board WHERE LOWER("Name") =  LOWER(TRIM(iboardname)) and ("BoardID"!=iboardid OR "BoardID"=iboardid) and is_active='false' )
THEN

            message = 'Board already exists in disabled mode.';
			status ='false';
			return;
END IF;

IF EXISTS (SELECT "Name" FROM board.board WHERE  "BoardID"=iboardid and is_active='false' )

THEN
            message = 'Board already exists in disabled mode.';
			status ='false';
			return;
END IF;

IF NOT EXISTS (SELECT "BoardID" FROM board.board WHERE "BoardID"=iboardid)
THEN  
            message = 'Board not exists.';
			status ='false';
			return;

END IF;

IF EXISTS (SELECT "Name" FROM board.board WHERE LOWER("Name") =  LOWER(TRIM(iboardname)) and"BoardID"!=iboardid)

THEN
            message = 'Board already exists.';
			status ='false';
			return;
END IF;
IF EXISTS (SELECT "Name" FROM board.board WHERE LOWER("Name") =  LOWER(TRIM(iboardname)) and "BoardID"=iboardid and is_active ='false' )
THEN
          message = 'Board couldnot update,already exists in disabled mode';
		   status ='false';
END IF;
IF NOT EXISTS (SELECT "Name" FROM board.board WHERE LOWER("Name") =  LOWER(TRIM(iboardname)) and "BoardID"=iboardid and is_active ='false' )
THEN
UPDATE board.board SET
		   "Name" = iboardname,
		   "Description" = idescription,
		   last_updated_date = CURRENT_DATE,
		   updated_by = iby
		   WHERE "BoardID" = iboardid
		   AND is_active = 'true';
		   message = 'Board Updated Successfully';
		   status ='true';
ELSE
message = 'Board couldnot update,already exists in disabled mode';
		   status ='false';
END IF;
EXCEPTION  WHEN OTHERS
THEN
   message = 'Error occured during the Opeartion';
    status = 'false';
END;
$$;


--
-- Name: insert_customer_order_id(integer, text, text, bigint, text); Type: FUNCTION; Schema: customers; Owner: -
--

CREATE FUNCTION customers.insert_customer_order_id(customerrefid integer, orderno text, createdby text, ticketid bigint, toolcenterlink text DEFAULT NULL::text) RETURNS TABLE(message text, status boolean, customerorderid text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offected integer := 0;
	in_customer_id bigint;
	result_rows_affected INTEGER := 0;
BEGIN

		-- Created by  || Craeted Date  || Purpose
		-- Malarkodi Jaganathan || 27-03-2024  || Insert the customer order id
		-- Malarkodi Jaganathan || 30-05-2024  || Insert the Customer tool center link

-- Get the Customer id 

SELECT customer_id INTO in_customer_id FROM customers.customer
WHERE customer_ref_id = customerrefid AND is_active ='true';

IF toolcenterlink IS NOT NULL THEN
  
  IF EXISTS (SELECT customer_id FROM customers.customer
  WHERE customer_ref_id = customerrefid AND is_active ='true' AND (tool_center_link IS NULL OR tool_center_link <> '' )) THEN
  
      UPDATE customers.customer 
      SET tool_center_link = toolcenterlink,
         updated_by = createdby,
         last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	   WHERE  customer_ref_id = customerrefid AND is_active ='true';
  END IF;
END IF;

  IF EXISTS (SELECT customer_id FROM customers.customer
  WHERE customer_ref_id = customerrefid AND is_active ='true') THEN
		--Insert the data into customer_order table
		INSERT INTO customers.customer_order
		(
			 customer_id
			,orderno
			,ticket_id
			,is_active
			,created_date
			,created_by
		)
		VALUES
		(
			in_customer_id
			,orderno
			,ticketid
			,'true'
			,current_timestamp AT TIME ZONE 'UTC'
			,createdby :: UUID
         );
		 
		 -- After in sert the data customer_order table need to update the order no in ticket table also
		 UPDATE  tickets.ticket SET 
		 order_id = orderno,
		 updated_by = current_timestamp AT TIME ZONE 'UTC'
		 WHERE ticket_id = ticketid AND is_active = true;
		 
      get diagnostics offected = ROW_COUNT; 
	  
	  	 -- Call function for insert history details
        result_rows_affected := tickets.add_history_details(
            in_ticket_id => ticketid,
            in_content => CONCAT('Created the orderid','-',orderno),
            in_user_id => createdby :: UUID,
            in_created_by => createdby :: UUID,
            in_created_date => current_timestamp AT TIME ZONE 'UTC',
            in_history_type => 'customer orderid'
        );
	  	  
  ELSE
    return query select 'Customer detail is not available and Order id added failed' as message,'true'::boolean as status,NULL :: text as customerorderid;
  END IF ;
	
	IF(offected>0)
    THEN
		  return query select 'Order id created and added successfully' as message,'true'::boolean as status,orderno as customerorderid ;
    ELSE 
	      return query select 'Order id added failed' as message,'false'::boolean as status, NULL :: text as customerorderid;
    END IF;
	
	-- Handle the exception
	EXCEPTION
    WHEN others THEN
     
        ROLLBACK;
        message := 'Error inserting data';
        status := false; 
END;
$$;


--
-- Name: add_update_knowledgebase(integer, character varying, character varying, boolean, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_update_knowledgebase(IN p_id integer, IN p_name character varying, IN p_description character varying, IN p_is_helpdesk boolean, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_name_exists boolean;
    v_context text;
    v_rowcount integer := 0;
    v_code text;
    v_is_helpdesk boolean;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Create or update knowledge base master
*/

    IF p_name IS NULL OR btrim(p_name) = '' THEN
        message := 'Knowledge base name is required.';
        status := 'false';
        RETURN;
    END IF;

    v_is_helpdesk := COALESCE(p_is_helpdesk, false);
    v_code := UPPER(REPLACE(btrim(p_name), ' ', ''));

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_master kb
        WHERE lower(kb.name) = lower(btrim(p_name))
          AND kb.is_active = true
          AND (p_id IS NULL OR p_id = 0 OR kb.id <> p_id)
    )
    INTO v_name_exists;

    IF v_name_exists THEN
        message := format('Knowledge base with name "%s" already exists.', btrim(p_name));
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_master kb
        WHERE kb.id = p_id
          AND kb.is_active = true
    )
    INTO v_exists;

    IF v_exists THEN
        UPDATE knowledgebase.knowledgebase_master
        SET name = btrim(p_name),
            description = NULLIF(btrim(p_description), ''),
            code = v_code,
            is_helpdesk = v_is_helpdesk,
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE id = p_id
          AND is_active = true;

        new_p_id := p_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Knowledge base updated successfully.';
            status := 'true';
        ELSE
            message := 'Knowledge base update failed.';
            status := 'false';
        END IF;
    ELSE
        INSERT INTO knowledgebase.knowledgebase_master
        (
            name,
            description,
            code,
            is_helpdesk,
            is_active,
            created_date,
            created_by
        )
        VALUES
        (
            btrim(p_name),
            NULLIF(btrim(p_description), ''),
            v_code,
            v_is_helpdesk,
            true,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            p_created_by
        )
        RETURNING id INTO new_p_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Knowledge base created successfully.';
            status := 'true';
        ELSE
            message := 'Knowledge base creation failed.';
            status := 'false';
        END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_update_knowledgebase',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_id,
                p_name,
                p_description,
                p_is_helpdesk,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_update_knowledgebase_attachment(integer, integer, uuid, integer, character varying, character varying, character varying, character varying, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_update_knowledgebase_attachment(IN p_id integer, IN p_knowledge_base_id integer, IN p_attachment_refid uuid, IN p_folder_id integer, IN p_document_name character varying, IN p_description character varying, IN p_file_type character varying, IN p_file_name character varying, IN p_file_url text, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_folder_ok boolean;
    v_kb_ok boolean;
    v_rowcount integer := 0;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Create or update a knowledge base attachment (volume path in file_url)
*/

    IF p_document_name IS NULL OR btrim(p_document_name) = '' THEN
        message := 'Document name is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_attachments a
        WHERE a.attachment_id = p_id
          AND a.is_active = true
    )
    INTO v_exists;

    IF v_exists THEN
        UPDATE knowledgebase.knowledgebase_attachments
        SET document_name = btrim(p_document_name),
            description = NULLIF(btrim(p_description), ''),
            file_type = NULLIF(btrim(p_file_type), ''),
            file_name = NULLIF(btrim(p_file_name), ''),
            file_url = COALESCE(NULLIF(btrim(p_file_url), ''), file_url),
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE attachment_id = p_id
          AND is_active = true;

        new_p_id := p_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Attachment updated successfully.';
            status := 'true';
        ELSE
            message := 'Attachment update failed.';
            status := 'false';
        END IF;
    ELSE
        IF p_knowledge_base_id IS NULL OR p_knowledge_base_id <= 0 THEN
            message := 'Knowledge base ID is required.';
            status := 'false';
            RETURN;
        END IF;

        IF p_folder_id IS NULL OR p_folder_id <= 0 THEN
            message := 'Folder ID is required.';
            status := 'false';
            RETURN;
        END IF;

        IF p_attachment_refid IS NULL THEN
            message := 'Attachment ref id is required.';
            status := 'false';
            RETURN;
        END IF;

        IF p_file_url IS NULL OR btrim(p_file_url) = '' THEN
            message := 'File path is required.';
            status := 'false';
            RETURN;
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.knowledgebase_master kb
            WHERE kb.id = p_knowledge_base_id
              AND kb.is_active = true
        )
        INTO v_kb_ok;

        IF NOT v_kb_ok THEN
            message := 'Knowledge base not found.';
            status := 'false';
            RETURN;
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.knowledgebase_folders f
            WHERE f.folder_id = p_folder_id
              AND f.knowledge_base_id = p_knowledge_base_id
              AND f.is_active = true
        )
        INTO v_folder_ok;

        IF NOT v_folder_ok THEN
            message := 'Folder not found for the given knowledge base.';
            status := 'false';
            RETURN;
        END IF;

        INSERT INTO knowledgebase.knowledgebase_attachments
        (
            attachment_refid,
            folder_id,
            document_name,
            description,
            file_type,
            file_name,
            file_url,
            is_active,
            created_date,
            created_by
        )
        VALUES
        (
            p_attachment_refid,
            p_folder_id,
            btrim(p_document_name),
            NULLIF(btrim(p_description), ''),
            NULLIF(btrim(p_file_type), ''),
            NULLIF(btrim(p_file_name), ''),
            btrim(p_file_url),
            true,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            p_created_by
        )
        RETURNING attachment_id INTO new_p_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Attachment created successfully.';
            status := 'true';
        ELSE
            message := 'Attachment creation failed.';
            status := 'false';
        END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_update_knowledgebase_attachment',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_id,
                p_knowledge_base_id,
                p_attachment_refid,
                p_folder_id,
                p_document_name,
                p_description,
                p_file_type,
                p_file_name,
                p_file_url,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_update_knowledgebase_folder(integer, integer, integer, character varying, character varying, text, boolean, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_update_knowledgebase_folder(IN p_id integer, IN p_knowledge_base_id integer, IN p_parent_id integer, IN p_name character varying, IN p_description character varying, IN p_created_by text, IN p_is_manual boolean DEFAULT NULL::boolean, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_name_exists boolean;
    v_kb_exists boolean;
    v_parent_kb_id integer;
    v_knowledge_base_id integer;
    v_parent_id integer;
    v_is_manual boolean;
    v_context text;
    v_rowcount integer := 0;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Create or update a knowledge base folder
*/

    IF p_name IS NULL OR btrim(p_name) = '' THEN
        message := 'Folder name is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = p_id
          AND f.is_active = true
    )
    INTO v_exists;

    IF v_exists THEN
        SELECT f.knowledge_base_id, f.parent_folder_id, f.is_manual
        INTO v_knowledge_base_id, v_parent_id, v_is_manual
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = p_id
          AND f.is_active = true;

        v_is_manual := COALESCE(p_is_manual, v_is_manual, false);
    ELSE
        v_knowledge_base_id := p_knowledge_base_id;
        v_parent_id := NULLIF(p_parent_id, 0);
        v_is_manual := COALESCE(p_is_manual, false);

        IF v_knowledge_base_id IS NULL OR v_knowledge_base_id <= 0 THEN
            message := 'Knowledge base ID is required.';
            status := 'false';
            RETURN;
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.knowledgebase_master kb
            WHERE kb.id = v_knowledge_base_id
              AND kb.is_active = true
        )
        INTO v_kb_exists;

        IF NOT v_kb_exists THEN
            message := 'Knowledge base not found.';
            status := 'false';
            RETURN;
        END IF;

        IF v_parent_id IS NOT NULL THEN
            SELECT pf.knowledge_base_id
            INTO v_parent_kb_id
            FROM knowledgebase.knowledgebase_folders pf
            WHERE pf.folder_id = v_parent_id
              AND pf.is_active = true;

            IF v_parent_kb_id IS NULL THEN
                message := 'Parent folder not found.';
                status := 'false';
                RETURN;
            END IF;

            IF v_parent_kb_id <> v_knowledge_base_id THEN
                message := 'Parent folder must belong to the same knowledge base.';
                status := 'false';
                RETURN;
            END IF;
        END IF;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.knowledge_base_id = v_knowledge_base_id
          AND COALESCE(f.parent_folder_id, 0) = COALESCE(v_parent_id, 0)
          AND lower(f.name) = lower(btrim(p_name))
          AND f.is_active = true
          AND (p_id IS NULL OR p_id = 0 OR f.folder_id <> p_id)
    )
    INTO v_name_exists;

    IF v_name_exists THEN
        message := format('Folder with name "%s" already exists.', btrim(p_name));
        status := 'false';
        RETURN;
    END IF;

    IF v_exists THEN
        UPDATE knowledgebase.knowledgebase_folders
        SET name = btrim(p_name),
            description = NULLIF(btrim(p_description), ''),
            is_manual = v_is_manual,
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE folder_id = p_id
          AND is_active = true;

        new_p_id := p_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Folder updated successfully.';
            status := 'true';
        ELSE
            message := 'Folder update failed.';
            status := 'false';
        END IF;
    ELSE
        -- Keep identity sequence in sync (manual/seed inserts can leave it behind)
        PERFORM setval(
            pg_get_serial_sequence('knowledgebase.knowledgebase_folders', 'folder_id'),
            COALESCE((SELECT MAX(folder_id) FROM knowledgebase.knowledgebase_folders), 1),
            true
        );

        INSERT INTO knowledgebase.knowledgebase_folders
        (
            knowledge_base_id,
            parent_folder_id,
            name,
            description,
            is_manual,
            is_active,
            created_date,
            created_by
        )
        VALUES
        (
            v_knowledge_base_id,
            v_parent_id,
            btrim(p_name),
            NULLIF(btrim(p_description), ''),
            v_is_manual,
            true,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            p_created_by
        )
        RETURNING folder_id INTO new_p_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Folder created successfully.';
            status := 'true';
        ELSE
            message := 'Folder creation failed.';
            status := 'false';
        END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_update_knowledgebase_folder',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_id,
                p_knowledge_base_id,
                p_parent_id,
                p_name,
                p_description,
                p_is_manual,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_update_knowledgebase_issue(uuid, integer, integer, integer, text, text, text, text, jsonb, text, text, jsonb, jsonb, jsonb, jsonb, jsonb, text, text, timestamp without time zone, text, text, integer, uuid, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_update_knowledgebase_issue(IN p_issue_refid uuid, IN p_knowledge_base_id integer, IN p_folder_id integer, IN p_parent_folder_id integer, IN p_source_type text, IN p_issue_type text, IN p_issue_subtype text, IN p_issue_title text, IN p_issue_tags jsonb, IN p_issue_description text, IN p_root_cause text, IN p_resolution_steps jsonb, IN p_xml_configs jsonb, IN p_related_tickets jsonb, IN p_symptoms jsonb, IN p_verification jsonb, IN p_process_workflow text, IN p_freshdesk_ticket text, IN p_last_synced timestamp without time zone, IN p_vector_processing_status text, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT new_issue_refid uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_issue_id integer;
    v_existing_json jsonb;
    v_existing_name text;
    v_existing_freshdesk text;
    v_existing_synced timestamp without time zone;
    v_existing_vector text;
    v_existing_kb_id integer;
    v_existing_folder_id integer;
    v_existing_parent_id integer;
    v_existing_source text;
    v_is_update boolean := false;
    v_is_freshdesk_locked boolean := false;
    v_kb_id integer;
    v_folder_id integer;
    v_parent_id integer;
    v_issue_title text;
    v_issue_type text;
    v_issue_subtype text;
    v_issue_tags jsonb;
    v_symptoms jsonb;
    v_verification jsonb;
    v_process_workflow text;
    v_source_type text;
    v_freshdesk text;
    v_last_synced timestamp without time zone;
    v_vector_status text;
    v_issue_json jsonb;
    v_steps jsonb;
    v_xml jsonb;
    v_tickets jsonb;
    v_kb_ok boolean;
    v_folder_ok boolean;
    v_parent_ok boolean;
    v_rowcount integer := 0;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Create or update a knowledge base issue
            issueTags replaces documentType (ISSUETAGS master type)
*/

    IF p_issue_refid IS NOT NULL AND p_issue_refid <> '00000000-0000-0000-0000-000000000000'::uuid THEN
        SELECT
            i.issue_id,
            i.issue_json,
            i.issue_name,
            i.freshdesk_ticket,
            i.last_synced,
            i.vector_processing_status,
            i.knowledge_base_id,
            i.folder_id,
            i.parent_folder_id
        INTO
            v_issue_id,
            v_existing_json,
            v_existing_name,
            v_existing_freshdesk,
            v_existing_synced,
            v_existing_vector,
            v_existing_kb_id,
            v_existing_folder_id,
            v_existing_parent_id
        FROM knowledgebase.knowledgebase_issues i
        WHERE i.issue_refid = p_issue_refid
          AND i.is_active = true;

        v_is_update := v_issue_id IS NOT NULL;

        IF NOT v_is_update THEN
            message := 'Issue not found.';
            status := 'false';
            RETURN;
        END IF;

        v_existing_source := lower(COALESCE(v_existing_json->>'sourceType', 'manual'));
        v_is_freshdesk_locked := (v_existing_source = 'freshdesk');
        new_issue_refid := p_issue_refid;
    ELSE
        new_issue_refid := gen_random_uuid();
    END IF;

    -- Normalize string arrays (NULL input = keep existing on update)
    IF p_issue_tags IS NULL THEN
        v_issue_tags := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(to_jsonb(btrim(value)))
                FROM jsonb_array_elements_text(COALESCE(p_issue_tags, '[]'::jsonb)) value
                WHERE btrim(value) <> ''
            ),
            '[]'::jsonb
        )
        INTO v_issue_tags;
    END IF;

    IF p_symptoms IS NULL THEN
        v_symptoms := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(to_jsonb(btrim(value)))
                FROM jsonb_array_elements_text(COALESCE(p_symptoms, '[]'::jsonb)) value
                WHERE btrim(value) <> ''
            ),
            '[]'::jsonb
        )
        INTO v_symptoms;
    END IF;

    IF p_verification IS NULL THEN
        v_verification := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(to_jsonb(btrim(value)))
                FROM jsonb_array_elements_text(COALESCE(p_verification, '[]'::jsonb)) value
                WHERE btrim(value) <> ''
            ),
            '[]'::jsonb
        )
        INTO v_verification;
    END IF;

    IF p_resolution_steps IS NULL THEN
        v_steps := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(to_jsonb(btrim(value)))
                FROM jsonb_array_elements_text(COALESCE(p_resolution_steps, '[]'::jsonb)) value
                WHERE btrim(value) <> ''
            ),
            '[]'::jsonb
        )
        INTO v_steps;
    END IF;

    IF p_xml_configs IS NULL THEN
        v_xml := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_strip_nulls(
                        jsonb_build_object(
                            'tagName', NULLIF(btrim(COALESCE(elem->>'tagName', elem->>'tag_name', '')), ''),
                            'description', NULLIF(btrim(COALESCE(elem->>'description', '')), ''),
                            'example', NULLIF(btrim(COALESCE(elem->>'example', elem->>'exampleUsage', elem->>'example_usage', '')), '')
                        )
                    )
                )
                FROM jsonb_array_elements(COALESCE(p_xml_configs, '[]'::jsonb)) elem
                WHERE COALESCE(btrim(elem->>'tagName'), btrim(elem->>'tag_name'), '') <> ''
                   OR COALESCE(btrim(elem->>'description'), '') <> ''
                   OR COALESCE(btrim(elem->>'example'), btrim(elem->>'exampleUsage'), btrim(elem->>'example_usage'), '') <> ''
            ),
            '[]'::jsonb
        )
        INTO v_xml;
    END IF;

    IF p_related_tickets IS NULL THEN
        v_tickets := NULL;
    ELSE
        SELECT COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_strip_nulls(
                        jsonb_build_object(
                            'ticketId', NULLIF(btrim(COALESCE(elem->>'ticketId', elem->>'ticket_id', '')), ''),
                            'resolvedDate', NULLIF(btrim(COALESCE(elem->>'resolvedDate', elem->>'resolved_date', '')), ''),
                            'team', NULLIF(btrim(COALESCE(elem->>'team', '')), ''),
                            'status', NULLIF(btrim(COALESCE(elem->>'status', '')), '')
                        )
                    )
                )
                FROM jsonb_array_elements(COALESCE(p_related_tickets, '[]'::jsonb)) elem
                WHERE COALESCE(btrim(elem->>'ticketId'), btrim(elem->>'ticket_id'), '') <> ''
            ),
            '[]'::jsonb
        )
        INTO v_tickets;
    END IF;

    IF v_is_freshdesk_locked THEN
        v_issue_title := v_existing_name;
        v_issue_type := COALESCE(v_existing_json->>'issueType', '');
        v_issue_subtype := COALESCE(v_existing_json->>'issueSubtype', '');
        v_issue_tags := knowledgebase.kb_issue_tags_json(v_existing_json);
        v_source_type := 'freshdesk';
        v_freshdesk := v_existing_freshdesk;
        v_last_synced := v_existing_synced;
        v_kb_id := v_existing_kb_id;
        v_folder_id := COALESCE(NULLIF(p_folder_id, 0), v_existing_folder_id);
        v_parent_id := CASE
            WHEN p_parent_folder_id IS NULL THEN v_existing_parent_id
            WHEN p_parent_folder_id = 0 THEN NULL
            ELSE p_parent_folder_id
        END;
        v_vector_status := COALESCE(NULLIF(btrim(p_vector_processing_status), ''), v_existing_vector, 'Pending');
        v_process_workflow := COALESCE(
            NULLIF(btrim(COALESCE(p_process_workflow, '')), ''),
            v_existing_json->>'processWorkflow',
            ''
        );

        v_issue_json := jsonb_build_object(
            'issueType', v_issue_type,
            'issueSubtype', v_issue_subtype,
            'issueTags', v_issue_tags,
            'issueDescription', COALESCE(p_issue_description, v_existing_json->>'issueDescription', ''),
            'symptoms', COALESCE(v_symptoms, v_existing_json->'symptoms', '[]'::jsonb),
            'verification', COALESCE(v_verification, v_existing_json->'verification', '[]'::jsonb),
            'processWorkflow', v_process_workflow,
            'rootCause', COALESCE(p_root_cause, v_existing_json->>'rootCause', ''),
            'resolutionSteps', COALESCE(v_steps, v_existing_json->'resolutionSteps', '[]'::jsonb),
            'xmlConfigs', COALESCE(v_xml, v_existing_json->'xmlConfigs', '[]'::jsonb),
            'relatedTickets', COALESCE(v_tickets, v_existing_json->'relatedTickets', '[]'::jsonb),
            'sourceType', 'freshdesk'
        );
    ELSE
        v_issue_title := NULLIF(btrim(COALESCE(p_issue_title, '')), '');
        v_issue_type := NULLIF(btrim(COALESCE(p_issue_type, '')), '');
        v_issue_subtype := NULLIF(btrim(COALESCE(p_issue_subtype, '')), '');

        IF v_is_update THEN
            v_source_type := lower(COALESCE(NULLIF(btrim(p_source_type), ''), v_existing_source, 'manual'));
            v_kb_id := COALESCE(NULLIF(p_knowledge_base_id, 0), v_existing_kb_id);
            v_folder_id := COALESCE(NULLIF(p_folder_id, 0), v_existing_folder_id);
            v_parent_id := CASE
                WHEN p_parent_folder_id IS NULL THEN v_existing_parent_id
                WHEN p_parent_folder_id = 0 THEN NULL
                ELSE p_parent_folder_id
            END;
            v_freshdesk := COALESCE(NULLIF(btrim(p_freshdesk_ticket), ''), v_existing_freshdesk);
            v_last_synced := COALESCE(p_last_synced, v_existing_synced);
            v_vector_status := COALESCE(NULLIF(btrim(p_vector_processing_status), ''), v_existing_vector, 'Pending');
            v_issue_title := COALESCE(v_issue_title, v_existing_name);
            v_issue_type := COALESCE(v_issue_type, NULLIF(v_existing_json->>'issueType', ''));
            v_issue_subtype := COALESCE(v_issue_subtype, NULLIF(v_existing_json->>'issueSubtype', ''));
            v_issue_tags := COALESCE(v_issue_tags, knowledgebase.kb_issue_tags_json(v_existing_json));
            v_symptoms := COALESCE(v_symptoms, v_existing_json->'symptoms', '[]'::jsonb);
            v_verification := COALESCE(v_verification, v_existing_json->'verification', '[]'::jsonb);
            v_process_workflow := COALESCE(
                NULLIF(btrim(COALESCE(p_process_workflow, '')), ''),
                v_existing_json->>'processWorkflow',
                ''
            );
            v_steps := COALESCE(v_steps, v_existing_json->'resolutionSteps', '[]'::jsonb);
            v_xml := COALESCE(v_xml, v_existing_json->'xmlConfigs', '[]'::jsonb);
            v_tickets := COALESCE(v_tickets, v_existing_json->'relatedTickets', '[]'::jsonb);
        ELSE
            v_source_type := 'manual';
            v_kb_id := p_knowledge_base_id;
            v_folder_id := p_folder_id;
            v_parent_id := NULLIF(p_parent_folder_id, 0);
            v_freshdesk := NULLIF(btrim(p_freshdesk_ticket), '');
            v_last_synced := p_last_synced;
            v_vector_status := COALESCE(NULLIF(btrim(p_vector_processing_status), ''), 'Pending');
            v_issue_tags := COALESCE(v_issue_tags, '[]'::jsonb);
            v_symptoms := COALESCE(v_symptoms, '[]'::jsonb);
            v_verification := COALESCE(v_verification, '[]'::jsonb);
            v_process_workflow := COALESCE(p_process_workflow, '');
            v_steps := COALESCE(v_steps, '[]'::jsonb);
            v_xml := COALESCE(v_xml, '[]'::jsonb);
            v_tickets := COALESCE(v_tickets, '[]'::jsonb);
        END IF;

        IF v_source_type NOT IN ('manual', 'freshdesk') THEN
            v_source_type := 'manual';
        END IF;

        IF v_issue_title IS NULL THEN
            message := 'Issue title is required.';
            status := 'false';
            RETURN;
        END IF;

        IF v_issue_type IS NULL OR v_issue_subtype IS NULL
           OR v_issue_tags IS NULL OR jsonb_array_length(v_issue_tags) = 0 THEN
            message := 'Issue type, subtype, and issue tags are required.';
            status := 'false';
            RETURN;
        END IF;

        v_issue_json := jsonb_build_object(
            'issueType', v_issue_type,
            'issueSubtype', v_issue_subtype,
            'issueTags', v_issue_tags,
            'issueDescription', COALESCE(p_issue_description, CASE WHEN v_is_update THEN v_existing_json->>'issueDescription' ELSE '' END, ''),
            'symptoms', v_symptoms,
            'verification', v_verification,
            'processWorkflow', COALESCE(v_process_workflow, ''),
            'rootCause', COALESCE(p_root_cause, CASE WHEN v_is_update THEN v_existing_json->>'rootCause' ELSE '' END, ''),
            'resolutionSteps', v_steps,
            'xmlConfigs', v_xml,
            'relatedTickets', v_tickets,
            'sourceType', v_source_type
        );
    END IF;

    IF v_vector_status NOT IN ('Pending', 'Processing', 'Completed', 'Failed') THEN
        message := 'Invalid vector processing status.';
        status := 'false';
        RETURN;
    END IF;

    IF v_is_update THEN
        UPDATE knowledgebase.knowledgebase_issues
        SET knowledge_base_id = v_kb_id,
            folder_id = v_folder_id,
            parent_folder_id = v_parent_id,
            freshdesk_ticket = v_freshdesk,
            issue_name = v_issue_title,
            issue_json = v_issue_json,
            last_synced = v_last_synced,
            vector_processing_status = v_vector_status,
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE issue_id = v_issue_id
          AND is_active = true;

        new_p_id := v_issue_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'updated';
            status := 'true';
        ELSE
            message := 'Issue update failed.';
            status := 'false';
        END IF;
        RETURN;
    END IF;

    IF v_kb_id IS NULL OR v_kb_id <= 0 THEN
        message := 'Knowledge base ID is required.';
        status := 'false';
        RETURN;
    END IF;

    IF v_folder_id IS NULL OR v_folder_id <= 0 THEN
        message := 'Folder ID is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_master kb
        WHERE kb.id = v_kb_id
          AND kb.is_active = true
    )
    INTO v_kb_ok;

    IF NOT v_kb_ok THEN
        message := 'Knowledge base not found.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = v_folder_id
          AND f.knowledge_base_id = v_kb_id
          AND f.is_active = true
    )
    INTO v_folder_ok;

    IF NOT v_folder_ok THEN
        message := 'Folder not found for the given knowledge base.';
        status := 'false';
        RETURN;
    END IF;

    IF v_parent_id IS NOT NULL AND v_parent_id > 0 THEN
        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.knowledgebase_folders f
            WHERE f.folder_id = v_parent_id
              AND f.knowledge_base_id = v_kb_id
              AND f.is_active = true
        )
        INTO v_parent_ok;

        IF NOT v_parent_ok THEN
            message := 'Parent folder not found for the given knowledge base.';
            status := 'false';
            RETURN;
        END IF;
    END IF;

    -- Keep identity sequence in sync (manual/seed inserts can leave it behind)
    PERFORM setval(
        pg_get_serial_sequence('knowledgebase.knowledgebase_issues', 'issue_id'),
        COALESCE((SELECT MAX(issue_id) FROM knowledgebase.knowledgebase_issues), 1),
        true
    );

    INSERT INTO knowledgebase.knowledgebase_issues
    (
        issue_refid,
        knowledge_base_id,
        folder_id,
        parent_folder_id,
        freshdesk_ticket,
        issue_name,
        issue_json,
        last_synced,
        vector_processing_status,
        is_active,
        created_date,
        created_by
    )
    VALUES
    (
        new_issue_refid,
        v_kb_id,
        v_folder_id,
        v_parent_id,
        v_freshdesk,
        v_issue_title,
        v_issue_json,
        v_last_synced,
        v_vector_status,
        true,
        CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
        p_created_by
    )
    RETURNING issue_id INTO new_p_id;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'created';
        status := 'true';
    ELSE
        message := 'Issue creation failed.';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_update_knowledgebase_issue',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_issue_refid,
                p_knowledge_base_id,
                p_folder_id,
                p_parent_folder_id,
                p_source_type,
                p_issue_title,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_update_knowledgebase_link(integer, integer, character varying, character varying, character varying, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_update_knowledgebase_link(IN p_id integer, IN p_folder_id integer, IN p_name character varying, IN p_url character varying, IN p_description character varying, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_folder_exists boolean;
    v_rowcount integer := 0;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Create or update a knowledge base link
*/

    IF p_name IS NULL OR btrim(p_name) = '' THEN
        message := 'Link name is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_links l
        WHERE l.link_id = p_id
          AND l.is_active = true
    )
    INTO v_exists;

    IF v_exists THEN
        IF p_url IS NULL OR btrim(p_url) = '' THEN
            message := 'Link URL is required.';
            status := 'false';
            RETURN;
        END IF;

        UPDATE knowledgebase.knowledgebase_links
        SET name = btrim(p_name),
            url = btrim(p_url),
            description = NULLIF(btrim(p_description), ''),
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE link_id = p_id
          AND is_active = true;

        new_p_id := p_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Link updated successfully.';
            status := 'true';
        ELSE
            message := 'Link update failed.';
            status := 'false';
        END IF;
    ELSE
        IF p_folder_id IS NULL OR p_folder_id <= 0 THEN
            message := 'Folder ID is required.';
            status := 'false';
            RETURN;
        END IF;

        IF p_url IS NULL OR btrim(p_url) = '' THEN
            message := 'Link URL is required.';
            status := 'false';
            RETURN;
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.knowledgebase_folders f
            WHERE f.folder_id = p_folder_id
              AND f.is_active = true
        )
        INTO v_folder_exists;

        IF NOT v_folder_exists THEN
            message := 'Folder not found.';
            status := 'false';
            RETURN;
        END IF;

        -- Keep identity sequence in sync (manual/seed inserts can leave it behind)
        PERFORM setval(
            pg_get_serial_sequence('knowledgebase.knowledgebase_links', 'link_id'),
            GREATEST(
                COALESCE((SELECT MAX(link_id) FROM knowledgebase.knowledgebase_links), 1),
                1
            ),
            true
        );

        INSERT INTO knowledgebase.knowledgebase_links
        (
            folder_id,
            name,
            url,
            description,
            is_active,
            created_date,
            created_by
        )
        VALUES
        (
            p_folder_id,
            btrim(p_name),
            btrim(p_url),
            NULLIF(btrim(p_description), ''),
            true,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            p_created_by
        )
        RETURNING link_id INTO new_p_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Link created successfully.';
            status := 'true';
        ELSE
            message := 'Link creation failed.';
            status := 'false';
        END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_update_knowledgebase_link',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_id,
                p_folder_id,
                p_name,
                p_url,
                p_description,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_user_knowledgebase_permission(integer, uuid, integer, integer, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.add_user_knowledgebase_permission(IN p_user_knowledgebase_permission_id integer, IN p_user_id uuid, IN p_knowledge_base_id integer DEFAULT NULL::integer, IN p_can_edit integer DEFAULT NULL::integer, IN p_created_by text DEFAULT NULL::text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_duplicate boolean;
    v_rowcount integer := 0;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Add, update, or remove user knowledge base permission
*/

    IF p_user_id IS NULL THEN
        message := 'User id is required.';
        status := 'false';
        RETURN;
    END IF;

    -- Remove
    IF COALESCE(p_user_knowledgebase_permission_id, 0) > 0 AND p_knowledge_base_id IS NULL THEN
        UPDATE knowledgebase.user_knowledgebase_permission
        SET is_active = false,
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE user_knowledgebase_permission_id = p_user_knowledgebase_permission_id
          AND reg_id = p_user_id
          AND is_active = true;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;
        new_p_id := p_user_knowledgebase_permission_id;

        IF v_rowcount > 0 THEN
            message := 'Knowledge base permission removed successfully.';
            status := 'true';
        ELSE
            message := 'Knowledge base permission not found.';
            status := 'false';
        END IF;
        RETURN;
    END IF;

    IF p_knowledge_base_id IS NULL OR p_knowledge_base_id <= 0 THEN
        message := 'Knowledge base id is required.';
        status := 'false';
        RETURN;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_master kb
        WHERE kb.id = p_knowledge_base_id
          AND kb.is_active = true
    ) THEN
        message := 'Knowledge base not found.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.user_knowledgebase_permission ukp
        WHERE ukp.reg_id = p_user_id
          AND ukp.knowledge_base_id = p_knowledge_base_id
          AND ukp.is_active = true
          AND (COALESCE(p_user_knowledgebase_permission_id, 0) = 0
               OR ukp.user_knowledgebase_permission_id <> p_user_knowledgebase_permission_id)
    )
    INTO v_duplicate;

    IF v_duplicate THEN
        message := 'Knowledge base permission already exists for the given user.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.user_knowledgebase_permission ukp
        WHERE ukp.user_knowledgebase_permission_id = p_user_knowledgebase_permission_id
          AND ukp.is_active = true
    )
    INTO v_exists;

    -- Update
    IF v_exists THEN
        UPDATE knowledgebase.user_knowledgebase_permission
        SET knowledge_base_id = p_knowledge_base_id,
            action_id = COALESCE(p_can_edit, 0),
            updated_by = p_created_by,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
        WHERE user_knowledgebase_permission_id = p_user_knowledgebase_permission_id
          AND is_active = true;

        new_p_id := p_user_knowledgebase_permission_id;
        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Knowledge base permission updated successfully.';
            status := 'true';
        ELSE
            message := 'Knowledge base permission update failed.';
            status := 'false';
        END IF;
        RETURN;
    END IF;

    -- Add
    INSERT INTO knowledgebase.user_knowledgebase_permission
    (
        reg_id,
        knowledge_base_id,
        action_id,
        is_active,
        created_date,
        created_by
    )
    VALUES
    (
        p_user_id,
        p_knowledge_base_id,
        COALESCE(p_can_edit, 0),
        true,
        CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
        p_created_by
    )
    RETURNING user_knowledgebase_permission_id INTO new_p_id;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'Knowledge base permission added successfully.';
        status := 'true';
    ELSE
        message := 'Knowledge base permission creation failed.';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.add_user_knowledgebase_permission',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_user_knowledgebase_permission_id,
                p_user_id,
                p_knowledge_base_id,
                p_can_edit,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: delete_knowledgebase_attachment(uuid, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.delete_knowledgebase_attachment(IN p_attachment_refid uuid, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rowcount integer := 0;
    v_attachment_id integer;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Soft delete a knowledge base attachment by attachment_refid
*/

    IF p_attachment_refid IS NULL THEN
        message := 'Valid attachment ref id is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT a.attachment_id
    INTO v_attachment_id
    FROM knowledgebase.knowledgebase_attachments a
    WHERE a.attachment_refid = p_attachment_refid
      AND a.is_active = true;

    IF v_attachment_id IS NULL THEN
        message := 'Attachment not found.';
        status := 'false';
        RETURN;
    END IF;

    UPDATE knowledgebase.knowledgebase_attachments
    SET is_active = false,
        updated_by = p_created_by,
        last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
    WHERE attachment_id = v_attachment_id
      AND is_active = true;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;
    new_p_id := v_attachment_id;

    IF v_rowcount > 0 THEN
        message := 'Attachment deleted successfully.';
        status := 'true';
    ELSE
        message := 'Attachment not found.';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.delete_knowledgebase_attachment',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(p_attachment_refid, p_created_by))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: delete_knowledgebase_folder(integer, text, integer, character varying, character varying); Type: PROCEDURE; Schema: knowledgebase; Owner: -
--

CREATE PROCEDURE knowledgebase.delete_knowledgebase_folder(IN p_id integer, IN p_created_by text, INOUT new_p_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_rowcount integer := 0;
    v_context text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Soft delete a knowledge base folder and nested folders
*/

    IF p_id IS NULL OR p_id <= 0 THEN
        message := 'Valid folder ID is required.';
        status := 'false';
        RETURN;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = p_id
          AND f.is_active = true
    )
    INTO v_exists;

    IF NOT v_exists THEN
        message := 'Folder not found.';
        status := 'false';
        RETURN;
    END IF;

    WITH RECURSIVE descendants AS (
        SELECT f.folder_id
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = p_id
          AND f.is_active = true
        UNION ALL
        SELECT c.folder_id
        FROM knowledgebase.knowledgebase_folders c
        INNER JOIN descendants d ON c.parent_folder_id = d.folder_id
        WHERE c.is_active = true
    )
    UPDATE knowledgebase.knowledgebase_folders f
    SET is_active = false,
        updated_by = p_created_by,
        last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
    FROM descendants d
    WHERE f.folder_id = d.folder_id
      AND f.is_active = true;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;
    new_p_id := p_id;

    IF v_rowcount > 0 THEN
        message := 'Folder deleted successfully.';
        status := 'true';
    ELSE
        message := 'Folder delete failed.';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'knowledgebase.delete_knowledgebase_folder',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_id,
                p_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


