--
-- Name: get_folder_tree(integer, integer, uuid); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_folder_tree(p_folder_id integer DEFAULT NULL::integer, p_knowledge_base_id integer DEFAULT NULL::integer, p_reg_id uuid DEFAULT NULL::uuid) RETURNS TABLE(folder_id integer, parent_folder_id integer, knowledge_base_id integer, name text, description text, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- ============================================================
    -- CASE 1:
    -- folder_id IS NULL AND knowledge_base_id IS NULL
    -- Return ALL folders
    -- ============================================================
    IF p_folder_id IS NULL AND p_knowledge_base_id IS NULL THEN

        RETURN QUERY
        SELECT
            f.folder_id,
            f.parent_folder_id,
            f.knowledge_base_id,
            f.name::TEXT,
            f.description::TEXT,
            0::INTEGER AS level
        FROM knowledgebase.knowledgebase_folders f
	    JOIN knowledgebase.user_knowledgebase_permission kp ON kp.knowledge_base_id = f.knowledge_base_id AND kp.is_active = true
        WHERE f.is_active = TRUE AND kp.reg_id = p_reg_id
        ORDER BY f.folder_id;

        RETURN;
    END IF;


    -- ============================================================
    -- CASE 2:
    -- folder_id IS NULL AND knowledge_base_id IS NOT NULL
    -- Return ALL folders for knowledge_base_id
    -- ============================================================
    IF p_folder_id IS NULL AND p_knowledge_base_id IS NOT NULL THEN

        RETURN QUERY
        SELECT
            f.folder_id,
            f.parent_folder_id,
            f.knowledge_base_id,
            f.name::TEXT,
            f.description::TEXT,
            0::INTEGER AS level
        FROM knowledgebase.knowledgebase_folders f
        WHERE
            f.knowledge_base_id = p_knowledge_base_id
            AND f.is_active = TRUE
        ORDER BY f.folder_id;

        RETURN;
    END IF;


    -- ============================================================
    -- CASE 3:
    -- folder_id IS NOT NULL
    -- Return child folders recursively
    -- ============================================================
    RETURN QUERY

    WITH RECURSIVE folder_tree AS (

        -- Direct children
        SELECT
            f.folder_id,
            f.parent_folder_id,
            f.knowledge_base_id,
            f.name::TEXT AS name,
            f.description::TEXT AS description,
            0::INTEGER AS level
        FROM knowledgebase.knowledgebase_folders f
        WHERE
            f.parent_folder_id = p_folder_id
            AND (
                p_knowledge_base_id IS NULL
                OR f.knowledge_base_id = p_knowledge_base_id
            )
            AND f.is_active = TRUE

        UNION ALL

        -- Nested children
        SELECT
            f.folder_id,
            f.parent_folder_id,
            f.knowledge_base_id,
            f.name::TEXT AS name,
            f.description::TEXT AS description,
            (ft.level + 1)::INTEGER AS level
        FROM knowledgebase.knowledgebase_folders f
        INNER JOIN folder_tree ft
            ON f.parent_folder_id = ft.folder_id
        WHERE
            (
                p_knowledge_base_id IS NULL
                OR f.knowledge_base_id = p_knowledge_base_id
            )
            AND f.is_active = TRUE
    )

    SELECT
        ft.folder_id,
        ft.parent_folder_id,
        ft.knowledge_base_id,
        ft.name,
        ft.description,
        ft.level
    FROM folder_tree ft
    ORDER BY ft.level, ft.folder_id;

END;
$$;


--
-- Name: get_knowledgebase(); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase() RETURNS TABLE(id integer, name character varying, description character varying, code text, is_helpdesk boolean, "createdDate" timestamp without time zone, "createdBy" jsonb)
    LANGUAGE plpgsql
    AS $_$
BEGIN
/*
  Author  : Mubarak Basha
  Details : Get all knowledge base master records
*/
    RETURN QUERY
    SELECT
        kb.id,
        kb.name,
        kb.description,
        kb.code,
        kb.is_helpdesk,
        kb.created_date AS "createdDate",
        COALESCE(
            (
                SELECT jsonb_build_array(
                    jsonb_build_object(
                        'name',  ru."DisplayName",
                        'photo', ru.photo_url,
                        'regId', ru."RegId"
                    )
                )
                FROM users.registereduser ru
                WHERE kb.created_by IS NOT NULL
                  AND kb.created_by ~* '^[0-9a-fA-F-]{36}$'
                  AND ru."RegId" = kb.created_by::uuid
            ),
            '[]'::jsonb
        ) AS "createdBy"
    FROM knowledgebase.knowledgebase_master kb
    WHERE kb.is_active = true
    ORDER BY kb.id;
END;
$_$;


