-- Name: get_knowledgebase_attachment_by_id(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_attachment_by_id(p_attachment_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
