      AND a.is_active = true;
$$;


--
-- Name: get_knowledgebase_folder_by_id(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_folder_by_id(p_folder_id integer) RETURNS TABLE(id integer, "knowledgeBaseId" integer, "parentId" integer, name character varying, description character varying, "createdBy" jsonb, "createdDate" timestamp without time zone, "itemCount" integer, "recentItems" jsonb)
    LANGUAGE plpgsql ROWS 1
    AS $_$
BEGIN
/*
  Author  : Mubarak Basha
  Details : Get a single knowledge base folder
*/
    RETURN QUERY
    SELECT
        f.folder_id,
        f.knowledge_base_id,
        f.parent_folder_id,
        f.name,
        f.description,
        COALESCE(
            (
                SELECT jsonb_build_array(
                    jsonb_build_object(
                        'name', ru."DisplayName",
                        'displayName', ru."DisplayName",
                        'photo', COALESCE(ru.photo_url, '')
                    )
                )
                FROM users.registereduser ru
                WHERE f.created_by IS NOT NULL
                  AND f.created_by ~* '^[0-9a-fA-F-]{36}$'
                  AND ru."RegId" = f.created_by::uuid
            ),
            '[]'::jsonb
        ) AS "createdBy",
        f.created_date AS "createdDate",
        (
            SELECT COUNT(*)::integer
            FROM knowledgebase.knowledgebase_folders c
            WHERE c.parent_folder_id = f.folder_id
              AND c.is_active = true
        ) AS "itemCount",
        '[]'::jsonb AS "recentItems"
    FROM knowledgebase.knowledgebase_folders f
    WHERE f.folder_id = p_folder_id
      AND f.is_active = true;
END;
$_$;


--
-- Name: get_knowledgebase_folder_items(integer, integer, integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_folder_items(p_folder_id integer, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS TABLE("folderId" integer, "itemCount" integer, items jsonb, page integer, "pageSize" integer, total integer, "hasMore" boolean)
    LANGUAGE plpgsql ROWS 1
    AS $$
DECLARE
    v_page integer;
    v_page_size integer;
    v_exists boolean;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Get paginated mixed contents of a knowledge base folder
*/
    v_page := GREATEST(COALESCE(p_page, 1), 1);
    v_page_size := GREATEST(COALESCE(NULLIF(p_page_size, 0), 20), 1);

    SELECT EXISTS (
        SELECT 1
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.folder_id = p_folder_id
          AND f.is_active = true
    )
    INTO v_exists;

    IF NOT v_exists THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH mixed_items AS (
        SELECT
            f.folder_id AS item_id,
            1 AS type_sort,
            'Folder'::text AS item_kind,
            LOWER(f.name) AS sort_name,
            f.created_date
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.parent_folder_id = p_folder_id
          AND f.is_active = true

        UNION ALL

        SELECT
            a.attachment_id,
            2,
            'Attachment'::text,
            LOWER(a.document_name),
            a.created_date
        FROM knowledgebase.knowledgebase_attachments a
        WHERE a.folder_id = p_folder_id
          AND a.is_active = true

        UNION ALL

        SELECT
            l.link_id,
            3,
            'Link'::text,
            LOWER(l.name),
            l.created_date
        FROM knowledgebase.knowledgebase_links l
        WHERE l.folder_id = p_folder_id
          AND l.is_active = true

        UNION ALL

        SELECT
            i.issue_id,
            4,
            'Issue'::text,
            LOWER(i.issue_name),
            i.created_date
        FROM knowledgebase.knowledgebase_issues i
        WHERE i.folder_id = p_folder_id
          AND i.is_active = true
    ),
    total_count AS (
        SELECT COUNT(*)::integer AS cnt
        FROM mixed_items
    ),
    paged AS (
        SELECT mi.*
        FROM mixed_items mi
        ORDER BY
            mi.created_date DESC NULLS LAST,
            mi.item_id DESC
        OFFSET ((v_page - 1) * v_page_size)
        LIMIT v_page_size
    )
    SELECT
        p_folder_id,
        (SELECT cnt FROM total_count),
        COALESCE(
            (
                SELECT jsonb_agg(
                    CASE p.item_kind
                        WHEN 'Folder' THEN knowledgebase.kb_folder_json(p.item_id, true)
                        WHEN 'Attachment' THEN knowledgebase.kb_attachment_json(p.item_id)
                        WHEN 'Link' THEN knowledgebase.kb_link_json(p.item_id)
                        WHEN 'Issue' THEN knowledgebase.kb_issue_folder_item_json(p.item_id)
                    END
                    ORDER BY
                        p.created_date DESC NULLS LAST,
                        p.item_id DESC
                )
                FROM paged p
            ),
            '[]'::jsonb
        ),
        v_page,
        v_page_size,
        (SELECT cnt FROM total_count),
        (SELECT cnt FROM total_count) > (v_page * v_page_size);
END;
$$;


--
-- Name: get_knowledgebase_folders(integer, integer, integer, uuid); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_folders(p_knowledge_base_id integer, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(data jsonb, total integer)
    LANGUAGE plpgsql ROWS 1
    AS $$
DECLARE
    v_page integer;
    v_page_size integer;
    v_user_type_id integer;
    v_has_permission boolean := false;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Get paginated root folders for a knowledge base
            Access:
              - user_type_id 44, 45 : full access
              - user_type_id 46     : requires user_knowledgebase_permission row
              - others              : no access
*/
    v_page := GREATEST(COALESCE(p_page, 1), 1);
    v_page_size := GREATEST(COALESCE(NULLIF(p_page_size, 0), 20), 1);

    SELECT up.user_type_id
    INTO v_user_type_id
    FROM users.userprofile up
    WHERE up.user_id = p_user_id
      AND up.is_active = true
    LIMIT 1;

    IF v_user_type_id IN (44, 45) THEN
        v_has_permission := true;
    ELSIF v_user_type_id = 46 THEN
        SELECT EXISTS (
            SELECT 1
            FROM knowledgebase.user_knowledgebase_permission p
            WHERE p.reg_id = p_user_id
              AND p.knowledge_base_id = p_knowledge_base_id
              AND p.is_active = true
        )
        INTO v_has_permission;
    ELSE
        v_has_permission := false;
    END IF;

    IF NOT v_has_permission THEN
        RETURN QUERY
        SELECT '[]'::jsonb, 0;
        RETURN;
    END IF;

    RETURN QUERY
    WITH root_folders AS (
        SELECT f.folder_id, f.created_date
        FROM knowledgebase.knowledgebase_folders f
        WHERE f.knowledge_base_id = p_knowledge_base_id
          AND f.parent_folder_id IS NULL
          AND f.is_active = true
    ),
    total_count AS (
        SELECT COUNT(*)::integer AS cnt
        FROM root_folders
    ),
    paged AS (
        SELECT rf.folder_id, rf.created_date
        FROM root_folders rf
        ORDER BY rf.created_date DESC NULLS LAST, rf.folder_id DESC
        OFFSET ((v_page - 1) * v_page_size)
        LIMIT v_page_size
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    knowledgebase.kb_folder_json(p.folder_id, false)
                    ORDER BY p.created_date DESC NULLS LAST, p.folder_id DESC
                )
                FROM paged p
            ),
            '[]'::jsonb
        ) AS data,
        (SELECT cnt FROM total_count) AS total;
END;
$$;


--
-- Name: get_knowledgebase_issue_by_id(uuid); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_issue_by_id(p_issue_refid uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT knowledgebase.kb_issue_json(i.issue_id)
    FROM knowledgebase.knowledgebase_issues i
    WHERE i.issue_refid = p_issue_refid
      AND i.is_active = true;
$$;


--
-- Name: get_knowledgebase_issues(integer, integer, integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_issues(p_folder_id integer, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS TABLE(data jsonb, page integer, "pageSize" integer, total integer, "hasMore" boolean)
    LANGUAGE plpgsql ROWS 1
    AS $$
DECLARE
    v_page integer;
    v_page_size integer;
    v_total integer;
BEGIN
/*
  Author  : Mubarak Basha
  Details : Paginated issue list for a tool folder
*/
    v_page := GREATEST(COALESCE(p_page, 1), 1);
    v_page_size := GREATEST(COALESCE(p_page_size, 20), 1);

    IF p_folder_id IS NULL OR p_folder_id <= 0 THEN
        RETURN QUERY
        SELECT '[]'::jsonb, v_page, v_page_size, 0, false;
        RETURN;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_total
    FROM knowledgebase.knowledgebase_issues i
    WHERE i.folder_id = p_folder_id
      AND i.is_active = true;

    RETURN QUERY
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(knowledgebase.kb_issue_json(x.issue_id) ORDER BY x.sort_date DESC NULLS LAST, x.issue_id DESC)
                FROM (
                    SELECT
                        i.issue_id,
                        i.created_date AS sort_date
                    FROM knowledgebase.knowledgebase_issues i
                    WHERE i.folder_id = p_folder_id
                      AND i.is_active = true
                    ORDER BY i.created_date DESC NULLS LAST, i.issue_id DESC
                    OFFSET ((v_page - 1) * v_page_size)
                    LIMIT v_page_size
                ) x
            ),
            '[]'::jsonb
        ) AS data,
        v_page AS page,
        v_page_size AS "pageSize",
        COALESCE(v_total, 0) AS total,
        (COALESCE(v_total, 0) > (v_page * v_page_size)) AS "hasMore";
END;
$$;


--
-- Name: get_knowledgebase_link_by_id(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_knowledgebase_link_by_id(p_link_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT knowledgebase.kb_link_json(p_link_id);
$$;


--
-- Name: get_user_knowledgebase_permission(uuid); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.get_user_knowledgebase_permission(p_user_id uuid) RETURNS TABLE("userKnowledgeBasePermissionId" integer, "knowledgeBaseId" integer, "knowledgeBaseName" character varying, "canEdit" integer, "isAdmin" boolean, "grantedBy" text, "grantedOn" timestamp without time zone)
    LANGUAGE plpgsql
    AS $_$
BEGIN
/*
  Author  : Mubarak Basha
  Details : Get user knowledge base permissions.
            Returns both User rows (is_admin = false) and Admin/Super Admin
            assignment rows (is_admin = true) for the given user.
*/
    RETURN QUERY
    SELECT
        ukp.user_knowledgebase_permission_id::integer AS "userKnowledgeBasePermissionId",
        ukp.knowledge_base_id::integer AS "knowledgeBaseId",
        kb.name::character varying AS "knowledgeBaseName",
        ukp.action_id::integer AS "canEdit",
        COALESCE(ukp.is_admin, false)::boolean AS "isAdmin",
        CASE
            WHEN ukp.created_by ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            THEN (
                SELECT ru."DisplayName"::text
                FROM users.registereduser ru
                WHERE ru."RegId" = ukp.created_by::uuid
                LIMIT 1
            )
            ELSE NULL::text
        END AS "grantedBy",
        ukp.created_date::timestamp AS "grantedOn"
    FROM knowledgebase.user_knowledgebase_permission ukp
    LEFT JOIN knowledgebase.knowledgebase_master kb
        ON kb.id = ukp.knowledge_base_id
    WHERE ukp.reg_id = p_user_id
      AND ukp.is_active = true
    ORDER BY ukp.user_knowledgebase_permission_id;
END;
$_$;


--
-- Name: kb_attachment_json(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_attachment_json(p_attachment_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT jsonb_build_object(
        'kind', 'Attachment',
        'id', a.attachment_refid,
        'folderId', a.folder_id,
        'documentName', a.document_name,
        'description', a.description,
        'fileType', COALESCE(a.file_type, ''),
        'fileName', COALESCE(a.file_name, ''),
        'fileUrl', COALESCE(a.file_url, ''),
        'uploadedBy', knowledgebase.kb_created_by_json(a.created_by),
        'uploadedDate', a.created_date
    )
    FROM knowledgebase.knowledgebase_attachments a
    WHERE a.attachment_id = p_attachment_id
      AND a.is_active = true;
$$;


--
-- Name: kb_created_by_json(text); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_created_by_json(p_created_by text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $_$
    SELECT COALESCE(
        (
            SELECT jsonb_build_array(
                jsonb_build_object(
                    'name', ru."DisplayName",
                    'displayName', ru."DisplayName",
                    'photo', COALESCE(ru.photo_url, '')
                )
            )
            FROM users.registereduser ru
            WHERE p_created_by IS NOT NULL
              AND p_created_by ~* '^[0-9a-fA-F-]{36}$'
              AND ru."RegId" = p_created_by::uuid
        ),
        '[]'::jsonb
    );
$_$;


--
-- Name: kb_folder_item_count(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_folder_item_count(p_folder_id integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT (
        (
            SELECT COUNT(*)::integer
            FROM knowledgebase.knowledgebase_folders f
            WHERE f.parent_folder_id = p_folder_id
              AND f.is_active = true
        )
        +
        (
            SELECT COUNT(*)::integer
            FROM knowledgebase.knowledgebase_attachments a
            WHERE a.folder_id = p_folder_id
              AND a.is_active = true
        )
        +
        (
            SELECT COUNT(*)::integer
            FROM knowledgebase.knowledgebase_links l
            WHERE l.folder_id = p_folder_id
              AND l.is_active = true
        )
        +
        (
            SELECT COUNT(*)::integer
            FROM knowledgebase.knowledgebase_issues i
            WHERE i.folder_id = p_folder_id
              AND i.is_active = true
        )
    );
$$;


--
-- Name: kb_folder_json(integer, boolean); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_folder_json(p_folder_id integer, p_include_kind boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT
        CASE
            WHEN p_include_kind THEN jsonb_build_object('kind', 'Folder')
            ELSE '{}'::jsonb
        END
        || jsonb_build_object(
            'id', f.folder_id,
            'knowledgeBaseId', f.knowledge_base_id,
            'parentId', f.parent_folder_id,
            'name', f.name,
            'description', f.description,
            'isManual', COALESCE(f.is_manual, false),
            'createdBy', knowledgebase.kb_created_by_json(f.created_by),
            'createdDate', f.created_date,
            'itemCount', knowledgebase.kb_folder_item_count(f.folder_id),
            'recentItems', knowledgebase.kb_folder_recent_items(f.folder_id)
        )
    FROM knowledgebase.knowledgebase_folders f
    WHERE f.folder_id = p_folder_id
      AND f.is_active = true;
$$;


--
-- Name: kb_folder_recent_items(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_folder_recent_items(p_folder_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    -- Child items only (no nested recentItems — avoids recursive kb_folder_json).
    SELECT COALESCE(
        (
            SELECT jsonb_agg(item_json ORDER BY sort_date DESC NULLS LAST, item_id DESC)
            FROM (
                SELECT
                    f.folder_id AS item_id,
                    f.created_date AS sort_date,
                    jsonb_build_object(
                        'kind', 'Folder',
                        'id', f.folder_id,
                        'knowledgeBaseId', f.knowledge_base_id,
                        'parentId', f.parent_folder_id,
                        'name', f.name,
                        'description', f.description,
                        'isManual', COALESCE(f.is_manual, false),
                        'createdBy', knowledgebase.kb_created_by_json(f.created_by),
                        'createdDate', f.created_date,
                        'itemCount', knowledgebase.kb_folder_item_count(f.folder_id),
                        'recentItems', '[]'::jsonb
                    ) AS item_json
                FROM knowledgebase.knowledgebase_folders f
                WHERE f.parent_folder_id = p_folder_id
                  AND f.is_active = true

                UNION ALL

                SELECT
                    a.attachment_id,
                    a.created_date,
                    knowledgebase.kb_attachment_json(a.attachment_id)
                FROM knowledgebase.knowledgebase_attachments a
                WHERE a.folder_id = p_folder_id
                  AND a.is_active = true

                UNION ALL

                SELECT
                    l.link_id,
                    l.created_date,
                    knowledgebase.kb_link_json(l.link_id)
                FROM knowledgebase.knowledgebase_links l
                WHERE l.folder_id = p_folder_id
                  AND l.is_active = true

                UNION ALL

                SELECT
                    i.issue_id,
                    i.created_date,
                    knowledgebase.kb_issue_folder_item_json(i.issue_id)
                FROM knowledgebase.knowledgebase_issues i
                WHERE i.folder_id = p_folder_id
                  AND i.is_active = true
            ) x
            WHERE x.item_json IS NOT NULL
        ),
        '[]'::jsonb
    );
$$;


--
-- Name: kb_issue_created_by_json(text); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_issue_created_by_json(p_created_by text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $_$
    SELECT COALESCE(
        (
            SELECT jsonb_build_object(
                'name', COALESCE(ru."DisplayName", ru."Email", ''),
                'email', COALESCE(ru."Email", ''),
                'photo', COALESCE(ru.photo_url, '')
            )
            FROM users.registereduser ru
            WHERE p_created_by IS NOT NULL
              AND p_created_by ~* '^[0-9a-fA-F-]{36}$'
              AND ru."RegId" = p_created_by::uuid
        ),
        jsonb_build_object('name', '', 'email', '', 'photo', '')
    );
$_$;


--
-- Name: kb_issue_folder_item_json(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_issue_folder_item_json(p_issue_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT jsonb_build_object('kind', 'Issue')
        || knowledgebase.kb_issue_json(p_issue_id)
    FROM knowledgebase.knowledgebase_issues i
    WHERE i.issue_id = p_issue_id
      AND i.is_active = true;
$$;


--
-- Name: kb_issue_json(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_issue_json(p_issue_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT jsonb_build_object(
        'id', i.issue_refid,
        'knowledgeBaseId', i.knowledge_base_id,
        'kbId', i.knowledge_base_id,
        'folderId', i.folder_id,
        'parentFolderId', i.parent_folder_id,
        'issueType', COALESCE(i.issue_json->>'issueType', ''),
        'issueSubtype', COALESCE(i.issue_json->>'issueSubtype', ''),
        'issueTitle', COALESCE(i.issue_name, ''),
        'issueTags', knowledgebase.kb_issue_tags_json(i.issue_json),
        'issueDescription', COALESCE(i.issue_json->>'issueDescription', ''),
        'symptoms', COALESCE(i.issue_json->'symptoms', '[]'::jsonb),
        'verification', COALESCE(i.issue_json->'verification', '[]'::jsonb),
        'processWorkflow', COALESCE(i.issue_json->>'processWorkflow', ''),
        'rootCause', COALESCE(i.issue_json->>'rootCause', ''),
        'resolutionSteps', COALESCE(i.issue_json->'resolutionSteps', '[]'::jsonb),
        'xmlConfigs', COALESCE(i.issue_json->'xmlConfigs', '[]'::jsonb),
        'relatedTickets', COALESCE(i.issue_json->'relatedTickets', '[]'::jsonb),
        'sourceType', COALESCE(i.issue_json->>'sourceType', 'manual'),
        'freshdeskTicketId', i.freshdesk_ticket,
        'lastSyncedAt', i.last_synced,
        'vectorProcessingStatus', i.vector_processing_status,
        'createdBy', knowledgebase.kb_issue_created_by_json(i.created_by),
        'createdDate', i.created_date,
        'updatedDate', i.last_updated_date
    )
    FROM knowledgebase.knowledgebase_issues i
    WHERE i.issue_id = p_issue_id
      AND i.is_active = true;
$$;


--
-- Name: kb_issue_tags_json(jsonb); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_issue_tags_json(p_issue_json jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE
        WHEN jsonb_typeof(p_issue_json->'issueTags') = 'array' THEN
            COALESCE(p_issue_json->'issueTags', '[]'::jsonb)
        WHEN NULLIF(btrim(COALESCE(p_issue_json->>'documentType', '')), '') IS NOT NULL THEN
            jsonb_build_array(btrim(p_issue_json->>'documentType'))
        ELSE
            '[]'::jsonb
    END;
$$;


--
-- Name: kb_link_json(integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_link_json(p_link_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT jsonb_build_object(
        'kind', 'Link',
        'id', l.link_id,
        'folderId', l.folder_id,
        'name', l.name,
        'url', l.url,
        'description', l.description,
        'createdBy', knowledgebase.kb_created_by_json(l.created_by),
        'createdDate', l.created_date
    )
    FROM knowledgebase.knowledgebase_links l
    WHERE l.link_id = p_link_id
      AND l.is_active = true;
$$;


--
-- Name: kb_search_match(text, text, text, tsquery); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_search_match(p_text text, p_query text, p_like text, p_tsq tsquery) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT
        COALESCE(p_text, '') ILIKE p_like ESCAPE '\'
        OR (
            p_tsq IS NOT NULL
            AND to_tsvector('simple', COALESCE(p_text, '')) @@ p_tsq
        );
$$;


--
-- Name: kb_search_path(integer, integer); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_search_path(p_knowledge_base_id integer, p_folder_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    WITH RECURSIVE chain AS (
        SELECT
            f.folder_id,
            f.parent_folder_id,
            f.name,
            0 AS depth
        FROM knowledgebase.knowledgebase_folders f
        WHERE p_folder_id IS NOT NULL
          AND f.folder_id = p_folder_id
          AND f.is_active = true

        UNION ALL

        SELECT
            p.folder_id,
            p.parent_folder_id,
            p.name,
            c.depth + 1
        FROM knowledgebase.knowledgebase_folders p
        INNER JOIN chain c ON p.folder_id = c.parent_folder_id
        WHERE p.is_active = true
    )
    SELECT COALESCE(
        (
            SELECT jsonb_build_array(
                jsonb_build_object(
                    'id', kb.id::text,
                    'name', kb.name
                )
            ) || COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'id', c.folder_id::text,
                            'name', c.name
                        )
                        ORDER BY c.depth DESC
                    )
                    FROM chain c
                ),
                '[]'::jsonb
            )
            FROM knowledgebase.knowledgebase_master kb
            WHERE kb.id = p_knowledge_base_id
        ),
        '[]'::jsonb
    );
$$;


--
-- Name: kb_search_rank(text, text, text, tsquery); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.kb_search_rank(p_text text, p_title text, p_query text, p_tsq tsquery) RETURNS real
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT GREATEST(
        CASE
            WHEN p_tsq IS NULL THEN 0
            ELSE ts_rank(to_tsvector('simple', COALESCE(p_text, '')), p_tsq)
        END,
        CASE
            WHEN lower(COALESCE(p_title, '')) = lower(btrim(p_query)) THEN 1
            WHEN COALESCE(p_title, '') ILIKE p_query || '%' THEN 0.7
            WHEN COALESCE(p_title, '') ILIKE '%' || p_query || '%' THEN 0.45
            ELSE 0
        END
    )::real;
$$;


--
-- Name: search_knowledgebase(text, text, integer, integer, integer, text, text, uuid); Type: FUNCTION; Schema: knowledgebase; Owner: -
--

CREATE FUNCTION knowledgebase.search_knowledgebase(p_query text, p_knowledge_base_ids text, p_page_offset integer DEFAULT 0, p_page_size integer DEFAULT 20, p_folder_id integer DEFAULT NULL::integer, p_type text DEFAULT NULL::text, p_sort text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(data jsonb, "pageOffset" integer, "pageSize" integer, total integer, "hasMore" boolean)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_query text;
    v_type text;
    v_sort text;
    v_offset integer;
    v_page_size integer;
    v_folder_id integer;
    v_tsq tsquery;
    v_user_type_id integer;
    v_like text;
BEGIN
/*
  Author  : Mubarak Basha
  Details : PostgreSQL full-text search across knowledge bases, folders,
            attachments, links, and issues. Ignores knowledge bases the
            caller is not allowed to access.
*/

    v_query := btrim(COALESCE(p_query, ''));
    v_offset := GREATEST(COALESCE(p_page_offset, 0), 0);
    v_page_size := GREATEST(COALESCE(NULLIF(p_page_size, 0), 20), 1);
    v_folder_id := NULLIF(p_folder_id, 0);
    v_type := NULLIF(btrim(COALESCE(p_type, '')), '');
    v_sort := lower(COALESCE(NULLIF(btrim(p_sort), ''), 'relevance'));

    IF p_user_id IS NULL OR length(v_query) < 2 OR NULLIF(btrim(COALESCE(p_knowledge_base_ids, '')), '') IS NULL THEN
        RETURN QUERY
        SELECT '[]'::jsonb, v_offset, v_page_size, 0, false;
        RETURN;
    END IF;

    IF v_type IS NOT NULL AND v_type NOT IN ('Attachment', 'Issue', 'Link', 'Folder', 'KnowledgeBase') THEN
        v_type := NULL;
    END IF;

    IF v_sort NOT IN ('relevance', 'updated', 'created', 'nameasc', 'namedesc') THEN
        v_sort := 'relevance';
    END IF;

    SELECT up.user_type_id
    INTO v_user_type_id
    FROM users.userprofile up
    WHERE up.user_id = p_user_id
      AND up.is_active = true
    LIMIT 1;

    v_like := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';

    BEGIN
        SELECT to_tsquery('simple', string_agg(token || ':*', ' & '))
        INTO v_tsq
        FROM (
            SELECT DISTINCT regexp_replace(lower(word), '[^a-z0-9]+', '', 'g') AS token
            FROM regexp_split_to_table(v_query, '\s+') AS word
        ) tokens
        WHERE length(token) >= 2;
    EXCEPTION
        WHEN OTHERS THEN
            v_tsq := NULL;
    END;

    RETURN QUERY
    WITH RECURSIVE requested_ids AS (
        SELECT DISTINCT trimmed::integer AS knowledge_base_id
        FROM regexp_split_to_table(p_knowledge_base_ids, ',') AS raw(value)
        CROSS JOIN LATERAL (SELECT btrim(raw.value) AS trimmed) t
        WHERE trimmed ~ '^[0-9]+$'
          AND trimmed::integer > 0
    ),
    allowed_kbs AS (
        SELECT kb.id, kb.name, kb.description, kb.created_date, kb.last_updated_date, kb.created_by, kb.updated_by
        FROM requested_ids r
        INNER JOIN knowledgebase.knowledgebase_master kb
            ON kb.id = r.knowledge_base_id
           AND kb.is_active = true
        WHERE v_user_type_id IN (44, 45)
           OR EXISTS (
                SELECT 1
                FROM knowledgebase.user_knowledgebase_permission p
                WHERE p.reg_id = p_user_id
                  AND p.knowledge_base_id = kb.id
                  AND p.is_active = true
           )
    ),
    subtree AS (
        SELECT f.folder_id
        FROM knowledgebase.knowledgebase_folders f
        INNER JOIN allowed_kbs kb ON kb.id = f.knowledge_base_id
        WHERE v_folder_id IS NOT NULL
          AND f.folder_id = v_folder_id
          AND f.is_active = true

        UNION ALL

        SELECT c.folder_id
        FROM knowledgebase.knowledgebase_folders c
        INNER JOIN subtree s ON c.parent_folder_id = s.folder_id
        WHERE c.is_active = true
    ),
    hits AS (
        SELECT
            kb.id::text AS id,
            'KnowledgeBase'::text AS item_type,
            kb.name AS title,
            COALESCE(kb.description, '') AS snippet,
            knowledgebase.kb_search_path(kb.id, NULL) AS path,
            kb.id AS knowledge_base_id,
            NULL::integer AS folder_id,
            ''::text AS url,
            NULL::text AS file_type,
            knowledgebase.kb_issue_created_by_json(kb.created_by) AS created_by,
            knowledgebase.kb_issue_created_by_json(COALESCE(kb.updated_by, kb.created_by)) AS updated_by,
            kb.created_date,
            COALESCE(kb.last_updated_date, kb.created_date) AS updated_date,
            knowledgebase.kb_search_rank(kb.name || ' ' || COALESCE(kb.description, ''), kb.name, v_query, v_tsq) AS score
        FROM allowed_kbs kb
        WHERE v_folder_id IS NULL
          AND (v_type IS NULL OR v_type = 'KnowledgeBase')
          AND knowledgebase.kb_search_match(kb.name || ' ' || COALESCE(kb.description, ''), v_query, v_like, v_tsq)

        UNION ALL

        SELECT
            f.folder_id::text,
            'Folder',
            f.name,
            COALESCE(f.description, ''),
            knowledgebase.kb_search_path(f.knowledge_base_id, f.parent_folder_id),
            f.knowledge_base_id,
            f.folder_id,
            '',
            NULL,
            knowledgebase.kb_issue_created_by_json(f.created_by),
            knowledgebase.kb_issue_created_by_json(COALESCE(f.updated_by, f.created_by)),
            f.created_date,
            COALESCE(f.last_updated_date, f.created_date),
            knowledgebase.kb_search_rank(f.name || ' ' || COALESCE(f.description, ''), f.name, v_query, v_tsq)
        FROM knowledgebase.knowledgebase_folders f
        INNER JOIN allowed_kbs kb ON kb.id = f.knowledge_base_id
        WHERE f.is_active = true
          AND (v_type IS NULL OR v_type = 'Folder')
          AND (
                v_folder_id IS NULL
                OR f.folder_id IN (SELECT folder_id FROM subtree)
          )
          AND knowledgebase.kb_search_match(f.name || ' ' || COALESCE(f.description, ''), v_query, v_like, v_tsq)

        UNION ALL

        SELECT
            a.attachment_refid::text,
            'Attachment',
            a.document_name,
            COALESCE(NULLIF(a.description, ''), a.file_name, ''),
            knowledgebase.kb_search_path(f.knowledge_base_id, a.folder_id),
            f.knowledge_base_id,
            a.folder_id,
            '',
            CASE lower(COALESCE(a.file_type, ''))
                WHEN 'pdf' THEN 'application/pdf'
                WHEN 'doc' THEN 'application/msword'
                WHEN 'docx' THEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
                WHEN 'xls' THEN 'application/vnd.ms-excel'
                WHEN 'xlsx' THEN 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
                WHEN 'ppt' THEN 'application/vnd.ms-powerpoint'
                WHEN 'pptx' THEN 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
                WHEN 'txt' THEN 'text/plain'
                WHEN 'csv' THEN 'text/csv'
                WHEN 'json' THEN 'application/json'
                WHEN 'xml' THEN 'application/xml'
                WHEN 'png' THEN 'image/png'
                WHEN 'jpg' THEN 'image/jpeg'
                WHEN 'jpeg' THEN 'image/jpeg'
                ELSE NULLIF(a.file_type, '')
            END,
            knowledgebase.kb_issue_created_by_json(a.created_by),
            knowledgebase.kb_issue_created_by_json(COALESCE(a.updated_by, a.created_by)),
            a.created_date,
            COALESCE(a.last_updated_date, a.created_date),
            knowledgebase.kb_search_rank(
                a.document_name || ' ' || COALESCE(a.description, '') || ' ' || COALESCE(a.file_name, ''),
                a.document_name,
                v_query,
                v_tsq)
        FROM knowledgebase.knowledgebase_attachments a
        INNER JOIN knowledgebase.knowledgebase_folders f
            ON f.folder_id = a.folder_id
           AND f.is_active = true
        INNER JOIN allowed_kbs kb ON kb.id = f.knowledge_base_id
        WHERE a.is_active = true
          AND (v_type IS NULL OR v_type = 'Attachment')
          AND (
                v_folder_id IS NULL
                OR a.folder_id IN (SELECT folder_id FROM subtree)
          )
          AND knowledgebase.kb_search_match(
                a.document_name || ' ' || COALESCE(a.description, '') || ' ' || COALESCE(a.file_name, ''),
                v_query,
                v_like,
                v_tsq)

        UNION ALL

        SELECT
            l.link_id::text,
            'Link',
            l.name,
            COALESCE(NULLIF(l.description, ''), l.url, ''),
            knowledgebase.kb_search_path(f.knowledge_base_id, l.folder_id),
            f.knowledge_base_id,
            l.folder_id,
            COALESCE(l.url, ''),
            NULL,
            knowledgebase.kb_issue_created_by_json(l.created_by),
            knowledgebase.kb_issue_created_by_json(COALESCE(l.updated_by, l.created_by)),
            l.created_date,
            COALESCE(l.last_updated_date, l.created_date),
            knowledgebase.kb_search_rank(l.name || ' ' || COALESCE(l.description, '') || ' ' || COALESCE(l.url, ''), l.name, v_query, v_tsq)
        FROM knowledgebase.knowledgebase_links l
        INNER JOIN knowledgebase.knowledgebase_folders f
            ON f.folder_id = l.folder_id
           AND f.is_active = true
        INNER JOIN allowed_kbs kb ON kb.id = f.knowledge_base_id
        WHERE l.is_active = true
          AND (v_type IS NULL OR v_type = 'Link')
          AND (
                v_folder_id IS NULL
                OR l.folder_id IN (SELECT folder_id FROM subtree)
          )
          AND knowledgebase.kb_search_match(
                l.name || ' ' || COALESCE(l.description, '') || ' ' || COALESCE(l.url, ''),
                v_query,
                v_like,
                v_tsq)

        UNION ALL

        SELECT
            i.issue_refid::text,
            'Issue',
            i.issue_name,
            COALESCE(i.issue_json->>'issueDescription', ''),
            knowledgebase.kb_search_path(i.knowledge_base_id, i.folder_id),
            i.knowledge_base_id,
            i.folder_id,
            '',
            NULL,
            knowledgebase.kb_issue_created_by_json(i.created_by),
            knowledgebase.kb_issue_created_by_json(COALESCE(i.updated_by, i.created_by)),
            i.created_date,
            COALESCE(i.last_updated_date, i.created_date),
            knowledgebase.kb_search_rank(
                i.issue_name || ' ' ||
                COALESCE(i.issue_json->>'issueDescription', '') || ' ' ||
                COALESCE(i.issue_json->>'issueType', '') || ' ' ||
                COALESCE(i.issue_json->>'issueSubtype', '') || ' ' ||
                COALESCE(i.issue_json->>'rootCause', '') || ' ' ||
                COALESCE(i.issue_json->>'processWorkflow', '') || ' ' ||
                COALESCE(i.issue_json->>'symptoms', '') || ' ' ||
                COALESCE(i.issue_json->>'issueTags', ''),
                i.issue_name,
                v_query,
                v_tsq)
        FROM knowledgebase.knowledgebase_issues i
        INNER JOIN allowed_kbs kb ON kb.id = i.knowledge_base_id
        WHERE i.is_active = true
          AND (v_type IS NULL OR v_type = 'Issue')
          AND (
                v_folder_id IS NULL
                OR i.folder_id IN (SELECT folder_id FROM subtree)
          )
          AND knowledgebase.kb_search_match(
                i.issue_name || ' ' ||
                COALESCE(i.issue_json->>'issueDescription', '') || ' ' ||
                COALESCE(i.issue_json->>'issueType', '') || ' ' ||
                COALESCE(i.issue_json->>'issueSubtype', '') || ' ' ||
                COALESCE(i.issue_json->>'rootCause', '') || ' ' ||
                COALESCE(i.issue_json->>'processWorkflow', '') || ' ' ||
                COALESCE(i.issue_json->>'symptoms', '') || ' ' ||
                COALESCE(i.issue_json->>'issueTags', ''),
                v_query,
                v_like,
                v_tsq)
    ),
    counted AS (
        SELECT COUNT(*)::integer AS cnt
        FROM hits
    ),
    paged AS (
        SELECT *
        FROM hits
        ORDER BY
            CASE WHEN v_sort = 'relevance' THEN score END DESC NULLS LAST,
            CASE WHEN v_sort = 'updated' THEN updated_date END DESC NULLS LAST,
            CASE WHEN v_sort = 'created' THEN created_date END DESC NULLS LAST,
            CASE WHEN v_sort = 'nameasc' THEN lower(title) END ASC NULLS LAST,
            CASE WHEN v_sort = 'namedesc' THEN lower(title) END DESC NULLS LAST,
            updated_date DESC NULLS LAST,
            title ASC
        OFFSET (v_offset * v_page_size)
        LIMIT v_page_size
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', p.id,
                        'type', p.item_type,
                        'kind', p.item_type,
                        'title', p.title,
                        'name', p.title,
                        'snippet', left(regexp_replace(COALESCE(p.snippet, ''), '\s+', ' ', 'g'), 240),
                        'description', COALESCE(p.snippet, ''),
                        'path', COALESCE(p.path, '[]'::jsonb),
                        'breadcrumb', knowledgebase.kb_search_path(p.knowledge_base_id, p.folder_id),
                        'knowledgeBaseId', p.knowledge_base_id::text,
                        'kbId', p.knowledge_base_id::text,
                        'folderId', CASE WHEN p.folder_id IS NULL THEN NULL ELSE p.folder_id::text END,
                        'parentFolderId', CASE WHEN p.folder_id IS NULL THEN NULL ELSE p.folder_id::text END,
                        'url', COALESCE(p.url, ''),
                        'linkUrl', COALESCE(p.url, ''),
                        'fileType', p.file_type,
                        'mimeType', p.file_type,
                        'createdBy', p.created_by,
                        'updatedBy', p.updated_by,
                        'createdDate', to_char(p.created_date, 'YYYY-MM-DD'),
                        'updatedDate', to_char(p.updated_date, 'YYYY-MM-DD'),
                        'scoreLabel', CASE
                            WHEN p.score >= 0.4 THEN 'high'
                            WHEN p.score >= 0.15 THEN 'medium'
                            ELSE 'low'
                        END
                    )
                    ORDER BY
                        CASE WHEN v_sort = 'relevance' THEN p.score END DESC NULLS LAST,
                        CASE WHEN v_sort = 'updated' THEN p.updated_date END DESC NULLS LAST,
                        CASE WHEN v_sort = 'created' THEN p.created_date END DESC NULLS LAST,
                        CASE WHEN v_sort = 'nameasc' THEN lower(p.title) END ASC NULLS LAST,
                        CASE WHEN v_sort = 'namedesc' THEN lower(p.title) END DESC NULLS LAST,
                        p.updated_date DESC NULLS LAST,
                        p.title ASC
                )
                FROM paged p
            ),
            '[]'::jsonb
        ) AS data,
        v_offset AS "pageOffset",
        v_page_size AS "pageSize",
        (SELECT cnt FROM counted) AS total,
        ((SELECT cnt FROM counted) > ((v_offset + 1) * v_page_size)) AS "hasMore";
END;
$_$;


--
-- Name: add_update_master_configuration(integer, character varying, character varying, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.add_update_master_configuration(IN p_config_id integer, IN p_config_name character varying, IN p_config_type character varying, IN p_config_value text, IN p_created_by text, INOUT new_p_config_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context TEXT;
    v_config_value JSONB := p_config_value::jsonb;   
    v_exists BOOLEAN;
    v_rowcount INTEGER := 0;
BEGIN
    /*
      Author  : Mubarak Basha
      Details : Create or Update Master Configuration
    */

    --  Validate JSON
    IF p_config_value IS NULL THEN
        message := 'Formula Value cannot be null';
        status  := 'false';
        RETURN;
    END IF;

    --  Check if record exists
    SELECT EXISTS (
        SELECT 1
        FROM master.master_configuration
        WHERE id = p_config_id
    )
    INTO v_exists;

    
    --  UPDATE
    
    IF v_exists THEN

        UPDATE master.master_configuration
        SET name = p_config_name,
            type = p_config_type,
            value = v_config_value,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = p_created_by
        WHERE id = p_config_id;

        new_p_config_id := p_config_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Formula Updated Successfully';
            status  := 'true';
        ELSE
            message := 'Formula Update Failed';
            status  := 'false';
        END IF;

  
    --  INSERT

    ELSE

        INSERT INTO master.master_configuration
        (
            name,
            type,
            value,
            is_active,
            created_date,
            created_by
        )
        VALUES
        (
            p_config_name,
            p_config_type,
            v_config_value,
            true,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            p_created_by
        )
        RETURNING id INTO new_p_config_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            message := 'Formula Created Successfully';
            status  := 'true';
        ELSE
            message := 'Formula Creation Failed';
            status  := 'false';
        END IF;

    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'master.add_update_master_configuration',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_config_id,
                p_config_name,
                p_config_type,
                p_config_value,
                p_created_by
            ))::TEXT
        );

        status  := 'ERROR';
        message := SQLERRM;
END;
$$;


--
-- Name: add_update_workspace(integer, character varying, text, integer, integer, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.add_update_workspace(IN in_work_space_id integer, IN in_name character varying, IN in_created_by text, IN in_work_flow_type integer, INOUT out_work_space_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists boolean;
    v_name_exists boolean;
    v_context text;
    v_new_work_space_id integer;
	v_rowcount INTEGER := 0;
BEGIN
/*
Authour : Mubarak Basha
Details : To add & update the workspace 
Sprinit : Kanban Board - 5
*/
    -- Check for duplicate workspace name
    SELECT EXISTS (
        SELECT 1 
        FROM master.work_space_master w
        WHERE lower(w.name) = lower(in_name)
          AND (in_work_space_id IS NULL 
               OR w.work_space_id <> in_work_space_id)
			   AND w.is_active = true  
    ) INTO v_name_exists;

    IF v_name_exists THEN
        message := format('Workspace with name "%s" already exists', in_name);
        status := 'false';
        RETURN;
    END IF;
	
      -- Validate workflow type (INTEGER)

    IF in_work_flow_type IS NULL OR NOT EXISTS (
        SELECT 1
        FROM master.status_code_master
        WHERE status_id = in_work_flow_type
          AND type = 'WORKFLOWTYPE'
          AND is_active = true
    ) THEN
        message := 'Invalid workflow type';
        status  := 'false';
        RETURN;
	END IF;
	
    -- Check if workspace id exists
    SELECT EXISTS (
        SELECT 1 
        FROM master.work_space_master w
        WHERE w.work_space_id = in_work_space_id
    ) INTO v_exists;

    IF v_exists THEN
        -- UPDATE existing workspace
        UPDATE master.work_space_master
        SET name = in_name,
		    work_flow_type = in_work_flow_type,
            updated_by = in_created_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE work_space_id = in_work_space_id;

        out_work_space_id := in_work_space_id;
		GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'Workspace Updated Successfully';
        status := 'true';
    ELSE
       message := 'Workspace Updated failed';
       status := 'false';
    END IF;

    ELSE
        
        SELECT COALESCE(MAX(work_space_id) + 1, 1) INTO v_new_work_space_id FROM master.work_space_master;

	     -- INSERT new workspace
			INSERT INTO master.work_space_master (
			    work_space_id, 
			    name, 
			    created_by, 
				work_flow_type,
			    created_date, 
			    is_active, 
			    code
			)
			VALUES (
			    v_new_work_space_id,
			    in_name,
			    in_created_by,
			    in_work_flow_type,
			    current_timestamp AT TIME ZONE 'UTC',
			    true, 
			    UPPER(REPLACE(in_name, ' ', ''))
			)
        RETURNING work_space_id INTO out_work_space_id;
		GET DIAGNOSTICS v_rowcount = ROW_COUNT;

    IF v_rowcount > 0 THEN
        message := 'Workspace Created Successfully';
        status := 'true';
    ELSE
       message := 'Workspace Created failed';
       status := 'false';
    END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'master.add_update_workspace',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                in_work_space_id,
                in_name,
                in_created_by,
				in_work_flow_type
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: addorupdatecorecolordetails(bigint, character varying, character varying, character varying, character varying, bigint, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.addorupdatecorecolordetails(IN icolorid bigint, IN icolorcode character varying, IN icolorname character varying, IN iflag character varying, IN iby character varying, INOUT colorid bigint DEFAULT NULL::bigint, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
begin
 
 -- updatedby || updatedDate  || Purpose
 -- Naveen S  || 05-03-2024   || Modify the update Codition

if(iflag = 'insert')
THEN
IF NOT EXISTS (SELECT "ColorCode" FROM master.corecolor WHERE LOWER("ColorCode") =  LOWER(icolorcode) )
THEN
			INSERT INTO master.corecolor("ColorCode", "Name", is_active, created_date, created_by)
			values(icolorcode,icolorname,'true',CURRENT_DATE,iby)
			RETURNING "ColorID"
			INTO ColorID;
			message = 'New CoreColor Created Successfully';
			status ='true';
ELSE
            message = 'ColorCode already exists.';
			status ='false';
			return;
END IF;
END IF;
if(iflag = 'update')
THEN
IF EXISTS (SELECT * FROM master.corecolor WHERE "ColorID"= icolorid and is_active = 'true' )
THEN
-- IF EXISTS (SELECT * FROM master.corecolor WHERE "ColorID"!= icolorid AND LOWER("ColorCode") =  LOWER(icolorcode))
-- THEN
            UPDATE master.corecolor SET 
		   "ColorCode"=icolorcode,
		   "Name" = icolorname,
		   last_updated_date = CURRENT_DATE,
		   updated_by = iby
		   WHERE "ColorID" = icolorid
		   AND is_active = 'true';
		   message = 'CoreCore Updated Successfully';
		   status ='true';
-- ELSE
--             message = 'ColorCode already exists.';
-- 			status ='false';
-- 			return;
-- END IF;
ELSE
            message = 'CoreColor Not exists.';
			status ='false';
			return;
END IF;
END IF;
EXCEPTION  WHEN OTHERS
THEN
   message = 'Error occured during the Opeartion';
    status = 'false';
END;
$$;


--
-- Name: addorupdatecountrydetails(bigint, character varying, character varying, bigint, character varying, character varying, bigint, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.addorupdatecountrydetails(IN icountryid bigint, IN icountrycode character varying, IN icountryname character varying, IN iregionid bigint, IN iflag character varying, IN iby character varying, INOUT countryid bigint DEFAULT NULL::bigint, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
begin
IF EXISTS (SELECT "Name" FROM master.country WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(icountryname)) and is_active='false')
THEN
            message = 'Country is deactivated State.';
			status ='false';
			return;

 

END IF;
IF EXISTS (SELECT "Name" FROM master.country WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(icountryname)) AND "CountryID"!=icountryid)
THEN
            message = 'Country already exists.';
			status ='false';
			return;

 

END IF;

 

if(iflag = 'insert')
THEN

IF NOT EXISTS (SELECT "Name" FROM master.country WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(icountryname)) )
THEN
			INSERT INTO master.country("CountryCode", "Name", "RegionID", is_active, created_date, created_by)
			values(icountrycode,icountryname,iregionid,'true',CURRENT_DATE,iby)
			RETURNING "CountryID"
			INTO CountryID;
			message = 'New Country Created Successfully';
			status ='true';
END IF;
END IF;
if(iflag = 'update')
THEN
IF NOT EXISTS (SELECT "Name" FROM master.country WHERE "CountryID"=icountryid)
THEN
            message = 'Country not exists.';
			status ='false';
			return;

 

END IF;
IF EXISTS (SELECT * FROM master.country WHERE "CountryID"=icountryid and is_active!='false')
THEN
            UPDATE master.country SET 
			"CountryCode"=icountrycode,
		   "Name" = icountryname,
		   "RegionID"=iregionid,
		   last_updated_date = CURRENT_DATE,
		   updated_by = iby
		   WHERE "CountryID"=icountryid
		   AND is_active ='true';
		   message = 'Country Updated Successfully';
		   status ='true';
ELSE
            message = 'Country is deactivated State.';
			status ='false';
			return;
END IF;
END IF;
EXCEPTION  WHEN OTHERS
THEN
   message = 'Error occured during the Opeartion';
    status = 'false';
END;
$$;


--
-- Name: addorupdatedeptdetails(bigint, character varying, character varying, character varying, character varying, bigint, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.addorupdatedeptdetails(IN ideptid bigint, IN ideptname character varying, IN ideptcode character varying, IN iflag character varying, IN iby character varying, INOUT deptid bigint DEFAULT NULL::bigint, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    regid_array UUID[];
    regid UUID;
begin

 -- updatedby || updatedDate  || Purpose
 -- Naveen S  || 05-03-2024   || Modify the update Codition
 
IF EXISTS (SELECT "Name" FROM master.department WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(ideptname)) AND is_active='false')
THEN
            message = 'Department is deactivated State.';
			status ='false';
			return;

 

END IF;
IF EXISTS (SELECT "Name" FROM master.department WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(ideptname)) AND "DeptID"!=ideptid)
THEN
            message = 'Department already exists.';
			status ='false';
			return;

 

END IF;

 

if(iflag = 'insert')
THEN

IF NOT EXISTS (SELECT "Name" FROM master.department WHERE LOWER(TRIM("Name")) =  LOWER(TRIM(ideptname)) )
THEN
			INSERT INTO master.department("Name","DeptCode",is_active,created_date,created_by)
			values(ideptname,ideptcode,'true',CURRENT_DATE,iby)
			RETURNING "DeptID"
			INTO DeptID;
 
    		-- Retrieve the array of RegId
   			SELECT array_agg(ur."RegId")
    		INTO regid_array
   			FROM users.userrole ur
    		JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true'
    		WHERE UPPER(r."Name") IN (UPPER('SuperAdmin'), UPPER('Admin'));
    
    		-- Loop through the array and insert into another table
    		FOREACH regid IN ARRAY regid_array
    		LOOP
	 			 INSERT INTO users.userdepartment
	  			 (
		 			 "RegId",
		  			 "DeptID",
		             is_active,
		             created_date,
		             created_by
	             )
	             VALUES
	            (
		  			regid,
		  			DeptID,
		 			'true',
		  			current_timestamp AT TIME ZONE 'UTC',
		  			iby
	  			);
       
           END LOOP;
			message = 'New Department Created Successfully';
			status ='true';
END IF;
END IF;
if(iflag = 'update')
THEN
IF NOT EXISTS (SELECT "Name" FROM master.department WHERE "DeptID"=ideptid)
THEN
            message = 'Department not exists.';
			status ='false';
			return;

 

END IF;
IF EXISTS (SELECT * FROM master.department WHERE "DeptID"=ideptid and is_active!='false')
THEN
            UPDATE master.department SET 
		   "Name" = ideptname,
		   "DeptCode" = ideptcode,
		   last_updated_date = CURRENT_DATE,
		   updated_by = iby
		   WHERE "DeptID" = ideptid
		   AND is_active = 'true';
		   message = 'Department Updated Successfully';
		   status ='true';
ELSE
            message = 'Department is deactivated State.';
			status ='false';
			return;
END IF;
END IF;
-- EXCEPTION  WHEN OTHERS
-- THEN
--    message = 'Error occured during the Opeartion';
--     status = 'false';
END;
$$;


