--
-- Name: calculate_time_ago(timestamp without time zone); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.calculate_time_ago(in_date timestamp without time zone) RETURNS text
    LANGUAGE plpgsql
    AS $$

BEGIN
    RETURN (
        SELECT CONCAT(
            CASE
                WHEN EXTRACT(YEAR FROM AGE(NOW(), in_date)) > 0 THEN
                    EXTRACT(YEAR FROM AGE(NOW(), in_date)) || ' year' || 
                    CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), in_date)) > 1 THEN 's' ELSE '' END || ' ago '
                WHEN EXTRACT(MONTH FROM AGE(NOW(), in_date)) > 0 THEN
                    EXTRACT(MONTH FROM AGE(NOW(), in_date)) || ' month' || 
                    CASE WHEN EXTRACT(MONTH FROM AGE(NOW(), in_date)) > 1 THEN 's' ELSE '' END || ' ago '
                WHEN EXTRACT(DAY FROM AGE(NOW(), in_date)) > 0 THEN
                    EXTRACT(DAY FROM AGE(NOW(), in_date)) || ' day' || 
                    CASE WHEN EXTRACT(DAY FROM AGE(NOW(), in_date)) > 1 THEN 's' ELSE '' END || ' ago '
                WHEN EXTRACT(HOUR FROM AGE(NOW(), in_date)) > 0 THEN
                    EXTRACT(HOUR FROM AGE(NOW(), in_date)) || ' hour' || 
                    CASE WHEN EXTRACT(HOUR FROM AGE(NOW(), in_date)) > 1 THEN 's' ELSE '' END || ' ago '
                WHEN EXTRACT(MINUTE FROM AGE(NOW(), in_date)) > 0 THEN
                    EXTRACT(MINUTE FROM AGE(NOW(), in_date)) || ' minute' || 
                    CASE WHEN EXTRACT(MINUTE FROM AGE(NOW(), in_date)) > 1 THEN 's' ELSE '' END || ' ago '
                ELSE
                    'just now'
            END
        )
    );
END;
$$;


--
-- Name: delete_workspace_board(character varying, integer, integer, text, character varying, character varying); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.delete_workspace_board(IN in_type character varying, IN in_work_space_id integer, IN in_board_id integer, IN in_created_by text, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists INTEGER := 0;
    v_workspace_count INTEGER := 0;
    v_board_count INTEGER := 0;
    v_context TEXT;
BEGIN

    /*
      Author  : Mubarak Basha
      Purpose : Soft delete Workspace or Board
                - Prevent deletion if active tickets exist
                - Mark related entities inactive
    */

    -- WORKSPACE DELETE
    IF in_type = 'workspace' THEN

        -- Validate workspace existence
        SELECT COUNT(1)
        INTO v_exists
        FROM master.work_space_master
        WHERE work_space_id = in_work_space_id
          AND is_active = TRUE;

        IF v_exists = 0 THEN
            message := 'Workspace not found';
            status := 'false';
            RETURN;
        END IF;

        -- Validate tickets under workspace
        IF EXISTS (
            SELECT 1
            FROM tickets.ticket t
            JOIN tickets.tool_detail td 
                ON t.ticket_id = td.ticket_id 
               AND td.is_active = TRUE
            JOIN board.boardstatus bs 
                ON td.label_id = bs."LabelID"
            JOIN board.board b 
                ON bs."BoardID" = b."BoardID"
            WHERE t.is_active = TRUE
              AND t.is_process_order = TRUE
              AND b.work_space_id = in_work_space_id
              AND bs.is_active = TRUE
        ) THEN
            message := 'Cannot delete workspace. Active tickets exist.';
            status := 'false';
            RETURN;
        END IF;

        -- Soft delete workspace
        UPDATE master.work_space_master
        SET is_active = FALSE,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE work_space_id = in_work_space_id;

        GET DIAGNOSTICS v_workspace_count = ROW_COUNT;

        -- Soft delete boards under workspace
        UPDATE board.board
        SET is_active = FALSE,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE work_space_id = in_work_space_id;

        -- Soft delete labels under boards
        UPDATE board.boardstatus
        SET is_active = FALSE,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE "BoardID" IN (
            SELECT "BoardID"
            FROM board.board
            WHERE work_space_id = in_work_space_id
        );

        IF v_workspace_count > 0 THEN
            message := 'Workspace deleted successfully';
            status := 'true';
        ELSE
            message := 'Workspace deletion failed';
            status := 'false';
        END IF;

    -- BOARD DELETE
    ELSIF in_type = 'board' THEN

        -- Validate board existence
        SELECT COUNT(1)
        INTO v_exists
        FROM board.board
        WHERE "BoardID" = in_board_id
          AND work_space_id = in_work_space_id
          AND is_active = TRUE;

        IF v_exists = 0 THEN
            message := 'Board not found';
            status := 'false';
            RETURN;
        END IF;

        -- Validate tickets under board
        IF EXISTS (
            SELECT 1
            FROM tickets.ticket t
            JOIN tickets.tool_detail td 
                ON t.ticket_id = td.ticket_id
               AND td.is_active = TRUE
            JOIN board.boardstatus bs 
                ON td.label_id = bs."LabelID"
            WHERE t.is_active = TRUE
              AND t.is_process_order = TRUE
              AND bs."BoardID" = in_board_id
              AND bs.is_active = TRUE
        ) THEN
            message := 'Cannot delete board. Active tickets exist.';
            status := 'false';
            RETURN;
        END IF;

        -- Soft delete board
        UPDATE board.board
        SET is_active = FALSE,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE "BoardID" = in_board_id
          AND work_space_id = in_work_space_id;

        GET DIAGNOSTICS v_board_count = ROW_COUNT;

        -- Soft delete labels
        UPDATE board.boardstatus
        SET is_active = FALSE,
            last_updated_date = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            updated_by = in_created_by
        WHERE "BoardID" = in_board_id;

        IF v_board_count > 0 THEN
            message := 'Board deleted successfully';
            status := 'true';
        ELSE
            message := 'Board deletion failed';
            status := 'false';
        END IF;

    -- INVALID TYPE

    ELSE
        message := 'Invalid type. Use workspace or board';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'master.delete_workspace_board',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                in_type,
                in_work_space_id,
                in_board_id,
                in_created_by
            ))::TEXT
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: format_duration(bigint); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.format_duration(seconds bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    d int;
    h int;
    m int;
BEGIN
  /*
      Author  : Mubarak Basha
      Details : Convertaion data and time
    */
    IF seconds IS NULL THEN
        RETURN NULL;
    END IF;

    IF seconds < 60 THEN
        RETURN '<1m';
    END IF;

    d := seconds / 86400;
    h := (seconds % 86400) / 3600;
    m := (seconds % 3600) / 60;

    IF seconds < 3600 THEN
        RETURN m || 'm';

    ELSIF seconds < 86400 THEN
        IF m = 0 THEN
            RETURN h || 'h';
        ELSE
            RETURN h || 'h ' || m || 'm';
        END IF;

    ELSE
        IF h = 0 AND m = 0 THEN
            RETURN d || 'd';

        ELSIF h = 0 THEN
            RETURN d || 'd ' || m || 'm';

        ELSIF m = 0 THEN
            RETURN d || 'd ' || h || 'h';

        ELSE
            RETURN d || 'd ' || h || 'h ' || m || 'm';
        END IF;
    END IF;
END;
$$;


--
-- Name: format_duration_dashboard(bigint); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.format_duration_dashboard(seconds bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    d int;
    h int;
    m int;
    s int;
BEGIN
   /*
      Author  : Mubarak Basha
      Details : Convertaion data and time
    */
    IF seconds IS NULL THEN
        RETURN NULL;
    END IF;

    IF seconds < 0 THEN
        seconds := 0;
    END IF;

    d := seconds / 86400;
    h := (seconds % 86400) / 3600;
    m := (seconds % 3600) / 60;
    s := seconds % 60;

    -- Less than 1 minute
    IF seconds < 60 THEN
        RETURN s || 's';

    -- Less than 1 hour
    ELSIF seconds < 3600 THEN
        IF s = 0 THEN
            RETURN m || 'm';
        ELSE
            RETURN m || 'm ' || s || 's';
        END IF;

    -- Less than 1 day
    ELSIF seconds < 86400 THEN
        RETURN
            CASE WHEN h > 0 THEN h || 'h ' ELSE '' END ||
            CASE WHEN m > 0 THEN m || 'm ' ELSE '' END ||
            CASE WHEN s > 0 THEN s || 's' ELSE '' END;

    -- One day or more
    ELSE
        RETURN
            CASE WHEN d > 0 THEN d || 'd ' ELSE '' END ||
            CASE WHEN h > 0 THEN h || 'h ' ELSE '' END ||
            CASE WHEN m > 0 THEN m || 'm ' ELSE '' END ||
            CASE WHEN s > 0 THEN s || 's' ELSE '' END;
    END IF;
END;
$$;


--
-- Name: format_utc_to_local(timestamp without time zone, text); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.format_utc_to_local(p_utc_time timestamp without time zone, p_timezone text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	local_input_date TIMESTAMP;
BEGIN
SELECT public.convert_utc_to_localtime(p_utc_time,p_timezone ) INTO local_input_date;
    RETURN TO_CHAR(
        local_input_date,
        'DD Mon YYYY "at" HH12:MI AM'
    );
END;
$$;


--
-- Name: get_all_status_codes(text); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_all_status_codes(p_type text DEFAULT NULL::text) RETURNS TABLE(status_id integer, name character varying, type character varying, code character varying, colour_code text, back_ground_colour text, parent_code text)
    LANGUAGE plpgsql
    AS $$
BEGIN
--Created By    Date           Purpose
--Syed Abdhahir 19-06-2025     To fetch the LABELS
    RETURN QUERY
    SELECT 
        scm.status_id,
        scm.name,
        scm.type,
        scm.code,
        scm.colour_code,
        scm.back_ground_colour,
        scm.parent_code
    FROM master.status_code_master AS scm
    WHERE 
        (p_type IS NULL OR scm.type = p_type)
        AND (
            p_type != 'ORDERLABEL' 
            OR scm.is_active = true
        )
    ORDER BY 
        CASE 
            WHEN p_type = 'ORDERLABEL' THEN 
                CASE scm.name
                    WHEN 'Urgent' THEN 1
                    WHEN 'High' THEN 2
                    WHEN 'Medium' THEN 3
                    WHEN 'IPO' THEN 4
                END
            ELSE scm.status_id
        END;
END;
$$;


--
-- Name: get_all_workspaces_with_boards(integer); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_all_workspaces_with_boards(p_work_space_id integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
/*
Authour : Mubarak Basha
Details : To get the workspace with boards and relalted labels
Sprinit : Kanban Board - 5
*/
    SELECT jsonb_agg(
        jsonb_build_object(
            'workspaceId', w.work_space_id,
            'name', w.name,
			'workflowType', w.work_flow_type,
            'created_date', w.created_date,
            'created_by', w.created_by,
			   'user_info', (
                                SELECT COALESCE(
                                    jsonb_agg(
                                        jsonb_build_object(
                                            'regId', r."RegId",
                                            'photo', r.photo_url,
											'name',r."DisplayName",
											'email',r."Email"
                                        )
                                    ), '[]'::jsonb
                                )
                                FROM users.registereduser r
                                WHERE r."RegId" = w.created_by :: UUId
                            ),
            'boards', (
                SELECT COALESCE(
                    jsonb_agg(
                        jsonb_build_object(
                            'boardId', b."BoardID",
                            'name', b."Name",
                            'type', b."type",
                            'labels', (
                                SELECT COALESCE(
                                    jsonb_agg(
                                        jsonb_build_object(
                                            'labelId', s."LabelID",
                                            'name', s."Name",
                                            'color_code', s."ColorCode",
                                            'position', s."Position"
                                        )
										ORDER BY s."Position"
                                    ), '[]'::jsonb
                                )
                                FROM board.boardstatus s
                                WHERE s."BoardID" = b."BoardID" AND is_active = true
                            )
                        )
						ORDER BY b."BoardID"
                    ), '[]'::jsonb
                )
                FROM board.board b 
                WHERE b.work_space_id = w.work_space_id AND b.type = 'subtask'
                  AND b.is_active = true
		
            )
        )
    )
    INTO result
    FROM master.work_space_master w
    WHERE w.is_active = true AND (p_work_space_id IS NULL OR w.work_space_id = p_work_space_id);

    RETURN result;
END;
$$;


