--
-- Name: get_board_access_permission(uuid, integer, bigint, character varying); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_board_access_permission(in_reg_id uuid, in_work_space_id integer, in_ticket_id bigint DEFAULT NULL::bigint, in_user_type character varying DEFAULT NULL::character varying) RETURNS TABLE(access_permission boolean)
    LANGUAGE plpgsql
    AS $$

BEGIN
   
/*
Created By : Malarkodi Jaganathan
Description : Identifies if the user has permission for the board based on work_space_id.
*/

-- Check if the user type is 'Agency'
IF in_user_type = 'Agency' THEN
    RETURN QUERY 
    SELECT EXISTS (
        SELECT 1
        FROM board.board b
        JOIN board.departmentboard db ON db."BoardID" = b."BoardID" AND db.is_active = true
        JOIN master.department d ON db."DeptID" = d."DeptID" AND d.is_active = true
		JOIN users.userdepartment ud ON d."DeptID" = ud."DeptID" AND ud.is_active ='true'
		JOIN users.agency_user au ON ud."RegId" = au.reg_id AND au.is_active ='true'
		JOIN master.agency ag ON au.agency_id = ag.agency_id AND b."BoardID" = ag.board_id AND ag.is_active = true
        JOIN agency.agency_ticket at ON ag.board_id = at.ag_board_id AND at.is_active = true
        WHERE UPPER(d."DeptCode") = 'AG'
		AND au.reg_id = in_reg_id
		AND at.ag_ticket_id = in_ticket_id
		AND b.is_active ='true'
    );
ELSE
    -- For other user types or null user type
    RETURN QUERY 
    SELECT EXISTS (
        SELECT 1
        FROM users.registereduser ru
        JOIN users.user_work_space uw ON ru."RegId" = uw.reg_id AND uw.is_active = true
        JOIN master.work_space_master wm ON uw.work_space_id = wm.work_space_id AND wm.is_active = true
        LEFT JOIN board.board b ON wm.work_space_id = b.work_space_id AND b.is_active = true
		--JOIN board.departmentboard db ON db."BoardID" = b."BoardID" AND db.is_active = true
        --JOIN master.department d ON d."DeptID" = db."DeptID" AND d.is_active = true
        LEFT JOIN updates.updates_board ub ON wm.work_space_id = ub.work_space_id AND ub.is_active = true
        LEFT JOIN irapp.board pssb ON wm.work_space_id = pssb.work_space_id AND pssb.is_active = true
        WHERE wm.work_space_id = in_work_space_id
          AND ru."RegId" = in_reg_id
          AND ru.is_active = true AND
              CASE 
                  WHEN wm.code = 'IOD' THEN b."BoardID" IS NOT NULL
                  WHEN wm.code = 'UB' THEN ub.ub_id IS NOT NULL
                  WHEN wm.code = 'PSS' THEN pssb.board_id IS NOT NULL
                  WHEN wm.code = 'AG' THEN b."BoardID" IS NOT NULL
              END
    );
END IF;

END;
$$;


--
-- Name: get_board_participants(integer, integer); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_board_participants(workspaceid integer, boardid integer) RETURNS TABLE(regid uuid, photo bytea, displayname text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    
    IF workspaceid = 2 THEN
        RETURN QUERY
        SELECT DISTINCT 
            ru."RegId",
            ru."Photo",
            ru."DisplayName"
        FROM
            users.registereduser ru
        JOIN 
          	updates.updates_ticket_participant utp ON ru."RegId" = utp.ut_reg_id    
		JOIN 
			updates.updates_ticket ut on utp.ut_ticket_id=ut.ut_ticket_id
		Join  
			updates.updates_board ub  on  ut.ub_id=ub.ub_id
		where ub.ub_id=boardid
        ORDER BY 
            ru."DisplayName";
    END IF;
 
END;
$$;


--
-- Name: get_health_status(); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_health_status() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
BEGIN
   /*
      Author  : Mubarak Basha
      Details : Fetch Master Configuration
    */
	SELECT json_agg(t)
    INTO result
    FROM (
        SELECT 
            id,
            name,
            type,
            value
        FROM master.master_configuration mc
        WHERE mc.is_active = TRUE
          AND LOWER(mc.type) = LOWER('Health')
        ORDER BY mc.id
    ) t;

    RETURN COALESCE(result, '[]'::json);
END;
$$;


