--
-- Name: get_master_configuration(integer, character varying); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_master_configuration(p_config_id integer DEFAULT NULL::integer, p_config_type character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
BEGIN
   /*
      Author  : Mubarak Basha
      Details : Fetch Master Configuration
    */
    SELECT json_agg(t)
    INTO result
    FROM (
        SELECT *
        FROM master.master_configuration mc
        WHERE mc.is_active = TRUE
          AND (p_config_id IS NULL OR mc.id = p_config_id)
          AND (p_config_type IS NULL OR LOWER(mc.type) = LOWER(p_config_type))
        ORDER BY mc.id
    ) t;

    RETURN COALESCE(result, '[]'::json);
END;
$$;


