--
-- Name: get_user_workspaces(uuid); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_user_workspaces(userid uuid) RETURNS TABLE(work_space_id integer, name character varying, is_workspace_default boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if the user belongs to the department with DeptCode 'UT'
--     IF EXISTS (
--         SELECT 1 
--         FROM users.userdepartment usd 
--         JOIN master.department d ON usd."DeptID" = d."DeptID"
--         WHERE UPPER(d."DeptCode") = 'UT' AND usd."RegId" = userid
--     ) THEN
--         RETURN QUERY
--         SELECT
--             wm.work_space_id,
--             wm.name,
--             COALESCE(uwm.is_workspace_default, false) AS is_workspace_default
--         FROM
--             master.work_space_master wm
--         LEFT JOIN
--             master.user_default_work_space_mapping uwm ON wm.work_space_id = uwm.work_space_id and uwm.is_active=true AND uwm.reg_user_id = userid;
	IF EXISTS (
        SELECT 1 
        FROM users.user_work_space  
        WHERE reg_id= userid AND is_active ='true'
    ) THEN
        RETURN QUERY
        SELECT
            wm.work_space_id,
            wm.name,
            COALESCE(uwm.is_workspace_default, false) AS is_workspace_default
        FROM
            master.work_space_master wm
		JOIN users.user_work_space uws on wm.work_space_id = uws.work_space_id 
		and uws.reg_id = userid and uws.is_active ='true'
        LEFT JOIN
        master.user_default_work_space_mapping uwm ON wm.work_space_id = uwm.work_space_id 
	    and uwm.is_active=true AND uwm.reg_user_id = userid;
					
    ELSE
        RETURN QUERY
        SELECT
            wm.work_space_id,
            wm.name,
            true AS is_workspace_default
        FROM
            master.work_space_master wm
        WHERE
            UPPER(wm.code) = 'IOD';
    END IF;
END;
$$;


--
-- Name: get_user_workspaces_detail(uuid); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.get_user_workspaces_detail(userid uuid) RETURNS TABLE(work_space_id integer, name character varying, isdefault boolean, "workflowType" integer, board_ids jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_admin_status_id integer;
    v_superadmin_status_id integer;
BEGIN
    -- Fetch admin and superadmin status IDs
    SELECT
        MAX(CASE WHEN scm.name = 'Admin' THEN scm.status_id END),
        MAX(CASE WHEN scm.name = 'Super Admin' THEN scm.status_id END)
    INTO
        v_admin_status_id,
        v_superadmin_status_id
    FROM master.status_code_master scm
    WHERE scm.is_active = TRUE
      AND scm.type = 'USERROLE';

    -- Check if the user is an admin or superadmin
    IF EXISTS (
        SELECT 1
        FROM users.userprofile up
        WHERE up.user_id = userid
          AND up.user_type_id IN (v_admin_status_id, v_superadmin_status_id)
          AND up.is_active = true
    ) THEN
        RETURN QUERY
        SELECT 
            wm.work_space_id,
            wm.name,
            wm.is_active AS isDefault,
            wm.work_flow_type AS "workflowType",
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'boardID', b."BoardID",
                        'code', b.code,
                        'name', b."Name",
                        'isDefault', false,
                        'mainBoardID', COALESCE(b.main_board_id, b."BoardID"),
                        'mainBoardName', COALESCE(mb."Name", b."Name")
                    )
                ) FILTER (WHERE b."BoardID" IS NOT NULL),
                '[]'::jsonb
            ) AS board_ids
        FROM master.work_space_master wm
        LEFT JOIN board.board b
            ON wm.work_space_id = b.work_space_id
           AND b.is_active = true
           AND b.type = 'subtask'
        LEFT JOIN board.board mb
            ON mb."BoardID" = COALESCE(b.main_board_id, b."BoardID")
           AND mb.is_active = true
        WHERE wm.is_active = true
        GROUP BY wm.work_space_id, wm.name, wm.is_active, wm.work_flow_type;
    ELSE
        RETURN QUERY
        SELECT 
            wm.work_space_id,
            wm.name,
            wm.is_active AS isDefault,
            wm.work_flow_type AS "workflowType",
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'boardID', b."BoardID",
                        'code', b.code,
                        'name', b."Name",
                        'isDefault', b.is_active,
                        'mainBoardID', COALESCE(b.main_board_id, b."BoardID"),
                        'mainBoardName', COALESCE(mb."Name", b."Name")
                    )
                ) FILTER (WHERE b."BoardID" IS NOT NULL),
                '[]'::jsonb
            ) AS board_ids
        FROM users.user_board_permission ubp
        JOIN master.work_space_master wm
            ON ubp.workspace_id = wm.work_space_id
           AND wm.is_active = true
        JOIN board.board b
            ON ubp.board_id = b."BoardID"
           AND b.is_active = true
           AND b.type = 'subtask'
        LEFT JOIN board.board mb
            ON mb."BoardID" = COALESCE(b.main_board_id, b."BoardID")
           AND mb.is_active = true
        WHERE ubp.reg_id = userid
          AND ubp.is_active = true
        GROUP BY wm.work_space_id, wm.name, wm.is_active, wm.work_flow_type;
    END IF;
END;
$$;


