--
-- Name: getrolesettingdetail(); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.getrolesettingdetail() RETURNS TABLE(id uuid, permission text, type text, roleid integer, name character varying, ischecked boolean, depid integer, depcode character varying)
    LANGUAGE plpgsql
    AS $$
/* 
  -- Modified by || Modified Date || Purpose 
  -- Naveen S    || 16-11-2023    || Added the new role permission for Subscriptions
*/
BEGIN
	return query
       
	SELECT rs."Id", rs."Permission", rs."Type", rs."RoleId",r."Name", rs."Ischecked",rs.dept_id,d."DeptCode"
	FROM master.rolesetting rs
	JOIN master.role r on rs."RoleId" = r."RoleID" AND r.is_active = 'true'
	JOIN master.department d ON rs.dept_id = d."DeptID" AND d.is_active = 'true'
	WHERE rs.is_active = 'true'
	ORDER BY 
    CASE "Permission"
        WHEN 'User Management' THEN 1
        WHEN 'Department' THEN 2
        WHEN 'Tools' THEN 3
        WHEN 'Boards' THEN 4
		WHEN 'Board Status' THEN 5
		WHEN 'Tickets' THEN 6
        ELSE 7
    END;
END;

$$;


--
-- Name: insert_logdetail(text, text, text, text, timestamp without time zone, text); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.insert_logdetail(in_message text, in_stack_track text, in_exception text, in_apiurl text, in_log_date timestamp without time zone DEFAULT NULL::timestamp without time zone, in_user_id text DEFAULT NULL::text) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected integer;
BEGIN

/*

Root Cause:

The API itself threw an exception. While handling that exception, the middleware called master.insert_logdetail() to write the error into the database.

Inside master.insert_logdetail(), there was a ROLLBACK statement in the EXCEPTION block. Since insert_logdetail is a PL/pgSQL function (CREATE FUNCTION), PostgreSQL does not allow transaction control statements like COMMIT or ROLLBACK inside functions.

Therefore, instead of logging the original exception, PostgreSQL raised a new error:

2D000: invalid transaction termination

As a result, the original application error was masked by the logging function failure.
*/
    INSERT INTO public.logdetail
    (
        message,
        stack_track,
        log_date,
        exception,
        level,
        reg_id
    )
    VALUES
    (
        in_message,
        in_stack_track,
        in_log_date,
        in_exception,
        in_apiurl,
        CASE
            WHEN in_user_id IS NULL OR trim(in_user_id) = '' THEN NULL
            ELSE in_user_id::uuid
        END
    );

    GET DIAGNOSTICS affected = ROW_COUNT;

    IF affected > 0 THEN
        RETURN QUERY
        SELECT
            'Log details inserted successfully'::text,
            TRUE;
    ELSE
        RETURN QUERY
        SELECT
            'Log details insertion failed'::text,
            FALSE;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY
        SELECT
            SQLERRM,
            FALSE;
END;
$$;


--
-- Name: insert_update_agency(integer, text, text, uuid, boolean, text); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.insert_update_agency(IN in_agency_id integer DEFAULT 0, IN in_agency_code text DEFAULT NULL::text, IN in_agency_name text DEFAULT NULL::text, IN in_user_id uuid DEFAULT NULL::uuid, INOUT status boolean DEFAULT NULL::boolean, INOUT message text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    max_agency_id BIGINT;
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
	
BEGIN
 
   /*
     CALL master.insert_update_agency(
	   1,
	'testings', 
	'namess', 
	'3a3d7038-e4eb-4cd7-977d-a5d38e4e18e1'
)
   */
 
	IF(in_agency_id is null or  in_agency_id = 0) THEN
	--RAISE INFO 'if_agency_id: %', in_agency_id;
	--select the max id in master.update_agency table
 
    SELECT COALESCE(MAX(agency_id), 0) + 1 INTO max_agency_id  FROM master.agency;
 
    INSERT INTO  master.agency (
        agency_id,
        agency_name,
        agency_code,
        is_active,
		created_date,
		created_by
    )
    VALUES(
	    max_agency_id,
        in_agency_name,
        in_agency_code,
		'true',
		current_timestamp AT TIME ZONE 'UTC',
		in_user_id :: text
   );
  
  ELSE
  	--RAISE INFO 'else_agency_id: %', in_agency_id;
  		UPDATE master.agency
  		SET agency_name = in_agency_name,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
             updated_by = in_user_id :: text
        WHERE agency_id = in_agency_id AND
              is_active = 'true';
  END IF;
 
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
 
    -- Set status and message based on the result
    IF total_affected_rows > 0 THEN
	   IF (in_agency_id is null or  in_agency_id = 0) THEN
          status := 'true';
          message := 'New Agency Created Successfully!';
		ELSE
		   status := 'true';
           message := 'New Agency Updated Successfully!';
		END IF;
    ELSE
        status := 'false';
        message := 'An Error Occured, Contact admin';
    END IF;
 
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
        ROLLBACK;
        status := 'false';
END;
$$;


--
-- Name: insert_update_agency_package(text, uuid, integer, boolean, text); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.insert_update_agency_package(IN in_agency_package_name text DEFAULT NULL::text, IN in_user_id uuid DEFAULT NULL::uuid, IN in_agency_package_id integer DEFAULT 0, INOUT status boolean DEFAULT NULL::boolean, INOUT message text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$

DECLARE
    max_agency_package_id BIGINT;
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
	
BEGIN

	IF(in_agency_package_id is null or  in_agency_package_id = 0) THEN
    --RAISE INFO 'if_agency_id: %', in_agency_id;
	--select the max id in master.update_agencypackage table
 
    SELECT COALESCE(MAX(agency_package_id), 0) + 1 INTO max_agency_package_id  FROM master.agency_package;

    INSERT INTO  master.agency_package (
        agency_package_id,
        agency_package_name,
        is_active,
		created_date,
		created_by
    )
    VALUES(
	    max_agency_package_id,
        in_agency_package_name,
		'true',
		current_timestamp AT TIME ZONE 'UTC',
		in_user_id :: text
   );
   ELSE
  	--RAISE INFO 'else_agency_package_id: %', in_agency_package_id;
  		UPDATE master.agency_package
  		SET agency_package_name = in_agency_package_name,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
             updated_by = in_user_id :: text
        WHERE agency_package_id = in_agency_package_id AND
              is_active = 'true';
			  
  END IF;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;

    -- Set status and message based on the result
    IF total_affected_rows > 0 THEN
	 IF (in_agency_package_id is null or  in_agency_package_id = 0) THEN
        status := 'true';
        message := 'New Agency Package Created Successfully!';
    ELSE
	status := 'true';
           message := 'New Agency Package Updated Successfully!';
		END IF;
	Else
        status := 'false';
        message := 'An Error Occured, Contact admin';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
        ROLLBACK;
        status := 'false'; 
END;
$$;


--
-- Name: procedure_log_exception(text, text, uuid, timestamp without time zone, text); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.procedure_log_exception(IN p_source text, IN p_message text, IN p_added_by uuid, IN p_log_date timestamp without time zone, IN p_input_data text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO public.logdetail (
        message, 
        stack_track, 
        level, 
        log_date, 
        exception, 
        reg_id, 
        database_input
    )
    VALUES (
        p_message,             
        p_message,                 
        'Database ERROR',               
        p_log_date,             
        p_source,              
        p_added_by,             
        COALESCE(p_input_data::jsonb, '{}'::jsonb)       
    );
END;
$$;


--
-- Name: rolesetting_update(jsonb); Type: FUNCTION; Schema: master; Owner: -
--

CREATE FUNCTION master.rolesetting_update(input_json jsonb) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
	declare offected integer;

BEGIN
    UPDATE master.rolesetting as rs 
	SET "Ischecked" = (obj->>'status')::boolean  
	FROM  jsonb_array_elements(input_json) as arr(obj) 
	WHERE rs."Id" = (obj->>'id')::UUID
	AND is_active ='true';
	get diagnostics offected = ROW_COUNT;
		 
     IF(offected>0)
      THEN
		  return query select 'Updated sucessfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'Updated failed' as message,'false'::boolean as status;
	 END IF;
END;
$$;


