--
-- Name: set_default_workspace_to_user(uuid, integer, character varying, boolean); Type: PROCEDURE; Schema: master; Owner: -
--

CREATE PROCEDURE master.set_default_workspace_to_user(IN p_reg_user_id uuid, IN p_work_space_id integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status boolean DEFAULT NULL::boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
  max_user_mapping_id integer:= 0;
  current_default_workspace integer := NULL;
BEGIN
	 SELECT work_space_id INTO current_default_workspace
			FROM  master.user_default_work_space_mapping
			WHERE work_space_id = p_work_space_id
			  AND reg_user_id = p_reg_user_id 
			  AND is_workspace_default = true 
			  AND is_active = true
			LIMIT 1;

        -- User exists, deactivate existing mapping and insert new one
        UPDATE master.user_default_work_space_mapping
        SET  
		   is_workspace_default = false,
            is_active = false,  -- Deactivate existing entry 
            last_updated_date = current_timestamp,
            updated_by = p_reg_user_id
        WHERE reg_user_id = p_reg_user_id and is_workspace_default = true and is_active =  true;  
		
        -- Insert new mapping
	IF current_default_workspace IS NULL OR current_default_workspace != p_work_space_id THEN 
	 SELECT  COALESCE(MAX(user_mapping_id), 0) + 1 INTO max_user_mapping_id
   			FROM master.user_default_work_space_mapping;
    
        INSERT INTO master.user_default_work_space_mapping(
             user_mapping_id, reg_user_id, work_space_id, is_workspace_default,
            is_active, created_date, created_by 
        ) VALUES (
             max_user_mapping_id,p_reg_user_id, p_work_space_id, true,
           true, current_timestamp, p_reg_user_id 
        ); 
		
	END IF;
	message := 'Default Workspace Updated Successfully';
         status := 'true';
EXCEPTION  WHEN OTHERS
THEN
      ROLLBACK;
	   message := 'Error: ' || SQLERRM;
    --  message = 'Error occured during the Opeartion';
       status = 'false'; 
END;
$$;


--
-- Name: add_notification(character varying, text, text, character varying, integer, integer, text, character varying, character varying); Type: PROCEDURE; Schema: notification; Owner: -
--

CREATE PROCEDURE notification.add_notification(IN p_type character varying, IN p_recipient text, IN p_subject text, IN p_message character varying, IN p_retry_count integer DEFAULT 0, IN p_max_retries integer DEFAULT 3, IN p_message_json text DEFAULT NULL::text, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_notification_id UUID;
	v_message_json JSONB := COALESCE(p_message_json, '{}')::JSONB;
BEGIN
	
    -- Insert notification record

    INSERT INTO notification.notification (
        type,
        recipient,
        subject,
        message,
        status,
        retry_count,
        max_retries,
		created_at,
		message_json
    )
    VALUES (
        p_type,
        p_recipient,
        p_subject,
        p_message,
        'Pending',
        COALESCE(p_retry_count, 0),
		COALESCE(p_max_retries, 3),
		current_timestamp AT TIME ZONE 'UTC',
		v_message_json
    )
    RETURNING notification_id INTO v_notification_id;	

    -- Insert initial log entry
    INSERT INTO notification.notification_log (
        notification_id,
        attempt_at,
        status,
        error
    ) VALUES (
        v_notification_id,
        current_timestamp AT TIME ZONE 'UTC',
        'Pending',
        NULL
    );

    -- Set success response
    status := 'true';
    message := FORMAT('Notification successfully created with ID: %s', v_notification_id);

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS message = PG_EXCEPTION_DETAIL;
        message := SQLERRM;
        status := 'false';
END;
$$;


--
-- Name: get_page_notification(uuid); Type: FUNCTION; Schema: notification; Owner: -
--

CREATE FUNCTION notification.get_page_notification(regid uuid) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        jsonb_agg(notification_data) AS result
    FROM (
        SELECT 
            jsonb_build_object(
                'notification_id', n.notification_id,
                'type', n.type,
                'notify_type', n.message_json::jsonb ->> 'type',
                'header', n.message_json::jsonb ->> 'header',
                'notify_message', n.message_json::jsonb ->> 'notify_message',
                'ticket_id', (n.message_json::jsonb ->> 'ticket_id')::int,
                'board_id', (n.message_json::jsonb ->> 'board_id')::int,
                'moved_from', (n.message_json::jsonb ->> 'moved_from')::uuid,
                'moved_from_name', r."DisplayName",
                'moved_to', (n.message_json::jsonb ->> 'moved_to')::uuid,
                'moved_to_name', r1."DisplayName",
                'tool_id', (n.message_json::jsonb ->> 'tool_id')::int,
                'tool_ticket_id', (n.message_json::jsonb ->> 'tool_ticket_id')::int,
                'workspace_id', (n.message_json::jsonb ->> 'workspace_id')::int,
				'workspace_type', wsp.work_flow_type,
                'is_read', (n.message_json::jsonb ->> 'is_read')::boolean,
                'time_ago', master.calculate_time_ago(n.sent_at),
                'status', n.status
            ) AS notification_data
        FROM notification.notification n
        JOIN users.registereduser r 
            ON r."RegId" = (n.message_json::jsonb ->> 'moved_from')::uuid
        JOIN users.registereduser r1 
            ON r1."RegId" = (n.message_json::jsonb ->> 'moved_to')::uuid
		LEFT JOIN master.work_space_master wsp 
            ON wsp.work_space_id = (n.message_json::jsonb ->> 'workspace_id')::int AND wsp.is_active = true
        WHERE n.type = 'Push' 
          AND n.status = 'Sent'
          AND n.recipient = regid::text
		  AND n.subject != 'KANBAN_UPDATE'
        ORDER BY n.status DESC, n.sent_at DESC
    ) ordered_notifications;
	  
END;
$$;


--
-- Name: notify_channel_on_insert(); Type: FUNCTION; Schema: notification; Owner: -
--

CREATE FUNCTION notification.notify_channel_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    payload_json TEXT;
BEGIN
    payload_json := json_build_object(
        'id', NEW.notification_id,
        'type', NEW.type,
        'recipient', NEW.recipient,
        'subject', NEW.subject,
		'message', NEW.message,
		'status', NEW.status,
		'message_json', NEW.message_json
    )::TEXT;

    -- Send a NOTIFY event to the channel
    PERFORM pg_notify('notification_channel', payload_json);

    RETURN NEW;
END;
$$;


--
-- Name: update_notification(uuid, boolean, uuid, character varying, character varying); Type: PROCEDURE; Schema: notification; Owner: -
--

CREATE PROCEDURE notification.update_notification(IN p_notification_id uuid DEFAULT NULL::uuid, IN p_is_read boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_tool
Developer   : Aravindhan.B
Created On  : 10-10-2025
Purpose     : Update notification "is_read" field in message_json

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
10-10-2025  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context text;	
	v_count int;
	v_affected_rows int := 0;
BEGIN
    
    UPDATE notification.notification
    SET message_json = jsonb_set(
        message_json, 
        '{is_read}',                      
        to_jsonb(p_is_read),              
        true                             
    )
    WHERE notification_id = p_notification_id;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_affected_rows := v_affected_rows + v_count;
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN
        status := 'true';
        message := 'Status notification updated successfully.';
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';
    END IF;

EXCEPTION
    WHEN OTHERS THEN	
		ROLLBACK;		
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'notification.update_notification',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_notification_id, p_is_read, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: update_notification_readall_deleteall(uuid, text, uuid, character varying, boolean); Type: PROCEDURE; Schema: notification; Owner: -
--

CREATE PROCEDURE notification.update_notification_readall_deleteall(IN p_reg_id uuid, IN p_type text, IN p_added_by uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status boolean DEFAULT NULL::boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_count int := 0;
BEGIN

    -- Validate input
    IF p_reg_id IS NULL OR p_type IS NULL THEN
        message := 'Invalid input parameters.';
        status := false;
        RETURN;
    END IF;

    -- READ ALL
    IF LOWER(p_type) = 'readall' THEN

        UPDATE notification.notification n
        SET message_json = jsonb_set(
            n.message_json,
            '{is_read}',
            to_jsonb(true),
            true
        )
        WHERE n.recipient = p_reg_id::TEXT
          AND n.type = 'Push'
          AND n.subject <> 'KANBAN_UPDATE';

        GET DIAGNOSTICS v_count = ROW_COUNT;

    -- DELETE ALL
    ELSIF LOWER(p_type) = 'deleteall' THEN

        DELETE FROM notification.notification n
        WHERE n.recipient = p_reg_id::TEXT
          AND n.type = 'Push';

        GET DIAGNOSTICS v_count = ROW_COUNT;

    ELSE
        message := 'Invalid operation type.';
        status := false;
        RETURN;
    END IF;

    -- Final response
    IF v_count > 0 THEN
        message := 'Notification status updated successfully.';
        status := true;
    ELSE
        message := 'No records affected.';
        status := false;
    END IF;

EXCEPTION
    WHEN OTHERS THEN

        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'notification.update_notification_readall_deleteall',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            NOW() AT TIME ZONE 'UTC',
            row_to_json(ROW(p_reg_id, p_type, p_added_by))::text
        );

        message := SQLERRM;
        status := false;
END;
$$;


