--
-- Name: cleanup_ticketing_db(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.cleanup_ticketing_db()
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Disable triggers to avoid FK enforcement during truncate
    SET session_replication_role = replica;
 
    -- Truncate all dependent tables in one go
    TRUNCATE TABLE
        tickets.ticket_assignee,
        tickets.ticket_detail,
        tickets.ticket_status,
        tickets.ticket_work_log,
        tickets.tool_work_log,
        tickets.tool_board_log,
        tickets.tool_detail,
		tickets.tool_assignee,
        tickets.ticket_company,
        tickets.ticket_comments,
        tickets.ticket_attachment,
		tickets.tool_attachment,
        tickets.ticket_history,
        customers.customer_order,
        tickets.ticket,
		tickets.ticket_tool_info,
		tickets.tool_delete_reason,
       --customers.customer,
		tickets.ticket_board_tracker,
		tickets.ticket_status_track,
		tickets.tool_duedate_log,
		tickets.tool_history
    RESTART IDENTITY CASCADE;
 
    -- Enable triggers back
    SET session_replication_role = DEFAULT;
    RAISE NOTICE '✅ Database cleanup completed successfully.';
END;
$$;


