--
-- Name: delete_or_insert_tickets(integer, integer, integer[], integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_or_insert_tickets(in_ticket_id integer, in_subscription_type_id integer, in_tool_id_list integer[], in_user_id integer, subscription_name character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare variables as needed
    existing_tool_ids INT[];
    tools_to_remove INT[] := ARRAY[]::INT;
    i INT;
BEGIN
    -- DELETE logic
    IF in_tool_id_list IS NOT NULL AND array_length(in_tool_id_list, 1) > 0 THEN
        -- Create an array to store existing premium_ticket tool IDs
        SELECT array_agg(tool_id)
        INTO existing_tool_ids
        FROM tickets.premium_ticket
        WHERE ticket_id = in_ticket_id;

-- Identify tool IDs to be removed
FOR i IN 1..array_length(existing_tool_ids, 1) LOOP
    -- Check if the existing_tool_id is not present in in_tool_id_list
    IF existing_tool_ids[i] IS NOT NULL AND existing_tool_ids[i] = ANY(in_tool_id_list) THEN
        -- Add the existing_tool_id to the removal array
        tools_to_remove := tools_to_remove || existing_tool_ids[i];
    END IF;
END LOOP;



        -- Remove the identified tool IDs from premium_ticket
        IF array_length(tools_to_remove, 1) > 0 THEN
            DELETE FROM tickets.premium_ticket
            WHERE ticket_id = in_ticket_id AND tool_id = ANY(tools_to_remove);
        END IF;
    END IF;

    -- Insert associated tools in the appropriate ticket table
    IF in_tool_id_list IS NOT NULL AND array_length(in_tool_id_list, 1) > 0 THEN
        FOR i IN 1..array_upper(in_tool_id_list, 1) LOOP
            -- Insert logic for premium_ticket
            IF UPPER(subscription_name) = 'PREMIUM' THEN
                IF NOT EXISTS (
                    SELECT 1
                    FROM tickets.premium_ticket
                    WHERE ticket_id = in_ticket_id AND tool_id = in_tool_id_list[i]
                ) THEN
                    -- Insert statement for premium_ticket
                    INSERT INTO tickets.premium_ticket (
                        ticket_id,
                        subscription_type_id,
                        tool_id,
                        status,
                        is_active,
                        created_by,
                        created_date
                    ) VALUES (
                        in_ticket_id,
                        in_subscription_type_id,
                        in_tool_id_list[i],
                        'open',
                        'true',
                        in_user_id,
                        current_timestamp AT TIME ZONE 'UTC'
                    );
                END IF;
            ELSIF UPPER(subscription_name) = 'BASIC' THEN
                -- Insert statement for basic_ticket
                IF NOT EXISTS (
                    SELECT 1
                    FROM tickets.basic_ticket
                    WHERE ticket_id = in_ticket_id AND tool_id = in_tool_id_list[i]
                ) THEN
                    -- Insert statement for basic_ticket
                    INSERT INTO tickets.basic_ticket (
                        ticket_id,
                        subscription_type_id,
                        tool_id,
                        status,
                        is_active,
                        created_by,
                        created_date
                    ) VALUES (
                        in_ticket_id,
                        in_subscription_type_id,
                        in_tool_id_list[i],
                        'open',
                        'true',
                        in_user_id,
                        current_timestamp AT TIME ZONE 'UTC'
                    );
                END IF;
            ELSIF UPPER(subscription_name) = 'CUSTOM' THEN
                -- Insert statement for custom_ticket
                IF NOT EXISTS (
                    SELECT 1
                    FROM tickets.custom_ticket
                    WHERE ticket_id = in_ticket_id AND tool_id = in_tool_id_list[i]
                ) THEN
                    -- Insert statement for custom_ticket
                    INSERT INTO tickets.custom_ticket (
                        ticket_id,
                        subscription_type_id,
                        tool_id,
                        status,
                        is_active,
                        created_by,
                        created_date
                    ) VALUES (
                        in_ticket_id,
                        in_subscription_type_id,
                        in_tool_id_list[i],
                        'open',
                        'true',
                        in_user_id,
                        current_timestamp AT TIME ZONE 'UTC'
                    );
                END IF;
            END IF; -- subscription type conditions
        END LOOP;
    END IF;
END;
$$;


--
-- Name: format_stage_datetime(timestamp without time zone, text); Type: FUNCTION; Schema: public; Owner: -
