    );
$$;


--
-- Name: generate_json_format(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_json_format() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
BEGIN
    -- Aggregate roles and their associated departments
    SELECT jsonb_build_object(
        'name', 'Internal Order Delivery',
        'work_space_id', 'wk1',
        'roles', jsonb_agg(role_data)
    ) INTO result
    FROM (
        SELECT
            r."Name" AS name,
            jsonb_agg(
                jsonb_build_object(
                    'name', d."Name",
                    'permissionData', permission_data
                )
                ORDER BY d."Name"
            ) AS department
        FROM master.role r
        LEFT JOIN (
            SELECT
                rs."RoleId",
                d."Name",
                jsonb_agg(
                    jsonb_build_object(
                        'id', rs."Id",
                        'permission', rs."Permission",
                        'details', jsonb_build_object(
                            'type', 'Actions',
                            'data', jsonb_agg(jsonb_build_object(
                                jsonb_build_object(
                                    'name', rs."Permission",
                                    'ischecked', rs."Ischecked"
                                )
                                ORDER BY rs."Permission"
								)
                            )
                        )
                    )
                ) AS permission_data
            FROM master.rolesetting rs
            LEFT JOIN master.department d ON rs.dept_id = d."DeptID"
            GROUP BY rs."RoleId", d."Name"
        ) AS department_data ON r."RoleId" = department_data."RoleId"
        GROUP BY r."Name"
    ) AS role_data;

    RETURN result;
END;
$$;


--
-- Name: get_all_active_tickets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_active_tickets() RETURNS TABLE(ut_ticket_id integer, ut_ticket_no character varying, name character varying, description text, iod_ticket_id integer, due_date date, assigned_to integer, status_id integer, ub_id integer, ubl_id integer, u_customer_id integer, is_active boolean, created_date timestamp without time zone, created_by integer, last_updated_date timestamp without time zone, updated_by integer, "position" character varying, is_update_required boolean, ut_assign_to integer, announced_date date, current_financial_year integer, upcoming_release_date date)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ut.ut_ticket_id, 
        ut.ut_ticket_no, 
        ut.name, 
        ut.description, 
        ut.iod_ticket_id, 
        ut.due_date, 
        ut.assigned_to, 
        ut.status_id, 
        ut.ub_id, 
        ut.ubl_id, 
        ut.u_customer_id, 
        ut.is_active, 
        ut.created_date, 
        ut.created_by, 
        ut.last_updated_date, 
        ut.updated_by, 
        ut."position",  -- Again, quoting the reserved keyword here
        ut.is_update_required, 
        ut.ut_assign_to, 
        ut.announced_date, 
        ut.current_financial_year, 
        ut.upcoming_release_date
    FROM 
        updates.updates_ticket ut
    JOIN 
        updates.updates_board_list ubl 
    ON 
        ut.ubl_id = ubl.ubl_id
    WHERE 
        ubl.code IN ('NNU', 'SO') -- Filter for specific positions
        AND ut.is_active = true; -- Include only active tickets
END;
$$;


--
-- Name: get_board_participants(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_board_participants(workspacid integer, boardid integer) RETURNS TABLE(regid uuid, photo bytea, displayname text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    
    IF workspacid = 2 THEN
        RETURN QUERY
        SELECT DISTINCT 
            ru."RegId",
            ru."Photo",
            ru."DisplayName"
        FROM
            users.registereduser ru
        JOIN 
            updates.updates_ticket_participant utp ON ru."RegId" = utp.ut_reg_id    
        ORDER BY 
            ru."DisplayName";
    END IF;
 
END;
$$;


--
-- Name: get_board_participants_info(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_board_participants_info(added_by uuid, assign_to uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_info JSONB;
BEGIN
    user_info := (
        SELECT jsonb_agg(user_info)
        FROM (
            SELECT
                jsonb_build_object(
                    'regid', reguser."RegId",
                    'displayname', reguser."DisplayName",
                    'email', reguser."Email",
                    'photo', encode(reguser."Photo"::bytea, 'base64')
                ) AS user_info
            FROM
                users.registereduser reguser
            WHERE
                reguser."RegId" = added_by
                AND reguser.is_active = 'true'
            
            UNION
            
            SELECT
                jsonb_build_object(
                    'regid', reguser_ass."RegId",
                    'displayname', reguser_ass."DisplayName",
                    'email', reguser_ass."Email",
                    'photo', encode(reguser_ass."Photo"::bytea, 'base64')
                ) AS user_info
            FROM
                users.registereduser reguser_ass
            WHERE
                reguser_ass."RegId" = assign_to
                AND reguser_ass.is_active = 'true'
        ) AS user_infos
    );

    RETURN user_info;
END;
$$;


--
-- Name: get_comment_attachment_json(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_comment_attachment_json(comment_id bigint, comment_type integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    json_result JSON;
BEGIN 
	 CASE comment_type
        WHEN 1 THEN
           SELECT json_agg(
				json_build_object(
					'attachement_id', attachement_id,
					'file_type', file_type,
					'file_name', file_name,
					'file_upload_path', file_upload_path
				)
			) INTO json_result
            FROM tickets.ticket_attachment
			where comment_id=comment_id; 
            
        WHEN 2 THEN
			 SELECT json_agg(
				json_build_object(
					'attachement_id', attachement_id,
					'file_type', file_type,
					'file_name', file_name,
					'file_upload_path', file_upload_path
				)
			) INTO json_result
            FROM tickets.basic_ticket_attachment
			where comment_id=comment_id;            

        WHEN 3 THEN		
			 SELECT json_agg(
				json_build_object(
					'attachement_id', attachement_id,
					'file_type', file_type,
					'file_name', file_name,
					'file_upload_path', file_upload_path
				)
			) INTO json_result
            FROM tickets.premium_ticket_attachment
			where comment_id=comment_id;  
		WHEN 4 THEN		
			 SELECT json_agg(
				json_build_object(
					'attachement_id', attachement_id,
					'file_type', file_type,
					'file_name', file_name,
					'file_upload_path', file_upload_path
				)
			) INTO json_result
            FROM tickets.custom_ticket_attachment
			where comment_id=comment_id; 
		ELSE
            RAISE EXCEPTION 'Invalid table_type: %', table_type;
    END CASE;
    RETURN json_result;
END;
$$;


