--
-- Name: get_filter_date(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_filter_date(input_text text) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_date DATE;
BEGIN
     CASE input_text
        WHEN 'next_week' THEN
           -- Get the following week's Saturday (skip this week's Saturday)
            result_date := CURRENT_DATE + ((12 - EXTRACT(DOW FROM CURRENT_DATE)::INTEGER) % 7 + 1) * INTERVAL '1 day' + INTERVAL '7 days';
        WHEN 'next_month' THEN
            -- Get the last day of the next month
            result_date := (CURRENT_DATE + INTERVAL '1 month')::DATE + INTERVAL '1 month' - INTERVAL '1 day';
        WHEN 'next_day' THEN
            -- Get tomorrow's date
            result_date := CURRENT_DATE + INTERVAL '1 day';
        ELSE
            -- If the input doesn't match any case, raise an error
            RAISE EXCEPTION 'Invalid input: %', input_text;
    END CASE;
    RETURN result_date AS filter_date;
END;
$$;


