--
-- Name: get_iterations_main_module(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_iterations_main_module(in_ticket_id integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_build_object(
            'iterations_module', json_agg(
                json_build_object(
                    'iteration_id', mi.iteration_id,
                    'iteration_name', mi.iteration_name,
                    'created_by', json_build_array(
                        json_build_object(
                            'reg_id', ru."RegId",
                            'display_name', ru."DisplayName",
                            'mail', ru."Email"
                            -- 'photo', ru."Photo"  -- Uncomment if needed
                        )
                    ),
                    'created_date_time', mi.created_date,
                    'last_updated_by', CASE
                        WHEN mi.updated_by IS NOT NULL THEN json_build_array(
                            json_build_object(
                                'reg_id', ru."RegId",
                                'display_name', ru."DisplayName",
                                'mail', ru."Email"
                                -- 'photo', ru."Photo"  -- Uncomment if needed
                            )
                        )
                        ELSE NULL
                    END,
                    'data', (
                        SELECT json_agg(
                            json_build_object(
                                'module_detail_id', md.module_detail_id,
                                'module_id', md.module_id,
                                'name', md.name,
                                'sub_module_id', md.sub_module_id,  -- Modify this if you need nested children
                                'can_create_iteration', mi.can_create_iteration,  
                                'active_iteration_id', mi.status
                            )
                        )
                        FROM irapp.module_iteration_detail AS md
                        WHERE md.module_iteration_id = mi.module_iteration_id
                    )
                )
            ),
            'can_create_iteration', mi.can_create_iteration,  
            'active_iteration_id', mi.status
        ) AS result
        FROM irapp.module_iteration AS mi
        JOIN irapp.ticket AS it ON mi.ticket_id = it.ticket_id
        LEFT JOIN users.registereduser ru ON mi.created_by::uuid = ru."RegId"
        WHERE it.ticket_id = in_ticket_id  -- Using the function parameter
        AND mi.iteration_id = 'iteration_0'  -- Make sure 'iteration_0' is a valid iteration_id or replace with actual value
        GROUP BY mi.iteration_id, mi.iteration_name, mi.created_date, mi.updated_by, mi.can_create_iteration, mi.status
    );
END;
$$;


--
-- Name: get_lastest_customer_orderid(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lastest_customer_orderid(customer_id integer) RETURNS TABLE(customercode character varying, customerorderid character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE orderid character varying;
BEGIN

 
-- customerid + '-' + regionid + '-' + orderedID
--Eg : SF-MAN-66056 - 7774  - Customer code  - customer id - latest order id
 IF EXISTS (SELECT id FROM public.customer WHERE id = customer_id ) THEN

			SELECT id INTO orderid 
			FROM  public.customer_order customerid  
			WHERE customerid = 34699 ;

			  IF orderid IS NULL OR orderid = '' THEN
			  INSERT INTO public.customer_order(
				  customerid	  
			  )
			  VALUES(customer_id);

			  RETURN QUERY SELECT 
				  c.code as customercode,
				  CONCAT(c.code, '-', c.id, '-', co.id)::VARCHAR
			  FROM public.customer c 
			  JOIN 
				public.customer_order co ON c.id = co.customerid 
			WHERE 
				co.customerid = customer_id 
			ORDER BY 
				co.Created DESC
			  LIMIT 1;

			  ELSE

			 RETURN QUERY SELECT 
				c.code as customercode,
				CONCAT(c.code, '-', c.id, '-', co.id + 1)::VARCHAR

			FROM 
				public.customer c 
			 JOIN 
				public.customer_order co ON c.id = co.customerid 
			WHERE 
				co.customerid = customer_id 
			ORDER BY 
				co.Created DESC
			LIMIT 1;
			END IF;

			/* RETURN QUERY
				 /*   SELECT c.code as customercode
					, CONCAT(c.code ,'-', c.id ,'-', COALESCE((co.id) + 1, 1)) :: VARCHAR as customerordercode
					FROM public.customer c 
					JOIN public.customer_order co ON c.id = co.customerid 
					WHERE co.customerid = customer_id
					ORDER BY co.Created DESC
					LIMIT 1; */
					SELECT 
				c.code as customercode,
				CASE
					WHEN co.id IS NULL THEN CONCAT(c.code, '-', c.id, '0001')::VARCHAR
					ELSE CONCAT(c.code, '-', c.id, '-', co.id + 1)::VARCHAR
				END as customerordercode
			FROM 
				public.customer c 
			LEFT JOIN 
				public.customer_order co ON c.id = co.customerid 
			WHERE 
				co.customerid = customer_id OR co.customerid IS NULL
			ORDER BY 
				co.Created DESC
			LIMIT 1; */
			ELSE
					-- Return default values when customer_id doesn't exist
					RETURN QUERY
					SELECT NULL :: VARCHAR as customercode,
						   NULL :: VARCHAR as customerordercode;
 END IF;

END;
$$;


--
-- Name: get_localtime_updated_on(timestamp without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_localtime_updated_on(datetime_param timestamp without time zone, timezone_param text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_on_text TEXT;
	local_today_date TIMESTAMP;
	local_input_date TIMESTAMP;
    time_diff_minutes INTEGER;
BEGIN
	RAISE INFO 'date: %', datetime_param;
	RAISE INFO 'timezonedate: %', timezone_param;
	
	IF timezone_param is null or timezone_param = '' then
	 updated_on_text := TO_CHAR(datetime_param, 'Mon DD YYYY'); 
	 RAISE INFO 'updateontext: %', updated_on_text;
	else 
		SELECT public.convert_utc_to_localtime(now()::TIMESTAMP,timezone_param) INTO local_today_date; 
		RAISE INFO 'local_today_date: %', local_today_date;
		SELECT public.convert_utc_to_localtime(datetime_param,timezone_param ) INTO local_input_date;
		RAISE INFO 'local_input_date: %', local_input_date;
		--RAISE INFO 'CHECK: %',local_input_date::DATE = local_today_date - INTERVAL;
		 time_diff_minutes := EXTRACT(EPOCH FROM (local_today_date - local_input_date)) / 60;
		 
		IF DATE(local_input_date) = DATE(local_today_date) THEN
			 -- Calculate the time difference in minutes
--    	 IF time_diff_minutes < 60 THEN
-- 			  updated_on_text := time_diff_minutes || ' minutes ago';
-- 		 ELSE
			updated_on_text := 'Today';
--	 	 END IF;
		ELSIF DATE(local_input_date) = DATE(local_today_date) - INTERVAL '1 day' THEN
			updated_on_text := 'Yesterday';
-- 		ELSIF local_input_date >= DATE_TRUNC('week', local_today_date) THEN
-- 			updated_on_text := TO_CHAR(datetime_param, 'FMDay');
		ELSIF local_input_date >= DATE_TRUNC('year', local_today_date) THEN
			updated_on_text := TO_CHAR(local_input_date, 'Mon DD'); 
		ELSE
			updated_on_text := TO_CHAR(local_input_date, 'Mon DD YYYY'); 
		END IF;
		
		IF time_diff_minutes = 0 THEN
		    updated_on_text := 'just now';
		ELSIF time_diff_minutes < 60 THEN
			updated_on_text := time_diff_minutes || ' min ago';
		else
		updated_on_text := updated_on_text || ' at ' || TO_CHAR(local_input_date, 'HH12:MI am');
		END IF;
	end if;
	RAISE INFO 'updateontext1: %', updated_on_text;
    RETURN updated_on_text;
END;
$$;


