--
-- Name: get_notification(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification(regid uuid, page_number integer, page_size integer) RETURNS TABLE(notify_id integer, ticket_id bigint, board_id integer, moved_by uuid, photo bytea, notify_message character varying, status integer, time_ago text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT
        tn.id AS notify_id,
        tn.ticket_id,
        tn.board_id,
        tn.moved_by,
        ur."Photo" AS photo,
        tn.message AS notify_message,
        tn.status,
        CONCAT(
            EXTRACT(MINUTE FROM AGE(NOW(), tn.created_date)),
            ' mins ago'
        ) AS time_ago
    FROM
        tickets.ticket_notification tn
    JOIN
        users.registereduser ur ON ur."RegId" = tn.moved_by
    WHERE
        tn.is_active = 'true'
        AND ur.is_active = 'true'
        AND tn.status = 0
        AND moved_to = '21901d39-fe05-4bd9-b375-518da7041405'
    ORDER BY
        tn.id DESC
    OFFSET
        (page_number - 1) * page_size
    LIMIT
        page_size;
END;
$$;


