--
-- Name: insert_update_ticket_detail_with_tools(bigint, bigint, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, jsonb, integer[], integer[], integer, character varying, integer, boolean, character varying, timestamp without time zone, character varying, timestamp without time zone, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_update_ticket_detail_with_tools(p_ticket_detail_id bigint DEFAULT NULL::bigint, p_ticket_id bigint DEFAULT NULL::bigint, p_company_id integer DEFAULT NULL::integer, p_customer_code character varying DEFAULT NULL::character varying, p_company_name character varying DEFAULT NULL::character varying, p_phone_no character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_website character varying DEFAULT NULL::character varying, p_translation_approval character varying DEFAULT NULL::character varying, p_address character varying DEFAULT NULL::character varying, p_note character varying DEFAULT NULL::character varying, p_commondata jsonb DEFAULT NULL::jsonb, p_language_id integer[] DEFAULT '{}'::integer[], p_region_id integer[] DEFAULT '{}'::integer[], p_existing_subscription_type_id integer DEFAULT NULL::integer, p_existing_subscription_name character varying DEFAULT NULL::character varying, p_subscription_type_id integer DEFAULT NULL::integer, p_is_active boolean DEFAULT NULL::boolean, p_created_by character varying DEFAULT NULL::character varying, p_created_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_update_by character varying DEFAULT NULL::character varying, p_update_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_tool_data integer[] DEFAULT '{}'::integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existing_ticket_id BIGINT;
    tool_rec record;  -- Define a record variable for the loop
BEGIN

  -- call the function
--   -- Example parameters (adjust these values as needed)
-- DECLARE
--     p_ticket_detail_id BIGINT := 123;
--     p_ticket_id BIGINT := 456;
--     p_company_id INT := 789;
--     -- Add other parameters as needed

--     -- Example tool data
--     p_tool_data INT[][] := '{{1, 101, true}, {2, 102, false}}';

-- BEGIN
--     CALL insert_update_ticket_detail_with_tools(
--         p_ticket_detail_id := p_ticket_detail_id,
--         p_ticket_id := p_ticket_id,
--         p_company_id := p_company_id,
--         -- Add other parameters as needed
--         p_tool_data := p_tool_data
--     );
-- END;

    -- Check if the ticket already exists
    SELECT ticket_id INTO v_existing_ticket_id FROM ticketdetail WHERE ticket_id = COALESCE(p_ticket_id, ticket_id) LIMIT 1;

    IF v_existing_ticket_id IS NOT NULL THEN
        -- Update the existing ticketdetail record
        UPDATE ticketdetail
        SET
            company_id = COALESCE(p_company_id, company_id),
            customer_code = COALESCE(p_customer_code, customer_code),
            company_name = COALESCE(p_company_name, company_name),
            phone_no = COALESCE(p_phone_no, phone_no),
            email = COALESCE(p_email, email),
            website = COALESCE(p_website, website),
            translation_approval = COALESCE(p_translation_approval, translation_approval),
            address = COALESCE(p_address, address),
            note = COALESCE(p_note, note),
            commondata = COALESCE(p_commondata, commondata),
            language_id = COALESCE(p_language_id, language_id),
            region_id = COALESCE(p_region_id, region_id),
            existing_subscription_type_id = COALESCE(p_existing_subscription_type_id, existing_subscription_type_id),
            existing_subscription_name = COALESCE(p_existing_subscription_name, existing_subscription_name),
            subscription_type_id = COALESCE(p_subscription_type_id, subscription_type_id),
            is_active = COALESCE(p_is_active, is_active),
            update_by = COALESCE(p_update_by, update_by),
            update_date = COALESCE(p_update_date, update_date)
        WHERE ticket_id = COALESCE(p_ticket_id, ticket_id);
    ELSE
        -- Insert a new ticketdetail record
        INSERT INTO ticketdetail (
            ticket_id, company_id, customer_code, company_name, phone_no, email,
            website, translation_approval, address, note, commondata, language_id,
            region_id, existing_subscription_type_id, existing_subscription_name,
            subscription_type_id, is_active, created_by, created_date, update_by, update_date
        )
        VALUES (
            COALESCE(p_ticket_id, DEFAULT_VALUE),
            COALESCE(p_company_id, DEFAULT_VALUE),
            COALESCE(p_customer_code, DEFAULT_VALUE),
            COALESCE(p_company_name, DEFAULT_VALUE),
            COALESCE(p_phone_no, DEFAULT_VALUE),
            COALESCE(p_email, DEFAULT_VALUE),
            COALESCE(p_website, DEFAULT_VALUE),
            COALESCE(p_translation_approval, DEFAULT_VALUE),
            COALESCE(p_address, DEFAULT_VALUE),
            COALESCE(p_note, DEFAULT_VALUE),
            COALESCE(p_commondata, DEFAULT_VALUE),
            COALESCE(p_language_id, DEFAULT_VALUE),
            COALESCE(p_region_id, DEFAULT_VALUE),
            COALESCE(p_existing_subscription_type_id, DEFAULT_VALUE),
            COALESCE(p_existing_subscription_name, DEFAULT_VALUE),
            COALESCE(p_subscription_type_id, DEFAULT_VALUE),
            COALESCE(p_is_active, DEFAULT_VALUE),
            COALESCE(p_created_by, DEFAULT_VALUE),
            COALESCE(p_created_date, DEFAULT_VALUE),
            COALESCE(p_update_by, DEFAULT_VALUE),
            COALESCE(p_update_date, DEFAULT_VALUE)
        );
    END IF;

    -- Insert or update records in ticketorderedtool table
    FOR tool_rec IN SELECT * FROM UNNEST(COALESCE(p_tool_data, '{}'::INT[][])) AS t(tool_id INT, subscription_type_id INT, is_active BOOL)
    LOOP
        -- Check if the tool record already exists
        IF EXISTS (SELECT 1 FROM ticketorderedtool WHERE ticket_id = COALESCE(p_ticket_id, ticket_id) AND tool_id = tool_rec.tool_id LIMIT 1) THEN
            -- Update the existing tool record
            UPDATE ticketorderedtool
            SET
                subscription_type_id = COALESCE(tool_rec.subscription_type_id, subscription_type_id),
                is_active = COALESCE(tool_rec.is_active, is_active),
                update_by = COALESCE(p_update_by, update_by),
                update_date = COALESCE(p_update_date, update_date)
            WHERE ticket_id = COALESCE(p_ticket_id, ticket_id) AND tool_id = tool_rec.tool_id;
        ELSE
            -- Insert a new tool record
            INSERT INTO ticketorderedtool (
                ticket_id, tool_id, subscription_type_id, is_active, created_by, created_date, update_by, update_date
            )
            VALUES (
                COALESCE(p_ticket_id, DEFAULT_VALUE),
                COALESCE(tool_rec.tool_id, DEFAULT_VALUE),
                COALESCE(tool_rec.subscription_type_id, DEFAULT_VALUE),
                COALESCE(tool_rec.is_active, DEFAULT_VALUE),
                COALESCE(p_created_by, DEFAULT_VALUE),
                COALESCE(p_created_date, DEFAULT_VALUE),
                COALESCE(p_update_by, DEFAULT_VALUE),
                COALESCE(p_update_date, DEFAULT_VALUE)
            );
        END IF;
    END LOOP;
END;
$$;


--
-- Name: log_exception(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_exception(procedure_name text, message text, in_added_by uuid, input_timezone text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    log_json TEXT; 
    exception_context TEXT;
BEGIN
    -- Capture the exception context
    GET STACKED DIAGNOSTICS exception_context = PG_EXCEPTION_CONTEXT;

    -- Create the JSON object as text
    log_json := json_build_object(
        'procedure_name', procedure_name,
        'message', message,
        'stack_trace', exception_context,
        'exception_detail', SQLERRM,
        'log_timestamp', current_timestamp AT TIME ZONE 'UTC',
        'local_timestamp', public.get_localtime_updated_on(current_timestamp, input_timezone),
        'level', 'ERROR',
        'reg_id', in_added_by
    )::TEXT; 
    RETURN log_json;

EXCEPTION
    WHEN OTHERS THEN
        -- Handle failure to log the exception
        RETURN '{"error": "Failed to log exception", "message": "' || SQLERRM || '", "log_timestamp": "' || current_timestamp AT TIME ZONE 'UTC' || '"}';
END;
$$;


