--
-- Name: send_periodic_update_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_periodic_update_notifications() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    periodic_record RECORD;
    notification_message TEXT;
    notification_title TEXT;
    current_date DATE := CURRENT_DATE;
BEGIN
    -- Loop through records where release_date is today or before today
    FOR periodic_record IN
       SELECT 
    ud.ut_periodic_id, 
    ud.ut_ticket_id, 
    ud.periodic_id, 
    ud.release_date,
    uc.company_name
FROM 
    updates.ticket_periodic_detail ud
JOIN 
    updates.updates_customer uc 
    ON uc.customer_id = ud.u_customer_id 
JOIN 
    updates.updates_ticket ut  
    ON ud.ut_ticket_id = ut.ut_ticket_id
WHERE 
    ud.is_active = TRUE 
    AND ud.release_date <= current_date
    LOOP
        -- Determine the notification message
        IF periodic_record.release_date = current_date THEN
            notification_message := periodic_record.uc.company_name || 
                ' is scheduled for today to carry out a periodic update. Please take note.';
            notification_title := 'Periodic Update Scheduled for Today';
        ELSE
            notification_message := periodic_record.uc.company_name || 
                ' is scheduled to carry out a periodic update in 1 day. Please take note.';
            notification_title := 'Periodic Update Scheduled for Tomorrow';
        END IF;

        -- Insert notification into updates_ticket_notification table
        INSERT INTO updates.updates_ticket_notification (
            ut_ticket_id, 
            moved_by, 
            message, 
            status, 
            type, 
            is_active, 
            created_date, 
            created_by, 
            title
        )
        VALUES (
            periodic_record.ut_ticket_id,
            'System', -- Assuming "System" as the moved_by value
            notification_message,
            'Pending', -- Assuming "Pending" as the status
            'Notification', -- Assuming "Notification" as the type
            TRUE, -- is_active
            NOW(), -- created_date
            'System', -- created_by
            notification_title
        );
    END LOOP;
END;
$$;


--
-- Name: update_iteration_status(integer, integer, integer, integer, integer, text, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_iteration_status(p_ticket_id integer, p_module_iteration_id integer, p_module_iteration_detail_id integer, p_id integer, p_status_id integer, p_user_id text, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE 
	affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
	max_module_iteration_status_id INT;
	module_id_to_use INT;
    sub_module_id_to_use INT;
BEGIN
    -- Step 1: Validate if the iteration and iteration detail are active
    IF EXISTS (
        SELECT 1
        FROM irapp.module_iteration
        WHERE module_iteration_id = p_module_iteration_id
          AND is_active = TRUE
    ) AND EXISTS (
        SELECT 1
        FROM irapp.module_iteration_detail
        WHERE module_iteration_id = p_module_iteration_id
		  AND module_detail_id = p_module_iteration_detail_id
          AND (module_id = p_id OR sub_module_id=p_id)
          AND is_active = TRUE
    ) THEN
	
     -- Step 2: Determine if module_id or sub_module_id should be used
              SELECT 
            module_id,
            sub_module_id
        INTO 
            module_id_to_use, 
            sub_module_id_to_use
        FROM irapp.module_iteration_detail
        WHERE module_iteration_id = p_module_iteration_id
          AND module_detail_id = p_module_iteration_detail_id
          AND (module_id = p_id OR sub_module_id = p_id) AND is_active ='true'; 
		  
	 SELECT COALESCE(MAX(module_iteration_status_id), 0) + 1 INTO max_module_iteration_status_id
         FROM irapp.module_iteration_status;
        -- Step 2: Insert into module_iteration_status table
        INSERT INTO irapp.module_iteration_status (
            module_iteration_status_id, -- Assuming this is auto-increment
            module_detail_id,
			module_id,
            sub_module_id,
            status_id,
            is_active,
            created_date,
            created_by
        )
        VALUES(
            max_module_iteration_status_id,
            p_module_iteration_detail_id,
            p_status_id,
			module_id_to_use,
			sub_module_id_to_use,
			'true',
            current_timestamp AT TIME ZONE 'UTC',
			p_user_id ::UUID
        );
		
		GET DIAGNOSTICS affected_rows = ROW_COUNT;
        total_affected_rows := total_affected_rows + affected_rows;
        -- Step 3: Update the status_id in module_iteration_detail
        UPDATE irapp.module_iteration_detail
        SET status_id = p_status_id,
            last_updated_date =current_timestamp AT TIME ZONE 'UTC',
            updated_by = p_user_id :: UUID
        WHERE module_iteration_id = p_module_iteration_id
          AND module_detail_id = p_id AND is_active ='true';
		  
		  
		  GET DIAGNOSTICS affected_rows = ROW_COUNT;
          total_affected_rows := total_affected_rows + affected_rows;
    ELSE
        RAISE NOTICE 'Iteration or Iteration Detail is not active.';
    END IF;
	
	 IF total_affected_rows > 0 THEN
		
                 message := 'Iteration Status updated successfully.';
                 -- Set status to 'true'
                 status := 'true';
        ELSE
                 -- If no changes were made
                 message := 'No changes made.';
                 status := 'false';
        END IF;
END;
$$;


--
-- Name: update_rolesetting(public.rolearray); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_rolesetting(roles public.rolearray) RETURNS TABLE(result_text text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    role_record master.rolesetting_type;
BEGIN
    -- Loop through the array elements
    FOREACH role_record IN ARRAY roles
    LOOP
        -- Access individual fields of the composite type
        result_text := 'ID: ' || role_record.id || ', Status: ' || role_record.status;
        -- Return each result in a table
        RETURN NEXT;
    END LOOP;
END;
$$;


--
-- Name: upsert_ticket(bigint, character varying, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone, character varying, boolean, character varying, timestamp without time zone, character varying, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_ticket(p_ticket_id bigint, p_name character varying DEFAULT NULL::character varying, p_ticket_no character varying DEFAULT NULL::character varying, p_description character varying DEFAULT NULL::character varying, p_order_id character varying DEFAULT NULL::character varying, p_order_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_due_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_status character varying DEFAULT NULL::character varying, p_is_active boolean DEFAULT NULL::boolean, p_created_by character varying DEFAULT NULL::character varying, p_created_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_update_by character varying DEFAULT NULL::character varying, p_update_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Try to update the existing record
    UPDATE ticket.ticket
    SET
        name = COALESCE(p_name, name),
        ticket_no = COALESCE(p_ticket_no, ticket_no),
        description = COALESCE(p_description, description),
        order_id = COALESCE(p_order_id, order_id),
        order_date = COALESCE(p_order_date, order_date),
        due_date = COALESCE(p_due_date, due_date),
        status = COALESCE(p_status, status),
        is_active = COALESCE(p_is_active, is_active),
        created_by = COALESCE(p_created_by, created_by),
        created_date = COALESCE(p_created_date, created_date),
        update_by = COALESCE(p_update_by, update_by),
        update_date = COALESCE(p_update_date, update_date)
    WHERE ticket_id = p_ticket_id;

    -- If the update affected zero rows, then insert a new record
    IF NOT FOUND THEN
        INSERT INTO ticket.ticket (
            ticket_id,
            name,
            ticket_no,
            description,
            order_id,
            order_date,
            due_date,
            status,
            is_active,
            created_by,
            created_date,
            update_by,
            update_date
        ) VALUES (
            p_ticket_id,
            COALESCE(p_name, DEFAULT_VALUE),
            COALESCE(p_ticket_no, DEFAULT_VALUE),
            COALESCE(p_description, DEFAULT_VALUE),
            COALESCE(p_order_id, DEFAULT_VALUE),
            COALESCE(p_order_date, DEFAULT_VALUE),
            COALESCE(p_due_date, DEFAULT_VALUE),
            COALESCE(p_status, DEFAULT_VALUE),
            COALESCE(p_is_active, DEFAULT_VALUE),
            COALESCE(p_created_by, DEFAULT_VALUE),
            COALESCE(p_created_date, DEFAULT_VALUE),
            COALESCE(p_update_by, DEFAULT_VALUE),
            COALESCE(p_update_date, DEFAULT_VALUE)
        );
    END IF;
END;
$$;


--
-- Name: add_or_update_history_details(bigint, bigint, text, uuid, uuid, uuid, timestamp with time zone, uuid, timestamp with time zone, integer, text, text, text, text, text); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.add_or_update_history_details(in_order_id bigint DEFAULT (0)::bigint, in_tool_ticket_id bigint DEFAULT (0)::bigint, in_content text DEFAULT NULL::text, in_user_id uuid DEFAULT NULL::uuid, in_assigned_by uuid DEFAULT NULL::uuid, in_assigned_to uuid DEFAULT NULL::uuid, in_assigned_date timestamp with time zone DEFAULT NULL::timestamp with time zone, in_created_by uuid DEFAULT NULL::uuid, in_created_date timestamp with time zone DEFAULT NULL::timestamp with time zone, in_ticket_status integer DEFAULT NULL::integer, in_uploaded_file_name text DEFAULT NULL::text, in_removed_file_name text DEFAULT NULL::text, in_downloaded_file_name text DEFAULT NULL::text, in_remarks text DEFAULT NULL::text, in_history_type text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_history_data JSONB;
	get_history_data JSONB;
    rows_affected INT;
    out_rows_affected INT;
	gen_uuid UUID;
	id UUID;
	max_history_id BIGINT;
BEGIN
    out_rows_affected := 0;	

-- Generate a UUID
SELECT uuid_generate_v4() INTO gen_uuid;
 RAISE INFO ' p_gen_uuid: %', gen_uuid;
 
	  -- convert the input parameters into json object 
	    new_history_data := jsonb_build_array(
        jsonb_build_object(
			'id',gen_uuid,
            'message', in_content,
            'assigned_by', in_assigned_by,
            'assigned_to', in_assigned_to,
            'assigned_date', in_assigned_date,
            'created_by', in_created_by,
            'created_date', in_created_date,
            --'move_ticket_label_from', in_move_ticket_label_from,
            --'move_ticket_label_to', in_move_ticket_label_to,
            --'move_ticket_board_from', in_move_ticket_board_from,
            --'move_ticket_board_to', in_move_ticket_board_to,
            'ticket_status', in_ticket_status,
            --'ticket_tool_status', in_ticket_tool_status,
			'uploaded_file_name',in_uploaded_file_name,
			'removed_file_name', in_removed_file_name,
			'downloaded_file_name',in_downloaded_file_name,
			'remarks',in_remarks,
			'history_type',in_history_type
        )
    );
	 
	-- insert/update the json data into ticket table table  
	 
	IF(in_order_id > 0 AND (in_tool_ticket_id IS NULL OR in_tool_ticket_id = 0)) THEN
	
       -- Get the ticket_history_data (Json Column) set in to  get_history_data local variable
	   
	   SELECT history_data INTO get_history_data FROM tickets.ticket_history 
	   WHERE ticket_id = in_order_id AND is_active = 'true';
	   
	   -- Select the max id in agency.agency_ticket
       SELECT COALESCE(MAX(history_id), 0) + 1 INTO max_history_id FROM tickets.ticket_history;
		
	    -- if get_history_data is not available insert the json data
		
		IF get_history_data IS NULL THEN
		 
		 --insert into tickets.ticket_history		
		 INSERT INTO tickets.ticket_history 
		 (
			history_id,
			ticket_id,
			history_data,
			is_active,
			created_date,
			created_by
		 )
		 VALUES
		 (
			max_history_id,
			in_order_id,
			new_history_data,
			'true',
			current_timestamp AT TIME ZONE 'UTC',
			in_user_id
		 );
			
		 -- Get the number of affected rows
         GET DIAGNOSTICS rows_affected = ROW_COUNT;
         RAISE NOTICE 'inserted  % rows', rows_affected;
			
		-- if get_history_data is available append the json data in Same row
        ELSE		 
			 --update into tickets.ticket_history			 
		 	UPDATE tickets.ticket_history
         	SET history_data = history_data :: jsonb|| new_history_data :: jsonb,
		 	last_updated_date = current_timestamp AT TIME ZONE 'UTC',
		 	updated_by = in_user_id 
         	WHERE ticket_id = in_order_id 
		 	AND is_active = 'true';	
		 
		 	-- Get the number of affected rows
           GET DIAGNOSTICS rows_affected = ROW_COUNT;
           RAISE NOTICE 'inserted  % rows', rows_affected;
        END IF;
END IF;
	 
	-- insert/update the json data into ticket table table  
	 
	IF in_tool_ticket_id > 0  THEN
	
       -- Get the ticket_history_data (Json Column) set in to  get_history_data local variable
	   
	   SELECT history_data INTO get_history_data FROM tickets.tool_history 
	   WHERE tool_ticket_id = in_tool_ticket_id AND is_active = 'true';
	   
	   -- Select the max id in agency.agency_ticket
       SELECT COALESCE(MAX(history_id), 0) + 1 INTO max_history_id FROM tickets.tool_history;
		
	    -- if get_history_data is not available insert the json data
		
		IF get_history_data IS NULL THEN
		 
		 --insert into tickets.ticket_history		
		 INSERT INTO tickets.tool_history 
		 (
			history_id,
			tool_ticket_id,
			history_data,
			is_active,
			created_date,
			created_by
		 )
		 VALUES
		 (
			max_history_id,
			in_tool_ticket_id,
			new_history_data,
			'true',
			current_timestamp AT TIME ZONE 'UTC',
			in_user_id
		 );
			
		 -- Get the number of affected rows
         GET DIAGNOSTICS rows_affected = ROW_COUNT;
         RAISE NOTICE 'inserted  % rows', rows_affected;
			
		-- if get_history_data is available append the json data in Same row
        ELSE		 
			 --update into tickets.ticket_history			 
		 	UPDATE tickets.tool_history
         	SET history_data = history_data :: jsonb|| new_history_data :: jsonb,
		 	last_updated_date = current_timestamp AT TIME ZONE 'UTC',
		 	updated_by = in_user_id 
         	WHERE tool_ticket_id = in_tool_ticket_id 
		 	AND is_active = 'true';	
		 
		 	-- Get the number of affected rows
           GET DIAGNOSTICS rows_affected = ROW_COUNT;
           RAISE NOTICE 'inserted  % rows', rows_affected;
        END IF;
END IF;
            -- Update the total affected rows
            out_rows_affected := out_rows_affected + rows_affected;
           RETURN out_rows_affected;
END;
$$;


--
-- Name: add_or_update_tool_ticket_info(integer, text, integer, text, text, text, text, text, text, text, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.add_or_update_tool_ticket_info(IN p_tool_ticket_info_id integer DEFAULT NULL::integer, IN p_name text DEFAULT NULL::text, IN p_tool_ticket_id integer DEFAULT NULL::integer, IN p_file_type text DEFAULT NULL::text, IN p_file_name text DEFAULT NULL::text, IN p_file_upload_path text DEFAULT NULL::text, IN p_type text DEFAULT NULL::text, IN p_description text DEFAULT NULL::text, IN p_blob_name text DEFAULT NULL::text, IN p_tool_link text DEFAULT NULL::text, IN p_blob_uri text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT p_message character varying DEFAULT NULL::character varying, INOUT p_status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.add_or_update_tool_ticket_info
Developer   : Mubarak Basha
Created On  : 10-Oct-2025
Purpose     : Insert or update tool ticket information (attachments/links)
*******************************************************************************/

DECLARE
    v_context TEXT;
    v_exists  BOOLEAN := FALSE;
    v_rowcount INTEGER := 0;
    v_tool_code TEXT;
    v_content TEXT;
    v_history_type TEXT;

BEGIN

    --  Get Tool ID
    SELECT mt."ToolCode"
    INTO v_tool_code
    FROM tickets.tool_detail td
    JOIN master.tool mt
        ON mt."ToolID" = td.tool_id
    WHERE td.tool_ticket_id = p_tool_ticket_id
    LIMIT 1;

   
    -- Check if record exists
 
    IF p_tool_ticket_info_id IS NOT NULL AND p_tool_ticket_info_id > 0 THEN
        SELECT EXISTS (
            SELECT 1 
            FROM tickets.ticket_tool_info 
            WHERE tool_ticket_info_id = p_tool_ticket_info_id
        )
        INTO v_exists;
    END IF;

    -- UPDATE
 
    IF v_exists THEN

        UPDATE tickets.ticket_tool_info
        SET
            name              = COALESCE(p_name, name),
            file_type         = COALESCE(p_file_type, file_type),
            file_name         = COALESCE(p_file_name, file_name),
            file_upload_path  = COALESCE(p_file_upload_path, file_upload_path),
            description       = COALESCE(p_description, description),
            blob_name         = COALESCE(p_blob_name, blob_name),
            blob_uri          = COALESCE(p_blob_uri, blob_uri),
            tool_link         = COALESCE(p_tool_link, tool_link),
            type              = COALESCE(p_type, type),
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
            updated_by        = p_added_by
        WHERE tool_ticket_info_id = p_tool_ticket_info_id;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
            p_status := 'true';
            p_message := CASE 
                            WHEN p_type = 'attachment' THEN 'Attachment updated successfully.'
                            ELSE 'Link updated successfully.'
                         END;

            --  Tool Based History
            IF v_tool_code = 'EUROLANDTOOL' THEN
                v_content := 'Task Info Updated';
                v_history_type := 'Task Info Updated';
            ELSE
                v_content := 'Tool Info Updated';
                v_history_type := 'Tool Info Updated';
            END IF;

            PERFORM tickets.add_or_update_history_details(
                in_tool_ticket_id => p_tool_ticket_id,
                in_content        => v_content,
                in_user_id        => p_added_by,
                in_created_by     => p_added_by,
                in_created_date   => current_timestamp AT TIME ZONE 'UTC',
                in_history_type   => v_history_type
            );

        ELSE
            p_status := 'false';
            p_message := 'No records were updated.';
        END IF;

    -- INSERT
    ELSE

        SELECT COALESCE(MAX(tool_ticket_info_id), 0) + 1
        INTO p_tool_ticket_info_id
        FROM tickets.ticket_tool_info;

        INSERT INTO tickets.ticket_tool_info (
            tool_ticket_info_id,
            name,
            tool_ticket_id,
            file_type,
            file_name,
            file_upload_path,
            type,
            description,
            blob_name,
            tool_link,
            blob_uri,
            is_active,
            created_date,
            created_by,
            last_updated_date,
            updated_by
        )
        VALUES (
            p_tool_ticket_info_id,
            p_name,
            p_tool_ticket_id,
            p_file_type,
            p_file_name,
            p_file_upload_path,
            p_type,
            p_description,
            p_blob_name,
            p_tool_link,
            p_blob_uri,
            TRUE,
            current_timestamp AT TIME ZONE 'UTC',
            p_added_by,
            current_timestamp AT TIME ZONE 'UTC',
            p_added_by
        );

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount > 0 THEN
		-- UPDATE tickets.ticket_tool_info
  --       SET
  --           last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
		-- 	updated_by = p_added_by 
  --       WHERE ticket_id = p_tool_ticket_info_id;
            p_status := 'true';
            p_message := CASE 
                            WHEN p_type = 'attachment' THEN 'Attachment added successfully.'
                            ELSE 'Link added successfully.'
                         END;

            --  Tool Based History
            IF v_tool_code = 'EUROLANDTOOL' THEN
                v_content := 'Task Info Added';
                v_history_type := 'Task Info Added';
            ELSE
                v_content := 'Tool Info Added';
                v_history_type := 'Tool Info Added';
            END IF;

            PERFORM tickets.add_or_update_history_details(
                in_tool_ticket_id => p_tool_ticket_id,
                in_content        => v_content,
                in_user_id        => p_added_by,
                in_created_by     => p_added_by,
                in_created_date   => current_timestamp AT TIME ZONE 'UTC',
                in_history_type   => v_history_type
            );

        ELSE
            p_status := 'false';
            p_message := 'Failed to insert record.';
        END IF;

    END IF;

EXCEPTION
    WHEN OTHERS THEN

        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.add_or_update_tool_ticket_info',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_tool_ticket_info_id, p_name, p_tool_ticket_id, 
                p_file_type, p_file_name, p_file_upload_path, p_type, 
                p_description, p_blob_name, p_tool_link, p_blob_uri, 
                p_added_by
            ))::TEXT
        );

        p_status := 'false';
        p_message := SQLERRM;

END;
$$;


--
-- Name: add_tool_to_existing_order(bigint, text, uuid, integer, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.add_tool_to_existing_order(IN p_ticket_id bigint DEFAULT 0, IN p_tools_details text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.add_tool_to_existing_order
Developer   : Mubarak Basha
Created On  : 11-08-2026
Purpose     : Add tool(s) to an existing order.
              - Reject if tool already exists for the same order type.
              - Insert tool_detail in Open status.
              - If order already process-ordered: place new tool on OB Open,
                notify, capture history, and reopen Completed main task to In Progress.
*******************************************************************************/
DECLARE
	v_context text;
	v_tools_json JSONB := COALESCE(NULLIF(TRIM(p_tools_details), '')::jsonb, '[]'::jsonb);
	v_tool_element JSONB;
	v_tool_id INTEGER;
	v_package INTEGER := 0;
	v_order_type INTEGER := 0;
	v_tools_ids INTEGER[];
	v_tool_exist INTEGER := 0;
	v_flow_id INT;
	v_tool_statusid INTEGER := 0;
	v_dep_code TEXT;
	v_is_processed BOOLEAN := FALSE;
	v_ob_boardid INTEGER := 0;
	v_ob_labelid INTEGER := 0;
	v_obm_boardid INTEGER := 0;
	v_main_inprogress_labelid INTEGER := 0;
	v_main_complete_labelid INTEGER := 0;
	v_ex_main_label_id INTEGER;
	v_new_logid INTEGER := 0;
	v_new_tool_ticket_id INTEGER;
	v_new_tool_ticket_ids INTEGER[] := ARRAY[]::INTEGER[];
	v_added_tool_names TEXT := '';
	v_tool_name TEXT;
	v_company_name TEXT;
	v_board_name TEXT;
	v_label_name TEXT;
	v_subject TEXT;
	v_recipient_email TEXT;
	v_recipient_push TEXT;
	v_email TEXT;
	v_reg TEXT;
	v_message TEXT;
	v_work_space_id INTEGER := 0;
	v_refresh JSONB;
	v_added_count INTEGER := 0;
	v_max_ticket_status_track_id INTEGER;
BEGIN
	IF COALESCE(p_ticket_id, 0) = 0 THEN
		message := 'Invalid ticket.';
		status := 'false';
		RETURN;
	END IF;

	IF NOT EXISTS (
		SELECT 1 FROM tickets.ticket
		WHERE ticket_id = p_ticket_id AND is_active = TRUE
	) THEN
		message := 'In-active ticket.';
		status := 'false';
		RETURN;
	END IF;

	IF jsonb_typeof(v_tools_json) <> 'array' OR jsonb_array_length(v_tools_json) = 0 THEN
		message := 'Tools details cannot be null or empty.';
		status := 'false';
		RETURN;
	END IF;

	SELECT COALESCE(is_process_order, FALSE)
	INTO v_is_processed
	FROM tickets.ticket
	WHERE ticket_id = p_ticket_id AND is_active = TRUE;

	SELECT "DeptCode" INTO v_dep_code
	FROM master.department
	WHERE is_active = TRUE AND upper("Name") = 'ON BOARDING'
	LIMIT 1;

	SELECT status_id INTO v_tool_statusid
	FROM master.status_code_master
	WHERE is_active = TRUE AND type = 'Tool' AND name = 'Open'
	LIMIT 1;

	IF v_is_processed THEN
		SELECT "BoardID" INTO v_ob_boardid
		FROM board.board
		WHERE code = 'OB' AND is_active = TRUE
		LIMIT 1;

		SELECT "LabelID" INTO v_ob_labelid
		FROM board.boardstatus
		WHERE "BoardID" = v_ob_boardid AND UPPER("Code") = 'OPEN' AND is_active = TRUE
		LIMIT 1;

		SELECT "BoardID" INTO v_obm_boardid
		FROM board.board
		WHERE code = 'OBM' AND is_active = TRUE
		LIMIT 1;

		SELECT
			MAX(CASE WHEN "Code" = 'INPROGRESS' THEN "LabelID" END),
			MAX(CASE WHEN "Code" = 'COMPLETED' THEN "LabelID" END)
		INTO v_main_inprogress_labelid, v_main_complete_labelid
		FROM board.boardstatus
		WHERE is_active = TRUE AND "BoardID" = v_obm_boardid;
	END IF;

	-- Validate all tools first (reject duplicates before any insert)
	FOR v_tool_element IN SELECT * FROM jsonb_array_elements(v_tools_json)
	LOOP
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(
				COALESCE(v_tool_element -> 'Package', v_tool_element -> 'package')
			) LIMIT 1),
			NULL
		) INTO v_package;

		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(
				COALESCE(v_tool_element -> 'OrderType', v_tool_element -> 'orderType')
			) LIMIT 1),
			NULL
		) INTO v_order_type;

		v_tools_ids := ARRAY(
			SELECT jsonb_array_elements_text(
				COALESCE(v_tool_element -> 'ToolsId', v_tool_element -> 'toolsId')
			)::INTEGER
		);

		IF v_order_type IS NULL OR v_order_type = 0 THEN
			message := 'Order type is required.';
			status := 'false';
			RETURN;
		END IF;

		IF v_tools_ids IS NULL OR array_length(v_tools_ids, 1) IS NULL THEN
			message := 'Tool id cannot be null or empty.';
			status := 'false';
			RETURN;
		END IF;

		FOREACH v_tool_id IN ARRAY v_tools_ids
		LOOP
			SELECT COUNT(*) INTO v_tool_exist
			FROM tickets.tool_detail
			WHERE ticket_id = p_ticket_id
			  AND order_type_id = v_order_type
			  AND tool_id = v_tool_id
			  AND is_active = TRUE;

			IF v_tool_exist > 0 THEN
				SELECT t."ToolName" INTO v_tool_name
				FROM master.tool t
				WHERE t."ToolID" = v_tool_id AND t.is_active = TRUE
				LIMIT 1;

				message := format(
					'Tool "%s" (ID %s) already exists for this order. Duplicate tools are not allowed.',
					COALESCE(v_tool_name, v_tool_id::text),
					v_tool_id
				);
				status := 'false';
				RETURN;
			END IF;

			SELECT flow_id INTO v_flow_id
			FROM board.tool_flow
			WHERE is_active = TRUE AND tool_id = v_tool_id
			LIMIT 1;

			IF v_flow_id IS NULL THEN
				message := format('Tool ID %s is not linked in any flow.', v_tool_id);
				status := 'false';
				RETURN;
			END IF;
		END LOOP;
	END LOOP;

	-- Insert tools
	FOR v_tool_element IN SELECT * FROM jsonb_array_elements(v_tools_json)
	LOOP
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(
				COALESCE(v_tool_element -> 'Package', v_tool_element -> 'package')
			) LIMIT 1),
			NULL
		) INTO v_package;

		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(
				COALESCE(v_tool_element -> 'OrderType', v_tool_element -> 'orderType')
			) LIMIT 1),
			NULL
		) INTO v_order_type;

		v_tools_ids := ARRAY(
			SELECT jsonb_array_elements_text(
				COALESCE(v_tool_element -> 'ToolsId', v_tool_element -> 'toolsId')
			)::INTEGER
		);

		FOREACH v_tool_id IN ARRAY v_tools_ids
		LOOP
			SELECT flow_id INTO v_flow_id
			FROM board.tool_flow
			WHERE is_active = TRUE AND tool_id = v_tool_id
			LIMIT 1;

			INSERT INTO tickets.tool_detail (
				ticket_id, subscription_type_id, tool_id, board_id, label_id,
				added_by, assign_to, status, status_id, dept_code,
				is_active, created_date, created_by, order_type_id, flow_id, position
			) VALUES (
				p_ticket_id, v_package, v_tool_id, NULL, NULL,
				p_added_by, NULL, 'Open', v_tool_statusid, v_dep_code,
				TRUE, current_timestamp AT TIME ZONE 'UTC', p_added_by, v_order_type, v_flow_id,
				(
					SELECT COALESCE(MAX(td.position), 0) + 1
					FROM tickets.tool_detail td
					WHERE td.ticket_id = p_ticket_id
					  AND td.is_active = true
				)
			)
			RETURNING tool_ticket_id INTO v_new_tool_ticket_id;

			v_new_tool_ticket_ids := array_append(v_new_tool_ticket_ids, v_new_tool_ticket_id);
			v_added_count := v_added_count + 1;

			SELECT t."ToolName" INTO v_tool_name
			FROM master.tool t
			WHERE t."ToolID" = v_tool_id AND t.is_active = TRUE
			LIMIT 1;

			v_added_tool_names := CASE
				WHEN v_added_tool_names = '' THEN COALESCE(v_tool_name, v_tool_id::text)
				ELSE v_added_tool_names || ', ' || COALESCE(v_tool_name, v_tool_id::text)
			END;

			-- If already process-ordered, place new tool on OB Open
			IF v_is_processed THEN
				SELECT COALESCE(MAX(tool_board_logid), 0) + 1
				INTO v_new_logid
				FROM tickets.tool_board_log;

				INSERT INTO tickets.tool_board_log (
					tool_board_logid,
					ticket_id,
					tool_ticket_id,
					moved_by,
					board_id,
					label_id,
					moved_date,
					sequence,
					action_id,
					created_date,
					created_by,
					is_active
				) VALUES (
					v_new_logid,
					p_ticket_id,
					v_new_tool_ticket_id,
					p_added_by,
					v_ob_boardid,
					v_ob_labelid,
					current_timestamp AT TIME ZONE 'UTC',
					1,
					NULL,
					current_timestamp AT TIME ZONE 'UTC',
					p_added_by,
					TRUE
				);
			END IF;
		END LOOP;
	END LOOP;

	IF v_added_count = 0 THEN
		message := 'No tools were added.';
		status := 'false';
		RETURN;
	END IF;

	PERFORM tickets.add_or_update_history_details(
		in_order_id => p_ticket_id,
		in_tool_ticket_id => 0,
		in_content => CONCAT('Added tool(s): ', v_added_tool_names),
		in_user_id => p_added_by,
		in_created_by => p_added_by,
		in_created_date => current_timestamp AT TIME ZONE 'UTC',
		in_uploaded_file_name => NULL,
		in_history_type => 'Tool Added'
	);

	-- Process-ordered ticket: notify + reopen completed main task + auto refresh
	IF v_is_processed THEN
		SELECT TRIM(name) INTO v_company_name
		FROM tickets.ticket
		WHERE ticket_id = p_ticket_id AND is_active = TRUE;

		SELECT "Name", work_space_id
		INTO v_board_name, v_work_space_id
		FROM board.board
		WHERE "BoardID" = v_ob_boardid AND is_active = TRUE;

		SELECT "Name" INTO v_label_name
		FROM board.boardstatus
		WHERE "BoardID" = v_ob_boardid AND "LabelID" = v_ob_labelid AND is_active = TRUE;

		v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_added_tool_names, '') || '" , "boardName": "' || COALESCE(v_board_name, '') || '" , "stage": "' || COALESCE(v_label_name, '') || '"}}';

		SELECT subject
		INTO v_subject
		FROM master.mailtemplate
		WHERE mailtemplatetype = 'NewCardArrived'
		  AND is_active = TRUE
		LIMIT 1;

		SELECT
			STRING_AGG(r."Email", ', ') AS recipient_email,
			STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
		INTO
			v_recipient_email,
			v_recipient_push
		FROM users.user_board_permission ubp
		JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = TRUE
		WHERE ubp.board_id = v_ob_boardid AND ubp.is_active = TRUE;

		FOR v_email IN SELECT unnest(string_to_array(COALESCE(v_recipient_email, ''), ','))
		LOOP
			v_email := trim(v_email);
			IF v_email <> '' THEN
				CALL notification.add_notification(
					p_type := 'Email',
					p_recipient := v_email,
					p_subject := v_subject,
					p_message := v_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := NULL,
					message := message,
					status := status
				);
			END IF;
		END LOOP;

		FOR v_reg IN SELECT unnest(string_to_array(COALESCE(v_recipient_push, ''), ','))
		LOOP
			v_reg := trim(v_reg);
			IF v_reg <> '' THEN
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_reg,
					p_subject := 'New Card',
					p_message := 'A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := '{
										"ticket_id": '|| p_ticket_id ||',
										"tool_id": 0,
										"tool_ticket_id": 0,
										"board_id": '|| v_ob_boardid ||',
										"moved_from": "'|| p_added_by ||'",
										"moved_to": "'|| v_reg ||'",
										"notify_message": "A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
										"is_read": false,
										"type": "moved the ticket",	
										"workspace_id": '|| COALESCE(v_work_space_id, 0) ||',
										"header": "New Card"
									   }'::text,
					message := message,
					status := status
				);
			END IF;
		END LOOP;

		-- If main task is Completed, reopen to In Progress
		SELECT label_id INTO v_ex_main_label_id
		FROM tickets.ticket_board_tracker
		WHERE ticket_id = p_ticket_id
		  AND board_id = v_obm_boardid
		  AND is_active = TRUE
		LIMIT 1;

		IF v_ex_main_label_id IS NOT NULL
		   AND v_main_complete_labelid IS NOT NULL
		   AND v_main_inprogress_labelid IS NOT NULL
		   AND v_ex_main_label_id = v_main_complete_labelid
		THEN
			UPDATE tickets.ticket_board_tracker
			SET label_id = v_main_inprogress_labelid,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = p_added_by
			WHERE ticket_id = p_ticket_id
			  AND board_id = v_obm_boardid
			  AND is_active = TRUE;

			SELECT COALESCE(MAX(id), 0) + 1
			INTO v_max_ticket_status_track_id
			FROM tickets.ticket_status_track;

			INSERT INTO tickets.ticket_status_track (
				id,
				ticket_id,
				board_id,
				label_id,
				moved_by,
				activity_date,
				is_active,
				created_by,
				created_date
			) VALUES (
				v_max_ticket_status_track_id,
				p_ticket_id,
				v_obm_boardid,
				v_main_inprogress_labelid,
				p_added_by,
				current_timestamp AT TIME ZONE 'UTC',
				'true',
				p_added_by,
				current_timestamp AT TIME ZONE 'UTC'
			);

			PERFORM tickets.add_or_update_history_details(
				in_order_id => p_ticket_id,
				in_tool_ticket_id => 0,
				in_content => 'Main task moved to In Progress because a new incomplete tool was added.',
				in_user_id => p_added_by,
				in_created_by => p_added_by,
				in_created_date => current_timestamp AT TIME ZONE 'UTC',
				in_uploaded_file_name => NULL,
				in_history_type => 'Ticket Movement'
			);
		END IF;

		v_refresh := jsonb_build_object(
			'tool_ticket_id', v_new_tool_ticket_ids,
			'ticket_id', p_ticket_id,
			'board_id', v_ob_boardid,
			'from_label_id', 0,
			'to_label_id', v_ob_labelid,
			'type', 'ADD',
			'added_by', p_added_by
		);

		autorefreshreq := (
			COALESCE(NULLIF(TRIM(autorefreshreq), ''), '[]')::jsonb || jsonb_build_array(v_refresh)
		)::text;
	END IF;

	new_ticket_id := p_ticket_id::integer;
	status := 'true';
	message := CASE
		WHEN v_is_processed THEN 'Tool(s) added and process-ordered to Onboarding Open successfully.'
		ELSE 'Tool(s) added successfully.'
	END;

EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
		GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
		CALL master.procedure_log_exception(
			'tickets.add_tool_to_existing_order',
			CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
			NULL,
			current_timestamp AT TIME ZONE 'UTC',
			row_to_json(ROW(p_ticket_id, p_tools_details, p_added_by))::TEXT
		);
		status := 'false';
		message := SQLERRM;
END;
$$;


--
-- Name: auto_move_ticket(integer, integer, boolean, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.auto_move_ticket(IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.auto_move_ticket
Developer   : Aravindhan.B
Created On  : 24-09-2025
Purpose     : Auto Ticket movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
19-09-2025  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context text;
	v_start_stage_id integer;
	v_end_stage_id integer;
	v_main_board_id integer;
	v_main_open_labelid integer;
	v_main_inprocess_labelid integer;
	v_main_complete_labelid integer;
	v_all_tool_ticket_id integer[];
	v_all_board_tool_ticket_id integer[];
	v_is_ticket_open_moved boolean;
	v_is_ticket_inprocess_moved boolean;
	v_is_ticket_completed_moved boolean;
	v_label_tool_count integer;
	v_exists boolean;
	v_not_exists boolean;
	v_ex_main_label_id integer; --exist label id
	v_cu_main_label_id integer; -- current label id
	v_max_ticket_tracker_id integer; --max of ticket tracker id
	v_max_ticket_status_track_id integer; --max of ticket tracker id
	v_affected_rows int := 0; -- track inserts/updates
	v_count int;  -- for diagnostics
	v_ob_boardid INTEGER := 0;
	
	v_total_open_count INTEGER := 0;
	v_total_completed_count INTEGER := 0;
	v_order_status_id INTEGER := 0;
BEGIN
  
  	--Get Main Board ID
  	SELECT main_board_id INTO v_main_board_id
	FROM board.board
	WHERE "BoardID" = p_board_id
	AND is_active = true;
  	
	-- Get Start Stage ID (first position)
	SELECT "LabelID"
	INTO v_start_stage_id
	FROM board.boardstatus 
	WHERE is_active = true
	  AND "BoardID" = p_board_id
	ORDER BY "Position" ASC
	LIMIT 1;

	-- Get End Stage ID (last position)
	SELECT "LabelID"
	INTO v_end_stage_id
	FROM board.boardstatus 
	WHERE is_active = true
	  AND "BoardID" = p_board_id
	ORDER BY "Position" DESC
	LIMIT 1;
	
	--Get Main stage label id
	SELECT 
		MAX(CASE WHEN "Code" = 'OPEN' THEN "LabelID" END) AS v_main_open_labelid,
		MAX(CASE WHEN "Code" = 'INPROGRESS' THEN "LabelID" END) AS v_main_inprocess_labelid,
		MAX(CASE WHEN "Code" = 'COMPLETED' THEN "LabelID" END) AS v_main_complete_labelid
	INTO v_main_open_labelid, v_main_inprocess_labelid, v_main_complete_labelid
	FROM board.boardstatus 
	WHERE is_active = true
	  AND "BoardID" = v_main_board_id;
	
	--Get all tool_ticket id
	SELECT array_agg(tool_ticket_id) 
	INTO v_all_tool_ticket_id
	FROM tickets.tool_detail
	WHERE ticket_id = p_ticket_id   -- use the input parameter
	  AND is_active = true;
	  	
	--Remove ticket label
	IF p_is_moved THEN
		SELECT (COUNT(DISTINCT label_id) = 0) INTO v_not_exists FROM 
		(
			SELECT DISTINCT ON (tool_ticket_id)
				   board_id, label_id, sequence
			FROM tickets.tool_board_log
			WHERE ticket_id = p_ticket_id
			  AND board_id = p_board_id
			  AND is_active = true
			  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
			  AND is_moved = false
			ORDER BY tool_ticket_id, sequence DESC
		) A;
		
		IF v_not_exists THEN
			DELETE FROM tickets.ticket_board_tracker 
			WHERE ticket_id = p_ticket_id AND board_id = v_main_board_id AND is_active = true;						
		END IF;
		
		status := 'true';
    	message := 'Removed the ticket in the board.';
		RETURN;
	END IF;
	
	SELECT "BoardID" INTO v_ob_boardid 
    FROM board.board 
    WHERE code = 'OB' AND is_active = TRUE;
	
	--Completed stage count
	SELECT COUNT(*) INTO v_total_completed_count FROM(
		SELECT DISTINCT ON (tool_ticket_id)
		   board_id, label_id, sequence
	FROM tickets.tool_board_log
	WHERE ticket_id = p_ticket_id
	  AND board_id = v_ob_boardid
	  --AND label_id = v_end_stage_id
	  AND is_active = true
	  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
	ORDER BY tool_ticket_id, sequence DESC) AS A WHERE label_id = v_end_stage_id;
	
	--Open stage count
	SELECT COUNT(*) INTO v_total_open_count FROM(
		SELECT DISTINCT ON (tool_ticket_id)
		   board_id, label_id, sequence
	FROM tickets.tool_board_log
	WHERE ticket_id = p_ticket_id
	  AND board_id = v_ob_boardid
	  --AND label_id = v_start_stage_id
	  AND is_active = true
	  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
	ORDER BY tool_ticket_id, sequence DESC) AS A WHERE label_id = v_start_stage_id;
	
	
	IF array_length(v_all_tool_ticket_id, 1) = v_total_open_count THEN
		SELECT status_id INTO v_order_status_id
		FROM master.status_code_master
		WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND name = 'Open';
	ELSIF array_length(v_all_tool_ticket_id, 1) = v_total_completed_count THEN
		SELECT status_id INTO v_order_status_id
		FROM master.status_code_master
		WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND name = 'Completed';
	ELSE
		SELECT status_id INTO v_order_status_id
		FROM master.status_code_master
		WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND name = 'In-Progress';	
	END IF;
	
	raise info 'a %, %', array_length(v_all_tool_ticket_id, 1), v_total_open_count;
	
	IF NOT EXISTS(SELECT 1 FROM tickets.ticket WHERE ticket_id = p_ticket_id AND status_id = v_order_status_id AND is_active = true) THEN
	    --UPDATE ticket table
		UPDATE tickets.ticket SET 
			status_id = v_order_status_id,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC',
			updated_by = p_added_by
		WHERE ticket_id = p_ticket_id AND is_active = true;	
	END IF;
	
	--Move to completed task
	SELECT 
		(COUNT(DISTINCT label_id) = 1 AND MIN(label_id) = v_end_stage_id) INTO v_is_ticket_completed_moved
	FROM (
		SELECT DISTINCT ON (tool_ticket_id)
			   board_id, label_id, sequence
		FROM tickets.tool_board_log
		WHERE ticket_id = p_ticket_id
		  AND board_id = p_board_id
		  AND is_active = true
		  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
		  --AND is_moved = false
		ORDER BY tool_ticket_id, sequence DESC
	) A;	
	
	--Move to Open label
	SELECT 
		(COUNT(DISTINCT label_id) = 1 AND MIN(label_id) = v_start_stage_id) INTO v_is_ticket_open_moved
	FROM (
		SELECT DISTINCT ON (tool_ticket_id)
			   board_id, label_id, sequence
		FROM tickets.tool_board_log
		WHERE ticket_id = p_ticket_id
		  AND board_id = p_board_id
		  AND is_active = true
		  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
		  --AND is_moved = false
		ORDER BY tool_ticket_id, sequence DESC
	) A;
	
	-- Move to other stage (neither Open nor Completed)
	SELECT 
		(COUNT(DISTINCT label_id) >= 1) INTO v_is_ticket_inprocess_moved
	FROM (
		SELECT DISTINCT ON (tool_ticket_id)
			   board_id, label_id, sequence
		FROM tickets.tool_board_log
		WHERE ticket_id = p_ticket_id
		  AND board_id = p_board_id
		  AND is_active = true
		  AND tool_ticket_id = ANY(v_all_tool_ticket_id)
		  AND label_id NOT IN (v_start_stage_id, v_end_stage_id)
		ORDER BY tool_ticket_id, sequence DESC
	) A;
	
-- 	RAISE INFO 'v_start_stage_id: %', v_start_stage_id;
-- 	RAISE INFO 'v_is_ticket_open_moved: %', v_is_ticket_open_moved::text;
-- 	RAISE INFO 'v_is_ticket_inprocess_moved: %', v_is_ticket_inprocess_moved::text;
-- 	RAISE INFO 'v_is_ticket_completed_moved: %', v_is_ticket_completed_moved::text;
			
		
	-- Check if the record exists
    SELECT EXISTS (
        SELECT 1
        FROM tickets.ticket_board_tracker
        WHERE ticket_id = p_ticket_id
          AND board_id = v_main_board_id
          AND is_active = true
    ) INTO v_exists;
	  
		SELECT label_id INTO v_ex_main_label_id
	FROM tickets.ticket_board_tracker
	WHERE ticket_id = p_ticket_id
	  AND board_id = v_main_board_id
	  AND is_active = true LIMIT 1;
	
	v_cu_main_label_id := 0;
	
	IF v_is_ticket_open_moved AND (v_ex_main_label_id IS NULL OR  v_ex_main_label_id != v_main_open_labelid) THEN --Moved to Open stage		
		v_cu_main_label_id := v_main_open_labelid;
	ELSIF v_is_ticket_inprocess_moved AND (v_ex_main_label_id IS NULL OR  v_ex_main_label_id != v_main_inprocess_labelid)  THEN --Moved to InProcess stage		
		v_cu_main_label_id := v_main_inprocess_labelid;		
	ELSIF v_is_ticket_completed_moved AND (v_ex_main_label_id IS NULL OR  v_ex_main_label_id != v_main_complete_labelid)  THEN --Moved to Completed stage		
		v_cu_main_label_id := v_main_complete_labelid;
	END IF;		
	
	IF v_cu_main_label_id != 0 THEN	
	
		IF v_exists THEN --Update label id
		
			UPDATE tickets.ticket_board_tracker SET
				label_id = v_cu_main_label_id,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = p_added_by
			WHERE ticket_id = p_ticket_id AND board_id = v_main_board_id;
			GET DIAGNOSTICS v_count = ROW_COUNT;
            v_affected_rows := v_affected_rows + v_count;
			
		ELSE --Insert label id

			SELECT COALESCE(MAX(ticket_tracker_id), 0) + 1 INTO v_max_ticket_tracker_id FROM tickets.ticket_board_tracker;

			INSERT INTO tickets.ticket_board_tracker (
				ticket_tracker_id,
				ticket_id,
				board_id,
				label_id,
				moved_date,
				created_date,
				created_by,
				is_active
			) VALUES (
				v_max_ticket_tracker_id,
				p_ticket_id,
				v_main_board_id,
				v_cu_main_label_id,
				current_timestamp AT TIME ZONE 'UTC',
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				TRUE
			);
			GET DIAGNOSTICS v_count = ROW_COUNT;
            v_affected_rows := v_affected_rows + v_count;			

		END IF;
		
		--Insert Status tracker
		SELECT COALESCE(MAX(id), 0) + 1 INTO v_max_ticket_status_track_id FROM tickets.ticket_status_track;
		
		INSERT INTO tickets.ticket_status_track (
			id,
			ticket_id,
			board_id,
			label_id,
			moved_by,
			activity_date,
			is_active,
			created_by,
			created_date
		) VALUES (
			v_max_ticket_status_track_id,
			p_ticket_id,
			v_main_board_id,
			v_cu_main_label_id,
			p_added_by,
			current_timestamp AT TIME ZONE 'UTC',
			'true',
			p_added_by,
			current_timestamp AT TIME ZONE 'UTC'
		);   
		GET DIAGNOSTICS v_count = ROW_COUNT;
        v_affected_rows := v_affected_rows + v_count;
			
		IF v_affected_rows > 0 THEN
			status := 'true';
    		message := 'Ticket successfully moved to the new label.';
		ELSE
			status := 'true';
			message := 'No change: Ticket remains in the current label.';
		END IF;
	ELSE
		status := 'false';
    	message := 'No change: Ticket remains in the current label.';
	END IF;		

EXCEPTION
    WHEN OTHERS THEN
		ROLLBACK;
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.auto_move_ticket',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_ticket_id, p_board_id, p_added_by))::text
        );
		
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: average_time_per_stage(date, date, integer, uuid, integer[], text, integer[], integer[], integer[], uuid[], integer[], integer[], integer[], integer[], integer[], integer[], integer[]); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.average_time_per_stage(p_from_date date, p_to_date date, p_usertypeid integer, p_regid uuid, p_workspaceids integer[], p_tasktype text, p_boardids integer[] DEFAULT NULL::integer[], p_ordertype integer[] DEFAULT NULL::integer[], p_order_labels integer[] DEFAULT NULL::integer[], p_assignee uuid[] DEFAULT NULL::uuid[], p_order_stage_list integer[] DEFAULT NULL::integer[], p_regionids integer[] DEFAULT NULL::integer[], p_marketids integer[] DEFAULT NULL::integer[], p_countryids integer[] DEFAULT NULL::integer[], p_taskduestatus integer[] DEFAULT NULL::integer[], p_free_flow_label_id integer[] DEFAULT NULL::integer[], p_tool_id integer[] DEFAULT NULL::integer[]) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_date date;
    v_to_date   date;
    ipo_id      int;
BEGIN

    /*
    Created_by  : Mubarak Basha
    Description : Average Time per Stage — Board View with filters.
                  Calculates per-stage Cards Entered/Exited, Average/Median/Max/Total
                  duration, and a board-level summary row. Subtask only (stage
                  durations are always subtask-grained via tool_ticket_id in
                  tool_board_log).
   */

    -- ── DATE NORMALISATION ────────────────────────────────────────────────────────
    v_from_date := LEAST   (p_from_date, p_to_date);
    v_to_date   := GREATEST(p_from_date, p_to_date);

    -- ── IPO LOOKUP ────────────────────────────────────────────────────────────────
    SELECT status_id
    INTO   ipo_id
    FROM   master.status_code_master
    WHERE  name      = 'IPO'
      AND  type      = 'ORDERLABEL'
      AND  is_active = TRUE
    LIMIT  1;

    RETURN QUERY
    WITH

    -- ── BOARD SCOPE ───────────────────────────────────────────────────────────────
    scoped_board AS MATERIALIZED (
        SELECT b."BoardID" AS board_id
        FROM   board.board b
        WHERE  b.is_active     = TRUE
          AND  b.work_space_id = ANY(p_workspaceids)
          AND  p_boardids IS NOT NULL
          AND  array_length(p_boardids, 1) = 1
          AND  b."BoardID"     = ANY(p_boardids)
    ),

    -- ── FINAL STAGE per board ─────────────────────────────────────────────────────
    final_stage AS MATERIALIZED (
        SELECT DISTINCT ON (b."BoardID")
            b."BoardID"  AS board_id,
            bs."LabelID" AS last_label_id
        FROM  board.board b
        JOIN  board.boardstatus bs
              ON bs."BoardID" = b."BoardID" AND bs.is_active = TRUE
        WHERE b.is_active = TRUE
        ORDER BY b."BoardID", bs."Position" DESC
    ),

    -- ── ALL STAGES on the scoped board (final stage excluded) ────────────────────
    board_stages AS MATERIALIZED (
        SELECT
            bs."BoardID"  AS board_id,
            bs."LabelID"  AS label_id,
            bs."Name"     AS stage_name,
            bs."Position" AS stage_order
        FROM  board.boardstatus bs
        JOIN  scoped_board sbd ON sbd.board_id = bs."BoardID"
        JOIN  final_stage fs   ON fs.board_id  = bs."BoardID"
        WHERE bs.is_active      = TRUE
          AND bs."LabelID"     <> fs.last_label_id
    ),

    -- ── LATEST LOG ROW per (tool_ticket_id, board_id) ────────────────────────────
    latest_log AS MATERIALIZED (
        SELECT DISTINCT ON (tbl.tool_ticket_id, tbl.board_id)
            tbl.tool_ticket_id,
            tbl.ticket_id,
            tbl.board_id,
            tbl.label_id,
            tbl.tool_board_logid
        FROM  tickets.tool_board_log tbl
        JOIN  scoped_board sbd ON sbd.board_id = tbl.board_id
        WHERE tbl.is_active = TRUE
          AND tbl.is_moved  = FALSE
        ORDER BY tbl.tool_ticket_id, tbl.board_id, tbl.sequence DESC
    ),

    -- ── FILTER CONTEXT ────────────────────────────────────────────────────────────
    filter_context AS MATERIALIZED (
        SELECT
            ll.tool_ticket_id,
            ll.board_id,
            t.order_type,
            ta.assignee_to,
            td.free_flow_label_id,
			td.priority_id,
			td.tool_id,
            tc.region_id,
            tc.country_id,
            t.primary_market,
           COALESCE(
					    CASE
					        WHEN tc.is_ipo
					            THEN t.order_label_id || ARRAY[ipo_id]
					        ELSE
					            t.order_label_id
					    END,
					    ARRAY[]::integer[]
					)
					||
					CASE
					    WHEN lower(p_tasktype) = 'subtask'
					        THEN COALESCE(td.priority_id, ARRAY[]::integer[])
					    ELSE
					        COALESCE(t.priority_id, ARRAY[]::integer[])
					END AS order_label
        FROM  latest_log ll
        JOIN  tickets.ticket t
              ON t.ticket_id = ll.ticket_id AND t.is_active = TRUE
        LEFT  JOIN tickets.tool_detail td
               ON td.tool_ticket_id = ll.tool_ticket_id AND td.is_active = TRUE
        LEFT  JOIN LATERAL (
            SELECT *
            FROM   tickets.ticket_company tc
            WHERE  tc.ticket_id = t.ticket_id
              AND  tc.is_active = TRUE
            ORDER  BY tc.ticket_company_id DESC
            LIMIT  1
        ) tc ON TRUE
        LEFT  JOIN LATERAL (
            SELECT ta2.assignee_to
            FROM   tickets.tool_assignee ta2
            WHERE  ta2.tool_board_logid                  = ll.tool_board_logid
              AND  ta2.is_active                         = TRUE
              AND  COALESCE(ta2.un_assigned_flag, FALSE) = FALSE
            ORDER  BY ta2.sequence DESC
            LIMIT  1
        ) ta ON TRUE
    ),

    -- ── FILTERED SUBTASKS ─────────────────────────────────────────────────────────
    filtered_tickets AS MATERIALIZED (
        SELECT DISTINCT fc.tool_ticket_id
        FROM   filter_context fc
        WHERE
            (p_ordertype IS NULL OR array_length(p_ordertype, 1) IS NULL
             OR COALESCE(fc.order_type && p_ordertype, FALSE))
        AND (p_order_labels IS NULL OR array_length(p_order_labels, 1) IS NULL
             OR COALESCE(fc.order_label && p_order_labels, FALSE))
        AND (p_free_flow_label_id IS NULL OR array_length(p_free_flow_label_id, 1) IS NULL
             OR COALESCE(fc.free_flow_label_id && p_free_flow_label_id, FALSE))
		AND ( p_tool_id IS NULL
        OR array_length(p_tool_id, 1) IS NULL
        OR fc.tool_id = ANY(p_tool_id))
        AND (p_assignee IS NULL OR array_length(p_assignee, 1) IS NULL
             OR fc.assignee_to = ANY(p_assignee))
        AND (p_regionids IS NULL OR array_length(p_regionids, 1) IS NULL
             OR COALESCE(fc.region_id && p_regionids, FALSE))
        AND (p_countryids IS NULL OR array_length(p_countryids, 1) IS NULL
             OR COALESCE(fc.country_id && p_countryids, FALSE))
        AND (p_marketids IS NULL OR array_length(p_marketids, 1) IS NULL
             OR COALESCE(fc.primary_market && p_marketids, FALSE))
    ),

    -- ── RAW TRANSITIONS ───────────────────────────────────────────────────────────
    raw_transitions AS MATERIALIZED (
        SELECT
            tbl.tool_ticket_id,
            tbl.board_id,
            tbl.label_id,
            tbl.sequence,
            tbl.created_date AS entry_date,
            LEAD(tbl.created_date) OVER (
                PARTITION BY tbl.tool_ticket_id, tbl.board_id
                ORDER BY tbl.sequence
            )                AS exit_date
        FROM  tickets.tool_board_log tbl
        JOIN  scoped_board sbd     ON sbd.board_id      = tbl.board_id
        JOIN  filtered_tickets ft  ON ft.tool_ticket_id = tbl.tool_ticket_id
        WHERE tbl.is_active = TRUE
          AND tbl.is_moved  = FALSE
    ),

    -- ── QUALIFYING VISITS ─────────────────────────────────────────────────────────
    qualifying_visits AS (
        SELECT
            rt.tool_ticket_id,
            rt.board_id,
            rt.label_id,
            rt.entry_date,
            rt.exit_date,
            (rt.exit_date - rt.entry_date) AS visit_duration
        FROM  raw_transitions rt
        WHERE rt.exit_date IS NOT NULL
          AND rt.entry_date::date >= v_from_date
          AND rt.exit_date::date  <= v_to_date
          AND (
              p_order_stage_list IS NULL
              OR array_length(p_order_stage_list, 1) IS NULL
              OR rt.label_id = ANY(p_order_stage_list)
          )
    ),

    -- ── PER CARD-STAGE DURATION ───────────────────────────────────────────────────
    card_stage_duration AS (
        SELECT
            tool_ticket_id,
            board_id,
            label_id,
            MIN(entry_date)     AS card_entry,
            MAX(exit_date)      AS card_exit,
            SUM(visit_duration) AS total_duration
        FROM  qualifying_visits
        GROUP BY tool_ticket_id, board_id, label_id
    ),

	occupancy_islands AS (
		    SELECT
		        tool_ticket_id,
		        board_id,
		        label_id,
		        card_entry,
		        card_exit,
		        MAX(card_exit) OVER (
		            PARTITION BY board_id, label_id
		            ORDER BY card_entry, card_exit, tool_ticket_id
		            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
		        ) AS prev_max_exit
		    FROM card_stage_duration
		),

	occupancy_groups AS (
		    SELECT
		        tool_ticket_id,
		        board_id,
		        label_id,
		        card_entry,
		        card_exit,
		        SUM(
		            CASE
		                WHEN prev_max_exit IS NULL OR card_entry > prev_max_exit
		                THEN 1
		                ELSE 0
		            END
		        ) OVER (
		            PARTITION BY board_id, label_id
		            ORDER BY card_entry, card_exit, tool_ticket_id
		        ) AS island_id
		    FROM occupancy_islands
		),
    stage_occupancy AS (
        SELECT
            board_id,
            label_id,
            island_id,
            MAX(card_exit) - MIN(card_entry) AS island_span
        FROM  occupancy_groups
        GROUP BY board_id, label_id, island_id
    ),
    stage_occupancy_total AS (
        SELECT
            board_id,
            label_id,
            SUM(island_span) AS total_occupancy
        FROM  stage_occupancy
        GROUP BY board_id, label_id
    ),

    -- ── PER STAGE AGGREGATION ─────────────────────────────────────────────────────
    stage_stats AS (
        SELECT
            bst.board_id,
            bst.label_id,
            bst.stage_name,
            bst.stage_order,
            COUNT(DISTINCT csd.tool_ticket_id)                   AS cards_entered,
            COUNT(DISTINCT csd.tool_ticket_id)                   AS cards_exited,
            SUM(csd.total_duration)                              AS total_time,
            -- Average: SUM(individual) / COUNT — not occupancy/count
           CASE
			    WHEN COUNT(DISTINCT csd.tool_ticket_id) = 0 THEN INTERVAL '0'
			    ELSE
			        SUM(csd.total_duration)
			        / COUNT(DISTINCT csd.tool_ticket_id)
			END AS average_time,                                        
            -- Median: over individual per-card totals
           EXTRACT(
					    EPOCH FROM MIN(csd.total_duration)
					) AS median_time_seconds,
            -- Max: longest individual card duration
            MAX(csd.total_duration)                               AS max_time
        FROM  board_stages bst
        LEFT  JOIN card_stage_duration csd
               ON  csd.board_id = bst.board_id
              AND  csd.label_id = bst.label_id
        GROUP BY bst.board_id, bst.label_id, bst.stage_name, bst.stage_order
    ),

    -- ── BOARD SUMMARY ─────────────────────────────────────────────────────────────
   board_summary AS (
    SELECT
        SUM(total_time) AS board_total_time,
        SUM(cards_exited) AS board_total_exited,
        CASE
            WHEN SUM(cards_exited) = 0
            THEN INTERVAL '0'
            ELSE SUM(total_time) / SUM(cards_exited)
        END AS board_average_time
    FROM stage_stats
)

    -- ── FINAL JSON OUTPUT ─────────────────────────────────────────────────────────
    SELECT
        CASE
            WHEN NOT EXISTS (SELECT 1 FROM scoped_board)
                THEN jsonb_build_object(
                    'status',         FALSE,
                    'message',        'Invalid or missing board selection. Provide exactly one board in p_boardids.',
                    'StageDurations', '[]'::jsonb
                )
            WHEN (SELECT board_total_exited FROM board_summary) = 0
                THEN jsonb_build_object(
                    'status',         TRUE,
                    'message',        'No stage duration data available for the selected criteria.',
                    'StageDurations', '[]'::jsonb,
                    'BoardSummary',   NULL
                )
            ELSE jsonb_build_object(
                'status',  TRUE,
                'message', 'Stage durations fetched successfully',
                'StageDurations', (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'stageOrder',           ss.stage_order,
                            'stageName',            ss.stage_name,
                            'cardsEntered',         ss.cards_entered,
                            'cardsExited',          ss.cards_exited,
                            'averageTimeSeconds',   EXTRACT(EPOCH FROM ss.average_time),
                            'averageTimeFormatted', master.format_duration_dashboard(EXTRACT(EPOCH FROM ss.average_time)::bigint),
                            'medianTimeSeconds',    COALESCE(ss.median_time_seconds, 0),
                            'medianTimeFormatted',  master.format_duration_dashboard(COALESCE(ss.median_time_seconds, 0)::bigint),
                            'maxTimeSeconds',       EXTRACT(EPOCH FROM COALESCE(ss.max_time, INTERVAL '0')),
                            'maxTimeFormatted',     master.format_duration_dashboard(EXTRACT(EPOCH FROM COALESCE(ss.max_time, INTERVAL '0'))::bigint),
                            'totalTimeSeconds',     EXTRACT(EPOCH FROM ss.total_time),
                            'totalTimeFormatted',   master.format_duration_dashboard(EXTRACT(EPOCH FROM ss.total_time)::bigint)
                        )
                        ORDER BY ss.stage_order
                    )
                   FROM stage_stats ss
					WHERE ss.cards_entered > 0
                ),
                'BoardSummary', (
                    SELECT jsonb_build_object(
                        'totalAverageTimeSeconds',   EXTRACT(EPOCH FROM bs.board_average_time),
                        'totalAverageTimeFormatted', master.format_duration_dashboard(EXTRACT(EPOCH FROM bs.board_average_time)::bigint),
                        'totalTimeSeconds',          EXTRACT(EPOCH FROM bs.board_total_time),
                        'totalTimeFormatted',        master.format_duration_dashboard(EXTRACT(EPOCH FROM bs.board_total_time)::bigint)
                    )
                    FROM board_summary bs
                )
            )
        END;

END;
$$;


--
-- Name: board_upcoming_deadlines(uuid, integer, integer[], text[], integer[], integer[], integer[], uuid[], integer[], integer[], integer[], integer[], integer[], integer[], integer[]); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.board_upcoming_deadlines(p_regid uuid, p_usertypeid integer, p_workspaceids integer[], p_status text[] DEFAULT NULL::text[], p_boardids integer[] DEFAULT NULL::integer[], p_ordertype integer[] DEFAULT NULL::integer[], p_order_labels integer[] DEFAULT NULL::integer[], p_assignee uuid[] DEFAULT NULL::uuid[], p_order_stage_list integer[] DEFAULT NULL::integer[], p_regionids integer[] DEFAULT NULL::integer[], p_marketids integer[] DEFAULT NULL::integer[], p_countryids integer[] DEFAULT NULL::integer[], p_taskduestatus integer[] DEFAULT NULL::integer[], p_free_flow_label_id integer[] DEFAULT NULL::integer[], p_tool_id integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_result jsonb;
    ipo_id int;
    v_completed_id int;
    v_overdue_id int;
    v_neardue_id int;
    v_ontrack_id int;

BEGIN
	/*
	Created by : Mubarak Basha 
	Description: Fetching the Overdue according to filters except taskduestatus
	SELECT tickets.board_upcoming_deadlines(
		'b78d1c3f-8ac7-4c04-a872-2f25d23d096c',
		46,
		Array [1],
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null
	)
	*/
	-- ACCESS
	-- IF p_usertypeid NOT IN (44,45) THEN
	
	--     RETURN jsonb_build_object(
	--         'status', FALSE,
	--         'message', 'Access denied'
	--     );
	-- END IF;
	
	-- STATUS LOOKUPS
	
	SELECT status_id
	INTO ipo_id
	FROM master.status_code_master
	WHERE name = 'IPO'
	  AND type = 'ORDERLABEL'
	  AND is_active = TRUE
	LIMIT 1;
	
	WITH
	final_stage AS (
	    SELECT DISTINCT ON (b."BoardID")
	        b."BoardID" AS board_id,
	        bs."LabelID" AS last_label_id
	    FROM board.board b
	    JOIN board.boardstatus bs
	        ON bs."BoardID" = b."BoardID"
	       AND bs.is_active = TRUE
	    WHERE b.is_active = TRUE
	    ORDER BY
	        b."BoardID",
	        bs."Position" DESC
	),
	
	-- LATEST LOG
	latest_log AS (
	    SELECT DISTINCT ON (tbl.tool_ticket_id, tbl.board_id)
	        tbl.tool_board_logid,
	        tbl.tool_ticket_id,
	        tbl.ticket_id,
	        tbl.board_id,
	        tbl.label_id,
			td.free_flow_label_id,
	        tbl.sequence
	    FROM tickets.tool_board_log tbl
		JOIN tickets.tool_detail td
		      ON td.tool_ticket_id = tbl.tool_ticket_id
		     AND td.is_active = TRUE
	    WHERE tbl.is_active = TRUE
	      AND tbl.is_moved  = FALSE
	    ORDER BY
	        tbl.tool_ticket_id,
	        tbl.board_id,
	        tbl.sequence DESC
	),
	
	-- TOOL BASE
	tool_base AS (
	    SELECT
	        ll.tool_ticket_id,
	        ll.ticket_id AS order_id,
	        td.tool_id,
	        ll.label_id,
			ll.free_flow_label_id,
	        CASE
	            WHEN mt."ToolName" = 'Euroland Tool'
	                THEN td.sub_task_name
	            WHEN mt."ToolName" IS NOT NULL
	                THEN mt."ToolName"
	            ELSE td.sub_task_name
	        END AS tool_name,
	        td.created_date::date,
	        COALESCE(dd.due_date, td.due_date)::date AS due_date,
	        ll.board_id,
	        b."Name" AS board_name,
	        b.work_space_id,
	        fs.last_label_id,
	        ta.assignee_to,
	        t.order_type,
	        CASE
	            WHEN tc.is_ipo = TRUE
	                THEN t.order_label_id || ARRAY[ipo_id]
	            ELSE t.order_label_id
	        END AS order_labels,
	        tc.region_id,
	        tc.country_id,
	        t.primary_market,
	        CASE
			    WHEN COALESCE(dd.due_date, td.due_date) < CURRENT_DATE
			         AND ll.label_id <> fs.last_label_id
			    THEN TRUE
			    ELSE FALSE
			END AS is_overdue
		FROM latest_log ll
		JOIN tickets.tool_detail td
			ON td.tool_ticket_id = ll.tool_ticket_id
		   AND td.is_active = TRUE
		LEFT JOIN master.tool mt
			ON mt."ToolID" = td.tool_id
			LEFT JOIN LATERAL (
			    SELECT dl.due_date
			    FROM tickets.tool_duedate_log dl
			    WHERE dl.tool_ticket_id = td.tool_ticket_id
			      AND dl.is_active = TRUE
			    ORDER BY dl.sequence DESC, dl.created_date DESC
			    LIMIT 1
			) dd ON TRUE
		JOIN final_stage fs
			ON fs.board_id = ll.board_id
		JOIN board.board b
			ON b."BoardID" = ll.board_id
		   AND b.is_active = TRUE
		JOIN tickets.ticket t
			ON t.ticket_id = ll.ticket_id
		   AND t.is_active = TRUE
		LEFT JOIN LATERAL (
			SELECT
				tc.region_id,
				tc.country_id,
				tc.is_ipo
			FROM tickets.ticket_company tc
			WHERE tc.ticket_id = t.ticket_id
			  AND tc.is_active = TRUE
			ORDER BY tc.ticket_company_id DESC
			LIMIT 1
		) tc ON TRUE
	
		-- LATEST ASSIGNEE FOR CURRENT BOARD LOG
		LEFT JOIN LATERAL (
			SELECT ta.assignee_to
			FROM tickets.tool_assignee ta
			WHERE ta.tool_board_logid = ll.tool_board_logid
			  AND ta.is_active = TRUE
			  AND COALESCE(ta.un_assigned_flag,FALSE) = FALSE
			ORDER BY ta.sequence DESC
			LIMIT 1
		) ta ON TRUE
	
		WHERE
			-- WORKSPACE
			b.work_space_id = ANY(p_workspaceids)
			-- BOARD FILTER
			AND (
				p_boardids IS NULL
				OR array_length(p_boardids,1) IS NULL
				OR ll.board_id = ANY(p_boardids)
			)
			-- ORDER TYPE
			AND (
				p_ordertype IS NULL
				OR array_length(p_ordertype,1) IS NULL
				OR COALESCE(t.order_type && p_ordertype,FALSE)
			)
			-- ORDER LABEL
		   AND (
					p_order_labels IS NULL
					OR array_length(p_order_labels, 1) IS NULL
					OR COALESCE(
						(
						    CASE
						        WHEN tc.is_ipo = TRUE
						        THEN t.order_label_id || ARRAY[ipo_id]
						        ELSE t.order_label_id
						    END
						    || COALESCE(td.priority_id, ARRAY[]::integer[])
						) && p_order_labels,
						FALSE
					)
				)
	
			-- FREE FLOW LABEL
			AND (
			    p_free_flow_label_id IS NULL
			    OR array_length(p_free_flow_label_id, 1) IS NULL
			    OR COALESCE(ll.free_flow_label_id && p_free_flow_label_id, FALSE)
	        )

			-- Tools
			AND (
				    p_tool_id IS NULL
				    OR array_length(p_tool_id, 1) IS NULL
				    OR td.tool_id = ANY(p_tool_id)
				)
			
			-- ASSIGNEE
			AND (
				p_assignee IS NULL
				OR array_length(p_assignee,1) IS NULL
				OR ta.assignee_to = ANY(p_assignee)
			)
			-- STAGE
			AND (
				p_order_stage_list IS NULL
				OR array_length(p_order_stage_list,1) IS NULL
				OR ll.label_id = ANY(p_order_stage_list)
			)
			-- REGION
			AND (
				p_regionids IS NULL
				OR array_length(p_regionids,1) IS NULL
				OR COALESCE(tc.region_id && p_regionids,FALSE)
			)
			-- COUNTRY
			AND (
				p_countryids IS NULL
				OR array_length(p_countryids,1) IS NULL
				OR COALESCE(tc.country_id && p_countryids,FALSE)
			)
			-- MARKET
			AND (
				p_marketids IS NULL
				OR array_length(p_marketids,1) IS NULL
				OR COALESCE(t.primary_market && p_marketids,FALSE)
			)
	),
	
	-- ORDER SUMMARY
	order_summary AS (
		SELECT
			tb.order_id,
			t.name AS task_name,
			MIN(tb.created_date) AS created_date,
			MIN(tb.due_date) AS due_date,
			COUNT(DISTINCT tb.tool_ticket_id) AS total_tools,
			COUNT(DISTINCT tb.tool_ticket_id) FILTER (
				WHERE tb.is_overdue = TRUE
			) AS overdue_tools
		FROM tool_base tb
		JOIN tickets.ticket t
			ON t.ticket_id = tb.order_id
		   AND t.is_active = TRUE
		WHERE tb.label_id <> tb.last_label_id
		GROUP BY
			tb.order_id,
			t.name
		HAVING COUNT(DISTINCT tb.tool_ticket_id) FILTER (
			WHERE tb.is_overdue = TRUE
		) > 0
	),
	
	-- RANK
	ranked_orders AS (
		SELECT *,
			   ROW_NUMBER() OVER (
				   ORDER BY due_date ASC
			   ) AS rn
		FROM order_summary
	)
	
	-- FINAL JSON
	SELECT jsonb_build_object(
		'UpcomingDeadlines',
		COALESCE(
			(
				SELECT jsonb_agg(
					jsonb_build_object(
						'orderId', order_id,
						'taskName', task_name,
						'createdDate', created_date,
						'totalToolCount', total_tools,
						'overdueToolCount', overdue_tools,
						'dueDate', due_date,
						'isOverdueHighlight', TRUE
					)
				)
				FROM ranked_orders
				WHERE rn <= 4
			),
			'[]'::jsonb
		),
		'UpcomingDeadlinesViewMore',
		COALESCE(
			(
				SELECT jsonb_agg(
					jsonb_build_object(
						'orderId', os.order_id,
						'taskName', os.task_name,
						'createdDate', os.created_date,
						'totalToolCount', os.total_tools,
						'overdueToolCount', os.overdue_tools,
						'dueDate', os.due_date,
						'isOverdueHighlight', TRUE,
						'listOfTools',
						(
							SELECT jsonb_agg(
								jsonb_build_object(
									'toolTicketId', x.tool_ticket_id,
									'toolName', x.tool_name,
									'dueDate', x.due_date,
									 'toolId', x.tool_id,
									'activeStages', x.active_stages
								)
								ORDER BY x.due_date ASC
							)
							FROM (
								SELECT
									tb.tool_ticket_id,
									tb.tool_name,
									tb.due_date,
									 tb.tool_id,
									jsonb_agg(
										DISTINCT jsonb_build_object(
											'boardId', b."BoardID",
											'boardName', b."Name",
											'workspaceId', wm.work_space_id,
											'workspaceName', wm.name,
											'isStageCompleted',
											CASE
												WHEN tb.label_id = fs.last_label_id
												THEN TRUE
												ELSE FALSE
											END,
	
											'stage',
											jsonb_build_object(
												'code', bs."Code",
												'name', bs."Name",
												'labelId', bs."LabelID",
												'labelName', bs."Name",
												'colorCode', bs."ColorCode"
											),
											'assignee',
											COALESCE(
	
												(
													SELECT jsonb_agg(
														DISTINCT jsonb_build_object(
															'regId', ru."RegId",
															'displayName', ru."DisplayName",
															'givenName', ru."GivenName",
															'photoUrl', ru.photo_url
														)
													)
													FROM users.registereduser ru
													WHERE ru."RegId" = tb.assignee_to
												),
												'[]'::jsonb
											)
										)
									) AS active_stages
								FROM tool_base tb
								JOIN board.board b
									ON b."BoardID" = tb.board_id
								LEFT JOIN master.work_space_master wm
									ON wm.work_space_id = b.work_space_id
								LEFT JOIN board.boardstatus bs
									ON bs."BoardID" = tb.board_id
								   AND bs."LabelID" = tb.label_id
								   AND bs.is_active = TRUE
								LEFT JOIN final_stage fs
									ON fs.board_id = tb.board_id
								WHERE tb.order_id = os.order_id
								  AND tb.label_id <> fs.last_label_id AND tb.due_date < CURRENT_DATE
								GROUP BY
									tb.tool_ticket_id,
									tb.tool_name,
									tb.due_date,
									 tb.tool_id
							) x
						)
					)
				)
				FROM ranked_orders os
			),
			'[]'::jsonb
		),
		'status', TRUE,
		'message', 'Overdue tasks fetched successfully'
)
INTO v_result;

RETURN v_result;

END;
$$;


