--     in_added_by := '7f47a253-0cda-4d5b-ac8b-43a4b076fe54',
--     in_comment_id := 0, -- 0 means insert; use actual ID to update
--     in_attachments := '[{"file_name":"doc1.pdf","file_path":"https://.../doc1.pdf"}]', -- JSON string
--     in_deleted_attachments := '', -- JSON string
--     in_mentions := '' -- JSON string or text array, based on your backend logic
    
