	-- Handle NULL in_comment_id
	in_comment_id := COALESCE(in_comment_id, 0);
	in_tool_ticket_id := COALESCE(in_tool_ticket_id, 0);

	-- Remove duplicates from mentions
	IF in_mentions IS NOT NULL THEN
		in_mention_value := (
			SELECT STRING_AGG(in_mention_values, ',')
			FROM (
				SELECT DISTINCT UNNEST(STRING_TO_ARRAY(in_mentions, ',')) AS in_mention_values
