		);
	END IF;

	-- Truncate content if it exceeds 200 characters
	truncated_content := LEFT(in_content, 200) || CASE WHEN LENGTH(in_content) > 200 THEN '...' ELSE '' END;

	-- Get comment type_id
	SELECT type_id INTO typeid
	FROM tickets.comments_type
	WHERE UPPER(type_name) = 'COMMENTS' AND is_active = true;

	--Tool comments vs Ticket comments
	IF in_tool_ticket_id > 0  AND in_comment_id = 0 THEN
	 SELECT COALESCE(MAX(comment_id), 0) + 1 INTO max_comment_id
		FROM tickets.tool_comments;
		INSERT INTO tickets.tool_comments (
			comment_id,
			ticket_id,
			tool_ticket_id,
			content,
			type_id,
			added_by,
			is_active,
			created_by,
			created_date
		)
		VALUES (
			max_comment_id,
			in_order_id,
			in_tool_ticket_id,
			in_content,
			typeid,
			in_added_by,
			true,
			in_added_by,
			current_timestamp AT TIME ZONE 'UTC'
		);
		GET DIAGNOSTICS affected_rows = ROW_COUNT;
		total_affected_rows := total_affected_rows + affected_rows;
 ELSEIF
    
     in_tool_ticket_id > 0 AND in_comment_id > 0 THEN
		-- UPDATE existing comment
		IF EXISTS (
			SELECT 1
			FROM tickets.tool_comments
			WHERE tool_ticket_id = in_tool_ticket_id
			  AND comment_id = in_comment_id
			  AND is_active = true
		) THEN
			UPDATE tickets.tool_comments
			SET content = in_content,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = in_added_by
			WHERE tool_ticket_id  = in_tool_ticket_id
			AND ticket_id = in_order_id
			  AND comment_id = in_comment_id
			  AND is_active = true;

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;
		END IF;
ELSIF 
-- INSERT new comment
	in_order_id > 0 AND (in_tool_ticket_id IS NULL OR in_tool_ticket_id = 0) AND in_comment_id = 0 THEN
	-- INSERT new ticket comment
		SELECT COALESCE(MAX(comment_id), 0) + 1 INTO max_comment_id
		FROM tickets.ticket_comments;

		INSERT INTO tickets.ticket_comments (
			comment_id,
			ticket_id,
