			type_id,
			added_by,
			is_active,
			created_by,
			created_date
		)
		VALUES (
			max_comment_id,
			in_order_id,
			in_content,
			typeid,
			in_added_by,
			true,
			in_added_by,
			current_timestamp AT TIME ZONE 'UTC'
		);
		GET DIAGNOSTICS affected_rows = ROW_COUNT;
		total_affected_rows := total_affected_rows + affected_rows;

	ELSIF 
	in_order_id > 0 AND (in_tool_ticket_id IS NULL OR in_tool_ticket_id = 0)  AND in_comment_id > 0 THEN
		-- UPDATE existing comment
		IF EXISTS (
			SELECT 1
			FROM tickets.ticket_comments
			WHERE ticket_id = in_order_id
			  AND comment_id = in_comment_id
			  AND is_active = true
		) THEN
			UPDATE tickets.ticket_comments
			SET content = in_content,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = in_added_by
			WHERE ticket_id = in_order_id
			  AND comment_id = in_comment_id
			  AND is_active = true;

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;
		END IF;
	END IF;

	--Handle attachments
	IF in_attachments IS NOT NULL THEN
		CALL tickets.insert_ticket_comments_with_attachments(
			in_order_id,
			in_tool_ticket_id,
			in_added_by,
			in_attachments => in_attachments,
			in_comment_id => COALESCE(NULLIF(in_comment_id, 0), max_comment_id),
			message => message,
			status => status
		);
	END IF;

	--Handle deleted attachments
	IF in_deleted_attachments IS NOT NULL THEN
		FOR deleted_attachment IN
			SELECT CAST(unnested_value AS BIGINT)
			FROM UNNEST(STRING_TO_ARRAY(in_deleted_attachments, ',')) AS unnested_value
		LOOP
			CALL tickets.delete_ticket_attachment(
				in_order_id => in_order_id,
				in_tool_ticket_id=> in_tool_ticket_id,
				in_file_id => deleted_attachment,
				in_added_by => in_added_by,
				message => message,
				status => status,
				affected_count => affected_count
			);
			total_affected_rows := total_affected_rows + affected_count;
		END LOOP;
	END IF;
	
	
	--Push Notification
	IF in_mentions IS NOT NULL THEN
	
		FOR in_mention_value IN 
        	SELECT DISTINCT UNNEST(STRING_TO_ARRAY(in_mentions, ',')) 
		LOOP
			
			DECLARE 
				v_notify_message TEXT := '';
				v_notify_subject TEXT := '';
				v_company_name TEXT := '';
				v_user_name TEXT := '';
				v_tool_name TEXT := '';
				v_tool_id integer := 0;

				-- Email
				v_email_subject Text := '';
				v_email_message TEXT := '';
				v_email_recipient TEXT := '';
				v_email_recipientName TEXT := '';
				v_email_tool_Id INTEGER := 0;
			BEGIN

				
				SELECT TRIM(name) INTO v_company_name 
				FROM tickets.ticket 
				WHERE ticket_id = in_order_id  AND is_active = true;
				
				
				
				SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = in_added_by AND is_active = true;

				SELECT "Email", "DisplayName" INTO v_email_recipient,v_email_recipientName FROM users.registereduser WHERE "RegId" = in_mention_value::uuid AND is_active = true;
				
				IF in_tool_ticket_id = 0 AND in_order_id > 0 THEN
					v_notify_subject := 'Mentioned in Card';
					v_notify_message := 'You were mentioned in a comment on the card: <b>' || COALESCE(v_company_name, '') || '</b> by <b>' || COALESCE(v_user_name, '') || '</b>.';
                   -- Ticket Comment user Mention Email
					v_email_subject := v_user_name || ' mentioned you in the Orion card' || COALESCE(v_company_name, ''); 
					v_email_message := jsonb_build_object(
                         'TemplateKey', 'TicketCommentMention',
                         'Payload', jsonb_build_object(
						     'mentionerName',COALESCE(v_user_name, ''),
			                 'userName',COALESCE(v_email_recipientName, ''),
                             'cardName', COALESCE(v_company_name, ''),
							 'date',to_char(current_timestamp AT TIME ZONE 'UTC', 'DD Mon YYYY "at" HH12:MI AM'),
							  'ticketId',COALESCE(in_order_id::text,'')
                            )
                     );

				ELSIF in_tool_ticket_id > 0 AND in_order_id > 0 THEN					
															
					SELECT "ToolName" , t."ToolID",t."ToolCode" INTO v_tool_name, v_tool_id, v_tool_code
					FROM tickets.tool_detail td
					JOIN master.tool t ON t."ToolID" = td.tool_id AND t.is_active = true
					WHERE td.tool_ticket_id = in_tool_ticket_id AND td.is_active = true;							
					
					 -- Take Based on Content type          //naveen
					IF v_tool_code = 'EUROLANDTOOL' THEN
						v_content := 'task';
						v_history_type := 'Task';
					ELSE
						v_content := 'tool';
						v_history_type := 'Tool';
					END IF;
				
					IF v_content = 'task' THEN
						SELECT sub_task_name INTO v_tool_name  FROM  tickets.tool_detail WHERE tool_ticket_id = in_tool_ticket_id AND is_active = true;
					END IF;
					
					SELECT tool_id INTO v_email_tool_Id  FROM  tickets.tool_detail WHERE tool_ticket_id = in_tool_ticket_id ;
				
					v_notify_subject := 'Mentioned in '|| v_history_type;
					v_notify_message := CASE 
										WHEN v_content = 'tool' THEN
											'You were mentioned in a comment on the ' || v_content ||
											' <b>' || COALESCE(v_tool_name, '') || '</b> for the card: <b>' ||
											COALESCE(v_company_name, '') || '</b> by <b>' ||
											COALESCE(v_user_name, '') || '</b>.'
										ELSE
											'You were mentioned in a comment on the ' || v_content ||
											' for the card: <b>' || COALESCE(v_company_name, '') || '</b> by <b>' ||
											COALESCE(v_user_name, '') || '</b>.'
										END;
										
					-- Tool Comment user Mention Email
					v_email_subject := v_user_name || ' mentioned you in the Orion card' || COALESCE(v_company_name, ''); 
					v_email_message := jsonb_build_object(
                         'TemplateKey', CASE WHEN v_content = 'task' THEN 'TaskCommentMention' ELSE 'ToolCommentMention' END,
                         'Payload', jsonb_build_object(
						     'mentionerName',COALESCE(v_user_name, ''),
							 'toolName',COALESCE(v_tool_name, ''),
			                 'userName',COALESCE(v_email_recipientName, ''),
                             'cardName', COALESCE(v_company_name, ''),
                             'date',to_char(current_timestamp AT TIME ZONE 'UTC', 'DD Mon YYYY "at" HH12:MI AM'),
							 'ticketId',COALESCE(in_order_id::text,''),
							 'toolId',COALESCE(v_email_tool_Id::text,'')						 
                            )
                     );
				END IF;								
				
				--Push Notification
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := in_mention_value::text,
					p_subject := v_notify_subject::text,
					p_message := v_notify_message::text,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := jsonb_build_object(
										'ticket_id',       in_order_id,
										'tool_id',         v_tool_id,
										'tool_ticket_id',  in_tool_ticket_id,
										'board_id',        v_board_id,
										'moved_from',      in_added_by::text,
										'moved_to',        in_mention_value::text,
										'notify_message',  v_notify_message,
										'is_read',         false,
										'type',            'mentions',
										'workspace_id',    0,
										'header',          v_notify_subject
									)::text,
					message := message,
					status := status
				);

				 -- Ticket/Tool comment mention user EMAIL Notification
                CALL notification.add_notification(
                    p_type := 'Email',
                    p_recipient := v_email_recipient::text,
                    p_subject := v_email_subject,
                    p_message := v_email_message,
                    p_retry_count := 0,
                    p_max_retries := 3,
                    p_message_json := null,
                    message := message,
                    status := status
                );
			END;		   		
		END LOOP;
	END IF;

	-- Final output handling
	IF total_affected_rows > 0 THEN
		IF in_comment_id > 0 THEN
			message := 'Your comment has been updated.';
		ELSE
			message := 'Your comment has been posted.';
		END IF;
		status := 'true';
		in_ticket_comment_id := COALESCE(max_comment_id, in_comment_id);
	ELSE
		message := 'Ticket comment insertion failed';
		status := 'false';
	END IF;
	EXCEPTION
		
		    WHEN OTHERS THEN
			  ROLLBACK;
			
             GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT; 
			 -- save the sql exception into public.logdetail table
           CALL master.procedure_log_exception
		   (
            'tickets.insert_update_ticket_comments',
            CONCAT('Error: ', SQLERRM, ' | Context: ', message),                    
             in_added_by ::UUID,         
            (current_timestamp AT TIME ZONE 'UTC'),
			row_to_json
			   (
				   ROW
				   (
					 in_order_id, 
					 in_tool_ticket_id,
					 in_content,
					 in_added_by,
					 in_comment_id,
					 in_attachments,
					 in_deleted_attachments,
					 in_mentions
				   )
			   )::text 
        );
            
        status := false;                   
        message := 'An error occurred while insert/update the Comment.';         
END;
$$;


--
-- Name: main_sub_board_refresh(integer[], integer, integer, integer, integer, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.main_sub_board_refresh(IN p_tool_ticket_id integer[] DEFAULT NULL::integer[], IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_from_label_id integer DEFAULT 0, IN p_to_label_id integer DEFAULT 0, IN p_action text DEFAULT ''::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_sub_task_data jsonb;
	v_main_task_data jsonb;
    ipo_id integer;
	v_flow_tool_list jsonb;
	v_filtered_flow_tool_list jsonb;
	v_ticket_data jsonb;
	v_main_board_id integer;
	v_main_label_id integer;
	v_result_data jsonb;
	v_recipient_push text := NULL;
	v_reg text := NULL;
	v_main_total_tool_count integer;
	v_main_task_filter jsonb;
	v_sub_task_filter jsonb;
	v_main_filtered_result jsonb;
	v_sub_filtered_result jsonb;
	v_sub_result  jsonb;
	v_sub_obj jsonb;
	tool_item jsonb;
	v_remove_tool_data jsonb;
BEGIN
    -- Fetch IPO label ID
    SELECT status_id
    INTO ipo_id
    FROM master.status_code_master
    WHERE name = 'IPO'
      AND type = 'ORDERLABEL'
      AND is_active = true
    LIMIT 1;
	
	--Get Main Board ID
  	SELECT main_board_id INTO v_main_board_id
	FROM board.board
	WHERE "BoardID" = p_board_id
	AND is_active = true;

	--Get Main Label ID
	SELECT label_id INTO v_main_label_id
	FROM tickets.ticket_board_tracker 
	WHERE ticket_id = p_ticket_id AND board_id = v_main_board_id 
	AND is_active = true LIMIT 1;

    WITH filtered_tool_flows AS (
        SELECT 
            flow_id, 
            ARRAY_AGG(tool_ticket_id ORDER BY tool_ticket_id) AS tool_ticket_ids
        FROM tickets.tool_detail
        WHERE tool_ticket_id = ANY(p_tool_ticket_id)
          AND is_active = TRUE
        GROUP BY flow_id
        ORDER BY flow_id
    ),
    latest_label_assignee AS (
--         SELECT DISTINCT ON (board_id, label_id, tool_board_logid)
--                board_id,
--                label_id,
--                assignee_to,
--                tool_board_logid,
--                sequence
--         FROM tickets.tool_assignee
--         WHERE is_active = true 
--           AND board_id = p_board_id 
--           AND label_id = p_to_label_id
--         ORDER BY board_id, label_id, tool_board_logid, sequence DESC
		SELECT *
		FROM (
			SELECT DISTINCT ON (board_id, label_id, tool_board_logid)
				   board_id,
				   label_id,
				   assignee_to,
				   tool_board_logid,
				   un_assigned_flag,
				   sequence
			FROM tickets.tool_assignee
			WHERE is_active = TRUE
			  AND board_id = p_board_id
			  AND label_id = p_to_label_id
			ORDER BY
				board_id,
				label_id,
				tool_board_logid,
				sequence DESC
		) x
		WHERE un_assigned_flag = FALSE
    )
	--Get Flow Tool Details
    SELECT 
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'flowId', COALESCE(f.flow_id, 0),
                    'flowName', COALESCE(f.flow_name, ''),
                    'listOfTools', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'toolTicketId', td.tool_ticket_id,
                                'toolBoardLogId', tbl.tool_board_logid,
                                'toolId', td.tool_id,
                                'toolCode', mt."ToolCode",
                                'toolName', mt."ToolName",
                                'toolStatusId', td.status_id,
                                'assignee', CASE
                                    WHEN la.assignee_to IS NOT NULL THEN
                                        jsonb_build_array(
                                            jsonb_build_object(
                                                'regId', la.assignee_to::text,
                                                'name', COALESCE(u2."DisplayName", ''),
                                                'photo', COALESCE(u2.photo_url, '')
                                            )
                                        )
                                    ELSE '[]'::jsonb
                                END,
                                'dueDate', td.due_date
                            )
                        ) FILTER (WHERE td.tool_id IS NOT NULL) AS flowTools
                        FROM tickets.tool_detail td
                        JOIN (
                            SELECT DISTINCT ON (tool_ticket_id)
                                   tbl.tool_ticket_id,
                                   tbl.board_id,
                                   tbl.label_id,
                                   tbl.tool_board_logid
                            FROM tickets.tool_board_log tbl
                            WHERE tbl.board_id = p_board_id
                              AND tbl.is_active = true
                              AND tbl.is_moved = false
                            ORDER BY tbl.tool_ticket_id, sequence DESC
                        ) tbl ON td.tool_ticket_id = tbl.tool_ticket_id
                        JOIN master.tool mt 
                            ON td.tool_id = mt."ToolID" 
                           AND mt.is_active = true
                        LEFT JOIN latest_label_assignee la 
                            ON la.tool_board_logid = tbl.tool_board_logid
                        LEFT JOIN users.registereduser u2 
                            ON la.assignee_to = u2."RegId"
                        WHERE td.is_active = true 
                          AND td.tool_ticket_id = ANY(ft.tool_ticket_ids)
                    ), '[]'::jsonb)
                )
            ),
            '[]'::jsonb
        ) INTO v_flow_tool_list
    FROM filtered_tool_flows ft
    JOIN board.flow f 
        ON f.flow_id = ft.flow_id
    WHERE f.is_active = true;
	
	-- Get Ticket Details 
    SELECT COALESCE(
        jsonb_build_object(
            'orderId', t.ticket_id,
            'ticketOrderId', t.order_id,
            'companyName', t.name,
            'orderDate', t.order_date,
            'expectedDeliveryDate', t.expected_delivery_date,
            'orderLabels', COALESCE(
                to_json(
                    CASE
                        WHEN tc.is_ipo = true THEN t.order_label_id || ARRAY[ipo_id]
                        ELSE t.order_label_id
                    END
                ),
                '[]'::json
            ),
            'assignee', CASE
                WHEN ts.assignee_to IS NOT NULL THEN
                    jsonb_build_array(
                        jsonb_build_object(
                            'regId', ts.assignee_to,
                            'name', u."DisplayName",
                            'photo', u.photo_url
                        )
                    )
                ELSE '[]'::jsonb
            END,
            'orderType', t.order_type,
            'orderCategory', t.order_category,
            'upSellCategory', t.upsellcategory,
            'reDesignCategory', t.redesigncategory,
            'createdDate', t.created_date
        ),
        '{}'::jsonb
    ) INTO v_ticket_data
    FROM tickets.ticket t
    LEFT JOIN tickets.ticket_company tc 
        ON tc.ticket_id = t.ticket_id 
       AND tc.is_active = true
    LEFT JOIN tickets.ticket_assignee ts 
        ON t.ticket_id = ts.ticket_id
       AND ts.is_active = true
       AND ts.assignee_type = 'OB'
    LEFT JOIN users.registereduser u
        ON ts.assignee_to = u."RegId"
    WHERE t.ticket_id = p_ticket_id 
      AND t.is_active = true;

	--Main task total tool count
	SELECT 
		COUNT(tool_ticket_id) INTO v_main_total_tool_count 
	FROM tickets.tool_detail 
	WHERE ticket_id = p_ticket_id 
	AND is_active = true;

	--Get task data
	IF v_main_label_id IS NOT NULL AND v_main_label_id > 0 THEN
		v_main_task_data := jsonb_build_object(
				'type', 'KANBAN_UPDATE',
				'action', p_action,
				'level', 'MAIN',
				'data', COALESCE(
					jsonb_build_object(
						'ticket',
							COALESCE(v_ticket_data, '{}'::jsonb)
							|| jsonb_build_object(
								'labelId', v_main_label_id,
								'totalToolCount', v_main_total_tool_count
							),						
						'fromLabelId', 0,
						'toLabelId', v_main_label_id
					),
					'{}'::jsonb
				)
		   ); 
	ELSE
		v_main_task_data := '{}'::jsonb;
	END IF;
	--Sub task data
	v_sub_task_data := jsonb_build_object(
            'type', 'KANBAN_UPDATE',
            'action', p_action,
            'level', 'SUB',
            'data', COALESCE(
                jsonb_build_object(                    
					'ticket',
						COALESCE(v_ticket_data, '{}'::jsonb)
						|| jsonb_build_object(
							'toolList', v_flow_tool_list,
							'labelId', p_to_label_id,
							'totalToolCount', 0
						),					
					'fromLabelId', p_from_label_id,
					'toLabelId', p_to_label_id
                ),
                '{}'::jsonb
            )
       ); 
		
	
	--Push Notification 
-- 	SELECT 
-- 		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
-- 	INTO 
-- 		v_recipient_push
-- 	 FROM users.user_board_permission ubp
-- 	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
-- 	 WHERE ubp.board_id = p_board_id AND ubp.is_active = true AND ubp.reg_id != p_added_by
-- 	 AND r.token_expiry_time IS NOT NULL AND r.token_expiry_time > NOW();

	SELECT 
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_push
	 FROM users.user_board_permission ubp
	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	 JOIN users.userprofile up ON r."RegId" = up.user_id AND up.is_active = true
	 WHERE ubp.board_id = p_board_id AND ubp.is_active = true AND ubp.reg_id != p_added_by
	 AND r.last_active_time IS NOT NULL AND r.last_active_time >= (NOW() AT TIME ZONE 'UTC') - INTERVAL '5 minutes' -- Only online users
	 AND ((up.sub_board_filter IS NOT NULL
			  AND (up.sub_board_filter->>'board_id')::int = p_board_id) OR (up.main_board_filter IS NOT NULL
			  AND (up.main_board_filter->>'board_id')::int = v_main_board_id)); --Users whose main-board or sub-board filter matches the same board.

	-- Add Push Notification
	FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP		
		
		-- Trim spaces if any
		v_reg := trim(v_reg);
		
		--Filter the result data
		SELECT 
			main_board_filter, sub_board_filter
		INTO
			v_main_task_filter, v_sub_task_filter
		FROM users.userprofile
		WHERE user_id = v_reg::UUID;				
		
		v_result_data := NULL;
		-- Initialize
		v_result_data := COALESCE(
			(CASE 
				WHEN v_main_task_filter IS NOT NULL 
				THEN (SELECT * FROM tickets.filter_kanban_by_main_sub(v_main_task_data, v_main_task_filter, 'MAIN')) || jsonb_build_object(
						'type', 'KANBAN_UPDATE',
						'action', p_action,
						'level', 'MAIN'
					)
				ELSE v_main_task_data 
			 END),
			'[]'::jsonb
		);

		-- Build sub result (filtered or raw)
		v_sub_result := CASE 
			WHEN v_sub_task_filter IS NOT NULL 
			THEN (SELECT * FROM tickets.filter_kanban_by_main_sub(v_sub_task_data, v_sub_task_filter, 'SUB')) || jsonb_build_object(
						'type', 'KANBAN_UPDATE',
						'action', p_action,
						'level', 'SUB'
					)
			ELSE v_sub_task_data 
		END;

		-- Combine main and sub
		v_result_data := 
			CASE 
				WHEN v_result_data IS NULL THEN v_sub_result
				ELSE jsonb_build_array(v_result_data, v_sub_result)
			END;
			
		
		--Remove Tool data
		IF v_result_data IS NOT NULL 
				AND p_action = 'UPDATE' 
				AND EXISTS (
						SELECT 1
						FROM jsonb_array_elements(v_result_data) elem
						WHERE elem->>'level' = 'SUB'
					) 
				AND v_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_flow_tool_list) = 'array'
				AND jsonb_array_length(v_flow_tool_list) > 0 THEN
					
			-- Get the SUB element (single record)
			SELECT elem
			INTO v_sub_obj
			FROM jsonb_array_elements(v_result_data) elem
			WHERE elem->>'level' = 'SUB'
			LIMIT 1;
			
			v_filtered_flow_tool_list := '[]'::jsonb;
			
			-- Loop each item in toolList
			FOR tool_item IN
				SELECT value
				FROM jsonb_array_elements(v_sub_obj->'data'->'ticket'->'toolList') AS t(value)
			LOOP
				RAISE NOTICE 'Tool Item: %', tool_item;

				IF tool_item->'listOfTools' IS NULL OR tool_item->'listOfTools' = 'null'::jsonb THEN

					-- Extract flowId
					DECLARE
						v_flow_id text := tool_item->>'flowId';
						v_existing_item jsonb;
					BEGIN
						-- Find existing item with same flowId
						SELECT elem
						INTO v_existing_item
						FROM jsonb_array_elements(v_flow_tool_list) elem
						WHERE elem->>'flowId' = v_flow_id
						LIMIT 1;

						IF v_existing_item IS NOT NULL THEN
							-- No existing: add this tool_item
							v_filtered_flow_tool_list :=
								v_filtered_flow_tool_list || jsonb_build_array(v_existing_item);
						END IF;
					END;
				END IF;
			END LOOP;
			
			IF v_filtered_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_filtered_flow_tool_list) = 'array'
				AND jsonb_array_length(v_filtered_flow_tool_list) > 0 THEN
				
				v_remove_tool_data := jsonb_build_array(
											jsonb_build_object(
												'type', 'KANBAN_UPDATE',
												'action', 'REMOVE',
												'level', 'SUB',
												'data', COALESCE(
													jsonb_build_object(                    
														'ticket',
															COALESCE(v_ticket_data, '{}'::jsonb)
															|| jsonb_build_object(
																'toolList', v_filtered_flow_tool_list,
																	'labelId', p_to_label_id,
																'totalToolCount', 0
															),					
														'fromLabelId', p_from_label_id,
														'toLabelId', p_to_label_id
													),
													'{}'::jsonb
												)
											)
										   );
										   
				v_result_data := v_result_data || v_remove_tool_data;
				
			END IF;
		END IF;
		
		-- Call the existing add_notification procedure for each recipient
		IF v_result_data IS NOT NULL THEN	
		
			CALL notification.add_notification(
				p_type := 'Push',
				p_recipient := v_reg,
				p_subject := 'KANBAN_UPDATE',
				p_message := 'Board and task details have been refreshed with the latest updates.',
				p_retry_count := 0,
				p_max_retries := 3,
				p_message_json := v_result_data::text,
				message := message,
				status := status
			);
			
		END IF;

	END LOOP;

    status := 'true';
    message := 'Notification Pushed.';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.main_sub_board_refresh',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_ticket_id, p_board_id))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: main_sub_board_refresh_remove_tool(integer[], integer, integer, integer, integer, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.main_sub_board_refresh_remove_tool(IN p_tool_ticket_id integer[] DEFAULT NULL::integer[], IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_from_label_id integer DEFAULT 0, IN p_to_label_id integer DEFAULT 0, IN p_action text DEFAULT ''::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;
    v_sub_task_data jsonb;
	v_main_task_data jsonb;
    ipo_id integer;
	v_flow_tool_list jsonb;
	v_filtered_flow_tool_list jsonb;
	v_ticket_data jsonb;
	v_main_board_id integer;
	v_main_label_id integer;
	v_result_data jsonb;
	v_recipient_push text := NULL;
	v_reg text := NULL;
	v_main_total_tool_count integer;
	v_main_task_filter jsonb;
	v_sub_task_filter jsonb;
	v_main_filtered_result jsonb;
	v_sub_filtered_result jsonb;
	v_sub_result  jsonb;
	v_sub_obj jsonb;
	tool_item jsonb;
	v_remove_tool_data jsonb;
BEGIN
    -- Fetch IPO label ID
    SELECT status_id
    INTO ipo_id
    FROM master.status_code_master
    WHERE name = 'IPO'
      AND type = 'ORDERLABEL'
      AND is_active = true
    LIMIT 1;
	
	--Get Main Board ID
  	SELECT main_board_id INTO v_main_board_id
	FROM board.board
	WHERE "BoardID" = p_board_id
	AND is_active = true;

	--Get Main Label ID
	SELECT label_id INTO v_main_label_id
	FROM tickets.ticket_board_tracker 
	WHERE ticket_id = p_ticket_id AND board_id = v_main_board_id 
	AND is_active = true LIMIT 1;

    WITH filtered_tool_flows AS (
        SELECT 
            flow_id, 
            ARRAY_AGG(tool_ticket_id ORDER BY tool_ticket_id) AS tool_ticket_ids
        FROM tickets.tool_detail
        WHERE tool_ticket_id = ANY(p_tool_ticket_id)
          AND is_active = TRUE
        GROUP BY flow_id
        ORDER BY flow_id
    ),
    latest_label_assignee AS (
        SELECT DISTINCT ON (board_id, label_id, tool_board_logid)
               board_id,
               label_id,
               assignee_to,
               tool_board_logid,
               sequence
        FROM tickets.tool_assignee
        WHERE is_active = true 
          AND board_id = p_board_id 
          AND label_id = p_to_label_id
        ORDER BY board_id, label_id, tool_board_logid, sequence DESC
    )
	--Get Flow Tool Details
    SELECT 
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'flowId', COALESCE(f.flow_id, 0),
                    'flowName', COALESCE(f.flow_name, ''),
                    'listOfTools', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'toolTicketId', td.tool_ticket_id,
                                'toolBoardLogId', tbl.tool_board_logid,
                                'toolId', td.tool_id,
                                'toolCode', mt."ToolCode",
                                'toolName', mt."ToolName",
                                'toolStatusId', td.status_id,
                                'assignee', CASE
                                    WHEN la.assignee_to IS NOT NULL THEN
                                        jsonb_build_array(
                                            jsonb_build_object(
                                                'regId', la.assignee_to::text,
                                                'name', COALESCE(u2."DisplayName", ''),
                                                'photo', COALESCE(u2.photo_url, '')
                                            )
                                        )
                                    ELSE '[]'::jsonb
                                END,
                                'dueDate', td.due_date
                            )
                        ) FILTER (WHERE td.tool_id IS NOT NULL) AS flowTools
                        FROM tickets.tool_detail td
                        JOIN (
                            SELECT DISTINCT ON (tool_ticket_id)
                                   tbl.tool_ticket_id,
                                   tbl.board_id,
                                   tbl.label_id,
                                   tbl.tool_board_logid
                            FROM tickets.tool_board_log tbl
                            WHERE tbl.board_id = p_board_id
                              AND tbl.is_active = true
                              AND tbl.is_moved = false
                            ORDER BY tbl.tool_ticket_id, sequence DESC
                        ) tbl ON td.tool_ticket_id = tbl.tool_ticket_id
                        JOIN master.tool mt 
                            ON td.tool_id = mt."ToolID" 
                           AND mt.is_active = true
                        LEFT JOIN latest_label_assignee la 
                            ON la.tool_board_logid = tbl.tool_board_logid
                        LEFT JOIN users.registereduser u2 
                            ON la.assignee_to = u2."RegId"
                        WHERE td.is_active = true 
                          AND td.tool_ticket_id = ANY(ft.tool_ticket_ids)
                    ), '[]'::jsonb)
                )
            ),
            '[]'::jsonb
        ) INTO v_flow_tool_list
    FROM filtered_tool_flows ft
    JOIN board.flow f 
        ON f.flow_id = ft.flow_id
    WHERE f.is_active = true;
	
	-- Get Ticket Details 
    SELECT COALESCE(
        jsonb_build_object(
            'orderId', t.ticket_id,
            'ticketOrderId', t.order_id,
            'companyName', t.name,
            'orderDate', t.order_date,
            'expectedDeliveryDate', t.expected_delivery_date,
            'orderLabels', COALESCE(
                to_json(
                    CASE
                        WHEN tc.is_ipo = true THEN t.order_label_id || ARRAY[ipo_id]
                        ELSE t.order_label_id
                    END
                ),
                '[]'::json
            ),
            'assignee', CASE
                WHEN ts.assignee_to IS NOT NULL THEN
                    jsonb_build_array(
                        jsonb_build_object(
                            'regId', ts.assignee_to,
                            'name', u."DisplayName",
                            'photo', u.photo_url
                        )
                    )
                ELSE '[]'::jsonb
            END,
            'orderType', t.order_type,
            'orderCategory', t.order_category,
            'upSellCategory', t.upsellcategory,
            'reDesignCategory', t.redesigncategory,
            'createdDate', t.created_date
        ),
        '{}'::jsonb
    ) INTO v_ticket_data
    FROM tickets.ticket t
    LEFT JOIN tickets.ticket_company tc 
        ON tc.ticket_id = t.ticket_id 
       AND tc.is_active = true
    LEFT JOIN tickets.ticket_assignee ts 
        ON t.ticket_id = ts.ticket_id
       AND ts.is_active = true
       AND ts.assignee_type = 'OB'
    LEFT JOIN users.registereduser u
        ON ts.assignee_to = u."RegId"
    WHERE t.ticket_id = p_ticket_id 
      AND t.is_active = true;

	--Main task total tool count
	SELECT 
		COUNT(tool_ticket_id) INTO v_main_total_tool_count 
	FROM tickets.tool_detail 
	WHERE ticket_id = p_ticket_id 
	AND is_active = true;

	--Get task data
	IF v_main_label_id IS NOT NULL AND v_main_label_id > 0 THEN
		v_main_task_data := jsonb_build_object(
				'type', 'KANBAN_UPDATE',
				'action', p_action,
				'level', 'MAIN',
				'data', COALESCE(
					jsonb_build_object(
						'ticket',
							COALESCE(v_ticket_data, '{}'::jsonb)
							|| jsonb_build_object(
								'labelId', v_main_label_id,
								'totalToolCount', v_main_total_tool_count
							),						
						'fromLabelId', 0,
						'toLabelId', v_main_label_id
					),
					'{}'::jsonb
				)
		   ); 
	ELSE
		v_main_task_data := '{}'::jsonb;
	END IF;
	--Sub task data
	v_sub_task_data := jsonb_build_object(
            'type', 'KANBAN_UPDATE',
            'action', p_action,
            'level', 'SUB',
            'data', COALESCE(
                jsonb_build_object(                    
					'ticket',
						COALESCE(v_ticket_data, '{}'::jsonb)
						|| jsonb_build_object(
							'toolList', v_flow_tool_list,
							'labelId', p_to_label_id,
							'totalToolCount', 0
						),					
					'fromLabelId', p_from_label_id,
					'toLabelId', p_to_label_id
                ),
                '{}'::jsonb
            )
       ); 
		
	
	--Push Notification 
-- 	SELECT 
-- 		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
-- 	INTO 
-- 		v_recipient_push
-- 	 FROM users.user_board_permission ubp
-- 	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
-- 	 WHERE ubp.board_id = p_board_id AND ubp.is_active = true AND ubp.reg_id != p_added_by
-- 	 AND r.token_expiry_time IS NOT NULL AND r.token_expiry_time > NOW();

	SELECT 
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_push
	 FROM users.user_board_permission ubp
	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	 JOIN users.userprofile up ON r."RegId" = up.user_id AND up.is_active = true
	 WHERE ubp.board_id = p_board_id AND ubp.is_active = true AND ubp.reg_id != p_added_by
	 AND r.last_active_time IS NOT NULL AND r.last_active_time >= (NOW() AT TIME ZONE 'UTC') - INTERVAL '5 minutes' -- Only online users
	 AND ((up.sub_board_filter IS NOT NULL
			  AND (up.sub_board_filter->>'board_id')::int = p_board_id) OR (up.main_board_filter IS NOT NULL
			  AND (up.main_board_filter->>'board_id')::int = v_main_board_id)); --Users whose main-board or sub-board filter matches the same board.

	-- Add Push Notification
	FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP		
		
		-- Trim spaces if any
		v_reg := trim(v_reg);
		
		--Filter the result data
		SELECT 
			main_board_filter, sub_board_filter
		INTO
			v_main_task_filter, v_sub_task_filter
		FROM users.userprofile
		WHERE user_id = v_reg::UUID;				
		
		v_result_data := NULL;
		-- Initialize
		v_result_data := COALESCE(
			(CASE 
				WHEN v_main_task_filter IS NOT NULL 
				THEN (SELECT * FROM tickets.filter_kanban_by_main_sub(v_main_task_data, v_main_task_filter, 'MAIN')) || jsonb_build_object(
						'type', 'KANBAN_UPDATE',
						'action', p_action,
						'level', 'MAIN'
					)
				ELSE v_main_task_data 
			 END),
			'[]'::jsonb
		);

		-- Build sub result (filtered or raw)
		v_sub_result := CASE 
			WHEN v_sub_task_filter IS NOT NULL 
			THEN (SELECT * FROM tickets.filter_kanban_by_main_sub(v_sub_task_data, v_sub_task_filter, 'SUB')) || jsonb_build_object(
						'type', 'KANBAN_UPDATE',
						'action', p_action,
						'level', 'SUB'
					)
			ELSE v_sub_task_data 
		END;

		-- Combine main and sub
		v_result_data := 
			CASE 
				WHEN v_result_data IS NULL THEN v_sub_result
				ELSE jsonb_build_array(v_result_data, v_sub_result)
			END;
			
		
		--Remove Tool data
		IF v_result_data IS NOT NULL 
				AND p_action = 'UPDATE' 
				AND EXISTS (
						SELECT 1
						FROM jsonb_array_elements(v_result_data) elem
						WHERE elem->>'level' = 'SUB'
					) 
				AND v_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_flow_tool_list) = 'array'
				AND jsonb_array_length(v_flow_tool_list) > 0 THEN
					
			-- Get the SUB element (single record)
			SELECT elem
			INTO v_sub_obj
			FROM jsonb_array_elements(v_result_data) elem
			WHERE elem->>'level' = 'SUB'
			LIMIT 1;
			
			v_filtered_flow_tool_list := '[]'::jsonb;
			
			-- Loop each item in toolList
			FOR tool_item IN
				SELECT value
				FROM jsonb_array_elements(v_sub_obj->'data'->'ticket'->'toolList') AS t(value)
			LOOP
				RAISE NOTICE 'Tool Item: %', tool_item;

				IF tool_item->'listOfTools' IS NULL OR tool_item->'listOfTools' = 'null'::jsonb THEN

					-- Extract flowId
					DECLARE
						v_flow_id text := tool_item->>'flowId';
						v_existing_item jsonb;
					BEGIN
						-- Find existing item with same flowId
						SELECT elem
						INTO v_existing_item
						FROM jsonb_array_elements(v_flow_tool_list) elem
						WHERE elem->>'flowId' = v_flow_id
						LIMIT 1;

						IF v_existing_item IS NOT NULL THEN
							-- No existing: add this tool_item
							v_filtered_flow_tool_list :=
								v_filtered_flow_tool_list || jsonb_build_array(v_existing_item);
						END IF;
					END;
				END IF;
			END LOOP;
			
			IF v_filtered_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_filtered_flow_tool_list) = 'array'
				AND jsonb_array_length(v_filtered_flow_tool_list) > 0 THEN
				
				v_remove_tool_data := jsonb_build_array(
											jsonb_build_object(
												'type', 'KANBAN_UPDATE',
												'action', 'REMOVE',
												'level', 'SUB',
												'data', COALESCE(
													jsonb_build_object(                    
														'ticket',
															COALESCE(v_ticket_data, '{}'::jsonb)
															|| jsonb_build_object(
																'toolList', v_filtered_flow_tool_list,
																'labelId', p_to_label_id,
																'totalToolCount', 0
															),					
														'fromLabelId', p_from_label_id,
														'toLabelId', p_to_label_id
													),
													'{}'::jsonb
												)
											)
										   );
										   
				v_result_data := v_result_data || v_remove_tool_data;
				
			END IF;
		END IF;
		
		RAISE INFO 'v_result_data % :', v_result_data::TEXT;
		
		-- Call the existing add_notification procedure for each recipient
		IF v_result_data IS NOT NULL THEN	
		
-- 			CALL notification.add_notification(
-- 				p_type := 'Push',
-- 				p_recipient := v_reg,
-- 				p_subject := 'KANBAN_UPDATE',
-- 				p_message := 'Board and task details have been refreshed with the latest updates.',
-- 				p_retry_count := 0,
-- 				p_max_retries := 3,
-- 				p_message_json := v_result_data::text,
-- 				message := message,
-- 				status := status
-- 			);
			
		END IF;

	END LOOP;

    status := 'true';
    message := 'Notification Pushed.';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.main_sub_board_refresh',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_ticket_id, p_board_id))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: move_task(integer[], text, integer, uuid, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.move_task(IN p_tool_ticket_id integer[] DEFAULT '{}'::integer[], IN p_flow_detail text DEFAULT NULL::text, IN p_flow_id integer DEFAULT 0, IN p_action_id uuid DEFAULT NULL::uuid, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_task
Developer   : Aravindhan.B
Created On  : 27-01-2026
Purpose     : Task movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
27-01-2026  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context TEXT;
    v_flow_details JSONB;
	v_source jsonb;       -- source object
    v_target jsonb;       -- each target object
	
	v_tool_ticket_id integer;
	v_new_tool_board_logid integer;
	v_ticket_id integer;
	v_new_tool_assignee_id integer;
	v_assignee_to UUID;
	v_affected_rows int := 0; -- track inserts/updates
    v_count int;              -- for diagnostics
	
	v_tool_board_logid integer;
	v_recipient_push TEXT := NULL;
	v_reg TEXT := NULL;
	v_board_name TEXT := NULL;
	v_label_name TEXT := NULL;
	v_work_space_id	INTEGER := 0;
	v_company_name TEXT := NULL;
	v_source_board_name TEXT := NULL;
	v_target_board_name		TEXT 	:= NULL;	
	v_source_label_name		TEXT 	:= NULL;
	v_target_label_name		TEXT 	:= NULL;	
	v_refresh jsonb;
BEGIN
    -- Safely convert flow detail text to JSONB
    IF p_flow_detail IS NOT NULL THEN
        v_flow_details := p_flow_detail::JSONB;
    END IF;

	--RAISE INFO 'v_flow_details : %', v_flow_details->'source';
 	v_source := v_flow_details->'source'; 
	v_target := v_flow_details->'targets'; 

	SELECT "Name"
	INTO v_source_board_name
	FROM board.board 
	WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
	
	SELECT "Name", work_space_id
	INTO v_target_board_name, v_work_space_id
	FROM board.board 
	WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;
		
	SELECT "Name" INTO v_source_label_name 
	FROM board.boardstatus
	WHERE "BoardID" = (v_source->>'board_id')::integer AND "LabelID" = (v_source->>'label_id')::integer AND is_active = TRUE;
	
	SELECT "Name" INTO v_target_label_name 
	FROM board.boardstatus
	WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;

	-- Loop through each tool_ticket_id
	FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
	LOOP 
		--Add Tool board Log
		SELECT COALESCE(MAX(tool_board_logid),0) + 1
		INTO v_new_tool_board_logid
		FROM tickets.tool_board_log;

		SELECT ticket_id INTO v_ticket_id
		FROM tickets.tool_detail 
		WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;	
				
		--RAISE INFO 'Ticeket_id : %', v_tool_ticket_id;

		SELECT tool_board_logid INTO v_tool_board_logid
		FROM tickets.tool_board_log
		WHERE is_active = true
		  AND board_id = (v_source->>'board_id')::integer
		  AND label_id = (v_source->>'label_id')::integer
		  AND tool_ticket_id = v_tool_ticket_id
		  AND is_moved = false
		  ORDER BY sequence DESC limit 1;
			  
	   INSERT INTO tickets.tool_board_log(
			tool_board_logid,
			ticket_id,
			tool_ticket_id,
			moved_by,
			board_id,
			label_id,
			moved_date,
			sequence,
			action_id,
			created_date,
			created_by,
			is_active
		)
		VALUES (
			v_new_tool_board_logid,
			v_ticket_id,
			v_tool_ticket_id,
			p_added_by,			
			(v_target->>'board_id')::integer,
			(v_target->>'label_id')::integer,
			current_timestamp AT TIME ZONE 'UTC',
			COALESCE((
				SELECT MAX(sequence) + 1
				FROM tickets.tool_board_log
				WHERE tool_ticket_id = v_tool_ticket_id
				  AND board_id = (v_target->>'board_id')::integer AND is_active = true
			), 1),
			p_action_id,
			current_timestamp AT TIME ZONE 'UTC',
			p_added_by,
			TRUE
		);
		GET DIAGNOSTICS v_count = ROW_COUNT;
		v_affected_rows := v_affected_rows + v_count;
		
		--If not unassigned flag, add tool_assignee entry
		IF NOT (v_target->>'unassigned')::boolean THEN			 					

			SELECT assignee_to INTO v_assignee_to
			FROM tickets.tool_assignee
			WHERE is_active = true
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND tool_board_logid = v_tool_board_logid
			  AND assignee_to IS NOT NULL
			ORDER BY sequence DESC
			LIMIT 1;	

			IF v_assignee_to IS NULL THEN				
				RAISE EXCEPTION 'assignee_to cannot be NULL or empty';			
			END IF;

			-- Insert into tool_assignee
			SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
			INTO v_new_tool_assignee_id
			FROM tickets.tool_assignee;

			INSERT INTO tickets.tool_assignee (
				tool_assignee_id,
				tool_board_logid,
				board_id,
				label_id,
				assignee_to,
				assigned_date,
				un_assigned_flag,            
				is_active,
				created_date,
				created_by,
				sequence
			)
			VALUES (
				v_new_tool_assignee_id,
				v_new_tool_board_logid,
				(v_target->>'board_id')::integer,
				(v_target->>'label_id')::integer,                
				v_assignee_to,
				current_timestamp AT TIME ZONE 'UTC',
				false,
				true,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by::text,
				1
			);	
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
		END IF;	

			PERFORM tickets.add_or_update_history_details(
					in_order_id           => v_ticket_id,
					in_tool_ticket_id     => v_tool_ticket_id,
					in_content => CONCAT(
											    'moved the tool from ',
											    COALESCE(v_source_board_name, ''), ' - "',
											    COALESCE(v_source_label_name, ''), '"',
											    ' to ',
											    COALESCE(v_target_board_name, ''), ' - "',
											    COALESCE(v_target_label_name, ''), '"'
											),
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Task label Movement'
				);			
	END LOOP;
	
	
	IF ((v_source->>'board_id')::integer != (v_target->>'board_id')::integer) THEN									

		SELECT TRIM(name) INTO v_company_name 
		FROM tickets.ticket 
		WHERE ticket_id = v_ticket_id  AND is_active = true;

		SELECT "Name", work_space_id
		INTO v_board_name, v_work_space_id
		FROM board.board 
		WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;

		SELECT "Name"
		INTO v_source_board_name
		FROM board.board 
		WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
		
		SELECT "Name" INTO v_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;

		SELECT 			
			STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
		INTO 			
			v_recipient_push
		 FROM users.user_board_permission ubp
		 JOIN users.registereduser r ON r."RegId" = ubp.reg_id and r.is_active = true
		 where ubp.board_id = (v_target->>'board_id')::integer and ubp.is_active = true;

		-- Add Push Notification
		FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP

			-- Trim spaces if any
			v_reg := trim(v_reg);

			-- Call the existing add_notification procedure for each recipient
			CALL notification.add_notification(
				p_type := 'Push',
				p_recipient := v_reg,
				p_subject := 'New Card',
				p_message := 'A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
				p_retry_count := 0,
				p_max_retries := 3,
				p_message_json := '{
									"ticket_id": '|| v_ticket_id ||',
									"tool_id": 0,
									"tool_ticket_id": 0,
									"board_id": '|| (v_target->>'board_id')::integer ||',
									"moved_from": "'|| p_added_by ||'",
									"moved_to": "'|| v_reg ||'",
									"notify_message": "A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
									"is_read": false,
									"type": "task_ticket",	
									"workspace_id": '|| v_work_space_id ||',
									"header": "New Card"
								   }'::text,
				message := message,
				status := status
			);

		END LOOP;							

		PERFORM tickets.add_or_update_history_details(
			in_order_id           => v_ticket_id,
			   in_content            => CONCAT(
											'moved the ticket from ',
											COALESCE(v_source->>'board_name', ''),
											' to ',
											COALESCE(v_target->>'board_name', '')
										 ),
			in_user_id            => p_added_by,
			in_created_by         => p_added_by,
			in_created_date       => current_timestamp AT TIME ZONE 'UTC',
			in_uploaded_file_name => NULL,
			in_history_type       => 'Ticket board Movement'
		);
	END IF;

	--Moved to ticket another stage	
	IF p_is_moved THEN			
		-- Loop through each tool_ticket_id
		FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
		LOOP    	
					
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			UPDATE tickets.tool_board_log 
			SET is_moved = true
			WHERE tool_ticket_id = v_tool_ticket_id
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND is_moved = false;
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
			
		END LOOP;
		-- PERFORM tickets.add_or_update_history_details(
		-- 		in_order_id           => v_ticket_id,
		-- 		   in_content            => CONCAT(
		-- 										'moved the ticket from ',
		-- 										COALESCE(v_source->>'board_name', ''),
		-- 										' to ',
		-- 										COALESCE(v_target->>'board_name', '')
		-- 									 ),
		-- 		in_user_id            => p_added_by,
		-- 		in_created_by         => p_added_by,
		-- 		in_created_date       => current_timestamp AT TIME ZONE 'UTC',
		-- 		in_uploaded_file_name => NULL,
		-- 		in_history_type       => 'Task board Movement'
		-- 	);
			PERFORM tickets.add_or_update_history_details(
			    in_order_id => v_ticket_id,
			    in_content => CONCAT(
			        'moved the ticket from ',
			        COALESCE(v_source_board_name, ''),
			        ' to ',
			        COALESCE(v_board_name, '')
			    ),
			    in_user_id => p_added_by,
			    in_created_by => p_added_by,
			    in_created_date => current_timestamp AT TIME ZONE 'UTC',
			    in_uploaded_file_name => NULL,
			    in_history_type => 'Ticket board Movement'
			);
				
	END IF;		
	

	--Kanban board auto refresh			
	IF (v_source->>'board_id')::integer = (v_target->>'board_id')::integer THEN

		 v_refresh := jsonb_build_object(
				'tool_ticket_id', p_tool_ticket_id,
				'ticket_id', v_ticket_id,
				'board_id', (v_target->>'board_id')::integer,
				'from_label_id', (v_source->>'label_id')::integer,
				'to_label_id', (v_target->>'label_id')::integer,
				'type', 'MOVE',
				'added_by', p_added_by
			);

			autorefreshreq := (
				COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
			)::text;

	ELSIF (v_source->>'board_id')::integer <> (v_target->>'board_id')::integer THEN

		 v_refresh := jsonb_build_object(
				'tool_ticket_id', p_tool_ticket_id,
				'ticket_id', v_ticket_id,
				'board_id', (v_target->>'board_id')::integer,
				'from_label_id', 0,
				'to_label_id', (v_target->>'label_id')::integer,
				'type', 'ADD',
				'added_by', p_added_by
			);		

			autorefreshreq := (
				COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
			)::text;

	END IF;		
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN

		UPDATE tickets.ticket
        SET
            last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
			updated_by = p_added_by 
        WHERE ticket_id = v_ticket_id;
	         status := 'true';	
			 
        status := 'true';
        message := 'Task moved successfully.';		
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';		
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.move_task',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(
                ROW(
                    p_tool_ticket_id,
                    p_flow_detail,
                    p_flow_id,
                    p_action_id,
                    p_is_moved,
                    p_added_by
                )
            )::TEXT
        );

        status := 'false';
        message := SQLERRM; 
END;
$$;


--
-- Name: move_task_backup_19062026(integer[], text, integer, uuid, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.move_task_backup_19062026(IN p_tool_ticket_id integer[] DEFAULT '{}'::integer[], IN p_flow_detail text DEFAULT NULL::text, IN p_flow_id integer DEFAULT 0, IN p_action_id uuid DEFAULT NULL::uuid, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_task
Developer   : Aravindhan.B
Created On  : 27-01-2026
Purpose     : Task movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
27-01-2026  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context TEXT;
    v_flow_details JSONB;
	v_source jsonb;       -- source object
    v_target jsonb;       -- each target object
	
	v_tool_ticket_id integer;
	v_new_tool_board_logid integer;
	v_ticket_id integer;
	v_new_tool_assignee_id integer;
	v_assignee_to UUID;
	v_affected_rows int := 0; -- track inserts/updates
    v_count int;              -- for diagnostics
	
	v_tool_board_logid integer;
	v_recipient_push TEXT := NULL;
	v_reg TEXT := NULL;
	v_board_name TEXT := NULL;
	v_label_name TEXT := NULL;
	v_work_space_id	INTEGER := 0;
	v_company_name TEXT := NULL;
	v_source_board_name TEXT := NULL;
	v_refresh jsonb;
BEGIN
    -- Safely convert flow detail text to JSONB
    IF p_flow_detail IS NOT NULL THEN
        v_flow_details := p_flow_detail::JSONB;
    END IF;

	--RAISE INFO 'v_flow_details : %', v_flow_details->'source';
 	v_source := v_flow_details->'source'; 
	v_target := v_flow_details->'targets'; 

	-- Loop through each tool_ticket_id
	FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
	LOOP 
		--Add Tool board Log
		SELECT COALESCE(MAX(tool_board_logid),0) + 1
		INTO v_new_tool_board_logid
		FROM tickets.tool_board_log;

		SELECT ticket_id INTO v_ticket_id
		FROM tickets.tool_detail 
		WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;	
				
		--RAISE INFO 'Ticeket_id : %', v_tool_ticket_id;

		SELECT tool_board_logid INTO v_tool_board_logid
		FROM tickets.tool_board_log
		WHERE is_active = true
		  AND board_id = (v_source->>'board_id')::integer
		  AND label_id = (v_source->>'label_id')::integer
		  AND tool_ticket_id = v_tool_ticket_id
		  AND is_moved = false
		  ORDER BY sequence DESC limit 1;
			  
	   INSERT INTO tickets.tool_board_log(
			tool_board_logid,
			ticket_id,
			tool_ticket_id,
			moved_by,
			board_id,
			label_id,
			moved_date,
			sequence,
			action_id,
			created_date,
			created_by,
			is_active
		)
		VALUES (
			v_new_tool_board_logid,
			v_ticket_id,
			v_tool_ticket_id,
			p_added_by,			
			(v_target->>'board_id')::integer,
			(v_target->>'label_id')::integer,
			current_timestamp AT TIME ZONE 'UTC',
			COALESCE((
				SELECT MAX(sequence) + 1
				FROM tickets.tool_board_log
				WHERE tool_ticket_id = v_tool_ticket_id
				  AND board_id = (v_target->>'board_id')::integer AND is_active = true
			), 1),
			p_action_id,
			current_timestamp AT TIME ZONE 'UTC',
			p_added_by,
			TRUE
		);
		GET DIAGNOSTICS v_count = ROW_COUNT;
		v_affected_rows := v_affected_rows + v_count;
		
		--If not unassigned flag, add tool_assignee entry
		IF NOT (v_target->>'unassigned')::boolean THEN			 					

			SELECT assignee_to INTO v_assignee_to
			FROM tickets.tool_assignee
			WHERE is_active = true
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND tool_board_logid = v_tool_board_logid
			  AND assignee_to IS NOT NULL
			ORDER BY sequence DESC
			LIMIT 1;	

			IF v_assignee_to IS NULL THEN				
				RAISE EXCEPTION 'assignee_to cannot be NULL or empty';			
			END IF;

			-- Insert into tool_assignee
			SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
			INTO v_new_tool_assignee_id
			FROM tickets.tool_assignee;

			INSERT INTO tickets.tool_assignee (
				tool_assignee_id,
				tool_board_logid,
				board_id,
				label_id,
				assignee_to,
				assigned_date,
				un_assigned_flag,            
				is_active,
				created_date,
				created_by,
				sequence
			)
			VALUES (
				v_new_tool_assignee_id,
				v_new_tool_board_logid,
				(v_target->>'board_id')::integer,
				(v_target->>'label_id')::integer,                
				v_assignee_to,
				current_timestamp AT TIME ZONE 'UTC',
				false,
				true,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by::text,
				1
			);	
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
		END IF;	
				
	END LOOP;
	
	
	IF ((v_source->>'board_id')::integer != (v_target->>'board_id')::integer) THEN									

		SELECT TRIM(name) INTO v_company_name 
		FROM tickets.ticket 
		WHERE ticket_id = v_ticket_id  AND is_active = true;

		SELECT "Name", work_space_id
		INTO v_board_name, v_work_space_id
		FROM board.board 
		WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;

		SELECT "Name"
		INTO v_source_board_name
		FROM board.board 
		WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
		
		SELECT "Name" INTO v_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;

		SELECT 			
			STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
		INTO 			
			v_recipient_push
		 FROM users.user_board_permission ubp
		 JOIN users.registereduser r ON r."RegId" = ubp.reg_id and r.is_active = true
		 where ubp.board_id = (v_target->>'board_id')::integer and ubp.is_active = true;

		-- Add Push Notification
		FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP

			-- Trim spaces if any
			v_reg := trim(v_reg);

			-- Call the existing add_notification procedure for each recipient
			CALL notification.add_notification(
				p_type := 'Push',
				p_recipient := v_reg,
				p_subject := 'New Card',
				p_message := 'A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
				p_retry_count := 0,
				p_max_retries := 3,
				p_message_json := '{
									"ticket_id": '|| v_ticket_id ||',
									"tool_id": 0,
									"tool_ticket_id": 0,
									"board_id": '|| (v_target->>'board_id')::integer ||',
									"moved_from": "'|| p_added_by ||'",
									"moved_to": "'|| v_reg ||'",
									"notify_message": "A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
									"is_read": false,
									"type": "task_ticket",	
									"workspace_id": '|| v_work_space_id ||',
									"header": "New Card"
								   }'::text,
				message := message,
				status := status
			);

		END LOOP;							

		PERFORM tickets.add_or_update_history_details(
			in_order_id           => v_ticket_id,
			   in_content            => CONCAT(
											'moved the ticket from ',
											COALESCE(v_source->>'board_name', ''),
											' to ',
											COALESCE(v_target->>'board_name', '')
										 ),
			in_user_id            => p_added_by,
			in_created_by         => p_added_by,
			in_created_date       => current_timestamp AT TIME ZONE 'UTC',
			in_uploaded_file_name => NULL,
			in_history_type       => 'Ticket board Movement'
		);
	END IF;

	--Moved to ticket another stage	
	IF p_is_moved THEN			
		-- Loop through each tool_ticket_id
		FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
		LOOP    	
					
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			UPDATE tickets.tool_board_log 
			SET is_moved = true
			WHERE tool_ticket_id = v_tool_ticket_id
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND is_moved = false;
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
			
		END LOOP;
		-- PERFORM tickets.add_or_update_history_details(
		-- 		in_order_id           => v_ticket_id,
		-- 		   in_content            => CONCAT(
		-- 										'moved the ticket from ',
		-- 										COALESCE(v_source->>'board_name', ''),
		-- 										' to ',
		-- 										COALESCE(v_target->>'board_name', '')
		-- 									 ),
		-- 		in_user_id            => p_added_by,
		-- 		in_created_by         => p_added_by,
		-- 		in_created_date       => current_timestamp AT TIME ZONE 'UTC',
		-- 		in_uploaded_file_name => NULL,
		-- 		in_history_type       => 'Task board Movement'
		-- 	);
			PERFORM tickets.add_or_update_history_details(
			    in_order_id => v_ticket_id,
			    in_content => CONCAT(
			        'moved the ticket from ',
			        COALESCE(v_source_board_name, ''),
			        ' to ',
			        COALESCE(v_board_name, '')
			    ),
			    in_user_id => p_added_by,
			    in_created_by => p_added_by,
			    in_created_date => current_timestamp AT TIME ZONE 'UTC',
			    in_uploaded_file_name => NULL,
			    in_history_type => 'Ticket board Movement'
			);
				
	END IF;		
	

	--Kanban board auto refresh			
	IF (v_source->>'board_id')::integer = (v_target->>'board_id')::integer THEN

		 v_refresh := jsonb_build_object(
				'tool_ticket_id', p_tool_ticket_id,
				'ticket_id', v_ticket_id,
				'board_id', (v_target->>'board_id')::integer,
				'from_label_id', (v_source->>'label_id')::integer,
				'to_label_id', (v_target->>'label_id')::integer,
				'type', 'MOVE',
				'added_by', p_added_by
			);

			autorefreshreq := (
				COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
			)::text;

	ELSIF (v_source->>'board_id')::integer <> (v_target->>'board_id')::integer THEN

		 v_refresh := jsonb_build_object(
				'tool_ticket_id', p_tool_ticket_id,
				'ticket_id', v_ticket_id,
				'board_id', (v_target->>'board_id')::integer,
				'from_label_id', 0,
				'to_label_id', (v_target->>'label_id')::integer,
				'type', 'ADD',
				'added_by', p_added_by
			);		

			autorefreshreq := (
				COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
			)::text;

	END IF;		
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN

		UPDATE tickets.ticket
        SET
            last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
			updated_by = p_added_by 
        WHERE ticket_id = v_ticket_id;
	         status := 'true';	
			 
        status := 'true';
        message := 'Task moved successfully.';		
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';		
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.move_task',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(
                ROW(
                    p_tool_ticket_id,
                    p_flow_detail,
                    p_flow_id,
                    p_action_id,
                    p_is_moved,
                    p_added_by
                )
            )::TEXT
        );

        status := 'false';
        message := SQLERRM; 
END;
$$;


--
-- Name: move_tool(integer[], integer, uuid, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.move_tool(IN p_tool_ticket_id integer[] DEFAULT '{}'::integer[], IN p_flow_id integer DEFAULT 0, IN p_action_id uuid DEFAULT NULL::uuid, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_tool
Developer   : Aravindhan.B
Created On  : 09-09-2025
Purpose     : Tool movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
19-09-2025  Aravindhan.B         Initial creation
18-09-2026  Mubarak Basha        unassigned=false: reassign from target board
                                 existing assignee (not source stage)
*******************************************************************************/
DECLARE
    v_context text;
	v_flow_details jsonb; -- store flow JSON here
	v_action jsonb;       -- matching action JSON
	v_source jsonb;       -- source object
    v_target jsonb;       -- each target object
	v_tool_ticket_id integer;
	v_new_tool_board_logid integer;
	v_ticket_id integer;
	v_new_tool_assignee_id integer;
	v_assignee_to UUID;
	v_affected_rows int := 0; -- track inserts/updates
    v_count int;              -- for diagnostics
		
    -- variables for auto_move_ticket call
    v_msg varchar;
    v_status varchar;	
	v_tool_board_logid integer;
	
	v_company_name			TEXT 	:= NULL;
	v_tool_list				TEXT 	:= NULL;	
	v_source_board_name		TEXT 	:= NULL;
	v_target_board_name		TEXT 	:= NULL;	
	v_source_label_name		TEXT 	:= NULL;
	v_target_label_name		TEXT 	:= NULL;	
	v_subject				TEXT	:= NULL;
	v_recipient_email		TEXT 	:= NULL;
	v_recipient_push		TEXT 	:= NULL;
	v_email 				TEXT 	:= NULL;
	v_message				TEXT 	:= NULL;
	v_reg	 				TEXT 	:= NULL;	
	v_work_space_id			INTEGER := 0;
	v_refresh jsonb;
BEGIN

    -- Get flow JSON for given flow_id
    SELECT flow_details
    INTO v_flow_details
    FROM board.flow
    WHERE flow_id = p_flow_id
    LIMIT 1;

    IF v_flow_details IS NULL THEN
        status := 'false';
        message := format('No flow found for flow_id: %s', p_flow_id);
        RETURN;
    END IF;	
	
    -- Find the action object matching the action_id
    SELECT elem
    INTO v_action
    FROM jsonb_array_elements(v_flow_details) elem
    WHERE elem->>'action_id' = p_action_id::text
    LIMIT 1;

    IF v_action IS NULL THEN
        status := 'false';
        message := format('No action found for action_id: %s in flow_id: %s', p_action_id, p_flow_id);
        RETURN;
    END IF;	
	
	-- Extract source object
    v_source := v_action->'Source';    

    -- Extract each target individually
    FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
    LOOP        
	
		SELECT "Name"
		INTO v_source_board_name
		FROM board.board 
		WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
		
		SELECT "Name", work_space_id
		INTO v_target_board_name, v_work_space_id
		FROM board.board 
		WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;
			
		SELECT "Name" INTO v_source_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_source->>'board_id')::integer AND "LabelID" = (v_source->>'label_id')::integer AND is_active = TRUE;
		
		SELECT "Name" INTO v_target_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;
		
        -- Loop through each tool_ticket_id
        FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
        LOOP            

		 	SELECT COALESCE(MAX(tool_board_logid),0) + 1
			INTO v_new_tool_board_logid
			FROM tickets.tool_board_log;
			
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			SELECT tool_board_logid INTO v_tool_board_logid
			FROM tickets.tool_board_log
			WHERE is_active = true
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND tool_ticket_id = v_tool_ticket_id
			  AND is_moved = false
			  ORDER BY sequence DESC limit 1;
	
            INSERT INTO tickets.tool_board_log(
				tool_board_logid,
				ticket_id,
				tool_ticket_id,
				moved_by,
				board_id,
				label_id,
				moved_date,
				sequence,
				action_id,
				created_date,
				created_by,
				is_active
			)
			VALUES (
				v_new_tool_board_logid,
				v_ticket_id,
				v_tool_ticket_id,
				p_added_by,			
				(v_target->>'board_id')::integer,
				(v_target->>'label_id')::integer,
				current_timestamp AT TIME ZONE 'UTC',
				COALESCE((
					SELECT MAX(sequence) + 1
					FROM tickets.tool_board_log
					WHERE tool_ticket_id = v_tool_ticket_id
					  AND board_id = (v_target->>'board_id')::integer AND is_active = true
				), 1),
				p_action_id,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				TRUE
			);
            GET DIAGNOSTICS v_count = ROW_COUNT;
            v_affected_rows := v_affected_rows + v_count;
			
			-- Assignee rules (per board flow):
			--   unassigned = true  => move with empty assignee (no tool_assignee insert)
			--   unassigned = false => reassign using existing assignee on the TARGET board
			--                         for this tool (e.g. Onboarding Tool Creation -> A;
			--                         when returning to Onboarding Final QC, restore A).
			--                         Do NOT copy assignee from another board (e.g. Production B).
			-- Same-board moves: if no prior assignee on target board yet, use source stage.
			IF COALESCE((v_target->>'unassigned')::boolean, FALSE) = FALSE THEN
				v_assignee_to := NULL;

				-- Existing assignee already on the target board for this tool
				SELECT ta.assignee_to
				INTO v_assignee_to
				FROM tickets.tool_assignee ta
				JOIN tickets.tool_board_log tbl
				  ON ta.tool_board_logid = tbl.tool_board_logid
				 AND ta.board_id = tbl.board_id
				 AND ta.label_id = tbl.label_id
				WHERE ta.is_active = true
				  AND tbl.is_active = true
				  AND tbl.tool_ticket_id = v_tool_ticket_id
				  AND ta.board_id = (v_target->>'board_id')::integer
				  AND ta.assignee_to IS NOT NULL
				  AND COALESCE(ta.un_assigned_flag, FALSE) = FALSE
				ORDER BY tbl.sequence DESC, ta.sequence DESC
				LIMIT 1;

				-- Same-board only: carry forward source-stage assignee
				IF v_assignee_to IS NULL
				   AND (v_source->>'board_id')::integer = (v_target->>'board_id')::integer
				   AND v_tool_board_logid IS NOT NULL THEN
					SELECT ta.assignee_to
					INTO v_assignee_to
					FROM tickets.tool_assignee ta
					WHERE ta.is_active = true
					  AND ta.board_id = (v_source->>'board_id')::integer
					  AND ta.label_id = (v_source->>'label_id')::integer
					  AND ta.tool_board_logid = v_tool_board_logid
					  AND ta.assignee_to IS NOT NULL
					  AND COALESCE(ta.un_assigned_flag, FALSE) = FALSE
					ORDER BY ta.sequence DESC
					LIMIT 1;
				END IF;

				IF v_assignee_to IS NOT NULL THEN
					SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
					INTO v_new_tool_assignee_id
					FROM tickets.tool_assignee;

					INSERT INTO tickets.tool_assignee (
						tool_assignee_id,
						tool_board_logid,
						board_id,
						label_id,
						assignee_to,
						assigned_date,
						un_assigned_flag,
						is_active,
						created_date,
						created_by,
						sequence
					)
					VALUES (
						v_new_tool_assignee_id,
						v_new_tool_board_logid,
						(v_target->>'board_id')::integer,
						(v_target->>'label_id')::integer,
						v_assignee_to,
						current_timestamp AT TIME ZONE 'UTC',
						false,
						true,
						current_timestamp AT TIME ZONE 'UTC',
						p_added_by::text,
						1
					);
					GET DIAGNOSTICS v_count = ROW_COUNT;
					v_affected_rows := v_affected_rows + v_count;
				END IF;
			END IF;
			
			PERFORM tickets.add_or_update_history_details(
					in_order_id           => v_ticket_id,
					in_tool_ticket_id     => v_tool_ticket_id,
					in_content => CONCAT(
											    'moved the tool from ',
											    COALESCE(v_source_board_name, ''), ' - "',
											    COALESCE(v_source_label_name, ''), '"',
											    ' to ',
											    COALESCE(v_target_board_name, ''), ' - "',
											    COALESCE(v_target_label_name, ''), '"'
											),
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Tool label Movement'
				);
				
        END LOOP;
		
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_target->>'board_id')::integer,
			false,
            p_added_by,
            v_msg,
            v_status
        );		
		
		--Email Notification
		IF ((v_source->>'board_id')::integer != (v_target->>'board_id')::integer) THEN									
						
			
			SELECT TRIM(name) INTO v_company_name 
			FROM tickets.ticket 
			WHERE ticket_id = v_ticket_id  AND is_active = true;
						
			
			SELECT STRING_AGG(t."ToolName", ', ') AS "ToolNames" INTO v_tool_list
			FROM tickets.tool_detail td
			JOIN master.tool t 
			  ON t."ToolID" = td.tool_id 
			  AND t.is_active = TRUE
			WHERE td.tool_ticket_id = ANY(p_tool_ticket_id)
			  AND td.is_active = TRUE;			
			
			v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_tool_list, '') || '" , "boardName": "' || COALESCE(v_target_board_name, '') || '",
					"stage": "' || COALESCE(v_target_label_name, '') || '"}}';	
					
			SELECT subject
			INTO v_subject
			FROM master.mailtemplate
			WHERE mailtemplatetype = 'NewCardArrived'
			  AND is_active = true
			LIMIT 1;	
			
			 SELECT 
				STRING_AGG(r."Email", ', ') AS recipient_email,
				STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
			INTO 
				v_recipient_email, 
				v_recipient_push
			 FROM users.user_board_permission ubp
			 JOIN users.registereduser r ON r."RegId" = ubp.reg_id and r.is_active = true
			 where ubp.board_id = (v_target->>'board_id')::integer and ubp.is_active = true;
			 
			 -- Add Email Notification
			FOR v_email IN SELECT unnest(string_to_array(v_recipient_email, ',')) LOOP

				-- Trim spaces if any
				v_email := trim(v_email);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Email',
					p_recipient := v_email,
					p_subject := v_subject,
					p_message := v_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := NULL,
					message := message,
					status := status
				);

			END LOOP;
			
			
			-- Add Push Notification
			FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
				
				-- Trim spaces if any
				v_reg := trim(v_reg);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_reg,
					p_subject := 'New Card',
					p_message := 'A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := '{
										"ticket_id": '|| v_ticket_id ||',
										"tool_id": 0,
										"tool_ticket_id": 0,
										"board_id": '|| (v_target->>'board_id')::integer ||',
										"moved_from": "'|| p_added_by ||'",
										"moved_to": "'|| v_reg ||'",
										"notify_message": "A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
										"is_read": false,
										"type": "moved the ticket",	
										"workspace_id": '|| v_work_space_id ||',
										"header": "New Card"
									   }'::text,
					message := message,
					status := status
				);
				
			END LOOP;							
			
			PERFORM tickets.add_or_update_history_details(
				in_order_id           => v_ticket_id,
				   in_content            => CONCAT(
												'moved the ticket from ',
												COALESCE(v_source_board_name, ''),
												' to ',
												COALESCE(v_target_board_name, '')
											 ),
				in_user_id            => p_added_by,
				in_created_by         => p_added_by,
				in_created_date       => current_timestamp AT TIME ZONE 'UTC',
				in_uploaded_file_name => NULL,
				in_history_type       => 'Ticket board Movement'
			);
		END IF;
		
		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;		
		END IF;
		
    END LOOP;
		
	--Moved to ticket another stage	
	IF p_is_moved THEN	
		
		-- Loop through each tool_ticket_id
		FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
		LOOP    	
					
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			UPDATE tickets.tool_board_log 
			SET is_moved = true
			WHERE tool_ticket_id = v_tool_ticket_id
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND is_moved = false;
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
			
		END LOOP;
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_source->>'board_id')::integer,
			true,
            p_added_by,
            v_msg,
            v_status
        );

		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;	
		END IF;
		
	END IF;	
	
	--Kanban board auto refresh	
    FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
    LOOP   
				
		IF (v_source->>'board_id')::integer = (v_target->>'board_id')::integer THEN

			 v_refresh := jsonb_build_object(
					'tool_ticket_id', p_tool_ticket_id,
					'ticket_id', v_ticket_id,
					'board_id', (v_target->>'board_id')::integer,
					'from_label_id', (v_source->>'label_id')::integer,
					'to_label_id', (v_target->>'label_id')::integer,
					'type', 'MOVE',
					'added_by', p_added_by
				);
				
				autorefreshreq := (
					COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
				)::text;
	
		ELSIF (v_source->>'board_id')::integer <> (v_target->>'board_id')::integer THEN
		
			 v_refresh := jsonb_build_object(
					'tool_ticket_id', p_tool_ticket_id,
					'ticket_id', v_ticket_id,
					'board_id', (v_target->>'board_id')::integer,
					'from_label_id', 0,
					'to_label_id', (v_target->>'label_id')::integer,
					'type', 'ADD',
					'added_by', p_added_by
				);		

				autorefreshreq := (
					COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
				)::text;

		END IF;	
	END LOOP;
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN
        status := 'true';
        message := 'Tool moved successfully.';
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';
    END IF;

EXCEPTION
    WHEN OTHERS THEN	
		ROLLBACK;		
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.move_tool',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_flow_id, p_action_id, p_is_moved, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: move_tool_backup(integer[], integer, uuid, boolean, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.move_tool_backup(IN p_tool_ticket_id integer[] DEFAULT '{}'::integer[], IN p_flow_id integer DEFAULT 0, IN p_action_id uuid DEFAULT NULL::uuid, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_tool
Developer   : Aravindhan.B
Created On  : 09-09-2025
Purpose     : Tool movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
19-09-2025  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context text;
	v_flow_details jsonb; -- store flow JSON here
	v_action jsonb;       -- matching action JSON
	v_source jsonb;       -- source object
    v_target jsonb;       -- each target object
	v_tool_ticket_id integer;
	v_new_tool_board_logid integer;
	v_ticket_id integer;
	v_new_tool_assignee_id integer;
	v_assignee_to UUID;
	v_affected_rows int := 0; -- track inserts/updates
    v_count int;              -- for diagnostics
		
    -- variables for auto_move_ticket call
    v_msg varchar;
    v_status varchar;	
	v_tool_board_logid integer;
	
	v_company_name			TEXT 	:= NULL;
	v_tool_list				TEXT 	:= NULL;	
	v_source_board_name		TEXT 	:= NULL;
	v_target_board_name		TEXT 	:= NULL;	
	v_source_label_name		TEXT 	:= NULL;
	v_target_label_name		TEXT 	:= NULL;	
	v_subject				TEXT	:= NULL;
	v_recipient_email		TEXT 	:= NULL;
	v_recipient_push		TEXT 	:= NULL;
	v_email 				TEXT 	:= NULL;
	v_message				TEXT 	:= NULL;
	v_reg	 				TEXT 	:= NULL;	
	v_work_space_id			INTEGER := 0;
BEGIN

    -- Get flow JSON for given flow_id
    SELECT flow_details
    INTO v_flow_details
    FROM board.flow
    WHERE flow_id = p_flow_id
    LIMIT 1;

    IF v_flow_details IS NULL THEN
        status := 'false';
        message := format('No flow found for flow_id: %s', p_flow_id);
        RETURN;
    END IF;	
	
    -- Find the action object matching the action_id
    SELECT elem
    INTO v_action
    FROM jsonb_array_elements(v_flow_details) elem
    WHERE elem->>'action_id' = p_action_id::text
    LIMIT 1;

    IF v_action IS NULL THEN
        status := 'false';
        message := format('No action found for action_id: %s in flow_id: %s', p_action_id, p_flow_id);
        RETURN;
    END IF;	
	
	-- Extract source object
    v_source := v_action->'Source';    

    -- Extract each target individually
    FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
    LOOP        
	
		SELECT "Name"
		INTO v_source_board_name
		FROM board.board 
		WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
		
		SELECT "Name", work_space_id
		INTO v_target_board_name, v_work_space_id
		FROM board.board 
		WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;
			
		SELECT "Name" INTO v_source_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_source->>'board_id')::integer AND "LabelID" = (v_source->>'label_id')::integer AND is_active = TRUE;
		
		SELECT "Name" INTO v_target_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;
		
        -- Loop through each tool_ticket_id
        FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
        LOOP            

		 	SELECT COALESCE(MAX(tool_board_logid),0) + 1
			INTO v_new_tool_board_logid
			FROM tickets.tool_board_log;
			
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			SELECT tool_board_logid INTO v_tool_board_logid
			FROM tickets.tool_board_log
			WHERE is_active = true
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND tool_ticket_id = v_tool_ticket_id
			  AND is_moved = false
			  ORDER BY sequence DESC limit 1;
	
            INSERT INTO tickets.tool_board_log(
				tool_board_logid,
				ticket_id,
				tool_ticket_id,
				moved_by,
				board_id,
				label_id,
				moved_date,
				sequence,
				action_id,
				created_date,
				created_by,
				is_active
			)
			VALUES (
				v_new_tool_board_logid,
				v_ticket_id,
				v_tool_ticket_id,
				p_added_by,			
				(v_target->>'board_id')::integer,
				(v_target->>'label_id')::integer,
				current_timestamp AT TIME ZONE 'UTC',
				COALESCE((
					SELECT MAX(sequence) + 1
					FROM tickets.tool_board_log
					WHERE tool_ticket_id = v_tool_ticket_id
					  AND board_id = (v_target->>'board_id')::integer AND is_active = true
				), 1),
				p_action_id,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				TRUE
			);
            GET DIAGNOSTICS v_count = ROW_COUNT;
            v_affected_rows := v_affected_rows + v_count;
			
			--If not unassigned flag, add tool_assignee entry
			IF NOT (v_target->>'unassigned')::boolean THEN			 					
			 
				SELECT assignee_to INTO v_assignee_to
				FROM tickets.tool_assignee
				WHERE is_active = true
				  AND board_id = (v_source->>'board_id')::integer
				  AND label_id = (v_source->>'label_id')::integer
				  AND tool_board_logid = v_tool_board_logid
				  AND assignee_to IS NOT NULL
				ORDER BY sequence DESC
				LIMIT 1;	
																			    
				IF v_assignee_to IS NULL THEN				
					RAISE EXCEPTION 'assignee_to cannot be NULL or empty';			
				END IF;
				
				-- Insert into tool_assignee
				SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
				INTO v_new_tool_assignee_id
				FROM tickets.tool_assignee;
								 
				 
				INSERT INTO tickets.tool_assignee (
					tool_assignee_id,
					tool_board_logid,
					board_id,
					label_id,
					assignee_to,
					assigned_date,
					un_assigned_flag,            
					is_active,
					created_date,
					created_by,
					sequence
				)
				VALUES (
					v_new_tool_assignee_id,
					v_new_tool_board_logid,
					(v_target->>'board_id')::integer,
					(v_target->>'label_id')::integer,                
					v_assignee_to,
					current_timestamp AT TIME ZONE 'UTC',
					false,
					true,
					current_timestamp AT TIME ZONE 'UTC',
					p_added_by::text,
					1
				);	
				GET DIAGNOSTICS v_count = ROW_COUNT;
                v_affected_rows := v_affected_rows + v_count;
			END IF;	
			
			PERFORM tickets.add_or_update_history_details(
					in_order_id           => v_ticket_id,
					in_tool_ticket_id     => v_tool_ticket_id,
					in_content            => CONCAT(
												'moved the tool from ',
												COALESCE(v_source_label_name, ''),
												' to ',
												COALESCE(v_target_label_name, '')
											 ),
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Tool label Movement'
				);
				
        END LOOP;
		
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_target->>'board_id')::integer,
			false,
            p_added_by,
            v_msg,
            v_status
        );		
		
		--Email Notification
		IF ((v_source->>'board_id')::integer != (v_target->>'board_id')::integer) THEN									
						
			
			SELECT TRIM(name) INTO v_company_name 
			FROM tickets.ticket 
			WHERE ticket_id = v_ticket_id  AND is_active = true;
						
			
			SELECT STRING_AGG(t."ToolName", ', ') AS "ToolNames" INTO v_tool_list
			FROM tickets.tool_detail td
			JOIN master.tool t 
			  ON t."ToolID" = td.tool_id 
			  AND t.is_active = TRUE
			WHERE td.tool_ticket_id = ANY(p_tool_ticket_id)
			  AND td.is_active = TRUE;			
			
			v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_tool_list, '') || '" , "boardName": "' || COALESCE(v_target_board_name, '') || '",
					"stage": "' || COALESCE(v_target_label_name, '') || '"}}';	
					
			SELECT subject
			INTO v_subject
			FROM master.mailtemplate
			WHERE mailtemplatetype = 'NewCardArrived'
			  AND is_active = true
			LIMIT 1;	
			
			 SELECT 
				STRING_AGG(r."Email", ', ') AS recipient_email,
				STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
			INTO 
				v_recipient_email, 
				v_recipient_push
			 FROM users.user_board_permission ubp
			 JOIN users.registereduser r ON r."RegId" = ubp.reg_id and r.is_active = true
			 where ubp.board_id = (v_target->>'board_id')::integer and ubp.is_active = true;
			 
			 -- Add Email Notification
			FOR v_email IN SELECT unnest(string_to_array(v_recipient_email, ',')) LOOP

				-- Trim spaces if any
				v_email := trim(v_email);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Email',
					p_recipient := v_email,
					p_subject := v_subject,
					p_message := v_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := NULL,
					message := message,
					status := status
				);

			END LOOP;
			
			
			-- Add Push Notification
			FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
				
				-- Trim spaces if any
				v_reg := trim(v_reg);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_reg,
					p_subject := 'New Card',
					p_message := 'A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := '{
										"ticket_id": '|| v_ticket_id ||',
										"tool_id": 0,
										"tool_ticket_id": 0,
										"board_id": '|| (v_target->>'board_id')::integer ||',
										"moved_from": "'|| p_added_by ||'",
										"moved_to": "'|| v_reg ||'",
										"notify_message": "A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
										"is_read": false,
										"type": "moved the ticket",	
										"workspace_id": '|| v_work_space_id ||',
										"header": "New Card"
									   }'::text,
					message := message,
					status := status
				);
				
			END LOOP;							
			
			PERFORM tickets.add_or_update_history_details(
				in_order_id           => v_ticket_id,
				   in_content            => CONCAT(
												'moved the ticket from ',
												COALESCE(v_source_board_name, ''),
												' to ',
												COALESCE(v_target_board_name, '')
											 ),
				in_user_id            => p_added_by,
				in_created_by         => p_added_by,
				in_created_date       => current_timestamp AT TIME ZONE 'UTC',
				in_uploaded_file_name => NULL,
				in_history_type       => 'Ticket board Movement'
			);
		END IF;
		
		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;		
		END IF;
		
    END LOOP;
		
	--Moved to ticket another stage	
	IF p_is_moved THEN	
		
		-- Loop through each tool_ticket_id
		FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
		LOOP    	
					
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			UPDATE tickets.tool_board_log 
			SET is_moved = true
			WHERE tool_ticket_id = v_tool_ticket_id
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND is_moved = false;
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
			
		END LOOP;
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_source->>'board_id')::integer,
			true,
            p_added_by,
            v_msg,
            v_status
        );

		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;	
		END IF;
		
	END IF;	
	
	--Kanban board auto refresh	
--     FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
--     LOOP   
				
-- 		IF (v_source->>'board_id')::integer = (v_target->>'board_id')::integer THEN

-- 			CALL tickets.main_sub_board_refresh(
-- 				p_tool_ticket_id,
-- 				v_ticket_id,
-- 				(v_target->>'board_id')::integer,
-- 				(v_source->>'label_id')::integer,
-- 				(v_target->>'label_id')::integer,
-- 				'MOVE',
-- 				p_added_by,
-- 				message := message,
-- 				status := status
-- 			);
			
-- 		ELSIF (v_source->>'board_id')::integer <> (v_target->>'board_id')::integer THEN
		
-- 			CALL tickets.main_sub_board_refresh(
-- 				p_tool_ticket_id,
-- 				v_ticket_id,
-- 				(v_target->>'board_id')::integer,
-- 				0,
-- 				(v_target->>'label_id')::integer,
-- 				'ADD',
-- 				p_added_by,
-- 				message := message,
-- 				status := status
-- 			);
			
-- 		END IF;	
-- 	END LOOP;
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN
        status := 'true';
        message := 'Tool moved successfully.';
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';
    END IF;

EXCEPTION
    WHEN OTHERS THEN	
		ROLLBACK;		
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.move_tool',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_flow_id, p_action_id, p_is_moved, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: move_tool_backup_19062026(integer[], integer, uuid, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.move_tool_backup_19062026(IN p_tool_ticket_id integer[] DEFAULT '{}'::integer[], IN p_flow_id integer DEFAULT 0, IN p_action_id uuid DEFAULT NULL::uuid, IN p_is_moved boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.move_tool
Developer   : Aravindhan.B
Created On  : 09-09-2025
Purpose     : Tool movement

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
19-09-2025  Aravindhan.B         Initial creation
*******************************************************************************/
DECLARE
    v_context text;
	v_flow_details jsonb; -- store flow JSON here
	v_action jsonb;       -- matching action JSON
	v_source jsonb;       -- source object
    v_target jsonb;       -- each target object
	v_tool_ticket_id integer;
	v_new_tool_board_logid integer;
	v_ticket_id integer;
	v_new_tool_assignee_id integer;
	v_assignee_to UUID;
	v_affected_rows int := 0; -- track inserts/updates
    v_count int;              -- for diagnostics
		
    -- variables for auto_move_ticket call
    v_msg varchar;
    v_status varchar;	
	v_tool_board_logid integer;
	
	v_company_name			TEXT 	:= NULL;
	v_tool_list				TEXT 	:= NULL;	
	v_source_board_name		TEXT 	:= NULL;
	v_target_board_name		TEXT 	:= NULL;	
	v_source_label_name		TEXT 	:= NULL;
	v_target_label_name		TEXT 	:= NULL;	
	v_subject				TEXT	:= NULL;
	v_recipient_email		TEXT 	:= NULL;
	v_recipient_push		TEXT 	:= NULL;
	v_email 				TEXT 	:= NULL;
	v_message				TEXT 	:= NULL;
	v_reg	 				TEXT 	:= NULL;	
	v_work_space_id			INTEGER := 0;
	v_refresh jsonb;
BEGIN

    -- Get flow JSON for given flow_id
    SELECT flow_details
    INTO v_flow_details
    FROM board.flow
    WHERE flow_id = p_flow_id
    LIMIT 1;

    IF v_flow_details IS NULL THEN
        status := 'false';
        message := format('No flow found for flow_id: %s', p_flow_id);
        RETURN;
    END IF;	
	
    -- Find the action object matching the action_id
    SELECT elem
    INTO v_action
    FROM jsonb_array_elements(v_flow_details) elem
    WHERE elem->>'action_id' = p_action_id::text
    LIMIT 1;

    IF v_action IS NULL THEN
        status := 'false';
        message := format('No action found for action_id: %s in flow_id: %s', p_action_id, p_flow_id);
        RETURN;
    END IF;	
	
	-- Extract source object
    v_source := v_action->'Source';    

    -- Extract each target individually
    FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
    LOOP        
	
		SELECT "Name"
		INTO v_source_board_name
		FROM board.board 
		WHERE "BoardID" = (v_source->>'board_id')::integer AND is_active = TRUE;
		
		SELECT "Name", work_space_id
		INTO v_target_board_name, v_work_space_id
		FROM board.board 
		WHERE "BoardID" = (v_target->>'board_id')::integer AND is_active = TRUE;
			
		SELECT "Name" INTO v_source_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_source->>'board_id')::integer AND "LabelID" = (v_source->>'label_id')::integer AND is_active = TRUE;
		
		SELECT "Name" INTO v_target_label_name 
		FROM board.boardstatus
		WHERE "BoardID" = (v_target->>'board_id')::integer AND "LabelID" = (v_target->>'label_id')::integer AND is_active = TRUE;
		
        -- Loop through each tool_ticket_id
        FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
        LOOP            

		 	SELECT COALESCE(MAX(tool_board_logid),0) + 1
			INTO v_new_tool_board_logid
			FROM tickets.tool_board_log;
			
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			SELECT tool_board_logid INTO v_tool_board_logid
			FROM tickets.tool_board_log
			WHERE is_active = true
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND tool_ticket_id = v_tool_ticket_id
			  AND is_moved = false
			  ORDER BY sequence DESC limit 1;
	
            INSERT INTO tickets.tool_board_log(
				tool_board_logid,
				ticket_id,
				tool_ticket_id,
				moved_by,
				board_id,
				label_id,
				moved_date,
				sequence,
				action_id,
				created_date,
				created_by,
				is_active
			)
			VALUES (
				v_new_tool_board_logid,
				v_ticket_id,
				v_tool_ticket_id,
				p_added_by,			
				(v_target->>'board_id')::integer,
				(v_target->>'label_id')::integer,
				current_timestamp AT TIME ZONE 'UTC',
				COALESCE((
					SELECT MAX(sequence) + 1
					FROM tickets.tool_board_log
					WHERE tool_ticket_id = v_tool_ticket_id
					  AND board_id = (v_target->>'board_id')::integer AND is_active = true
				), 1),
				p_action_id,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				TRUE
			);
            GET DIAGNOSTICS v_count = ROW_COUNT;
            v_affected_rows := v_affected_rows + v_count;
			
			--If not unassigned flag, add tool_assignee entry
			IF NOT (v_target->>'unassigned')::boolean THEN			 					
			 
				SELECT assignee_to INTO v_assignee_to
				FROM tickets.tool_assignee
				WHERE is_active = true
				  AND board_id = (v_source->>'board_id')::integer
				  AND label_id = (v_source->>'label_id')::integer
				  AND tool_board_logid = v_tool_board_logid
				  AND assignee_to IS NOT NULL
				ORDER BY sequence DESC
				LIMIT 1;	
																			    
				IF v_assignee_to IS NULL THEN				
					RAISE EXCEPTION 'assignee_to cannot be NULL or empty';			
				END IF;
				
				-- Insert into tool_assignee
				SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
				INTO v_new_tool_assignee_id
				FROM tickets.tool_assignee;
								 
				 
				INSERT INTO tickets.tool_assignee (
					tool_assignee_id,
					tool_board_logid,
					board_id,
					label_id,
					assignee_to,
					assigned_date,
					un_assigned_flag,            
					is_active,
					created_date,
					created_by,
					sequence
				)
				VALUES (
					v_new_tool_assignee_id,
					v_new_tool_board_logid,
					(v_target->>'board_id')::integer,
					(v_target->>'label_id')::integer,                
					v_assignee_to,
					current_timestamp AT TIME ZONE 'UTC',
					false,
					true,
					current_timestamp AT TIME ZONE 'UTC',
					p_added_by::text,
					1
				);	
				GET DIAGNOSTICS v_count = ROW_COUNT;
                v_affected_rows := v_affected_rows + v_count;
			END IF;	
			
			PERFORM tickets.add_or_update_history_details(
					in_order_id           => v_ticket_id,
					in_tool_ticket_id     => v_tool_ticket_id,
					in_content => CONCAT(
											    'moved the tool from ',
											    COALESCE(v_source_board_name, ''), ' - "',
											    COALESCE(v_source_label_name, ''), '"',
											    ' to ',
											    COALESCE(v_target_board_name, ''), ' - "',
											    COALESCE(v_target_label_name, ''), '"'
											),
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Tool label Movement'
				);
				
        END LOOP;
		
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_target->>'board_id')::integer,
			false,
            p_added_by,
            v_msg,
            v_status
        );		
		
		--Email Notification
		IF ((v_source->>'board_id')::integer != (v_target->>'board_id')::integer) THEN									
						
			
			SELECT TRIM(name) INTO v_company_name 
			FROM tickets.ticket 
			WHERE ticket_id = v_ticket_id  AND is_active = true;
						
			
			SELECT STRING_AGG(t."ToolName", ', ') AS "ToolNames" INTO v_tool_list
			FROM tickets.tool_detail td
			JOIN master.tool t 
			  ON t."ToolID" = td.tool_id 
			  AND t.is_active = TRUE
			WHERE td.tool_ticket_id = ANY(p_tool_ticket_id)
			  AND td.is_active = TRUE;			
			
			v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_tool_list, '') || '" , "boardName": "' || COALESCE(v_target_board_name, '') || '",
					"stage": "' || COALESCE(v_target_label_name, '') || '"}}';	
					
			SELECT subject
			INTO v_subject
			FROM master.mailtemplate
			WHERE mailtemplatetype = 'NewCardArrived'
			  AND is_active = true
			LIMIT 1;	
			
			 SELECT 
				STRING_AGG(r."Email", ', ') AS recipient_email,
				STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
			INTO 
				v_recipient_email, 
				v_recipient_push
			 FROM users.user_board_permission ubp
			 JOIN users.registereduser r ON r."RegId" = ubp.reg_id and r.is_active = true
			 where ubp.board_id = (v_target->>'board_id')::integer and ubp.is_active = true;
			 
			 -- Add Email Notification
			FOR v_email IN SELECT unnest(string_to_array(v_recipient_email, ',')) LOOP

				-- Trim spaces if any
				v_email := trim(v_email);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Email',
					p_recipient := v_email,
					p_subject := v_subject,
					p_message := v_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := NULL,
					message := message,
					status := status
				);

			END LOOP;
			
			
			-- Add Push Notification
			FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
				
				-- Trim spaces if any
				v_reg := trim(v_reg);

				-- Call the existing add_notification procedure for each recipient
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_reg,
					p_subject := 'New Card',
					p_message := 'A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := '{
										"ticket_id": '|| v_ticket_id ||',
										"tool_id": 0,
										"tool_ticket_id": 0,
										"board_id": '|| (v_target->>'board_id')::integer ||',
										"moved_from": "'|| p_added_by ||'",
										"moved_to": "'|| v_reg ||'",
										"notify_message": "A new card has arrived in the <b>' || COALESCE(v_target_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
										"is_read": false,
										"type": "moved the ticket",	
										"workspace_id": '|| v_work_space_id ||',
										"header": "New Card"
									   }'::text,
					message := message,
					status := status
				);
				
			END LOOP;							
			
			PERFORM tickets.add_or_update_history_details(
				in_order_id           => v_ticket_id,
				   in_content            => CONCAT(
												'moved the ticket from ',
												COALESCE(v_source_board_name, ''),
												' to ',
												COALESCE(v_target_board_name, '')
											 ),
				in_user_id            => p_added_by,
				in_created_by         => p_added_by,
				in_created_date       => current_timestamp AT TIME ZONE 'UTC',
				in_uploaded_file_name => NULL,
				in_history_type       => 'Ticket board Movement'
			);
		END IF;
		
		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;		
		END IF;
		
    END LOOP;
		
	--Moved to ticket another stage	
	IF p_is_moved THEN	
		
		-- Loop through each tool_ticket_id
		FOREACH v_tool_ticket_id IN ARRAY p_tool_ticket_id
		LOOP    	
					
			SELECT ticket_id INTO v_ticket_id
			FROM tickets.tool_detail 
			WHERE tool_ticket_id = v_tool_ticket_id AND is_active = true;
			
			UPDATE tickets.tool_board_log 
			SET is_moved = true
			WHERE tool_ticket_id = v_tool_ticket_id
			  AND board_id = (v_source->>'board_id')::integer
			  AND label_id = (v_source->>'label_id')::integer
			  AND is_moved = false;
			GET DIAGNOSTICS v_count = ROW_COUNT;
			v_affected_rows := v_affected_rows + v_count;
			
		END LOOP;
		
        --Correct CALL to auto_move_ticket with INOUT params
        CALL tickets.auto_move_ticket(
            v_ticket_id,
            (v_source->>'board_id')::integer,
			true,
            p_added_by,
            v_msg,
            v_status
        );

		IF v_status = 'false' THEN
        	RAISE INFO 'AutoMoveTicket -> Status: %, Message: %', v_status, v_msg;	
		END IF;
		
	END IF;	
	
	--Kanban board auto refresh	
    FOR v_target IN SELECT * FROM jsonb_array_elements(v_action->'Targets')
    LOOP   
				
		IF (v_source->>'board_id')::integer = (v_target->>'board_id')::integer THEN

			 v_refresh := jsonb_build_object(
					'tool_ticket_id', p_tool_ticket_id,
					'ticket_id', v_ticket_id,
					'board_id', (v_target->>'board_id')::integer,
					'from_label_id', (v_source->>'label_id')::integer,
					'to_label_id', (v_target->>'label_id')::integer,
					'type', 'MOVE',
					'added_by', p_added_by
				);
				
				autorefreshreq := (
					COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
				)::text;
	
		ELSIF (v_source->>'board_id')::integer <> (v_target->>'board_id')::integer THEN
		
			 v_refresh := jsonb_build_object(
					'tool_ticket_id', p_tool_ticket_id,
					'ticket_id', v_ticket_id,
					'board_id', (v_target->>'board_id')::integer,
					'from_label_id', 0,
					'to_label_id', (v_target->>'label_id')::integer,
					'type', 'ADD',
					'added_by', p_added_by
				);		

				autorefreshreq := (
					COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
				)::text;

		END IF;	
	END LOOP;
	
    -- Main logic will go here (currently just a success placeholder)
    IF v_affected_rows > 0 THEN
        status := 'true';
        message := 'Tool moved successfully.';
    ELSE
        status := 'false';
        message := 'No records were updated or inserted.';
    END IF;

EXCEPTION
    WHEN OTHERS THEN	
		ROLLBACK;		
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.move_tool',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_flow_id, p_action_id, p_is_moved, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: orders_focus_detailed_view_filters(date, date, integer, uuid, integer[], text, integer[], integer[], integer[], uuid[], integer[], integer[], integer[], integer[], integer[], integer[], integer[]); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.orders_focus_detailed_view_filters(p_from_date date, p_to_date date, p_usertypeid integer, p_regid uuid, p_workspaceids integer[], p_tasktype text, p_boardids integer[] DEFAULT NULL::integer[], p_ordertype integer[] DEFAULT NULL::integer[], p_order_labels integer[] DEFAULT NULL::integer[], p_assignee uuid[] DEFAULT NULL::uuid[], p_order_stage_list integer[] DEFAULT NULL::integer[], p_regionids integer[] DEFAULT NULL::integer[], p_marketids integer[] DEFAULT NULL::integer[], p_countryids integer[] DEFAULT NULL::integer[], p_taskduestatus integer[] DEFAULT NULL::integer[], p_free_flow_label_id integer[] DEFAULT NULL::integer[], p_tool_id integer[] DEFAULT NULL::integer[]) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_date     date;
    v_to_date       date;
    v_days          int;
    v_group_type    text;
    v_period_days   int;
    ipo_id          int;
    v_completed_id  int;
    v_overdue_id    int;
    v_neardue_id    int;
    v_ontrack_id    int;
BEGIN

    /*
    Created_by  : Mubarak Basha
    Description : Calculates Orders/Tasks Focus dashboard KPIs using point-in-time
                  snapshot logic for Created, Active, Completed, and Overdue tasks
                  with period-over-period trend analysis and filtering.

                  FIX (this version): maintask completion previously used additive
                  daily SUM() windows for total/completed subtask counts, which
                  double/triple-counted a subtask every day it had any activity.
                  Replaced with an as-of-date forward-filled snapshot
                  (subtask_state_asof / maintask_daily_completion) so each subtask
                  is counted exactly once per activity_date, based on its latest
                  state on or before that date.

	Request:
		SELECT tickets.orders_focus_detailed_view_filters(
		'2026-07-13',
		'2026-07-07',
		44,
		'3a3d7038-e4eb-4cd7-977d-a5d38e4e18e1',
		Array[49],
		'subtask',
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		Array[76]
	)
    */
    -- ── STATUS CODES ──────────────────────────────────────────────────────────────
    SELECT
        MAX(CASE WHEN name = 'IPO'       AND type = 'ORDERLABEL'    THEN status_id END),
        MAX(CASE WHEN name = 'Completed' AND type = 'TASKDUESTATUS' THEN status_id END),
        MAX(CASE WHEN name = 'Overdue'   AND type = 'TASKDUESTATUS' THEN status_id END),
        MAX(CASE WHEN name = 'Near due'  AND type = 'TASKDUESTATUS' THEN status_id END),
        MAX(CASE WHEN name = 'On-track'  AND type = 'TASKDUESTATUS' THEN status_id END)
    INTO ipo_id, v_completed_id, v_overdue_id, v_neardue_id, v_ontrack_id
    FROM master.status_code_master
    WHERE is_active = TRUE
	AND type IN ('ORDERLABEL', 'TASKDUESTATUS'); 

    -- ── DATE NORMALISATION ────────────────────────────────────────────────────────
    v_from_date   := LEAST   (p_from_date, p_to_date);
    v_to_date     := GREATEST(p_from_date, p_to_date);
    v_days        := (v_to_date - v_from_date) + 1;
    v_period_days := v_days;

    IF    v_days <= 30 THEN v_group_type := 'day';
    ELSIF v_days <= 90 THEN v_group_type := 'week';
    ELSE                    v_group_type := 'month';
    END IF;

    RETURN QUERY
    WITH

    -- ── DATE BUCKETS ──────────────────────────────────────────────────────────────
    date_series AS (
        SELECT generate_series(
            date_trunc(v_group_type, v_from_date),
            date_trunc(v_group_type, v_to_date),
            CASE v_group_type
                WHEN 'day'  THEN INTERVAL '1 day'
                WHEN 'week' THEN INTERVAL '1 week'
                ELSE             INTERVAL '1 month'
            END
        )::date AS bucket_start
    ),
    bucket_range AS (
        SELECT
            bucket_start,
            CASE v_group_type
                WHEN 'day'  THEN bucket_start
                WHEN 'week' THEN (bucket_start + INTERVAL '6 days')::date
                ELSE             (date_trunc('month', bucket_start) + INTERVAL '1 month - 1 day')::date
            END AS bucket_end
        FROM date_series
    ),

    -- ── FINAL STAGE per board ─────────────────────────────────────────────────────
    final_stage AS MATERIALIZED (
        SELECT DISTINCT ON (b."BoardID")
            b."BoardID",
            bs."LabelID" AS last_label_id
        FROM  board.board       b
        JOIN  board.boardstatus bs ON bs."BoardID" = b."BoardID" AND bs.is_active = TRUE
        WHERE b.is_active = TRUE
        ORDER BY b."BoardID", bs."Position" DESC
    ),

    -- ── BOARDS IN SCOPE ───────────────────────────────────────────────────────────
    scoped_boards AS MATERIALIZED (
        SELECT b."BoardID"
        FROM   board.board b
        WHERE  b.is_active     = TRUE
          AND  b.work_space_id = ANY(p_workspaceids)
          AND  (p_boardids IS NULL OR array_length(p_boardids,1) IS NULL
                OR b."BoardID" = ANY(p_boardids))
    ),

    -- ── LATEST LOG STATE PER (tool_ticket_id, board_id) ──────────────────────────
  latest_log AS MATERIALIZED (
	    SELECT DISTINCT ON (tbl.tool_ticket_id, tbl.board_id)
	        tbl.tool_ticket_id,
	        tbl.ticket_id,
	        tbl.board_id,
	        tbl.label_id,
	        td.free_flow_label_id,
			td.tool_id,
	        tbl.tool_board_logid,
	        tbl.created_date::date AS created_date
	    FROM tickets.tool_board_log tbl
	    JOIN tickets.tool_detail td
	      ON td.tool_ticket_id = tbl.tool_ticket_id
	     AND td.is_active = TRUE
	    WHERE tbl.is_active = TRUE
	      AND tbl.is_moved = FALSE
	      AND tbl.board_id IN (SELECT "BoardID" FROM scoped_boards)
	
	    ORDER BY tbl.tool_ticket_id, tbl.board_id, tbl.sequence DESC
    ),

    -- ── CREATED DATE per task ─────────────────────────────────────────────────────
    task_created_date AS MATERIALIZED (
        SELECT
            CASE lower(p_tasktype)
                WHEN 'subtask'  THEN tbl.tool_ticket_id
                WHEN 'maintask' THEN tbl.ticket_id
            END AS task_id,
            MIN(tbl.created_date::date) AS created_date
        FROM  tickets.tool_board_log tbl
        WHERE tbl.is_active = TRUE
          AND tbl.is_moved  = FALSE
          AND tbl.sequence  = 1
          AND tbl.board_id IN (SELECT "BoardID" FROM scoped_boards)
        GROUP BY 1
    ),
	
	-- ── BASE  ─────────────────────────────────────────────────────
		base_data AS (
		    SELECT
		        CASE lower(p_tasktype)
		            WHEN 'subtask'  THEN ll.tool_ticket_id
		            WHEN 'maintask' THEN ll.ticket_id
		        END AS task_id,
		        ll.ticket_id,
		        ll.board_id,
		        ll.label_id,
		        fs.last_label_id,
				ll.free_flow_label_id,
				ll.tool_id,
		        t.order_type,
		      --  ta.assignee_to,
			  CASE lower(p_tasktype)
    WHEN 'maintask' THEN COALESCE(oba.ob_assignee_to, ARRAY[]::uuid[])
    ELSE CASE WHEN ta.assignee_to IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[ta.assignee_to] END
END AS assignee_to,

		        tc.region_id,
		        tc.country_id,
		        t.primary_market,
		        dd.due_date::date AS due_date,
		       COALESCE(
					    CASE
					        WHEN tc.is_ipo
					            THEN t.order_label_id || ARRAY[ipo_id]
					        ELSE
					            t.order_label_id
					    END,
					    ARRAY[]::integer[]
					)
					||
					CASE
					    WHEN lower(p_tasktype) = 'subtask'
					        THEN COALESCE(td.priority_id, ARRAY[]::integer[])
					    ELSE
					        COALESCE(t.priority_id, ARRAY[]::integer[])
					END AS order_label
		    FROM latest_log ll
		    JOIN tickets.ticket t
		      ON t.ticket_id = ll.ticket_id
		     AND t.is_active = TRUE
			LEFT JOIN tickets.tool_detail td
			    ON td.tool_ticket_id = ll.tool_ticket_id
			   AND td.is_active = TRUE

			   LEFT JOIN (
    SELECT mta.ticket_id, ARRAY_AGG(DISTINCT mta.assignee_to) AS ob_assignee_to
    FROM tickets.ticket_assignee mta
    WHERE mta.assignee_type = 'OB' AND mta.is_active = TRUE
    GROUP BY mta.ticket_id
) oba ON oba.ticket_id = t.ticket_id

			   
		    LEFT JOIN LATERAL (
		        SELECT *
		        FROM tickets.ticket_company tc
		        WHERE tc.ticket_id = t.ticket_id
		          AND tc.is_active
		        ORDER BY ticket_company_id DESC
		        LIMIT 1
		    ) tc ON TRUE
		    JOIN final_stage fs
		      ON fs."BoardID" = ll.board_id
		    LEFT JOIN LATERAL (
		        SELECT ta2.assignee_to
		        FROM tickets.tool_assignee ta2
		        WHERE ta2.tool_board_logid = ll.tool_board_logid
		          AND ta2.is_active = TRUE
		          AND COALESCE(ta2.un_assigned_flag, FALSE) = FALSE
		        ORDER BY ta2.sequence DESC
		        LIMIT 1
		    ) ta ON TRUE
		    LEFT JOIN LATERAL (
		        SELECT tdl.due_date
		        FROM tickets.tool_duedate_log tdl
		        WHERE tdl.tool_ticket_id = ll.tool_ticket_id
		          AND tdl.is_active = TRUE
		        ORDER BY tdl.created_date DESC,
		                 tdl.tool_duedate_log_id DESC
		        LIMIT 1
		    ) dd ON TRUE
		),
    -- ── FILTERS ───────────────────────────────────────────────────────────────────
    filtered_tasks AS MATERIALIZED (
        SELECT DISTINCT task_id
        FROM   base_data
        WHERE
            (p_ordertype IS NULL       OR array_length(p_ordertype,1)       IS NULL OR COALESCE(order_type   && p_ordertype,       FALSE))
        AND (p_order_labels IS NULL    OR array_length(p_order_labels,1)    IS NULL OR COALESCE(order_label   && p_order_labels,    FALSE))
		AND (p_assignee IS NULL OR array_length(p_assignee,1) IS NULL OR COALESCE(assignee_to && p_assignee, FALSE))
       -- AND (p_assignee IS NULL        OR array_length(p_assignee,1)        IS NULL OR assignee_to = ANY(p_assignee))
        AND (p_order_stage_list IS NULL OR array_length(p_order_stage_list,1) IS NULL OR label_id = ANY(p_order_stage_list))
		AND (p_free_flow_label_id IS NULL OR array_length(p_free_flow_label_id, 1) IS NULL OR COALESCE(free_flow_label_id && p_free_flow_label_id, FALSE))
		AND (
			    p_tool_id IS NULL
			    OR array_length(p_tool_id, 1) IS NULL
			    OR tool_id = ANY(p_tool_id)
			)
        AND (p_regionids IS NULL       OR array_length(p_regionids,1)       IS NULL OR COALESCE(region_id    && p_regionids,       FALSE))
        AND (p_countryids IS NULL      OR array_length(p_countryids,1)      IS NULL OR COALESCE(country_id   && p_countryids,      FALSE))
        AND (p_marketids IS NULL       OR array_length(p_marketids,1)       IS NULL OR COALESCE(primary_market && p_marketids,     FALSE))
        AND (p_taskduestatus IS NULL   OR array_length(p_taskduestatus,1) IS NULL
		        OR (
		        (
		            v_completed_id = ANY(p_taskduestatus)
		            AND label_id = last_label_id
		        )
		        OR
		        (
		            v_overdue_id = ANY(p_taskduestatus)
		            AND label_id <> last_label_id
		            AND due_date IS NOT NULL
		            AND due_date < CURRENT_DATE
		        )
		        OR
		        (
		            v_neardue_id = ANY(p_taskduestatus)
		            AND label_id <> last_label_id
		            AND due_date IS NOT NULL
		            AND due_date >= CURRENT_DATE
		            AND due_date <= CURRENT_DATE + INTERVAL '5 days'
		        )
		        OR
		        (
		            v_ontrack_id = ANY(p_taskduestatus)
		            AND label_id <> last_label_id
		            AND due_date IS NOT NULL
		            AND due_date > CURRENT_DATE + INTERVAL '5 days'
		        )
                   )
			)
       ),

	 tasks_in_scope AS MATERIALIZED (
		    SELECT
		        ft.task_id,
		        tcd.created_date,
		        bd.due_date
		    FROM filtered_tasks ft
		    JOIN task_created_date tcd
		      ON tcd.task_id = ft.task_id
		    JOIN base_data bd
		      ON bd.task_id = ft.task_id
		),
    -- ── TASK DAILY STATE — window function replaces correlated subquery ────────────
    raw_log_window AS MATERIALIZED (
        SELECT
            CASE lower(p_tasktype)
                WHEN 'subtask'  THEN tbl.tool_ticket_id
                WHEN 'maintask' THEN tbl.ticket_id
            END                          AS task_id,
            tbl.tool_ticket_id,
            tbl.board_id,
            tbl.created_date::date       AS activity_date,
            tbl.label_id,
            tbl.sequence,
            fs.last_label_id,
            MAX(tbl.sequence) OVER (
                PARTITION BY tbl.tool_ticket_id,
                             tbl.board_id,
                             tbl.created_date::date
            )                            AS max_seq_on_date
        FROM  tickets.tool_board_log tbl
        JOIN  final_stage fs ON fs."BoardID" = tbl.board_id
        WHERE tbl.is_active = TRUE
          AND tbl.is_moved  = FALSE
          AND tbl.board_id IN (SELECT "BoardID" FROM scoped_boards)
          AND (
              (lower(p_tasktype) = 'subtask'  AND tbl.tool_ticket_id IN (SELECT task_id FROM tasks_in_scope))
           OR (lower(p_tasktype) = 'maintask' AND tbl.ticket_id      IN (SELECT task_id FROM tasks_in_scope))
          )
    ),

    task_daily_state AS (
        SELECT
            task_id,
            tool_ticket_id,
            board_id,
            activity_date,
            last_label_id,
            -- highest-sequence label for this (subtask, board, date)
            (array_agg(label_id ORDER BY sequence DESC))[1]         AS eod_label,
            -- intraday reopen: a non-final label existed before the last sequence
            BOOL_OR(
                label_id <> last_label_id
                AND sequence < max_seq_on_date
            )                                                        AS had_intraday_reopen
        FROM  raw_log_window
        GROUP BY task_id, tool_ticket_id, board_id, activity_date, last_label_id, max_seq_on_date
    ),

    -- ── MAINTASK SUBTASK COMPLETION — as-of-date forward-filled snapshot ──────────
    -- Replaces the old additive SUM()-window approach, which double/triple-counted
    -- a subtask on every day it had activity instead of counting it once.
    maintask_subtask_log AS MATERIALIZED (
        SELECT
            tbl.ticket_id           AS task_id,
            tbl.tool_ticket_id,
            tbl.board_id,
            tbl.created_date::date  AS event_date,
            tbl.sequence,
            tbl.label_id,
            fs.last_label_id
        FROM  tickets.tool_board_log tbl
        JOIN  final_stage fs ON fs."BoardID" = tbl.board_id
        WHERE tbl.is_active = TRUE
          AND tbl.is_moved  = FALSE
          AND tbl.board_id IN (SELECT "BoardID" FROM scoped_boards)
          AND tbl.ticket_id IN (SELECT task_id FROM tasks_in_scope WHERE lower(p_tasktype) = 'maintask')
    ),

    maintask_dates AS MATERIALIZED (
        SELECT DISTINCT task_id, event_date AS activity_date
        FROM   maintask_subtask_log
    ),

    -- Forward-filled state of every subtask, evaluated as of each maintask activity_date
    subtask_state_asof AS (
        SELECT
            md.task_id,
            md.activity_date,
            msl.tool_ticket_id,
            msl.board_id,
            msl.label_id,
            msl.last_label_id,
            ROW_NUMBER() OVER (
                PARTITION BY md.task_id, md.activity_date, msl.tool_ticket_id, msl.board_id
                ORDER BY msl.event_date DESC, msl.sequence DESC
            ) AS rn
        FROM maintask_dates md
        JOIN maintask_subtask_log msl
          ON  msl.task_id    = md.task_id
         AND  msl.event_date <= md.activity_date
    ),


		subtask_completion_asof AS (
		    SELECT
		        task_id,
		        activity_date,
		        tool_ticket_id,
		        BOOL_AND(label_id = last_label_id) AS subtask_fully_completed
		    FROM subtask_state_asof
		    WHERE rn = 1
		    GROUP BY task_id, activity_date, tool_ticket_id
		),
		
		maintask_daily_completion AS MATERIALIZED (
		    SELECT
		        task_id,
		        activity_date,
		        COUNT(DISTINCT tool_ticket_id)                                       AS total_subtasks_asof,
		        COUNT(DISTINCT tool_ticket_id) FILTER (WHERE subtask_fully_completed) AS completed_subtasks_asof
		    FROM subtask_completion_asof
		    GROUP BY task_id, activity_date
		),

    -- ── TASK DAILY COMPLETION ─────────────────────────────────────────────────────
    task_daily_completion AS (
        SELECT
            tds.task_id,
            tds.activity_date,
            CASE lower(p_tasktype)
                WHEN 'maintask' THEN (
                    COALESCE(mdc.total_subtasks_asof, 0) > 0
                    AND mdc.total_subtasks_asof = mdc.completed_subtasks_asof
                )
                ELSE BOOL_AND(tds.eod_label = tds.last_label_id)
            END AS all_boards_eod_completed,
            BOOL_OR(tds.had_intraday_reopen) AS any_intraday_reopen
        FROM  task_daily_state tds
        LEFT  JOIN maintask_daily_completion mdc
               ON  mdc.task_id       = tds.task_id
               AND mdc.activity_date = tds.activity_date
        GROUP BY
            tds.task_id,
            tds.activity_date,
            mdc.total_subtasks_asof,
            mdc.completed_subtasks_asof
    ),

    task_daily_with_prev AS (
        SELECT
            tdc.task_id,
            tdc.activity_date,
            tdc.all_boards_eod_completed,
            tdc.any_intraday_reopen,
            LAG(tdc.all_boards_eod_completed, 1, FALSE)
                OVER (PARTITION BY tdc.task_id ORDER BY tdc.activity_date)
                AS prev_day_completed
        FROM task_daily_completion tdc
    ),

    task_completion_date AS MATERIALIZED (
        SELECT task_id, activity_date AS completed_date
        FROM   task_daily_with_prev
        WHERE  all_boards_eod_completed = TRUE
          AND (prev_day_completed = FALSE OR any_intraday_reopen = TRUE)
    ),

    -- ── COMPLETION SNAPSHOT — pre-scan replaces per-task lateral ─────────────────
    snapshot_dates AS (
        SELECT bucket_end                         AS ref_date FROM bucket_range
        UNION
        SELECT (bucket_end - v_period_days)::date AS ref_date FROM bucket_range
    ),

    -- Latest log row per (subtask, board) as of each snapshot ref_date
    snap_latest AS MATERIALIZED (
        SELECT DISTINCT ON (sd.ref_date, tbl.tool_ticket_id, tbl.board_id)
            sd.ref_date,
            CASE lower(p_tasktype)
                WHEN 'subtask'  THEN tbl.tool_ticket_id
                WHEN 'maintask' THEN tbl.ticket_id
            END AS task_id,
            tbl.tool_ticket_id,
            tbl.board_id,
            tbl.label_id
        FROM  snapshot_dates sd
        JOIN  tickets.tool_board_log tbl
              ON  tbl.created_date::date <= sd.ref_date
              AND tbl.is_active           = TRUE
              AND tbl.is_moved            = FALSE
              AND tbl.board_id           IN (SELECT "BoardID" FROM scoped_boards)
              AND (
                  (lower(p_tasktype) = 'subtask'  AND tbl.tool_ticket_id IN (SELECT task_id FROM tasks_in_scope))
               OR (lower(p_tasktype) = 'maintask' AND tbl.ticket_id      IN (SELECT task_id FROM tasks_in_scope))
              )
        ORDER BY sd.ref_date, tbl.tool_ticket_id, tbl.board_id, tbl.sequence DESC
    ),

    completion_snapshot AS MATERIALIZED (
        SELECT
            sl.ref_date,
            sl.task_id,
            BOOL_AND(sl.label_id = fs.last_label_id) AS is_completed
        FROM   snap_latest sl
        JOIN   final_stage fs ON fs."BoardID" = sl.board_id
        GROUP  BY sl.ref_date, sl.task_id
    ),

    -- ── EFFECTIVE DUE DATE — ranked CTE replaces correlated subquery ──────────────
    due_date_ranked AS MATERIALIZED (
        SELECT
            sd.ref_date,
            CASE lower(p_tasktype)
                WHEN 'subtask'  THEN tdl.tool_ticket_id
                WHEN 'maintask' THEN NULL  -- not used for maintask
            END AS task_id,
            tdl.due_date::date AS due_date,
            ROW_NUMBER() OVER (
                PARTITION BY sd.ref_date, tdl.tool_ticket_id
                ORDER BY tdl.created_date DESC, tdl.sequence DESC
            ) AS rn
        FROM  snapshot_dates sd
        JOIN  tickets.tool_duedate_log tdl
              ON  tdl.created_date::date <= sd.ref_date
              AND tdl.is_active           = TRUE
              AND tdl.tool_ticket_id     IN (SELECT task_id FROM tasks_in_scope)
        WHERE lower(p_tasktype) = 'subtask'
    ),

    task_bucket_due_date AS (
        SELECT ref_date, task_id, due_date AS effective_due_date
        FROM   due_date_ranked
        WHERE  rn = 1
    ),

    -- ── MAIN METRIC CALCULATION ───────────────────────────────────────────────────
    compare_calc AS (
        SELECT
            br.bucket_start,
            br.bucket_end,

            -- CREATED
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date BETWEEN br.bucket_start AND br.bucket_end
                  AND tis.created_date BETWEEN v_from_date AND v_to_date
            ) AS cur_created,

            -- ACTIVE (not completed as of bucket_end)
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date <= br.bucket_end
                  AND COALESCE(cs.is_completed, FALSE) = FALSE
            ) AS cur_active,

            -- COMPLETED (event falls in bucket)
            COUNT(DISTINCT tcd.task_id) FILTER (
                WHERE tcd.completed_date BETWEEN br.bucket_start AND br.bucket_end
                  AND tcd.completed_date BETWEEN v_from_date AND v_to_date
            ) AS cur_completed,

            -- OVERDUE (subtask only: active + past due)
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE lower(p_tasktype) = 'subtask'
                  AND tis.created_date <= br.bucket_end
                  AND COALESCE(cs.is_completed, FALSE) = FALSE
                  AND tbd.effective_due_date IS NOT NULL
                  AND tbd.effective_due_date < br.bucket_end
            ) AS cur_overdue,

            -- PERCENTAGE WINDOW — current period
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date BETWEEN (br.bucket_end - (v_period_days - 1)) AND br.bucket_end
            ) AS pct_cur_created,
            COUNT(DISTINCT tcd.task_id) FILTER (
                WHERE tcd.completed_date BETWEEN (br.bucket_end - (v_period_days - 1)) AND br.bucket_end
            ) AS pct_cur_completed,
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date <= br.bucket_end
                  AND COALESCE(cs.is_completed, FALSE) = FALSE
            ) AS pct_cur_active,
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE lower(p_tasktype) = 'subtask'
                  AND tis.created_date <= br.bucket_end
                  AND COALESCE(cs.is_completed, FALSE) = FALSE
                  AND tbd.effective_due_date IS NOT NULL
                  AND tbd.effective_due_date < br.bucket_end
            ) AS pct_cur_overdue,

            -- PERCENTAGE WINDOW — prior period
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date BETWEEN
                    (br.bucket_end - (v_period_days * 2 - 1)) AND (br.bucket_end - v_period_days)
            ) AS pct_cmp_created,
            COUNT(DISTINCT tcd.task_id) FILTER (
                WHERE tcd.completed_date BETWEEN
                    (br.bucket_end - (v_period_days * 2 - 1)) AND (br.bucket_end - v_period_days)
            ) AS pct_cmp_completed,
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE tis.created_date <= (br.bucket_end - v_period_days)
                  AND COALESCE(cs_prev.is_completed, FALSE) = FALSE
            ) AS pct_cmp_active,
            COUNT(DISTINCT tis.task_id) FILTER (
                WHERE lower(p_tasktype) = 'subtask'
                  AND tis.created_date <= (br.bucket_end - v_period_days)
                  AND COALESCE(cs_prev.is_completed, FALSE) = FALSE
                  AND tbd_prev.effective_due_date IS NOT NULL
                  AND tbd_prev.effective_due_date < (br.bucket_end - v_period_days)
            ) AS pct_cmp_overdue

        FROM   bucket_range br
        CROSS  JOIN tasks_in_scope tis

        LEFT   JOIN completion_snapshot cs
                 ON cs.task_id  = tis.task_id
                AND cs.ref_date = br.bucket_end
        LEFT   JOIN completion_snapshot cs_prev
                 ON cs_prev.task_id  = tis.task_id
                AND cs_prev.ref_date = (br.bucket_end - v_period_days)::date
        LEFT   JOIN task_completion_date tcd
                 ON tcd.task_id = tis.task_id
        LEFT   JOIN task_bucket_due_date tbd
                 ON tbd.task_id  = tis.task_id
                AND tbd.ref_date = br.bucket_end
        LEFT   JOIN task_bucket_due_date tbd_prev
                 ON tbd_prev.task_id  = tis.task_id
                AND tbd_prev.ref_date = (br.bucket_end - v_period_days)::date
        GROUP  BY br.bucket_start, br.bucket_end
    ),

    -- ── TREND CALCULATION ─────────────────────────────────────────────────────────
    final_metrics AS (
        SELECT
            cc.bucket_start,
            cc.bucket_end,
            cc.cur_created   AS created_tasks,
            cc.cur_active    AS active_tasks,
            cc.cur_completed AS completed_tasks,
            cc.cur_overdue   AS overdue_tasks,

            CASE WHEN cc.pct_cmp_created   = 0 THEN 0
                 ELSE ABS(ROUND((cc.pct_cur_created  - cc.pct_cmp_created)::numeric  / cc.pct_cmp_created  * 100, 2))
            END AS created_pct,
            CASE WHEN cc.pct_cur_created   = cc.pct_cmp_created   THEN 'Ideal'
                 WHEN cc.pct_cur_created   > cc.pct_cmp_created   THEN 'Increase'
                 ELSE 'Decrease' END AS created_trend,

            CASE WHEN cc.pct_cmp_active    = 0 THEN 0
                 ELSE ABS(ROUND((cc.pct_cur_active   - cc.pct_cmp_active)::numeric   / cc.pct_cmp_active   * 100, 2))
            END AS active_pct,
            CASE WHEN cc.pct_cur_active    = cc.pct_cmp_active    THEN 'Ideal'
                 WHEN cc.pct_cur_active    > cc.pct_cmp_active    THEN 'Increase'
                 ELSE 'Decrease' END AS active_trend,

            CASE WHEN cc.pct_cmp_completed = 0 THEN 0
                 ELSE ABS(ROUND((cc.pct_cur_completed - cc.pct_cmp_completed)::numeric / cc.pct_cmp_completed * 100, 2))
            END AS completed_pct,
            CASE WHEN cc.pct_cur_completed = cc.pct_cmp_completed THEN 'Ideal'
                 WHEN cc.pct_cur_completed > cc.pct_cmp_completed THEN 'Increase'
                 ELSE 'Decrease' END AS completed_trend,

            CASE WHEN cc.pct_cmp_overdue   = 0 THEN 0
                 ELSE ABS(ROUND((cc.pct_cur_overdue  - cc.pct_cmp_overdue)::numeric  / cc.pct_cmp_overdue  * 100, 2))
            END AS overdue_pct,
            CASE WHEN cc.pct_cur_overdue   = cc.pct_cmp_overdue   THEN 'Ideal'
                 WHEN cc.pct_cur_overdue   > cc.pct_cmp_overdue   THEN 'Increase'
                 ELSE 'Decrease' END AS overdue_trend
        FROM compare_calc cc
    )

    -- ── FINAL JSON OUTPUT ─────────────────────────────────────────────────────────
    SELECT jsonb_build_object(
        'velocity', jsonb_agg(
            jsonb_build_object(
                'key',            TO_CHAR(bucket_start, 'Mon DD'),
                'dateFrom',       bucket_start,
                'dateTo',         bucket_end,
                'createdTasks',   jsonb_build_object('count', created_tasks,   'percentage', COALESCE(created_pct,   0), 'trend', created_trend),
                'activeTasks',    jsonb_build_object('count', active_tasks,    'percentage', COALESCE(active_pct,    0), 'trend', active_trend),
                'completedTasks', jsonb_build_object('count', completed_tasks, 'percentage', COALESCE(completed_pct, 0), 'trend', completed_trend),
                'overdueTasks', CASE
                    WHEN lower(p_tasktype) = 'subtask'
                    THEN jsonb_build_object('count', overdue_tasks, 'percentage', COALESCE(overdue_pct, 0), 'trend', overdue_trend)
                    ELSE NULL
                END
            )
            ORDER BY bucket_start
        ),
        'status',  TRUE,
        'message', 'Counts and Percentage Fetched Successfully'
    )
    FROM final_metrics;

END;
$$;


--
-- Name: reorder_tool_detail(integer, integer, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.reorder_tool_detail(IN p_ticket_id integer, IN p_tool_ticket_id integer, IN p_direction text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_current_pos integer;
	v_swap_id integer;
	v_swap_pos integer;
	v_exists boolean := false;
	v_direction text := LOWER(TRIM(COALESCE(p_direction, '')));
	v_context text;
BEGIN
	IF p_ticket_id IS NULL OR p_ticket_id <= 0 OR p_tool_ticket_id IS NULL OR p_tool_ticket_id <= 0 THEN
		status := 'false';
		message := 'ticketId and toolTicketId are required.';
		RETURN;
	END IF;

	IF v_direction NOT IN ('up', 'down') THEN
		status := 'false';
		message := 'direction must be up or down.';
		RETURN;
	END IF;

	-- Match Orderticketdetails: tools for a ticket are returned even when is_active = false
	SELECT EXISTS (
		SELECT 1
		FROM tickets.tool_detail
		WHERE tool_ticket_id = p_tool_ticket_id
		  AND ticket_id = p_ticket_id
	) INTO v_exists;

	IF NOT v_exists THEN
		status := 'false';
		message := 'Tool / subtask not found.';
		RETURN;
	END IF;

	-- Normalize positions for this ticket (active + inactive, same as detail response)
	WITH ranked AS (
		SELECT
			tool_ticket_id,
			ROW_NUMBER() OVER (ORDER BY COALESCE(position, tool_ticket_id), tool_ticket_id) AS rn
		FROM tickets.tool_detail
		WHERE ticket_id = p_ticket_id
	)
	UPDATE tickets.tool_detail td
	SET position = ranked.rn,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	FROM ranked
	WHERE td.tool_ticket_id = ranked.tool_ticket_id
	  AND td.position IS DISTINCT FROM ranked.rn;

	SELECT position
	INTO v_current_pos
	FROM tickets.tool_detail
	WHERE tool_ticket_id = p_tool_ticket_id
	  AND ticket_id = p_ticket_id;

	IF v_direction = 'up' THEN
		SELECT tool_ticket_id, position
		INTO v_swap_id, v_swap_pos
		FROM tickets.tool_detail
		WHERE ticket_id = p_ticket_id
		  AND position < v_current_pos
		ORDER BY position DESC
		LIMIT 1;
	ELSE
		SELECT tool_ticket_id, position
		INTO v_swap_id, v_swap_pos
		FROM tickets.tool_detail
		WHERE ticket_id = p_ticket_id
		  AND position > v_current_pos
		ORDER BY position ASC
		LIMIT 1;
	END IF;

	IF v_swap_id IS NULL THEN
		status := 'true';
		message := CASE WHEN v_direction = 'up'
			THEN 'Already at the top.'
			ELSE 'Already at the bottom.'
		END;
		RETURN;
	END IF;

	UPDATE tickets.tool_detail
	SET position = v_swap_pos,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	WHERE tool_ticket_id = p_tool_ticket_id;

	UPDATE tickets.tool_detail
	SET position = v_current_pos,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	WHERE tool_ticket_id = v_swap_id;

	status := 'true';
	message := 'Tool / subtask position updated successfully.';

EXCEPTION
	WHEN OTHERS THEN
		GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
		CALL master.procedure_log_exception(
			'tickets.reorder_tool_detail',
			CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
			NULL,
			current_timestamp AT TIME ZONE 'UTC',
			row_to_json(ROW(p_ticket_id, p_tool_ticket_id, p_direction, p_added_by))::TEXT
		);
		status := 'false';
		message := SQLERRM;
END;
$$;


--
-- Name: set_process_order(integer, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.set_process_order(IN p_ticket_id integer DEFAULT 0, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.set_process_order
Developer   : Aravindhan.B
Created On  : 03-09-2025
Purpose     : Proceed to order 

Change Log  :
-------------------------------------------------------------------------------
Date        Developer        		Change Description
----------- ----------------------- -------------------------------------------
03-09-2025  Aravindhan.B     		Initial creation
*******************************************************************************/
DECLARE
    v_context text;
	v_order_status_id       INTEGER := 0;
	v_obm_boardid       	INTEGER := 0;
	v_obm_labelid       	INTEGER := 0;
	v_ob_boardid       		INTEGER := 0;
	v_ob_labelid       		INTEGER := 0;
	v_new_logid       		INTEGER := 0;
    tool_log          		RECORD;
	v_company_name			TEXT 	:= NULL;
	v_tool_list				TEXT 	:= NULL;
	v_board_name			TEXT 	:= NULL;
	v_label_name			TEXT 	:= NULL;
	v_subject				TEXT	:= NULL;
	v_recipient_email		TEXT 	:= NULL;
	v_recipient_push		TEXT 	:= NULL;
	v_email 				TEXT 	:= NULL;
	v_reg	 				TEXT 	:= NULL;
	v_message				TEXT 	:= NULL;
	v_work_space_id			INTEGER := 0;
	v_tool_ticket_ids 		INTEGER[];
	v_refresh 				JSONB;
BEGIN

	IF NOT EXISTS (SELECT 1 FROM tickets.ticket WHERE ticket_id = p_ticket_id AND is_active = TRUE) THEN
        message := 'In-active ticket.';
        status := 'false';
        RETURN;
    END IF;
	
	
    -- Get order status
    SELECT status_id INTO v_order_status_id
    FROM master.status_code_master 
    WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND code = 'OP';

    -- Get ON BOARDING MAIN BOARD VIEW
    SELECT "BoardID" INTO v_obm_boardid 
    FROM board.board 
    WHERE code = 'OBM' AND is_active = TRUE;

    SELECT "LabelID" INTO v_obm_labelid 
    FROM board.boardstatus 
    WHERE "BoardID" = v_obm_boardid AND UPPER("Code") = 'OPEN' AND is_active = TRUE;

    -- Get ON BOARDING board
    SELECT "BoardID" INTO v_ob_boardid 
    FROM board.board 
    WHERE code = 'OB' AND is_active = TRUE;

    SELECT "LabelID" INTO v_ob_labelid 
    FROM board.boardstatus 
    WHERE "BoardID" = v_ob_boardid AND UPPER("Code") = 'OPEN' AND is_active = TRUE;
	

    --UPDATE ticket table
	UPDATE tickets.ticket SET 
		status_id = v_order_status_id,
		is_process_order = true,
		process_date = current_timestamp AT TIME ZONE 'UTC',
		last_updated_date = current_timestamp AT TIME ZONE 'UTC',
		updated_by = p_added_by
	WHERE ticket_id = p_ticket_id AND is_active = true;
	
   -- -- ✅ Capture history for main ticket update
   --  CALL tickets.add_or_update_history_details(
   --      in_order_id       := p_ticket_id,
   --      in_content        := CONCAT('Moved the ticket to ', v_obm_boardid, ' Label ', v_obm_labelid),
   --      in_user_id        := p_added_by,
   --      in_created_by     := p_added_by,
   --      in_created_date   := current_timestamp AT TIME ZONE 'UTC',
   --      in_history_type   := 'Ticket process order'
   --  );
	--Insert Board tracker
	INSERT INTO tickets.ticket_board_tracker (
		ticket_tracker_id,
		ticket_id,
		board_id,
		label_id,
		moved_date,
		created_date,
		created_by,
		is_active
	) VALUES (
		(SELECT COALESCE(MAX(ticket_tracker_id), 0) + 1 FROM tickets.ticket_board_tracker),
		p_ticket_id,
		v_obm_boardid,
		v_obm_labelid,
		current_timestamp AT TIME ZONE 'UTC',
		current_timestamp AT TIME ZONE 'UTC',
		p_added_by,
		TRUE
	);
	
	 INSERT INTO tickets.ticket_status_track (
		id,
		ticket_id,
		board_id,
		label_id,
		moved_by,
		activity_date,
		is_active,
		created_by,
		created_date
	) VALUES (
		(SELECT COALESCE(MAX(id), 0) + 1 FROM tickets.ticket_status_track),
		p_ticket_id,
		v_obm_boardid,
		v_obm_labelid,
		p_added_by,
		current_timestamp AT TIME ZONE 'UTC',
		'true',
		p_added_by,
		current_timestamp AT TIME ZONE 'UTC'
	);    
	
-- 	UPDATE tickets.tool_detail SET
-- 		board_id = v_ob_boardid,
-- 		label_id = v_ob_labelid,
--     	last_updated_date = current_timestamp AT TIME ZONE 'UTC',
-- 		updated_by = p_added_by
-- 	WHERE ticket_id = p_ticket_id AND is_active = true;

	-- add history details
	PERFORM tickets.add_or_update_history_details(
					in_order_id           => p_ticket_id,
					in_tool_ticket_id     => 0,
					in_content            => 'This ticket has been process ordered.',
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Ticket Movement'
				);
	
	 -- Get starting log id (MAX + 1)
    SELECT COALESCE(MAX(tool_board_logid),0) + 1
    INTO v_new_logid
    FROM tickets.tool_board_log;
	-- Loop over all tools for this ticket and insert logs
    FOR tool_log IN
        SELECT tool_ticket_id
        FROM tickets.tool_detail
        WHERE ticket_id = p_ticket_id AND is_active = TRUE
    LOOP
	
        INSERT INTO tickets.tool_board_log(
            tool_board_logid,
            ticket_id,
            tool_ticket_id,
			moved_by,
            board_id,
            label_id,
			moved_date,
			sequence,
			action_id,
            created_date,
            created_by,
            is_active
        )
        VALUES (
            v_new_logid,
            p_ticket_id,
            tool_log.tool_ticket_id,
			p_added_by,			
            v_ob_boardid,
            v_ob_labelid,
			current_timestamp AT TIME ZONE 'UTC',
			1,
			NULL,
            current_timestamp AT TIME ZONE 'UTC',
            p_added_by,
            TRUE
        );

        -- Increment log id for next insert
        v_new_logid := v_new_logid + 1;
		
    END LOOP;
	
	
	--Notification
	SELECT TRIM(name) INTO v_company_name 
	FROM tickets.ticket 
	WHERE ticket_id = p_ticket_id  AND is_active = true;
		
	SELECT "Name", work_space_id
	INTO v_board_name, v_work_space_id
    FROM board.board 
    WHERE "BoardID" = v_ob_boardid AND is_active = TRUE;
	
	SELECT "Name" INTO v_label_name 
    FROM board.boardstatus
    WHERE "BoardID" = v_ob_boardid AND "LabelID" = v_ob_labelid AND is_active = TRUE;
	
	SELECT STRING_AGG(t."ToolName", ', ') AS "ToolNames" INTO v_tool_list
	FROM tickets.tool_detail td
	JOIN master.tool t 
	  ON t."ToolID" = td.tool_id 
	  AND t.is_active = TRUE
	WHERE td.ticket_id = p_ticket_id 
	  AND td.is_active = TRUE;
	
	v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_tool_list, '') || '" , "boardName": "' || COALESCE(v_board_name, '') || '" , "stage": "' || COALESCE(v_label_name, '') || '"}}';		
	
	SELECT subject
	INTO v_subject
	FROM master.mailtemplate
	WHERE mailtemplatetype = 'NewCardArrived'
	  AND is_active = true
	LIMIT 1;		
	
	--Get Email address
	 SELECT 
		STRING_AGG(r."Email", ', ') AS recipient_email,
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_email, 
		v_recipient_push
	 FROM users.user_board_permission ubp
	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	 WHERE ubp.board_id = v_ob_boardid AND ubp.is_active = true;
	 	 

	-- Add Email Notification
	FOR v_email IN SELECT unnest(string_to_array(v_recipient_email , ',')) LOOP
		
		-- Trim spaces if any
		v_email := trim(v_email);

		-- Call the existing add_notification procedure for each recipient
		CALL notification.add_notification(
			p_type := 'Email',
			p_recipient := v_email,
			p_subject := v_subject,
			p_message := v_message,
			p_retry_count := 0,
			p_max_retries := 3,
			p_message_json := NULL,
			message := message,
			status := status
		);

	END LOOP;
		
	
	-- Add Push Notification
	FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
		
		-- Trim spaces if any
		v_reg := trim(v_reg);

		-- Call the existing add_notification procedure for each recipient
		CALL notification.add_notification(
			p_type := 'Push',
			p_recipient := v_reg,
			p_subject := 'New Card',
			p_message := 'A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
			p_retry_count := 0,
			p_max_retries := 3,
			p_message_json := '{
								"ticket_id": '|| p_ticket_id ||',
								"tool_id": 0,
								"tool_ticket_id": 0,
								"board_id": '|| v_ob_boardid ||',
								"moved_from": "'|| p_added_by ||'",
								"moved_to": "'|| v_reg ||'",
								"notify_message": "A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
								"is_read": false,
								"type": "moved the ticket",	
								"workspace_id": '|| v_work_space_id ||',
								"header": "New Card"
							   }'::text,
			message := message,
			status := status
		);

	END LOOP;
	
	--Kanban board auto refresh	
	
	SELECT ARRAY_AGG(tool_ticket_id) 
	INTO v_tool_ticket_ids 
	FROM tickets.tool_detail 
	WHERE ticket_id = p_ticket_id AND is_active = TRUE;
	
-- 	CALL tickets.main_sub_board_refresh(
-- 		v_tool_ticket_ids,
-- 		p_ticket_id,
-- 		v_ob_boardid,
-- 		0,
-- 		v_ob_labelid,
-- 		'ADD',
-- 		p_added_by,
-- 		message := message,
-- 		status := status
-- 	);
	
	 v_refresh := jsonb_build_object(
		'tool_ticket_id', v_tool_ticket_ids,
		'ticket_id', p_ticket_id,
		'board_id', v_ob_boardid,
		'from_label_id', 0,
		'to_label_id', v_ob_labelid,
		'type', 'ADD',
		'added_by', p_added_by
	);		

	autorefreshreq := (
		COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
	)::text;
				
    status := 'true';
    message := 'Order Processed to On-boarding.';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.set_process_order',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_added_by
            ))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: set_process_order_backup(integer, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.set_process_order_backup(IN p_ticket_id integer DEFAULT 0, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.set_process_order
Developer   : Aravindhan.B
Created On  : 03-09-2025
Purpose     : Proceed to order 

Change Log  :
-------------------------------------------------------------------------------
Date        Developer        		Change Description
----------- ----------------------- -------------------------------------------
03-09-2025  Aravindhan.B     		Initial creation
*******************************************************************************/
DECLARE
    v_context text;
	v_order_status_id       INTEGER := 0;
	v_obm_boardid       	INTEGER := 0;
	v_obm_labelid       	INTEGER := 0;
	v_ob_boardid       		INTEGER := 0;
	v_ob_labelid       		INTEGER := 0;
	v_new_logid       		INTEGER := 0;
    tool_log          		RECORD;
	v_company_name			TEXT 	:= NULL;
	v_tool_list				TEXT 	:= NULL;
	v_board_name			TEXT 	:= NULL;
	v_label_name			TEXT 	:= NULL;
	v_subject				TEXT	:= NULL;
	v_recipient_email		TEXT 	:= NULL;
	v_recipient_push		TEXT 	:= NULL;
	v_email 				TEXT 	:= NULL;
	v_reg	 				TEXT 	:= NULL;
	v_message				TEXT 	:= NULL;
	v_work_space_id			INTEGER := 0;
	v_tool_ticket_ids 		INTEGER[];
BEGIN

	IF NOT EXISTS (SELECT 1 FROM tickets.ticket WHERE ticket_id = p_ticket_id AND is_active = TRUE) THEN
        message := 'In-active ticket.';
        status := 'false';
        RETURN;
    END IF;
	
	
    -- Get order status
    SELECT status_id INTO v_order_status_id
    FROM master.status_code_master 
    WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND code = 'OP';

    -- Get ON BOARDING MAIN BOARD VIEW
    SELECT "BoardID" INTO v_obm_boardid 
    FROM board.board 
    WHERE code = 'OBM' AND is_active = TRUE;

    SELECT "LabelID" INTO v_obm_labelid 
    FROM board.boardstatus 
    WHERE "BoardID" = v_obm_boardid AND UPPER("Code") = 'OPEN' AND is_active = TRUE;

    -- Get ON BOARDING board
    SELECT "BoardID" INTO v_ob_boardid 
    FROM board.board 
    WHERE code = 'OB' AND is_active = TRUE;

    SELECT "LabelID" INTO v_ob_labelid 
    FROM board.boardstatus 
    WHERE "BoardID" = v_ob_boardid AND UPPER("Code") = 'OPEN' AND is_active = TRUE;
	

    --UPDATE ticket table
	UPDATE tickets.ticket SET 
		status_id = v_order_status_id,
		is_process_order = true,
		process_date = current_timestamp AT TIME ZONE 'UTC',
		last_updated_date = current_timestamp AT TIME ZONE 'UTC',
		updated_by = p_added_by
	WHERE ticket_id = p_ticket_id AND is_active = true;
	
   -- -- ✅ Capture history for main ticket update
   --  CALL tickets.add_or_update_history_details(
   --      in_order_id       := p_ticket_id,
   --      in_content        := CONCAT('Moved the ticket to ', v_obm_boardid, ' Label ', v_obm_labelid),
   --      in_user_id        := p_added_by,
   --      in_created_by     := p_added_by,
   --      in_created_date   := current_timestamp AT TIME ZONE 'UTC',
   --      in_history_type   := 'Ticket process order'
   --  );
	--Insert Board tracker
	INSERT INTO tickets.ticket_board_tracker (
		ticket_tracker_id,
		ticket_id,
		board_id,
		label_id,
		moved_date,
		created_date,
		created_by,
		is_active
	) VALUES (
		(SELECT COALESCE(MAX(ticket_tracker_id), 0) + 1 FROM tickets.ticket_board_tracker),
		p_ticket_id,
		v_obm_boardid,
		v_obm_labelid,
		current_timestamp AT TIME ZONE 'UTC',
		current_timestamp AT TIME ZONE 'UTC',
		p_added_by,
		TRUE
	);
	
	 INSERT INTO tickets.ticket_status_track (
		id,
		ticket_id,
		board_id,
		label_id,
		moved_by,
		activity_date,
		is_active,
		created_by,
		created_date
	) VALUES (
		(SELECT COALESCE(MAX(id), 0) + 1 FROM tickets.ticket_status_track),
		p_ticket_id,
		v_obm_boardid,
		v_obm_labelid,
		p_added_by,
		current_timestamp AT TIME ZONE 'UTC',
		'true',
		p_added_by,
		current_timestamp AT TIME ZONE 'UTC'
	);    
	
-- 	UPDATE tickets.tool_detail SET
-- 		board_id = v_ob_boardid,
-- 		label_id = v_ob_labelid,
--     	last_updated_date = current_timestamp AT TIME ZONE 'UTC',
-- 		updated_by = p_added_by
-- 	WHERE ticket_id = p_ticket_id AND is_active = true;

	-- add history details
	PERFORM tickets.add_or_update_history_details(
					in_order_id           => p_ticket_id,
					in_tool_ticket_id     => 0,
					in_content            => 'This ticket has been process ordered.',
					in_user_id            => p_added_by,
					in_created_by         => p_added_by,
					in_created_date       => current_timestamp AT TIME ZONE 'UTC',
					in_uploaded_file_name => NULL,
					in_history_type       => 'Ticket Movement'
				);
	
	 -- Get starting log id (MAX + 1)
    SELECT COALESCE(MAX(tool_board_logid),0) + 1
    INTO v_new_logid
    FROM tickets.tool_board_log;
	-- Loop over all tools for this ticket and insert logs
    FOR tool_log IN
        SELECT tool_ticket_id
        FROM tickets.tool_detail
        WHERE ticket_id = p_ticket_id AND is_active = TRUE
    LOOP
	
        INSERT INTO tickets.tool_board_log(
            tool_board_logid,
            ticket_id,
            tool_ticket_id,
			moved_by,
            board_id,
            label_id,
			moved_date,
			sequence,
			action_id,
            created_date,
            created_by,
            is_active
        )
        VALUES (
            v_new_logid,
            p_ticket_id,
            tool_log.tool_ticket_id,
			p_added_by,			
            v_ob_boardid,
            v_ob_labelid,
			current_timestamp AT TIME ZONE 'UTC',
			1,
			NULL,
            current_timestamp AT TIME ZONE 'UTC',
            p_added_by,
            TRUE
        );

        -- Increment log id for next insert
        v_new_logid := v_new_logid + 1;
		
    END LOOP;
	
	
	--Notification
	SELECT TRIM(name) INTO v_company_name 
	FROM tickets.ticket 
	WHERE ticket_id = p_ticket_id  AND is_active = true;
		
	SELECT "Name", work_space_id
	INTO v_board_name, v_work_space_id
    FROM board.board 
    WHERE "BoardID" = v_ob_boardid AND is_active = TRUE;
	
	SELECT "Name" INTO v_label_name 
    FROM board.boardstatus
    WHERE "BoardID" = v_ob_boardid AND "LabelID" = v_ob_labelid AND is_active = TRUE;
	
	SELECT STRING_AGG(t."ToolName", ', ') AS "ToolNames" INTO v_tool_list
	FROM tickets.tool_detail td
	JOIN master.tool t 
	  ON t."ToolID" = td.tool_id 
	  AND t.is_active = TRUE
	WHERE td.ticket_id = p_ticket_id 
	  AND td.is_active = TRUE;
	
	v_message := '{"TemplateKey": "NewCardArrived", "Payload": {"companyName": "' || COALESCE(v_company_name, '') || '", 
					"toolList": "' || COALESCE(v_tool_list, '') || '" , "boardName": "' || COALESCE(v_board_name, '') || '" , "stage": "' || COALESCE(v_label_name, '') || '"}}';		
	
	SELECT subject
	INTO v_subject
	FROM master.mailtemplate
	WHERE mailtemplatetype = 'NewCardArrived'
	  AND is_active = true
	LIMIT 1;		
	
	--Get Email address
	 SELECT 
		STRING_AGG(r."Email", ', ') AS recipient_email,
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_email, 
		v_recipient_push
	 FROM users.user_board_permission ubp
	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	 WHERE ubp.board_id = v_ob_boardid AND ubp.is_active = true;
	 	 

	-- Add Email Notification
	FOR v_email IN SELECT unnest(string_to_array(v_recipient_email , ',')) LOOP
		
		-- Trim spaces if any
		v_email := trim(v_email);

		-- Call the existing add_notification procedure for each recipient
		CALL notification.add_notification(
			p_type := 'Email',
			p_recipient := v_email,
			p_subject := v_subject,
			p_message := v_message,
			p_retry_count := 0,
			p_max_retries := 3,
			p_message_json := NULL,
			message := message,
			status := status
		);

	END LOOP;
		
	
	-- Add Push Notification
	FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
		
		-- Trim spaces if any
		v_reg := trim(v_reg);

		-- Call the existing add_notification procedure for each recipient
		CALL notification.add_notification(
			p_type := 'Push',
			p_recipient := v_reg,
			p_subject := 'New Card',
			p_message := 'A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.',
			p_retry_count := 0,
			p_max_retries := 3,
			p_message_json := '{
								"ticket_id": '|| p_ticket_id ||',
								"tool_id": 0,
								"tool_ticket_id": 0,
								"board_id": '|| v_ob_boardid ||',
								"moved_from": "'|| p_added_by ||'",
								"moved_to": "'|| v_reg ||'",
								"notify_message": "A new card has arrived in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_company_name, '') || '</b>.",	
								"is_read": false,
								"type": "moved the ticket",	
								"workspace_id": '|| v_work_space_id ||',
								"header": "New Card"
							   }'::text,
			message := message,
			status := status
		);

	END LOOP;
	
	--Kanban board auto refresh	
	
-- 	SELECT ARRAY_AGG(tool_ticket_id) 
-- 	INTO v_tool_ticket_ids 
-- 	FROM tickets.tool_detail 
-- 	WHERE ticket_id = p_ticket_id AND is_active = TRUE;
	
-- 	CALL tickets.main_sub_board_refresh(
-- 		v_tool_ticket_ids,
-- 		p_ticket_id,
-- 		v_ob_boardid,
-- 		0,
-- 		v_ob_labelid,
-- 		'ADD',
-- 		p_added_by,
-- 		message := message,
-- 		status := status
-- 	);
		
    status := 'true';
    message := 'Order Processed to On-boarding.';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.set_process_order',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_added_by
            ))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: subtask_progress_bar(uuid, bigint, integer, text); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.subtask_progress_bar(p_regid uuid, p_ticket_id bigint, p_tool_ticket_id integer, p_timezone text DEFAULT 'UTC'::text) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN

    /*
    Created_by  : Mubarak Basha
    Description : Sub-Task Stage History & Time Tracking.
                  Returns complete lifetime history of a subtask across all boards.
    */

    RETURN QUERY
    WITH

    -- ── ALL LOG ROWS ──────────────────────────────────────────────────────────────
    all_log AS MATERIALIZED (
        SELECT
            tbl.tool_board_logid,
            tbl.tool_ticket_id,
            tbl.ticket_id,
            tbl.board_id,
            tbl.label_id,
            tbl.sequence,
            tbl.created_date,
            tbl.moved_by,
            tbl.is_moved
        FROM  tickets.tool_board_log tbl
        WHERE tbl.tool_ticket_id = p_tool_ticket_id
          AND tbl.ticket_id      = p_ticket_id
          AND tbl.is_active      = TRUE
    ),

    -- ── FINAL STAGE per board ─────────────────────────────────────────────────────
    final_stage AS MATERIALIZED (
        SELECT DISTINCT ON (b."BoardID")
            b."BoardID"  AS board_id,
            bs."LabelID" AS last_label_id
        FROM  board.board b
        JOIN  board.boardstatus bs
              ON bs."BoardID" = b."BoardID" AND bs.is_active = TRUE
        WHERE b.is_active = TRUE
        ORDER BY b."BoardID", bs."Position" DESC
    ),

    -- ── BOARD ORDER ───────────────────────────────────────────────────────────────
    board_order AS MATERIALIZED (
        SELECT
            al.board_id,
            MIN(al.created_date) AS board_entered_date,
            MAX(al.sequence)     AS max_seq_on_board
        FROM  all_log al
        GROUP BY al.board_id
        ORDER BY MIN(al.created_date)
    ),

    -- ── TRANSITIONS ───────────────────────────────────────────────────────────────
    transitions AS MATERIALIZED (
        SELECT
            al.tool_board_logid,
            al.board_id,
            al.label_id,
            al.sequence,
            al.created_date                        AS entry_date,
            al.moved_by,
            al.is_moved,
            LEAD(al.created_date) OVER (
                PARTITION BY al.board_id ORDER BY al.sequence
            )                                      AS exit_date,
            LAG(al.label_id) OVER (
                PARTITION BY al.board_id ORDER BY al.sequence
            )                                      AS prev_label_id,
            LAG(al.board_id) OVER (
                ORDER BY al.created_date, al.board_id, al.sequence
            )                                      AS prev_board_id,
            (al.sequence = bo.max_seq_on_board)    AS is_current_stage
        FROM  all_log al
        JOIN  board_order bo ON bo.board_id = al.board_id
    ),

    -- ── OVERALL TIME ──────────────────────────────────────────────────────────────
    overall_time AS MATERIALIZED (
        SELECT
            MIN(al.created_date) AS overall_start,
            CASE
                WHEN EXISTS (
                    SELECT 1 FROM transitions t
                    JOIN  final_stage fs ON fs.board_id = t.board_id
                    WHERE t.is_current_stage = TRUE
                      AND t.exit_date        IS NULL
                      AND t.label_id        <> fs.last_label_id
                )
                THEN NOW()::timestamp
                ELSE (
                    SELECT MAX(t.entry_date)
                    FROM   transitions t
                    JOIN   final_stage fs ON fs.board_id = t.board_id
                    WHERE  t.is_current_stage = TRUE
                      AND  t.label_id         = fs.last_label_id
                )
            END AS overall_end
        FROM all_log al
    ),

    -- ── BOARD DURATIONS ───────────────────────────────────────────────────────────
	board_duration AS MATERIALIZED (
		    SELECT
		        bo.board_id,
		        bo.board_entered_date,
		        CASE
		            WHEN EXISTS (
		                SELECT 1
		                FROM transitions t
		                JOIN final_stage fs
		                  ON fs.board_id = t.board_id
		                WHERE t.board_id = bo.board_id
		                  AND t.is_current_stage
		                  AND t.label_id <> fs.last_label_id
		            )
		            THEN NOW()::timestamp
		
		            ELSE (
		                SELECT t2.entry_date
		                FROM transitions t2
		                JOIN final_stage fs
		                  ON fs.board_id = t2.board_id
		                WHERE t2.board_id = bo.board_id
		                  AND t2.label_id = fs.last_label_id
		                ORDER BY t2.sequence DESC
		                LIMIT 1
		            )
		        END AS board_ended_date
		    FROM board_order bo
		),

    -- ── DUE DATE active at each stage entry ───────────────────────────────────────
    due_date_per_stage AS MATERIALIZED (
        SELECT DISTINCT ON (tr.board_id, tr.sequence)
            tr.board_id,
            tr.sequence,
            tdl.due_date::date AS due_date
        FROM  transitions tr
        JOIN  tickets.tool_duedate_log tdl
              ON  tdl.tool_ticket_id     = p_tool_ticket_id
              AND tdl.is_active          = TRUE
              AND tdl.created_date::date <= tr.entry_date::date
        ORDER BY tr.board_id, tr.sequence,
                 tdl.created_date DESC, tdl.tool_duedate_log_id DESC
    ),

    -- ── ALL TOOL HISTORY ──────────────────────────────────────────────────────────
    all_tool_history AS MATERIALIZED (
        SELECT
            (rec->>'created_date')::timestamp         AS log_date,
            COALESCE(rec->>'message',      '')         AS message,
            COALESCE(rec->>'history_type', '')         AS history_type
        FROM  tickets.tool_history th
        CROSS JOIN LATERAL jsonb_array_elements(th.history_data::jsonb) AS rec
        WHERE th.tool_ticket_id = p_tool_ticket_id
          AND th.is_active      = TRUE
    ),

    -- ── DUE DATE CHANGES within each stage visit ──────────────────────────────────
    due_date_change_per_stage AS MATERIALIZED (
        SELECT
            tr.board_id,
            tr.sequence,
            jsonb_agg(
                jsonb_build_object(
                    'changedOn', public.format_stage_datetime(ath.log_date, p_timezone),
                    'reason',    ath.message
                )
                ORDER BY ath.log_date ASC
            ) AS due_date_change_messages
        FROM  transitions tr
        JOIN  all_tool_history ath
              ON  ath.history_type = 'Due Date'
              AND ath.log_date    >= tr.entry_date
              AND (tr.exit_date IS NULL OR ath.log_date < tr.exit_date)
        GROUP BY tr.board_id, tr.sequence
    ),

    -- ── ASSIGNEES per tool_board_logid ────────────────────────────────────────────
    assignees_per_log AS MATERIALIZED (
        SELECT
            ta.tool_board_logid,
            jsonb_agg(
                jsonb_build_object(
                    'name',   ru."DisplayName",
                    'regId',  ru."RegId",
                    'photo',  ru.photo_url,
                    'email',  ru."Email"
                )
                ORDER BY ta.sequence
            ) AS assigned
        FROM  tickets.tool_assignee ta
        JOIN  users.registereduser ru
              ON ru."RegId"   = ta.assignee_to
             AND ru.is_active  = TRUE
        WHERE ta.is_active                          = TRUE
          AND COALESCE(ta.un_assigned_flag, FALSE)  = FALSE
          AND ta.tool_board_logid IN (SELECT tool_board_logid FROM all_log)
        GROUP BY ta.tool_board_logid
    ),

    -- ── STAGE HISTORY — one row per log entry ─────────────────────────────────────
    stage_history_rows AS (
        SELECT
            tr.board_id,
            tr.label_id,
            tr.sequence,
            tr.is_current_stage,
            tr.entry_date,
            tr.exit_date,
            (tr.label_id = fs.last_label_id) AS is_final_stage,
            jsonb_build_object(
                'stageName',        bs."Name",
                'stageId',          bs."LabelID",
                'stageEnteredDate', public.format_stage_datetime(tr.entry_date, p_timezone),
                'stageExitedDate',  CASE
                                        WHEN tr.is_current_stage THEN NULL
                                        ELSE public.format_stage_datetime(tr.exit_date, p_timezone)
                                    END,
								'stageDuration',
									CASE
									    WHEN tr.is_current_stage
									         AND tr.exit_date IS NULL
									         AND tr.label_id <> fs.last_label_id
									    THEN
									        CASE
									            WHEN EXTRACT(EPOCH FROM (NOW() - tr.entry_date)) < 60
									                THEN '0'
									            ELSE master.format_duration(
									                EXTRACT(EPOCH FROM (NOW() - tr.entry_date))::bigint
									            )
									        END
									    ELSE
									        CASE
									            WHEN EXTRACT(EPOCH FROM (
									                COALESCE(tr.exit_date, tr.entry_date) - tr.entry_date
									            )) < 60
									                THEN '0'
									            ELSE master.format_duration(
									                EXTRACT(EPOCH FROM (
									                    COALESCE(tr.exit_date, tr.entry_date) - tr.entry_date
									                ))::bigint
									            )
									        END
									END,
								'stageDurationOngoing', tr.is_current_stage,
								
								'isFinalStage', (tr.label_id = fs.last_label_id),
                'movedFrom',        CASE
                                        -- Cross-board: first stage on this board, came from another board
                                        WHEN tr.prev_label_id IS NULL
                                             AND tr.prev_board_id IS NOT NULL
                                             AND tr.prev_board_id <> tr.board_id
                                        THEN (
                                            SELECT pb."Name" || ' - ' || pbs."Name"
                                                   || ' to ' ||
                                                   cb."Name" || ' - ' || bs."Name"
                                            FROM  board.board pb
                                            JOIN  board.boardstatus pbs
                                                  ON pbs."BoardID" = tr.prev_board_id
                                                 AND pbs."LabelID" = (
                                                     SELECT al2.label_id FROM all_log al2
                                                     WHERE al2.board_id = tr.prev_board_id
                                                     ORDER BY al2.sequence DESC LIMIT 1
                                                 )
                                                 AND pbs.is_active = TRUE
                                            JOIN  board.board cb ON cb."BoardID" = tr.board_id
                                            WHERE pb."BoardID" = tr.prev_board_id
                                        )
                                        -- Same board: stage name transition
                                        WHEN tr.prev_label_id IS NOT NULL
                                        THEN (
                                            SELECT 'from ' || prev_bs."Name" || ' to ' || bs."Name"
                                            FROM   board.boardstatus prev_bs
                                            WHERE  prev_bs."BoardID" = tr.board_id
                                              AND  prev_bs."LabelID" = tr.prev_label_id
                                              AND  prev_bs.is_active  = TRUE
                                        )
                                        ELSE ''
                                    END,
                'dueDate',              dds.due_date,
                'dueDateChangedReason', COALESCE(ddc.due_date_change_messages, '[]'::jsonb),
                'overDueDateStatus',    CASE
                                            WHEN dds.due_date IS NULL             THEN FALSE
                                            WHEN tr.label_id = fs.last_label_id   THEN FALSE
                                            WHEN tr.is_current_stage
                                            THEN dds.due_date < CURRENT_DATE
                                            ELSE dds.due_date < tr.exit_date::date
                                        END,
                'assigned',             COALESCE(apl.assigned, '[]'::jsonb)
            ) AS history_entry
        FROM  transitions tr
        JOIN  board.boardstatus bs
              ON bs."BoardID" = tr.board_id
             AND bs."LabelID" = tr.label_id
             AND bs.is_active  = TRUE
        JOIN  final_stage fs   ON fs.board_id = tr.board_id
        LEFT  JOIN due_date_per_stage dds
               ON  dds.board_id = tr.board_id AND dds.sequence = tr.sequence
        LEFT  JOIN due_date_change_per_stage ddc
               ON  ddc.board_id = tr.board_id AND ddc.sequence = tr.sequence
        LEFT  JOIN assignees_per_log apl
               ON  apl.tool_board_logid = tr.tool_board_logid
    ),

    -- ── ALL STAGES on boards in scope ─────────────────────────────────────────────
    all_board_stages AS (
        SELECT
            bs."BoardID"  AS board_id,
            bs."LabelID"  AS label_id,
            bs."Name"     AS stage_name,
            bs."Position" AS stage_position
        FROM  board.boardstatus bs
        WHERE bs."BoardID" IN (SELECT board_id FROM board_order)
          AND bs.is_active  = TRUE
    ),

    -- ── TICKET INFO ───────────────────────────────────────────────────────────────
    ticket_info AS MATERIALIZED (
        SELECT
            t.ticket_id,
            t.name     AS ticket_name,
            t.order_id AS order_id
        FROM  tickets.ticket t
        WHERE t.ticket_id = p_ticket_id
          AND t.is_active  = TRUE
        LIMIT 1
    ),

    -- ── TOOL (SUBTASK) INFO ───────────────────────────────────────────────────────
    tool_info AS MATERIALIZED (
        SELECT
            td.tool_ticket_id,
            CASE
                WHEN mt."ToolName" = 'Euroland Tool' THEN td.sub_task_name
                WHEN mt."ToolName" IS NOT NULL        THEN mt."ToolName"
                ELSE td.sub_task_name
            END AS task_name,
            td.tool_id
        FROM  tickets.tool_detail td
        LEFT  JOIN master.tool mt ON mt."ToolID" = td.tool_id
        WHERE td.tool_ticket_id = p_tool_ticket_id
          AND td.is_active       = TRUE
        LIMIT 1
    )

    -- ── FINAL JSON OUTPUT ─────────────────────────────────────────────────────────
    SELECT jsonb_build_object(
        'status',  TRUE,
        'message', 'Sub-task progress fetched successfully',
        'data', jsonb_build_object(

            'ticketName', ti.ticket_name,
            'ticketId',   ti.ticket_id,
            'orderId',    ti.order_id,
            'taskId',     toi.tool_ticket_id,
            'taskName',   toi.task_name,

            -- Overall time: first entry → completion entry or NOW()
            'overallTime',     master.format_duration(
                                   EXTRACT(EPOCH FROM (ot.overall_end - ot.overall_start))::bigint
                               ),
            'overallTimeFrom', public.format_stage_datetime(ot.overall_start, p_timezone),
            'overallTimeTo',   public.format_stage_datetime(ot.overall_end,   p_timezone),
			'overallDurationOngoing',
						CASE
						    WHEN EXISTS (
						        SELECT 1
						        FROM transitions t
						        JOIN final_stage fs
						          ON fs.board_id = t.board_id
						        WHERE t.is_current_stage = TRUE
						          AND t.exit_date IS NULL
						          AND t.label_id <> fs.last_label_id
						    )
						    THEN TRUE
						    ELSE FALSE
						END,

            'boards', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'boardId',   b."BoardID",
                        'boardName', b."Name",

                        'boardDuration', CASE
                            WHEN bd.board_ended_date IS NULL
                              OR bd.board_entered_date IS NULL THEN NULL
                            ELSE master.format_duration(
                                EXTRACT(EPOCH FROM (bd.board_ended_date - bd.board_entered_date))::bigint
                            )
                        END,
                        'boardDurationDateFromTo', CASE
                            WHEN bd.board_entered_date IS NULL OR bd.board_ended_date IS NULL THEN NULL
                            ELSE public.format_stage_datetime(bd.board_entered_date, p_timezone)
                                 || ' - ' ||
                                 public.format_stage_datetime(bd.board_ended_date, p_timezone)
                        END,

                        -- Stages: visited stages in sequence order,
                        -- unvisited stages shown only if board hasn't reached final stage.
                        'stages', (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'stageName',      u.stage_name,
                                    'stageId',        u.label_id,
                                    'isCurrentStage', u.is_current_stage,
                                    'enteredDate',    u.entered_date,
                                    'exitDate',       u.exit_date,
                                    'stageHistory',   u.stage_history
                                )
                                ORDER BY u.sort_key
                            )
                            FROM (
                                -- Visited: one row per sequence, reopens as separate entries
                                SELECT
                                    shr.board_id,
                                    shr.label_id,
                                    bs2."Name"                                            AS stage_name,
                                    shr.is_current_stage,
                                    public.format_stage_datetime(shr.entry_date, p_timezone) AS entered_date,
                                    CASE
                                        WHEN shr.is_current_stage THEN NULL
                                        ELSE public.format_stage_datetime(shr.exit_date, p_timezone)
                                    END                                                   AS exit_date,
                                    jsonb_build_array(shr.history_entry)                  AS stage_history,
                                    (shr.sequence * 1000)::numeric                        AS sort_key
                                FROM  stage_history_rows shr
                                JOIN  board.boardstatus bs2
                                      ON bs2."BoardID" = shr.board_id
                                     AND bs2."LabelID" = shr.label_id
                                     AND bs2.is_active  = TRUE
                                WHERE shr.board_id = b."BoardID"
								UNION ALL
								    SELECT
								        abs3.board_id,
								        abs3.label_id,
								        abs3.stage_name,
								        FALSE AS is_current_stage,
								        NULL AS entered_date,
								        NULL AS exit_date,
								        '[]'::jsonb AS stage_history,
								        -- always sort AFTER every real history row on this board,
								        -- then in board-position order among themselves
								        ((bo2.max_seq_on_board + 1) * 1000 + abs3.stage_position)::numeric AS sort_key
								    FROM all_board_stages abs3
								    JOIN board.boardstatus bs_abs
								        ON bs_abs."BoardID" = abs3.board_id
								       AND bs_abs."LabelID" = abs3.label_id
								    JOIN board_order bo2
								        ON bo2.board_id = abs3.board_id
								    JOIN (
								        SELECT
								            shr.board_id,
								            MAX(bs."Position") AS current_position
								        FROM stage_history_rows shr
								        JOIN board.boardstatus bs
								          ON bs."BoardID" = shr.board_id
								         AND bs."LabelID" = shr.label_id
								        WHERE shr.is_current_stage = TRUE
								        GROUP BY shr.board_id
								    ) cp
								    ON cp.board_id = abs3.board_id
								    WHERE abs3.board_id = b."BoardID"
								      -- only stages after the CURRENT stage's position — regardless of whether
								      -- they were visited before this reopen
								      AND bs_abs."Position" > cp.current_position
                              
                            ) u
                        )
                    )
                    ORDER BY bo.board_entered_date
                )
                FROM  board_order bo
                JOIN  board.board b     ON b."BoardID"  = bo.board_id
                JOIN  board_duration bd ON bd.board_id  = bo.board_id
            )
        )
    )
    FROM  ticket_info  ti
    CROSS JOIN tool_info    toi
    CROSS JOIN overall_time ot;

END;
$$;


--
-- Name: task_board_refresh(integer[], integer, integer, integer, integer, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.task_board_refresh(IN p_tool_ticket_id integer[] DEFAULT NULL::integer[], IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_from_label_id integer DEFAULT 0, IN p_to_label_id integer DEFAULT 0, IN p_action text DEFAULT ''::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context text;

	v_workspace_id INTEGER := 0;
	v_workflow_typeid INTEGER := 0;
	v_flow_id INTEGER := 0;
	v_flow_name TEXT := 0;
	v_flow_tool_list jsonb;
	v_ticket_data jsonb;
	
	v_task_data jsonb;
	v_recipient_push text := NULL;
	v_reg text := NULL;
	v_task_filter jsonb;
	v_result_data jsonb;
	
	v_sub_obj jsonb;
	v_filtered_flow_tool_list jsonb;
	
	tool_item jsonb;
	v_remove_tool_data jsonb;
BEGIN

	--Get work flow type id
	SELECT status_id INTO v_workflow_typeid
	FROM master.status_code_master 
	WHERE is_active= true AND UPPER(type) = UPPER('WORKFLOWTYPE') AND UPPER(name) = UPPER('Task');
	
	--Get Main Board ID
  	SELECT work_space_id INTO v_workspace_id
	FROM board.board
	WHERE "BoardID" = p_board_id
	AND is_active = true;
	
	--Get Flow Id, Flow Name
	SELECT 
		COALESCE(f.flow_id, 0), 
		COALESCE(f.flow_name, '')     
	INTO 
		v_flow_id, 
		v_flow_name
	FROM (
		SELECT f.flow_id, f.flow_name
		FROM board.flow f
		WHERE EXISTS (
			SELECT 1
			FROM jsonb_array_elements(f.flow_details::jsonb) AS fd
			WHERE (fd->'Source'->>'workspace_id')::int = v_workspace_id
			  AND (fd->'Source'->>'board_id')::int = p_board_id
		)
		AND f.work_flow_type = v_workflow_typeid
		AND f.is_active = true
		LIMIT 1
	) f
	RIGHT JOIN (SELECT 1) dummy ON true;	
	
    WITH filtered_tool_flows AS (
        SELECT             
            ARRAY_AGG(tool_ticket_id ORDER BY tool_ticket_id) AS tool_ticket_ids
        FROM tickets.tool_detail
        WHERE tool_ticket_id = ANY(p_tool_ticket_id)
          AND is_active = TRUE
        GROUP BY flow_id
        ORDER BY flow_id
    ),
    latest_label_assignee AS (
		SELECT *
		FROM (
			SELECT DISTINCT ON (board_id, label_id, tool_board_logid)
				   board_id,
				   label_id,
				   assignee_to,
				   tool_board_logid,
				   un_assigned_flag,
				   sequence
			FROM tickets.tool_assignee
			WHERE is_active = TRUE
			  AND board_id = p_board_id
			ORDER BY
				board_id,
				label_id,
				tool_board_logid,
				sequence DESC
		) x
		WHERE un_assigned_flag = FALSE
    )
	--Get Flow Tool Details
    SELECT 
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'flowId', COALESCE(v_flow_id, 0),
                    'flowName', COALESCE(v_flow_name, ''),
                    'listOfTools', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'toolTicketId', td.tool_ticket_id,
                                'toolBoardLogId', tbl.tool_board_logid,
                                'toolId', td.tool_id,
                                'toolCode', mt."ToolCode",
                                'toolName', td.sub_task_name,
                                'toolStatusId', td.status_id,
								'priorityId', td.priority_id,
                                'assignee', CASE
                                    WHEN la.assignee_to IS NOT NULL THEN
                                        jsonb_build_array(
                                            jsonb_build_object(
                                                'regId', la.assignee_to::text,
                                                'name', COALESCE(u2."DisplayName", ''),
                                                'photo', COALESCE(u2.photo_url, '')
                                            )
                                        )
                                    ELSE '[]'::jsonb
                                END,
                                'dueDate', td.due_date
                            )
                        ) FILTER (WHERE td.tool_id IS NOT NULL) AS flowTools
                        FROM tickets.tool_detail td
                        JOIN (
                            SELECT DISTINCT ON (tool_ticket_id)
                                   tbl.tool_ticket_id,
                                   tbl.board_id,
                                   tbl.label_id,
                                   tbl.tool_board_logid
                            FROM tickets.tool_board_log tbl
                            WHERE tbl.board_id = p_board_id
                              AND tbl.is_active = true
                              AND tbl.is_moved = false
                            ORDER BY tbl.tool_ticket_id, sequence DESC
                        ) tbl ON td.tool_ticket_id = tbl.tool_ticket_id
                        JOIN master.tool mt 
                            ON td.tool_id = mt."ToolID" 
                           AND mt.is_active = true
                        LEFT JOIN latest_label_assignee la 
                            ON la.tool_board_logid = tbl.tool_board_logid
                        LEFT JOIN users.registereduser u2 
                            ON la.assignee_to = u2."RegId"
                        WHERE td.is_active = true 
                          AND td.tool_ticket_id = ANY(ft.tool_ticket_ids)
                    ), '[]'::jsonb)
                )
            ),
            '[]'::jsonb
        ) INTO v_flow_tool_list
    FROM filtered_tool_flows ft;

	-- Get Ticket Details 
    SELECT COALESCE(
        jsonb_build_object(
            'orderId', t.ticket_id,
            'taskName', t.name,
            'createdDate', t.order_date,
            'priorityId', t.priority_id,
			'lastUpdatedDate', master.calculate_time_ago(t.last_updated_date),           
            'createdBy', CASE
                WHEN t.updated_by IS NOT NULL THEN
                    jsonb_build_array(
                        jsonb_build_object(
                            'regId', t.updated_by::UUID,
                            'name', u."DisplayName",
                            'photo', u.photo_url
                        )
                    )
                ELSE '[]'::jsonb
            END
        ),
        '{}'::jsonb
    ) INTO v_ticket_data
    FROM tickets.ticket t
    LEFT JOIN users.registereduser u
        ON t.updated_by::UUID = u."RegId"
    WHERE t.ticket_id = p_ticket_id 
      AND t.is_active = true;	  	
		  		
	
	--task data
	v_task_data := jsonb_build_object(
            'type', 'KANBAN_UPDATE',
            'action', p_action,
            'level', 'TASK',
            'data', COALESCE(
                jsonb_build_object(                    
					'ticket',
						COALESCE(v_ticket_data, '{}'::jsonb)
						|| jsonb_build_object(
							'toolList', v_flow_tool_list,
							'labelId', p_to_label_id,
							'totalToolCount', 0
						),					
					'fromLabelId', p_from_label_id,
					'toLabelId', p_to_label_id
                ),
                '{}'::jsonb
            )
       ); 
	
	
	--RAISE INFO 'v_ticket_data : %', v_ticket_data;

	SELECT 
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_push	
	 FROM users.user_board_permission ubp
	 JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	 JOIN users.userprofile up ON r."RegId" = up.user_id AND up.is_active = true
	 WHERE ubp.board_id = p_board_id AND ubp.is_active = true AND ubp.reg_id != p_added_by
	 AND r.last_active_time IS NOT NULL AND r.last_active_time >= (NOW() AT TIME ZONE 'UTC') - INTERVAL '5 minutes' -- Only online users
	 AND (up.sub_board_filter IS NOT NULL
			  AND (up.sub_board_filter->>'board_id')::int = p_board_id); --Users whose main-board or sub-board filter matches the same board.

	-- Add Push Notification
	FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP
			
		-- Trim spaces if any
		v_reg := trim(v_reg);	
		
		
		--Filter the result data
		SELECT 
			sub_board_filter
		INTO
			v_task_filter
		FROM users.userprofile
		WHERE user_id = v_reg::UUID;			
	
		v_result_data := NULL;
		

		-- Build sub result (filtered or raw)
		v_result_data := CASE 
			WHEN v_task_filter IS NOT NULL 
			THEN (SELECT * FROM tickets.filter_kanban_by_main_sub(v_task_data, v_task_filter, 'TASK')) || jsonb_build_object(
						'type', 'KANBAN_UPDATE',
						'action', p_action,
						'level', 'TASK'
					)
			ELSE v_task_data 
		END;
		
		-- Combine 
		v_result_data := jsonb_build_array(v_result_data);	
		
		--Remove Tool data
		IF v_result_data IS NOT NULL 
				AND p_action = 'UPDATE' 
				AND EXISTS (
						SELECT 1
						FROM jsonb_array_elements(v_result_data) elem
						WHERE elem->>'level' = 'TASK'
					) 
				AND v_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_flow_tool_list) = 'array'
				AND jsonb_array_length(v_flow_tool_list) > 0 THEN
				
			-- Get the SUB element (single record)
			SELECT elem
			INTO v_sub_obj
			FROM jsonb_array_elements(v_result_data) elem
			WHERE elem->>'level' = 'TASK'
			LIMIT 1;
			
			v_filtered_flow_tool_list := '[]'::jsonb;
			
			-- Loop each item in toolList
			FOR tool_item IN
				SELECT value
				FROM jsonb_array_elements(v_sub_obj->'data'->'ticket'->'toolList') AS t(value)
			LOOP
				
				RAISE NOTICE 'Tool Item: %', tool_item;
				
				IF tool_item->'listOfTools' IS NULL OR tool_item->'listOfTools' = 'null'::jsonb THEN
					-- Extract flowId
					DECLARE
						v_flow_id text := tool_item->>'flowId';
						v_existing_item jsonb;
					BEGIN
						-- Find existing item with same flowId
						SELECT elem
						INTO v_existing_item
						FROM jsonb_array_elements(v_flow_tool_list) elem
						WHERE elem->>'flowId' = v_flow_id
						LIMIT 1;

						IF v_existing_item IS NOT NULL THEN
							-- No existing: add this tool_item
							v_filtered_flow_tool_list :=
								v_filtered_flow_tool_list || jsonb_build_array(v_existing_item);
						END IF;
					END;
				END IF;
				
			END LOOP;
			
			IF v_filtered_flow_tool_list IS NOT NULL 
				AND jsonb_typeof(v_filtered_flow_tool_list) = 'array'
				AND jsonb_array_length(v_filtered_flow_tool_list) > 0 THEN
				
				v_remove_tool_data := jsonb_build_array(
											jsonb_build_object(
												'type', 'KANBAN_UPDATE',
												'action', 'REMOVE',
												'level', 'TASK',
												'data', COALESCE(
													jsonb_build_object(                    
														'ticket',
															COALESCE(v_ticket_data, '{}'::jsonb)
															|| jsonb_build_object(
																'toolList', v_filtered_flow_tool_list,
																'labelId', p_to_label_id,
																'totalToolCount', 0
															),					
														'fromLabelId', p_from_label_id,
														'toLabelId', p_to_label_id
													),
													'{}'::jsonb
												)
											)
										   );
										   
				v_result_data := v_result_data || v_remove_tool_data;
				
			END IF;
		END IF;	
		
		--RAISE INFO 'v_result_data : %', v_result_data;
		-- Call the existing add_notification procedure for each recipient
		IF v_result_data IS NOT NULL THEN	
		
			CALL notification.add_notification(
				p_type := 'Push',
				p_recipient := v_reg,
				p_subject := 'KANBAN_UPDATE',
				p_message := 'Board and task details have been refreshed with the latest updates.',
				p_retry_count := 0,
				p_max_retries := 3,
				p_message_json := v_result_data::text,
				message := message,
				status := status
			);
			
		END IF;
	END LOOP;
	
	
    status := 'true';
    message := 'Notification Pushed.';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.task_board_refresh',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_ticket_id, p_ticket_id, p_board_id))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: ticket_comment_delete(bigint, bigint, bigint, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.ticket_comment_delete(IN in_ticket_id bigint, IN in_tool_ticket_id bigint, IN in_comment_id bigint, IN in_added_by uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/*****************************************************************************
Procedure   : tickets.ticket_comment_delete
Developer   : Mageswari.T
Created On  : 09-08-2025
Purpose     : Delete ticket comment
Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
09-09-2025  Mageswari.T         For tool delete tcomment
*******************************************************************************/
DECLARE
    typeid INTEGER;
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
BEGIN
    -- Validate input
    IF (in_ticket_id IS NULL OR in_ticket_id <= 0) 
       AND (in_tool_ticket_id IS NULL OR in_tool_ticket_id <= 0) THEN
        message := 'Either Ticket ID or Tool Ticket ID is mandatory';
        status := 'false';
        RETURN;
    END IF;

    IF in_comment_id IS NULL OR in_comment_id <= 0 THEN
        message := 'Comment ID is mandatory';
        status := 'false';
        RETURN;
    END IF;

    -- Get type_id for 'COMMENTS'
    SELECT type_id INTO typeid 
    FROM tickets.comments_type 
    WHERE UPPER(type_name) = 'COMMENTS' AND is_active = 'true';

    -- Soft delete for ticket_comments
    IF in_ticket_id > 0 AND (in_tool_ticket_id IS NULL OR in_tool_ticket_id = 0) THEN
        UPDATE tickets.ticket_comments
        SET is_active = 'false',
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
            updated_by = in_added_by
        WHERE ticket_id = in_ticket_id
          AND comment_id = in_comment_id
          AND type_id = typeid
          AND is_active = 'true';
        
        GET DIAGNOSTICS affected_rows = ROW_COUNT;
        total_affected_rows := total_affected_rows + affected_rows;
        RAISE INFO 'Ticket comment affected rows: %', affected_rows;
    END IF;

    -- Soft delete for tool_comments
    IF in_tool_ticket_id > 0 THEN
        UPDATE tickets.tool_comments
        SET is_active = 'false',
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
            updated_by = in_added_by
        WHERE tool_ticket_id = in_tool_ticket_id
          AND ticket_id = in_ticket_id
          AND comment_id = in_comment_id
          AND type_id = typeid
          AND is_active = 'true';
        
        GET DIAGNOSTICS affected_rows = ROW_COUNT;
        total_affected_rows := total_affected_rows + affected_rows;
        RAISE INFO 'Tool comment affected rows: %', affected_rows;
    END IF;

    -- Set output message based on affected rows
    IF total_affected_rows > 0 THEN
        message := 'Comment removed successfully.';
        status := 'true';
    ELSE
        message := 'No active comment found to remove.';
        status := 'false';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.ticket_comment_delete',
            CONCAT('Error: ', SQLERRM, ' | Context: ', message),
            in_added_by ::UUID,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(in_ticket_id, in_tool_ticket_id, in_comment_id, in_added_by))::text
        );
        status := 'false';
        message := 'An error occurred while deleting the comment.';
END;
$$;


--
-- Name: ticket_delete(boolean, integer[], integer[]); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.ticket_delete(p_customer_id boolean, p_ticket_id integer[] DEFAULT NULL::integer[], p_boardids integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  	p_ticket_id      integer[] := NULLIF(array_remove(p_ticket_id,     0), ARRAY[]::integer[]);
    p_boardids      integer[] := NULLIF(array_remove(p_boardids,     0), ARRAY[]::integer[]);
    v_ticketids         INTEGER[];
    v_tool_ticketids    INTEGER[];
    v_tool_board_logids INTEGER[];
BEGIN

	-- Created by   : Naveen S
	-- Created Date : 01/06/2026
	-- Purpose      : Overall,board or individual tickets deletion

    -- -------------------------------------------------------------------------
    -- Sample call (for reference / testing):
    -- -------------------------------------------------------------------------
    -- SELECT * FROM tickets.ticket_delete(
    --     false,           -- IOD Ticket 
    --     ARRAY[27],              -- individual ticket
    --     ARRAY[0]             -- individual board
    -- );
    -- -------------------------------------------------------------------------

    -- Get ticket ids
    SELECT ARRAY_AGG(DISTINCT t.ticket_id)
    INTO v_ticketids
    FROM tickets.ticket t
    WHERE
        (
            p_ticket_id IS NOT NULL
            AND t.ticket_id = ANY(p_ticket_id)
        )
        OR
        (
            p_ticket_id IS NULL
            AND (
                (NOT p_customer_id AND t.customer_id <> 1)
                OR
                (p_customer_id AND t.customer_id = 1)
            )
        );

    -- Filter by board ids if provided
    IF p_boardids IS NOT NULL THEN
        SELECT ARRAY_AGG(DISTINCT td.ticket_id)
        INTO v_ticketids
        FROM tickets.tool_detail td
        JOIN board.board b
            ON b."BoardID" = td.board_id
           AND b.is_active = TRUE
		WHERE
        (
            p_boardids IS NOT NULL
            AND b."BoardID" = ANY(p_boardids)
        )
        OR
        (
            p_boardids IS NULL
            AND (td.ticket_id = ANY(v_ticketids))       
        );
    END IF;

    -- No tickets found
    IF v_ticketids IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No tickets found'
        );
    END IF;

    -- Tool ticket ids
    SELECT ARRAY_AGG(DISTINCT tool_ticket_id)
    INTO v_tool_ticketids
    FROM tickets.tool_detail
    WHERE ticket_id = ANY(v_ticketids);

    -- Tool board log ids
    SELECT ARRAY_AGG(DISTINCT tool_board_logid)
    INTO v_tool_board_logids
    FROM tickets.tool_board_log
    WHERE tool_ticket_id = ANY(v_tool_ticketids);

    -- Delete child tables first
    DELETE FROM tickets.ticket_status
    WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket_assignee
    WHERE ticket_id = ANY(v_ticketids);
	
	DELETE FROM tickets.ticket_customer_branding_attachment ca
	USING tickets.ticket_customer_branding cb
	WHERE cb.section_id = ca.section_id
	AND cb.ticket_id = ANY(v_ticketids);
	
	DELETE FROM tickets.ticket_customer_branding
	WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket_history
    WHERE ticket_id = ANY(v_ticketids);
	
	DELETE FROM tickets.ticket_attachment
    WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket_comments
    WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket_company
    WHERE ticket_id = ANY(v_ticketids);
	
	DELETE FROM tickets.ticket_status_track
    WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket_tool_info
    WHERE tool_ticket_id = ANY(v_tool_ticketids);

    DELETE FROM tickets.tool_assignee
    WHERE tool_board_logid = ANY(v_tool_board_logids);
	
	DELETE FROM tickets.tool_comments
    WHERE tool_ticket_id = ANY(v_tool_ticketids);

    DELETE FROM tickets.tool_board_log
    WHERE tool_ticket_id = ANY(v_tool_ticketids);

    DELETE FROM tickets.tool_duedate_log
    WHERE tool_ticket_id = ANY(v_tool_ticketids);

    DELETE FROM tickets.tool_detail
    WHERE ticket_id = ANY(v_ticketids);

    DELETE FROM tickets.ticket
    WHERE ticket_id = ANY(v_ticketids);

    RETURN jsonb_build_object(
        'success', true,
        'deleted_ticket_count', COALESCE(array_length(v_ticketids, 1), 0)
    );

END;
$$;


--
-- Name: ticket_status_count(uuid, integer); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.ticket_status_count(p_login_user uuid DEFAULT NULL::uuid, p_all_user integer DEFAULT 0) RETURNS TABLE(totalorders integer, yettoprocess integer, open integer, inprogress integer, completed integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(1)::INTEGER AS totalOrders,
        COUNT(1) FILTER (WHERE scm.code = 'YTP')::INTEGER AS yetToProcess, 
        COUNT(1) FILTER (WHERE scm.code = 'OP')::INTEGER AS open,
        COUNT(1) FILTER (WHERE scm.code = 'INP')::INTEGER AS inProgress,
        COUNT(1) FILTER (WHERE scm.code = 'COM')::INTEGER AS completed
    FROM tickets.ticket t
    JOIN master.status_code_master scm 
        ON t.status_id = scm.status_id AND scm.is_active = true
	LEFT JOIN tickets.ticket_assignee ta ON ta.ticket_id = t.ticket_id 
				AND ta.assignee_to = p_login_user
				AND ta.assignee_type = 'SA'
				AND ta.is_active = true
    WHERE t.is_active = true AND scm.type = 'ORDERSTATUS' AND (p_all_user = 1 OR ta.ticket_id IS NOT NULL);
END;
$$;


--
-- Name: update_order_ticket(bigint, integer, text, text, integer[], integer[], integer[], integer[], integer[], integer[], text, boolean, timestamp without time zone, text, text, boolean, text, text, uuid, text, text, text, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_order_ticket(IN p_ticket_id bigint DEFAULT 0, IN p_company_id integer DEFAULT NULL::integer, IN p_company_name text DEFAULT NULL::text, IN p_company_code text DEFAULT NULL::text, IN p_industry_sector integer[] DEFAULT NULL::integer[], IN p_region integer[] DEFAULT NULL::integer[], IN p_country integer[] DEFAULT NULL::integer[], IN p_primary_market integer[] DEFAULT NULL::integer[], IN p_language integer[] DEFAULT NULL::integer[], IN p_instrument integer[] DEFAULT NULL::integer[], IN p_website_link text DEFAULT NULL::text, IN p_is_ipo boolean DEFAULT false, IN p_ipo_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_other_data text DEFAULT NULL::text, IN p_headquarters_address text DEFAULT NULL::text, IN p_is_same_address boolean DEFAULT false, IN p_ir_address text DEFAULT NULL::text, IN p_contact_form text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, IN p_page_type text DEFAULT NULL::text, IN p_branding text DEFAULT NULL::text, IN p_order_management_panel text DEFAULT NULL::text, IN p_isin text DEFAULT NULL::text, IN p_symbol text DEFAULT NULL::text, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE    
    v_company_id INTEGER := p_company_id;
	v_previous_company_id INTEGER := 0;
	v_ticket_company_id INTEGER := 0;
	v_company_exists INTEGER := 0;
	v_context text;
	v_max_ticket_company_id INTEGER := 0;	
	v_other_data JSONB := p_other_data::jsonb;
	v_contact_form JSONB := p_contact_form::jsonb;
	v_branding_guidelines_details JSONB := p_branding::jsonb;	
	v_order_management_panel JSONB := p_order_management_panel::jsonb;
	v_key TEXT;
    v_value JSONB;
	v_type TEXT;
	v_assignee_to UUID;	
	v_total_affected_rows INTEGER := 0;
	v_affected_rows INTEGER;
	history_content text;
	v_user_name text;
	v_stage_name TEXT;
	v_board_name TEXT;
	v_customer_ref_id INTEGER := 0;
	v_updated_customer boolean := false;
BEGIN

--Created By      Created_date       Purpose
--Aravindhan   04-07-2025         Add Company info

--Modified By		Created Date		Purpose
--Aravindhan B		24/07/2025			Add right side panel
--Modified By		Created Date		Purpose
--(fix)				13/08/2026			Company_info resolve/rename no longer gated on
--									customer_ref_id = 0; resolves via ticket's existing
--									customer FK first and renames that row in place.
-- 	CALL tickets.update_order_ticket(
-- 		-- Core ticket info
-- 		p_ticket_id            => 491,
-- 		p_company_id           => 889,
-- 		p_company_name         => 'Sumitomo Corporation',                         -- or '' if you prefer
-- 		p_company_code         => 'JP-SUMA',

-- 		-- Array-valued fields
-- 		p_industry_sector      => ARRAY[2],
-- 		p_region               => ARRAY[2],
-- 		p_country              => ARRAY[4],
-- 		p_primary_market       => ARRAY[21],
-- 		p_language             => ARRAY[41,42],
-- 		p_instrument           => ARRAY[5,6],            -- empty array

-- 		-- Simple scalar fields
-- 		p_website_link         => 'www.test.com',
-- 		p_is_ipo               => true,
-- 		p_ipo_date             => current_timestamp AT TIME ZONE 'UTC',                         -- no IPO date

-- 		-- JSONB fields
-- 		p_other_data           => '[{\"fieldName\":\"NewField\",\"fieldValue\":null,\"id\":1},{\"fieldName\":\"Field2\",\"fieldValue\":\"771\",\"id\":2,\"disabled\":false}]'::text,
-- 		p_headquarters_address => '123 Main Street, Anytown, CA 91234',
-- 		p_is_same_address      => true,
-- 		p_ir_address           => '123 Main Street, Anytown, CA 91234',
-- 		p_contact_form         => '{\"primaryContact\":{\"fullName\":\"Aravindhan\",\"dialCode\":\"91\",\"phoneNumber\":\"545465\",\"emailID\":\"test@gmail.com\",\"designation\":null,\"otherData\":[{\"fieldName\":\"Newfield\",\"fieldValue\":null,\"id\":1}]},\"secondaryContact\":{\"fullName\":\"sec\",\"dialCode\":1,\"phoneNumber\":\"6555545\",\"emailID\":\"sdf@gmail.com\",\"designation\":\"de\"}}'::text,

-- 		-- Audit/output params
-- 		p_added_by             => '2e1f5081-4a9d-4f9b-b1c3-8510b3b66e10'::uuid,
-- 		new_ticket_id          => NULL,
-- 		message                => NULL,
-- 		status                 => NULL
-- 	);
	
	-- Validate required arrays
	IF LOWER(p_page_type) = LOWER('Company_info') THEN
-- 		IF 
-- 		p_industry_sector IS NULL OR array_length(p_industry_sector, 1) IS NULL OR
-- 		p_region IS NULL OR array_length(p_region, 1) IS NULL OR
-- 		p_country IS NULL OR array_length(p_country, 1) IS NULL OR
-- 		p_primary_market IS NULL OR array_length(p_primary_market, 1) IS NULL OR
-- 		p_language IS NULL OR array_length(p_language, 1) IS NULL
-- 		THEN
-- 			RAISE INFO 'One or more required arrays are NULL or empty';

-- 			message := 'One or more required arrays are NULL or empty';
-- 			status := 'false';
-- 			RETURN;		
-- 		END IF;

		-- Get customer currently linked to this ticket (the row we should rename, if any)
		SELECT customer_id INTO v_previous_company_id
		FROM tickets.ticket
		WHERE ticket_id = p_ticket_id AND is_active = true;

		SELECT ticket_company_id INTO v_ticket_company_id
		FROM tickets.ticket_company
		WHERE ticket_id = p_ticket_id AND is_active = true LIMIT 1;

		v_company_id := NULL;
		v_customer_ref_id := 0;

		-- =========================================================
		-- Resolve target customer row.
		-- FIX: previously this only inserted/repointed when the linked
		-- customer's customer_ref_id was 0, so any customer that already
		-- had a ref id set (the normal case) silently skipped both branches
		-- and the rename never happened. Now we resolve via the ticket's
		-- existing FK first (or fall back through id/ref/code/name), then
		-- always rename that resolved row in place.
		-- =========================================================

		-- 1) Primary path: the customer already linked to this ticket
		IF v_previous_company_id IS NOT NULL THEN
			SELECT customer_id, customer_ref_id
			INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_id = v_previous_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 2) Fallback: UI companyId as customers.customer.customer_id
		IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_id = p_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 3) Fallback: Europe-mapped id stored as customer_ref_id
		IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_ref_id = p_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 4) Fallback: match by customer_code
		IF v_company_id IS NULL AND NULLIF(TRIM(p_company_code), '') IS NOT NULL THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE LOWER(TRIM(customer_code)) = LOWER(TRIM(p_company_code)) AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 5) Fallback: exact (case-insensitive) name match
		SELECT COUNT(*) INTO v_company_exists
		FROM customers.customer
		WHERE LOWER(company_name) = LOWER(p_company_name) AND is_active = true;

		IF v_company_id IS NULL AND v_company_exists <> 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE LOWER(TRIM(company_name)) = LOWER(TRIM(p_company_name)) AND is_active = TRUE
			LIMIT 1;
		END IF;

		IF v_company_id IS NULL THEN
			-- Nothing resolved anywhere -> genuinely new company
			RAISE INFO 'Inserting new company: %', p_company_name;
			INSERT INTO customers.customer (
				customer_ref_id, company_name, customer_code, is_active, created_by, created_date
			) VALUES (
				NULLIF(p_company_id, 0), p_company_name, p_company_code, true, p_added_by, current_timestamp AT TIME ZONE 'UTC'
			) RETURNING customer_id INTO v_company_id;
			v_updated_customer := true;
		ELSE
			-- Rename / refresh the resolved customer row in place
			UPDATE customers.customer
			SET
				company_name = COALESCE(NULLIF(TRIM(p_company_name), ''), company_name),
				customer_code = COALESCE(NULLIF(TRIM(p_company_code), ''), customer_code),
				customer_ref_id = CASE
					WHEN p_company_id IS NOT NULL AND p_company_id > 0 AND p_company_id <> COALESCE(v_customer_ref_id, 0)
						THEN p_company_id
					ELSE customer_ref_id
				END,
				updated_by = p_added_by::text,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE customer_id = v_company_id;

			v_updated_customer := true;
		END IF;

		-- Keep ticket in sync with resolved/renamed customer
		IF v_updated_customer THEN		
			
			UPDATE tickets.ticket SET 
				name = p_company_name,
				customer_id = v_company_id 
			WHERE 
				ticket_id = p_ticket_id AND 
				is_active = true;

			-- Only deactivate the previous customer row if the ticket actually
			-- moved to a *different* customer and it's a ref-less orphan
			IF v_previous_company_id IS NOT NULL
			   AND v_previous_company_id <> v_company_id
			   AND NOT EXISTS (
					SELECT 1
					FROM tickets.ticket
					WHERE customer_id = v_previous_company_id
					  AND is_active = TRUE
			   ) THEN
				UPDATE customers.customer SET is_active = false
				WHERE customer_ref_id = 0
				  AND customer_id = v_previous_company_id
				  AND is_active = TRUE;
			END IF;
		END IF;	

		--Update industory_id
			UPDATE tickets.ticket SET 
		        industory_id = p_industry_sector,
		        primary_market = p_primary_market,
		        isin = p_isin,
		        symbol = p_symbol
		    WHERE 
		        ticket_id = p_ticket_id AND 
		        is_active = true;
		
		--Insert/update ticket company table
		IF v_ticket_company_id IS NULL OR v_ticket_company_id = 0 THEN
			--Get max of ticket company id.
			SELECT 
				COALESCE(MAX(ticket_company_id), 0) + 1 INTO v_max_ticket_company_id
			FROM tickets.ticket_company;				

			--Insert into ticket_company
			INSERT INTO tickets.ticket_company (
				ticket_company_id, ticket_id, region_id, country_id, language_id, instrument_id, website_link,
				is_ipo, ipo_date, headquarters_address, ir_address, is_same_as_address, other_data, contect_info,
				branding_guidelines_details, created_by, created_date, is_active, last_updated_date, updated_by
			)
			VALUES (
				v_max_ticket_company_id, p_ticket_id, p_region, p_country, p_language, p_instrument, p_website_link,
				p_is_ipo, p_ipo_date, p_headquarters_address, p_ir_address, p_is_same_address, v_other_data, v_contact_form,
				NULL, p_added_by, current_timestamp AT TIME ZONE 'UTC', true, NULL, NULL
			);
			GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		ELSIF v_ticket_company_id > 0 then
			-- existing ticket_company → do UPDATE
			UPDATE tickets.ticket_company SET 
-- 				industory_id = p_industry_sector,
				region_id = p_region,
				country_id = p_country,
				--language_id = p_language,
				instrument_id = p_instrument,
				website_link = p_website_link,
				is_ipo = p_is_ipo,
				ipo_date = p_ipo_date,
				headquarters_address = p_headquarters_address,
				ir_address = p_ir_address,
				is_same_as_address = p_is_same_address,
				other_data = v_other_data,
				contect_info = v_contact_form,
				updated_by = p_added_by,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE 
				ticket_company_id = v_ticket_company_id AND is_active = true;
				GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		END IF;	
		PERFORM tickets.add_or_update_history_details(
            in_order_id          => p_ticket_id,
            in_content           => CONCAT('Updated company information for "', COALESCE(p_company_name, ''), '"'),
            in_user_id           => p_added_by,
            in_created_by        => p_added_by,
            in_created_date      => current_timestamp AT TIME ZONE 'UTC',
            in_uploaded_file_name=> NULL,
            in_history_type      => 'Company Info Updated'
        );
		RAISE INFO 'Updated Company_info.';
	ELSIF LOWER(p_page_type) = LOWER('Branding') THEN
		
		-- Get Previous customer ID
		SELECT ticket_company_id INTO v_ticket_company_id
		FROM tickets.ticket_company
		WHERE ticket_id = p_ticket_id AND is_active = true LIMIT 1;

		UPDATE tickets.ticket_company SET 
				branding_guidelines_details = v_branding_guidelines_details,				
				updated_by = p_added_by,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE 
				ticket_company_id = v_ticket_company_id AND is_active = true;
				GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		PERFORM tickets.add_or_update_history_details(
            in_order_id           => p_ticket_id,
            in_content            => 'Updated branding guidelines',
            in_user_id            => p_added_by,
            in_created_by         => p_added_by,
            in_created_date       => current_timestamp AT TIME ZONE 'UTC',
            in_uploaded_file_name => NULL,
            in_history_type       => 'Branding Updated'
        );
		
		RAISE INFO 'Updated Branding.';
	ELSIF LOWER(p_page_type) = LOWER('Order_Management_Panel') THEN
		
		FOR v_key, v_value IN SELECT * FROM jsonb_each(v_order_management_panel)
		LOOP
			v_type := (v_order_management_panel -> 'type') ->> 0;
			RAISE INFO 'v_key :% , v_value :%', v_key, v_value;
			IF v_key = 'ticketAsignee' THEN	
			
				IF jsonb_array_length(v_value) > 0 THEN
					UPDATE tickets.ticket_assignee
					SET is_active = false,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC',
						updated_by = p_added_by
					WHERE ticket_id = p_ticket_id
					  AND assignee_type = v_type
					  AND is_active = true
					  AND NOT (
						assignee_to = ANY (
							ARRAY(
								SELECT jsonb_array_elements_text(v_value)::uuid
							)
						)
					);
					GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
				ELSE
					-- No assignees provided, so deactivate all existing active ones
					UPDATE tickets.ticket_assignee
					SET is_active = false,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC',
						updated_by = p_added_by
					WHERE ticket_id = p_ticket_id
					  AND assignee_type = v_type
					  AND is_active = true;
					  GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
				END IF;

				FOR v_assignee_to IN (
					SELECT jsonb_array_elements_text(v_value)::uuid
				)
				LOOP
					
					IF NOT EXISTS (
						SELECT 1 FROM tickets.ticket_assignee
						WHERE ticket_id = p_ticket_id
						  AND assignee_to = v_assignee_to
						  AND assignee_type = v_type
						  AND is_active = true
					) THEN						
					
						INSERT INTO tickets.ticket_assignee (							
							ticket_id,
							assignee_to,
							assigned_date,
							created_by,
							created_date,
							is_active,
							assignee_type
						)
						VALUES (							
							p_ticket_id,
							v_assignee_to,
							current_timestamp AT TIME ZONE 'UTC',
							p_added_by,
							current_timestamp AT TIME ZONE 'UTC',
							true,
							v_type
						);
						
						 GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
						 
						IF v_total_affected_rows > 0 THEN
						 
						 	SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = v_assignee_to AND is_active = true;
							
							
                            PERFORM tickets.add_or_update_history_details(
                                in_order_id           => p_ticket_id,
								in_content 			  => CASE 
															  WHEN p_added_by = v_assignee_to THEN
																  'self-assigned the OB Order Manager.'
															  ELSE
																  'assigned the OB Order Manager to "' || v_user_name ||'".'
														  END,
                                in_user_id            => p_added_by,
                                in_created_by         => p_added_by,
                                in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                                in_uploaded_file_name => NULL,
                                in_history_type       => 'Assignee Updated'
                            );
														
							IF upper(COALESCE(v_type, '')) IN ('OB') THEN	
							
								SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = p_added_by AND is_active = true;
								
								IF v_assignee_to != p_added_by THEN
								
									--Push Notification
									CALL notification.add_notification(
										p_type := 'Push',
										p_recipient := v_assignee_to::text,
										p_subject := 'Card Assigned',
										p_message := 'You have been assigned to the card: <b>' || COALESCE(p_company_name, '') || '</b> by <b>' || COALESCE(v_user_name, '') || '<b>.',
										p_retry_count := 0,
										p_max_retries := 3,
										p_message_json := '{
															"ticket_id": '|| p_ticket_id ||',
															"tool_id": 0,
															"tool_ticket_id": 0,
															"board_id": 0,
															"moved_from": "'|| p_added_by::text ||'",
															"moved_to": "'|| v_assignee_to::text ||'",
															"notify_message": "You have been assigned to the card: <b>' || COALESCE(p_company_name, '') || '</b> by <b>' || COALESCE(v_user_name, '') || '<b>.",	
															"is_read": false,
															"type": "ticket_assignee",	
															"workspace_id": 0,
															"header": "Card Assigned"
														   }'::text,
										message := message,
										status := status
									);
								
								END IF;
														
							END IF;
							
							IF upper(COALESCE(v_type, '')) IN ('OB','SA') THEN
								IF v_total_affected_rows > 0 THEN
									message := CASE upper(v_type)
												   WHEN 'OB' THEN 'Onboarding member updated successfully.'
												   WHEN 'SA' THEN 'Sales member updated successfully.'
											   END;
									new_ticket_id := p_ticket_id;
									status := 'true';
									RETURN;
								ELSE
									new_ticket_id := p_ticket_id;
									status := 'true';
									message := 'No member updates performed.';
									RETURN;
								END IF;
							END IF;
						END IF;	
					END IF;	
				END LOOP;
			ELSIF v_key = 'ticketLabels' THEN
				RAISE INFO 'v_key :% , v_value :%', v_key, v_value;
				IF UPPER(v_type) = 'LABEL' THEN
					UPDATE tickets.ticket SET 
						order_label_id = (SELECT array_agg(value::int) FROM jsonb_array_elements_text(v_value)),
						updated_by = p_added_by,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC'
					WHERE 
						ticket_id = p_ticket_id AND 
						is_active = true; 
						GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
					IF v_affected_rows > 0 THEN
					PERFORM tickets.add_or_update_history_details(
                        in_order_id           => p_ticket_id,
                        in_content            => 'Updated ticket labels',
                        in_user_id            => p_added_by,
                        in_created_by         => p_added_by,
                        in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                        in_uploaded_file_name => NULL,
                        in_history_type       => 'Label Updated'
                    );
					new_ticket_id := p_ticket_id;
					status := 'true';
					message := 'Label updated successfully.';
					RETURN;
					END IF;
				END IF;
			END IF;
		END LOOP;
	ELSE		
		status := 'false';
		message := 'Invalid Input.';
		RETURN;	
	END IF;
	 -- Final status/message
    new_ticket_id := p_ticket_id;
  	status := 'true';
    message := 'Order updated successfully.';
	
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.update_order_ticket',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_company_id,
                p_company_name,
                p_company_code,
                p_industry_sector,
                p_region,
                p_country,
                p_primary_market,
                p_language,
				p_instrument,
				p_website_link,
				p_is_ipo,
				p_ipo_date,
				p_other_data,
				p_headquarters_address,
				p_is_same_address,
				p_ir_address,
				p_contact_form,
				p_is_ipo,
				p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: update_order_ticket_mubarak(bigint, integer, text, text, integer[], integer[], integer[], integer[], integer[], integer[], text, boolean, timestamp without time zone, text, text, boolean, text, text, uuid, text, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_order_ticket_mubarak(IN p_ticket_id bigint DEFAULT 0, IN p_company_id integer DEFAULT NULL::integer, IN p_company_name text DEFAULT NULL::text, IN p_company_code text DEFAULT NULL::text, IN p_industry_sector integer[] DEFAULT NULL::integer[], IN p_region integer[] DEFAULT NULL::integer[], IN p_country integer[] DEFAULT NULL::integer[], IN p_primary_market integer[] DEFAULT NULL::integer[], IN p_language integer[] DEFAULT NULL::integer[], IN p_instrument integer[] DEFAULT NULL::integer[], IN p_website_link text DEFAULT NULL::text, IN p_is_ipo boolean DEFAULT false, IN p_ipo_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_other_data text DEFAULT NULL::text, IN p_headquarters_address text DEFAULT NULL::text, IN p_is_same_address boolean DEFAULT false, IN p_ir_address text DEFAULT NULL::text, IN p_contact_form text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, IN p_page_type text DEFAULT NULL::text, IN p_branding text DEFAULT NULL::text, IN p_order_management_panel text DEFAULT NULL::text, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE    
    v_company_id INTEGER := p_company_id;
	v_previous_company_id INTEGER := 0;
	v_ticket_company_id INTEGER := 0;
	v_company_exists INTEGER := 0;
	v_context text;
	v_max_ticket_company_id INTEGER := 0;	
	v_other_data JSONB := p_other_data::jsonb;
	v_contact_form JSONB := p_contact_form::jsonb;
	v_branding_guidelines_details JSONB := p_branding::jsonb;	
	v_order_management_panel JSONB := p_order_management_panel::jsonb;
	v_key TEXT;
    v_value JSONB;
	v_type TEXT;
	v_assignee_to UUID;	
	v_total_affected_rows INTEGER := 0;
	v_affected_rows INTEGER;
	history_content text;
	v_user_name text;
	v_stage_name TEXT;
	v_board_name TEXT;
	v_customer_ref_id INTEGER := 0;
	v_updated_customer boolean := false;
BEGIN

--Created By      Created_date       Purpose
--Aravindhan   04-07-2025         Add Company info

--Modified By		Created Date		Purpose
--Aravindhan B		24/07/2025			Add right side panel
--Modified By		Created Date		Purpose
--(fix)				13/08/2026			Company_info resolve/rename no longer gated on
--									customer_ref_id = 0; resolves via ticket's existing
--									customer FK first and renames that row in place.
-- 	CALL tickets.update_order_ticket(
-- 		-- Core ticket info
-- 		p_ticket_id            => 491,
-- 		p_company_id           => 889,
-- 		p_company_name         => 'Sumitomo Corporation',                         -- or '' if you prefer
-- 		p_company_code         => 'JP-SUMA',

-- 		-- Array-valued fields
-- 		p_industry_sector      => ARRAY[2],
-- 		p_region               => ARRAY[2],
-- 		p_country              => ARRAY[4],
-- 		p_primary_market       => ARRAY[21],
-- 		p_language             => ARRAY[41,42],
-- 		p_instrument           => ARRAY[5,6],            -- empty array

-- 		-- Simple scalar fields
-- 		p_website_link         => 'www.test.com',
-- 		p_is_ipo               => true,
-- 		p_ipo_date             => current_timestamp AT TIME ZONE 'UTC',                         -- no IPO date

-- 		-- JSONB fields
-- 		p_other_data           => '[{\"fieldName\":\"NewField\",\"fieldValue\":null,\"id\":1},{\"fieldName\":\"Field2\",\"fieldValue\":\"771\",\"id\":2,\"disabled\":false}]'::text,
-- 		p_headquarters_address => '123 Main Street, Anytown, CA 91234',
-- 		p_is_same_address      => true,
-- 		p_ir_address           => '123 Main Street, Anytown, CA 91234',
-- 		p_contact_form         => '{\"primaryContact\":{\"fullName\":\"Aravindhan\",\"dialCode\":\"91\",\"phoneNumber\":\"545465\",\"emailID\":\"test@gmail.com\",\"designation\":null,\"otherData\":[{\"fieldName\":\"Newfield\",\"fieldValue\":null,\"id\":1}]},\"secondaryContact\":{\"fullName\":\"sec\",\"dialCode\":1,\"phoneNumber\":\"6555545\",\"emailID\":\"sdf@gmail.com\",\"designation\":\"de\"}}'::text,

-- 		-- Audit/output params
-- 		p_added_by             => '2e1f5081-4a9d-4f9b-b1c3-8510b3b66e10'::uuid,
-- 		new_ticket_id          => NULL,
-- 		message                => NULL,
-- 		status                 => NULL
-- 	);
	
	-- Validate required arrays
	IF LOWER(p_page_type) = LOWER('Company_info') THEN
-- 		IF 
-- 		p_industry_sector IS NULL OR array_length(p_industry_sector, 1) IS NULL OR
-- 		p_region IS NULL OR array_length(p_region, 1) IS NULL OR
-- 		p_country IS NULL OR array_length(p_country, 1) IS NULL OR
-- 		p_primary_market IS NULL OR array_length(p_primary_market, 1) IS NULL OR
-- 		p_language IS NULL OR array_length(p_language, 1) IS NULL
-- 		THEN
-- 			RAISE INFO 'One or more required arrays are NULL or empty';

-- 			message := 'One or more required arrays are NULL or empty';
-- 			status := 'false';
-- 			RETURN;		
-- 		END IF;

		-- Get customer currently linked to this ticket (the row we should rename, if any)
		SELECT customer_id INTO v_previous_company_id
		FROM tickets.ticket
		WHERE ticket_id = p_ticket_id AND is_active = true;

		SELECT ticket_company_id INTO v_ticket_company_id
		FROM tickets.ticket_company
		WHERE ticket_id = p_ticket_id AND is_active = true LIMIT 1;

		v_company_id := NULL;
		v_customer_ref_id := 0;

		-- =========================================================
		-- Resolve target customer row.
		-- FIX: previously this only inserted/repointed when the linked
		-- customer's customer_ref_id was 0, so any customer that already
		-- had a ref id set (the normal case) silently skipped both branches
		-- and the rename never happened. Now we resolve via the ticket's
		-- existing FK first (or fall back through id/ref/code/name), then
		-- always rename that resolved row in place.
		-- =========================================================

		-- 1) Primary path: the customer already linked to this ticket
		IF v_previous_company_id IS NOT NULL THEN
			SELECT customer_id, customer_ref_id
			INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_id = v_previous_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 2) Fallback: UI companyId as customers.customer.customer_id
		IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_id = p_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 3) Fallback: Europe-mapped id stored as customer_ref_id
		IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE customer_ref_id = p_company_id AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 4) Fallback: match by customer_code
		IF v_company_id IS NULL AND NULLIF(TRIM(p_company_code), '') IS NOT NULL THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE LOWER(TRIM(customer_code)) = LOWER(TRIM(p_company_code)) AND is_active = TRUE
			LIMIT 1;
		END IF;

		-- 5) Fallback: exact (case-insensitive) name match
		SELECT COUNT(*) INTO v_company_exists
		FROM customers.customer
		WHERE LOWER(company_name) = LOWER(p_company_name) AND is_active = true;

		IF v_company_id IS NULL AND v_company_exists <> 0 THEN
			SELECT customer_id, customer_ref_id INTO v_company_id, v_customer_ref_id
			FROM customers.customer
			WHERE LOWER(TRIM(company_name)) = LOWER(TRIM(p_company_name)) AND is_active = TRUE
			LIMIT 1;
		END IF;

		IF v_company_id IS NULL THEN
			-- Nothing resolved anywhere -> genuinely new company
			RAISE INFO 'Inserting new company: %', p_company_name;
			INSERT INTO customers.customer (
				customer_ref_id, company_name, customer_code, is_active, created_by, created_date
			) VALUES (
				NULLIF(p_company_id, 0), p_company_name, p_company_code, true, p_added_by, current_timestamp AT TIME ZONE 'UTC'
			) RETURNING customer_id INTO v_company_id;
			v_updated_customer := true;
		ELSE
			-- Rename / refresh the resolved customer row in place
			UPDATE customers.customer
			SET
				company_name = COALESCE(NULLIF(TRIM(p_company_name), ''), company_name),
				customer_code = COALESCE(NULLIF(TRIM(p_company_code), ''), customer_code),
				customer_ref_id = CASE
					WHEN p_company_id IS NOT NULL AND p_company_id > 0 AND p_company_id <> COALESCE(v_customer_ref_id, 0)
						THEN p_company_id
					ELSE customer_ref_id
				END,
				updated_by = p_added_by::text,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE customer_id = v_company_id;

			v_updated_customer := true;
		END IF;

		-- Keep ticket in sync with resolved/renamed customer
		IF v_updated_customer THEN		
			
			UPDATE tickets.ticket SET 
				name = p_company_name,
				customer_id = v_company_id 
			WHERE 
				ticket_id = p_ticket_id AND 
				is_active = true;

			-- Only deactivate the previous customer row if the ticket actually
			-- moved to a *different* customer and it's a ref-less orphan
			IF v_previous_company_id IS NOT NULL
			   AND v_previous_company_id <> v_company_id
			   AND NOT EXISTS (
					SELECT 1
					FROM tickets.ticket
					WHERE customer_id = v_previous_company_id
					  AND is_active = TRUE
			   ) THEN
				UPDATE customers.customer SET is_active = false
				WHERE customer_ref_id = 0
				  AND customer_id = v_previous_company_id
				  AND is_active = TRUE;
			END IF;
		END IF;	

		--Update industory_id
			UPDATE tickets.ticket SET 
			        industory_id = p_industry_sector,
			        primary_market = p_primary_market
			    WHERE 
			        ticket_id = p_ticket_id AND 
			        is_active = true;
		
		--Insert/update ticket company table
		IF v_ticket_company_id IS NULL OR v_ticket_company_id = 0 THEN
			--Get max of ticket company id.
			SELECT 
				COALESCE(MAX(ticket_company_id), 0) + 1 INTO v_max_ticket_company_id
			FROM tickets.ticket_company;				

			--Insert into ticket_company
			INSERT INTO tickets.ticket_company (
				ticket_company_id, ticket_id, region_id, country_id, language_id, instrument_id, website_link,
				is_ipo, ipo_date, headquarters_address, ir_address, is_same_as_address, other_data, contect_info,
				branding_guidelines_details, created_by, created_date, is_active, last_updated_date, updated_by
			)
			VALUES (
				v_max_ticket_company_id, p_ticket_id, p_region, p_country, p_language, p_instrument, p_website_link,
				p_is_ipo, p_ipo_date, p_headquarters_address, p_ir_address, p_is_same_address, v_other_data, v_contact_form,
				NULL, p_added_by, current_timestamp AT TIME ZONE 'UTC', true, NULL, NULL
			);
			GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		ELSIF v_ticket_company_id > 0 then
			-- existing ticket_company → do UPDATE
			UPDATE tickets.ticket_company SET 
-- 				industory_id = p_industry_sector,
				region_id = p_region,
				country_id = p_country,
				--language_id = p_language,
				instrument_id = p_instrument,
				website_link = p_website_link,
				is_ipo = p_is_ipo,
				ipo_date = p_ipo_date,
				headquarters_address = p_headquarters_address,
				ir_address = p_ir_address,
				is_same_as_address = p_is_same_address,
				other_data = v_other_data,
				contect_info = v_contact_form,
				updated_by = p_added_by,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE 
				ticket_company_id = v_ticket_company_id AND is_active = true;
				GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		END IF;	
		PERFORM tickets.add_or_update_history_details(
            in_order_id          => p_ticket_id,
            in_content           => CONCAT('Updated company information for "', COALESCE(p_company_name, ''), '"'),
            in_user_id           => p_added_by,
            in_created_by        => p_added_by,
            in_created_date      => current_timestamp AT TIME ZONE 'UTC',
            in_uploaded_file_name=> NULL,
            in_history_type      => 'Company Info Updated'
        );
		RAISE INFO 'Updated Company_info.';
	ELSIF LOWER(p_page_type) = LOWER('Branding') THEN
		
		-- Get Previous customer ID
		SELECT ticket_company_id INTO v_ticket_company_id
		FROM tickets.ticket_company
		WHERE ticket_id = p_ticket_id AND is_active = true LIMIT 1;

		UPDATE tickets.ticket_company SET 
				branding_guidelines_details = v_branding_guidelines_details,				
				updated_by = p_added_by,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE 
				ticket_company_id = v_ticket_company_id AND is_active = true;
				GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        v_total_affected_rows := v_total_affected_rows + v_affected_rows;
		PERFORM tickets.add_or_update_history_details(
            in_order_id           => p_ticket_id,
            in_content            => 'Updated branding guidelines',
            in_user_id            => p_added_by,
            in_created_by         => p_added_by,
            in_created_date       => current_timestamp AT TIME ZONE 'UTC',
            in_uploaded_file_name => NULL,
            in_history_type       => 'Branding Updated'
        );
		
		RAISE INFO 'Updated Branding.';
	ELSIF LOWER(p_page_type) = LOWER('Order_Management_Panel') THEN
		
		FOR v_key, v_value IN SELECT * FROM jsonb_each(v_order_management_panel)
		LOOP
			v_type := (v_order_management_panel -> 'type') ->> 0;
			RAISE INFO 'v_key :% , v_value :%', v_key, v_value;
			IF v_key = 'ticketAsignee' THEN	
			
				IF jsonb_array_length(v_value) > 0 THEN
					UPDATE tickets.ticket_assignee
					SET is_active = false,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC',
						updated_by = p_added_by
					WHERE ticket_id = p_ticket_id
					  AND assignee_type = v_type
					  AND is_active = true
					  AND NOT (
						assignee_to = ANY (
							ARRAY(
								SELECT jsonb_array_elements_text(v_value)::uuid
							)
						)
					);
					GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
				ELSE
					-- No assignees provided, so deactivate all existing active ones
					UPDATE tickets.ticket_assignee
					SET is_active = false,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC',
						updated_by = p_added_by
					WHERE ticket_id = p_ticket_id
					  AND assignee_type = v_type
					  AND is_active = true;
					  GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
				END IF;

				FOR v_assignee_to IN (
					SELECT jsonb_array_elements_text(v_value)::uuid
				)
				LOOP
					
					IF NOT EXISTS (
						SELECT 1 FROM tickets.ticket_assignee
						WHERE ticket_id = p_ticket_id
						  AND assignee_to = v_assignee_to
						  AND assignee_type = v_type
						  AND is_active = true
					) THEN						
					
						INSERT INTO tickets.ticket_assignee (							
							ticket_id,
							assignee_to,
							assigned_date,
							created_by,
							created_date,
							is_active,
							assignee_type
						)
						VALUES (							
							p_ticket_id,
							v_assignee_to,
							current_timestamp AT TIME ZONE 'UTC',
							p_added_by,
							current_timestamp AT TIME ZONE 'UTC',
							true,
							v_type
						);
						
						 GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                            v_total_affected_rows := v_total_affected_rows + v_affected_rows;
						 
						IF v_total_affected_rows > 0 THEN
						 
						 	SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = v_assignee_to AND is_active = true;
							
							
                            PERFORM tickets.add_or_update_history_details(
                                in_order_id           => p_ticket_id,
								in_content 			  => CASE 
															  WHEN p_added_by = v_assignee_to THEN
																  'self-assigned the OB Order Manager.'
															  ELSE
																  'assigned the OB Order Manager to "' || v_user_name ||'".'
														  END,
                                in_user_id            => p_added_by,
                                in_created_by         => p_added_by,
                                in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                                in_uploaded_file_name => NULL,
                                in_history_type       => 'Assignee Updated'
                            );
														
							IF upper(COALESCE(v_type, '')) IN ('OB') THEN	
							
								SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = p_added_by AND is_active = true;
								
								IF v_assignee_to != p_added_by THEN
								
									--Push Notification
									CALL notification.add_notification(
										p_type := 'Push',
										p_recipient := v_assignee_to::text,
										p_subject := 'Card Assigned',
										p_message := 'You have been assigned to the card: <b>' || COALESCE(p_company_name, '') || '</b> by <b>' || COALESCE(v_user_name, '') || '<b>.',
										p_retry_count := 0,
										p_max_retries := 3,
										p_message_json := '{
															"ticket_id": '|| p_ticket_id ||',
															"tool_id": 0,
															"tool_ticket_id": 0,
															"board_id": 0,
															"moved_from": "'|| p_added_by::text ||'",
															"moved_to": "'|| v_assignee_to::text ||'",
															"notify_message": "You have been assigned to the card: <b>' || COALESCE(p_company_name, '') || '</b> by <b>' || COALESCE(v_user_name, '') || '<b>.",	
															"is_read": false,
															"type": "ticket_assignee",	
															"workspace_id": 0,
															"header": "Card Assigned"
														   }'::text,
										message := message,
										status := status
									);
								
								END IF;
														
							END IF;
							
							IF upper(COALESCE(v_type, '')) IN ('OB','SA') THEN
								IF v_total_affected_rows > 0 THEN
									message := CASE upper(v_type)
												   WHEN 'OB' THEN 'Onboarding member updated successfully.'
												   WHEN 'SA' THEN 'Sales member updated successfully.'
											   END;
									new_ticket_id := p_ticket_id;
									status := 'true';
									RETURN;
								ELSE
									new_ticket_id := p_ticket_id;
									status := 'true';
									message := 'No member updates performed.';
									RETURN;
								END IF;
							END IF;
						END IF;	
					END IF;	
				END LOOP;
			ELSIF v_key = 'ticketLabels' THEN
				RAISE INFO 'v_key :% , v_value :%', v_key, v_value;
				IF UPPER(v_type) = 'LABEL' THEN
					UPDATE tickets.ticket SET 
						order_label_id = (SELECT array_agg(value::int) FROM jsonb_array_elements_text(v_value)),
						updated_by = p_added_by,
						last_updated_date = current_timestamp AT TIME ZONE 'UTC'
					WHERE 
						ticket_id = p_ticket_id AND 
						is_active = true; 
						GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
                    v_total_affected_rows := v_total_affected_rows + v_affected_rows;
					IF v_affected_rows > 0 THEN
					PERFORM tickets.add_or_update_history_details(
                        in_order_id           => p_ticket_id,
                        in_content            => 'Updated ticket labels',
                        in_user_id            => p_added_by,
                        in_created_by         => p_added_by,
                        in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                        in_uploaded_file_name => NULL,
                        in_history_type       => 'Label Updated'
                    );
					new_ticket_id := p_ticket_id;
					status := 'true';
					message := 'Label updated successfully.';
					RETURN;
					END IF;
				END IF;
			END IF;
		END LOOP;
	ELSE		
		status := 'false';
		message := 'Invalid Input.';
		RETURN;	
	END IF;
	 -- Final status/message
    new_ticket_id := p_ticket_id;
  	status := 'true';
    message := 'Order updated successfully.';
	
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.update_order_ticket',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_company_id,
                p_company_name,
                p_company_code,
                p_industry_sector,
                p_region,
                p_country,
                p_primary_market,
                p_language,
				p_instrument,
				p_website_link,
				p_is_ipo,
				p_ipo_date,
				p_other_data,
				p_headquarters_address,
				p_is_same_address,
				p_ir_address,
				p_contact_form,
				p_is_ipo,
				p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: update_tool_detail(text, integer, integer, integer, boolean, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_tool_detail(IN p_tool_detail text DEFAULT NULL::text, IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_label_id integer DEFAULT 0, IN p_is_assignee boolean DEFAULT false, IN p_is_due_date boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.update_tool_detail
Developer   : Aravindhan.B
Created On  : 09-09-2025
Purpose     : Update tool assignee and due date

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
09-09-2025  Aravindhan.B         Initial creation
19-09-2025	Aravindhan.B         addd column un_assigned_flag 
18-02-2016  Naveen S             Content type create based on tool ticket 
25-08-2026  Mubarak Basha        Log due-date clear (NULL) into tool_duedate_log
*******************************************************************************/
DECLARE
    v_context text;
    v_tool_detail jsonb;
    v_item jsonb;
    v_new_id bigint;
    v_updated_assign boolean := false;
    v_updated_due boolean := false;
	v_user_name TEXT;
	v_company_name TEXT;
	v_notify_message TEXT;
	 v_tool_name text;
	 v_old_assignee uuid;
	 v_old_due_date timestamp;
	 v_rowcount INTEGER := 0;
	 v_tool_ticket_ids INTEGER[] := '{}';
	 v_message character varying;
	 v_refresh jsonb;
	 v_stage_name TEXT;
	 v_board_name TEXT;
	 v_new_assign boolean := false;
	 v_tool_code TEXT;
	 v_content TEXT;
	 v_history_type TEXT;
	 v_new_due_date DATE;
     v_due_reason TEXT;
     v_due_month INT;
     v_due_seq INT;
     v_due_log_id INT;
BEGIN

    -- Safely cast input to jsonb
    IF p_tool_detail IS NOT NULL THEN
        v_tool_detail := p_tool_detail::jsonb;
    ELSE
        status := 'false';
        message := 'Tool detail input is null.';
        RETURN;
    END IF;

	SELECT "Name" INTO v_board_name FROM board.board WHERE "BoardID" = p_board_id AND is_active = true;
	SELECT "Name" INTO v_stage_name FROM board.boardstatus WHERE "LabelID" = p_label_id AND is_active = true;

    FOR v_item IN
        SELECT * FROM jsonb_array_elements(v_tool_detail)
    LOOP  
        -- Check which fields were provided
		
		v_tool_ticket_ids := v_tool_ticket_ids || (v_item->>'toolTicketId')::int;
		 --  Get Tool ID
		SELECT mt."ToolCode"
		INTO v_tool_code
		FROM tickets.tool_detail td
		JOIN master.tool mt
			ON mt."ToolID" = td.tool_id
		WHERE td.tool_ticket_id = (v_item->>'toolTicketId')::int
		LIMIT 1;
		
		 -- Content type create based on tool ticket    //Naveen
            IF v_tool_code = 'EUROLANDTOOL' THEN
                v_content := 'task';
                v_history_type := 'Task';
            ELSE
                v_content := 'tool';
                v_history_type := 'Tool';
            END IF;
		
        IF p_is_assignee THEN            
		  
            -- Insert into tool_assignee			
			IF v_item ? 'assignee' AND (v_item->>'assignee') IS NOT NULL THEN    
				SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
				INTO v_new_id
				FROM tickets.tool_assignee;								
				
				SELECT COUNT(*) = 0 INTO v_new_assign FROM tickets.tool_assignee WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int
						  AND board_id = p_board_id AND label_id = p_label_id 
						  AND is_active = true;				

				INSERT INTO tickets.tool_assignee (
					tool_assignee_id,
					tool_board_logid,
					board_id,
					label_id,
					assignee_to,
					assigned_date,				           
					is_active,
					created_date,
					created_by,
					sequence,
					un_assigned_flag
				)
				VALUES (
					v_new_id,
					(v_item->>'toolBoardLogId')::int,
					p_board_id,
					p_label_id,                
					(v_item->>'assignee')::uuid,
					current_timestamp,				
					true,
					current_timestamp,
					p_added_by::text,
					COALESCE((
						SELECT MAX(sequence) + 1
						FROM tickets.tool_assignee
						WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int
						  AND board_id = p_board_id AND label_id = p_label_id 
						  AND is_active = true					
					), 1),
					false
				);
				
				SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = (v_item->>'assignee')::uuid AND is_active = true;
				
				IF v_new_assign THEN
					 -- History for new assignment
					PERFORM tickets.add_or_update_history_details(
						in_order_id => p_ticket_id,
						in_tool_ticket_id => (v_item->>'toolTicketId')::int,
						in_content => CASE 
										  WHEN p_added_by = (v_item->>'assignee')::uuid THEN
											  'self-assigned the ' || v_content || ' in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
										  ELSE
											  'assigned the ' || v_content ||  '  to "' || v_user_name || '" in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
									  END,
						in_user_id => p_added_by,
						in_created_by => p_added_by,
						in_created_date => current_timestamp AT TIME ZONE 'UTC',
						in_history_type => v_history_type || 'Assignee'
					);
				ELSE 
				 	-- History for re-ssignment
					PERFORM tickets.add_or_update_history_details(
						in_order_id => p_ticket_id,
						in_tool_ticket_id => (v_item->>'toolTicketId')::int,
						in_content => CASE 
										  WHEN p_added_by = (v_item->>'assignee')::uuid THEN
											  'self-reassigned the  ' || v_content || '  in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
										  ELSE
											  're-assigned the ' || v_content ||  '  to "' || v_user_name || '" in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
									  END,
						in_user_id => p_added_by,
						in_created_by => p_added_by,
						in_created_date => current_timestamp AT TIME ZONE 'UTC',
						in_history_type => v_history_type || 'Re Assignee'
					);
				END IF;
			ELSE
			
				SELECT tool_assignee_id INTO v_new_id FROM (
					SELECT tool_assignee_id, un_assigned_flag  
						FROM tickets.tool_assignee 
					WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int 
					AND board_id = p_board_id 
					AND label_id = p_label_id 
					AND is_active 
					order by sequence desc 
					Limit 1
				)x WHERE x.un_assigned_flag = false;
			
				UPDATE tickets.tool_assignee SET 
					un_assigned_flag = true,
					un_assigned_date = current_timestamp AT TIME ZONE 'UTC',
					last_updated_date = current_timestamp AT TIME ZONE 'UTC',
					updated_by = p_added_by
				WHERE tool_assignee_id = v_new_id;
						  
				-- History for new assignment
                PERFORM tickets.add_or_update_history_details(
                    in_order_id => p_ticket_id,
					in_tool_ticket_id => (v_item->>'toolTicketId')::int,
                    in_content => 'un-assigned the ' || v_content || ' in the board "' || v_board_name || '", stage "' || v_stage_name || '".',
                    in_user_id => p_added_by,
                    in_created_by => p_added_by,
                    in_created_date => current_timestamp AT TIME ZONE 'UTC',
                    in_history_type => v_history_type || 'Un Assigneee'
                );
						  
			END IF;
			v_updated_assign := true; 
		END IF;
		 -- Get existing due date (prefer latest log row even when due_date is NULL)
    SELECT due_date
    INTO v_old_due_date
    FROM tickets.tool_duedate_log
    WHERE tool_ticket_id = (v_item->>'toolTicketId')::int
      AND is_active = true
    ORDER BY sequence DESC, tool_duedate_log_id DESC
    LIMIT 1;

    IF NOT FOUND THEN
        SELECT due_date
        INTO v_old_due_date
        FROM tickets.tool_detail
        WHERE tool_ticket_id = (v_item->>'toolTicketId')::int
          AND is_active = true
        LIMIT 1;
    END IF;
		
		IF p_is_due_date THEN

    -- Get new due date from JSON (null / "" clears the due date)
    v_new_due_date := NULLIF(v_item->>'dueDate','')::DATE;
    v_due_reason := v_item->>'dueDateChangeReason';

    -- Always update tool_detail to latest due date (including NULL clear)
    UPDATE tickets.tool_detail
    SET
        due_date = v_new_due_date,
        last_updated_date = current_timestamp AT TIME ZONE 'UTC',
        updated_by = p_added_by
    WHERE tool_ticket_id = (v_item->>'toolTicketId')::int 
      AND is_active = true;

    -- Log every change, including clear-to-NULL (previously skipped by IS NOT NULL)
    IF v_new_due_date IS DISTINCT FROM v_old_due_date::date THEN

        -- Sequence
        SELECT COALESCE(MAX(sequence), 0) + 1
        INTO v_due_seq
        FROM tickets.tool_duedate_log
        WHERE tool_ticket_id = (v_item->>'toolTicketId')::int
          AND is_active = true;

        -- ID
        SELECT COALESCE(MAX(tool_duedate_log_id),0) + 1
        INTO v_due_log_id
        FROM tickets.tool_duedate_log;

        -- Insert (due_date may be NULL when cleared)
        INSERT INTO tickets.tool_duedate_log(
            tool_duedate_log_id,
            tool_ticket_id,
            due_date,
            reason,
            sequence,
            is_active,
            created_date,
            created_by
        )
        VALUES(
            v_due_log_id,
            (v_item->>'toolTicketId')::int,
            v_new_due_date,
            v_due_reason,
            v_due_seq,
            true,
            current_timestamp AT TIME ZONE 'UTC',
            p_added_by
        );

        -- Insert history only when due date actually changed
        PERFORM tickets.add_or_update_history_details(
            in_order_id => p_ticket_id,
            in_tool_ticket_id => (v_item->>'toolTicketId')::int,
            in_content =>
                'Due Date changed from '
                || COALESCE(to_char(v_old_due_date, 'DD-Mon-YYYY'), 'N/A')
                || ' to '
                || COALESCE(to_char(v_new_due_date, 'DD-Mon-YYYY'), 'N/A')
                || CASE
                       WHEN COALESCE(v_due_reason, '') <> ''
                       THEN ' | Reason: ' || v_due_reason
                       ELSE ''
                   END,
            in_user_id => p_added_by,
            in_created_by => p_added_by,
            in_created_date => current_timestamp AT TIME ZONE 'UTC',
            in_history_type => 'Due Date'
        );

        v_updated_due := true;
    END IF;
END IF;
    END LOOP;

    -- Set appropriate message
    IF v_updated_assign AND v_updated_due THEN
        v_message := 'Assignee and Due Date updated successfully.';
		
    ELSIF v_updated_assign THEN
		
		IF p_is_assignee THEN     
			
			SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = p_added_by AND is_active = true;

			SELECT TRIM(name) INTO v_company_name 
			FROM tickets.ticket 
			WHERE ticket_id = p_ticket_id  AND is_active = true;
			
			v_notify_message :=
								CASE
									WHEN jsonb_array_length(v_tool_detail) > 1 THEN
										'You have been assigned <b>' || COALESCE(jsonb_array_length(v_tool_detail)::text, '0') ||
										'</b> ' || v_content ||'(s) for the card: <b>' || COALESCE(v_company_name, '') ||
										'</b> by <b>' || COALESCE(v_user_name, '') || '</b>.'
									ELSE
										'You have been assigned <b>' || COALESCE(jsonb_array_length(v_tool_detail)::text, '0') ||
										'</b> ' || v_content || ' for the card: <b>' || COALESCE(v_company_name, '') ||
										'</b> by <b>' || COALESCE(v_user_name, '') || '</b>.'
								END;
			
			IF (v_tool_detail->0->>'assignee')::uuid != p_added_by THEN
				--Push Notification
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_tool_detail->0->>'assignee'::text,
					p_subject := v_history_type||'s Assigned',
					p_message := v_notify_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := jsonb_build_object(
										'ticket_id',       p_ticket_id,
										'tool_id',         0,
										'tool_ticket_id',  0,
										'board_id',        p_board_id,
										'moved_from',      p_added_by::text,
										'moved_to',        v_tool_detail->0->>'assignee'::text,
										'notify_message',  v_notify_message,
										'is_read',         false,
										'type',            'ticket_assignee',
										'workspace_id',    0,
										'header',          CASE WHEN v_content = 'task' THEN 'Task Assigned' ELSE 'Tools Assigned' END
									)::text,
					message := message,
					status := status
				);	
			END IF;
			
		END IF;
		GET DIAGNOSTICS v_rowcount = ROW_COUNT;
        IF v_rowcount > 0 THEN
        	v_message := 'Assignee updated successfully.';
		END IF;
    ELSIF v_updated_due THEN
        v_message := 'Due Date updated successfully.';
    ELSE
        v_message := 'No changes were made.';
    END IF;    
	
	--Kanban board auto refresh	
	IF v_updated_assign OR v_updated_due THEN

		 v_refresh := jsonb_build_object(
			'tool_ticket_id', v_tool_ticket_ids,
			'ticket_id', p_ticket_id,
			'board_id', p_board_id,
			'from_label_id', 0,
			'to_label_id', p_label_id,
			'type', 'UPDATE',
			'added_by', p_added_by
		);		

		autorefreshreq := (
			COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
		)::text;
	END IF;

	IF v_content = 'task' then
				--Last Updated User Detail
			UPDATE tickets.ticket
			SET
				last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
				updated_by = p_added_by 
			WHERE ticket_id = p_ticket_id;
				 status := 'true';	
	END IF;	
	message := v_message;
	status := 'true';

EXCEPTION
    WHEN OTHERS THEN
		ROLLBACK;
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.update_tool_detail',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_detail, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: update_tool_detail_backup(text, integer, integer, integer, boolean, boolean, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_tool_detail_backup(IN p_tool_detail text DEFAULT NULL::text, IN p_ticket_id integer DEFAULT 0, IN p_board_id integer DEFAULT 0, IN p_label_id integer DEFAULT 0, IN p_is_assignee boolean DEFAULT false, IN p_is_due_date boolean DEFAULT false, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
/******************************************************************************
Procedure   : tickets.update_tool_detail
Developer   : Aravindhan.B
Created On  : 09-09-2025
Purpose     : Update tool assignee and due date

Change Log  :
-------------------------------------------------------------------------------
Date        Developer            Change Description
----------- -------------------- ----------------------------------------------
09-09-2025  Aravindhan.B         Initial creation
19-09-2025	Aravindhan.B         addd column un_assigned_flag 
18-02-2016  Naveen S             Content type create based on tool ticket 
*******************************************************************************/
DECLARE
    v_context text;
    v_tool_detail jsonb;
    v_item jsonb;
    v_new_id bigint;
    v_updated_assign boolean := false;
    v_updated_due boolean := false;
	v_user_name TEXT;
	v_company_name TEXT;
	v_notify_message TEXT;
	 v_tool_name text;
	 v_old_assignee uuid;
	 v_old_due_date timestamp;
	 v_rowcount INTEGER := 0;
	 v_tool_ticket_ids INTEGER[] := '{}';
	 v_message character varying;
	 v_refresh jsonb;
	 v_stage_name TEXT;
	 v_board_name TEXT;
	 v_new_assign boolean := false;
	 v_tool_code TEXT;
	 v_content TEXT;
	 v_history_type TEXT;
BEGIN

    -- Safely cast input to jsonb
    IF p_tool_detail IS NOT NULL THEN
        v_tool_detail := p_tool_detail::jsonb;
    ELSE
        status := 'false';
        message := 'Tool detail input is null.';
        RETURN;
    END IF;

	SELECT "Name" INTO v_board_name FROM board.board WHERE "BoardID" = p_board_id AND is_active = true;
	SELECT "Name" INTO v_stage_name FROM board.boardstatus WHERE "LabelID" = p_label_id AND is_active = true;

    FOR v_item IN
        SELECT * FROM jsonb_array_elements(v_tool_detail)
    LOOP  
		  -- Get previous data for comparison
       --  SELECT td.assignee_to, td.due_date, tm."ToolName"
       --  INTO v_old_assignee, v_old_due_date, v_tool_name
       -- FROM tickets.tool_detail td
       --  LEFT JOIN master.tool tm ON tm."ToolID" = td.tool_id
       --  WHERE td.tool_ticket_id = (v_item->>'toolTicketId')::int
       --    AND td.is_active = true
       --  LIMIT 1;
        -- Check which fields were provided
		
		v_tool_ticket_ids := v_tool_ticket_ids || (v_item->>'toolTicketId')::int;
		 --  Get Tool ID
		SELECT mt."ToolCode"
		INTO v_tool_code
		FROM tickets.tool_detail td
		JOIN master.tool mt
			ON mt."ToolID" = td.tool_id
		WHERE td.tool_ticket_id = (v_item->>'toolTicketId')::int
		LIMIT 1;
		
		 -- Content type create based on tool ticket    //Naveen
            IF v_tool_code = 'EUROLANDTOOL' THEN
                v_content := 'task';
                v_history_type := 'Task';
            ELSE
                v_content := 'tool';
                v_history_type := 'Tool';
            END IF;
		
        IF p_is_assignee THEN            
		  
            -- Insert into tool_assignee			
			IF v_item ? 'assignee' AND (v_item->>'assignee') IS NOT NULL THEN    
				SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
				INTO v_new_id
				FROM tickets.tool_assignee;								
				
				SELECT COUNT(*) = 0 INTO v_new_assign FROM tickets.tool_assignee WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int
						  AND board_id = p_board_id AND label_id = p_label_id 
						  AND is_active = true;				

				INSERT INTO tickets.tool_assignee (
					tool_assignee_id,
					tool_board_logid,
					board_id,
					label_id,
					assignee_to,
					assigned_date,				           
					is_active,
					created_date,
					created_by,
					sequence,
					un_assigned_flag
				)
				VALUES (
					v_new_id,
					(v_item->>'toolBoardLogId')::int,
					p_board_id,
					p_label_id,                
					(v_item->>'assignee')::uuid,
					current_timestamp,				
					true,
					current_timestamp,
					p_added_by::text,
					COALESCE((
						SELECT MAX(sequence) + 1
						FROM tickets.tool_assignee
						WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int
						  AND board_id = p_board_id AND label_id = p_label_id 
						  AND is_active = true					
					), 1),
					false
				);
				
				SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = (v_item->>'assignee')::uuid AND is_active = true;
				
				IF v_new_assign THEN
					 -- History for new assignment
					PERFORM tickets.add_or_update_history_details(
						in_order_id => p_ticket_id,
						in_tool_ticket_id => (v_item->>'toolTicketId')::int,
						in_content => CASE 
										  WHEN p_added_by = (v_item->>'assignee')::uuid THEN
											  'self-assigned the ' || v_content || ' in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
										  ELSE
											  'assigned the ' || v_content ||  '  to "' || v_user_name || '" in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
									  END,
						in_user_id => p_added_by,
						in_created_by => p_added_by,
						in_created_date => current_timestamp AT TIME ZONE 'UTC',
						in_history_type => v_history_type || 'Assignee'
					);
				ELSE 
				 	-- History for re-ssignment
					PERFORM tickets.add_or_update_history_details(
						in_order_id => p_ticket_id,
						in_tool_ticket_id => (v_item->>'toolTicketId')::int,
						in_content => CASE 
										  WHEN p_added_by = (v_item->>'assignee')::uuid THEN
											  'self-reassigned the  ' || v_content || '  in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
										  ELSE
											  're-assigned the ' || v_content ||  '  to "' || v_user_name || '" in the board "' || v_board_name || '", stage "' || v_stage_name || '".'
									  END,
						in_user_id => p_added_by,
						in_created_by => p_added_by,
						in_created_date => current_timestamp AT TIME ZONE 'UTC',
						in_history_type => v_history_type || 'Re Assignee'
					);
				END IF;
			ELSE
			
				SELECT tool_assignee_id INTO v_new_id FROM (
					SELECT tool_assignee_id, un_assigned_flag  
						FROM tickets.tool_assignee 
					WHERE tool_board_logid = (v_item->>'toolBoardLogId')::int 
					AND board_id = p_board_id 
					AND label_id = p_label_id 
					AND is_active 
					order by sequence desc 
					Limit 1
				)x WHERE x.un_assigned_flag = false;
			
				UPDATE tickets.tool_assignee SET 
					un_assigned_flag = true,
					un_assigned_date = current_timestamp AT TIME ZONE 'UTC',
					last_updated_date = current_timestamp AT TIME ZONE 'UTC',
					updated_by = p_added_by
				WHERE tool_assignee_id = v_new_id;
						  
				-- History for new assignment
                PERFORM tickets.add_or_update_history_details(
                    in_order_id => p_ticket_id,
					in_tool_ticket_id => (v_item->>'toolTicketId')::int,
                    in_content => 'un-assigned the ' || v_content || ' in the board "' || v_board_name || '", stage "' || v_stage_name || '".',
                    in_user_id => p_added_by,
                    in_created_by => p_added_by,
                    in_created_date => current_timestamp AT TIME ZONE 'UTC',
                    in_history_type => v_history_type || 'Un Assigneee'
                );
						  
			END IF;
			v_updated_assign := true; 
		END IF;
		
        IF p_is_due_date THEN            
			
			UPDATE tickets.tool_detail
			SET 				
				--due_date = COALESCE((v_item->>'dueDate')::timestamp, due_date),
				due_date = NULLIF(v_item->>'dueDate', '')::timestamp,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = p_added_by
			WHERE tool_ticket_id = (v_item->>'toolTicketId')::int 
			  AND is_active = true;
			   -- Call function for insert history details
            perform tickets.add_or_update_history_details(
                in_order_id => p_ticket_id,
				in_tool_ticket_id => (v_item->>'toolTicketId')::int,
				in_content => 'due date updated to the ' || v_content || ' in ' || v_stage_name,
                in_user_id => p_added_by,
                in_created_by => p_added_by,
                in_created_date => current_timestamp AT TIME ZONE 'UTC',
                in_history_type => 'Due Date'
            );
			  
			 v_updated_due := true;			 
        END IF;
    END LOOP;

    -- Set appropriate message
    IF v_updated_assign AND v_updated_due THEN
        v_message := 'Assignee and Due Date updated successfully.';
		
    ELSIF v_updated_assign THEN
		
		IF p_is_assignee THEN     
			
			SELECT "DisplayName" INTO v_user_name FROM users.registereduser WHERE "RegId" = p_added_by AND is_active = true;

			SELECT TRIM(name) INTO v_company_name 
			FROM tickets.ticket 
			WHERE ticket_id = p_ticket_id  AND is_active = true;
			
			v_notify_message :=
								CASE
									WHEN jsonb_array_length(v_tool_detail) > 1 THEN
										'You have been assigned <b>' || COALESCE(jsonb_array_length(v_tool_detail)::text, '0') ||
										'</b> ' || v_content ||'(s) for the card: <b>' || COALESCE(v_company_name, '') ||
										'</b> by <b>' || COALESCE(v_user_name, '') || '</b>.'
									ELSE
										'You have been assigned <b>' || COALESCE(jsonb_array_length(v_tool_detail)::text, '0') ||
										'</b> ' || v_content || ' for the card: <b>' || COALESCE(v_company_name, '') ||
										'</b> by <b>' || COALESCE(v_user_name, '') || '</b>.'
								END;
			
			IF (v_tool_detail->0->>'assignee')::uuid != p_added_by THEN
				--Push Notification
				CALL notification.add_notification(
					p_type := 'Push',
					p_recipient := v_tool_detail->0->>'assignee'::text,
					p_subject := v_history_type||'s Assigned',
					p_message := v_notify_message,
					p_retry_count := 0,
					p_max_retries := 3,
					p_message_json := jsonb_build_object(
										'ticket_id',       p_ticket_id,
										'tool_id',         0,
										'tool_ticket_id',  0,
										'board_id',        p_board_id,
										'moved_from',      p_added_by::text,
										'moved_to',        v_tool_detail->0->>'assignee'::text,
										'notify_message',  v_notify_message,
										'is_read',         false,
										'type',            'ticket_assignee',
										'workspace_id',    0,
										'header',          CASE WHEN v_content = 'task' THEN 'Task Assigned' ELSE 'Tools Assigned' END
									)::text,
					message := message,
					status := status
				);	
			END IF;
			 -- Call function for insert history details
--             perform tickets.add_or_update_history_details(
--                 in_order_id => p_ticket_id,
--                 in_content => 'Tool Assignee Updated',
--                 in_user_id => p_added_by,
--                 in_created_by => p_added_by,
--                 in_created_date => current_timestamp AT TIME ZONE 'UTC',
--                 in_history_type => 'Tool Assignee'
--             );
			
		END IF;
		GET DIAGNOSTICS v_rowcount = ROW_COUNT;
        IF v_rowcount > 0 THEN
        	v_message := 'Assignee updated successfully.';
		END IF;
    ELSIF v_updated_due THEN
        v_message := 'Due Date updated successfully.';
    ELSE
        v_message := 'No changes were made.';
    END IF;    
	
	--Kanban board auto refresh	
	IF v_updated_assign OR v_updated_due THEN
-- 		CALL tickets.main_sub_board_refresh(
-- 			v_tool_ticket_ids,
-- 			p_ticket_id,
-- 			p_board_id,
-- 			0,
-- 			p_label_id,
-- 			'UPDATE',
-- 			p_added_by,
-- 			message := message,
-- 			status := status
-- 		);	
		 v_refresh := jsonb_build_object(
			'tool_ticket_id', v_tool_ticket_ids,
			'ticket_id', p_ticket_id,
			'board_id', p_board_id,
			'from_label_id', 0,
			'to_label_id', p_label_id,
			'type', 'UPDATE',
			'added_by', p_added_by
		);		

		autorefreshreq := (
			COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
		)::text;
	END IF;

	IF v_content = 'task' then
				--Last Updated User Detail
			UPDATE tickets.ticket
			SET
				last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
				updated_by = p_added_by 
			WHERE ticket_id = p_ticket_id;
				 status := 'true';	
	END IF;	
	message := v_message;
	status := 'true';

EXCEPTION
    WHEN OTHERS THEN
		ROLLBACK;
        GET STACKED DIAGNOSTICS 
            v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.update_tool_detail',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_tool_detail, p_added_by))::text
        );

        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: update_tool_detail_positions(text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_tool_detail_positions(IN p_positions text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_positions jsonb;
	v_ticket_id bigint;
	v_item_count integer := 0;
	v_missing_ids text;
	v_context text;
BEGIN
	BEGIN
		v_positions := NULLIF(TRIM(p_positions), '')::jsonb;
	EXCEPTION
		WHEN OTHERS THEN
			status := 'false';
			message := 'Invalid positions JSON.';
			RETURN;
	END;

	IF v_positions IS NULL OR jsonb_typeof(v_positions) <> 'array' OR jsonb_array_length(v_positions) = 0 THEN
		status := 'false';
		message := 'At least one tool / subtask position is required.';
		RETURN;
	END IF;

	SELECT COUNT(*)
	INTO v_item_count
	FROM jsonb_array_elements(v_positions) elem
	WHERE COALESCE(NULLIF(elem->>'toolTicketId', ''), NULLIF(elem->>'tool_ticket_id', '')) IS NOT NULL
	  AND COALESCE(
			NULLIF(elem->>'position', '')::integer,
			NULLIF(elem->>'postion', '')::integer
		) IS NOT NULL;

	IF v_item_count = 0 THEN
		status := 'false';
		message := 'Each item must include toolTicketId and position.';
		RETURN;
	END IF;

	IF EXISTS (
		SELECT 1
		FROM jsonb_array_elements(v_positions) elem
		WHERE COALESCE(
			NULLIF(elem->>'ticketId', '')::bigint,
			NULLIF(elem->>'ticket_id', '')::bigint
		) IS NULL
	) THEN
		status := 'false';
		message := 'ticketId is required for each item.';
		RETURN;
	END IF;

	SELECT DISTINCT COALESCE(
		NULLIF(elem->>'ticketId', '')::bigint,
		NULLIF(elem->>'ticket_id', '')::bigint
	)
	INTO v_ticket_id
	FROM jsonb_array_elements(v_positions) elem;

	IF (
		SELECT COUNT(DISTINCT COALESCE(
			NULLIF(elem->>'ticketId', '')::bigint,
			NULLIF(elem->>'ticket_id', '')::bigint
		))
		FROM jsonb_array_elements(v_positions) elem
	) > 1 THEN
		status := 'false';
		message := 'All items must belong to the same ticket.';
		RETURN;
	END IF;

	IF (
		SELECT COUNT(*)
		FROM jsonb_array_elements(v_positions) elem
	) <> (
		SELECT COUNT(DISTINCT COALESCE(
			NULLIF(elem->>'toolTicketId', '')::integer,
			NULLIF(elem->>'tool_ticket_id', '')::integer
		))
		FROM jsonb_array_elements(v_positions) elem
	) THEN
		status := 'false';
		message := 'Duplicate toolTicketId is not allowed.';
		RETURN;
	END IF;

	IF (
		SELECT COUNT(*)
		FROM jsonb_array_elements(v_positions) elem
	) <> (
		SELECT COUNT(DISTINCT COALESCE(
			NULLIF(elem->>'position', '')::integer,
			NULLIF(elem->>'postion', '')::integer
		))
		FROM jsonb_array_elements(v_positions) elem
	) THEN
		status := 'false';
		message := 'Duplicate position is not allowed.';
		RETURN;
	END IF;

	SELECT string_agg(input_rows.tool_ticket_id::text, ', ' ORDER BY input_rows.tool_ticket_id)
	INTO v_missing_ids
	FROM (
		SELECT COALESCE(
			NULLIF(elem->>'toolTicketId', '')::integer,
			NULLIF(elem->>'tool_ticket_id', '')::integer
		) AS tool_ticket_id
		FROM jsonb_array_elements(v_positions) elem
	) input_rows
	LEFT JOIN tickets.tool_detail td
		ON td.tool_ticket_id = input_rows.tool_ticket_id
	   AND td.ticket_id = v_ticket_id
	WHERE input_rows.tool_ticket_id IS NULL
	   OR td.tool_ticket_id IS NULL;

	IF v_missing_ids IS NOT NULL THEN
		status := 'false';
		message := CONCAT('Tool / subtask not found: ', v_missing_ids, '.');
		RETURN;
	END IF;

	UPDATE tickets.tool_detail td
	SET position = input_rows.new_position,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	FROM (
		SELECT
			COALESCE(
				NULLIF(elem->>'toolTicketId', '')::integer,
				NULLIF(elem->>'tool_ticket_id', '')::integer
			) AS tool_ticket_id,
			COALESCE(
				NULLIF(elem->>'position', '')::integer,
				NULLIF(elem->>'postion', '')::integer
			) AS new_position
		FROM jsonb_array_elements(v_positions) elem
	) input_rows
	WHERE td.tool_ticket_id = input_rows.tool_ticket_id
	  AND td.ticket_id = v_ticket_id
	  AND input_rows.new_position IS NOT NULL
	  AND input_rows.new_position > 0;

	WITH ranked AS (
		SELECT
			tool_ticket_id,
			ROW_NUMBER() OVER (ORDER BY COALESCE(position, tool_ticket_id), tool_ticket_id) AS rn
		FROM tickets.tool_detail
		WHERE ticket_id = v_ticket_id
	)
	UPDATE tickets.tool_detail td
	SET position = ranked.rn,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	FROM ranked
	WHERE td.tool_ticket_id = ranked.tool_ticket_id
	  AND td.position IS DISTINCT FROM ranked.rn;

	status := 'true';
	message := 'Tool / subtask position updated successfully.';

EXCEPTION
	WHEN OTHERS THEN
		GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
		CALL master.procedure_log_exception(
			'tickets.update_tool_detail_positions',
			CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
			NULL,
			current_timestamp AT TIME ZONE 'UTC',
			COALESCE(p_positions, 'null')
		);
		status := 'false';
		message := SQLERRM;
END;
$$;


--
-- Name: update_tool_notes(bigint, integer, text, uuid, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.update_tool_notes(IN p_tool_ticket_id bigint DEFAULT 0, IN p_tool_id integer DEFAULT NULL::integer, IN p_notes text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE    
	v_context text;
	 v_old_notes text;
BEGIN
    SELECT tool_notes
    INTO v_old_notes
    FROM tickets.tool_detail
    WHERE tool_ticket_id = p_tool_ticket_id;
	
	UPDATE tickets.tool_detail SET 
		tool_notes = p_notes,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	WHERE tool_ticket_id = p_tool_ticket_id;
	
  	IF v_old_notes IS NULL THEN
        message := 'Notes Added successfully.';
    ELSE
        message := 'Notes Updated successfully.';
    END IF;

    status := 'true';
	
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.update_tool_notes',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_tool_ticket_id,
                p_tool_id,
                p_notes,
                p_company_code,
                p_added_by               
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: upsert_branding_guideline_notes(bigint, text, text); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_branding_guideline_notes(IN p_ticket_id bigint, IN p_guideline_notes text, IN p_created_by text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_notes_id bigint;
    v_context text;
BEGIN

    -- validate
    IF p_ticket_id IS NULL OR p_ticket_id = 0 THEN
        RETURN;
    END IF;

    -- check existing
    SELECT notes_id
    INTO v_notes_id
    FROM tickets.ticket_customer_branding_notes
    WHERE ticket_id = p_ticket_id
      AND is_active = true
    LIMIT 1;

    -- UPDATE
    IF v_notes_id IS NOT NULL THEN

        UPDATE tickets.ticket_customer_branding_notes
        SET guideline_notes   = p_guideline_notes,
            is_active         = true,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC',
			 updated_by = p_created_by
        WHERE notes_id = v_notes_id;

    ELSE
        -- INSERT
        INSERT INTO tickets.ticket_customer_branding_notes (
            ticket_id,
            guideline_notes,
            is_active,
            created_date,
            created_by
        )
        VALUES (
            p_ticket_id,
            p_guideline_notes,
            true,
            current_timestamp AT TIME ZONE 'UTC',
            p_created_by
        );

    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.upsert_branding_guideline_notes',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(p_ticket_id, p_guideline_notes,p_created_by))::text
        );

        RETURN;
END;
$$;


--
-- Name: upsert_order_details(bigint, timestamp without time zone, timestamp without time zone, integer[], integer, integer[], integer, text, integer[], integer[], uuid, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_order_details(IN p_ticket_id bigint DEFAULT 0, IN p_order_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_delivery_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_orderval_currency integer[] DEFAULT NULL::integer[], IN p_order_val integer DEFAULT NULL::integer, IN p_start_up_fee_currency integer[] DEFAULT NULL::integer[], IN p_start_up_fee integer DEFAULT NULL::integer, IN p_tools_details text DEFAULT NULL::text, IN p_language integer[] DEFAULT NULL::integer[], IN p_currency integer[] DEFAULT NULL::integer[], IN p_added_by uuid DEFAULT NULL::uuid, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE    
    v_company_id INTEGER := 0;	
	v_tools_json JSONB := COALESCE(p_tools_details::jsonb, '[]'::jsonb);
	v_tool_element JSONB;
	v_tool_id INTEGER;
	v_package INTEGER := 0;
	v_order_type INTEGER := 0;
	v_tools_ids INTEGER[];
	v_context text;
	v_ob_boardid INTEGER := 0;
    v_ob_labelid INTEGER := 0;
    v_tool_statusid INTEGER := 0;
    v_dep_code TEXT;
	V_tool_ticket_exist int := 0;
	V_pre_tool_ticket_id int := 0;
	V_pre_subscription_type_id int := 0;
	v_flow_id INT;
	v_ticket_company_id INTEGER := 0;
    v_rowcount INTEGER := 0;
BEGIN
	
	--Created by Aravindhan Baskaran
	
-- CALL tickets.upsert_order_detailssyed(
--   p_ticket_id             => 11,
--   p_order_date            => '2025-11-12 05:24:27.51324',
--   p_delivery_date         => '2025-11-16 05:24:27.51324',
--   p_orderval_currency     => ARRAY[19], -- correct array format
--   p_order_val             => 20,
--   p_start_up_fee_currency => ARRAY[19], -- correct array format
--   p_start_up_fee          => 20,
--   p_tools_details         => '[{"Package":[29],"OrderType":[15],"ToolsId":[24]}]', -- fixed closing quote
--   p_added_by              => '2e1f5081-4a9d-4f9b-b1c3-8510b3b66e10'::uuid,
--   p_language              =Array[10],
 --     p_currency              =Array[5],
--   new_ticket_id           => NULL,
--   message                 => NULL,
--   status                  => NULL
-- );

	--ticket id validation
	IF p_ticket_id = 0 THEN
		message := 'Invalid ticket.';
        status := 'false';
        RETURN;		
	END IF;	 	
	
	SELECT "BoardID" INTO v_ob_boardid 
	FROM board.board 
	WHERE "Name" = 'ON BOARDING' AND is_active= true;

	SELECT "LabelID" INTO v_ob_labelid 
	FROM board.boardstatus 
	WHERE "BoardID" = v_ob_boardid AND "Name" = 'Open' AND is_active= true;

	SELECT "DeptCode" INTO v_dep_code 
	FROM master.department 
	WHERE is_active= true AND upper("Name") = 'ON BOARDING';  

	SELECT status_id INTO v_tool_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND type = 'Tool' AND name = 'Open';
		
	-- Loop through each element in tools_details JSONB array
    FOR v_tool_element IN SELECT * FROM jsonb_array_elements(v_tools_json)
    LOOP
        -- Extract fields
--         v_package  := v_tool_element ->> 'Package';
--         v_order_type := v_tool_element ->> 'OrderType';
		
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(v_tool_element -> 'Package') LIMIT 1),
			NULL
		) INTO v_package;
		 -- Map it to the ID from master.status_code_master where type = 'PACKAGE'
-- 		 SELECT status_id INTO v_package
--           FROM master.status_code_master
--           WHERE status_id = v_package AND type = 'PACKAGE' AND is_active = true
--           LIMIT 1;
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(v_tool_element -> 'OrderType') LIMIT 1),
			NULL
		) INTO v_order_type;
		
		v_tools_ids   := ARRAY(
			SELECT jsonb_array_elements_text(v_tool_element -> 'ToolsId')::INTEGER
		);  
		
		--Remove Tools
		DELETE FROM 
			tickets.tool_detail			 
		WHERE 
			ticket_id = p_ticket_id AND 
			order_type_id = v_order_type AND 
			is_active = true AND 
			tool_id NOT IN(SELECT UNNEST(v_tools_ids));
-- 		UPDATE tickets.tool_detail SET 
-- 			is_active = false 
-- 		WHERE 
-- 			ticket_id = p_ticket_id AND 
-- 			order_type_id = v_order_type AND 
-- 			is_active = true AND 
-- 			tool_id NOT IN(SELECT UNNEST(v_tools_ids));
		
		 -- Loop through each tool ID
		FOREACH v_tool_id IN ARRAY v_tools_ids
		LOOP			
			--Check exists
			SELECT count(*) INTO V_tool_ticket_exist
			FROM tickets.tool_detail WHERE ticket_id = p_ticket_id AND 
			order_type_id = v_order_type AND is_active = true AND tool_id = v_tool_id;
			
			--Get tool ticket id and subscription type id.
			IF V_tool_ticket_exist > 0 THEN
				SELECT tool_ticket_id, subscription_type_id
				INTO V_pre_tool_ticket_id, V_pre_subscription_type_id
				FROM tickets.tool_detail 
				WHERE ticket_id = p_ticket_id 
				  AND order_type_id = v_order_type 
				  AND tool_id = v_tool_id
				  AND is_active = true
				LIMIT 1;
			END IF;
		
			IF V_tool_ticket_exist = 0 THEN
				
				SELECT flow_id
				INTO v_flow_id
				FROM board.tool_flow
				WHERE is_active = true
				  AND tool_id = v_tool_id
				LIMIT 1;				
				
				IF v_flow_id IS NULL THEN
					message := format('This tool''s is not linked in any flow.');
					status := 'false';
					RETURN;
				END IF;
				
				INSERT INTO tickets.tool_detail (
					ticket_id, subscription_type_id, tool_id, board_id, label_id,
					added_by, assign_to, status, status_id, dept_code,
					is_active, created_date, created_by, order_type_id, flow_id, position
				) VALUES (
					p_ticket_id, v_package, v_tool_id, NULL, NULL, 
					p_added_by, null, 'Open', v_tool_statusid, v_dep_code,
					true, current_timestamp AT TIME ZONE 'UTC', p_added_by, v_order_type, v_flow_id,
					(
						SELECT COALESCE(MAX(td.position), 0) + 1
						FROM tickets.tool_detail td
						WHERE td.ticket_id = p_ticket_id
						  AND td.is_active = true
					)
				);
				
				RAISE INFO 'tool detail table added successfully.';
				
			ELSIF V_tool_ticket_exist > 0 
					--AND v_package IS NOT NULL AND v_package > 0 AND V_pre_subscription_type_id > 0 
					--AND V_pre_subscription_type_id <> v_package
					AND V_pre_subscription_type_id IS DISTINCT FROM v_package 
			THEN
				UPDATE tickets.tool_detail SET 
					subscription_type_id = v_package,
					last_updated_date = current_timestamp AT TIME ZONE 'UTC',
					updated_by = p_added_by
				WHERE tool_ticket_id = V_pre_tool_ticket_id;
				RAISE INFO 'tool detail table updated successfully. %', v_package;
			END IF;
		END LOOP;
        
    END LOOP;
	
	-- Get Previous customer ID
	SELECT ticket_company_id INTO v_ticket_company_id
	FROM tickets.ticket_company
	WHERE ticket_id = p_ticket_id AND is_active = true LIMIT 1;
		
	--Update ticket data
	UPDATE tickets.ticket SET 
		order_date = p_order_date, 
		last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
		updated_by = p_added_by, 
		expected_delivery_date = p_delivery_date, 
		order_value = p_order_val, 
		order_value_type = p_orderval_currency, 
		start_up_fee = p_start_up_fee, 
		start_up_fee_type = p_start_up_fee_currency
	WHERE ticket_id = p_ticket_id AND is_active = true;
	
	UPDATE tickets.ticket_company SET 
		language_id = p_language,	
		currency_id = p_currency,
		updated_by = p_added_by,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	WHERE 
		ticket_company_id = v_ticket_company_id AND is_active = true;

   ---History: Tool details Updated
				PERFORM tickets.add_or_update_history_details(
                    in_order_id           => p_ticket_id,
                    in_content            => CONCAT('Order Details Updated'
                                               -- 'Added tool ID ', v_tool_id,
                                                --' (subscription ', COALESCE(v_package::text, 'NULL'),
                                               -- ') for OrderType ', COALESCE(v_order_type::text, 'NULL')
                                            ),
                    in_user_id            => p_added_by,
                    in_created_by         => p_added_by,
                    in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                    in_uploaded_file_name => NULL,
                    in_history_type       => 'Tool Details Updated'
                );
	new_ticket_id := p_ticket_id;
	   GET DIAGNOSTICS v_rowcount = ROW_COUNT;

		IF v_rowcount > 0 THEN
		    status := 'true';
		    message := 'Order details have been updated successfully.';
		ELSE
		    status := 'false';
		    message := 'Order details have been updated failed.';
		END IF;
			
			
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.upsert_order_details',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_order_date,
                p_delivery_date,
                p_orderval_currency,
                p_order_val,
                p_start_up_fee_currency,
                p_start_up_fee,
                p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
	
END;
$$;


--
-- Name: upsert_order_details_1(bigint, timestamp without time zone, timestamp without time zone, integer[], integer, integer[], integer, text, uuid, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_order_details_1(IN p_ticket_id bigint DEFAULT 0, IN p_order_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_delivery_date timestamp without time zone DEFAULT NULL::timestamp without time zone, IN p_orderval_currency integer[] DEFAULT NULL::integer[], IN p_order_val integer DEFAULT NULL::integer, IN p_start_up_fee_currency integer[] DEFAULT NULL::integer[], IN p_start_up_fee integer DEFAULT NULL::integer, IN p_tools_details text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE    
    v_company_id INTEGER := 0;	
	v_tools_json JSONB := COALESCE(p_tools_details::jsonb, '[]'::jsonb);
	v_tool_element JSONB;
	v_tool_id INTEGER;
	v_package INTEGER := 0;
	v_order_type INTEGER := 0;
	v_tools_ids INTEGER[];
	v_context text;
	v_ob_boardid INTEGER := 0;
    v_ob_labelid INTEGER := 0;
    v_tool_statusid INTEGER := 0;
    v_dep_code TEXT;
	V_tool_ticket_exist int := 0;
	V_pre_tool_ticket_id int := 0;
	V_pre_subscription_type_id int := 0;
	v_flow_id INT;
BEGIN

-- 	START
--   │
--   ├─► Validate ticket_id
--   │     ├─ 0 → Exit with error
--   │     └─ valid → continue
--   │
--   ├─► Fetch base config (BoardID, LabelID, DeptCode, ToolStatusID)
--   │
--   ├─► Parse JSON p_tools_details[]
--   │     └─ For each tool group:
--   │           ├─ Extract package, orderType, toolIds
--   │           ├─ Delete tools not in new list
--   │           └─ For each toolId:
--   │                ├─ Check exists in tool_detail
--   │                │     ├─ No → Insert new record
--   │                │     └─ Yes but package changed → Update
--   │
--   ├─► Update ticket order info
--   │
--   ├─► Add order history record
--   │
--   ├─► Return success (true, message)
--   │
--   └─► [EXCEPTION] → Rollback, log error, return failure
-- END

	--Created by Aravindhan Baskaran
	
-- CALL tickets.upsert_order_details(
--   p_ticket_id             => 637,
--   p_order_date            => '2025-07-31 00:00:00',
--   p_delivery_date         => '2025-07-31 00:00:00',
--   p_orderval_currency     => ARRAY[19], -- correct array format
--   p_order_val             => 20,
--   p_start_up_fee_currency => ARRAY[19], -- correct array format
--   p_start_up_fee          => 20,
--   p_tools_details         => '[{"Package":[31],"OrderType":[15],"ToolsId":[9]}]', -- fixed closing quote
--   p_added_by              => '2e1f5081-4a9d-4f9b-b1c3-8510b3b66e10'::uuid,
--   new_ticket_id           => NULL,
--   message                 => NULL,
--   status                  => NULL
-- );

	--ticket id validation
	IF p_ticket_id = 0 THEN
		message := 'Invalid ticket.';
        status := 'false';
        RETURN;		
	END IF;	 	
	
	SELECT "BoardID" INTO v_ob_boardid 
	FROM board.board 
	WHERE "Name" = 'ON BOARDING' AND is_active= true;

	SELECT "LabelID" INTO v_ob_labelid 
	FROM board.boardstatus 
	WHERE "BoardID" = v_ob_boardid AND "Name" = 'Open' AND is_active= true;

	SELECT "DeptCode" INTO v_dep_code 
	FROM master.department 
	WHERE is_active= true AND "Name" = 'ON BOARDING';

	SELECT status_id INTO v_tool_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND type = 'Tool' AND name = 'Open';
		
	-- Loop through each element in tools_details JSONB array
    FOR v_tool_element IN SELECT * FROM jsonb_array_elements(v_tools_json)
    LOOP
        -- Extract fields
--         v_package  := v_tool_element ->> 'Package';
--         v_order_type := v_tool_element ->> 'OrderType';
		
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(v_tool_element -> 'Package') LIMIT 1),
			NULL
		) INTO v_package;
		 -- Map it to the ID from master.status_code_master where type = 'PACKAGE'
-- 		 SELECT status_id INTO v_package
--           FROM master.status_code_master
--           WHERE status_id = v_package AND type = 'PACKAGE' AND is_active = true
--           LIMIT 1;
		SELECT COALESCE(
			(SELECT value::text::int FROM jsonb_array_elements(v_tool_element -> 'OrderType') LIMIT 1),
			NULL
		) INTO v_order_type;
		
		v_tools_ids   := ARRAY(
			SELECT jsonb_array_elements_text(v_tool_element -> 'ToolsId')::INTEGER
		);  
		
		--Remove Tools
		DELETE FROM 
			tickets.tool_detail			 
		WHERE 
			ticket_id = p_ticket_id AND 
			order_type_id = v_order_type AND 
			is_active = true AND 
			tool_id NOT IN(SELECT UNNEST(v_tools_ids));
-- 		UPDATE tickets.tool_detail SET 
-- 			is_active = false 
-- 		WHERE 
-- 			ticket_id = p_ticket_id AND 
-- 			order_type_id = v_order_type AND 
-- 			is_active = true AND 
-- 			tool_id NOT IN(SELECT UNNEST(v_tools_ids));
		
		 -- Loop through each tool ID
		FOREACH v_tool_id IN ARRAY v_tools_ids
		LOOP			
			--Check exists
			SELECT count(*) INTO V_tool_ticket_exist
			FROM tickets.tool_detail WHERE ticket_id = p_ticket_id AND 
			order_type_id = v_order_type AND is_active = true AND tool_id = v_tool_id;
			
			--Get tool ticket id and subscription type id.
			IF V_tool_ticket_exist > 0 THEN
				SELECT tool_ticket_id, subscription_type_id
				INTO V_pre_tool_ticket_id, V_pre_subscription_type_id
				FROM tickets.tool_detail 
				WHERE ticket_id = p_ticket_id 
				  AND order_type_id = v_order_type 
				  AND tool_id = v_tool_id
				  AND is_active = true
				LIMIT 1;
			END IF;
		
			IF V_tool_ticket_exist = 0 THEN
				
				SELECT flow_id
				INTO v_flow_id
				FROM board.tool_flow
				WHERE is_active = true
				  AND tool_id = v_tool_id
				LIMIT 1;				
				
				IF v_flow_id IS NULL THEN
					message := format('This tool''s is not linked in any flow.');
					status := 'false';
					RETURN;
				END IF;
				
				INSERT INTO tickets.tool_detail (
					ticket_id, subscription_type_id, tool_id, board_id, label_id,
					added_by, assign_to, status, status_id, dept_code,
					is_active, created_date, created_by, order_type_id, flow_id
				) VALUES (
					p_ticket_id, v_package, v_tool_id, NULL, NULL, 
					p_added_by, null, 'Open', v_tool_statusid, v_dep_code,
					true, current_timestamp AT TIME ZONE 'UTC', p_added_by, v_order_type, v_flow_id
				);
				
				RAISE INFO 'tool detail table added successfully.';
				
			ELSIF V_tool_ticket_exist > 0 
					--AND v_package IS NOT NULL AND v_package > 0 AND V_pre_subscription_type_id > 0 
					--AND V_pre_subscription_type_id <> v_package
					AND V_pre_subscription_type_id IS DISTINCT FROM v_package 
			THEN
				UPDATE tickets.tool_detail SET 
					subscription_type_id = v_package,
					last_updated_date = current_timestamp AT TIME ZONE 'UTC',
					updated_by = p_added_by
				WHERE tool_ticket_id = V_pre_tool_ticket_id;
				RAISE INFO 'tool detail table updated successfully. %', v_package;
			END IF;
		END LOOP;
        
    END LOOP;
	
	--Update ticket data
	UPDATE tickets.ticket SET 
		order_date = p_order_date, 
		last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
		updated_by = p_added_by, 
		expected_delivery_date = p_delivery_date, 
		order_value = p_order_val, 
		order_value_type = p_orderval_currency, 
		start_up_fee = p_start_up_fee, 
		start_up_fee_type = p_start_up_fee_currency
	WHERE ticket_id = p_ticket_id AND is_active = true;
   ---History: Tool details Updated
				PERFORM tickets.add_or_update_history_details(
                    in_order_id           => p_ticket_id,
                    in_content            => CONCAT('Order Details Updated'
                                               -- 'Added tool ID ', v_tool_id,
                                                --' (subscription ', COALESCE(v_package::text, 'NULL'),
                                               -- ') for OrderType ', COALESCE(v_order_type::text, 'NULL')
                                            ),
                    in_user_id            => p_added_by,
                    in_created_by         => p_added_by,
                    in_created_date       => current_timestamp AT TIME ZONE 'UTC',
                    in_uploaded_file_name => NULL,
                    in_history_type       => 'Tool Details Updated'
                );
	new_ticket_id := p_ticket_id;
  	status := 'true';
    message := 'Order details have been updated successfully.';
	
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.upsert_order_details',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id,
                p_order_date,
                p_delivery_date,
                p_orderval_currency,
                p_order_val,
                p_start_up_fee_currency,
                p_start_up_fee,
                p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
	
END;
$$;


--
-- Name: upsert_order_ticket(bigint, integer[], integer[], integer, text, text, boolean, boolean, integer[], text, uuid, integer[], integer[], integer[], text, text, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_order_ticket(IN p_ticket_id bigint DEFAULT 0, IN p_order_type integer[] DEFAULT NULL::integer[], IN p_order_category integer[] DEFAULT NULL::integer[], IN p_company_id integer DEFAULT NULL::integer, IN p_company_name text DEFAULT NULL::text, IN p_company_code text DEFAULT NULL::text, IN p_isnew_customer boolean DEFAULT false, IN p_is_ipo boolean DEFAULT false, IN p_primary_market integer[] DEFAULT NULL::integer[], IN p_flag text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, IN p_redesigncategory integer[] DEFAULT NULL::integer[], IN p_upsellcategory integer[] DEFAULT NULL::integer[], IN p_industry_sector integer[] DEFAULT NULL::integer[], IN p_toolcenterlink text DEFAULT NULL::text, IN p_primary_market_name text DEFAULT NULL::text, IN p_isin text DEFAULT NULL::text, IN p_symbol text DEFAULT NULL::text, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_company_id INTEGER;
    v_company_name_db TEXT;
    v_company_code_db TEXT;
    v_order_status_id INTEGER;
    v_sequence_number INTEGER := 0;
    v_generated_order_id TEXT;
    v_worklog_message TEXT := '';
    v_subscription_typeid INTEGER;
    v_dep_code TEXT;
	v_tool_statusid INTEGER := 0;
    v_record_tool RECORD;
    v_flow_id INT;
    v_recipient TEXT;
    v_subject TEXT;
    v_message JSONB;
    v_email TEXT;	
	new_type_id  INTEGER;
    plg_type_id  INTEGER;
    upsell_type_id INTEGER;	
	redesign_type_id INTEGER;
	v_first_order_type INTEGER;
	v_prev_newtype_ticket_id INT;
	v_rowcount INTEGER := 0;
	v_context text;
BEGIN

	    -- Validate flag
    IF p_flag NOT IN ('insert', 'update') THEN
        message := 'Invalid flag value';
        status := 'false';
        RETURN;
    END IF;

    -- Validate order_type
    IF p_order_type IS NULL OR array_length(p_order_type, 1) = 0 THEN
        message := 'Order type cannot be null or empty';
        status := 'false';
        RETURN;
    END IF;

    -- Set first order type
    v_first_order_type := p_order_type[1];   
	
	SELECT status_id INTO new_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'NC';
    
    SELECT status_id INTO plg_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'PLG';
    
    SELECT status_id INTO upsell_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'UP';
    
    SELECT status_id INTO redesign_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'RD';
	
	
    -- Resolve / create company
    -- Lookup order: ticket customer (update) -> customer_id -> customer_ref_id -> customer_code -> company_name

    IF p_flag = 'update' AND COALESCE(p_ticket_id, 0) > 0 THEN
        SELECT t.customer_id, c.company_name, c.customer_code
        INTO v_company_id, v_company_name_db, v_company_code_db
        FROM tickets.ticket t
        LEFT JOIN customers.customer c ON c.customer_id = t.customer_id AND c.is_active = TRUE
        WHERE t.ticket_id = p_ticket_id AND t.is_active = TRUE
        LIMIT 1;

        IF v_company_id IS NULL THEN
            message := 'Ticket not found or inactive';
            status := 'false';
            RETURN;
        END IF;
    END IF;

    IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
        -- UI companyId is customers.customer.customer_id
        SELECT customer_id, company_name, customer_code
        INTO v_company_id, v_company_name_db, v_company_code_db
        FROM customers.customer
        WHERE customer_id = p_company_id AND is_active = TRUE
        LIMIT 1;
    END IF;

    IF v_company_id IS NULL AND p_company_id IS NOT NULL AND p_company_id > 0 THEN
        -- AddOrderTicket passes Europe-mapped id as customer_ref_id
        SELECT customer_id, company_name, customer_code
        INTO v_company_id, v_company_name_db, v_company_code_db
        FROM customers.customer
        WHERE customer_ref_id = p_company_id AND is_active = TRUE
        LIMIT 1;
    END IF;

    IF v_company_id IS NULL AND NULLIF(TRIM(p_company_code), '') IS NOT NULL THEN
        SELECT customer_id, company_name, customer_code
        INTO v_company_id, v_company_name_db, v_company_code_db
        FROM customers.customer
        WHERE LOWER(TRIM(customer_code)) = LOWER(TRIM(p_company_code)) AND is_active = TRUE
        LIMIT 1;
    END IF;

    IF v_company_id IS NULL AND NULLIF(TRIM(p_company_name), '') IS NOT NULL THEN
        SELECT customer_id, company_name, customer_code
        INTO v_company_id, v_company_name_db, v_company_code_db
        FROM customers.customer
        WHERE LOWER(TRIM(company_name)) = LOWER(TRIM(p_company_name)) AND is_active = TRUE
        LIMIT 1;
    END IF;

    IF v_company_id IS NULL THEN
        IF p_flag = 'update' THEN
            message := 'Company not found for update';
            status := 'false';
            RETURN;
        END IF;

        INSERT INTO customers.customer (
		   customer_ref_id,
            company_name,
            customer_code,
            is_active,
            created_by,
            created_date,
            tool_center_link
        )
        VALUES (
		    NULLIF(p_company_id, 0),
            p_company_name,
            p_company_code,
            TRUE,
            p_added_by,
            current_timestamp AT TIME ZONE 'UTC',
            p_toolcenterlink
        )
        RETURNING customer_id INTO v_company_id;

        RAISE NOTICE ' New customer created: %, ID: %', p_company_name, v_company_id;
    ELSE
        RAISE NOTICE 'ℹ️ Existing customer found: %, ID: %', v_company_name_db, v_company_id;

        -- Update company name and related details
        UPDATE customers.customer
        SET
            company_name = COALESCE(NULLIF(TRIM(p_company_name), ''), company_name),
            customer_code = COALESCE(NULLIF(TRIM(p_company_code), ''), customer_code),
            tool_center_link = COALESCE(NULLIF(TRIM(p_toolcenterlink), ''), tool_center_link),
            customer_ref_id = CASE
                WHEN p_company_id IS NOT NULL AND p_company_id > 0 AND p_company_id <> customer_id
                    THEN p_company_id
                ELSE customer_ref_id
            END,
            updated_by = p_added_by::text,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE customer_id = v_company_id;

        SELECT company_name, customer_code
        INTO p_company_name, p_company_code
        FROM customers.customer
        WHERE customer_id = v_company_id;
    END IF;

    -- =========================
    -- UPDATE existing ticket
    -- =========================
    IF p_flag = 'update' THEN
        IF COALESCE(p_ticket_id, 0) = 0 THEN
            message := 'Ticket id is required for update';
            status := 'false';
            RETURN;
        END IF;

        UPDATE tickets.ticket
        SET
            name = COALESCE(NULLIF(TRIM(p_company_name), ''), name),
            customer_id = v_company_id,
            order_type = COALESCE(p_order_type, order_type),
            order_category = COALESCE(p_order_category, order_category),
            is_ipo = COALESCE(p_is_ipo, is_ipo),
            primary_market = COALESCE(p_primary_market, primary_market),
            redesigncategory = COALESCE(p_redesigncategory, redesigncategory),
            upsellcategory = COALESCE(p_upsellcategory, upsellcategory),
            is_new_customer = COALESCE(p_isnew_customer, is_new_customer),
            industory_id = COALESCE(p_industry_sector, industory_id),
            isin = COALESCE(NULLIF(TRIM(p_isin), ''), isin),
            symbol = COALESCE(NULLIF(TRIM(p_symbol), ''), symbol),
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE ticket_id = p_ticket_id
          AND is_active = TRUE;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;

        IF v_rowcount = 0 THEN
            message := 'Ticket not found or inactive';
            status := 'false';
            RETURN;
        END IF;

        PERFORM tickets.add_or_update_history_details(
            p_ticket_id,
            NULL,
            'Updated company details',
            p_added_by,
            NULL, NULL, NULL,
            p_added_by,
            current_timestamp AT TIME ZONE 'UTC',
            NULL, NULL, NULL, NULL, NULL,
            'Updated company details'
        );

        new_ticket_id := p_ticket_id::integer;
        status := 'true';
        message := 'Order / company details updated successfully.';
        RETURN;
    END IF;

    -- Get Order Status ID

    SELECT status_id
    INTO v_order_status_id
    FROM master.status_code_master
    WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND name = 'Yet To Process'
    LIMIT 1;

  
    -- Insert ticket

    INSERT INTO tickets.ticket (
        name,
        status_id,
        is_active,
        added_by,
        assign_to,
        customer_id,
        order_type,
        order_category,
        is_ipo,
        primary_market,
        created_by,
        created_date,
        redesigncategory,
        upsellcategory,
        is_new_customer,
        order_date,
        industory_id,
		isin,
		symbol
    )
    VALUES (
        p_company_name,
        v_order_status_id,
        TRUE,
        p_added_by,
        p_added_by,
        v_company_id,
        p_order_type,
        p_order_category,
        p_is_ipo,
        p_primary_market,
        p_added_by,
        current_timestamp AT TIME ZONE 'UTC',
        p_redesigncategory,
        p_upsellcategory,
        p_isnew_customer,
        current_timestamp AT TIME ZONE 'UTC',
        p_industry_sector,
		p_isin,
		p_symbol
    )
    RETURNING ticket_id INTO new_ticket_id;

    -- Generate sequence number & order_id

    IF NOT p_isnew_customer THEN
        SELECT COALESCE(
            MAX(CAST(SPLIT_PART(order_id, '-', 3) AS INTEGER)),
            1000
        ) + 1 INTO v_sequence_number
        FROM tickets.ticket
        WHERE order_id LIKE TRIM(p_company_code) || '-%';

        v_generated_order_id := TRIM(p_company_code) || '-' || new_ticket_id || '-' || LPAD(v_sequence_number::text, 4, '0');

        UPDATE tickets.ticket
        SET order_id = v_generated_order_id,
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE ticket_id = new_ticket_id;
    END IF;

    -- Insert ticket assignee

    INSERT INTO tickets.ticket_assignee (
        ticket_id, assignee_to, assigned_date, created_by, created_date, is_active, assignee_type
    )
    VALUES (
        new_ticket_id, p_added_by, current_timestamp AT TIME ZONE 'UTC',
        p_added_by, current_timestamp AT TIME ZONE 'UTC', TRUE, 'SA'
    );

  
    -- Insert ticket status
  
    INSERT INTO tickets.ticket_status (
        ticket_id, created_date, created_by, status_id
    )
    VALUES (
        new_ticket_id, current_timestamp AT TIME ZONE 'UTC', p_added_by, v_order_status_id
    );

   
    --  PLG Tool assignments
	SELECT "DeptCode" INTO v_dep_code 
	FROM master.department 
	WHERE is_active= true AND "Name" = 'ON BOARDING' LIMIT 1;

	SELECT status_id INTO v_tool_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND type = 'Tool' AND name = 'Open' LIMIT 1;
	
	IF v_first_order_type = plg_type_id THEN

		SELECT id INTO v_subscription_typeid
		FROM master.subscriptiontype
		WHERE name = 'PLG' AND is_active = TRUE
		LIMIT 1;

		FOR v_record_tool IN
			SELECT "ToolID" FROM master.tool
			WHERE "About" = 'PLG Tool' AND is_active = TRUE
		LOOP
			SELECT flow_id INTO v_flow_id
			FROM board.tool_flow
			WHERE is_active = TRUE
			  AND tool_id = v_record_tool."ToolID"
			LIMIT 1;

			IF v_flow_id IS NOT NULL THEN
-- 				INSERT INTO tickets.tool_detail (
-- 					ticket_id, subscription_type_id, tool_id, added_by, status,
-- 					status_id, dept_code, is_active, created_date, created_by, order_type_id, flow_id
-- 				)
-- 				VALUES (
-- 					new_ticket_id, v_subscription_typeid, v_record_tool."ToolID", p_added_by, 'Open',
-- 					v_order_status_id, v_dep_code, TRUE, current_timestamp AT TIME ZONE 'UTC', p_added_by, NULL, v_flow_id
-- 				);
				
				INSERT INTO tickets.tool_detail (
					ticket_id, subscription_type_id, tool_id, board_id, label_id,
					added_by, assign_to, status, status_id, dept_code,
					is_active, created_date, created_by, order_type_id, flow_id, position
				) VALUES (
					new_ticket_id, v_subscription_typeid, v_record_tool."ToolID",
					NULL, NULL, p_added_by, null,
					'Open', v_tool_statusid, v_dep_code,
					true, current_timestamp AT TIME ZONE 'UTC', p_added_by, plg_type_id, v_flow_id,
					(
						SELECT COALESCE(MAX(td.position), 0) + 1
						FROM tickets.tool_detail td
						WHERE td.ticket_id = new_ticket_id
						  AND td.is_active = true
					)
				);
			ELSE
				message := format('Tool''s not linked in any flow.');
				status := 'false';
				RETURN;				
			END IF;
		END LOOP;
		
		
	ELSIF redesign_type_id = ANY(p_order_type) THEN
		
		SELECT ticket_id INTO v_prev_newtype_ticket_id
			FROM tickets.ticket
		WHERE is_active = true
		  AND name = p_company_name
		  AND p_primary_market && primary_market
		  AND new_type_id = ANY(order_type);
			  
		IF v_prev_newtype_ticket_id > 0 THEN
			
			FOR v_record_tool IN
				SELECT tool_id FROM tickets.tool_detail 
				WHERE ticket_id = v_prev_newtype_ticket_id AND is_active = true 
				AND order_type_id = new_type_id
			LOOP

				SELECT flow_id
				INTO v_flow_id
				FROM board.tool_flow
				WHERE is_active = true
				  AND tool_id = v_record_tool.tool_id
				LIMIT 1;

				IF v_flow_id IS NOT NULL THEN
							
					INSERT INTO tickets.tool_detail (
						ticket_id, subscription_type_id, tool_id, board_id, label_id,
						added_by, assign_to, status, status_id, dept_code,
						is_active, created_date, created_by, order_type_id, flow_id, position
					) VALUES (
						new_ticket_id, 0, v_record_tool.tool_id,
						NULL, NULL, p_added_by, null,
						'Open', v_tool_statusid, v_dep_code,
						true, current_timestamp AT TIME ZONE 'UTC', p_added_by, redesign_type_id, v_flow_id,
						(
							SELECT COALESCE(MAX(td.position), 0) + 1
							FROM tickets.tool_detail td
							WHERE td.ticket_id = new_ticket_id
							  AND td.is_active = true
						)
					);
										
				ELSE 
					message := format('Tool''s not linked in any flow.');
					status := 'false';
					RETURN;
				END IF;	

			END LOOP;
		END IF;
    END IF;
		

    
    --  Send email if new customer
   
    IF new_ticket_id > 0 AND p_isnew_customer THEN
        v_message := jsonb_build_object(
            'TemplateKey', 'ManualOrderByCompany',
            'Payload', jsonb_build_object(
                'companyName', COALESCE(p_company_name, ''),
                'marketName', COALESCE(p_primary_market_name, '')
            )
        );

        SELECT to_email, subject
        INTO v_recipient, v_subject
        FROM master.mailtemplate
        WHERE mailtemplatetype = 'ManualOrderByCompany'
          AND is_active = TRUE
        LIMIT 1;

        FOR v_email IN SELECT unnest(string_to_array(v_recipient, ',')) LOOP
            v_email := trim(v_email);
            CALL notification.add_notification(
                p_type := 'Email',
                p_recipient := v_email,
                p_subject := v_subject,
                p_message := v_message::text,
                p_retry_count := 0,
                p_max_retries := 3,
                message := message,
                status := status
            );
        END LOOP;
    END IF;

  
    --  Add history
    PERFORM tickets.add_or_update_history_details(
        COALESCE(new_ticket_id, p_ticket_id),
        NULL,
        'Created the card',
        p_added_by,
        NULL, NULL, NULL,
        p_added_by,
        current_timestamp AT TIME ZONE 'UTC',
        NULL, NULL, NULL, NULL, NULL,
        'Created the card'
    );
	 GET DIAGNOSTICS v_rowcount = ROW_COUNT;

		IF v_rowcount > 0 THEN
		    status := 'true';
		    message := 'Order successfully created.';
		ELSE
		    status := 'false';
		    message := 'Order failed.';
		END IF;
	
    

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.upsert_order_ticket',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id, p_order_type, p_order_category, 
                p_company_id, p_company_name, p_company_code, p_isnew_customer, 
                p_is_ipo, p_primary_market, p_flag, p_added_by, p_redesigncategory,
                p_upsellcategory, p_industry_sector, p_toolcenterlink, p_primary_market_name,
				p_isin,p_symbol
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: upsert_order_ticket_old(bigint, integer[], integer[], integer, text, text, boolean, boolean, integer[], text, uuid, integer[], integer[], integer[], text, text, text, text, integer, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_order_ticket_old(IN p_ticket_id bigint DEFAULT 0, IN p_order_type integer[] DEFAULT NULL::integer[], IN p_order_category integer[] DEFAULT NULL::integer[], IN p_company_id integer DEFAULT NULL::integer, IN p_company_name text DEFAULT NULL::text, IN p_company_code text DEFAULT NULL::text, IN p_isnew_customer boolean DEFAULT false, IN p_is_ipo boolean DEFAULT false, IN p_primary_market integer[] DEFAULT NULL::integer[], IN p_flag text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, IN p_redesigncategory integer[] DEFAULT NULL::integer[], IN p_upsellcategory integer[] DEFAULT NULL::integer[], IN p_industry_sector integer[] DEFAULT NULL::integer[], IN p_toolcenterlink text DEFAULT NULL::text, IN p_primary_market_name text DEFAULT NULL::text, IN p_isin text DEFAULT NULL::text, IN p_symbol text DEFAULT NULL::text, INOUT new_ticket_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_company_id INTEGER;
    v_company_name_db TEXT;
    v_company_code_db TEXT;
    v_order_status_id INTEGER;
    v_sequence_number INTEGER := 0;
    v_generated_order_id TEXT;
    v_worklog_message TEXT := '';
    v_subscription_typeid INTEGER;
    v_dep_code TEXT;
	v_tool_statusid INTEGER := 0;
    v_record_tool RECORD;
    v_flow_id INT;
    v_recipient TEXT;
    v_subject TEXT;
    v_message JSONB;
    v_email TEXT;	
	new_type_id  INTEGER;
    plg_type_id  INTEGER;
    upsell_type_id INTEGER;	
	redesign_type_id INTEGER;
	v_first_order_type INTEGER;
	v_prev_newtype_ticket_id INT;
	v_rowcount INTEGER := 0;
	v_context text;
BEGIN

	    -- Validate flag
    IF p_flag NOT IN ('insert', 'update') THEN
        message := 'Invalid flag value';
        status := 'false';
        RETURN;
    END IF;

    -- Validate order_type
    IF p_order_type IS NULL OR array_length(p_order_type, 1) = 0 THEN
        message := 'Order type cannot be null or empty';
        status := 'false';
        RETURN;
    END IF;

    -- Set first order type
    v_first_order_type := p_order_type[1];   
	
	SELECT status_id INTO new_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'NC';
    
    SELECT status_id INTO plg_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'PLG';
    
    SELECT status_id INTO upsell_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'UP';
    
    SELECT status_id INTO redesign_type_id 
    FROM master.status_code_master 
    WHERE is_active = true AND type = 'ORDERTYPE' AND code = 'RD';
	
	
    -- Check if company exists or create it

    SELECT customer_id, company_name, customer_code
    INTO v_company_id, v_company_name_db, v_company_code_db
    FROM customers.customer
    WHERE LOWER(company_name) = LOWER(p_company_name) AND is_active = TRUE
    LIMIT 1;

    IF v_company_id IS NULL THEN
        INSERT INTO customers.customer (
		   customer_ref_id,
            company_name,
            customer_code,
            is_active,
            created_by,
            created_date,
            tool_center_link
        )
        VALUES (
		    p_company_id,
            p_company_name,
            p_company_code,
            TRUE,
            p_added_by,
            current_timestamp AT TIME ZONE 'UTC',
            p_toolcenterlink
        )
        RETURNING customer_id INTO v_company_id;

        RAISE NOTICE ' New customer created: %, ID: %', p_company_name, v_company_id;
    ELSE
        RAISE NOTICE 'ℹ️ Existing customer found: %, ID: %', v_company_name_db, v_company_id;

        -- Update tool_center_link if NULL
        IF p_toolcenterlink IS NOT NULL THEN
            UPDATE customers.customer
            SET tool_center_link = p_toolcenterlink
            WHERE customer_id = v_company_id AND tool_center_link IS NULL;
        END IF;

        -- Override company name with DB value
        p_company_name := v_company_name_db;
    END IF;

    -- Get Order Status ID

    SELECT status_id
    INTO v_order_status_id
    FROM master.status_code_master
    WHERE is_active = TRUE AND type = 'ORDERSTATUS' AND name = 'Yet To Process'
    LIMIT 1;

  
    -- Insert ticket

    INSERT INTO tickets.ticket (
        name,
        status_id,
        is_active,
        added_by,
        assign_to,
        customer_id,
        order_type,
        order_category,
        is_ipo,
        primary_market,
        created_by,
        created_date,
        redesigncategory,
        upsellcategory,
        is_new_customer,
        order_date,
        industory_id,
		isin,
		symbol
    )
    VALUES (
        p_company_name,
        v_order_status_id,
        TRUE,
        p_added_by,
        p_added_by,
        v_company_id,
        p_order_type,
        p_order_category,
        p_is_ipo,
        p_primary_market,
        p_added_by,
        current_timestamp AT TIME ZONE 'UTC',
        p_redesigncategory,
        p_upsellcategory,
        p_isnew_customer,
        current_timestamp AT TIME ZONE 'UTC',
        p_industry_sector,
		p_isin,
		p_symbol
    )
    RETURNING ticket_id INTO new_ticket_id;

    -- Generate sequence number & order_id

    IF NOT p_isnew_customer THEN
        SELECT COALESCE(
            MAX(CAST(SPLIT_PART(order_id, '-', 3) AS INTEGER)),
            1000
        ) + 1 INTO v_sequence_number
        FROM tickets.ticket
        WHERE order_id LIKE TRIM(p_company_code) || '-%';

        v_generated_order_id := TRIM(p_company_code) || '-' || new_ticket_id || '-' || LPAD(v_sequence_number::text, 4, '0');

        UPDATE tickets.ticket
        SET order_id = v_generated_order_id,
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE ticket_id = new_ticket_id;
    END IF;

    -- Insert ticket assignee

    INSERT INTO tickets.ticket_assignee (
        ticket_id, assignee_to, assigned_date, created_by, created_date, is_active, assignee_type
    )
    VALUES (
        new_ticket_id, p_added_by, current_timestamp AT TIME ZONE 'UTC',
        p_added_by, current_timestamp AT TIME ZONE 'UTC', TRUE, 'SA'
    );

  
    -- Insert ticket status
  
    INSERT INTO tickets.ticket_status (
        ticket_id, created_date, created_by, status_id
    )
    VALUES (
        new_ticket_id, current_timestamp AT TIME ZONE 'UTC', p_added_by, v_order_status_id
    );

   
    --  PLG Tool assignments
	SELECT "DeptCode" INTO v_dep_code 
	FROM master.department 
	WHERE is_active= true AND "Name" = 'ON BOARDING' LIMIT 1;

	SELECT status_id INTO v_tool_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND type = 'Tool' AND name = 'Open' LIMIT 1;
	
	IF v_first_order_type = plg_type_id THEN

		SELECT id INTO v_subscription_typeid
		FROM master.subscriptiontype
		WHERE name = 'PLG' AND is_active = TRUE
		LIMIT 1;

		FOR v_record_tool IN
			SELECT "ToolID" FROM master.tool
			WHERE "About" = 'PLG Tool' AND is_active = TRUE
		LOOP
			SELECT flow_id INTO v_flow_id
			FROM board.tool_flow
			WHERE is_active = TRUE
			  AND tool_id = v_record_tool."ToolID"
			LIMIT 1;

			IF v_flow_id IS NOT NULL THEN
-- 				INSERT INTO tickets.tool_detail (
-- 					ticket_id, subscription_type_id, tool_id, added_by, status,
-- 					status_id, dept_code, is_active, created_date, created_by, order_type_id, flow_id
-- 				)
-- 				VALUES (
-- 					new_ticket_id, v_subscription_typeid, v_record_tool."ToolID", p_added_by, 'Open',
-- 					v_order_status_id, v_dep_code, TRUE, current_timestamp AT TIME ZONE 'UTC', p_added_by, NULL, v_flow_id
-- 				);
				
				INSERT INTO tickets.tool_detail (
					ticket_id, subscription_type_id, tool_id, board_id, label_id,
					added_by, assign_to, status, status_id, dept_code,
					is_active, created_date, created_by, order_type_id, flow_id
				) VALUES (
					new_ticket_id, v_subscription_typeid, v_record_tool."ToolID",
					NULL, NULL, p_added_by, null,
					'Open', v_tool_statusid, v_dep_code,
					true, current_timestamp AT TIME ZONE 'UTC', p_added_by, plg_type_id, v_flow_id
				);
			ELSE
				message := format('Tool''s not linked in any flow.');
				status := 'false';
				RETURN;				
			END IF;
		END LOOP;
		
		
	ELSIF redesign_type_id = ANY(p_order_type) THEN
		
		SELECT ticket_id INTO v_prev_newtype_ticket_id
			FROM tickets.ticket
		WHERE is_active = true
		  AND name = p_company_name
		  AND p_primary_market && primary_market
		  AND new_type_id = ANY(order_type);
			  
		IF v_prev_newtype_ticket_id > 0 THEN
			
			FOR v_record_tool IN
				SELECT tool_id FROM tickets.tool_detail 
				WHERE ticket_id = v_prev_newtype_ticket_id AND is_active = true 
				AND order_type_id = new_type_id
			LOOP

				SELECT flow_id
				INTO v_flow_id
				FROM board.tool_flow
				WHERE is_active = true
				  AND tool_id = v_record_tool.tool_id
				LIMIT 1;

				IF v_flow_id IS NOT NULL THEN
							
					INSERT INTO tickets.tool_detail (
						ticket_id, subscription_type_id, tool_id, board_id, label_id,
						added_by, assign_to, status, status_id, dept_code,
						is_active, created_date, created_by, order_type_id, flow_id
					) VALUES (
						new_ticket_id, 0, v_record_tool.tool_id,
						NULL, NULL, p_added_by, null,
						'Open', v_tool_statusid, v_dep_code,
						true, current_timestamp AT TIME ZONE 'UTC', p_added_by, redesign_type_id, v_flow_id
					);
										
				ELSE 
					message := format('Tool''s not linked in any flow.');
					status := 'false';
					RETURN;
				END IF;	

			END LOOP;
		END IF;
    END IF;
		

    
    --  Send email if new customer
   
    IF new_ticket_id > 0 AND p_isnew_customer THEN
        v_message := jsonb_build_object(
            'TemplateKey', 'ManualOrderByCompany',
            'Payload', jsonb_build_object(
                'companyName', COALESCE(p_company_name, ''),
                'marketName', COALESCE(p_primary_market_name, '')
            )
        );

        SELECT to_email, subject
        INTO v_recipient, v_subject
        FROM master.mailtemplate
        WHERE mailtemplatetype = 'ManualOrderByCompany'
          AND is_active = TRUE
        LIMIT 1;

        FOR v_email IN SELECT unnest(string_to_array(v_recipient, ',')) LOOP
            v_email := trim(v_email);
            CALL notification.add_notification(
                p_type := 'Email',
                p_recipient := v_email,
                p_subject := v_subject,
                p_message := v_message::text,
                p_retry_count := 0,
                p_max_retries := 3,
                message := message,
                status := status
            );
        END LOOP;
    END IF;

  
    --  Add history
    PERFORM tickets.add_or_update_history_details(
        COALESCE(new_ticket_id, p_ticket_id),
        NULL,
        'Created the card',
        p_added_by,
        NULL, NULL, NULL,
        p_added_by,
        current_timestamp AT TIME ZONE 'UTC',
        NULL, NULL, NULL, NULL, NULL,
        'Created the card'
    );
	 GET DIAGNOSTICS v_rowcount = ROW_COUNT;

		IF v_rowcount > 0 THEN
		    status := 'true';
		    message := 'Order successfully created.';
		ELSE
		    status := 'false';
		    message := 'Order failed.';
		END IF;
	
    

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;

        CALL master.procedure_log_exception(
            'tickets.upsert_order_ticket',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_ticket_id, p_order_type, p_order_category, 
                p_company_id, p_company_name, p_company_code, p_isnew_customer, 
                p_is_ipo, p_primary_market, p_flag, p_added_by, p_redesigncategory,
                p_upsellcategory, p_industry_sector, p_toolcenterlink, p_primary_market_name,
				p_isin,p_symbol
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: upsert_task_with_subtasks(text, uuid, character varying, character varying, character varying); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_task_with_subtasks(IN p_input text DEFAULT NULL::text, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying, INOUT autorefreshreq character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE  
	v_input JSONB := p_input::JSONB;
    v_taskid INT;
	v_boardid INT;
	v_labelid INT;	
    v_subtask JSONB;
	v_context  TEXT;
	v_company_id INT;
	v_sub_taskid INT;
	v_tool_statusid INT;
	v_new_tool_board_logid INT;
	v_new_tool_assignee_id INT;
	v_task_statusid INT;
	v_tool_id INT;
	v_rows_affected INT := 0;
	v_tmp_rows INT := 0;
	v_is_create BOOLEAN := FALSE;
	
	v_recipient_push TEXT := NULL;
	v_reg TEXT := NULL;
	v_recipient_email TEXT := NULL;
	v_board_name TEXT := NULL;
	v_label_name TEXT := NULL;
	v_work_space_id	INTEGER := 0;
	v_activity_content TEXT := NULL;
	v_assignee UUID := NULL;
	v_old_assignee_to UUID := NULL;
	
	-- Task tracking
	v_old_task_name TEXT;
	v_old_task_priority INT[];
	v_new_task_name TEXT;
	v_new_task_priority INT[];
	v_task_message TEXT := '';

	-- Sub task tracking
	v_old_sub_name TEXT;
	v_old_sub_priority INT[];
	v_old_assignee UUID;
	v_new_sub_name TEXT;
	v_new_sub_priority INT[];
	v_sub_message TEXT := '';
	v_final_message TEXT := '';

	-- Due Date Log
   v_new_due_date DATE;
   v_due_reason TEXT;
   v_due_month INT;
   v_due_seq INT;
   v_due_log_id INT;
   v_old_due_date DATE;
	
	v_refresh JSONB;
	v_tool_ticket_ids INTEGER[] := '{}';
	v_is_add_kanban boolean := false;
BEGIN

	/******************************************************************************
	Procedure   : tickets.upsert_task_with_subtasks
	Developer   : Aravindhan.B
	Created On  : 20-01-2026
	Purpose     : Add/Update Task and Sub Task

	Change Log  :
	-------------------------------------------------------------------------------
	Date        Developer        		Change Description
	----------- ----------------------- -------------------------------------------
	20-01-2026  Aravindhan.B     		Initial creation	
	23-02-2025  Mubarak Basha          Capture the history & Notification while adding assignee
	03-07-2026   Naveen S		     	Add the FreeFlowLabels
	*******************************************************************************/		
	
	-- Basic validation
    IF v_input IS NULL OR v_input ->> 'taskId' IS NULL THEN
        status  := 'false';
        message := 'Invalid input JSON or taskid missing';
        RETURN;
    END IF;
	
	
	--INSERT INTO master.stored_request VALUES(p_input::TEXT);
	
	-- Get task id
    v_taskid  := (v_input ->> 'taskId')::INT;
	v_boardid := (v_input ->> 'boardId')::INT;
	v_labelid := COALESCE(NULLIF(v_input ->> 'labelId', '')::INT, 0);
	
	 
	--Get tool status id
	SELECT status_id INTO v_tool_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND UPPER(type) = UPPER('Tool') AND UPPER(name) = UPPER('Open');
	
	--Get default tool id
	SELECT "ToolID" INTO v_tool_id 
	FROM master.tool
	WHERE is_active= true AND UPPER("ToolCode") = 'EUROLANDTOOL';
	
	--Get task status id
	SELECT status_id INTO v_task_statusid 
	FROM master.status_code_master 
	WHERE is_active= true AND UPPER(type) = 'TASKSTATUS' AND UPPER(name) = UPPER('Open');
	
	-- Get Start Stage ID (first position)
	IF v_labelid = 0 THEN
		SELECT "LabelID"
		INTO v_labelid
		FROM board.boardstatus 
		WHERE is_active = true
		  AND "BoardID" = v_boardid
		ORDER BY "Position" ASC
		LIMIT 1;
	END IF;
	
	SELECT "Name", work_space_id
	INTO v_board_name, v_work_space_id
    FROM board.board 
    WHERE "BoardID" = v_boardid AND is_active = TRUE;
	
	
	SELECT "Name" INTO v_label_name 
    FROM board.boardstatus
    WHERE "BoardID" = v_boardid AND "LabelID" = v_labelid AND is_active = TRUE;
	
	--Get Default Company Id
	SELECT 
		customer_id INTO v_company_id 
	FROM customers.customer 
	WHERE UPPER(customer_code) = 'EUROLANDCOMPANY'
		AND is_active = true;			

    -- Insert/Update Task
	IF v_taskid = 0 THEN
		v_is_create := TRUE;

		-- INSERT TICKET
		INSERT INTO tickets.ticket (
			name,
			status_id,
			is_active,
			added_by,
			assign_to,
			customer_id,			
			created_by,
			created_date,
			priority_id,
			order_date
		)
		VALUES (
			v_input ->> 'title',
			v_task_statusid,
			TRUE,
			p_added_by,
			p_added_by,
			v_company_id,			
			p_added_by,
			current_timestamp AT TIME ZONE 'UTC',
			CASE
				WHEN NULLIF(v_input ->> 'priorityId', '') IS NULL THEN NULL::integer[]
				ELSE ARRAY[(v_input ->> 'priorityId')::INT]
			END,
			current_timestamp AT TIME ZONE 'UTC'
		)
		RETURNING ticket_id INTO v_taskid;
		GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
		v_rows_affected := v_rows_affected + v_tmp_rows;

	ELSE
	
		-- Get old values
		SELECT name, priority_id
		INTO v_old_task_name, v_old_task_priority
		FROM tickets.ticket
		WHERE ticket_id = v_taskid;

		-- Assign new values
		v_new_task_name := v_input ->> 'title';
		v_new_task_priority := CASE
			WHEN NULLIF(v_input ->> 'priorityId', '') IS NULL THEN NULL::integer[]
			ELSE ARRAY[(v_input ->> 'priorityId')::INT]
		END;	
		
		
		IF v_old_task_name IS DISTINCT FROM v_new_task_name
   				OR v_old_task_priority IS DISTINCT FROM v_new_task_priority THEN
			-- Perform update
			UPDATE tickets.ticket
			SET
				name = v_new_task_name,
				priority_id = v_new_task_priority,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC',
				updated_by = p_added_by
			WHERE ticket_id = v_taskid;

			GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
			v_rows_affected := v_rows_affected + v_tmp_rows;

			-- Build task message
			IF v_old_task_name IS DISTINCT FROM v_new_task_name THEN
				v_task_message := 'Task Name';
			END IF;

			IF v_old_task_priority IS DISTINCT FROM v_new_task_priority THEN
				IF v_task_message <> '' THEN
					v_task_message := v_task_message || ' and ';
				END IF;
				v_task_message := v_task_message || 'Task Priority';
			END IF;

			IF v_task_message <> '' THEN
				v_task_message := v_task_message || ' updated successfully';
			END IF;
		
			status  := 'true';
			message := v_task_message;
			RETURN;	
		END IF;
		
	END IF;	
	
	-- INSERT / UPDATE sub-tasks from JSON	
    FOR v_subtask IN
        SELECT * FROM jsonb_array_elements(v_input -> 'subTask')
    LOOP
	
		v_sub_taskid := (v_subtask ->> 'subTaskId')::INT;		
		v_assignee := NULLIF(v_subtask ->> 'assignee', '')::UUID;
		raise info 'a % ', v_assignee::text;
		IF v_sub_taskid = 0 THEN
		
			-- Get starting log id (MAX + 1)
			SELECT COALESCE(MAX(tool_board_logid),0) + 1
			INTO v_new_tool_board_logid
			FROM tickets.tool_board_log;
		
			--INSERT TOOL DETAIL
			INSERT INTO tickets.tool_detail (
				ticket_id,
				subscription_type_id,
				tool_id,
				board_id,
				label_id,
				added_by,
				assign_to,
				status,
				status_id,
				dept_code,
				is_active,
				created_date,
				created_by,
				priority_id,
				free_flow_label_id,
				flow_id,
				sub_task_name,
				due_date,
				check_list,
				position
			)
			VALUES (
				v_taskid,
				0,
				v_tool_id,
				v_boardid,
				v_labelid,
				p_added_by,
				NULL,
				'Open',
				v_tool_statusid,
				NULL,
				TRUE,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				CASE
					WHEN NULLIF(v_subtask ->> 'priorityId', '') IS NULL THEN NULL::integer[]
					ELSE ARRAY[(v_subtask ->> 'priorityId')::INT]
				END,
				CASE
					WHEN jsonb_typeof(v_subtask -> 'freeFlowLabelId') = 'array' THEN
						NULLIF(ARRAY(SELECT jsonb_array_elements_text(v_subtask -> 'freeFlowLabelId')::integer), ARRAY[]::integer[])
					WHEN NULLIF(v_subtask ->> 'freeFlowLabelId', '') IS NOT NULL THEN
						ARRAY[(v_subtask ->> 'freeFlowLabelId')::integer]
					ELSE
						NULL::integer[]
				END,
				0,
				(v_subtask ->> 'title')::text,
				(v_subtask ->> 'dueDate')::DATE,
				COALESCE(v_subtask -> 'checkList', '[]'::jsonb),
				COALESCE(
					NULLIF(v_subtask ->> 'position', '')::integer,
					(
						SELECT COALESCE(MAX(td.position), 0) + 1
						FROM tickets.tool_detail td
						WHERE td.ticket_id = v_taskid
						  AND td.is_active = true
					)
				)
			)
			RETURNING tool_ticket_id INTO v_sub_taskid;

			-- Due Date Log Insert (New Subtask)
           v_new_due_date := (v_subtask ->> 'dueDate')::DATE;
           v_due_reason   := NULL;  -- First time always NULL

		   IF v_new_due_date IS NOT NULL THEN

           v_due_month := EXTRACT(MONTH FROM v_new_due_date);

           SELECT COALESCE(MAX(sequence),0) + 1
           INTO v_due_seq
           FROM tickets.tool_duedate_log
           WHERE tool_ticket_id = v_sub_taskid
           AND EXTRACT(MONTH FROM due_date) = v_due_month
           AND is_active = true;

           SELECT COALESCE(MAX(tool_duedate_log_id),0) + 1
           INTO v_due_log_id
           FROM tickets.tool_duedate_log;

           INSERT INTO tickets.tool_duedate_log(
           tool_duedate_log_id,
           tool_ticket_id,
           due_date,
           reason,
          sequence,
          is_active,
          created_date,
           created_by
         )
        VALUES(
        v_due_log_id,
        v_sub_taskid,
        v_new_due_date,
         NULL,  -- Always NULL first time
        v_due_seq,
        true,
        current_timestamp AT TIME ZONE 'UTC',
        p_added_by
        );
        END IF;
		
		PERFORM tickets.add_or_update_history_details(
		    in_order_id        => v_taskid,
		    in_tool_ticket_id  => v_sub_taskid,
		    in_content         => 'Due Date changed from ' ||
		                          COALESCE(to_char(v_old_due_date, 'DD-Mon-YYYY'), 'N/A') ||
		                          ' to ' ||
		                          COALESCE(to_char(v_new_due_date, 'DD-Mon-YYYY'), 'N/A'),
		    in_user_id         => p_added_by,
		    in_created_by      => p_added_by,
		    in_created_date    => current_timestamp AT TIME ZONE 'UTC',
		    in_history_type    => 'Due Date'
		);
			
			GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
            v_rows_affected := v_rows_affected + v_tmp_rows;
			
			v_tool_ticket_ids := array_append(v_tool_ticket_ids, v_sub_taskid);
			v_is_add_kanban := true;
						
			--INSERT TOOL BOARD LOG
			INSERT INTO tickets.tool_board_log(
				tool_board_logid,
				ticket_id,
				tool_ticket_id,
				moved_by,
				board_id,
				label_id,
				moved_date,
				sequence,
				action_id,
				created_date,
				created_by,
				is_active
			)
			VALUES (
				v_new_tool_board_logid,
				v_taskid,
				v_sub_taskid,
				p_added_by,			
				v_boardid,
				v_labelid,
				current_timestamp AT TIME ZONE 'UTC',
				1,
				NULL,
				current_timestamp AT TIME ZONE 'UTC',
				p_added_by,
				TRUE
			);
			
			GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
            v_rows_affected := v_rows_affected + v_tmp_rows;			
						
		ELSE
		
			-- Get old due date
			SELECT due_date
			INTO v_old_due_date
			FROM tickets.tool_detail
			WHERE tool_ticket_id = v_sub_taskid
			AND is_active = true;

			-- Get new due date from JSON
			v_new_due_date := NULLIF(v_subtask ->> 'dueDate','')::DATE;
			v_due_reason   := v_subtask ->> 'dueDateChangeReason';
 			-- UPDATE TOOL DETAIL
			UPDATE tickets.tool_detail
			SET
				sub_task_name        = v_subtask ->> 'title',
				priority_id = CASE
					WHEN NULLIF(v_subtask ->> 'priorityId', '') IS NULL THEN NULL::integer[]
					ELSE ARRAY[(v_subtask ->> 'priorityId')::INT]
				END,
				free_flow_label_id = CASE
					WHEN jsonb_typeof(v_subtask -> 'freeFlowLabelId') = 'array' THEN
						NULLIF(ARRAY(SELECT jsonb_array_elements_text(v_subtask -> 'freeFlowLabelId')::integer), ARRAY[]::integer[])
					WHEN NULLIF(v_subtask ->> 'freeFlowLabelId', '') IS NOT NULL THEN
						ARRAY[(v_subtask ->> 'freeFlowLabelId')::integer]
					ELSE
						NULL::integer[]
				END,
				--due_date = (v_subtask ->> 'dueDate')::DATE,
				check_list = CASE
					WHEN v_subtask ? 'checkList' THEN COALESCE(v_subtask -> 'checkList', '[]'::jsonb)
					ELSE check_list
				END,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
				updated_by = p_added_by
			WHERE tool_ticket_id = v_sub_taskid;
		
		 	GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
            v_rows_affected := v_rows_affected + v_tmp_rows;	

			 -- Insert log ONLY if due date changed
		IF v_new_due_date IS DISTINCT FROM v_old_due_date THEN
		
		    -- Update due date
		    UPDATE tickets.tool_detail
		    SET due_date = v_new_due_date
		    WHERE tool_ticket_id = v_sub_taskid;
		
		    -- Only insert log if new due date exists
		    IF v_new_due_date IS NOT NULL THEN
		
		        v_due_month := EXTRACT(MONTH FROM v_new_due_date);
		
		        SELECT COALESCE(MAX(sequence),0) + 1
		        INTO v_due_seq
		        FROM tickets.tool_duedate_log
		        WHERE tool_ticket_id = v_sub_taskid
		        AND EXTRACT(MONTH FROM due_date) = v_due_month
		        AND is_active = true;
		
		        SELECT COALESCE(MAX(tool_duedate_log_id),0) + 1
		        INTO v_due_log_id
		        FROM tickets.tool_duedate_log;
		
		        INSERT INTO tickets.tool_duedate_log(
		            tool_duedate_log_id,
		            tool_ticket_id,
		            due_date,
		            reason,
		            sequence,
		            is_active,
		            created_date,
		            created_by
		        )
		        VALUES(
		            v_due_log_id,
		            v_sub_taskid,
		            v_new_due_date,
		            v_due_reason,
		            v_due_seq,
		            true,
		            current_timestamp AT TIME ZONE 'UTC',
		            p_added_by
		        );
		
		    END IF;
			
			v_tool_ticket_ids := array_append(v_tool_ticket_ids, v_sub_taskid);
			v_is_add_kanban := false;

		END IF;
		END IF;
		
		SELECT tool_board_logid INTO v_new_tool_board_logid FROM (
				SELECT DISTINCT ON (tool_ticket_id)
					   tbl.tool_ticket_id,
					   tbl.board_id,
					   tbl.label_id,
					   tbl.tool_board_logid
				FROM tickets.tool_board_log tbl
				WHERE tbl.board_id = board_id
				  AND tbl.label_id = label_id
				  AND tbl.is_active = TRUE
				  AND tbl.is_moved = FALSE
				  AND tbl.tool_ticket_id = v_sub_taskid
				ORDER BY
					tbl.tool_ticket_id,
					sequence DESC
			)x;
			
		SELECT tool_assignee_id, assignee_to INTO v_new_tool_assignee_id, v_old_assignee_to FROM (
				SELECT tool_assignee_id, un_assigned_flag, assignee_to
					FROM tickets.tool_assignee 
				WHERE tool_board_logid = v_new_tool_board_logid 
				AND board_id = v_boardid 
				AND label_id = v_labelid 
				AND is_active 
				order by sequence desc 
				Limit 1
			)x WHERE x.un_assigned_flag = false;

		--INSERT ASSIGNEE

		-- ASSIGNEE HANDLING
		
		IF v_assignee IS NOT NULL 
		   AND v_old_assignee_to IS DISTINCT FROM v_assignee THEN
		
		    -- Generate new ID (Better: use sequence in production)
		    SELECT COALESCE(MAX(tool_assignee_id), 0) + 1
		    INTO v_new_tool_assignee_id
		    FROM tickets.tool_assignee;
		
		    INSERT INTO tickets.tool_assignee (
		        tool_assignee_id,
		        tool_board_logid,
		        board_id,
		        label_id,
		        assignee_to,
		        assigned_date,
		        is_active,
		        created_date,
		        created_by,
		        sequence,
		        un_assigned_flag
		    )
		    VALUES (
		        v_new_tool_assignee_id,
		        v_new_tool_board_logid,
		        v_boardid,
		        v_labelid,
		        v_assignee,
		        current_timestamp,
		        true,
		        current_timestamp,
		        p_added_by::text,
		        COALESCE((
		            SELECT MAX(sequence) + 1
		            FROM tickets.tool_assignee
		            WHERE tool_board_logid = v_new_tool_board_logid
		              AND board_id = v_boardid
		              AND label_id = v_labelid
		              AND is_active = true
		        ), 1),
		        false
		    );
		
		    GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
		    v_rows_affected := v_rows_affected + v_tmp_rows;
		
		    -- HISTORY ENTRY
		
		    DECLARE
		        v_assignee_name TEXT;
		        v_added_user_name TEXT;
		        v_notify_message TEXT;
		        v_history_type TEXT := 'TaskAssignee';
		    BEGIN
		
		        SELECT "DisplayName"
		        INTO v_assignee_name
		        FROM users.registereduser
		        WHERE "RegId" = v_assignee
		        AND is_active = true;
		
		        SELECT "DisplayName"
		        INTO v_added_user_name
		        FROM users.registereduser
		        WHERE "RegId" = p_added_by
		        AND is_active = true;
		
		        PERFORM tickets.add_or_update_history_details(
		            in_order_id        => v_taskid,
		            in_tool_ticket_id  => v_sub_taskid,
		            in_content         => CASE
		                                    WHEN p_added_by = v_assignee THEN
		                                        'self-assigned the task "' || (v_subtask ->> 'title') || '".'
		                                    WHEN v_old_assignee_to IS NULL THEN
		                                        'assigned the task to "' || v_assignee_name || '".'
		                                    ELSE
		                                        're-assigned the task to "' || v_assignee_name || '".'
		                                  END,
		            in_user_id         => p_added_by,
		            in_created_by      => p_added_by,
		            in_created_date    => current_timestamp AT TIME ZONE 'UTC',
		            in_history_type    => v_history_type
		        );
		
		        -- PUSH NOTIFICATION (Avoid self notify)
		
		        IF v_assignee <> p_added_by THEN
		
		            v_notify_message :=
		                'You have been assigned the task <b>' ||
		                COALESCE(v_subtask ->> 'title', '') ||
		                '</b> in card <b>' ||
		                COALESCE(v_input ->> 'title', '') ||
		                '</b> by <b>' ||
		                COALESCE(v_added_user_name, '') ||
		                '</b>.';
		
		            CALL notification.add_notification(
		                p_type := 'Push',
		                p_recipient := v_assignee::text,
		                p_subject := 'Task Assigned',
		                p_message := v_notify_message,
		                p_retry_count := 0,
		                p_max_retries := 3,
		                p_message_json := jsonb_build_object(
		                                    'ticket_id',      v_taskid,
		                                    'tool_ticket_id', v_sub_taskid,
		                                    'board_id',       v_boardid,
		                                    'moved_from',     p_added_by::text,
		                                    'moved_to',       v_assignee::text,
		                                    'notify_message', v_notify_message,
		                                    'is_read',        false,
		                                    'type',           'task_assignee',
		                                    'workspace_id',   v_work_space_id,
		                                    'header',         'Task Assigned'
		                                  )::text,
		                message := message,
		                status := status
		            );
		
		        END IF;
		
		    END;
		
		
		ELSIF v_assignee IS NULL 
		      AND v_new_tool_assignee_id > 0
		      AND v_old_assignee_to IS NOT NULL THEN
		
		    -- UNASSIGN
		
		    UPDATE tickets.tool_assignee
		    SET
		        un_assigned_flag = true,
		        un_assigned_date = current_timestamp AT TIME ZONE 'UTC',
		        last_updated_date = current_timestamp AT TIME ZONE 'UTC',
		        updated_by = p_added_by
		    WHERE tool_assignee_id = v_new_tool_assignee_id;
		
		    GET DIAGNOSTICS v_tmp_rows = ROW_COUNT;
		    v_rows_affected := v_rows_affected + v_tmp_rows;
		
		    PERFORM tickets.add_or_update_history_details(
		        in_order_id        => v_taskid,
		        in_tool_ticket_id  => v_sub_taskid,
		        in_content         => 'un-assigned the task "' || (v_subtask ->> 'title') || '".',
		        in_user_id         => p_added_by,
		        in_created_by      => p_added_by,
		        in_created_date    => current_timestamp AT TIME ZONE 'UTC',
		        in_history_type    => 'TaskUnAssignee'
		    );
		
		END IF;

    END LOOP;
	
	--Get Email address
	SELECT 
		STRING_AGG(r."Email", ', ') AS recipient_email,
		STRING_AGG(ubp.reg_id::text, ', ') AS recipient_push
	INTO 
		v_recipient_email, 
		v_recipient_push
	FROM users.user_board_permission ubp
	JOIN users.registereduser r ON r."RegId" = ubp.reg_id AND r.is_active = true
	WHERE ubp.board_id = v_boardid AND ubp.is_active = true;			
	
    -- FINAL RESPONSE
    IF v_rows_affected > 0 THEN
		--Last Updated User Detail
	 	UPDATE tickets.ticket
        SET
            last_updated_date = current_timestamp AT TIME ZONE 'UTC', 
			updated_by = p_added_by 
        WHERE ticket_id = v_taskid;
	         status := 'true';	

        IF v_is_create THEN
			
			-- Add Push Notification
			FOR v_reg IN  SELECT ubp.reg_id::text  FROM users.user_board_permission ubp
		    WHERE ubp.board_id = v_boardid  AND ubp.is_active = true AND ubp.reg_id <> p_added_by

	  LOOP
		
		    CALL notification.add_notification(
		        p_type := 'Push',
		        p_recipient := v_reg,
		        p_subject := 'New Card',
		        p_message := 'A new card has created in the <b>' || 
		                     COALESCE(v_label_name, '') || 
		                     '</b>: <b>' || 
		                     COALESCE(v_input ->> 'title', '') || 
		                     '</b>.',
		        p_retry_count := 0,
		        p_max_retries := 3,
		        p_message_json := '{
		                            "ticket_id": '|| v_taskid ||',
		                            "tool_id": 0,
		                            "tool_ticket_id": 0,
		                            "board_id": '|| v_boardid ||',
		                            "moved_from": "'|| p_added_by ||'",
		                            "moved_to": "'|| v_reg ||'",
		                            "notify_message": "A new card has created in the <b>' 
		                                || COALESCE(v_label_name, '') || 
		                                '</b>: <b>' || 
		                                COALESCE(v_input ->> 'title', '') || 
		                                '</b>.",	
		                            "is_read": false,
		                            "type": "task_ticket",	
		                            "workspace_id": '|| v_work_space_id ||',
		                            "header": "New Card"
		                           }'::text,
		        message := message,
		        status := status
		    );
		
		END LOOP;
			-- FOR v_reg IN SELECT unnest(string_to_array(v_recipient_push , ',')) LOOP

			-- 	-- Trim spaces if any
			-- 	v_reg := trim(v_reg);

			-- 	-- Call the existing add_notification procedure for each recipient
			-- 	CALL notification.add_notification(
			-- 		p_type := 'Push',
			-- 		p_recipient := v_reg,
			-- 		p_subject := 'New Card',
			-- 		p_message := 'A new card has created in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_input ->> 'title', '') || '</b>.',
			-- 		p_retry_count := 0,
			-- 		p_max_retries := 3,
			-- 		p_message_json := '{
			-- 							"ticket_id": '|| v_taskid ||',
			-- 							"tool_id": 0,
			-- 							"tool_ticket_id": 0,
			-- 							"board_id": '|| v_boardid ||',
			-- 							"moved_from": "'|| p_added_by ||'",
			-- 							"moved_to": "'|| v_reg ||'",
			-- 							"notify_message": "A new card has created in the <b>' || COALESCE(v_label_name, '') || '</b>: <b>' || COALESCE(v_input ->> 'title', '') || '</b>.",	
			-- 							"is_read": false,
			-- 							"type": "task_ticket",	
			-- 							"workspace_id": '|| v_work_space_id ||',
			-- 							"header": "New Card"
			-- 						   }'::text,
			-- 		message := message,
			-- 		status := status
			-- 	);

			-- END LOOP;
			v_activity_content := 'Task created';
            message := 'Task created successfully';
        ELSE
			v_activity_content := 'Task updated';
            message := 'Task updated successfully';
        END IF;
		
		-- History: Task / Sub-task details updated
		PERFORM tickets.add_or_update_history_details(
			in_order_id           => v_taskid,
			in_content            => v_activity_content,
			in_user_id            => p_added_by,
			in_created_by         => p_added_by,
			in_created_date       => current_timestamp AT TIME ZONE 'UTC',
			in_uploaded_file_name => NULL,
			in_history_type       => 'TaskCreateUpdate'
		);	
		autorefreshreq := NULL;
		IF array_length(v_tool_ticket_ids, 1) IS NOT NULL THEN
			v_refresh := jsonb_build_object(
				'tool_ticket_id', v_tool_ticket_ids,
				'ticket_id', v_taskid,
				'board_id', CASE WHEN v_is_add_kanban THEN v_boardid ELSE 0 END,
				'from_label_id', 0,
				'to_label_id', CASE WHEN v_is_add_kanban THEN v_labelid ELSE 0 END,
				'type', CASE WHEN v_is_create THEN 'ADD' ELSE 'UPDATE' END,
				'added_by', p_added_by
			);		

			autorefreshreq := (
				COALESCE(autorefreshreq, '[]')::jsonb || jsonb_build_array(v_refresh)
			)::text;
		END IF;
    ELSE
        status := 'false';
        message := 'No data updated';
		autorefreshreq := NULL;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'tickets.upsert_task_with_subtasks',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                v_input,
                p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
	
END;
$$;


--
-- Name: upsert_ticket_work_log(bigint, integer, uuid, uuid, text); Type: PROCEDURE; Schema: tickets; Owner: -
--

CREATE PROCEDURE tickets.upsert_ticket_work_log(IN p_ticket_id bigint, IN p_status_id integer, IN p_assignee uuid, IN p_created_by uuid, INOUT message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_work_log_id INTEGER;
    v_existing_status_id INTEGER;
	v_completed_status_id INTEGER;
    v_is_completed BOOLEAN := false;
	v_dep_code TEXT;
	v_current_work_log_id INTEGER := 0;
BEGIN
    -- Check if ticket exists
    IF NOT EXISTS (SELECT 1 FROM tickets.ticket WHERE ticket_id = p_ticket_id) THEN
        message := 'Invalid ticket ID.';
        RETURN;
    END IF;		
	
	SELECT "DeptCode" INTO v_dep_code
			FROM master.department
			WHERE is_active = true AND "Name" = 'SALES TEAM';

    -- Get the last work log entry
    SELECT ticket_work_log_id, status_id
    INTO v_max_work_log_id, v_existing_status_id
    FROM tickets.ticket_work_log
    WHERE ticket_id = p_ticket_id AND is_active = true
    ORDER BY ticket_work_log_id DESC
    LIMIT 1;

	SELECT COALESCE(MAX(ticket_work_log_id), 0) + 1 INTO v_current_work_log_id FROM tickets.ticket_work_log;

    -- Insert Ticket Work Log
	INSERT INTO tickets.ticket_work_log (
		ticket_work_log_id,
		ticket_id,
		status_id,
		assignee,
		start_time,
		dep_code,
		is_active,
		created_date,
		created_by
	) VALUES (
		v_current_work_log_id,
		p_ticket_id,
		p_status_id,
		p_assignee,
		current_timestamp AT TIME ZONE 'UTC',
		v_dep_code,
		true,
		current_timestamp AT TIME ZONE 'UTC',
		p_created_by
	);
	
    message := 'Ticket work log record added.';
	IF v_max_work_log_id IS NOT NULL THEN
		-- Update previous end time
		UPDATE tickets.ticket_work_log
		SET end_time = current_timestamp AT TIME ZONE 'UTC', last_updated_date = current_timestamp AT TIME ZONE 'UTC', updated_by = p_created_by
		WHERE ticket_work_log_id = v_max_work_log_id;

		-- If same status is being inserted again (completed case)
		SELECT status_id INTO v_completed_status_id
			FROM master.status_code_master
			WHERE is_active = true AND type = 'ORDERSTATUS' AND name = 'Completed';

		IF p_status_id = v_completed_status_id THEN
			UPDATE tickets.ticket_work_log
			SET end_time = current_timestamp AT TIME ZONE 'UTC', last_updated_date = current_timestamp AT TIME ZONE 'UTC', updated_by = p_created_by
			WHERE ticket_work_log_id = v_current_work_log_id;			
		END IF;
		message := 'Ticket work log end time updated.';
	END IF;    
EXCEPTION
    WHEN OTHERS THEN
        message := CONCAT('Error occurred: ', SQLERRM);
END;
$$;


--
-- Name: work_load_by_users(date, date, integer, uuid, integer[], integer[], integer[], integer[], uuid[], integer[], integer[], integer[], integer[], integer[], integer[], integer[]); Type: FUNCTION; Schema: tickets; Owner: -
--

CREATE FUNCTION tickets.work_load_by_users(p_from_date date, p_to_date date, p_usertypeid integer, p_regid uuid, p_workspaceids integer[], p_boardids integer[] DEFAULT NULL::integer[], p_ordertype integer[] DEFAULT NULL::integer[], p_order_labels integer[] DEFAULT NULL::integer[], p_assignee uuid[] DEFAULT NULL::uuid[], p_order_stage_list integer[] DEFAULT NULL::integer[], p_regionids integer[] DEFAULT NULL::integer[], p_marketids integer[] DEFAULT NULL::integer[], p_countryids integer[] DEFAULT NULL::integer[], p_taskduestatus integer[] DEFAULT NULL::integer[], p_free_flow_label_id integer[] DEFAULT NULL::integer[], p_tool_id integer[] DEFAULT NULL::integer[]) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql
    AS $$

DECLARE 
v_from_date date;
v_to_date date;
ipo_id int;
v_completed_id int;
v_overdue_id int;
v_neardue_id int;
v_ontrack_id int;

BEGIN 
/*Created_by  : Mubarak Basha
Description : According to filters Assignee details fetch
*/

SELECT 
  MAX(
    CASE WHEN name = 'IPO' 
    AND type = 'ORDERLABEL' THEN status_id END
  ), 
  MAX(
    CASE WHEN name = 'Completed' 
    AND type = 'TASKDUESTATUS' THEN status_id END
  ), 
  MAX(
    CASE WHEN name = 'Overdue' 
    AND type = 'TASKDUESTATUS' THEN status_id END
  ), 
  MAX(
    CASE WHEN name = 'Near due' 
    AND type = 'TASKDUESTATUS' THEN status_id END
  ), 
  MAX(
    CASE WHEN name = 'On-track' 
    AND type = 'TASKDUESTATUS' THEN status_id END
  ) INTO ipo_id, 
  v_completed_id, 
  v_overdue_id, 
  v_neardue_id, 
  v_ontrack_id 
FROM 
  master.status_code_master 
WHERE 
  is_active = TRUE 
  AND type IN ('ORDERLABEL', 'TASKDUESTATUS');
-- ── DATE NORMALISATION ────────────────────────────────────────────────────────
v_from_date := LEAST (p_from_date, p_to_date);
v_to_date := GREATEST(p_from_date, p_to_date);
RETURN QUERY 
WITH 
  -- ── FINAL STAGE per board ─────────────────────────────────────────────────────
  final_stage AS MATERIALIZED (
    SELECT 
      DISTINCT ON (b."BoardID") b."BoardID" AS board_id, 
      bs."LabelID" AS last_label_id 
    FROM 
      board.board b 
      JOIN board.boardstatus bs ON bs."BoardID" = b."BoardID" 
      AND bs.is_active = TRUE 
    WHERE 
      b.is_active = TRUE 
    ORDER BY 
      b."BoardID", 
      bs."Position" DESC
  ), 
  -- ── BOARDS IN SCOPE ───────────────────────────────────────────────────────────
  scoped_boards AS MATERIALIZED (
    SELECT 
      b."BoardID" AS board_id 
    FROM 
      board.board b 
    WHERE 
      b.is_active = TRUE 
      AND b.work_space_id = ANY(p_workspaceids) 
      AND (
        p_boardids IS NULL 
        OR array_length(p_boardids, 1) IS NULL 
        OR b."BoardID" = ANY(p_boardids)
      )
  ), 
  -- ── POINT-IN-TIME SNAPSHOT per (tool_ticket_id, board_id) ────────────────────
 snapshot_log AS MATERIALIZED (
    SELECT DISTINCT ON (tbl.tool_ticket_id, tbl.board_id)
        tbl.tool_ticket_id,
        tbl.ticket_id,
        tbl.board_id,
        tbl.label_id,
        tbl.tool_board_logid,
        tbl.moved_date::date AS moved_date
    FROM  tickets.tool_board_log tbl
    -- Join tool_detail only when p_tool_id filter is active
    LEFT  JOIN tickets.tool_detail td
              ON  td.tool_ticket_id = tbl.tool_ticket_id
              AND td.is_active      = TRUE
              AND (
                  p_tool_id IS NULL
                  OR array_length(p_tool_id, 1) IS NULL
                  OR td.tool_id = ANY(p_tool_id)
              )
    WHERE tbl.is_active        = TRUE
      AND tbl.is_moved         = FALSE
      AND tbl.board_id        IN (SELECT board_id FROM scoped_boards)
      AND tbl.moved_date::date <= v_to_date
      -- When p_tool_id is passed, only keep rows where tool_detail matched
      AND (
          p_tool_id IS NULL
          OR array_length(p_tool_id, 1) IS NULL
          OR td.tool_ticket_id IS NOT NULL
      )
    ORDER BY tbl.tool_ticket_id, tbl.board_id, tbl.sequence DESC
),
  -- ── LATEST DUE DATE per subtask as of v_to_date ───────────────────────────────
  latest_due_date AS MATERIALIZED (
    SELECT 
      DISTINCT ON (tool_ticket_id) tool_ticket_id, 
      due_date :: date AS due_date 
    FROM 
      tickets.tool_duedate_log 
    WHERE 
      is_active = TRUE 
      AND created_date :: date <= v_to_date 
    ORDER BY 
      tool_ticket_id, 
      created_date DESC, 
      sequence DESC
  ), 
  -- ── TICKET LABEL ARRAY (single source of truth) ───────────────────────────────
  ticket_label_array AS MATERIALIZED (
    SELECT 
      t.ticket_id, 
    COALESCE(
	    CASE
	        WHEN tc.is_ipo = TRUE
	        THEN t.order_label_id || ARRAY[ipo_id]
	        ELSE t.order_label_id
	    END,
	    ARRAY[]::integer[]
	) AS full_label_array
    FROM 
      tickets.ticket t 
      LEFT JOIN LATERAL (
        SELECT 
          * 
        FROM 
          tickets.ticket_company tc 
        WHERE 
          tc.ticket_id = t.ticket_id 
          AND tc.is_active 
        ORDER BY 
          ticket_company_id DESC 
        LIMIT 
          1
      ) tc ON TRUE 
    WHERE 
      t.is_active = TRUE
  ), 
  -- ── SUBTASK SNAPSHOT DATA ─────────────────────────────────────────────────────
  subtask_data AS (
    SELECT 
      sl.tool_ticket_id AS task_id, 
      sl.ticket_id, 
      sl.board_id, 
      sl.label_id, 
      fs.last_label_id, 
	  td.free_flow_label_id,
	  td.tool_id,
      sl.moved_date, 
      t.order_type, 
      CASE WHEN ta.assignee_to IS NULL THEN ARRAY[] :: uuid[] ELSE ARRAY[ta.assignee_to] :: uuid[] END AS assignee_to, 
      tc.region_id, 
      tc.country_id, 
      t.primary_market, 
      COALESCE(ldd.due_date, td.due_date :: date) AS due_date, 
      tla.full_label_array
		||
		COALESCE(td.priority_id, ARRAY[]::integer[]) AS order_label
    FROM 
      snapshot_log sl 
      JOIN final_stage fs ON fs.board_id = sl.board_id 
      JOIN tickets.ticket t ON t.ticket_id = sl.ticket_id 
      AND t.is_active = TRUE 
      JOIN ticket_label_array tla ON tla.ticket_id = sl.ticket_id 
      LEFT JOIN tickets.ticket_company tc ON tc.ticket_id = t.ticket_id 
      AND tc.is_active = TRUE 
      LEFT JOIN latest_due_date ldd ON ldd.tool_ticket_id = sl.tool_ticket_id 
      LEFT JOIN tickets.tool_detail td ON td.tool_ticket_id = sl.tool_ticket_id 
      AND td.is_active = TRUE 
      LEFT JOIN LATERAL (
        SELECT 
          sta.assignee_to 
        FROM 
          tickets.tool_assignee sta 
        WHERE 
          sta.tool_board_logid = sl.tool_board_logid 
          AND sta.is_active = TRUE 
          AND COALESCE(sta.un_assigned_flag, FALSE) = FALSE 
        ORDER BY 
          sta.sequence DESC 
        LIMIT 
          1
      ) ta ON TRUE 
    WHERE 
      sl.label_id <> fs.last_label_id
  ), 
  -- ── MAINTASK SNAPSHOT DATA ────────────────────────────────────────────────────
  maintask_data AS (
    SELECT 
      t.ticket_id AS task_id, 
      t.ticket_id, 
      sl.board_id, 
	  NULL::integer[] AS free_flow_label_id,
	  --NULL::integer AS tool_id,
	  --ARRAY_AGG(DISTINCT td.tool_id) AS tool_id,
	  MIN(td.tool_id) AS tool_id,
      MAX(sl.label_id) FILTER (
        WHERE 
          sl.label_id <> fs.last_label_id
      ) AS label_id, 
      fs.last_label_id, 
      MAX(sl.moved_date) AS moved_date, 
      t.order_type, 
      COALESCE(ta.assignee_to, ARRAY[] :: uuid[]) AS assignee_to, 
      tc.region_id, 
      tc.country_id, 
      t.primary_market, 
      MIN(ldd.due_date) AS due_date, 
      tla.full_label_array
		||
		COALESCE(t.priority_id, ARRAY[]::integer[]) AS order_label
    FROM 
      snapshot_log sl 
      JOIN final_stage fs ON fs.board_id = sl.board_id 
      JOIN tickets.ticket t ON t.ticket_id = sl.ticket_id 
      AND t.is_active = TRUE 
      JOIN ticket_label_array tla ON tla.ticket_id = t.ticket_id 
      LEFT JOIN tickets.ticket_company tc ON tc.ticket_id = t.ticket_id 
      AND tc.is_active = TRUE 
      LEFT JOIN latest_due_date ldd ON ldd.tool_ticket_id = sl.tool_ticket_id 
	   LEFT JOIN tickets.tool_detail td ON td.tool_ticket_id = sl.tool_ticket_id 
      AND td.is_active = TRUE 
      LEFT JOIN (
        SELECT 
          mta.ticket_id, 
          ARRAY_AGG(DISTINCT mta.assignee_to) AS assignee_to 
        FROM 
          tickets.ticket_assignee mta 
        WHERE 
          mta.assignee_type = 'OB' 
          AND mta.is_active = TRUE 
        GROUP BY 
          mta.ticket_id
      ) ta ON ta.ticket_id = t.ticket_id 
    WHERE 
      sl.board_id IN (
        SELECT 
          board_id 
        FROM 
          scoped_boards
      ) 
    GROUP BY 
      t.ticket_id, 
      sl.board_id, 
      fs.last_label_id, 
      t.order_type, 
      tc.region_id, 
      tc.country_id, 
      t.primary_market, 
      ta.assignee_to, 
      tla.full_label_array 
    HAVING 
      COUNT(*) FILTER (
        WHERE 
          sl.label_id <> fs.last_label_id
      ) > 0
  ), 
  -- ── UNION ─────────────────────────────────────────────────────────────────────
  base_data AS (
    SELECT 
      'subtask' AS task_type, 
      task_id, 
      ticket_id, 
      board_id, 
      label_id, 
      last_label_id, 
	  free_flow_label_id,
	  tool_id,
      moved_date, 
      order_type, 
      assignee_to, 
      region_id, 
      country_id, 
      primary_market, 
      due_date, 
      order_label 
    FROM 
      subtask_data 
    UNION ALL 
    SELECT 
      'maintask' AS task_type, 
      task_id, 
      ticket_id, 
      board_id, 
      label_id, 
      last_label_id, 
	  free_flow_label_id,
	  tool_id,
      moved_date, 
      order_type, 
      assignee_to, 
      region_id, 
      country_id, 
      primary_market, 
      due_date, 
      order_label 
    FROM 
      maintask_data
  ), 
  -- ── FILTERS ───────────────────────────────────────────────────────────────────
  filtered_data AS (
    SELECT 
      * 
    FROM 
      base_data bd
    WHERE 
      (
        p_ordertype IS NULL 
        OR array_length(p_ordertype, 1) IS NULL 
        OR COALESCE(order_type && p_ordertype, FALSE)
      ) 
      AND (
        p_order_labels IS NULL 
        OR array_length(p_order_labels, 1) IS NULL 
        OR COALESCE(
          order_label && p_order_labels, FALSE
        )
      ) 
      AND (
        p_assignee IS NULL 
        OR array_length(p_assignee, 1) IS NULL 
        OR COALESCE(assignee_to && p_assignee, FALSE)
      ) 
      AND (
        p_order_stage_list IS NULL 
        OR array_length(p_order_stage_list, 1) IS NULL 
        OR label_id = ANY(p_order_stage_list)
      ) 
	AND (
		    p_free_flow_label_id IS NULL
		    OR array_length(p_free_flow_label_id,1) IS NULL
		    OR bd.task_type = 'maintask'
		    OR COALESCE(bd.free_flow_label_id && p_free_flow_label_id,FALSE)
		)
		AND (
			    p_tool_id IS NULL
			    OR array_length(p_tool_id, 1) IS NULL
			    OR bd.tool_id = ANY(p_tool_id)
			)
      AND (
        p_regionids IS NULL 
        OR array_length(p_regionids, 1) IS NULL 
        OR COALESCE(region_id && p_regionids, FALSE)
      ) 
      AND (
        p_countryids IS NULL 
        OR array_length(p_countryids, 1) IS NULL 
        OR COALESCE(country_id && p_countryids, FALSE)
      ) 
      AND (
        p_marketids IS NULL 
        OR array_length(p_marketids, 1) IS NULL 
        OR COALESCE(
          primary_market && p_marketids, FALSE
        )
      ) 
      AND (
        p_taskduestatus IS NULL 
        OR array_length(p_taskduestatus, 1) IS NULL 
        OR (
          (
            v_completed_id = ANY(p_taskduestatus) 
            AND label_id = last_label_id
          ) 
          OR (
            v_neardue_id = ANY(p_taskduestatus) 
            AND label_id <> last_label_id 
            AND due_date IS NOT NULL 
            AND due_date >= CURRENT_DATE 
            AND due_date <= CURRENT_DATE + INTERVAL '5 days'
          ) 
          OR (
            v_ontrack_id = ANY(p_taskduestatus) 
            AND label_id <> last_label_id 
            AND due_date IS NOT NULL 
            AND due_date > CURRENT_DATE + INTERVAL '5 days'
          ) 
          OR (
            v_overdue_id = ANY(p_taskduestatus) 
            AND label_id <> last_label_id 
            AND due_date IS NOT NULL 
            AND due_date < CURRENT_DATE
          )
        )
      )
  ), 
  
all_board_users AS (
    SELECT DISTINCT
        ubp.reg_id
    FROM users.user_board_permission ubp
    WHERE ubp.is_active = TRUE
      AND ubp.workspace_id = ANY(p_workspaceids)
      AND ubp.board_id IN (SELECT board_id FROM scoped_boards)
      AND (
            p_assignee IS NULL
            OR array_length(p_assignee,1) IS NULL
            OR ubp.reg_id = ANY(p_assignee)
      )
),
  -- ── WORKLOAD PER ASSIGNEE ─────────────────────────────────────────────────────
  workload_per_assignee AS (
    SELECT 
      assignee_uuid, 
      COUNT(DISTINCT task_id) FILTER (
        WHERE 
          task_type = 'subtask'
      ) AS subtask_workload, 
      COUNT(DISTINCT task_id) FILTER (
        WHERE 
          task_type = 'maintask'
      ) AS maintask_workload 
    FROM 
      (
        SELECT 
          fd.task_type, 
          fd.task_id, 
          UNNEST(
            CASE WHEN COALESCE(
              array_length(fd.assignee_to, 1), 
              0
            ) = 0 THEN ARRAY[NULL :: uuid] ELSE fd.assignee_to END
          ) AS assignee_uuid 
        FROM 
          filtered_data fd
      ) x 
    GROUP BY 
      assignee_uuid
  ), 
  -- ──  ASSIGNEE NAME —  ───────────────
workload_with_user AS (

    -- Board users
    SELECT
        abu.reg_id AS assignee_uuid,
        COALESCE(w.subtask_workload, 0) AS subtask_workload,
        COALESCE(w.maintask_workload, 0) AS maintask_workload,
        jsonb_build_array(
            jsonb_build_object(
                'name',  ru."DisplayName",
                'photo', ru.photo_url,
                'regId', ru."RegId"
            )
        ) AS assignee_info
    FROM all_board_users abu
    LEFT JOIN workload_per_assignee w
           ON w.assignee_uuid = abu.reg_id
    LEFT JOIN users.registereduser ru
           ON ru."RegId" = abu.reg_id
          AND ru.is_active = TRUE

    UNION ALL

    -- Unassigned
    SELECT
        NULL::uuid,
        COALESCE(w.subtask_workload, 0),
        COALESCE(w.maintask_workload, 0),
        jsonb_build_array(
            jsonb_build_object(
                'name', 'Unassigned',
                'photo', NULL,
                'regId', NULL
            )
        )
    FROM workload_per_assignee w
    WHERE w.assignee_uuid IS NULL
)

  -- ── FINAL OUTPUT ──────────────────────────────────────────────────────────────
SELECT 
  jsonb_build_object(
    'status', 
    TRUE, 
    'message', 
    'Workload by assignee fetched successfully', 
    'WorkloadByAssignee', 
    jsonb_build_array(
      jsonb_build_object(
        'taskByWorkload', 
        (
          SELECT 
            COALESCE(
              jsonb_agg(
                jsonb_build_object(
                  'workload', wu.subtask_workload, 
                  'assigneeName', wu.assignee_info
                ) 
                ORDER BY 
                  wu.subtask_workload DESC
              ), 
              '[]' :: jsonb
            ) 
          FROM 
            workload_with_user wu 
        ), 
        'ordersByWorkload', 
        (
          SELECT 
            COALESCE(
              jsonb_agg(
                jsonb_build_object(
                  'workload', wu.maintask_workload, 
                  'assigneeName', wu.assignee_info
                ) 
                ORDER BY 
                  wu.maintask_workload DESC
              ), 
              '[]' :: jsonb
            ) 
          FROM 
            workload_with_user wu 
        )
      )
    )
  );
END;
$$;


--
-- Name: add_agency_user(text, character varying, character varying, character varying, character varying, character varying, text, boolean, text); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.add_agency_user(IN in_user_id text, IN in_firstname character varying, IN in_lastname character varying, IN in_email character varying, IN in_agency_name character varying, IN in_country_code character varying, IN in_phone_number text DEFAULT NULL::text, INOUT status boolean DEFAULT NULL::boolean, INOUT message text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
    gen_uuid UUID;
    result_rows_affected INTEGER := 0;
	new_request_count INTEGER := 0;
	approved_request_count INTEGER := 0;
	rejected_request_count INTEGER := 0;
	already_euroland_employee INTEGER := 0;
	get_agency_id INTEGER DEFAULT 0 :: INTEGER; 
	get_country_id INTEGER DEFAULT 0 :: INTEGER; 
BEGIN
 
-- updated by Mubarak on 09-01-2025 to change the input of  in_agency_name and in_country_code
  select agency_id into get_agency_id from master.agency where lower(agency_name) = lower(in_agency_name) and is_active = true;
-- Raise info 'get_agency_id%', get_agency_id;
  IF ( get_agency_id IS NULL )  THEN
    status := false;
    message := 'Invalid agency name';
    RETURN;
END IF;
 
  select country_id into get_country_id from master.country_detail where lower(country_code) = lower(in_country_code) and is_active = true;
  -- Raise info 'get_country_id%', get_country_id;
  IF (get_country_id IS NULL) THEN
    status := false;
    message := 'Invalid country';
    RETURN;
  END IF;

  -- Check if the parameter email contains '@euroland.com'
  IF UPPER(in_email) LIKE UPPER('%@euroland.com') THEN
        -- Increment the count
        already_euroland_employee := already_euroland_employee + 1;
  END IF;
 
-- GET new_request_count for validation
SELECT COUNT(agency_user_id) INTO new_request_count FROM users.agency_user
WHERE UPPER(email)=UPPER(in_email) AND is_approval IS NULL AND is_active = 'false' ;
-- GET approved_request_count for validation
SELECT COUNT(agency_user_id) INTO approved_request_count FROM users.agency_user
WHERE  UPPER(email)=UPPER(in_email) AND is_approval = 'Approved' ;
-- GET rejected_request_count for validation
SELECT COUNT(agency_user_id) INTO rejected_request_count FROM users.agency_user
WHERE  UPPER(email)=UPPER(in_email) AND is_approval = 'Rejected' AND is_active = 'false';

IF(already_euroland_employee = 0 AND new_request_count = 0 AND approved_request_count = 0 AND rejected_request_count = 0 ) THEN
-- Generate a UUID
SELECT uuid_generate_v4() INTO gen_uuid;
 
    INSERT INTO  users.agency_user (
        agency_user_id,
        firstname,
        lastname,
        email,
		agency_id,
		country_id,
		is_requested_date,
		phone_number,
		is_active,
		created_by,
		created_date
    )
    VALUES(
	    gen_uuid,
        in_firstname,
        in_lastname,
		in_email,
		get_agency_id,
		get_country_id,
		current_timestamp AT TIME ZONE 'UTC',
		in_phone_number,
		'false',
		in_user_id,
		current_timestamp AT TIME ZONE 'UTC'				
   );
GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	--below function used to add the signupnotification to all admins	
		result_rows_affected := users.add_signup_request_notification_participants(gen_uuid,(in_firstname || ' ' || in_lastname));
 
		total_affected_rows := total_affected_rows + result_rows_affected;
 
    -- Set status and message based on the result
    IF total_affected_rows > 0 THEN
        status := 'true';
        message := 'New Agency User Created Successfully!';
   ELSE 
	    STATUS := 'false';
         MESSAGE := 'An Error Occured, Contact admin';
 
  END IF;
ELSE
    IF(already_euroland_employee > 0) THEN
	     STATUS := 'false';
         MESSAGE := 'Your are already euroland employee you cannot able to create the agency login'; 
    ELSIF (new_request_count > 0) THEN
         STATUS := 'false';
         MESSAGE := 'Your request is already in progress waiting for admin approval';
	ELSIF (approved_request_count > 0) THEN
	     STATUS := 'false';
         MESSAGE := 'Your email is already registered kindly use your registered userid and password';
	ELSIF (rejected_request_count > 0) THEN
	     STATUS := 'false';
         MESSAGE := 'Your signup request is rejected please contact admin';
	END IF;
END IF;
 
EXCEPTION
     WHEN OTHERS THEN
         GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
         ROLLBACK;       
		 status := 'false'; 
		 message := 'An error occurred while inserting the record.';
END;
$$;


--
-- Name: add_approve_reject_agency_user(uuid, integer, integer, text, text, boolean, boolean, text); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.add_approve_reject_agency_user(IN in_reg_id uuid, IN in_approval_type integer, IN in_agency_id integer, IN in_user_id text, IN in_remarks text DEFAULT NULL::text, IN in_is_active boolean DEFAULT NULL::boolean, INOUT status boolean DEFAULT NULL::boolean, INOUT message text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
    gen_uuid UUID;
	role_id integer;
	dept_id integer;
	max_user_workspace_id BIGINT;
	workspace_id integer;
	
BEGIN

 /*
 in_approval_type = 1  -- Approve
 in_approval_type = 2  -- Reject
 in_approval_type = 3  -- Active/Inactive Agent user
 */
 

 
 IF(in_approval_type = 1 OR in_approval_type = 2 ) THEN

  -- update the approval date
  UPDATE users.agency_user SET
     is_approval = CASE WHEN in_approval_type = 1 THEN 'Approved' WHEN in_approval_type = 2 THEN 'Rejected' END,
     approved_on = current_timestamp AT TIME ZONE 'UTC',
     approved_by = in_user_id ::uuid,
	 remarks = in_remarks,
	 is_active = CASE WHEN in_approval_type = 1 THEN true ELSE false END,
	 last_updated_date = current_timestamp AT TIME ZONE 'UTC',
	 updated_by = in_user_id
   WHERE agency_user_id = in_reg_id AND agency_id = in_agency_id;
   
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- Generate a UUID
   SELECT uuid_generate_v4() INTO gen_uuid;
   
   -- when admin approve the user that time only data will insert in users.registereduser table
   
   IF(in_approval_type = 1) THEN
   
  -- select member role as a default for new Agency user
 
 SELECT "RoleID" INTO role_id FROM master.role WHERE UPPER("Name") = UPPER('Member') AND is_active = 'true'; 
 
  -- select Agent Department as a default for new Agency user
 
 SELECT "DeptID" INTO dept_id FROM master.department WHERE UPPER("DeptCode") = UPPER('AG') AND is_active = 'true'; 
 
 --select the max id in updates.updates_customer table
 
 SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_workspace_id  FROM users.user_work_space;
 
 -- select agency workspace id as default for new Agency user
 SELECT work_space_id INTO workspace_id FROM master.work_space_master WHERE UPPER(code) = UPPER('AG') AND is_active ='true';
 
   
   -- Generate a UUID
   WITH selected_data AS (
       SELECT 
        email,
        (firstname || ' ' || lastname) AS displayname,
        phone_number
      FROM 
        users.agency_user  
      WHERE 
        agency_user_id = in_reg_id 
        AND agency_id = in_agency_id
      )
		   
	INSERT INTO users.registereduser
	(
    	"RegId",
    	"Email",
    	"DisplayName",
    	"GivenName",   
    	"MobilePhone",
		"IsRegistered",
		"IsHidden",
		"IsMailSent",
    	 user_type ,
		 is_active,
		 created_date,
		 created_by	
	)
	SELECT 
    gen_uuid,
    s.email,
    s.displayname,
    s.displayname,  
    s.phone_number,
	'true',
	'false',
	'false',
    'Agency',
	'true',
	current_timestamp AT TIME ZONE 'UTC',
	in_user_id
    FROM 
    selected_data s;
 
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- assign the user role
	 INSERT INTO users.userrole
	 (
		 "RegId",
		 "RoleID",
		  is_active,
		  created_date,
		  created_by	 
	 )
	 VALUES
	 (
		 gen_uuid,
		 role_id,
		 'true',
		 current_timestamp AT TIME ZONE 'UTC',
		 in_user_id
	 );
	 
	GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- assign the user department
	INSERT INTO users.userdepartment
	(
		"RegId",
		"DeptID",
		is_active,
		created_date,
		created_by	
	)
	VALUES(
		 gen_uuid,
		 dept_id,
		 'true',
		 current_timestamp AT TIME ZONE 'UTC',
		 in_user_id
	);
	
	GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- assign the user workspace default agent work space
	INSERT INTO users.user_work_space
	(
		user_work_space_id,
		work_space_id,
		reg_id,
		is_active,
		created_date,
		created_by	
	)
	VALUES
	(
		max_user_workspace_id,
		workspace_id,
		gen_uuid,
		'true',
		current_timestamp AT TIME ZONE 'UTC',
		in_user_id
	);
	
	GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- after insert the record in user.registereduser then update reg id in users.agency_user
    
	 UPDATE users.agency_user SET
	 reg_id = gen_uuid
     WHERE agency_user_id = in_reg_id AND agency_id = in_agency_id;
	 
	 GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
  END IF;
  -- 
  ELSIF(in_approval_type = 3 ) THEN
  
    UPDATE users.registereduser SET
	 is_active = in_is_active,
	 last_updated_date = current_timestamp AT TIME ZONE 'UTC',
	 updated_by = in_user_id
   WHERE "RegId" = in_reg_id ;
    
	GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
   
  END IF;

    -- Set status and message based on the result
    IF total_affected_rows > 0 THEN
	 IF (in_approval_type = 1) THEN
        status := 'true';
        message := 'User Approved Successfully!';
	  ELSIF(in_approval_type = 2) THEN
	    status := 'true';
        message := 'User Request Rejected!';
	  ELSE
	    status := 'true';
		IF(in_is_active = 'true') THEN
            message := 'User Activated Successfully!';
		ELSE
		    message := 'User In Active Successfully!';
		END IF;
	END IF;	
   ELSE 
      IF in_approval_type NOT IN (1,2,3) THEN
        status := 'false';
        message := 'Invalid approval type';
      ELSE
        status := 'false';
        message := 'An Error Occured, Contact admin';
      END IF;
  END IF;

 EXCEPTION
     WHEN OTHERS THEN
         GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
         ROLLBACK;       status := 'false'; 
END;
$$;


--
-- Name: add_approve_reject_agency_user_b2c(uuid, integer, integer, text, text, boolean, uuid, text, boolean, text); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.add_approve_reject_agency_user_b2c(IN in_reg_id uuid, IN in_approval_type integer, IN in_agency_id integer, IN in_user_id text, IN in_remarks text DEFAULT NULL::text, IN in_is_active boolean DEFAULT NULL::boolean, IN in_ad_uuid uuid DEFAULT NULL::uuid, IN in_password text DEFAULT NULL::text, INOUT status boolean DEFAULT NULL::boolean, INOUT message text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
    affected_rows INTEGER;
    total_affected_rows INTEGER := 0;
    gen_uuid UUID;
	role_id integer;
	dept_id integer;
	max_user_workspace_id BIGINT;
	workspace_id integer;
	
BEGIN

 /*
 in_approval_type = 1  -- Approve
 in_approval_type = 2  -- Reject
 in_approval_type = 3  -- Active/Inactive Agent user
 */
 

 
 IF(in_approval_type = 1 OR in_approval_type = 2 ) THEN

  -- update the approval date
  UPDATE users.agency_user SET
     is_approval = CASE WHEN in_approval_type = 1 THEN 'Approved' WHEN in_approval_type = 2 THEN 'Rejected' END,
	 password =case when in_approval_type = 1 THEN in_password WHEN in_approval_type = 2 THEN password END,
     approved_on = current_timestamp AT TIME ZONE 'UTC',
     approved_by = in_user_id ::uuid,
	 remarks = in_remarks,
	 is_active = CASE WHEN in_approval_type = 1 THEN true ELSE false END,
	 last_updated_date = current_timestamp AT TIME ZONE 'UTC',
	 updated_by = in_user_id
   WHERE agency_user_id = in_reg_id AND agency_id = in_agency_id;
   
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
	
	-- Generate a UUID
   SELECT uuid_generate_v4() INTO gen_uuid;
   
   -- when admin approve the user that time only data will insert in users.registereduser table
   
   IF(in_approval_type = 1) THEN
   
  -- select member role as a default for new Agency user
 
	 SELECT "RoleID" INTO role_id FROM master.role WHERE UPPER("Name") = UPPER('Member') AND is_active = 'true'; 
	 RAISE INFO 'select: %', role_id;

	  -- select Agent Department as a default for new Agency user

	 SELECT "DeptID" INTO dept_id FROM master.department WHERE UPPER("DeptCode") = UPPER('AG') AND is_active = 'true'; 
 RAISE INFO 'selectde: %', dept_id;
	 --select the max id in updates.updates_customer table

	 SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_workspace_id  FROM users.user_work_space;

	 -- select agency workspace id as default for new Agency user
	 SELECT work_space_id INTO workspace_id FROM master.work_space_master WHERE UPPER(code) = UPPER('AG') AND is_active ='true';

		   -- Generate a UUID
		   WITH selected_data AS (
			   SELECT 
				email,
				(firstname || ' ' || lastname) AS displayname,
			     firstname as givenname,
				phone_number
			  FROM 
				users.agency_user  
			  WHERE 
				agency_user_id = in_reg_id 
				AND agency_id = in_agency_id
			  )

			INSERT INTO users.registereduser
			(
				"RegId",
				"Email",
				"DisplayName",
				"GivenName",   
				"MobilePhone",
				"IsRegistered",
				"IsHidden",
				"IsMailSent",
				 user_type ,
				 is_active,
				 created_date,
				 created_by	
			)
			SELECT 
			in_ad_uuid,
			s.email,
			s.displayname,
			s.givenname,  
			s.phone_number,
			'true',
			'false',
			'false',
			'Agency',
			'true',
			current_timestamp AT TIME ZONE 'UTC',
			in_user_id
			FROM 
			selected_data s; 

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;
				 RAISE INFO 'select: %', role_id;
				 
 RAISE INFO 'selectaff: %', affected_rows;
			-- assign the user role
			 INSERT INTO users.userrole
			 (
				 "RegId",
				 "RoleID",
				  is_active,
				  created_date,
				  created_by	 
			 )
			 VALUES
			 (
				 in_ad_uuid,
				 role_id,
				 'true',
				 current_timestamp AT TIME ZONE 'UTC',
				 in_user_id
			 );

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;

			-- assign the user department
			INSERT INTO users.userdepartment
			(
				"RegId",
				"DeptID",
				is_active,
				created_date,
				created_by	
			)
			VALUES(
				 in_ad_uuid,
				 dept_id,
				 'true',
				 current_timestamp AT TIME ZONE 'UTC',
				 in_user_id
			);

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;

			-- assign the user workspace default agent work space
			INSERT INTO users.user_work_space
			(
				user_work_space_id,
				work_space_id,
				reg_id,
				is_active,
				created_date,
				created_by	
			)
			VALUES
			(
				max_user_workspace_id,
				workspace_id,
				in_ad_uuid,
				'true',
				current_timestamp AT TIME ZONE 'UTC',
				in_user_id
			);

			GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;

			-- after insert the record in user.registereduser then update reg id in users.agency_user

			 UPDATE users.agency_user SET
			 reg_id = in_ad_uuid
			 WHERE agency_user_id = in_reg_id AND agency_id = in_agency_id;

			 GET DIAGNOSTICS affected_rows = ROW_COUNT;
			total_affected_rows := total_affected_rows + affected_rows;
	
  END IF;
  -- 
  ELSIF(in_approval_type = 3 ) THEN
  
    UPDATE users.registereduser SET
	 is_active = in_is_active,
	 last_updated_date = current_timestamp AT TIME ZONE 'UTC',
	 updated_by = in_user_id
   WHERE "RegId" = in_reg_id ;
    
	GET DIAGNOSTICS affected_rows = ROW_COUNT;
    total_affected_rows := total_affected_rows + affected_rows;
   
  END IF;

    -- Set status and message based on the result
    IF total_affected_rows > 0 THEN
	 IF (in_approval_type = 1) THEN
        status := 'true';
        message := 'User Approved Successfully!';
	  ELSIF(in_approval_type = 2) THEN
	    status := 'true';
        message := 'User Request Rejected!';
	  ELSE
	    status := 'true';
		IF(in_is_active = 'true') THEN
            message := 'User Activated Successfully!';
		ELSE
		    message := 'User In Active Successfully!';
		END IF;
	END IF;	
   ELSE 
      IF in_approval_type NOT IN (1,2,3) THEN
        status := 'false';
        message := 'Invalid approval type';
      ELSE
        status := 'false';
        message := 'An Error Occured, Contact admin';
      END IF;
  END IF;

 EXCEPTION
     WHEN OTHERS THEN
         GET STACKED DIAGNOSTICS message = PG_EXCEPTION_CONTEXT;
         ROLLBACK;       status := 'false'; 
END;
$$;


--
-- Name: add_register_user_detail(uuid, text, bytea, text, text, text, text, text, text, text, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.add_register_user_detail(regid uuid, email text, photo bytea, jobtitle text, displayname text, givenname text, mobilephone text, officelocation text, preferredlanguage text, surname text, userprincipalname text, tenantid uuid, orgid uuid, createdby text, employeeid text, departmentid text) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offected integer;
BEGIN
         RAISE NOTICE 'regId-%',regid;
		 RAISE NOTICE 'regId-%',photo;
		if not exists(select * from users.registereduser where "RegId"=regid) then
			INSERT INTO users.registereduser("RegId", "Email", "Photo","JobTitle","DisplayName","GivenName","MobilePhone","OfficeLocation","PreferredLanguage","Surname","UserPrincipalName","TenantId","OrgId","IsRegistered", "IsHidden", "IsMailSent",is_active,created_date,created_by,employee_id,department)
			VALUES (
				regid,
				email,
				CAST(photo as bytea),
				jobtitle,
				displayname,
				givenname,
				mobilephone,
				officelocation,
				preferredlanguage,
				surname,
                userprincipalname,
				tenantid,
				orgid,
				'true',
				'false',
				'false',
				'true',
				current_timestamp,
				createdby,
				employeeid,
				departmentid
			);			
			
       end if;
	get diagnostics offected = ROW_COUNT;   
	IF(offected>0)
      THEN
		  return query select 'User have been added successfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'User Registration failed' as message,'false'::boolean as status;
	 END IF;
	 EXCEPTION
    WHEN others THEN
        -- Handle the exception
        ROLLBACK;
        message := 'Error inserting data';
        status := false;
END;
$$;


--
-- Name: add_signup_request_notification_participants(uuid, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.add_signup_request_notification_participants(user_id uuid, user_name text) RETURNS integer
    LANGUAGE plpgsql
    AS $$

--Created By : syed abdhahir.I
--Purpose : Used to get signUp notification 
DECLARE
uuid_list UUID[] :='{}'; --Initialize as an empty array 
rows_affected INTEGER;
max_notification_id BIGINT;
BEGIN

--get the only admin user list for signup notification

      SELECT 
	   array_agg(r."RegId") INTO uuid_list	
	   FROM users.registereduser r
       JOIN users.userrole ur ON ur."RegId" = r."RegId" AND ur.is_active ='true'
       JOIN master.role mr ON mr."RoleID"=ur."RoleID" AND mr.is_active ='true'
	   WHERE mr."Name"= 'Admin' AND r.is_active ='true';

IF uuid_list IS NOT NULL AND array_length(uuid_list, 1) > 0  THEN
		FOR i IN 1..COALESCE(array_upper(uuid_list, 1), 0) 
	LOOP
	SELECT COALESCE(MAX(notification_id), 0) + 1 INTO max_notification_id  FROM master.notification;
				INSERT INTO master.notification (	
					notification_id,
	                notified_by,
					notified_to,
					"message",
					status,
					"type",
					created_by,
					created_date,
					is_active
				)
	            VALUES 
				(    
					max_notification_id,
					user_id,
					uuid_list[i],
				    user_name ||' Raised the signup Request ' || '.',
	                0,
					'agency signup request',       
				    user_id,          
					current_timestamp AT TIME ZONE 'UTC',           
				   'true'                    
				);
			-- Get the number of affected rows
            GET DIAGNOSTICS rows_affected = ROW_COUNT;
           		
	END LOOP;
  END IF;	   
 RETURN rows_affected;
END;
$$;


--
-- Name: add_tool(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.add_tool(tool_data jsonb) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    offected integer;
    tool_item jsonb;
	inserted_tool_id int;
	inserted_version_id int;
	toolid int;   
	toolname text;
	toolcode text;
    platform_ids INT[];
    country_ids INT[];
    subscription_plan_ids INT[];
    tool_category INT;
    tool_status INT;
    primary_owner UUID;
    secondary_owner UUID;
    versionname text;
    description text;
    key_highlights text;
	tool_templateid int;
	is_dependency_requireds boolean;
	is_updateteam_dependencies boolean;
	is_analyse_dependencies boolean;
	is_tsr_dependencies boolean;
BEGIN
/*
Sample input Json format
	'{
           "toolid":1,
           "toolname": "Sample",
		   "toolcode": "SM";
           "platform": [1, 2],
           "country": [1,2,3],
           "subscription_plan": [1,3],
           "tool_category": 2,
           "status": 2,
           "primary_owner": "dae41c8c-d406-447f-8e14-7c0e4bdcf9f5",
           "secondary_owner": "b5595ae1-745b-43c0-bd9c-ec2af69e8d7b",
           "version": "1.0.1",
           "description": "sampletest",
           "key_highlights": "sampletestkeyhighlights"
     }'
*/
--Get the data from JSON
    toolid := (tool_data->>'toolid')::INT;
    toolname := tool_data->>'toolname';
	toolcode := tool_data->>'toolcode';
    platform_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'platform')::INT);
    country_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'country')::INT);
    subscription_plan_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'subscription_plan')::INT);
    tool_category := (tool_data->>'tool_category')::INT;
    tool_status := (tool_data->>'status')::INT;
    IF (tool_data->>'primary_owner') <> '' AND LENGTH(tool_data->>'primary_owner') = 36 AND (tool_data->>'primary_owner') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'  THEN primary_owner := (tool_data->>'primary_owner')::UUID; END IF;
    IF (tool_data->>'secondary_owner') <> '' AND LENGTH(tool_data->>'secondary_owner') = 36 AND (tool_data->>'secondary_owner') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN secondary_owner := (tool_data->>'secondary_owner')::UUID; END IF;
    versionname := tool_data->>'version';
    description := tool_data->>'description';
    key_highlights := tool_data->>'key_highlights';	
	is_dependency_requireds := tool_data->>'is_dependency_required';
	is_updateteam_dependencies := tool_data->>'is_updateteam_dependency';
	is_analyse_dependencies := tool_data->>'is_analyse_dependency';
	is_tsr_dependencies := tool_data->>'is_tsr_dependency';
	--Insert into tool table 
	IF NOT EXISTS(SELECT * FROM master.tool WHERE TRIM(LOWER("ToolName"))=TRIM(LOWER(toolname))) THEN
	        SELECT tool_template_id INTO tool_templateid FROM master.tool_template_master WHERE is_active = 'true' AND template_type ='Default';
		
			INSERT INTO master.tool("ToolCode","About","ToolName",is_active,description,keyhighlight,primary_user_id,secondary_user_id,status_id,tool_category_id,created_date,created_by,is_dependency_required,is_updateteam_dependency,is_analyse_dependency,is_tsr_dependency)
			VALUES(
				toolcode,
				description,
				toolname,
				'true',
				description,
				key_highlights,
				CASE WHEN primary_owner = '00000000-0000-0000-0000-000000000000' THEN NULL WHEN primary_owner IS NULL THEN NULL ELSE primary_owner END,
	            CASE WHEN secondary_owner = '00000000-0000-0000-0000-000000000000' THEN NULL WHEN secondary_owner IS NULL THEN NULL ELSE secondary_owner END,
				tool_status,
				tool_category,
				current_timestamp,
				'Admin',
				is_dependency_requireds,
				is_updateteam_dependencies,
				is_analyse_dependencies,
				is_tsr_dependencies
			)
			 RETURNING "ToolID"
			INTO inserted_tool_id;
			INSERT INTO master.tool_template (tool_id,is_active,created_date,created_by,tool_template_id)
			VALUES
			(
				inserted_tool_id
				,'true'
				,current_timestamp
				,'Admin'
				,tool_templateid
			);
			RAISE info 'tool entered';
       -- Insert into version table
		IF versionname IS NOT NULL AND LENGTH(versionname) > 0 THEN
		   IF NOT EXISTS(SELECT * FROM master.toolversion WHERE TRIM(LOWER("version_name"))=TRIM(LOWER(versionname)) AND tool_id=inserted_tool_id AND is_active='true') THEN
		      INSERT INTO master.toolversion (tool_id,version_name,is_active,created_date,created_by)
		      VALUES(inserted_tool_id,versionname,'true',current_timestamp,'Admin')
		      RETURNING "tool_version_id"
		      INTO inserted_version_id;
		   END IF;
		END IF;
		
		-- Update the version id in tool table
		IF inserted_version_id IS NOT NULL AND inserted_version_id <> 0 THEN
		   UPDATE master.tool SET tool_version_id = inserted_version_id
		   WHERE "ToolID" = inserted_tool_id AND is_active = 'true';
		END IF;
		
		-- Insert and Update Primary  in Usertool table
		IF primary_owner IS NOT NULL AND primary_owner <> '00000000-0000-0000-0000-000000000000' THEN
		  IF NOT EXISTS(SELECT 1 FROM users.usertool WHERE "RegId" = primary_owner AND "ToolID" = inserted_tool_id AND is_active='true') THEN
		     INSERT INTO users.usertool("RegId", "ToolID", is_active,created_date,created_by)
             SELECT primary_owner,inserted_tool_id, 'true',current_timestamp,'Admin';
		  END IF;
		END IF;
		-- Insert and Update Secondary  in Usertool table
		IF secondary_owner IS NOT NULL AND secondary_owner <> '00000000-0000-0000-0000-000000000000' THEN
		  IF NOT EXISTS(SELECT 1 FROM users.usertool WHERE "RegId" = secondary_owner AND "ToolID" = inserted_tool_id AND is_active='true') THEN
		     INSERT INTO users.usertool("RegId", "ToolID", is_active,created_date,created_by)
             SELECT secondary_owner,inserted_tool_id, 'true',current_timestamp,'Admin';
		  END IF;
		END IF;
		-- Insert data into the tool platform table if it matches the platform table.
		RAISE info 'tool platform entered';
		IF platform_ids IS NOT NULL AND array_length(platform_ids, 1) > 0 THEN
           INSERT INTO users.toolplatform(tool_id, platform_id, is_active,created_date,created_by)
           SELECT inserted_tool_id, CAST(plat AS INTEGER), 'true',current_timestamp,'Admin'
           FROM UNNEST(platform_ids) AS plat
		   JOIN master.platform p on p.platform_id = CAST(plat AS INTEGER) and p.is_active =true;
        END IF;
		
		-- Insert data into the toolcountryregion table if it matches the country table.
		RAISE info 'tool country region entered';
        IF country_ids IS NOT NULL AND array_length(country_ids, 1) > 0 THEN
             INSERT INTO users.toolcountryregion(tool_id, country_id, is_active,created_date,created_by)
        	 SELECT inserted_tool_id, CAST(countryid AS INTEGER), 'true',current_timestamp,'Admin'
        	 FROM UNNEST(country_ids) AS countryid
			 JOIN master.country c on c."CountryID" = CAST(countryid AS INTEGER) AND c."is_active"=true;
		END IF;	
		
		-- Insert data into the toolsubscription table if it matches the subscriptiontype table.
		RAISE info 'tool Subscription entered';
        IF subscription_plan_ids IS NOT NULL AND array_length(subscription_plan_ids, 1) > 0 THEN
        	INSERT INTO users.toolsubscription(tool_id, subscription_type_id, is_active,created_date,created_by)
        	SELECT inserted_tool_id, CAST(subscriptionid AS INTEGER), 'true',current_timestamp,'Admin'
        	FROM UNNEST(subscription_plan_ids) AS subscriptionid
			JOIN master.subscriptiontype c on c."id" = CAST(subscriptionid AS INTEGER) AND c.is_active = true;	 
		END IF;	
	get diagnostics offected = ROW_COUNT;   
	IF(offected>0)
    THEN
		  return query select 'Tool added successfully' as message,'true'::boolean as status;
    ELSE 
	      return query select 'Tool added failed' as message,'false'::boolean as status;
    END IF;
	ELSE 
	 return query select 'Tool name already exists' as message,'false'::boolean as status;																						
END IF;	
	-- Handle the exception
	EXCEPTION
    WHEN others THEN
     
        ROLLBACK;
        message := 'Error inserting data';
        status := false; 
END;
$_$;


--
-- Name: add_user_profile(integer, uuid, integer, text, boolean, integer, text, boolean, integer, integer, uuid, text, time without time zone, time without time zone, integer, character varying, character varying); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.add_user_profile(IN p_user_profile_id integer DEFAULT 0, IN p_user_id uuid DEFAULT NULL::uuid, IN p_team_id integer DEFAULT NULL::integer, IN p_team_name text DEFAULT NULL::text, IN p_isnew_team boolean DEFAULT false, IN p_designation_id integer DEFAULT NULL::integer, IN p_designation_name text DEFAULT NULL::text, IN p_isnew_designation boolean DEFAULT false, IN p_country_id integer DEFAULT NULL::integer, IN p_user_type_id integer DEFAULT NULL::integer, IN p_added_by uuid DEFAULT NULL::uuid, IN p_registered_users text DEFAULT NULL::text, IN p_shift_from_hour time without time zone DEFAULT NULL::time without time zone, IN p_shift_to_hour time without time zone DEFAULT NULL::time without time zone, INOUT new_user_profile_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_isnew_user boolean := (p_user_profile_id = 0);
    v_max_user_profile_id integer := 0;
    v_team_id integer := p_team_id;
    v_designation_id integer := p_designation_id;
    v_context text;
    v_registered_users JSONB := p_registered_users::JSONB;
    v_max_team_id integer := 0;
    v_max_designation_id integer := 0;
    v_shift_from_interval interval;
    v_shift_to_interval   interval;
BEGIN
    -- Created By: Aravindhan | Date: 13/08/2025 | Purpose: add/edit user profile

    v_shift_from_interval := CASE 
        WHEN p_shift_from_hour IS NOT NULL THEN
            make_interval(
                hours => EXTRACT(HOUR FROM p_shift_from_hour)::int,
                mins  => EXTRACT(MINUTE FROM p_shift_from_hour)::int
            )
        ELSE NULL 
    END;

    v_shift_to_interval := CASE 
        WHEN p_shift_to_hour IS NOT NULL THEN
            make_interval(
                hours => EXTRACT(HOUR FROM p_shift_to_hour)::int,
                mins  => EXTRACT(MINUTE FROM p_shift_to_hour)::int
            )
        ELSE NULL 
    END;

    -- Check if user with same reg_id already exists
    
    IF v_isnew_user AND EXISTS (
        SELECT 1 FROM users.userprofile 
        WHERE user_id = p_user_id AND is_active = true
    ) THEN
        status := 'false';
        message := 'User already exists with the given regId.';
        RETURN;
    END IF;

    -- Add new team if requested
    IF p_isnew_team THEN
        SELECT team_id
        INTO v_team_id
        FROM master.team
        WHERE LOWER(TRIM(name)) = LOWER(TRIM(p_team_name))
        LIMIT 1;
        
        IF v_team_id IS NULL THEN
            SELECT COALESCE(MAX(team_id), 0) + 1 INTO v_max_team_id
            FROM master.team;
        
            INSERT INTO master.team (
                team_id, name, code, is_active, created_date, created_by
            ) VALUES (
                v_max_team_id,
                TRIM(p_team_name),
                TRIM(p_team_name),
                TRUE,
                current_timestamp AT TIME ZONE 'UTC',
                p_added_by
            )
            RETURNING team_id INTO v_team_id;
        ELSE
            status := 'false';
            message := 'Team name already exists.';
            RETURN;
        END IF;
    END IF;

     -- Add new designation if requested
    IF p_isnew_designation THEN
        SELECT designation_id
        INTO v_designation_id
        FROM master.designation
        WHERE LOWER(TRIM(name)) = LOWER(TRIM(p_designation_name)) 
          AND team_id = v_team_id
        LIMIT 1;
        
        IF v_designation_id IS NULL THEN
            SELECT COALESCE(MAX(designation_id), 0) + 1 INTO v_max_designation_id
            FROM master.designation;
            
            INSERT INTO master.designation (
                designation_id, name, team_id, code, is_active, created_date, created_by
            ) VALUES (
                v_max_designation_id,
                TRIM(p_designation_name),
                v_team_id,
                TRIM(p_designation_name),
                TRUE,
                current_timestamp AT TIME ZONE 'UTC',
                p_added_by
            )
            RETURNING designation_id INTO v_designation_id;
        ELSE
            status := 'false';
            message := 'Designation name already exists with the given team.';
            RETURN;
        END IF;
    END IF;

    --Add new user
    IF p_user_profile_id = 0 THEN
        RAISE INFO 'Registered Users JSON: %', v_registered_users::text;

        -- Insert into registereduser if not exists
        IF v_registered_users IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 
                FROM users.registereduser 
                WHERE "RegId" = (v_registered_users->>'id')::uuid
            ) THEN
                INSERT INTO users.registereduser (
                    "RegId", "Email", "JobTitle", "DisplayName", "GivenName",
                    "MobilePhone", "OfficeLocation", "PreferredLanguage", "Surname",
                    "UserPrincipalName", "TenantId", "OrgId", "IsRegistered", "IsHidden", 
                    "IsMailSent", is_active, created_date, created_by,
                    employee_id, department, photo_url
                )
                VALUES (
                    (v_registered_users->>'id')::uuid,
                    v_registered_users->>'mail',				
                    v_registered_users->>'jobTitle',
                    v_registered_users->>'displayName',
                    v_registered_users->>'givenName',
                    v_registered_users->>'mobilePhone',
                    v_registered_users->>'officeLocation',
                    v_registered_users->>'preferredLanguage',
                    v_registered_users->>'surname',
                    v_registered_users->>'userPrincipalName',
                    NULLIF(v_registered_users->>'tenantId', '')::uuid,
                    NULLIF(v_registered_users->>'orgId', '')::uuid,
                    TRUE, FALSE, FALSE, TRUE,
                    current_timestamp AT TIME ZONE 'UTC', 
                    'Admin',
                    NULLIF(v_registered_users->>'employee_id', ''),
                    NULLIF(v_registered_users->>'department', ''),
                    v_registered_users->>'photo_url'				
                );
            END IF;
        END IF;
        
        -- Get next user_profile_id
        SELECT COALESCE(MAX(user_profile_id), 0) + 1 INTO v_max_user_profile_id
        FROM users.userprofile;
		
        -- Insert into userprofile
        IF NOT EXISTS (
            SELECT 1 
            FROM users.userprofile 
            WHERE user_id = p_user_id
        ) THEN
            INSERT INTO users.userprofile (
                user_profile_id,
                user_id,
                team_id,
                designation_id,
                country_id,
                user_type_id,
                "ShiftFromHour",
                "ShiftToHour",
                is_active,
                created_date,
                created_by
            ) VALUES (
                v_max_user_profile_id,
                p_user_id,
                v_team_id,
                v_designation_id,
                p_country_id,
                p_user_type_id,
                v_shift_from_interval,
                v_shift_to_interval,
                true,
                current_timestamp AT TIME ZONE 'UTC',
                p_added_by
            )
            RETURNING user_profile_id INTO new_user_profile_id;

            status := 'true';
            message := 'User added successfully.';
        ELSE
            status := 'false';
            message := 'Already registered with this user.';
            RETURN;
        END IF;

   -- Update existing user
    ELSE
        UPDATE users.userprofile
        SET
            team_id = v_team_id,
            designation_id = v_designation_id,
            country_id = p_country_id,
            "ShiftFromHour" = v_shift_from_interval,
            "ShiftToHour" = v_shift_to_interval,
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE user_profile_id = p_user_profile_id
        RETURNING user_profile_id INTO new_user_profile_id;

        status := 'true';
        message := 'User updated successfully.';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'users.add_user_profile',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_user_profile_id, p_user_id, p_team_id, p_team_name, p_isnew_team,
                p_designation_id, p_designation_name, p_isnew_designation,
                p_country_id, p_user_type_id, p_shift_from_hour, p_shift_to_hour, p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: add_user_registration(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.add_user_registration(user_data jsonb) RETURNS TABLE(message text, status boolean, regid uuid, photo bytea)
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_item jsonb;
    workspace jsonb;
    max_user_work_space_id BIGINT;
BEGIN
    -- Iterate through the registered users
    FOR user_item IN SELECT * FROM jsonb_array_elements(user_data->'registeredusers')
    LOOP
        RAISE NOTICE 'User: %', user_item->>'id';
        
        IF NOT EXISTS (SELECT 1 FROM users.registereduser WHERE "RegId" = (user_item->>'id')::uuid AND is_active = 'true') THEN
            -- Insert into registereduser table
            INSERT INTO users.registereduser(
                "RegId", "Email", "Photo", "JobTitle", "DisplayName", "GivenName",
                "MobilePhone", "OfficeLocation", "PreferredLanguage", "Surname",
                "UserPrincipalName", "TenantId", "OrgId", "IsRegistered", "IsHidden", 
                "IsMailSent", is_active, created_date, created_by, employee_id, department
            )
            VALUES (
                (user_item->>'id')::uuid,
                user_item->>'mail',
                (decode(user_item->>'Photo', 'base64'))::bytea,
                user_item->>'jobTitle',
                user_item->>'displayName',
                user_item->>'givenName',
                user_item->>'mobilePhone',
                user_item->>'officeLocation',
                user_item->>'preferredLanguage',
                user_item->>'surname',
                user_item->>'userPrincipalName',
                (user_item->>'tenantId')::uuid,
                (user_item->>'orgId')::uuid,
                'true', 'false', 'false', 'true', 
                current_timestamp, 'Admin', 
                user_item->>'employee_id', 
                user_item->>'department'
            );

            -- Insert into userdepartment table
            INSERT INTO users.userdepartment("RegId", "DeptID", is_active, created_date, created_by)
            SELECT CAST(user_item->>'id' AS uuid), CAST(dept AS INTEGER), 'true', current_timestamp, 'Admin'
            FROM jsonb_array_elements(user_data->'departments') AS dept
            JOIN master.department mdept ON mdept."DeptID" = CAST(dept AS INTEGER);

            -- Insert into userrole table
            INSERT INTO users.userrole("RegId", "RoleID", is_active, created_date, created_by)
            SELECT CAST(user_item->>'id' AS uuid), CAST(roleid AS INTEGER), 'true', current_timestamp, 'Admin'
            FROM jsonb_array_elements(user_data->'roles') AS roleid
            JOIN master.role r ON r."RoleID" = CAST(roleid AS INTEGER);

           
            SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_work_space_id FROM users.user_work_space;

            -- Insert into user_work_space table
            FOR workspace IN SELECT * FROM jsonb_array_elements(user_data->'workspaces')
            LOOP
                RAISE NOTICE 'Workspace ID: %', workspace;
                INSERT INTO users.user_work_space (
                    user_work_space_id, reg_id, work_space_id, is_active, created_date, created_by
                )
                VALUES (
                    max_user_work_space_id,
                    CAST(user_item->>'id' AS uuid),
                    CAST(workspace AS INTEGER),
                    'true',
                    current_timestamp,
                    'Admin'
                );
                max_user_work_space_id := max_user_work_space_id + 1; -- Increment for next workspace
            END LOOP;

            -- Return successful insertion record
            RETURN QUERY 
            SELECT 
                'User has been added successfully' AS message,
                'true'::boolean AS status,
                (user_item->>'id')::uuid AS regid,
                (decode(user_item->>'Photo', 'base64'))::bytea AS photo;

        ELSE
            -- Return record already exists
            RETURN QUERY 
            SELECT 
                'User already exists or inactive' AS message,
                'false'::boolean AS status,
                (user_item->>'id')::uuid AS regid,
                (decode(user_item->>'Photo', 'base64'))::bytea AS photo;
        END IF;
    END LOOP;

    -- If no records processed, return a default message
    IF NOT FOUND THEN
        RETURN QUERY 
        SELECT 
            'No users were processed' AS message,
            'false'::boolean AS status,
            NULL::uuid AS regid,
            NULL::bytea AS photo;
    END IF;

    RETURN;
	 EXCEPTION
     WHEN OTHERS THEN
      --  Handle any exceptions
         RAISE NOTICE 'Error during insert: %', SQLERRM;
         RETURN QUERY 
         SELECT 
            'Error inserting data' AS message,
            false AS status,
             NULL::uuid AS regid,
             NULL::bytea AS photo;
END;
$$;


