--
-- Name: delete_tool(integer, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.delete_tool(toolid integer, updatedby text) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
-- Created by  || Craeted Date  || Purpose
--   Naveen S  || 21-11-2023    || Archive the tool details
BEGIN
	   IF toolid IS NOT NULL AND toolid <>0  
	   THEN  
	      IF EXISTS(SELECT 1 FROM master.tool WHERE "ToolID"=toolid and is_active='true') 
	      THEN
			 UPDATE master.tool SET 
			 is_active='false',
			 last_updated_date = current_timestamp,
			 updated_by = updatedby 
			 WHERE "ToolID"=toolid 
			 AND is_active ='true';
			 return query select 'Tool Archived Successfully' as message,'true'::boolean as status;
	      ELSE 
	         return query select 'Tool not found or could not be deleted' as message,'false'::boolean as status;
	      END IF; 
		ELSE 
		   return query select 'Tool not found or could not be deleted' as message,'false'::boolean as status;
		END IF;
END;
$$;


