    LANGUAGE plpgsql
    AS $$
BEGIN	
IF EXISTS (SELECT "RegId" FROM users.registereduser WHERE "RegId" = UUID(regid))
THEN
	DELETE FROM users.userdepartment WHERE "RegId"= UUID(regid);
	DELETE FROM users.userrole WHERE "RegId"= UUID(regid);
	DELETE FROM users.registereduser WHERE "RegId"= UUID(regid);
END IF;
END;
$$;


--
-- Name: editorviewteamdetail(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.editorviewteamdetail(rregid character varying) RETURNS TABLE(regid uuid, photo bytea, displayname text, givenname text, empcode character varying, jobtitle text, email text, is_active boolean, timezone text, shiftid integer, shifttype character varying, starttime text, endtime text, joiningdate timestamp without time zone, rolehierarchy integer, deptid integer, deptname character varying, toolid integer, toolname character varying, languageid integer, languagename character varying, roleid integer, rolename character varying, regionid integer, regionname character varying, countryid integer, countryname character varying, countrycode character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
	role_id integer ; 
	usertype character varying := null;
BEGIN
     -- updatedby   || updateddate   || purpose
     -- Naveen S    || 23-04-2024    || i have get the is_active status filed
	 -- Naveen S    || 23-04-2024    || i have remove condition is_active status
	 
	--select usertype
   SELECT user_type INTO usertype FROM users.registereduser WHERE "RegId" = UUID(rregid);
   
   IF (usertype is null OR usertype<> 'Agency') THEN
			return query
			SELECT ru."RegId", ru."Photo",ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle"
			       ,ru."Email",ru.is_active,('GMT') as timezone
				   ,s."ShiftId",s."Type",s."StartTime",s."EndTime",u."JoiningDate"
				   ,(SELECT * FROM master.get_heirachy_role(ur."RoleID")) rolehierarchy
				   ,udd."DeptID",d."Name",ut."ToolID",t."ToolName"
				   ,ul."LanguageID",l."Name",ur."RoleID",r."Name",
				   co."RegionID",re."Name",uc."CountryID",co."Name",co."CountryCode"			  
			FROM users.registereduser ru	  
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true' 
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID"  AND d.is_active='true' 
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID"))  AND u.is_active= 'true'
			LEFT JOIN users.usertool ut ON ru."RegId" = ut."RegId" AND ut.is_active='true'
			LEFT JOIN master.tool t ON ut."ToolID" = t."ToolID"  AND t.is_active = 'true' 
			LEFT JOIN users.userlanguage ul ON ru."RegId" = ul."RegId" AND ul.is_active='true'
			LEFT JOIN master.language l ON ul."LanguageID" = l."LanguageID" AND l.is_active='true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true' 
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			LEFT JOIN users.usercountryregion uc ON ru."RegId"= uc."RegId" AND uc.is_active='true'
			LEFT JOIN master.country co ON uc."CountryID"=co."CountryID"  AND co.is_active='true'
			LEFT JOIN master.region re ON co."RegionID" = re."RegionID" AND re.is_active = 'true'
			LEFT JOIN master.shift s ON u."ShiftId" = s."ShiftId" AND s.is_active = 'true'
			WHERE ru."RegId" = UUID(rregid);
ELSE

	return query
			SELECT ru."RegId", ru."Photo",ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle"
			       ,ru."Email",ru.is_active,('GMT') as timezone
				   ,s."ShiftId",s."Type",s."StartTime",s."EndTime",u."JoiningDate"
				   ,(SELECT * FROM master.get_heirachy_role(ur."RoleID")) rolehierarchy
				   ,udd."DeptID",d."Name",ut."ToolID",t."ToolName"
				   ,ul."LanguageID",l."Name",ur."RoleID",r."Name",
				   0::integer,NULL :: character varying,co.country_id,co.country_name,co.country_code			  
			FROM users.registereduser ru
			JOIN users.agency_user au ON au.reg_id = ru."RegId" 
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true' 
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID"  AND d.is_active='true' 
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID"))  AND u.is_active= 'true'
			LEFT JOIN users.usertool ut ON ru."RegId" = ut."RegId" AND ut.is_active='true'
			LEFT JOIN master.tool t ON ut."ToolID" = t."ToolID"  AND t.is_active = 'true' 
			LEFT JOIN users.userlanguage ul ON ru."RegId" = ul."RegId" AND ul.is_active='true'
			LEFT JOIN master.language l ON ul."LanguageID" = l."LanguageID" AND l.is_active='true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true' 
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			--LEFT JOIN users.usercountryregion uc ON ru."RegId"= uc."RegId" AND uc.is_active='true'
			LEFT JOIN master.country_detail co ON au.country_id=co.country_id  AND co.is_active='true'
			--LEFT JOIN master.region re ON co."RegionID" = re."RegionID" AND re.is_active = 'true'
			LEFT JOIN master.shift s ON u."ShiftId" = s."ShiftId" AND s.is_active = 'true'
			WHERE ru."RegId" = UUID(rregid);

END IF;
				  --AND ru.is_active = 'true';
END;
$$;


--
-- Name: editorviewteamdetail_mubarak(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.editorviewteamdetail_mubarak(rregid character varying) RETURNS TABLE(regid uuid, photo bytea, displayname text, givenname text, empcode character varying, jobtitle text, email text, is_active boolean, timezone text, shiftid integer, shifttype character varying, starttime text, endtime text, joiningdate timestamp without time zone, rolehierarchy integer, deptid integer, deptname character varying, toolid integer, toolname character varying, languageid integer, languagename character varying, roleid integer, rolename character varying, regionid integer, regionname character varying, countryid integer, countryname character varying, countrycode character varying, workspaceid integer, workspacename character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
	role_id integer ; 
	usertype character varying := null;
BEGIN
     -- updatedby   || updateddate   || purpose
     -- Naveen S    || 23-04-2024    || i have get the is_active status filed
	 -- Naveen S    || 23-04-2024    || i have remove condition is_active status
	 
	--select usertype
   SELECT user_type INTO usertype FROM users.registereduser WHERE "RegId" = UUID(rregid);
   
   IF (usertype is null OR usertype<> 'Agency') THEN
			return query
			SELECT ru."RegId", ru."Photo",ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle"
			       ,ru."Email",ru.is_active,('GMT') as timezone
				   ,s."ShiftId",s."Type",s."StartTime",s."EndTime",u."JoiningDate"
				   ,(SELECT * FROM master.get_heirachy_role(ur."RoleID")) rolehierarchy
				   ,udd."DeptID",d."Name",ut."ToolID",t."ToolName"
				   ,ul."LanguageID",l."Name",ur."RoleID",r."Name",
				   co."RegionID",re."Name",uc."CountryID",co."Name",co."CountryCode",
				   uw.work_space_id AS workspaceid, wm.name AS workspacename
			FROM users.registereduser ru	  
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true' 
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID"  AND d.is_active='true' 
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID"))  AND u.is_active= 'true'
			LEFT JOIN users.usertool ut ON ru."RegId" = ut."RegId" AND ut.is_active='true'
			LEFT JOIN master.tool t ON ut."ToolID" = t."ToolID"  AND t.is_active = 'true' 
			LEFT JOIN users.userlanguage ul ON ru."RegId" = ul."RegId" AND ul.is_active='true'
			LEFT JOIN master.language l ON ul."LanguageID" = l."LanguageID" AND l.is_active='true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true' 
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			LEFT JOIN users.usercountryregion uc ON ru."RegId"= uc."RegId" AND uc.is_active='true'
			LEFT JOIN master.country co ON uc."CountryID"=co."CountryID"  AND co.is_active='true'
			LEFT JOIN master.region re ON co."RegionID" = re."RegionID" AND re.is_active = 'true'
			LEFT JOIN master.shift s ON u."ShiftId" = s."ShiftId" AND s.is_active = 'true'
			LEFT JOIN users.user_work_space uw ON ru."RegId" = uw.reg_id AND uw.is_active = 'true'
            LEFT JOIN master.work_space_master wm ON uw.work_space_id = wm.work_space_id AND wm.is_active = 'true'
			WHERE ru."RegId" = UUID(rregid);
ELSE

	return query
			SELECT ru."RegId", ru."Photo",ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle"
			       ,ru."Email",ru.is_active,('GMT') as timezone
				   ,s."ShiftId",s."Type",s."StartTime",s."EndTime",u."JoiningDate"
				   ,(SELECT * FROM master.get_heirachy_role(ur."RoleID")) rolehierarchy
				   ,udd."DeptID",d."Name",ut."ToolID",t."ToolName"
				   ,ul."LanguageID",l."Name",ur."RoleID",r."Name",
				   0::integer,NULL :: character varying,co.country_id,co.country_name,co.country_code,
				   uw.work_space_id AS workspaceid, wm.name AS workspacename
			FROM users.registereduser ru
			JOIN users.agency_user au ON au.reg_id = ru."RegId" 
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true' 
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID"  AND d.is_active='true' 
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID"))  AND u.is_active= 'true'
			LEFT JOIN users.usertool ut ON ru."RegId" = ut."RegId" AND ut.is_active='true'
			LEFT JOIN master.tool t ON ut."ToolID" = t."ToolID"  AND t.is_active = 'true' 
			LEFT JOIN users.userlanguage ul ON ru."RegId" = ul."RegId" AND ul.is_active='true'
			LEFT JOIN master.language l ON ul."LanguageID" = l."LanguageID" AND l.is_active='true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true' 
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			--LEFT JOIN users.usercountryregion uc ON ru."RegId"= uc."RegId" AND uc.is_active='true'
			LEFT JOIN master.country_detail co ON au.country_id=co.country_id  AND co.is_active='true'
			--LEFT JOIN master.region re ON co."RegionID" = re."RegionID" AND re.is_active = 'true'
			LEFT JOIN master.shift s ON u."ShiftId" = s."ShiftId" AND s.is_active = 'true'
			LEFT JOIN users.user_work_space uw ON ru."RegId" = uw."reg_id" AND uw.is_active = 'true'
            LEFT JOIN master.work_space_master wm ON uw.work_space_id = wm.work_space_id AND wm.is_active = 'true'
			WHERE ru."RegId" = UUID(rregid);

END IF;
				  --AND ru.is_active = 'true';
END;
$$;


--
-- Name: get_agency_board_details(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_agency_board_details(userid uuid) RETURNS TABLE(boardid integer, name character varying, deptcode character varying, is_board_default boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE 
check_agency_user INTEGER :=0;
BEGIN
    -- Check if the user belongs to the department with DeptCode 'UT'
    IF EXISTS (
        SELECT 1 
        FROM users.userdepartment usd 
        JOIN master.department d ON usd."DeptID" = d."DeptID"
        WHERE UPPER(d."DeptCode") = 'AG' AND usd."RegId" = userid
    ) THEN
	
	   -- check user is agency or euroland employee	
	   SELECT COUNT("RegId") INTO check_agency_user FROM users.registereduser WHERE "RegId" = userid 
	   AND is_active ='true' AND user_type = 'Agency';
	   
	   IF(check_agency_user = 0) THEN
        -- Check if the user has any board mappings
        IF EXISTS (
            SELECT 1 
            FROM users.user_default_board uub
            WHERE uub.reg_id = userid
        ) THEN
            RETURN QUERY
           SELECT DISTINCT
				b."BoardID",
				b."Name" AS name,
				d."DeptCode" AS "deptCode",
				COALESCE(ubm.is_board_default, false) AS is_board_default
			FROM
				board.board b
			LEFT JOIN board.departmentboard db ON db."BoardID" = b."BoardID" and db.is_active = 'true'
			LEFT JOIN master.department d ON d."DeptID" = db."DeptID" AND d.is_active ='true'
			LEFT JOIN
				users.user_default_board ubm
				ON b."BoardID" = ubm.board_id
				AND ubm.reg_id  = userid AND ubm.is_active =true 
				WHERE UPPER(d."DeptCode") = 'AG'
				ORDER by b."Name" asc;
        ELSE
            RETURN QUERY
             SELECT 
				b."BoardID",
				b."Name" AS name,
				d."DeptCode" AS "deptCode",
				false AS is_board_default
			FROM
				board.board b
			LEFT JOIN board.departmentboard db ON db."BoardID" = b."BoardID" and db.is_active = 'true'
			LEFT JOIN master.department d ON d."DeptID" = db."DeptID" AND d.is_active ='true'
			WHERE UPPER(d."DeptCode") = 'AG'
		   ORDER by b."Name" asc;
             
        END IF;
		ELSE
		        -- Check if the user has any board mappings
        IF EXISTS (
            SELECT 1 
            FROM users.user_default_board uub
            WHERE uub.reg_id = userid
        ) THEN
            RETURN QUERY
           SELECT DISTINCT
				b."BoardID",
				b."Name" AS name,
				d."DeptCode" AS "deptCode",
				COALESCE(ubm.is_board_default, false) AS is_board_default
			FROM
				board.board b
			JOIN users.agency_user au ON au.reg_id = userid
			LEFT JOIN master.agency ag ON au.agency_id = ag.agency_id AND b."BoardID" = ag.board_id AND ag.is_active ='true'
			LEFT JOIN board.departmentboard db ON db."BoardID" = ag.board_id and db.is_active = 'true'
			LEFT JOIN master.department d ON d."DeptID" = db."DeptID" AND d.is_active ='true'
			LEFT JOIN
				users.user_default_board ubm
				ON b."BoardID" = ubm.board_id
				AND ubm.reg_id  = userid AND ubm.is_active =true 
				WHERE UPPER(d."DeptCode") = 'AG'
				ORDER by b."Name" asc;
        ELSE
            RETURN QUERY
             SELECT 
				b."BoardID",
				b."Name" AS name,
				d."DeptCode" AS "deptCode",
				false AS is_board_default
			FROM
				board.board b
			JOIN users.agency_user au ON au.reg_id = userid
			LEFT JOIN master.agency ag ON au.agency_id = ag.agency_id AND b."BoardID" = ag.board_id AND ag.is_active ='true'
			LEFT JOIN board.departmentboard db ON db."BoardID" = ag.board_id and db.is_active = 'true'
			LEFT JOIN master.department d ON d."DeptID" = db."DeptID" AND d.is_active ='true'
			WHERE UPPER(d."DeptCode") = 'AG'
		   ORDER by b."Name" asc;
		 END IF;
             
        END IF;
    END IF;
END;
$$;


--
-- Name: get_agency_user_approve_reject_mail_sender(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_agency_user_approve_reject_mail_sender(regid uuid) RETURNS TABLE(user_id uuid, user_name text, user_mail text, sender_email text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
	user_id uuid;
	user_name text;	
	user_mail text;
BEGIN
    user_id := cast(regid as uuid);

	RETURN query		 
    SELECT user_id
	,(firstname || ' ' || lastname)
	,email
	,email as sender_email 
	FROM users.agency_user 
	WHERE  agency_user_id = regid ;
END;		
$$;


--
-- Name: get_agency_user_details(integer, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_agency_user_details(in_type integer, in_user_id text) RETURNS TABLE(regid uuid, photo bytea, display_name text, given_name text, mail text, country_id integer, country_name character varying, agency_id integer, agency_name character varying, phone_number character varying, is_active boolean, approved boolean, rejected boolean, remarks character varying, dial_code character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN  

/*

 in_type -> 0 -> New Request
 in_type -> 1 -> Approve
 in_type -> 2 -> Reject

*/
     -- CreatedBy             ||  CreatedDate   || purpose
	 -- Malarkodi Jaganathan  ||  15-07-2024    || get the agency user detail based on type
	 
	-- get Approve Agency user detail	
	IF(in_type = 1) THEN
	  
	  RETURN QUERY
	
			SELECT 
			ru."RegId",
			ru."Photo" AS photo,
			ru."DisplayName" AS full_name,
			ru."GivenName" AS given_name,
			ru."Email",
			au.country_id,
			cd.country_name,
		    au.agency_id ,
			ag.agency_name,
			au.phone_number,
			ru.is_active,
			(CASE WHEN au.is_approval = 'Approved' THEN true ELSE false END),
			false,
			au.remarks ,
			cd.dial_code		
			FROM users.registereduser ru
			JOIN users.agency_user au ON ru."RegId" = au.reg_id AND au.is_active = 'true'
			JOIN master.country_detail cd  ON au.country_id = cd.country_id AND cd.is_active = 'true'
			JOIN master.agency ag ON ag.agency_id = au.agency_id AND ag.is_active = 'true'
			--WHERE ru.is_active ='true' 
			ORDER BY ru.created_date DESC;
			
	-- get reject Agency user detail
	ELSIF (in_type = 2) THEN
	
	  RETURN QUERY
	  
	        SELECT 
			au.agency_user_id,
			NULL::bytea AS photo,
			au.firstname || ' ' || au.lastname AS full_name,
			au.firstname || ' ' || au.lastname AS given_name,
			au.email,
			au.country_id,
			cd.country_name,
		    au.agency_id ,
			ag.agency_name,
			au.phone_number,
			au.is_active ,
			CASE WHEN au.is_approval = 'Approved' THEN true ELSE false END,
			CASE WHEN au.is_approval = 'Rejected' THEN true ELSE false END,
			au.remarks,
			cd.dial_code			
			FROM users.agency_user au
			JOIN master.country_detail cd  ON au.country_id = cd.country_id AND cd.is_active = 'true'
			JOIN master.agency ag ON ag.agency_id = au.agency_id AND ag.is_active = 'true'
			WHERE au.is_active ='false' AND au.is_approval = 'Rejected'
			ORDER BY au.last_updated_date DESC;
			
    -- get new request Agency user detail
	ELSE 
	
	  RETURN QUERY
	        SELECT 
			au.agency_user_id,
			NULL::bytea AS photo,
			au.firstname || ' ' || au.lastname AS full_name,
			au.firstname || ' ' || au.lastname AS given_name,
			au.email,
			au.country_id,
			cd.country_name,
		    au.agency_id ,
			ag.agency_name,
			au.phone_number,
			au.is_active ,
			CASE WHEN au.is_approval = 'Approved' THEN true ELSE false END,
			CASE WHEN au.is_approval = 'Approved' THEN true ELSE false END,
			au.remarks ,
			cd.dial_code			
			FROM users.agency_user au
			JOIN master.country_detail cd  ON au.country_id = cd.country_id AND cd.is_active = 'true'
			JOIN master.agency ag ON ag.agency_id = au.agency_id AND ag.is_active = 'true'
			WHERE  au.is_active ='false' AND au.is_approval IS NULL
			ORDER BY au.created_date DESC;
	    
	END IF;
END;

$$;


--
-- Name: get_agency_user_info(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_agency_user_info(in_reg_id uuid) RETURNS TABLE(email text, displayname text, firstname character varying, lastname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        au.email,
        (au.firstname || ' ' || au.lastname) AS displayname,
        au.firstname,
        au.lastname 
    FROM 
        users.agency_user au 
    WHERE 
        au.agency_user_id = in_reg_id;
END;
$$;


--
-- Name: get_board_request_mail_sender(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_board_request_mail_sender(regid uuid) RETURNS TABLE(user_id uuid, user_name text, user_mail text, sender text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
	user_id uuid;
	user_name text;	
	user_mail text;
BEGIN
    user_id := cast(regid as uuid);
	SELECT "GivenName", "Email"
    INTO user_name, user_mail
    FROM users.registereduser
    WHERE "RegId" = UUID(regid);
	RETURN query		 
    SELECT user_id
	,user_name
	,user_mail
	,ru."Email" as sender 
	FROM users.registereduser ru
	LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active='true'
	JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true'
	WHERE r."RoleID" in (1,2) AND ru.is_active = 'true';
END;		
$$;


--
-- Name: get_list_grid_view_tool_detail(integer, integer, integer[], integer[], integer[], text, text, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_list_grid_view_tool_detail(offsetno integer, page_size integer, toolcategoryid integer[] DEFAULT NULL::integer[], subscriptionid integer[] DEFAULT NULL::integer[], platformid integer[] DEFAULT NULL::integer[], order_by text DEFAULT NULL::text, order_type text DEFAULT NULL::text, search_text text DEFAULT NULL::text) RETURNS TABLE(toolid integer, toolname character varying, toolcode character varying, platform_name text, tool_version character varying, category character varying, subscription_name text, status_name character varying, primary_user_display_name text, primary_user_photo bytea, dept_user_photo jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE setnumber integer;
BEGIN
    /*
	if the user photo is not available, obtain it using the username putting the initial letter of the first and last names on display
	*/
    setnumber := (CASE WHEN offsetno=0 THEN offsetno ELSE  ((offsetno*page_size)+1) END);
 	search_text:= NULLIF(search_text, 'string');
	order_by:= NULLIF(order_by, 'string');
	order_type:= NULLIF(order_type, 'string');
	IF toolcategoryid = ARRAY[0] THEN
       toolcategoryid := null;
	END IF;
    IF subscriptionid = ARRAY[0] THEN
       subscriptionid := null;
    END IF;
   IF platformid = ARRAY[0] THEN
      platformid := null;
   END IF;
   RAISE INFO 'search%',search_text;
   IF search_text IS NOT NULL THEN
			return query
			SELECT t."ToolID",t."ToolName",t."ToolCode",STRING_AGG(distinct p.name,','),tv.version_name,tc.name,STRING_AGG(distinct st.name,','),
			s.name,ru1."DisplayName",ru1."Photo",COALESCE(
    (
        SELECT jsonb_agg(user_info)
        FROM (
            SELECT
                jsonb_build_object(
                    'displayname', ru2."DisplayName",
                    'photo', encode(ru2."Photo"::bytea, 'base64')
                ) AS user_info
            FROM master.tool t1
            LEFT JOIN users.usertool ut1 ON t1."ToolID" = ut1."ToolID" AND ut1.is_active = 'true'
            LEFT JOIN users.registereduser ru2 ON (ut1."RegId" = ru2."RegId" AND ru2.is_active = 'true')
            LEFT JOIN users.userrole ur1 ON ru2."RegId" = ur1."RegId" AND ur1.is_active = 'true'
            LEFT JOIN master.role r1 ON ur1."RoleID" = r1."RoleID" AND r1.is_active = 'true'
            WHERE t1."ToolID" = t."ToolID" AND ru2.is_active = 'true'
              AND LOWER(r1."Name") NOT IN ('superadmin', 'admin')
            GROUP BY ru2."DisplayName", ru2."Photo"
        ) AS subquery_alias
    ),
    '[]'::jsonb
) AS deptuser
			FROM master.tool t 
			LEFT JOIN master.toolversion tv ON t.tool_version_id = tv.tool_version_id AND tv.is_active ='true'
			LEFT JOIN users.toolplatform tp ON t."ToolID" = tp.tool_id AND tp.is_active ='true'
			LEFT JOIN master.platform p ON tp.platform_id = p.platform_id AND p.is_active = 'true'
			LEFT JOIN master.status s ON t.status_id = s.id AND s.is_active='true'
			LEFT JOIN users.toolsubscription ts ON t."ToolID" = ts.tool_id AND ts.is_active = 'true'
			LEFT JOIN master.subscriptiontype st ON ts.subscription_type_id = st.id and st.is_active ='true'
			LEFT JOIN master.toolcategory tc ON t.tool_category_id = tc.id AND tc.is_active ='true'
			LEFT JOIN users.usertool ut ON t."ToolID" = ut."ToolID" AND ut.is_active = 'true'
			LEFT JOIN users.registereduser ru1 ON t.primary_user_id = ru1."RegId" AND ru1.is_active = 'true'
			LEFT JOIN users.registereduser ru ON ut."RegId" = ru."RegId" AND ru.is_active = 'true'
		    LEFT JOIN users.userdepartment ud ON ru."RegId" = ud."RegId" AND ud.is_active = 'true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			WHERE t.is_active = 'true'
	           AND (toolcategoryid IS NULL OR tc.id = ANY(toolcategoryid))
			   AND (subscriptionid IS NULL OR st.id = ANY(subscriptionid))
	           AND (platformid IS NULL OR p.platform_id = ANY(platformid))
			   AND (search_text IS NULL OR search_text = '' OR TRIM(LOWER(t."ToolName")) ILIKE '%' || E'\\' || search_text || '%' ESCAPE '\')
			GROUP BY t."ToolID",t."ToolName",tv.version_name,tc.name,s.name,ru1."DisplayName",ru1."Photo"
			ORDER BY
           CASE WHEN  order_type = 'toolname' AND order_by = 'asc' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END ASC,
            CASE WHEN order_type = 'toolname' AND order_by = 'desc' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END DESC,
            CASE WHEN order_type = 'status' AND order_by = 'asc' THEN s.name END ASC,
            CASE WHEN order_type = 'status' AND  order_by= 'desc' THEN s.name END DESC,
			CASE WHEN order_by IS NULL OR order_by = '' OR order_type IS NULL OR order_type = '' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END ASC;
           -- OFFSET setnumber
	        --LIMIT page_size;
ELSE
            RETURN QUERY
    		SELECT t."ToolID",t."ToolName",t."ToolCode",STRING_AGG(distinct p.name,','),tv.version_name,tc.name,STRING_AGG(distinct st.name,','),
			s.name,ru1."DisplayName",ru1."Photo",COALESCE(
    (
        SELECT jsonb_agg(user_info)
        FROM (
            SELECT
                jsonb_build_object(
                    'displayname', ru2."DisplayName",
                    'photo', encode(ru2."Photo"::bytea, 'base64')
                ) AS user_info
            FROM master.tool t1
            LEFT JOIN users.usertool ut1 ON t1."ToolID" = ut1."ToolID" AND ut1.is_active = 'true'
            LEFT JOIN users.registereduser ru2 ON (ut1."RegId" = ru2."RegId" AND ru2.is_active = 'true')
            LEFT JOIN users.userrole ur1 ON ru2."RegId" = ur1."RegId" AND ur1.is_active = 'true'
            LEFT JOIN master.role r1 ON ur1."RoleID" = r1."RoleID" AND r1.is_active = 'true'
            WHERE t1."ToolID" = t."ToolID" AND ru2.is_active = 'true'
              AND LOWER(r1."Name") NOT IN ('superadmin', 'admin')
            GROUP BY ru2."DisplayName", ru2."Photo"
        ) AS subquery_alias
    ),
    '[]'::jsonb
) AS deptuser

			FROM master.tool t 
			LEFT JOIN master.toolversion tv ON t.tool_version_id = tv.tool_version_id AND tv.is_active ='true'
			LEFT JOIN users.toolplatform tp ON t."ToolID" = tp.tool_id AND tp.is_active ='true'
			LEFT JOIN master.platform p ON tp.platform_id = p.platform_id AND p.is_active = 'true'
			LEFT JOIN master.status s ON t.status_id = s.id AND s.is_active='true'
			LEFT JOIN users.toolsubscription ts ON t."ToolID" = ts.tool_id AND ts.is_active = 'true'
			LEFT JOIN master.subscriptiontype st ON ts.subscription_type_id = st.id and st.is_active ='true'
			LEFT JOIN master.toolcategory tc ON t.tool_category_id = tc.id AND tc.is_active ='true'
			LEFT JOIN users.usertool ut ON t."ToolID" = ut."ToolID" AND ut.is_active = 'true'
			LEFT JOIN users.registereduser ru1 ON t.primary_user_id = ru1."RegId" AND ru1.is_active = 'true'
			LEFT JOIN users.registereduser ru ON ut."RegId" = ru."RegId" AND ru.is_active = 'true'
		    LEFT JOIN users.userdepartment ud ON ru."RegId" = ud."RegId" AND ud.is_active = 'true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			WHERE t.is_active = 'true' 
               AND (toolcategoryid IS NULL OR tc.id = ANY(toolcategoryid))
			   AND (subscriptionid IS NULL OR st.id = ANY(subscriptionid))
	           AND (platformid IS NULL OR p.platform_id = ANY(platformid))
			 GROUP BY t."ToolID",t."ToolName",tv.version_name,tc.name,s.name,ru1."DisplayName",ru1."Photo"
			 ORDER BY
            CASE WHEN  order_type = 'toolname' AND order_by = 'asc' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END ASC,
            CASE WHEN order_type = 'toolname' AND order_by = 'desc' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END DESC,
            CASE WHEN order_type = 'status' AND order_by = 'asc' THEN s.name END ASC,
            CASE WHEN order_type = 'status' AND  order_by= 'desc' THEN s.name END DESC,
			CASE WHEN order_by IS NULL OR order_by = '' OR order_type IS NULL OR order_type = '' THEN regexp_replace(t."ToolName", '[^a-zA-Z]', '', 'g') END ASC;
               --OFFSET setnumber
	           -- IMIT page_size;
END IF;
END;
$$;


--
-- Name: get_order_suggested_members(integer[]); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_order_suggested_members(p_board_ids integer[]) RETURNS TABLE(regid uuid, photo text, displayname text, givenname text, jobtitle text, country text, usertype integer, roleid integer, boardid integer, boardcode text, workspaceid integer, teamid integer, teamname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ru."RegId",
        ru.photo_url::text,
        ru."DisplayName"::text,
        ru."GivenName"::text,
        ru."JobTitle"::text,
        'India'::text,
        u.user_type_id,
        ubp.role_id,
		ubp.board_id,
        b.code::text AS board_code,
		ubp.workspace_id,
		u.team_id,
		t.name AS team_name
    FROM users.registereduser ru
    JOIN users.userprofile u 
        ON ru."RegId" = u.user_id 
       AND u.is_active = true
    JOIN users.user_board_permission ubp 
        ON ubp.reg_id = u.user_id
       AND ubp.is_active = true
    JOIN board.board b
        ON b."BoardID" = ubp.board_id
       AND b.is_active = true
	JOIN master.team t
		ON t.team_id = u.team_id 
		AND t.is_active = true
    WHERE ru.is_active = true
      AND ubp.board_id = ANY(p_board_ids);
END;
$$;


--
-- Name: get_suggested_members(text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_suggested_members(searchtext text DEFAULT NULL::text) RETURNS TABLE(regid uuid, photo bytea, displayname text, givenname text, empcode character varying, jobtitle text, email text, country text, roleid integer, rolename character varying, deptid integer, deptname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT
            ru."RegId",
            ru."Photo",
            ru."DisplayName",
            ru."GivenName",
            u."EmpCode",
            ru."JobTitle",
            ru."Email",
            'India' AS country,
            ur."RoleID",
            r."Name",
            udd."DeptID",
            d."Name"
        FROM
            users.registereduser ru	  
            LEFT JOIN users.userdepartment udd ON ru."RegId" = udd."RegId" AND udd.is_active = 'true'
            LEFT JOIN master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
            LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID")) AND u.is_active = 'true' 
            LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
            LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
        WHERE
            upper(d."Name") = 'ONBOARDING'
            AND r."RoleID" NOT IN (1, 2)
            AND ru.is_active = 'true'
            AND (
                searchtext IS NULL OR searchtext = '' or
                upper(ru."DisplayName") ILIKE '%' || upper(searchtext) || '%' OR
                ru."GivenName" ILIKE '%' || upper(searchtext) || '%');
END;
$$;


--
-- Name: get_ticket_suggested_members(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_ticket_suggested_members() RETURNS TABLE(deptid integer, deptname text, deptcode text, regid uuid, photo text, displayname text, givenname text, jobtitle text, country text, user_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_admin_status_id integer;
    v_superadmin_status_id integer;
BEGIN
    SELECT
        MAX(CASE WHEN name = 'Admin' THEN status_id END),
        MAX(CASE WHEN name = 'Super Admin' THEN status_id END)
    INTO
        v_admin_status_id,
        v_superadmin_status_id
    FROM master.status_code_master
    WHERE is_active = true
      AND type = 'USERROLE'
      AND name IN ('Admin', 'Super Admin');

    RETURN QUERY
    SELECT
        udd."DeptID" AS deptid,
        d."Name"::text AS deptname,
        d."DeptCode"::text AS deptcode,
        ru."RegId" AS regid,
        ru.photo_url::text AS photo,
        ru."DisplayName"::text AS displayname,
        ru."GivenName"::text AS givenname,
     --   u."EmpCode"::text AS empcode,
        ru."JobTitle"::text AS jobtitle,
     --   ru."Email"::text AS email,
        'India'::text AS country,
       -- ur."RoleID" AS roleid,
     --   r."Name"::text AS rolename,
        ru.user_type::text
    FROM
        users.registereduser ru
        LEFT JOIN users.userdepartment udd 
            ON ru."RegId" = udd."RegId" AND udd.is_active = true
        LEFT JOIN master.department d 
            ON udd."DeptID" = d."DeptID" AND d.is_active = true
        JOIN users.userprofile u 
            ON ru."RegId" = u.user_id AND u.is_active = true
        LEFT JOIN users.userrole ur 
            ON ru."RegId" = ur."RegId" AND ur.is_active = true
        -- LEFT JOIN master.role r 
        --     ON ur."RoleID" = r."RoleID" AND r.is_active = true
    WHERE
        (
            u.user_type_id IS DISTINCT FROM v_admin_status_id
            AND u.user_type_id IS DISTINCT FROM v_superadmin_status_id
        )
        OR EXISTS (
            SELECT 1
            FROM users.user_board_permission ubp
            WHERE ubp.reg_id = ru."RegId"
              AND ubp.is_active = true
        );
    --     ru.is_active = true;
END;
$$;


--
-- Name: get_tool_detail(integer); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_tool_detail(tid integer) RETURNS TABLE(toolid integer, toolname character varying, toolcode character varying, tool_description text, key_highlights text, is_dependency_required boolean, is_updateteam_dependency boolean, is_analyse_dependency boolean, is_tsr_dependency boolean, tool_version character varying, primary_regid uuid, primary_display_name text, primary_user_photo bytea, primary_user_email text, secondary_regid uuid, secondary_display_name text, secondary_user_photo bytea, secondary_user_email text, id integer, platform_name character varying, status_id integer, status_name character varying, subscription_id integer, subscription_name character varying, category_id integer, category_name character varying, regionid integer, regionname character varying, countryid integer, countryname character varying, countrycode character varying, deptid integer, deptname character varying, regid uuid, display_name text, photo bytea, job_title text, role_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
			return query
			SELECT t."ToolID",t."ToolName",t."ToolCode",t.description,t.keyhighlight,t.is_dependency_required,t.is_updateteam_dependency,t.is_analyse_dependency,t.is_tsr_dependency,tv.version_name,ru1."RegId",ru1."DisplayName",ru1."Photo",ru1."Email",ru2."RegId",ru2."DisplayName",ru2."Photo",ru2."Email",p.platform_id,p.name,
			t.status_id,s.name,ts.subscription_type_id,st.name,t.tool_category_id,tc.name,
			co."RegionID",re."Name",tcr.country_id,co."Name",co."CountryCode",d."DeptID",d."Name",
			CASE WHEN LOWER(r."Name") NOT IN ('superadmin', 'admin') THEN ru."RegId" END regid,CASE WHEN LOWER(r."Name") NOT IN ('superadmin', 'admin') THEN ru."DisplayName" END displayname,CASE WHEN LOWER(r."Name") NOT IN ('superadmin', 'admin') THEN ru."Photo" END photo,CASE WHEN LOWER(r."Name") NOT IN ('superadmin', 'admin') THEN ru."JobTitle" END jobtitle, CASE WHEN LOWER(r."Name") NOT IN ('superadmin', 'admin') THEN r."Name" END username
	
			FROM master.tool t 
			LEFT JOIN master.toolversion tv ON t.tool_version_id = tv.tool_version_id AND tv.is_active ='true'
			LEFT JOIN users.toolplatform tp ON t."ToolID" = tp.tool_id AND tp.is_active ='true'
			LEFT JOIN master.platform p ON tp.platform_id = p.platform_id AND p.is_active = 'true'
			LEFT JOIN master.status s ON t.status_id = s.id AND s.is_active='true'
			LEFT JOIN users.toolsubscription ts ON t."ToolID" = ts.tool_id AND ts.is_active = 'true'
			LEFT JOIN master.subscriptiontype st ON ts.subscription_type_id = st.id and st.is_active ='true'
			LEFT JOIN master.toolcategory tc ON t.tool_category_id = tc.id AND tc.is_active ='true'
			LEFT JOIN users.toolcountryregion tcr ON t."ToolID"= tcr.tool_id AND tcr.is_active='true'
			LEFT JOIN master.country co ON tcr.country_id = co."CountryID"  AND co.is_active='true'
			LEFT JOIN master.region re ON co."RegionID" = re."RegionID" AND re.is_active = 'true'
			LEFT JOIN users.usertool ut ON t."ToolID" = ut."ToolID" AND ut.is_active = 'true'
			LEFT JOIN users.registereduser ru1 ON t.primary_user_id = ru1."RegId" AND ru1.is_active = 'true'
			LEFT JOIN users.registereduser ru2 ON t.secondary_user_id = ru2."RegId" AND ru2.is_active = 'true'
			LEFT JOIN users.registereduser ru ON ut."RegId" = ru."RegId" AND ru.is_active = 'true'
			LEFT JOIN users.userdepartment ud ON ut."RegId" = ud."RegId" AND ud.is_active= 'true'
			LEFT JOIN master.department d ON ud."DeptID" = d."DeptID" AND d.is_active = 'true'
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			WHERE t."ToolID" = tid AND t.is_active = 'true' 
			ORDER BY 
            CASE 
                WHEN ru."RegId" = ru1."RegId" THEN 0
                WHEN ru."RegId" = ru2."RegId" THEN 1
                WHEN ru."RegId" IS NOT NULL THEN 2
            ELSE 3
           END,
          ru."RegId" ASC NULLS FIRST;
END;
$$;


--
-- Name: get_tool_product_owner(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_tool_product_owner() RETURNS TABLE(reg_id uuid, display_name text, email text, rolename character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
	return query
    SELECT  ud."RegId",ru."DisplayName",ru."Email",r."Name" as rolename FROM master.department d
	JOIN users.userdepartment ud ON d."DeptID" = ud."DeptID" and ud.is_active = true
	LEFT JOIN users.userrole urd ON ud."RegId" = urd."RegId" AND urd.is_active = 'true'
    JOIN users.registereduser ru ON urd."RegId" = ru."RegId" AND ru.is_active = true	
	JOIN master.role r ON urd."RoleID" = r."RoleID" AND r.is_active = 'true'
    WHERE TRIM(LOWER(d."DeptCode")) = LOWER('PDA') AND d.is_active = true AND LOWER(r."Name") NOT IN (LOWER('SuperAdmin'),LOWER('Admin')) ;
END;
$$;


--
-- Name: get_user_access_address(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_user_access_address(regid uuid) RETURNS TABLE(user_id uuid, user_name text, user_mail text, sender text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_name text;	
	user_mail text;
BEGIN
    SELECT "GivenName", "Email" INTO user_name, user_mail
    FROM users.registereduser
    WHERE "RegId" = UUID(regid) AND is_active ='true';
   RETURN QUERY
    -- select All superadmin and Admins
    WITH super_admin AS (
    SELECT UUID(regid) as user_id,ru."Email" as sender 
    FROM users.registereduser ru
    JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active='true'
    JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true'
    WHERE r."RoleID" in (1,2) AND ru.is_active = 'true' 
     ),
     -- select All reporting manager of the user
    report_manager AS (
        SELECT
        ru1."RegId" as user_id
        ,ru1."DisplayName" as user_name
        ,ru2."Email" as sender
    FROM users.reportmanager rm 
    JOIN users.registereduser ru1 ON ru1."RegId" = rm."RegId" AND ru1.is_active='true'
    LEFT JOIN users.registereduser ru2 ON ru2."RegId" = rm."ReportID" AND ru2.is_active='true'
    WHERE rm."RegId" = UUID(regid)  AND rm.is_active='true'
    )

  SELECT 
  rm.user_id
  ,rm.user_name
  ,user_mail
  ,rm.sender 
  FROM report_manager rm
  UNION
  SELECT 
  s.user_id
  ,user_name
  ,user_mail
  ,s.sender 
  FROM super_admin s ;
END;
$$;


--
-- Name: get_user_app_permission(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_user_app_permission(p_user_id uuid) RETURNS TABLE(user_app_permission_id integer, app_id integer, app_name character varying, app_code character varying, permission integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_user_type_id integer;
BEGIN
	SELECT up.user_type_id
	INTO v_user_type_id
	FROM users.userprofile up
	WHERE up.user_id = p_user_id
	LIMIT 1;

	-- Super Admin: all active apps
	IF v_user_type_id = 44 THEN
		RETURN QUERY
		SELECT
			0::integer AS user_app_permission_id,
			am.app_id::integer AS app_id,
			am.name::character varying AS app_name,
			am.code::character varying AS app_code,
			1::integer AS permission
		FROM master.app_master am
		WHERE am.is_active = true
		ORDER BY am.app_id;
		RETURN;
	END IF;

	RETURN QUERY
	SELECT
		uap.user_app_permission_id::integer AS user_app_permission_id,
		uap.app_id::integer AS app_id,
		am.name::character varying AS app_name,
		am.code::character varying AS app_code,
		1::integer AS permission
	FROM users.user_app_permission uap
	INNER JOIN master.app_master am
		ON am.app_id = uap.app_id
	   AND am.is_active = true
	WHERE uap.reg_id = p_user_id
	  AND uap.is_active = true
	ORDER BY uap.user_app_permission_id;
END;
$$;


--
-- Name: get_user_board_permission(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_user_board_permission(p_user_id uuid) RETURNS TABLE(user_board_permission_id integer, workspace_id integer, board_id integer, role_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_context TEXT := 'Fetching board permissions for user';
BEGIN

	--Created By      Date  		Purpose 
	--Aravindhan    13/08/2025		get user board permission
	--Mubarak       21/09/2026		removed is_admin
	
    RETURN QUERY
    SELECT 
	 	bp.user_board_permission_id AS user_board_permission_id,
        COALESCE(bp.workspace_id, wsm.work_space_id) AS workspace_id,
        b."BoardID" AS board_id,
        bp.role_id
    FROM users.user_board_permission bp
    INNER JOIN board.board b 
        ON bp.board_id = b."BoardID"
    INNER JOIN master.work_space_master wsm
        ON wsm.work_space_id = COALESCE(bp.workspace_id, b.work_space_id)
    LEFT JOIN master.role r
        ON bp.role_id = r.role_id
       AND r.is_active = TRUE
    WHERE bp.reg_id = p_user_id AND bp.is_active = TRUE
      AND b.is_active = TRUE
      AND wsm.is_active = TRUE;
	 
	EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in get_user_board_permission: %', SQLERRM;
		
		CALL master.procedure_log_exception(
            'users.get_user_board_permission',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_user_id
            ))::TEXT
        );
		
        RETURN QUERY SELECT 
            NULL::integer,
            NULL::integer,
            NULL::integer,
            NULL::integer;
END;
$$;


--
-- Name: get_user_board_roles(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_user_board_roles(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT COALESCE(jsonb_agg(workspaces) FILTER (WHERE workspaces IS NOT NULL), '[]'::jsonb)
        FROM (
            SELECT
                CASE
                    WHEN ubp.workspace_id IS NOT NULL THEN
                        jsonb_build_object(
                            'is_workspace_default', false,
                            'name', wpm.name,
                            'work_space_id', ubp.workspace_id,
                            'workflowType', wpm.work_flow_type,
                            'boards', COALESCE(
                                jsonb_agg(
                                    jsonb_build_object(
                                        'name', b."Name",
                                        'board_code', b.code,
                                        'board_id', ubp.board_id,
                                        'mainBoardID', COALESCE(b.main_board_id, b."BoardID"),
                                        'mainBoardName', COALESCE(mb."Name", b."Name"),
                                        'role_id', ubp.role_id,
                                        'role_name', r.name,
                                        'role_code', r.code
                                    )
                                ) FILTER (WHERE b."BoardID" IS NOT NULL),
                                '[]'::jsonb
                            )
                        )
                END AS workspaces
            FROM users.userprofile u

            LEFT JOIN users.user_board_permission ubp
                ON u.user_id = ubp.reg_id
               AND ubp.is_active = true

            LEFT JOIN master.work_space_master wpm
                ON ubp.workspace_id = wpm.work_space_id
               AND wpm.is_active = true

            LEFT JOIN board.board b
                ON ubp.board_id = b."BoardID"
               AND b.is_active = true

            LEFT JOIN board.board mb
                ON mb."BoardID" = COALESCE(b.main_board_id, b."BoardID")
               AND mb.is_active = true

            LEFT JOIN master.role r
                ON ubp.role_id = r.role_id
               AND r.is_active = true

            WHERE u.user_id = p_user_id
              AND u.is_active = true

            GROUP BY
                ubp.workspace_id,
                wpm.name,
                wpm.work_flow_type
        ) t
    );
END;
$$;


--
-- Name: get_user_list(text, integer[], integer[], integer[], integer[], integer, integer[], integer, integer, text, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_user_list(p_search_txt text DEFAULT ''::text, p_team_id integer[] DEFAULT NULL::integer[], p_country_id integer[] DEFAULT NULL::integer[], p_workspace_id integer[] DEFAULT NULL::integer[], p_board_id integer[] DEFAULT NULL::integer[], p_user_type_id integer DEFAULT NULL::integer, p_designation_id integer[] DEFAULT NULL::integer[], p_page_offset integer DEFAULT 0, p_page_size integer DEFAULT 20, p_sort_by text DEFAULT 'team'::text, p_sort_order text DEFAULT 'asc'::text) RETURNS TABLE(userlisting jsonb, totalcount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inactive_status_id   integer;
    v_user_status_id       integer;
    v_admin_status_id      integer;
    v_superadmin_status_id integer;
BEGIN
    -- Get status ids
    SELECT
        MAX(CASE WHEN name = 'InActive User' THEN status_id END),
        MAX(CASE WHEN name = 'User'          THEN status_id END),
        MAX(CASE WHEN name = 'Admin'         THEN status_id END),
        MAX(CASE WHEN name = 'Super Admin'   THEN status_id END)
    INTO
        v_inactive_status_id,
        v_user_status_id,
        v_admin_status_id,
        v_superadmin_status_id
    FROM master.status_code_master
    WHERE is_active = TRUE
      AND type = 'USERROLE';

    -- Workspace User View
    IF p_user_type_id = v_user_status_id THEN
        RETURN QUERY
        WITH filtered AS (
            SELECT up.user_id
            FROM users.userprofile up
            LEFT JOIN users.registereduser u ON u."RegId" = up.user_id
            WHERE up.is_active = TRUE 
              AND up.user_type_id = p_user_type_id
              AND (NULLIF(p_search_txt, '') IS NULL OR UPPER(u."DisplayName") LIKE '%' || UPPER(p_search_txt) || '%')
              -- team filter
              AND (p_team_id IS NULL OR array_length(p_team_id,1) IS NULL OR up.team_id = ANY(p_team_id))
              -- designation filter
              AND (p_designation_id IS NULL OR array_length(p_designation_id,1) IS NULL OR up.designation_id = ANY(p_designation_id))
              -- country filter
              AND (p_country_id IS NULL OR array_length(p_country_id,1) IS NULL OR up.country_id = ANY(p_country_id))
              -- workspace filter
              AND (p_workspace_id IS NULL OR array_length(p_workspace_id,1) IS NULL OR EXISTS (
                     SELECT 1 FROM users.user_board_permission sub_ubp
                     WHERE sub_ubp.reg_id = up.user_id AND sub_ubp.is_active = true
                       AND sub_ubp.workspace_id = ANY(p_workspace_id)
                   ))
              -- board filter
              AND (p_board_id IS NULL OR array_length(p_board_id,1) IS NULL OR EXISTS (
                     SELECT 1 FROM users.user_board_permission sub_ubp2
                     WHERE sub_ubp2.reg_id = up.user_id AND sub_ubp2.is_active = true
                       AND sub_ubp2.board_id = ANY(p_board_id)
                   ))
        ),
        total_count AS (
            SELECT COUNT(*) AS cnt FROM filtered
        ),
        paged AS (
            SELECT user_id FROM filtered
            OFFSET (p_page_offset * p_page_size)
            LIMIT p_page_size
        ),
        final AS (
            SELECT
                up.user_id,
                jsonb_build_object(
                    'regid', u."RegId",
                    'photo', u.photo_url,
                    'displayname', u."DisplayName",
                    'givenname', u."GivenName",
                    'empcode', null,
                    'jobtitle', u."JobTitle",
                    'mail', u."Email",
                    'country', c.country_name,
                    'roleid', null,
                    'rolename', null,
                    'usertype', u.user_type
                ) AS userInfo,
                up.user_profile_id AS userProfileId,
                up.is_active AS active,
                up.user_type_id AS userType,
                up.team_id AS team,
                up.country_id AS country,
                up.designation_id AS designation,
                array_agg(DISTINCT ubp.workspace_id) FILTER (WHERE ubp.workspace_id IS NOT NULL) AS workspace,
                array_agg(DISTINCT ubp.board_id)     FILTER (WHERE ubp.board_id IS NOT NULL)     AS board,
                up.created_date::date AS createdDate,
                NULL::integer AS previousUserType
            FROM users.userprofile up
            LEFT JOIN users.registereduser u ON u."RegId" = up.user_id
            JOIN master.country_detail c ON up.country_id = c.country_id
            LEFT JOIN users.user_board_permission ubp ON ubp.reg_id = up.user_id AND ubp.is_active = true
            WHERE up.user_id IN (SELECT user_id FROM paged)
              AND up.user_type_id = p_user_type_id
            GROUP BY up.user_id, u."RegId", u.photo_url, u."DisplayName", u."GivenName",
                     u."JobTitle", u."Email", u.user_type, up.is_active, up.user_type_id,
                     up.user_profile_id, up.team_id, up.country_id, up.designation_id, 
                     up.created_date, c.country_name
        )
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'userInfo', f.userInfo,
                    'userProfileId', f.userProfileId,
                    'active', f.active,
                    'userType', f.userType,
                    'team', f.team,
                    'country', f.country,
                    'designation', f.designation,
                    'workspace', f.workspace,
                    'board', f.board,
                    'createdDate', f.createdDate::text,
                    'previousUserType', f.previousUserType
                )
            ),
            (SELECT cnt FROM total_count)::integer
        FROM final f;

    -- Admin View (No Pagination)
    ELSIF p_user_type_id IN (v_admin_status_id, v_superadmin_status_id) THEN
        RETURN QUERY
        WITH filtered AS (
            SELECT up.user_id
            FROM users.userprofile up
            WHERE up.is_active = TRUE 
              AND up.user_type_id IN (v_admin_status_id, v_superadmin_status_id)
        ),
        total_count AS (
            SELECT COUNT(*) AS cnt FROM filtered
        ),
        final AS (
            SELECT
                up.user_id,
                jsonb_build_object(
                    'regid', u."RegId",
                    'photo', u.photo_url,
                    'displayname', u."DisplayName",
                    'givenname', u."GivenName",
                    'empcode', null,
                    'jobtitle', u."JobTitle",
                    'mail', u."Email",
                    'country', c.country_name,
                    'roleid', null,
                    'rolename', null,
                    'usertype', u.user_type
                ) AS userInfo,
                up.user_profile_id AS userProfileId,
                up.is_active AS active,
                up.user_type_id AS userType,
                up.team_id AS team,
                up.country_id AS country,
                up.designation_id AS designation,
                NULL::integer[] AS workspace,
                NULL::integer[] AS board,
                up.created_date::date AS createdDate,
                NULL::integer AS previousUserType
            FROM users.userprofile up
            LEFT JOIN users.registereduser u ON up.user_id = u."RegId"
            JOIN master.country_detail c ON up.country_id = c.country_id
            WHERE up.user_id IN (SELECT user_id FROM filtered)
              AND up.user_type_id IN (v_admin_status_id, v_superadmin_status_id)
			ORDER BY 
			CASE 
				WHEN up.user_type_id = v_superadmin_status_id THEN 1
				WHEN up.user_type_id = v_admin_status_id THEN 2
				ELSE 3
			END, u."DisplayName"
        )
        SELECT jsonb_agg(
                jsonb_build_object(
                    'userInfo', f.userInfo,
                    'userProfileId', f.userProfileId,
                    'active', f.active,
                    'userType', f.userType,
                    'team', f.team,
                    'country', f.country,
                    'designation', f.designation,
                    'workspace', f.workspace,
                    'board', f.board,
                    'createdDate', f.createdDate::text,
                    'previousUserType', f.previousUserType
                )
            ),
            (SELECT cnt FROM total_count)::integer
        FROM final f;

    -- Inactive Users View (No Pagination)
    ELSIF p_user_type_id = v_inactive_status_id THEN
        RETURN QUERY
        WITH filtered AS (
            SELECT up.user_id
            FROM users.userprofile up
            WHERE up.is_active = FALSE 
              AND up.user_type_id = v_inactive_status_id
        ),
        total_count AS (
            SELECT COUNT(*) AS cnt FROM filtered
        ),
        final AS (
            SELECT
                up.user_id,
                jsonb_build_object(
                    'regid', up.user_id,
                    'photo', u.photo_url,
                    'displayname', u."DisplayName",
                    'givenname', u."GivenName",
                    'empcode', null,
                    'jobtitle', u."JobTitle",
                    'mail', u."Email",
                    'country', c.country_name,
                    'roleid', null,
                    'rolename', null,
                    'usertype', null
                ) AS userInfo,
                up.user_profile_id AS userProfileId,
                up.is_active AS active,
                up.user_type_id AS userType,
                up.team_id AS team,
                up.country_id AS country,
                up.designation_id AS designation,
                NULL::integer[] AS workspace,
                NULL::integer[] AS board,
                up.created_date::date AS createdDate,
                up.previous_user_type_id AS previousUserType
            FROM users.userprofile up
            JOIN users.registereduser u ON up.user_id = u."RegId"
            JOIN master.country_detail c ON up.country_id = c.country_id
            WHERE up.user_id IN (SELECT user_id FROM filtered)
              AND up.user_type_id = p_user_type_id
        )
        SELECT jsonb_agg(
                jsonb_build_object(
                    'userInfo', f.userInfo,
                    'userProfileId', f.userProfileId,
                    'active', f.active,
                    'userType', f.userType,
                    'team', f.team,
                    'country', f.country,
                    'designation', f.designation,
                    'workspace', f.workspace,
                    'board', f.board,
                    'createdDate', f.createdDate::text,
                    'previousUserType', f.previousUserType
                )
            ),
            (SELECT cnt FROM total_count)::integer
        FROM final f;
    END IF;
END;
$$;


