--
-- Name: get_welcome_mail_sender(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.get_welcome_mail_sender(user_data jsonb) RETURNS TABLE(user_id uuid, user_name text, sender text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    user_ids uuid[];
    sql_query text;
BEGIN
    -- Get user IDs from the JSON parameter
    SELECT ARRAY(SELECT jsonb_array_elements_text(user_data->'userIds')::uuid) INTO user_ids;
    -- Create a dynamic SQL query
    sql_query := 'SELECT "RegId" AS user_id, "DisplayName" AS user_name, "Email" AS user_email ' ||
                 'FROM users.registereduser ' ||
                 'WHERE "RegId" = ANY($1)';

    -- Execute the dynamic SQL query and return the results
    RETURN QUERY EXECUTE sql_query USING user_ids;
			
END;		
$_$;


