--
-- Name: getmyteamdetail(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getmyteamdetail(rregid uuid) RETURNS TABLE(regid uuid, photo bytea, displayname text, givenname text, empcode character varying, jobtitle text, email text, activestatus boolean, country text, roleid integer, rolename character varying, deptid integer, deptname character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
	role_id integer ; 
BEGIN
           -- updatedby   || updateddate   || purpose
           -- Naveen S    || 24-04-2024    || i have remove condition is_active status
     SELECT "RoleID" INTO  role_id FROM users.userrole WHERE "RegId" = rregid and is_active = 'true';
	  IF(role_id = 3 OR role_id = 4 OR role_id = 5) /* 3->Manager,4->Lead,5->Member */
	  THEN
         -- Declare a cursor to select all rows from the table
   		 FOR row_record IN SELECT "DeptID" FROM users.userdepartment WHERE "RegId" = rregid and is_active = 'true'
    	 LOOP
	      return query
			SELECT ru."RegId",ru."Photo", ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle",ru."Email",ru.is_active as activestatus,'India' as country,ur."RoleID",r."Name",udd."DeptID",
			d."Name"
			FROM users.registereduser ru	  
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true'
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID")) AND u.is_active= 'true' 
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			WHERE udd."DeptID" = row_record."DeptID" AND r."RoleID" NOT IN (1,2);
			--AND ru.is_active = 'true' ;
			 
	    END LOOP;
		END IF;
		IF(role_id = 1 OR role_id = 2) /* 1->SuperAdmin,2->Admin */
    	THEN
			return query
			SELECT ru."RegId",ru."Photo", ru."DisplayName",ru."GivenName",u."EmpCode",ru."JobTitle",ru."Email",ru.is_active as activestatus,'India' as country,ur."RoleID",r."Name",udd."DeptID"
			,d."Name"
			FROM users.registereduser ru	
			LEFT JOIN users.userrole ur ON ru."RegId"= ur."RegId" AND ur.is_active='true'
			LEFT JOIN users.userdepartment udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true'
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID"))	AND u.is_active= 'true' 
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true' 
			WHERE ur."RoleID" = 2 ;
			--AND ru.is_active = 'true' ;
		END IF;
END;
$$;


