-- Name: getregisteredusers(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getregisteredusers() RETURNS TABLE(regid uuid, photo bytea, displayname text, givenname text, empcode character varying, jobtitle text, email text, activestatus boolean, country text, roleid integer, rolename character varying, deptid integer, deptname character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
          -- updatedby   || updateddate   || purpose
          -- Naveen S    || 24-04-2024    || i have remove condition is_active status
	      return query
			SELECT ru."RegId",ru."Photo", ru."DisplayName",ru."GivenName",
			u."EmpCode",ru."JobTitle",ru."Email",ru.is_active as activestatus,'India' as country,
			ur."RoleID",
			r."Name",
			udd."DeptID",
			d."Name"
			FROM users.registereduser ru	  
			LEFT JOIN users.userdepartment  udd ON ru."RegId" = udd."RegId" AND udd.is_active= 'true'
			LEFT JOIN master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
			LEFT JOIN users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID")) AND u.is_active= 'true' 
			LEFT JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
			LEFT JOIN master.role r ON ur."RoleID" = r."RoleID" AND r.is_active = 'true'
			WHERE (ru.user_type IS NULL OR ru.user_type <> 'Agency');
			--where ru.is_active = 'true' ;
END;
$$;


--
-- Name: getuserdetail(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserdetail(rregid character varying) RETURNS TABLE(regid uuid, empcode character varying, email text, jobtitle text, displayname text, photo text, givenname text, surname text, mobilephone text, officelocation text, user_boards integer[], is_active boolean, username text, usertype integer, usertypecode character varying, countryid integer, designationid integer, teamid integer, issuperadmin boolean, knowledgebasepermissions jsonb, boardid integer, boardname character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    usertype character varying; 
	user_boardids integer[];
BEGIN
    -- Get the user type, defaulting to 'Euroland' if null
    SELECT COALESCE(u.user_type, 'Euroland') INTO usertype 
    FROM users.registereduser u
    WHERE "RegId" = UUID(rregid);
 
SELECT ARRAY_AGG(DISTINCT board_id) INTO user_boardids
FROM (
	SELECT board_id FROM users.user_board_permission ubp
	WHERE ubp.reg_id = rregid::uuid and ubp.is_active = TRUE 
) boards;

    IF usertype = 'Euroland' THEN
        RETURN QUERY
        SELECT 
            ru."RegId", null::character varying AS "EmpCode", ru."Email", ru."JobTitle", ru."DisplayName", 
            ru.photo_url, ru."GivenName", ru."Surname", ru."MobilePhone", ru."OfficeLocation",user_boardids,
            ru.is_active, ru."DisplayName" AS username,            
		    u.user_type_id AS usertype, scm.code AS usertypecode, u.country_id as countryid, u.designation_id as designationid, u.team_id as teamid,
            CASE WHEN LOWER(scm.name) = LOWER('Super Admin') THEN true ELSE false END AS issuperadmin,
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'knowledgeBaseId', kb.id,
                            'knowledgeBaseName', kb.name,
                            'canEdit', ukp.action_id
                        )
                        ORDER BY ukp.user_knowledgebase_permission_id
                    )
                    FROM knowledgebase.user_knowledgebase_permission ukp
                    INNER JOIN knowledgebase.knowledgebase_master kb
                        ON kb.id = ukp.knowledge_base_id
                       AND kb.is_active = true
                    WHERE ukp.reg_id = ru."RegId"
                      AND ukp.is_active = true
                ),
                '[]'::jsonb
            ) AS knowledgebasepermissions,
            b."BoardID", b."Name"
        FROM 
            users.registereduser ru
         JOIN 
            users.userprofile u ON ru."RegId" = u.user_id AND u.is_active = 'true'
		LEFT JOIN 
			users.user_board_permission ubp ON ru."RegId" = ubp.reg_id AND ubp.is_active = true
        LEFT JOIN 
            board.board b ON ubp.board_id = b."BoardID" AND b.is_active = 'true'
		LEFT JOIN 
            master.status_code_master scm ON u.user_type_id = scm.status_id AND scm.is_active = 'true'
        WHERE 
            ru."RegId" = UUID(rregid)
		GROUP BY 
			ru."RegId",
			ru."Email",
			ru."JobTitle",
			ru."DisplayName",
			ru."Photo",
			ru."GivenName",
			ru."Surname",
			ru."MobilePhone",
			ru."OfficeLocation",
			ru.is_active,			
			u.user_type_id,
			ru.user_type, scm.code, u.country_id, u.designation_id, u.team_id,
			scm.name,			
			b."BoardID",b."Name";
   
    END IF;
END;
$$;


--
-- Name: getuserdetail_dashboard(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserdetail_dashboard() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'regid', ru."RegId",
            'empcode', NULL,
            'email', ru."Email",
            'jobtitle', ru."JobTitle",
            'displayname', ru."DisplayName",
            'photo', ru.photo_url,
            'givenname', ru."GivenName",
            'surname', ru."Surname",
            'mobilephone', ru."MobilePhone",
            'officelocation', ru."OfficeLocation",

            'user_boards',
            (
                SELECT COALESCE(array_agg(DISTINCT ubp1.board_id), ARRAY[]::integer[])
                FROM users.user_board_permission ubp1
                WHERE ubp1.reg_id = ru."RegId"
                  AND ubp1.is_active = TRUE
            ),

            'is_active', ru.is_active,
            'username', ru."DisplayName",
            'usertype', u.user_type_id,
            'usertypecode', scm.code,
            'countryid', u.country_id,
            'designationid', u.designation_id,
            'teamid', u.team_id,
            'issuperadmin',
                CASE
                    WHEN LOWER(scm.name) = 'super admin' THEN TRUE
                    ELSE FALSE
                END,

            'boards',
            (
                SELECT COALESCE(
                    jsonb_agg(
                        jsonb_build_object(
                            'boardid', b."BoardID",
                            'boardname', b."Name",
							'roleid', r.role_id,
							'rolename', r.name
                        )
                    ),
                    '[]'::jsonb
                )
                FROM users.user_board_permission ubp
                JOIN board.board b
                    ON ubp.board_id = b."BoardID"
                   AND b.is_active = TRUE
				JOIN master.role r 
					ON r.role_id = ubp.role_id 
					AND r.is_active = true
                WHERE ubp.reg_id = ru."RegId"
                  AND ubp.is_active = TRUE
            )
        )
    )
    INTO result
    FROM users.registereduser ru	
    JOIN users.userprofile u
      ON ru."RegId" = u.user_id
     AND u.is_active = TRUE
    LEFT JOIN master.status_code_master scm
      ON u.user_type_id = scm.status_id
     AND scm.is_active = TRUE;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: getuserdetail_jp(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserdetail_jp(rregid character varying) RETURNS TABLE(regid uuid, empcode character varying, email text, jobtitle text, displayname text, photo text, givenname text, surname text, mobilephone text, officelocation text, user_boards integer[], is_active boolean, username text, roleid integer, rolename character varying, usertype character varying, issuperadmin boolean, rolehierarchy integer, deptid integer, deptname character varying, deptcode character varying, boardid integer, boardname character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    usertype character varying; 
	user_boardids integer[];
BEGIN
    -- Get the user type, defaulting to 'Euroland' if null
    SELECT COALESCE(u.user_type, 'Euroland') INTO usertype 
    FROM users.registereduser u
    WHERE "RegId" = UUID(rregid);
	
	-- Get the User board list
SELECT ARRAY_AGG(DISTINCT board_id) INTO user_boardids
FROM (
    SELECT b."BoardID" AS board_id
    FROM users.user_work_space uw
    JOIN board.board b 
        ON uw.work_space_id = b.work_space_id AND b.is_active = TRUE
    WHERE uw.reg_id = rregid::uuid AND uw.is_active = TRUE
) boards;
 
    IF usertype = 'Euroland' THEN
        RETURN QUERY
        SELECT 
            ru."RegId", null::character varying AS "EmpCode", ru."Email", ru."JobTitle", ru."DisplayName", 
            ru.photo_url, ru."GivenName", ru."Surname", ru."MobilePhone", ru."OfficeLocation",user_boardids,
            ru.is_active, ru."DisplayName" AS username,
            urd."RoleID", r.name AS rolename,
		    ru.user_type,
            CASE WHEN LOWER(r.name) = LOWER('SuperAdmin') THEN true ELSE false END AS issuperadmin,
            (SELECT * FROM master.get_heirachy_role(urd."RoleID")) AS rolehierarchy,
            udd."DeptID", d."Name", d."DeptCode",
            b."BoardID", b."Name"
        FROM 
            users.registereduser ru
         JOIN 
            users.userprofile u ON ru."RegId" = u.user_id AND u.is_active = 'true'
        LEFT JOIN 
            users.userdepartment udd ON ru."RegId" = udd."RegId" AND udd.is_active = 'true'
        LEFT JOIN 
            users.user_work_space uw ON ru."RegId" = uw.reg_id AND uw.is_active = 'true'
        LEFT JOIN 
            master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
        LEFT JOIN 
            master.work_space_department wd ON uw.work_space_id = wd.work_space_id AND d."DeptID" = wd.dept_id AND wd.is_active = true
        LEFT JOIN 
            master.work_space_master wm ON wd.work_space_id = wm.work_space_id AND wm.is_active = 'true'
        LEFT JOIN 
            users.userrole urd ON ru."RegId" = urd."RegId" AND urd.is_active = 'true'
        LEFT JOIN 
            master.role r ON urd."RoleID" = r.role_id AND r.is_active = 'true'
        LEFT JOIN 
            board.departmentboard deb ON d."DeptID" = deb."DeptID" AND deb.is_active = 'true'
        LEFT JOIN 
            board.board b ON deb."BoardID" = b."BoardID" AND b.is_active = 'true'
        WHERE 
            ru."RegId" = UUID(rregid) --AND d."Name" IS NOT NULL  --wm.code <> 'AG'
-- 			AND case when d."DeptCode" ='ST' THEN wm.code=wm.code
-- 			else
-- 			wm.code <> 'AG' end
		GROUP BY 
			ru."RegId",
			ru."Email",
			ru."JobTitle",
			ru."DisplayName",
			ru."Photo",
			ru."GivenName",
			ru."Surname",
			ru."MobilePhone",
			ru."OfficeLocation",
			ru.is_active,
			urd."RoleID",
			r.name,
			udd."DeptID",
			d."Name",
			d."DeptCode",
			b."BoardID",b."Name",
            ru.user_type;
   
    END IF;
END;
$$;


--
-- Name: getuserdetail_old(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserdetail_old(rregid character varying) RETURNS TABLE(regid uuid, empcode character varying, email text, jobtitle text, displayname text, photo text, givenname text, surname text, mobilephone text, officelocation text, user_boards integer[], is_active boolean, username text, roleid integer, rolename character varying, usertype character varying, issuperadmin boolean, rolehierarchy integer, deptid integer, deptname character varying, deptcode character varying, boardid integer, boardname character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    usertype character varying; 
	user_boardids integer[];
BEGIN
    -- Get the user type, defaulting to 'Euroland' if null
    SELECT COALESCE(u.user_type, 'Euroland') INTO usertype 
    FROM users.registereduser u
    WHERE "RegId" = UUID(rregid);
	
	-- Get the User board list
SELECT ARRAY_AGG(DISTINCT board_id) INTO user_boardids
FROM (
    SELECT b."BoardID" AS board_id
    FROM users.user_work_space uw
    JOIN board.board b 
        ON uw.work_space_id = b.work_space_id AND b.is_active = TRUE
    WHERE uw.reg_id = rregid::uuid AND uw.is_active = TRUE
) boards;
 
    IF usertype = 'Euroland' THEN
        RETURN QUERY
        SELECT 
            ru."RegId", u."EmpCode", ru."Email", ru."JobTitle", ru."DisplayName", 
            ru.photo_url, ru."GivenName", ru."Surname", ru."MobilePhone", ru."OfficeLocation",user_boardids,
            ru.is_active, (u."FirstName" || ' ' || u."LastName") AS username,
            urd."RoleID", r."Name" AS rolename,
		    ru.user_type,
            CASE WHEN LOWER(r."Name") = LOWER('SuperAdmin') THEN true ELSE false END AS issuperadmin,
            (SELECT * FROM master.get_heirachy_role(urd."RoleID")) AS rolehierarchy,
            udd."DeptID", d."Name", d."DeptCode",
            b."BoardID", b."Name"
        FROM 
            users.registereduser ru
        LEFT JOIN 
            users.userprofile u ON TRIM(LOWER(ru."Email")) = TRIM(LOWER(u."EmailID")) AND u.is_active = 'true'
        LEFT JOIN 
            users.userdepartment udd ON ru."RegId" = udd."RegId" AND udd.is_active = 'true'
        LEFT JOIN 
            users.user_work_space uw ON ru."RegId" = uw.reg_id AND uw.is_active = 'true'
        LEFT JOIN 
            master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
        LEFT JOIN 
            master.work_space_department wd ON uw.work_space_id = wd.work_space_id AND d."DeptID" = wd.dept_id AND wd.is_active = true
        LEFT JOIN 
            master.work_space_master wm ON wd.work_space_id = wm.work_space_id AND wm.is_active = 'true'
        LEFT JOIN 
            users.userrole urd ON ru."RegId" = urd."RegId" AND urd.is_active = 'true'
        LEFT JOIN 
            master.role r ON urd."RoleID" = r."RoleID" AND r.is_active = 'true'
        LEFT JOIN 
            board.departmentboard deb ON d."DeptID" = deb."DeptID" AND deb.is_active = 'true'
        LEFT JOIN 
            board.board b ON deb."BoardID" = b."BoardID" AND b.is_active = 'true'
        WHERE 
            ru."RegId" = UUID(rregid) AND d."Name" IS NOT NULL AND  --wm.code <> 'AG'
			case when d."DeptCode" ='ST' THEN wm.code=wm.code
			else
			wm.code <> 'AG' end
		GROUP BY 
			ru."RegId",
			u."EmpCode",
			ru."Email",
			ru."JobTitle",
			ru."DisplayName",
			ru."Photo",
			ru."GivenName",
			ru."Surname",
			ru."MobilePhone",
			ru."OfficeLocation",
			ru.is_active,
			u."FirstName",
			u."LastName",
			urd."RoleID",
			r."Name",
			udd."DeptID",
			d."Name",
			d."DeptCode",
			b."BoardID",b."Name",
            ru.user_type;
    ELSE
	
		-- Get the User board list
SELECT ARRAY_AGG(DISTINCT board_id) INTO user_boardids
FROM (

	   SELECT b."BoardID" AS board_id
        FROM board.board b
        JOIN board.departmentboard db ON db."BoardID" = b."BoardID" AND db.is_active = true
        JOIN master.department d ON db."DeptID" = d."DeptID" AND d.is_active = true
		JOIN users.userdepartment ud ON d."DeptID" = ud."DeptID" AND ud.is_active ='true'
		JOIN users.agency_user au ON ud."RegId" = au.reg_id AND au.is_active ='true'
		JOIN master.agency ag ON au.agency_id = ag.agency_id AND b."BoardID" = ag.board_id AND ag.is_active = true
        WHERE UPPER(d."DeptCode") = 'AG'
		AND au.reg_id = UUID(rregid)
		AND b.is_active ='true'
) boards;
        RETURN QUERY
        SELECT 
            ru."RegId", null::character varying AS "EmpCode", ru."Email", ru."JobTitle", ru."DisplayName", 
            ru.photo_url, ru."GivenName", ru."Surname", ru."MobilePhone", ru."OfficeLocation", user_boardids,
            ru.is_active, ru."GivenName" AS username,
            urd."RoleID", r."Name" AS rolename,
		     ru.user_type,
            CASE WHEN LOWER(r."Name") = LOWER('SuperAdmin') THEN true ELSE false END AS issuperadmin,
            (SELECT * FROM master.get_heirachy_role(urd."RoleID")) AS rolehierarchy,
            udd."DeptID", d."Name", d."DeptCode",
            b."BoardID", b."Name"
        FROM 
            users.registereduser ru  
        JOIN 
            users.userdepartment udd ON ru."RegId" = udd."RegId" AND udd.is_active = 'true'
        JOIN 
            master.department d ON udd."DeptID" = d."DeptID" AND d.is_active = 'true'
        JOIN 
            users.userrole urd ON ru."RegId" = urd."RegId" AND urd.is_active = 'true'
        JOIN 
            master.role r ON urd."RoleID" = r."RoleID" AND r.is_active = 'true'
        JOIN 
            users.agency_user au ON ru."RegId" = au.reg_id AND au.is_active = 'true'
        JOIN 
            master.agency ag ON au.agency_id = ag.agency_id AND ag.is_active = 'true'
        JOIN 
            board.board b ON ag.board_id = b."BoardID" AND b.is_active = 'true'
        WHERE 
            ru."RegId" = UUID(rregid);
    END IF;
END;
$$;


--
-- Name: getuserdetail_v2(character varying); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserdetail_v2(rregid character varying) RETURNS TABLE(regid uuid, empcode character varying, email text, jobtitle text, displayname text, photo text, givenname text, surname text, mobilephone text, officelocation text, is_active boolean, username text, userroletype integer, issuperadmin boolean, userboard jsonb, userworkspace_board jsonb, userroleresponsedetail jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    
	RETURN QUERY
	SELECT 
		ru."RegId"                	AS regid,
		null::character varying   	AS empcode,
		ru."Email"					AS email,
		ru."JobTitle"				AS jobtitle,
		ru."DisplayName"			AS displayname,
        ru.photo_url				AS photo, 
		ru."GivenName"				AS givenname,
		ru."Surname"				AS surname, 
		ru."MobilePhone"			AS mobilephone,
		ru."OfficeLocation"			AS officelocation,
		ru.is_active				AS is_active,
		ru."DisplayName" 			AS username,
		u.user_type_id				AS userroletype,
		TRUE						AS issuperadmin,
		COALESCE(
			jsonb_agg(
				jsonb_build_object(
					'board_id', b."BoardID",
					'name', b."Name"
				)
			) FILTER (WHERE b."BoardID" IS NOT NULL),
			'[]'::jsonb
		) 							AS userboard,
		COALESCE(
			jsonb_agg(
				DISTINCT jsonb_build_object(
					'work_space_id', wpm.work_space_id,
					'name', wpm.name,
					'item', COALESCE(
						(
							SELECT jsonb_agg(
								jsonb_build_object(
									'board_id', ubp.board_id,
									'role_id', ubp.role_id
								)
							)
							FROM users.user_board_permission ubp
							WHERE ubp.reg_id = ru."RegId"
							  AND ubp.workspace_id = wpm.work_space_id
							  AND ubp.is_active = TRUE
						), '[]'::jsonb
					)
				)
			) FILTER (WHERE wpm.work_space_id IS NOT NULL),
			'[]'::jsonb
		) 							AS userworkspace_board,
		null::JSONB 				AS userroleresponsedetail
	FROM 
		users.registereduser ru
	JOIN 
        users.userprofile u ON ru."RegId" = u.user_id AND u.is_active = 'true'
	LEFT JOIN
		users.user_board_permission ubp ON ru."RegId" = ubp.reg_id AND ubp.is_active = 'true'
	LEFT JOIN
		board.board b ON ubp.board_id = b."BoardID" AND b.is_active = 'true'
	LEFT JOIN
		master.work_space_master wpm ON ubp.workspace_id = wpm.work_space_id AND wpm.is_active = 'true'
	WHERE 
		ru."RegId" = UUID(rregid)
	GROUP BY
		ru."RegId",
		ru."Email",
		ru."JobTitle",		
		ru."DisplayName",	
		ru.photo_url,	
		ru."GivenName",
		ru."Surname",		
		ru."MobilePhone",	
		ru."OfficeLocation",	
		ru.is_active,		
		ru."DisplayName",
		u.user_type_id;		
END;
$$;


--
-- Name: getuserroledetail(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserroledetail(rregid uuid) RETURNS TABLE(id uuid, permission text, type text, roleid integer, name character varying, ischecked boolean, depid integer, depcode character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
	return query

	SELECT rs."Id", rs."Permission", rs."Type", rs."RoleId",r.name, rs."Ischecked",rs.dept_id,d."DeptCode"
	FROM master.rolesetting rs
	JOIN master.role r on rs."RoleId" = r.role_id AND r.is_active = 'true'
	JOIN master.department d ON rs.dept_id = d."DeptID" AND d.is_active = 'true'
	WHERE r.role_id in (SELECT "RoleID" FROM users.userrole WHERE "RegId" = rregid) AND rs.is_active = 'true'
	ORDER BY "Permission";

END;

$$;


--
-- Name: getuserroledetail_old(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserroledetail_old(rregid uuid) RETURNS TABLE(id uuid, permission text, type text, roleid integer, name character varying, ischecked boolean, depid integer, depcode character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
	return query

	SELECT rs."Id", rs."Permission", rs."Type", rs."RoleId",r."Name", rs."Ischecked",rs.dept_id,d."DeptCode"
	FROM master.rolesetting rs
	JOIN master.role r on rs."RoleId" = r."RoleID" AND r.is_active = 'true'
	JOIN master.department d ON rs.dept_id = d."DeptID" AND d.is_active = 'true'
	WHERE r."RoleID" in (SELECT "RoleID" FROM users.userrole WHERE "RegId" = rregid) AND rs.is_active = 'true'
	ORDER BY "Permission";

END;

$$;


--
-- Name: getuserrolename(uuid); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.getuserrolename(regid uuid) RETURNS TABLE(rolename character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	return query

	SELECT r."Name" FROM users.userrole ur
	JOIN master.role r ON ur."RoleID"=r."RoleID" AND r.is_active='true'
	WHERE "RegId"=regid AND ur.is_active= 'true';
END;

$$;


--
-- Name: insert_user_department_work_space_data(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.insert_user_department_work_space_data() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_data RECORD;
    max_user_work_space_id BIGINT;
	dept_id INTEGER;
	workspace_id INTEGER;
BEGIN

			-- select Agent Department as a default for new Agency user
 
            SELECT "DeptID" INTO dept_id FROM master.department WHERE UPPER("DeptCode") = UPPER('AG') AND is_active = 'true'; 
 
            -- select agency workspace id as default for new Agency user
           SELECT work_space_id INTO workspace_id FROM master.work_space_master WHERE UPPER(code) = UPPER('AG') AND is_active ='true';
		   
    -- Query to fetch user data with ranking
    FOR user_data IN
        SELECT 
            ru."RegId", 
            ru."Email", 
            ru."DisplayName", 
            us."DeptID" as udept, 
            d."Name" as dept_name, 
            d."DeptCode",
			r."Name"
        FROM users.registereduser ru
        JOIN users.userdepartment us 
        ON ru."RegId" = us."RegId" AND us.is_active = 'true'
        JOIN master.department d 
        ON us."DeptID" = d."DeptID" AND d.is_active = 'true'
		JOIN users.userrole ur ON ru."RegId" = ur."RegId" AND ur.is_active = 'true'
		JOIN master.role r ON r."RoleID" = ur."RoleID" AND r.is_active = 'true'
        WHERE d."DeptCode" = 'OB' AND ru.is_active = 'true' 
    LOOP
            -- Insert logic based on DeptCode
            SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_work_space_id FROM users.user_work_space;			
			INSERT INTO users.userdepartment
			(
				"RegId",
				"DeptID",
				is_active,
				created_date,
				created_by
			)
			VALUES
			(
				user_data."RegId",
				dept_id,
				'true',
				current_timestamp AT TIME ZONE 'UTC',
				'admin'				
			);
			
			INSERT INTO users.user_work_space
			(
				user_work_space_id,
				work_space_id,
				reg_id,
				is_active,
				created_date,
				created_by
			)
			VALUES
			(
				max_user_work_space_id,
				workspace_id,
				user_data."RegId",
				'true',
				current_timestamp AT TIME ZONE 'UTC',
				'admin'				
			);
    END LOOP;
END;
$$;


--
-- Name: insert_user_work_space_data(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.insert_user_work_space_data() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_data RECORD;
    max_user_work_space_id BIGINT;
BEGIN
    -- Query to fetch user data with ranking
    FOR user_data IN
        SELECT 
            ru."RegId", 
            ru."Email", 
            ru."DisplayName", 
            us."DeptID" as udept, 
            d."Name" as dept_name, 
            d."DeptCode",
            ROW_NUMBER() OVER (PARTITION BY ru."RegId", 
                               CASE 
                                   WHEN d."DeptCode" IN ('OB', 'SP') THEN 'OBSP'
                                   WHEN d."DeptCode" IN ('UT', 'AC', 'DT') THEN 'UTACDT'
                                   ELSE d."DeptCode"
                               END
                               ORDER BY d."DeptCode"
                              ) AS rn
        FROM users.registereduser ru
        JOIN users.userdepartment us 
        ON ru."RegId" = us."RegId" AND us.is_active = 'true'
        JOIN master.department d 
        ON us."DeptID" = d."DeptID" AND d.is_active = 'true'
        WHERE ru.is_active = 'true'
    LOOP
        -- Check if it's the first record for 'OB', 'SP' or 'UT', 'AC', 'DT'
        IF user_data.rn = 1 THEN
            -- Insert logic based on DeptCode
            SELECT COALESCE(MAX(user_work_space_id), 0)::BIGINT INTO max_user_work_space_id FROM users.user_work_space;
            IF user_data."DeptCode" IN ('OB', 'SP') THEN
                -- Insert into workspace one
                INSERT INTO users.user_work_space(user_work_space_id, work_space_id, reg_id,is_active,created_date,created_by)
                VALUES (max_user_work_space_id + 1, 1, user_data."RegId",'true',current_timestamp AT TIME ZONE 'UTC','admin');
            ELSIF user_data."DeptCode" IN ('UT', 'AC', 'DT') THEN
                -- Insert into workspace two
                INSERT INTO users.user_work_space(user_work_space_id, work_space_id, reg_id,is_active,created_date,created_by)
                VALUES (max_user_work_space_id + 1, 2, user_data."RegId",'true',current_timestamp AT TIME ZONE 'UTC','admin');
            END IF;
        END IF;
    END LOOP;
END;
$$;


--
-- Name: insertuserroledeptmanager(); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.insertuserroledeptmanager() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_record RECORD;
BEGIN
    -- Declare a cursor to select all rows from the table
    FOR row_record IN SELECT "RegId" FROM users.registereduser
    LOOP
       IF NOT EXISTS (SELECT "RegId" FROM users.userrole WHERE "RegId" = row_record."RegId" AND is_active = 'true')
       THEN
         INSERT INTO users.userrole(
	     "RegId", "RoleID", is_active, created_date, created_by)
	     VALUES (row_record."RegId", 1,'true', CURRENT_DATE, 'Admin');
       END IF;
	   IF NOT EXISTS (SELECT "RegId" FROM users.userdepartment WHERE "RegId" = row_record."RegId" AND is_active = 'true')
       THEN
         INSERT INTO users.userdepartment(
	     "RegId", "DeptID", is_active, created_date, created_by)
	     VALUES (row_record."RegId", 2,'true', CURRENT_DATE, 'Admin');
       END IF;
    END LOOP;
END;
$$;


--
-- Name: registeruser_delete(character varying, text); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.registeruser_delete(regid character varying, updatedby text) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN	
IF EXISTS (SELECT ru."RegId" FROM users.registereduser ru
		    			 JOIN users.userdepartment ud on  ru."RegId" = ud."RegId" AND ud.is_active ='true'
		   				 JOIN users.userrole ur on  ru."RegId" = ur."RegId" AND ur.is_active = 'true'
		   				 WHERE ru."RegId" = UUID(regid) AND ru.is_active = 'true'
		                                         
		  )
THEN
	UPDATE users.registereduser SET is_active ='false' , "IsRegistered"='false' , last_updated_date = current_timestamp ,updated_by = updatedby WHERE "RegId"= UUID(regid);
	return query select 'User mapped with role and department. so user status changed to inactive.' as message,'true'::boolean as status;
	return;
ELSE 
	IF EXISTS (SELECT "RegId" FROM users.registereduser ru
							 WHERE ru."RegId" = UUID(regid) AND ru.is_active = 'true'
			  ) THEN
	DELETE FROM users.registereduser WHERE "RegId"= UUID(regid);
	return query select 'User deleted sucessfully.' as message,'true'::boolean as status;
	return;
	end if;
-- 	DELETE FROM users.userdepartment WHERE "RegId"= UUID(regid);
-- 	DELETE FROM users.userrole WHERE "RegId"= UUID(regid);
-- 	DELETE FROM users.registereduser WHERE "RegId"= UUID(regid);
END IF;
		  return query select 'User delete failed' as message,'false'::boolean as status;
END;
$$;


--
-- Name: save_update_user_profile(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.save_update_user_profile(input_json jsonb) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
   declare offected integer;
   email text;
   key text;
   value jsonb;
   regid uuid;
   department_value int;
   work_space_value int;
   countryid int; 
   toolid int;
   languageid int;
   roleid int;
   in_is_active boolean;
   max_user_work_space_id BIGINT;
   
   BEGIN 
   -- updatedby   || updateddate   || purpose
   -- Naveen S    || 23-04-2024    || Update is_active status
   
   -- Mubarak Basha || 21-01-2025  || Added Workspace logic
   
  /* SELECT * FROM users.save_update_user_profile(
    '{
      "regid": "9af06fa7-f8ef-49e1-85ae-3d947e4eddce",
      "department": [56,22,23],
      "workspace": [5,1],
      "role": [5],
      "tool": [1],
      "country": [24,1],
      "language": [5,1],
      "shift": 1,
      "is_active": true
    }'
);*/
   
   regid :=cast(replace(input_json ->>'regid','"','') as uuid);
    in_is_active :=cast(replace(input_json ->>'is_active','"','') as boolean);
   RAISE INFO 'reg id high %',regid;
   SELECT "EmailID" INTO email from users.userprofile u
           JOIN users.registereduser ru 
		   ON LOWER(TRIM(u."EmailID")) = LOWER(TRIM(ru."Email")) AND u.is_active = 'true' -- Added lower case for email comparison.
		   WHERE ru."RegId" = regid and ru.is_active = 'true';
   FOR key, value IN SELECT * FROM jsonb_each(input_json)
   LOOP 
      -- Iterate through all key-value pairs in the JSONB object	  
      IF key = 'department' THEN
         -- Iterate through the "department" array elements
		 DELETE FROM users.userdepartment WHERE "RegId"=regid;
         FOR department_value IN SELECT jsonb_array_elements(value)::int
         LOOP
		    --IF department_value is not null and department_value <> '' THEN
			IF department_value is not null AND department_value > 0 THEN
		      INSERT INTO users.userdepartment("RegId","DeptID",is_active,created_date,created_by)
		      VALUES(regid,department_value,true,current_timestamp,'Admin');
			END IF;
         RAISE INFO 'department: %', department_value;
         END LOOP;
      END IF;
	  

	 IF key = 'workspace' THEN
    DELETE FROM users.user_work_space WHERE reg_id = regid;
    -- Get the next available user_work_space_id manually
    SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_work_space_id
    FROM users.user_work_space;
    FOR work_space_value IN SELECT jsonb_array_elements(value)::int
    LOOP
        IF work_space_value IS NOT NULL AND work_space_value > 0 THEN
            INSERT INTO users.user_work_space(user_work_space_id, reg_id, work_space_id, is_active, created_date, created_by)
            VALUES (max_user_work_space_id, regid, work_space_value, true, current_timestamp, 'Admin');
            -- Increment for each new workspace to avoid conflicts
            SELECT COALESCE(MAX(user_work_space_id), 0) + 1 INTO max_user_work_space_id
            FROM users.user_work_space;
        END IF;
        RAISE INFO 'workspace: %', work_space_value;
    END LOOP;
END IF;

	  IF key ='shift' THEN	
	    IF cast(replace(input_json ->>'shift','"','') as int) is not null THEN
	      UPDATE users.userprofile SET "ShiftId" = cast(replace(input_json ->>'shift','"','') as int)
		  ,last_updated_date=current_timestamp
	      WHERE "EmailID" = email;
		END IF;
		--RAISE INFO 'shift type :',shift;
	  END IF;
	  
	IF key ='country' then
		DELETE FROM users.usercountryregion WHERE "RegId"=regid;
		FOR countryid IN SELECT jsonb_array_elements(value)::int
		LOOP
		  IF countryid is not null AND countryid > 0 THEN
		    INSERT INTO users.usercountryregion("RegId","CountryID",is_active,created_date,created_by)
		    VALUES(regid,countryid,true,current_timestamp,'Admin');
		  END IF;
	      RAISE INFO 'country id %',countryid;
	    END LOOP;
	END IF;
	
  IF key ='tool' then
	    DELETE FROM users.usertool WHERE "RegId"=regid;
		FOR toolid IN SELECT jsonb_array_elements(value)::int
		LOOP
		  IF toolid is not null AND toolid > 0 THEN
		    INSERT INTO users.usertool("RegId","ToolID",is_active,created_date,created_by)
		    VALUES(regid,toolid,true,current_timestamp,'Admin');
		  END IF;
	      RAISE INFO 'tool id %',toolid;
	    END LOOP;
	END IF;
    IF key ='language' then
		DELETE from users.userlanguage where "RegId"=regid;
		FOR languageid IN SELECT jsonb_array_elements(value)::int
		LOOP
		 IF languageid is not null AND languageid > 0 THEN
	       INSERT INTO users.userlanguage("RegId","LanguageID",is_active,created_date,created_by)
		   VALUES(regid,languageid,true,current_timestamp,'Admin');
	       RAISE INFO 'language ids %',languageid;
		 END IF;
	    END LOOP;
	END IF;
	
	IF key ='role' then
	  DELETE from users.userrole where "RegId"=regid;
	  FOR roleid IN SELECT jsonb_array_elements(value)::int
	  LOOP
	    IF roleid is not null  AND roleid > 0 THEN
	      INSERT INTO users.userrole("RegId","RoleID",is_active,created_date,created_by)
		  VALUES(regid,roleid,true,current_timestamp,'Admin');
		END IF;
	    RAISE INFO 'role ids %',roleid;
	  END LOOP;
	 END IF;
	 
 END LOOP;
  -- Update is_active status
   IF in_is_active IS NOT NULL THEN
      UPDATE users.registereduser 
      SET "is_active" = in_is_active,
          last_updated_date = current_timestamp,
          "updated_by" = cast(replace(input_json ->>'updated_by','"','') as uuid)
      WHERE "RegId" = regid;
   END IF;

   GET DIAGNOSTICS offected = ROW_COUNT;   
   RAISE INFO 'affected rows: %', offected;
  IF(offected>0)
      THEN
		  return query select 'User Updated Successfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'User Updated Failed' as message,'false'::boolean as status;
	 END IF;
END;
$$;


--
-- Name: save_update_user_profile_existing(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.save_update_user_profile_existing(input_json jsonb) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $$
   declare offected integer;
   email text;
   key text;
   value jsonb;
   regid uuid;
   department_value int;
   countryid int; 
   toolid int;
   languageid int;
   roleid int;
   in_is_active boolean;
   
   BEGIN 
   -- updatedby   || updateddate   || purpose
   -- Naveen S    || 23-04-2024    || Update is_active status
   
   regid :=cast(replace(input_json ->>'regid','"','') as uuid);
    in_is_active :=cast(replace(input_json ->>'is_active','"','') as boolean);
   RAISE INFO 'reg id high %',regid;
   SELECT "EmailID" INTO email from users.userprofile u
           JOIN users.registereduser ru 
		   ON LOWER(TRIM(u."EmailID")) = LOWER(TRIM(ru."Email")) AND u.is_active = 'true' -- Added lower case for email comparison.
		   WHERE ru."RegId" = regid and ru.is_active = 'true';
   FOR key, value IN SELECT * FROM jsonb_each(input_json)
   LOOP 
      -- Iterate through all key-value pairs in the JSONB object	  
      IF key = 'department' THEN
         -- Iterate through the "department" array elements
		 DELETE FROM users.userdepartment WHERE "RegId"=regid;
         FOR department_value IN SELECT jsonb_array_elements(value)::int
         LOOP
		    --IF department_value is not null and department_value <> '' THEN
			IF department_value is not null AND department_value > 0 THEN
		      INSERT INTO users.userdepartment("RegId","DeptID",is_active,created_date,created_by)
		      VALUES(regid,department_value,true,current_timestamp,'Admin');
			END IF;
         RAISE INFO 'department: %', department_value;
         END LOOP;
      END IF;
	  IF key ='shift' THEN	
	    IF cast(replace(input_json ->>'shift','"','') as int) is not null THEN
	      UPDATE users.userprofile SET "ShiftId" = cast(replace(input_json ->>'shift','"','') as int)
		  ,last_updated_date=current_timestamp
	      WHERE "EmailID" = email;
		END IF;
		--RAISE INFO 'shift type :',shift;
	  END IF;
	  
	IF key ='country' then
		DELETE FROM users.usercountryregion WHERE "RegId"=regid;
		FOR countryid IN SELECT jsonb_array_elements(value)::int
		LOOP
		  IF countryid is not null AND countryid > 0 THEN
		    INSERT INTO users.usercountryregion("RegId","CountryID",is_active,created_date,created_by)
		    VALUES(regid,countryid,true,current_timestamp,'Admin');
		  END IF;
	      RAISE INFO 'country id %',countryid;
	    END LOOP;
	END IF;
	
  IF key ='tool' then
	    DELETE FROM users.usertool WHERE "RegId"=regid;
		FOR toolid IN SELECT jsonb_array_elements(value)::int
		LOOP
		  IF toolid is not null AND toolid > 0 THEN
		    INSERT INTO users.usertool("RegId","ToolID",is_active,created_date,created_by)
		    VALUES(regid,toolid,true,current_timestamp,'Admin');
		  END IF;
	      RAISE INFO 'tool id %',toolid;
	    END LOOP;
	END IF;
    IF key ='language' then
		DELETE from users.userlanguage where "RegId"=regid;
		FOR languageid IN SELECT jsonb_array_elements(value)::int
		LOOP
		 IF languageid is not null AND languageid > 0 THEN
	       INSERT INTO users.userlanguage("RegId","LanguageID",is_active,created_date,created_by)
		   VALUES(regid,languageid,true,current_timestamp,'Admin');
	       RAISE INFO 'language ids %',languageid;
		 END IF;
	    END LOOP;
	END IF;
	
	IF key ='role' then
	  DELETE from users.userrole where "RegId"=regid;
	  FOR roleid IN SELECT jsonb_array_elements(value)::int
	  LOOP
	    IF roleid is not null  AND roleid > 0 THEN
	      INSERT INTO users.userrole("RegId","RoleID",is_active,created_date,created_by)
		  VALUES(regid,roleid,true,current_timestamp,'Admin');
		END IF;
	    RAISE INFO 'role ids %',roleid;
	  END LOOP;
	 END IF;
	 
 END LOOP;
  -- Update is_active status
   IF in_is_active IS NOT NULL THEN
      UPDATE users.registereduser 
      SET "is_active" = in_is_active,
          last_updated_date = current_timestamp,
          "updated_by" = cast(replace(input_json ->>'updated_by','"','') as uuid)
      WHERE "RegId" = regid;
   END IF;

   GET DIAGNOSTICS offected = ROW_COUNT;   
   RAISE INFO 'affected rows: %', offected;
  IF(offected>0)
      THEN
		  return query select 'User Updated Successfully' as message,'true'::boolean as status;
     ELSE 
		  return query select 'User Updated Failed' as message,'false'::boolean as status;
	 END IF;
END;
$$;


--
-- Name: update_tool(jsonb); Type: FUNCTION; Schema: users; Owner: -
--

CREATE FUNCTION users.update_tool(tool_data jsonb) RETURNS TABLE(message text, status boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    offected integer;
    tool_item jsonb;
	inserted_version_id int;
	toolid int;   
	toolname text;
	toolcode text;
    platform_ids INT[];
    country_ids INT[];
    subscription_plan_ids INT[];
    tool_category INT;
    tool_status INT;
    primary_owner UUID;
    secondary_owner UUID;
    versionname text;
    descriptions text;
    key_highlights text;
	is_dependency_requireds boolean;
	is_updateteam_dependencies boolean;
	is_analyse_dependencies boolean;
	is_tsr_dependencies boolean;
BEGIN
/*
Sample input Json format
	'{
           "toolid":1,
           "toolname": "Sample",
		   "toolcode":"SGP"
           "platform": [1, 2],
           "country": [1,2,3],
           "subscription_plan": [1,3],
           "tool_category": 2,
           "status": 2,
           "primary_owner": "dae41c8c-d406-447f-8e14-7c0e4bdcf9f5",
           "secondary_owner": "b5595ae1-745b-43c0-bd9c-ec2af69e8d7b",
           "version": "1.0.1",
           "description": "sampletest",
           "key_highlights": "sampletestkeyhighlights"
     }'
*/
--Get the data from JSON
    toolid := (tool_data->>'toolid')::INT;
    toolname := tool_data->>'toolname';
	toolcode := tool_data->>'toolcode';
    platform_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'platform')::INT);
    country_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'country')::INT);
    subscription_plan_ids := ARRAY(SELECT jsonb_array_elements_text(tool_data->'subscription_plan')::INT);
    tool_category := (tool_data->>'tool_category')::INT;
    tool_status := (tool_data->>'status')::INT;
    IF (tool_data->>'primary_owner') <> '' AND LENGTH(tool_data->>'primary_owner') = 36 AND (tool_data->>'primary_owner') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'  THEN primary_owner := (tool_data->>'primary_owner')::UUID; END IF;
    IF (tool_data->>'secondary_owner') <> '' AND LENGTH(tool_data->>'secondary_owner') = 36 AND (tool_data->>'secondary_owner') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN secondary_owner := (tool_data->>'secondary_owner')::UUID; END IF;
    versionname := tool_data->>'version';
    descriptions := tool_data->>'description';
    key_highlights := tool_data->>'key_highlights';
	is_dependency_requireds := tool_data->>'is_dependency_required';
	is_updateteam_dependencies := tool_data->>'is_updateteam_dependency';
	is_analyse_dependencies := tool_data->>'is_analyse_dependency';
	is_tsr_dependencies := tool_data->>'is_tsr_dependency';
		
	
	 IF toolid IS NOT NULL AND toolid <>0  THEN
	 
	 -- Insert  Primary user in UserTool table
	 IF primary_owner IS NOT NULL AND primary_owner <> '00000000-0000-0000-0000-000000000000'  THEN
		  IF NOT EXISTS(SELECT 1 FROM users.usertool WHERE "RegId" = primary_owner AND "ToolID" = toolid AND is_active ='true') THEN
		  -- Delete details  usertool Table
		    DELETE FROM users.usertool
			USING master.tool
			WHERE users.usertool."ToolID" = master.tool."ToolID"
  			AND master.tool.primary_user_id = users.usertool."RegId"
  			AND master.tool."ToolID" = toolid
  			AND master.tool.is_active = 'true';
			 
		     INSERT INTO users.usertool("RegId", "ToolID", is_active,created_date,created_by)
             SELECT primary_owner,toolid, 'true',current_timestamp,'Admin';
		  END IF;
		END IF;
		
		
		-- Insert Secondary user  in UserTool table 
		IF secondary_owner IS NOT NULL AND secondary_owner <> '00000000-0000-0000-0000-000000000000'  THEN			 
		  IF NOT EXISTS(SELECT 1 FROM users.usertool WHERE "RegId" = secondary_owner AND "ToolID" = toolid AND is_active ='true') THEN
		  	 -- Delete details  usertool Table
		    DELETE FROM users.usertool
			USING master.tool
			WHERE users.usertool."ToolID" = master.tool."ToolID"
  			AND master.tool.secondary_user_id = users.usertool."RegId"
  			AND master.tool."ToolID" = toolid
  			AND master.tool.is_active = 'true';
			 
		     INSERT INTO users.usertool("RegId", "ToolID", is_active,created_date,created_by)
             SELECT secondary_owner,toolid, 'true',current_timestamp,'Admin';
		  END IF;
		END IF;
		
	--Update data into tool table 
	IF EXISTS(SELECT 1 FROM master.tool WHERE "ToolID" = toolid AND is_active = 'true') THEN
	IF NOT EXISTS(SELECT 1 FROM master.tool WHERE TRIM(LOWER("ToolName"))=TRIM(LOWER(toolname)) AND "ToolID" <> Toolid) THEN
			UPDATE master.tool SET
			"ToolName" = toolname,
			"ToolCode" = toolcode,
			description = descriptions,
			keyhighlight = key_highlights,
			primary_user_id = CASE WHEN primary_owner = '00000000-0000-0000-0000-000000000000' THEN NULL WHEN primary_owner IS NULL THEN NULL ELSE primary_owner END,
	        secondary_user_id = CASE WHEN secondary_owner = '00000000-0000-0000-0000-000000000000' THEN NULL WHEN secondary_owner IS NULL THEN NULL ELSE secondary_owner END,
			status_id = tool_status,
			tool_category_id = tool_category,
			last_updated_date = current_timestamp,
			updated_by = 'Admin',
			is_dependency_required = is_dependency_requireds,
			is_updateteam_dependency = is_updateteam_dependencies,
			is_analyse_dependency = is_analyse_dependencies,
			is_tsr_dependency = is_tsr_dependencies
	        WHERE "ToolID" = toolid and is_active = 'true';
			
       -- Insert into version table
		IF versionname IS NOT NULL AND LENGTH(versionname) > 0 THEN
		   IF NOT EXISTS(SELECT 1 FROM master.toolversion WHERE TRIM(LOWER("version_name"))= TRIM(LOWER(versionname)) AND tool_id = toolid AND is_active ='true') THEN
		      INSERT INTO master.toolversion (tool_id,version_name,is_active,created_date,created_by)
		      VALUES(toolid,versionname,'true',current_timestamp,'Admin')
		      RETURNING "tool_version_id"
		      INTO inserted_version_id;
		   END IF;
		END IF;
		
		-- Update the version id in tool table
		IF inserted_version_id IS NOT NULL AND inserted_version_id <> 0 THEN
		   UPDATE master.tool SET tool_version_id = inserted_version_id
		   WHERE "ToolID" = toolid;
		END IF;
			
		-- Delete and Insert data into the tool platform table if it matches the platform table.
		RAISE info 'tool platform entered';

		IF platform_ids IS NOT NULL AND array_length(platform_ids, 1) > 0 THEN
		   DELETE FROM users.toolplatform WHERE tool_id = toolid;
		   
           INSERT INTO users.toolplatform(tool_id, platform_id, is_active,created_date,created_by)
           SELECT toolid, CAST(plat AS INTEGER), 'true',current_timestamp,'Admin'
           FROM UNNEST(platform_ids) AS plat
		   JOIN master.platform p on p.platform_id = CAST(plat AS INTEGER) and p.is_active =true;
        END IF;
		
		-- Delete and Insert data into the toolcountryregion table if it matches the country table.
		RAISE info 'tool country region entered';	
        IF country_ids IS NOT NULL AND array_length(country_ids, 1) > 0 THEN
		     DELETE FROM users.toolcountryregion WHERE tool_id = toolid;
			 
             INSERT INTO users.toolcountryregion(tool_id, country_id, is_active,created_date,created_by)
        	 SELECT toolid, CAST(countryid AS INTEGER), 'true',current_timestamp,'Admin'
        	 FROM UNNEST(country_ids) AS countryid
			 JOIN master.country c on c."CountryID" = CAST(countryid AS INTEGER) AND c.is_active=true;
		END IF;	
		
		-- Delete and Insert data into the toolsubscription table if it matches the subscriptiontype table.
		RAISE info 'tool Subscription entered';	
        IF subscription_plan_ids IS NOT NULL AND array_length(subscription_plan_ids, 1) > 0 THEN
		
		    DELETE FROM users.toolsubscription WHERE tool_id = toolid;
		
        	INSERT INTO users.toolsubscription(tool_id, subscription_type_id, is_active,created_date,created_by)
        	SELECT toolid, CAST(subscriptionid AS INTEGER), 'true',current_timestamp,'Admin'
        	FROM UNNEST(subscription_plan_ids) AS subscriptionid
			JOIN master.subscriptiontype c on c."id" = CAST(subscriptionid AS INTEGER) AND c.is_active = true;	 
		END IF;	
		get diagnostics offected = ROW_COUNT;   
	IF(offected>0)
    THEN
		  return query select 'Tool Updated successfully' as message,'true'::boolean as status;
    ELSE 
	      return query select 'Tool Updated failed' as message,'false'::boolean as status;
    END IF;
	ELSE 
	 return query select 'Tool name already exists' as message,'false'::boolean as status;		
	END IF;
	ELSE
	return query select 'Tool not found' as message,'false'::boolean as status;		
END IF;	
ELSE
	return query select 'Tool id is Mandatory' as message,'false'::boolean as status;	
END IF;
	-- Handle the exception
EXCEPTION
    WHEN others THEN
     
        ROLLBACK;
        message := 'Error inserting data';
        status := false; 
END;
$_$;


--
-- Name: upsert_user_app_permission(uuid, integer, integer, uuid, integer, character varying, character varying); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.upsert_user_app_permission(IN p_user_id uuid DEFAULT NULL::uuid, IN p_app_id integer DEFAULT NULL::integer, IN p_permission integer DEFAULT 1, IN p_added_by uuid DEFAULT NULL::uuid, INOUT new_user_app_permission_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_existing_id integer;
	v_app_valid boolean := false;
	v_context text;
BEGIN
	IF p_user_id IS NULL OR p_app_id IS NULL OR p_app_id <= 0 THEN
		status := 'false';
		message := 'userId and appId are required.';
		RETURN;
	END IF;

	IF p_permission IS NULL OR p_permission NOT IN (0, 1) THEN
		status := 'false';
		message := 'permission must be 0 (false) or 1 (true).';
		RETURN;
	END IF;

	SELECT EXISTS (
		SELECT 1
		FROM master.app_master am
		WHERE am.app_id = p_app_id
		  AND am.is_active = true
	) INTO v_app_valid;

	IF NOT v_app_valid THEN
		status := 'false';
		message := 'Invalid appId. App must exist in master.app_master.';
		RETURN;
	END IF;

	-- permission = 1 → grant
	IF p_permission = 1 THEN
		SELECT user_app_permission_id
		INTO v_existing_id
		FROM users.user_app_permission
		WHERE reg_id = p_user_id
		  AND app_id = p_app_id
		  AND is_active = true
		LIMIT 1;

		IF v_existing_id IS NOT NULL THEN
			new_user_app_permission_id := v_existing_id;
			status := 'true';
			message := 'App permission already exists.';
			RETURN;
		END IF;

		SELECT user_app_permission_id
		INTO v_existing_id
		FROM users.user_app_permission
		WHERE reg_id = p_user_id
		  AND app_id = p_app_id
		  AND is_active = false
		ORDER BY user_app_permission_id DESC
		LIMIT 1;

		IF v_existing_id IS NOT NULL THEN
			UPDATE users.user_app_permission
			SET
				is_active = true,
				updated_by = p_added_by::text,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE user_app_permission_id = v_existing_id;

			new_user_app_permission_id := v_existing_id;
			status := 'true';
			message := 'App permission granted successfully.';
			RETURN;
		END IF;

		INSERT INTO users.user_app_permission (
			reg_id,
			app_id,
			is_active,
			created_date,
			created_by
		) VALUES (
			p_user_id,
			p_app_id,
			true,
			current_timestamp AT TIME ZONE 'UTC',
			p_added_by::text
		)
		RETURNING user_app_permission_id INTO new_user_app_permission_id;

		status := 'true';
		message := 'App permission granted successfully.';
		RETURN;
	END IF;

	-- permission = 0 → revoke
	SELECT user_app_permission_id
	INTO v_existing_id
	FROM users.user_app_permission
	WHERE reg_id = p_user_id
	  AND app_id = p_app_id
	  AND is_active = true
	LIMIT 1;

	IF v_existing_id IS NULL THEN
		new_user_app_permission_id := 0;
		status := 'true';
		message := 'App permission already removed.';
		RETURN;
	END IF;

	UPDATE users.user_app_permission
	SET
		is_active = false,
		updated_by = p_added_by::text,
		last_updated_date = current_timestamp AT TIME ZONE 'UTC'
	WHERE user_app_permission_id = v_existing_id;

	new_user_app_permission_id := v_existing_id;
	status := 'true';
	message := 'App permission removed successfully.';

EXCEPTION
	WHEN OTHERS THEN
		GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
		CALL master.procedure_log_exception(
			'users.upsert_user_app_permission',
			CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
			NULL,
			current_timestamp AT TIME ZONE 'UTC',
			row_to_json(ROW(p_user_id, p_app_id, p_permission, p_added_by))::TEXT
		);
		status := 'false';
		message := SQLERRM;
END;
$$;


--
-- Name: upsert_user_board_permission(integer, uuid, integer, integer, integer, uuid, integer, character varying, character varying); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.upsert_user_board_permission(IN p_user_board_permission_id integer DEFAULT 0, IN p_user_id uuid DEFAULT NULL::uuid, IN p_workspace_id integer DEFAULT NULL::integer, IN p_board_id integer DEFAULT NULL::integer, IN p_role_id integer DEFAULT NULL::integer, IN p_added_by uuid DEFAULT NULL::uuid, INOUT new_user_board_permission_id integer DEFAULT NULL::integer, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_max_user_board_permission_id integer := 0;
	v_existing_id integer;
    v_context text;
BEGIN

	--Created By      Date  		Purpose 
	--Aravindhan    13/08/2025		add board permission
	--Mubarak       21/09/2026		removed is_admin; match on user+workspace+board
	
 	IF p_user_board_permission_id = 0 THEN
		SELECT user_board_permission_id
		INTO v_existing_id
		FROM users.user_board_permission
		WHERE reg_id = p_user_id
		  AND workspace_id = p_workspace_id
		  AND board_id = p_board_id
		  AND is_active = true
		LIMIT 1;

		IF v_existing_id IS NOT NULL THEN
			UPDATE users.user_board_permission
			SET
				role_id = p_role_id,
				updated_by = p_added_by,
				last_updated_date = current_timestamp AT TIME ZONE 'UTC'
			WHERE user_board_permission_id = v_existing_id;

			new_user_board_permission_id := v_existing_id;
			status := 'true';
			message := 'Board permission updated successfully.';
			RETURN;
		END IF;

		SELECT COALESCE(MAX(user_board_permission_id), 0) + 1 INTO v_max_user_board_permission_id
		FROM users.user_board_permission;

		INSERT INTO users.user_board_permission (
			user_board_permission_id,
			reg_id,
			workspace_id,
			board_id,
			role_id,
			is_active,
			created_date,
			created_by
		) VALUES (
			v_max_user_board_permission_id,
			p_user_id,
			p_workspace_id,
			p_board_id,
			p_role_id,
			true,
			current_timestamp AT TIME ZONE 'UTC',
			p_added_by
		)
		RETURNING user_board_permission_id INTO new_user_board_permission_id;

		status := 'true';
		message := 'Board permission added successfully.';
	ELSIF p_user_board_permission_id > 0 THEN
		UPDATE users.user_board_permission
        SET
            is_active = false,
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE user_board_permission_id = p_user_board_permission_id;

        new_user_board_permission_id := p_user_board_permission_id;
        status := 'true';
        message := 'Board permission deleted successfully.';
	ELSE
		new_user_board_permission_id := p_user_board_permission_id;
		status := 'true';
		message := 'No data updated.';
	END IF;	

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'users.add_user_board_permission',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_user_board_permission_id,
                p_user_id,
                p_workspace_id,
                p_board_id,
                p_role_id,
                p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


--
-- Name: upsert_user_type(uuid, integer, integer, uuid, character varying, character varying); Type: PROCEDURE; Schema: users; Owner: -
--

CREATE PROCEDURE users.upsert_user_type(IN p_user_id uuid DEFAULT NULL::uuid, IN p_user_type_id integer DEFAULT NULL::integer, IN p_previous_user_type_id integer DEFAULT NULL::integer, IN p_added_by uuid DEFAULT NULL::uuid, INOUT message character varying DEFAULT NULL::character varying, INOUT status character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_inactive_status_id INTEGER;
	v_user_status_id INTEGER;
	v_admin_status_id INTEGER;
	v_superadmin_status_id INTEGER;
	v_context TEXT;
BEGIN

	--Created By      Date  		Purpose 
	--Aravindhan    13/08/2025		Move to user type 

	SELECT
		MAX(CASE WHEN name = 'InActive User' THEN status_id END) AS v_inactive_status_id,
		MAX(CASE WHEN name = 'User' THEN status_id END) AS v_user_status_id,
		MAX(CASE WHEN name = 'Admin' THEN status_id END) AS v_admin_status_id,
		MAX(CASE WHEN name = 'Super Admin' THEN status_id END) AS v_superadmin_status_id
	INTO
		v_inactive_status_id,
		v_user_status_id,
		v_admin_status_id,
		v_superadmin_status_id
	FROM master.status_code_master
	WHERE is_active = true 
	  AND type = 'USERROLE'
	  AND name IN ('InActive User', 'User', 'Admin', 'Super Admin');
	
	IF p_user_type_id = v_inactive_status_id THEN
	
		UPDATE users.userprofile
		SET
			user_type_id = p_user_type_id,
			previous_user_type_id = p_previous_user_type_id,
			updated_by = p_added_by,
			is_active = false,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE user_id = p_user_id;
		
		UPDATE users.registereduser
		SET
			updated_by = p_added_by,
			is_active = false,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE "RegId" = p_user_id;

		UPDATE users.user_board_permission
		SET
			is_active = false,
			updated_by = p_added_by,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE reg_id = p_user_id
		  AND is_active = true;
		
			
		status  := 'true';
		message := 'User type updated to Inactive successfully.';
	
	ELSIF p_user_type_id = v_admin_status_id THEN
		raise info 'test %:', v_user_status_id;
		UPDATE users.userprofile
		SET
			user_type_id = p_user_type_id,
			previous_user_type_id = NULL,
			updated_by = p_added_by,
			is_active = true,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE user_id = p_user_id;
		
		UPDATE users.registereduser
		SET
			updated_by = p_added_by,
			is_active = true,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE "RegId" = p_user_id;
		
		UPDATE users.user_board_permission
        SET
            is_active = false,
            updated_by = p_added_by,
            last_updated_date = current_timestamp AT TIME ZONE 'UTC'
        WHERE reg_id = p_user_id and is_active = true;
		
		status  := 'true';
		message := 'User type updated to Admin successfully.';
	
	ELSIF p_user_type_id = v_user_status_id THEN
	
		
		UPDATE users.userprofile
		SET
			user_type_id = p_user_type_id,
			previous_user_type_id = NULL,
			updated_by = p_added_by,
			is_active = true,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE user_id = p_user_id;
		
		UPDATE users.registereduser
		SET
			updated_by = p_added_by,
			is_active = true,
			last_updated_date = current_timestamp AT TIME ZONE 'UTC'
		WHERE "RegId" = p_user_id;
		
		status  := 'true';
		message := 'User type updated to Workspace User successfully.';
	
	ELSE
		status  := 'true';
		message := 'User type update did not match any known role.';	
	END IF;
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_context = PG_EXCEPTION_CONTEXT;
        CALL master.procedure_log_exception(
            'users.upsert_user_type',
            CONCAT('Error: ', SQLERRM, ' | Context: ', v_context),
            NULL,
            current_timestamp AT TIME ZONE 'UTC',
            row_to_json(ROW(
                p_user_id,
                p_user_type_id,
                p_previous_user_type_id,
                p_added_by
            ))::TEXT
        );
        status := 'false';
        message := SQLERRM;
END;
$$;


