--
-- Name: mv_workspace_roles; Type: MATERIALIZED VIEW; Schema: users; Owner: -
--

CREATE MATERIALIZED VIEW users.mv_workspace_roles AS
 SELECT ws.work_space_id,
    ws.name AS workspace_name,
    jsonb_agg(jsonb_build_object('name', rd."Name", 'roleid', rd."RoleID", 'departments', rd.departments)) AS roles
   FROM (master.work_space_master ws
     LEFT JOIN ( SELECT r.role_id AS "RoleID",
            r.name AS "Name",
            wsd.work_space_id,
            jsonb_agg(jsonb_build_object('deptname', dd."Name", 'depid', dd."DeptID", 'depcode', dd."DeptCode", 'permissionData', dd.permissiondata)) AS departments
           FROM (((master.role r
             JOIN master.rolesetting rs ON ((r.role_id = rs."RoleId")))
             JOIN master.work_space_department wsd ON ((rs.dept_id = wsd.dept_id)))
             JOIN ( SELECT d."DeptID",
                    d."Name",
                    d."DeptCode",
                    jsonb_agg(jsonb_build_object('permission', pd."Permission", 'details', pd.details)) AS permissiondata
                   FROM (master.department d
                     LEFT JOIN ( SELECT dp.dept_id,
                            dp."Permission",
                            jsonb_agg(jsonb_build_object('type', dp."Type", 'data', dp.data)) AS details
                           FROM ( SELECT rs_1.dept_id,
                                    rs_1."Permission",
                                    rs_1."Type",
                                    jsonb_agg(jsonb_build_object('name', rs_1."Permission", 'id', rs_1."Id", 'ischecked', rs_1."Ischecked")) AS data
                                   FROM master.rolesetting rs_1
                                  GROUP BY rs_1.dept_id, rs_1."Permission", rs_1."Type") dp
                          GROUP BY dp.dept_id, dp."Permission") pd ON ((pd.dept_id = d."DeptID")))
                  GROUP BY d."DeptID", d."Name", d."DeptCode") dd ON ((dd."DeptID" = rs.dept_id)))
          GROUP BY r.role_id, r.name, wsd.work_space_id) rd ON ((rd.work_space_id = ws.work_space_id)))
  GROUP BY ws.work_space_id, ws.name
  WITH NO DATA;


